insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'PSA', $b$Nau Mprơ Ơm$b$, $b$["Ndrom Sămƀŭt Du Rơh", "NAU MPRƠ ƠM"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PSA',1,1,null,$b$Ueh maak ngăn ma mbu nâm mâu tĭng ôh tâm nau phung tih, mâu lĕ dâk hăn tĭng nau phung mhĭk, mâu lĕ gŭ ngau ndrel ma phung mưch.$b$,true),
('bunong-vn','PSA',1,2,null,$b$Ƀiă lah păng maak uănh tâm Nau Vay Kôranh Brah, păng răk Nau Vay nây măng nâm nar.$b$,true),
('bunong-vn','PSA',1,3,null,$b$Păng jêng nâm bu du n'gâng tơm si tăm dăch n'hor dak, păng play tơ lah tât khay yăn play, n'ha păng mâu blau kro ôh, jêh ri lĕ nau păng ƀư dơi jêng da dê.$b$,true),
('bunong-vn','PSA',1,4,null,$b$Phung tih mâu dơi jêng tâm ban pô nây ôh, Khân păng jêng nâm bu lâk sial đô̆.$b$,true),
('bunong-vn','PSA',1,5,null,$b$Brah Ndu mra phat dôih phung tih, tâm nkhah lơi khân păng đah phung sŏng$b$,true),
('bunong-vn','PSA',1,6,null,$b$Kôranh Brah mra chiă uănh phung sŏng, ƀiă lah phung tih mra hăn tâm nau rai yot.$b$,false),
('bunong-vn','PSA',2,1,null,$b$Mâm ƀư geh nau uh ah ndrăng ndŭl mpôl. Jêh ri phung bunuyh mĭn ma nau mâu khlay?$b$,true),
('bunong-vn','PSA',2,2,null,$b$Mâm ƀư hađăch neh ntu dâk, jêh ri phung kôranh tâm nchră. Ŭch tâm rdâng đah Yêhôva jêh ri đah nơm păng troch jêh dak ngi?$b$,true),
('bunong-vn','PSA',2,3,null,$b$Khân păng lah, ăn he rtăch lơi rse păng kât, jêh ri mƀăr lơi rse rvăk khân păng ăn ngai đah he.$b$,true),
('bunong-vn','PSA',2,4,null,$b$Nơm gŭ tâm trôk mra gơm ma khân păng: Kôranh Brah mra mưch ma khân păng.$b$,true),
('bunong-vn','PSA',2,5,null,$b$Dôl nây Păng mra ngơi ma khân păng ma nau păng nuih, jêh ri rsuak khân păng ma nau nuih ktang;$b$,true),
('bunong-vn','PSA',2,6,null,$b$Gâp rdâk jêh hađăch gâp ta klơ yôk Siôn yôk kloh ueh.$b$,false),
('bunong-vn','PSA',2,7,null,$b$Gâp mra mbơh nau ntăm: Yêhôva lah jêh ma gâp pô aơ: May jêng kon bu klâu gâp; nar aơ gâp deh ma may.$b$,true),
('bunong-vn','PSA',2,8,null,$b$Dăn hom tă bơh gâp, jêh ri gâp mra ăn phung ndŭl mpôl jêng drăp may krâm. Ntŭk dŭt bri dŭt neh jêng ndơ may.$b$,true),
('bunong-vn','PSA',2,9,null,$b$May mra nchah lơi khân păng ma mâng loih; may mra nchah lơi khân păng nâm bu glah bu mon$b$,true),
('bunong-vn','PSA',2,10,null,$b$Pô nây yơh, Ơ phung hađăch, ăn khân may geh nau blau mĭn. Ơ phung kôranh phat dôih neh ntu dơn hom nau nti lah.$b$,false),
('bunong-vn','PSA',2,11,null,$b$Pah kan ma Yêhôva ma nau klach mbah yơk. Jêh ri maak hom khân may tât sâr săk jăn$b$,true),
('bunong-vn','PSA',2,12,null,$b$Chum kon klach păng nuih, jêh ri khân may mra rai yot tâm trong, yor lah nau Păng ji nuih mra gơnh hao nuih. Ueh maak yơh lĕ rngôch phung rnơm ma Păng.$b$,false),
('bunong-vn','PSA',3,1,null,$b$Ơ Yêhôva, phung rlăng đah gâp jêng âk ngăn. Phung dâk tâm lơh đah gâp jêng âk lơn đŏng.$b$,true),
('bunong-vn','PSA',3,2,null,$b$Âk nơm lah ma huêng gâp, mâu geh ôh nau tâm rklaih păng tâm Brah Ndu (Sêla)$b$,true),
('bunong-vn','PSA',3,3,null,$b$Lah May, Ơ Yêhôva, jêng khêl gâp May jêng nau chrêk rmah gâp jêh ri Nơm ăn gâp ngơ̆ bôk$b$,false),
('bunong-vn','PSA',3,4,null,$b$Bâr gâp nter vơl ma Yêhôva Păng lŏ plơ̆ lah ma gâp tă bơh yôk kloh ueh Păng (Sêla)$b$,false),
('bunong-vn','PSA',3,5,null,$b$Gâp lâng săk jêh ri bêch; Gâp kah rngăl yor lah Yêhôva chiă uănh gâp$b$,false),
('bunong-vn','PSA',3,6,null,$b$Gâp mâu klach ôh ma âk rbăn bunuyh nchueng jŭm gâp$b$,false),
('bunong-vn','PSA',3,7,null,$b$Dâk hom May, ơ Yêhôva tâm rklaih gâp, Ơ Brah Ndu gâp Yor lah May dong jêh ta trô bom lĕ rngôch phung rlăng gâp; May ƀư pêch jêh sêk phung ƀai.$b$,false),
('bunong-vn','PSA',3,8,null,$b$Nau tâm rklaih jêng Yêhôva de; Ăn phung ƀon lan May geh nau ueh lăng May.$b$,true),
('bunong-vn','PSA',4,1,null,$b$Ơ Brah Ndu ma nau sŏng srăng gâp, lŏ plơ̆ lah ma gâp tơ lah gâp kuăl; May hŏ rklaih jêh gâp tă bơh nau rêh ni; Yô̆ nđach an ma gâp ƀă, jêh ri gŭ iăt nau gâp mbơh sơm,$b$,true),
('bunong-vn','PSA',4,2,null,$b$Ơ phung kon bunuyh, dŭm jŏ khân may mra nuih ma nau chrêk rmah gâp? Dŭm jŏ khân may mra rŏng nau mâu khlay, jêh ri joi nau mƀruh? (Sêla)$b$,false),
('bunong-vn','PSA',4,3,null,$b$Ăn khân may gĭt Yêhôva prăp jêh ma Păng Nơm, bunuyh blau yơk ma Păng. Yêhôva gŭ iăt tơ lah gâp kuăl mbơh sơm$b$,false),
('bunong-vn','PSA',4,4,null,$b$Gŭ tâm nau klach yơk mbah, jêh ri lơi hôm ƀư tih ôh. Gŭ mĭn tâm nuih n'hâm may dôl gŭ bêch, jêh ri gŭ rklăk (Sêla)$b$,false),
('bunong-vn','PSA',4,5,null,$b$Nhhơr nau sŏng srăng jêng ndơ ƀư brah, Jêh ri nsing rnơm ma Brah Yêhôva$b$,false),
('bunong-vn','PSA',4,6,null,$b$Âk bunuyh lah: “Mbu nâm mra ăn ma he saơ nau ueh maak?” Yêhôva, ăn nau ang tă bơh muh măt May sol ta hên.$b$,false),
('bunong-vn','PSA',4,7,null,$b$May dơm tâm nuih n'hâm gâp nau maak. Rmeh lơn ma khân păng geh, tơ lah ba, jêh ri play kriăk ƀâu mhe hao âk.$b$,true),
('bunong-vn','PSA',4,8,null,$b$Ơ Yêhôva mra lâng săk jêh ri bêch ma nau đăp mpăn Yor lah knŏng May yơh ăn gâp gŭ rlu mâu geh nau klach.$b$,true),
('bunong-vn','PSA',5,1,null,$b$Ơ Yêhôva rkêng tôr ma nau gâp ngơi. Sek na nê̆ ma nau gâp mĭn.$b$,true),
('bunong-vn','PSA',5,2,null,$b$Ơ Hađăch gâp jêh ri Brah Ndu gâp, gŭ iăt bâr gâp nter ma May; Yor lah ma May yơh gâp mbơh sơm.$b$,true),
('bunong-vn','PSA',5,3,null,$b$Ơ Yêhôva, dôl ôi May mra tăng bâr gâp. Dôl ôi gâp mra mbơh sơm ma May jêh ri kâp njrăng.$b$,true),
('bunong-vn','PSA',5,4,null,$b$Yor lah May mâu jêng du huê Brah Ndu rŏng ma nau ƀai ôh. Bunuyh mhĭk mâu dơi du ndrel ma May ôh$b$,true),
('bunong-vn','PSA',5,5,null,$b$Bunuyh sưr rlau mâu dơi kâng ta năp măt May ôh. May tâm rmot ma lĕ rngôch phung ƀư nau kue$b$,false),
('bunong-vn','PSA',5,6,null,$b$May mra ƀư rai lơi phung mƀruh, Yêhôva tâm rmot ma bunuyh rung mham jêh ri ƀư nau ndơm.$b$,false),
('bunong-vn','PSA',5,7,null,$b$Bi gâp, yor nau ueh may âk ngăn gâp mra lăp tâm ngih May. Gâp mra chon mpeh pa ngih brah kloh ueh May ma nau klach yơk.$b$,true),
('bunong-vn','PSA',5,8,null,$b$Ơ Yêhôva, njŭn leo gâp tâm nau sŏng srăng May yor phung rlăng gâp; Ƀư ăn lâng trong May ta năp gâp$b$,true),
('bunong-vn','PSA',5,9,null,$b$Yor lah mâu geh nau n'hêl nanê̆ tâm trôm mbung khân păng; Nuih n'hâm khân păng bêng ma nau ƀai Bâr khân păng jêng ntu môch hŏng mâu geh ndrŭp Jêh ri mpiăt khân păng ngơi nau nklă$b$,false),
('bunong-vn','PSA',5,10,null,$b$Ơ Brah Ndu, rmal lơi khân păng Ăn nau khân păng tâm nchră, ăn tŭp khân păng nơm. Yor lah khân păng tâm rdâng đah May.$b$,false),
('bunong-vn','PSA',5,11,null,$b$Ƀiă lah lĕ rngôch phung rnơm ma May mra gŭ maak. Khân păng mra troh nau răm maak ƀa ƀơ Yor lah May king n'gang khân păng. Phung rŏng ma amoh May mra geh nau răm maak tâm May$b$,true),
('bunong-vn','PSA',5,12,null,$b$Yor lah May ăn nau ueh uĭn ma phung sŏng; Ơ Yêhôva, nau rŏng May gŭ jum păng tâm ban ma khêl.$b$,false),
('bunong-vn','PSA',6,1,null,$b$Ơ Yêhôva, lơi ta nduyh gâp, dôl May nuih Lơi May dong gâp, dôl May ji nuih,$b$,true),
('bunong-vn','PSA',6,2,null,$b$Yô̆ nđach an ma gâp, Ơ Yêhôva, ƀư bah an gâp, Yor lah gâp jêng rdja$b$,false),
('bunong-vn','PSA',6,3,null,$b$Nđâp ma huêng gâp uh ah ngăn, Bi May, ơ Yêhôva ndah jŏ?$b$,false),
('bunong-vn','PSA',6,4,null,$b$Lŏ văch, Ơ Yêhôva sâm rklaih an huêng gâp: Sâm rklaih an gâp yor nau ueh May$b$,true),
('bunong-vn','PSA',6,5,null,$b$Yor tâm nau khĭt mâu hôm kah gĭt ma May ôh Mbu mra mât ton ma May tâm Ƀon phung Khĭt?$b$,false),
('bunong-vn','PSA',6,6,null,$b$Dŭt n'hâm jêh nau gâp nter Ăp măng gâp nhĭm, luh dak măt tât bĕ sưng bêch. Sưng gâp bêch bĕ yor nau gâp nhĭm$b$,true),
('bunong-vn','PSA',6,7,null,$b$Măt gâp sŏng broy yor ma nau rngot, păng jêng mŭnh jêh yor ma lĕ rngôch phung rlăng đah gâp.$b$,false),
('bunong-vn','PSA',6,8,null,$b$Ơ phung ƀư nau kue, du ăn ngai đah gâp Yor lah Yêhôva tăng jêh nau gâp nter nhĭm$b$,true),
('bunong-vn','PSA',6,9,null,$b$Yêhôva tăng jêh nau gâp vơh vơl Yêhôva dơn nau gâp mbơh sơm.$b$,false),
('bunong-vn','PSA',6,10,null,$b$Lĕ phung rlăng đah gâp mra bêk jêh ri uh ah ngăn; Khân păng mra seng du, jêh ri nau bêk mra nkŭm khân păng.$b$,true),
('bunong-vn','PSA',7,1,null,$b$Ơ Yêhôva Brah Ndu gâp, gâp joi ntŭk krap tâm May Koh đŏng an gâp đah lĕ rngôch phung ƀư mhĭk đah gâp jêh ri sâm rklaih an gâp$b$,true),
('bunong-vn','PSA',7,2,null,$b$Klach lah khân păng sa hêk huêng gâp nâm bu Yau mŭr Ƀư rai lơi păng, mâu hôm geh nơm dơi Kơl gâp$b$,false),
('bunong-vn','PSA',7,3,null,$b$Ơ Yêhôva Brah Ndu gâp, Phung rlăng đah gâp ƀư nau kue;$b$,false),
('bunong-vn','PSA',7,4,null,$b$Tơ lah gâp mplơ̆ nau mhĭk ma nơm gŭ đăp mpăn ndrel ma gâp (Ơ, gâp kơl jêh nơm ƀư mhĭk ma gâp mâu geh nau)$b$,false),
('bunong-vn','PSA',7,5,null,$b$Ăn nơm rlăng tĭng gâp ăn ban; Ăn păng jot nau rêh gâp tâm dâng jâng păng. Jêh ri dơm nau chrêk rmah gâp tâm neh rmuy.$b$,false),
('bunong-vn','PSA',7,6,null,$b$Ơ Yêhôva, dâk hom May, tâm nau May ji nuih; Dâk hom May tâm lơh ma nau ji nuih phung rlăng đah gâp; Kah rngăl hom May jêh ri kơl gâp; May nkra jêh nau phat dôih$b$,true),
('bunong-vn','PSA',7,7,null,$b$Pô ri phung bu nuyh mra tâm rƀŭn jum May; Ăn May lŏ jêng Kôranh ta klơ khân păng tâm trôk$b$,false),
('bunong-vn','PSA',7,8,null,$b$Yêhôva phat dôih phung bunuyh, Phat dôih gâp ăn sŏng, Ơ Yêhôva, tĭng nâm nau sŏng srăng gâp jêh ri nau na nê̆ gŭ tâm gâp$b$,false),
('bunong-vn','PSA',7,9,null,$b$Ăn nau tih phung ƀai mra rai lôch ƀiă lah ƀư ăn nâp phung sŏng. Yor lah Brah Ndu sŏng sek uănh nau mĭn jêh ri nuih n'hâm$b$,false),
('bunong-vn','PSA',7,10,null,$b$Khêl gâp gŭ tâm Brah Ndu, Păng tâm rklaih phung geh nuih n'hâm sŏng$b$,false),
('bunong-vn','PSA',7,11,null,$b$Brah Ndu jêng Kôranh phat dôih sŏng Nanê̆, Brah Ndu geh nau ji nuih ăp nar.$b$,false),
('bunong-vn','PSA',7,12,null,$b$Tơ lah bunuyh mâu rmal ma nau tih păng, Brah Ndu mra tôl đao gưm Păng; Păng van na jêh ri nchrŏng;$b$,true),
('bunong-vn','PSA',7,13,null,$b$Jêh ri Brah Ndu nkra ma nơm nây ndơ tâm nkhĭt Păng nkra hăr ŭnh$b$,false),
('bunong-vn','PSA',7,14,null,$b$Aơ, bunuyh ƀai nkra nau mhĭk; Păng mĭn ma nau kue, jêh ri ngluh nau mƀruh$b$,false),
('bunong-vn','PSA',7,15,null,$b$Păng kuyh ntu jru, Jêh ri păng mra tŭp tâm ntu păng nơm.$b$,false),
('bunong-vn','PSA',7,16,null,$b$Nau ƀai păng mra plơ̆ sĭt ta bôk păng Jêh ri nau mhĭk mra tŭp ta ndăr kleng păng nơm$b$,true),
('bunong-vn','PSA',7,17,null,$b$Gâp mra tâm rnê ma Yêhôva yor nau sŏng srăng Păng, Gâp mra mprơ tâm rnê ma amoh Yêhôva, Nơm Ta Klơ Lơn Nau Chrêk Rmah Yêhôva Jêh Ri Nau Păng Yơk Ma Bunuyh Ma kôranh phung mprơ di ma bâr Gitit nau mprơ ơm Y-Đavit$b$,false),
('bunong-vn','PSA',8,1,null,$b$Ơ Yêhôva, Kôranh Brah hên, Amoh May khlay lơn tâm lam neh ntu May n'hao jêh nau chrêk rmah May prêh lơn ma lam trôk!$b$,true),
('bunong-vn','PSA',8,2,null,$b$Tă bơh trôm mbung phung kon se jê̆ nđâp ma phung hôm pu, May rdâk nau ktang, Gay ƀư uh ah ma phung rlăng đah May, Gay ăn nơm rlăng jêh ri nơm plơng bôk gŭ rklăk.$b$,true),
('bunong-vn','PSA',8,3,null,$b$Tơ lah gâp mĭn ma trôk jêng kan tă bơh nglau ti May ƀư;$b$,true),
('bunong-vn','PSA',8,4,null,$b$Moh bunuyh jêng tât May kah gĭt ma păng? Jêh ri kon bunuyh tât may khâl păng?$b$,false),
('bunong-vn','PSA',8,5,null,$b$May njêng păng djê̆ jê̆ lơn ma Brah Ndu. Jêh ri May ăn păng ndô nau chrêk rmah jêh ri nau yơk$b$,true),
('bunong-vn','PSA',8,6,null,$b$May ăn păng chiă uănh kan ti May; May dơm jêh lĕ rngôch mpô mpa tâm dâng jâng păng$b$,false),
('bunong-vn','PSA',8,7,null,$b$Phung biăp nđâp ma ndrôk, Nđâp ma mpa bri,$b$,false),
('bunong-vn','PSA',8,8,null,$b$Nđâp ma sĭm klơ trôk, jêh ri ka tâm dak rlai,$b$,false),
('bunong-vn','PSA',8,9,null,$b$Ơ Yêhôva, Kôranh Brah hên Amoh May khlay lơn ma lĕ neh ntu Lah Ueh Yor Nau Sŏng Brah Ndu$b$,false),
('bunong-vn','PSA',9,1,null,$b$Gâp mra tâm rnê ma Yêhôva ma lĕ nuih n'hâm. Gâp mra nkoch bri lĕ rngôch kan khlay dŭt n'hâm$b$,true),
('bunong-vn','PSA',9,2,null,$b$Gâp mra răm jêh ri maak tâm May; Gâp mra mprơ tâm rnê ma amoh May Ơ Brah Ndu Nơm Klơ Lơn$b$,false),
('bunong-vn','PSA',9,3,null,$b$Tơ lah phung rlăng rŭch nkơi, khân păng jêh ri rai lôch ta năp May.$b$,false),
('bunong-vn','PSA',9,4,null,$b$Yor lah May ăn gâp dơi, jêh ri n'gang nau gâp jêh; May gŭ ta sưng hađăch phat dôih ma nau sŏng.$b$,true),
('bunong-vn','PSA',9,5,null,$b$May hŏ nduyh jêh phung mpôl băl bunuyh, May ƀư rai jêh phung ƀai May lâm n'ho ro jêh amoh khân păng$b$,true),
('bunong-vn','PSA',9,6,null,$b$Mâu hôm geh phung rlăng ôh, lĕ roh rai n'ho ro jêh. May ƀư rai jêh ƀon khân păng Jêh ri mâu hôm kah gĭt ma khân păng ôh$b$,false),
('bunong-vn','PSA',9,7,null,$b$Yêhôva jêng hađăch chiă uănh n'ho ro Păng nkra jêh sưng Păng ma nau phat dôih$b$,false),
('bunong-vn','PSA',9,8,null,$b$Păng mra phat dôih neh ntu ma nau sŏng, Păng mra phat dôih phung bunuyh ma nau di$b$,false),
('bunong-vn','PSA',9,9,null,$b$Yêhôva jêng ntŭk krap ma phung bu tŭn jot, Ntŭk krap tâm nar djơh mhĭk.$b$,false),
('bunong-vn','PSA',9,10,null,$b$Phung gĭt năl amoh May mra nsing ma May; Yor lah May mâu mâp cha lơi ôh phung joi May Ơ Yêhôva.$b$,true),
('bunong-vn','PSA',9,11,null,$b$Mprơ hom ma Yêhôva, nơm gŭ tâm ƀon Siôn mbơh tâm nklang phung ƀon lan nau Păng ƀư$b$,true),
('bunong-vn','PSA',9,12,null,$b$Yor lah nơm plơng bôk ma mham kah gĭt ma phung rêh ni Păng mâu chuêl ôh nau bu nhĭm nhhiăng$b$,false),
('bunong-vn','PSA',9,13,null,$b$Yô̆ nđach ma gâp, Ơ Yêhôva; Uănh ma nau rêh ni gâp hŏ dơn tă bơh phung tâm rmot ma gâp, May hŏ chông rdu gâp tă bơh mpông pêr nau khĭt;$b$,false),
('bunong-vn','PSA',9,14,null,$b$Gay ma gâp mbơh lĕ nau tâm rnê ma May. Ta mpông pêr kon bu ur ƀon Siôn. Gâp mra răm maak tâm nau May tâm rklaih.$b$,false),
('bunong-vn','PSA',9,15,null,$b$Phung mpôl băl tŭp tâm ntu jru khân păng kuyh jêh. Jâng khân păng văk tâm jal srêt khân păng nơm nthăng.$b$,true),
('bunong-vn','PSA',9,16,null,$b$Yêhôva tâm mpơl Păng Nơm, Păng ƀư jêh nau sŏng Bunuyh ƀai plơ̆ geh nhuăl păng nơm nthăng uh dĭng (Sêla)$b$,true),
('bunong-vn','PSA',9,17,null,$b$Phung ƀai ƀư ntrŭt du ta ƀon phung khĭt, Lĕ rngôch phung mpôl băl chuêl Brah Ndu$b$,false),
('bunong-vn','PSA',9,18,null,$b$Yor lah bu mâu mra chuêl ôh phung rêh ni. Nau phung o ach geh kâp gân mâu mra roh rai n'ho ro ôh$b$,false),
('bunong-vn','PSA',9,19,null,$b$Dâk hom ơ Yêhôva, lơi ăn bunuyh dơi ôh: Ăn phung mpôl băl bunuyh dơn nau phat dôih ta năp măt May.$b$,false),
('bunong-vn','PSA',9,20,null,$b$Ăn khân păng klach, Ơ Yêhôva; Ăn phung mpôl băl gĭt khân păng jêng knŏng bunuyh.$b$,true),
('bunong-vn','PSA',10,1,null,$b$Ơ Yêhôva, mâm ƀư May gŭ ngai? Mâm ƀư May du krap dôl geh nau rêh ni?$b$,true),
('bunong-vn','PSA',10,2,null,$b$Ma nau sưr rlau phung ƀai tĭng bunuyh o ach; Ăn khân păng tŭp tâm dăk khân păng sân Ăn khân păng tŭp tâm jal khân păng nơm$b$,true),
('bunong-vn','PSA',10,3,null,$b$Yor lah phung ƀai tâm rnê ma khân păng nơm ma nau nuih n'hâm khân păng ŭch, Jêh ri khân păng ngơi nau ueh ngăn ma nơm kơnh, jêh ri suai rak ma Yêhôva.$b$,false),
('bunong-vn','PSA',10,4,null,$b$Phung ƀai ngơi ma nau sưr, Păng mâu tâm rmal ôh; Lĕ nau păng mĭn pô nây. Mâu geh Brah Ndu ôh.$b$,true),
('bunong-vn','PSA',10,5,null,$b$Lĕ trong păng dơi jêng n'ho ro; Nau May phat dôih jêng prêh lơn tât măt păng mâu dơi saơ; Păng mưch ma lĕ rngôch phung rlăng đah păng$b$,true),
('bunong-vn','PSA',10,6,null,$b$Păng lah tâm nuih n'hâm păng; gâp mâu mra n'gơ ôh; Nau djơh mhĭk mâu mra tât ma gâp$b$,false),
('bunong-vn','PSA',10,7,null,$b$Trôm mbung păng bêng ma nau rtăp rak, nau mƀruh jêh ri nau saƀĭt, saƀer Mpiăt păng geh nau tih jêh ri nau kue$b$,false),
('bunong-vn','PSA',10,8,null,$b$Păng gŭ kâp tâm mpâr ƀon Păng nkhĭt phung mâu geh nau tih tâm ntŭk ndâp Măt păng kâp sek uănh ŭch ƀư ma phung rêh ni$b$,false),
('bunong-vn','PSA',10,9,null,$b$Păng gŭ krap ndâp tâm pôm rsuăn nâm bu yau mŭr. Păng gŭ krap gay ma nhŭp phung o-ach Păng nhŭp bu nâm iang tâm jal păng$b$,false),
('bunong-vn','PSA',10,10,null,$b$Păng chon, păng kunh, jêh ri phung rêh-ni tŭp iang tâm nheh păng$b$,false),
('bunong-vn','PSA',10,11,null,$b$Păng mĭn tâm nuih n'hâm păng: Brah Ndu chuêl jêh Păng pôn măt, mâu mra uănh ôh$b$,false),
('bunong-vn','PSA',10,12,null,$b$Dâk hom May, Ơ Yêhôva, Ơ Brah Ndu, yơr hom ti May. Lơi ta chuêl phung o ach ôh.$b$,false),
('bunong-vn','PSA',10,13,null,$b$Mâm ƀư phung ƀai suai rak ma Brah Ndu? Mâm păng lah tâm nuih n'hâm păng, May mâu mâp tâm rmal ôh?$b$,true),
('bunong-vn','PSA',10,14,null,$b$May saơ lĕ jêh; Yor lah May saơ nau rêh ni jêh ri nau jêr. Gay ma tâm rmal khân păng ma ti May. Phung rêh ni jao khân păng nơm ma May, May yơh kơl phung kon đơi khĭt mbơ̆$b$,true),
('bunong-vn','PSA',10,15,null,$b$Kêch lơi nting tur phung ƀai, Rmal lơi nau tih păng, lơi hôm ăn saơ păng ta năp măt May$b$,false),
('bunong-vn','PSA',10,16,null,$b$Yêhôva jêng hađăch n'ho ro Phung mpôl băl roh rai jêh tă bơh bri neh păng$b$,false),
('bunong-vn','PSA',10,17,null,$b$Ơ Yêhôva, May iăt jêh nau phung tông bâr May ŭch, May mra ăn nâp rjăp nuih n'hâm khân păng, May mra rkêng tôr ma khân păng$b$,false),
('bunong-vn','PSA',10,18,null,$b$Gay ƀư nau sŏng ma phung kon đơi khĭt mbơ̆ , jêh ri ma phung bu tŭn jot, neh mâu hôm jêng mhĭk. Yêhôva Jêng Nơm King Jêh Ri Ntŭk Krap Ma Phung Kôranh Mprơ: Nau mprơ ơm Y-Đavit$b$,false),
('bunong-vn','PSA',11,1,null,$b$Gâp gŭ krap tâm Yêhôva; Mâm ƀư may lah ma huêng gâp may hăn du hom tâm yôk may, tâm ban ma du mlâm sĭm$b$,true),
('bunong-vn','PSA',11,2,null,$b$Yor lah phung ƀai hŏ van jêh na: Khân păng dăp hăr, Ŭch pănh tâm phung geh nuih n'hâm sŏng dôl ngo$b$,false),
('bunong-vn','PSA',11,3,null,$b$Tơ lah ntur ngih rlâm jêh, Moh nơm sŏng dơi ƀư?$b$,false),
('bunong-vn','PSA',11,4,null,$b$Yêhôva gŭ tâm ngih brah kloh ueh Păng Yêhôva geh sưng hađăch Păng tâm trôk Măt Păng uănh, sâng măt Păng treng, phung kon bunuyh.$b$,true),
('bunong-vn','PSA',11,5,null,$b$Yêhôva rlong uănh phung sŏng; Ƀiă lah Păng tâm rmot ma phung ƀai jêh ri ma phung ŭch ƀư nau janh ƀai$b$,true),
('bunong-vn','PSA',11,6,null,$b$Păng mra nkhŭt sa ônh hâng ta phung ƀai Ŭnh, mô ŭnh jêh ri sial duh jêng kachok bu tâm pă ăn ma khân păng$b$,false),
('bunong-vn','PSA',11,7,null,$b$Yor lah Yêhôva jêng sŏng; Păng rŏng ma nau sŏng srăng, Phung bunuyh sŏng mra uănh muh măt Păng. Brah Ndu Nơm Kơl King N'gang Bơh Phung Tih Mhĭk Ma Kôranh Phung Mprơ: Di ma, bâr semĭnit nau mprơ Y-Đavit$b$,false),
('bunong-vn','PSA',12,1,null,$b$Kơl hom ơ Yêhôva, Yor lah mâu hôm geh ôh phung bunuyh sŏng srăng Mâu geh ôh phung nanê̆ tâm phung kon bunuyh.$b$,true),
('bunong-vn','PSA',12,2,null,$b$Khân păng ngơi mƀruh ndrăng nơm Ma bâr mbung khân păng ngơi nau nklă nuih n'hâm khân păng mĭn bar ntil nau$b$,true),
('bunong-vn','PSA',12,3,null,$b$Yêhôva mra ƀư rai lĕ rngôch bâr mbung ngơi nklă Jêh ri mpiăt ngơi sưr rlau ir$b$,false),
('bunong-vn','PSA',12,4,null,$b$Khân păng lah pô aơ; Hên mra dơi yor ma mpiăt hên, Hên geh trôm mbung ndrel ma hên nơm, mbu nâm mra jêng kôranh hên?$b$,false),
('bunong-vn','PSA',12,5,null,$b$Yor lah bu tŭn jot phung rêh ni jêh ri phung o ach nđêng, Yêhôva lah: Aƀaơ gâp mra dâk; Gâp mra ăn khân păng gŭ đăp mpăn tĭng nâm nau khân păng vơh vơl$b$,true),
('bunong-vn','PSA',12,6,null,$b$Nau Yêhôva ngơi jêng nau ngơi kloh Nâm bu prăk bu long uănh tâm dĭng nuh pơh tơ̆ ƀư kloh.$b$,false),
('bunong-vn','PSA',12,7,null,$b$Ơ Yêhôva, May mra chiă uănh khân păng May mra n'gang khân păng ntơm bơh rnôk aơ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',12,8,null,$b$Phung ƀai nsong lam ntŭk, Tơ lah phung kon bunuyh yơk ma nau tih. Vơh Vơl Ma Brah Ndu Kơl Tâm Nau Rêh-Ni Ma Kôranh Phung Mprơ: Nau mprơ ơm Y-Đavit$b$,true),
('bunong-vn','PSA',13,1,null,$b$Ơ Yêhôva, dŭm jŏ? May mra chuêl gâp n'ho ro? Dŭm jŏ May mra pôn măt May ma gâp.$b$,true),
('bunong-vn','PSA',13,2,null,$b$Dŭm jŏ gâp mra gŭ tâm nchră tâm huêng gâp, jêh ri ăp nar geh nau rngot tâm nuih n'hâm gâp. Dŭm jŏ bu mra n'hao nơm rlăng đah gâp, prêh lơn ma gâp?$b$,true),
('bunong-vn','PSA',13,3,null,$b$Ơ Yêhôva, Brah Ndu gâp, mĭn hom jêh ri plơ̆ lah ma gâp: Ăn ang măt gâp, klach lah gâp lêt bêch tâm nau khĭt$b$,true),
('bunong-vn','PSA',13,4,null,$b$Klach lah nơm rlăng đah gâp mra lah Dơi gâp jêh đah păng Jêh ri phung tâm rdâng đah gâp mra răm tơ lah gâp n'gơ$b$,false),
('bunong-vn','PSA',13,5,null,$b$Ƀiă lah gâp rnơm ma nau ueh May Nuih n'hâm gâp mra răm rhơn tâm nau May tâm rklaih$b$,false),
('bunong-vn','PSA',13,6,null,$b$Gâp mra mprơ ma Yêhôva, Yor lah păng ƀư jêh nau ueh ma gâp Nau Rluk Jêh Ri Nau Hăt Janh Kon Bunuyh Ma Kôranh Phung Mprơ: Nau mprơ ơm Y-Đavit$b$,false),
('bunong-vn','PSA',14,1,null,$b$Bunuyh rluk rluk lah tâm nuih n'hâm păng mâu geh Brah Ndu ôh. Khân păng geh nau khư ôm, khân păng ƀư kan djơh mhĭk, Mâu geh du huê ƀư nau ueh ôh$b$,true),
('bunong-vn','PSA',14,2,null,$b$Bơh klơ trôk Yêhôva uănh ma phung kon bunuyh, Gay saơ, gĭt lah geh bunuyh gĭt rbăng.$b$,false),
('bunong-vn','PSA',14,3,null,$b$Lĕ rngôch khân păng nkhah du; lĕ rngôch khân păng ƀơ̆ jêh Mâu geh nơm ƀư nau ueh, du huê mâu geh lĕ$b$,true),
('bunong-vn','PSA',14,4,null,$b$Di lĕ, lĕ rngôch phung ƀư nau kue mâu geh nau blau mĭn? Khân păng sa phung ƀon lan gâp tâm ban ma sa kapŭng. Khân păng mâu kuăl mbơh sơm ma Yêhôva ôh$b$,false),
('bunong-vn','PSA',14,5,null,$b$Dôl nây khân păng geh nau klach hâu ngăn Yor lah Brah Ndu gŭ ta nklang phung bunuyh sŏng$b$,false),
('bunong-vn','PSA',14,6,null,$b$Khân may ƀư bêk nau phung o-ach tâm nchră Ƀiă lah Yêhôva jêng ntŭk khân păng gŭ krap$b$,false),
('bunong-vn','PSA',14,7,null,$b$Ơ, ŭch ngăn ma nau tâm rklaih phung Israel du luh jêh tă bơh ƀon Siôn! Tơ lah Yêhôva mra njŭn sĭt phung bu nă ƀon lan păng, Dôl nây Yakôb mra maak, Phung Israel mra răm rhơn Mâm Jêng Bunuyh Ƀon Lan Siôn Nau mprơ ơm Y-Đavit$b$,false),
('bunong-vn','PSA',15,1,null,$b$Ơ Yêhôva, mbu mra gŭ tâm ngih bok May? Mbu mra gŭ ta yôk kloh May?$b$,true),
('bunong-vn','PSA',15,2,null,$b$Nơm hăn ma nau sŏng jêh ri ƀư nau di Jêh ri ngơi nau nanê̆ tâm nuih n'hâm păng$b$,true),
('bunong-vn','PSA',15,3,null,$b$Nơm mâu mâp nchơt ôh tă bơh mpiăt păng Mâu mâp ƀư mhĭk lĕ ma băl păng, Mâu mâp ƀư bêk lĕ ma nơm chiau meng păng,$b$,false),
('bunong-vn','PSA',15,4,null,$b$Păng uănh ma phung tih mhĭk ma nau tâm rmot, Ƀiă lah păng yơk ma phung blau yơk ma Yêhôva Păng mâu tâm rgâl ôh, nđâp tơ lah nau huach nglay săk jêng nau roh ma păng;$b$,false),
('bunong-vn','PSA',15,5,null,$b$Păng mâu ăn ôh bu chan prăk ma nau ŭch sa kao, Mbu mâu ăn chan prăk sŏk kao? Mâu lĕ sŏk dơn nau nkhôm saƀĭt sa kao đah phung sŏng Mbu nâm ƀư pô nây mâu mra mâp nau mpât n'gơ ôh Yêhôva Jêng Kô̆ Ueh Ma Nơm Mprơ Geh Tâm Nau Rêh Jêh Ri Nơm Tâm Rklaih Păng Bơh Nau Khĭt: Nau mprơ ơm Y-Đavit$b$,false),
('bunong-vn','PSA',16,1,null,$b$Ơ Brah Ndu, king gâp Yor lah gâp krap tâm May$b$,true),
('bunong-vn','PSA',16,2,null,$b$Gâp lah ma Yêhôva, may Jêng Kôranh Brah gâp Gâp mâu geh nau ueh ôh tâm nơm êng$b$,false),
('bunong-vn','PSA',16,3,null,$b$Phung kloh ueh tâm neh ntu jêng bu nuyh sŏng. Tâm khân păng gâp geh lĕ nau maak$b$,false),
('bunong-vn','PSA',16,4,null,$b$Nau rngot mra jêng âk lơn ma phung nhhơr mpa ma brah êng Gâp mâu mra nhhơr ôh nau khân păng nhhơr mham khân păng nơm Gâp mâu mra ngơi amoh khân păng ma bâr mbung gâp$b$,false),
('bunong-vn','PSA',16,5,null,$b$Yêhôva jêng drăp gâp krâm jêh ri kachok gâp nhêt Păng yơh chiă uănh drăp gâp$b$,false),
('bunong-vn','PSA',16,6,null,$b$Drăp krâm, ueh ngăn păng prăp ma gâp. Păng ăn ntŭk maak ma gâp$b$,false),
('bunong-vn','PSA',16,7,null,$b$Gâp tâm rnê ma Yêhôva, păng jêng nơm nchră an ma gâp; Nuih n'hâm gâp, nti gâp dôl măng$b$,false),
('bunong-vn','PSA',16,8,null,$b$Gâp geh Yêhôva ta năp gâp mro Gâp mâu mra mpât n'gơ ôh Yor lah păng gŭ mpeh pa ma gâp$b$,false),
('bunong-vn','PSA',16,9,null,$b$Yor nây yơh nuih n'hâm gâp maak, huêng gâp răm rhơn Jêh ri săk jăn gâp mra gŭ rlu ma nau đăp mpăn.$b$,false),
('bunong-vn','PSA',16,10,null,$b$Yor lah mâu cha lơi huêng gâp tâm ƀon phung khĭt Mâu lĕ May mra ăn Phung Kloh Ueh May blau ôm rai$b$,true),
('bunong-vn','PSA',16,11,null,$b$May mra ăn gâp gĭt trong nau rêh Ta năp May geh lĕ nau răm maak Ta ti ma May geh nau ueh maak ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','PSA',17,1,null,$b$Ơ Yêhôva gŭ iăt nau sŏng srăng, gŭ iăt ăn na nê̆ ma nau gâp nter; Rkêng tôr May ma nau gâp mbơh sơm ma bâr mbung mâu geh nau ndơm ôh$b$,true),
('bunong-vn','PSA',17,2,null,$b$Ăn nau di gâp lah ta năp May Ăn măt May uănh ma nau sŏng$b$,false),
('bunong-vn','PSA',17,3,null,$b$May sek uănh jêh nuih n'hâm gâp; May khâl jêh gâp dôl măng May rlong uănh jêh gâp, ƀiă lah May mâu saơ geh nau ôh. Gâp săch jêh nau aơ, trôm mbung gâp mâu mra tih ôh.$b$,false),
('bunong-vn','PSA',17,4,null,$b$Gâp saơ jêh kan phung bunuyh ƀư. Nau gâp rnơm ma nau ngơi tă bơh bâr mbung May, Gâp n'gang gâp nơm đah trong phung janh ktang.$b$,true),
('bunong-vn','PSA',17,5,null,$b$Nhuat gâp nâp jêh tâm trong May Jâng gâp mâu geh prah ôh$b$,true),
('bunong-vn','PSA',17,6,null,$b$Gâp mbơh sơm jêh ma May, Ơ Brah Ndu, Yor lah May mra dơn nau gâp. Rkêng tôr May ma gâp, gŭ iăt hom nau gâp lah$b$,false),
('bunong-vn','PSA',17,7,null,$b$Hơi Kôranh Brah, dŏng ti ma May gay tâm rklaih phung krap mbe May Bơh nau phung rlăng ƀư ma khân păng$b$,false),
('bunong-vn','PSA',17,8,null,$b$Mât mơh an gâp tâm ban ma găr măt, King gâp tâm dâng n'hâm năr May$b$,false),
('bunong-vn','PSA',17,9,null,$b$Tă bơh phung djơh mhĭk tŭn jot gâp, Tă bơh phung rlăng ji nuih ngăn gŭ nchueng gâp$b$,false),
('bunong-vn','PSA',17,10,null,$b$Khân păng chăng nuih n'hâm gâp Bâr mbung khân păng ngơi sưr.$b$,false),
('bunong-vn','PSA',17,11,null,$b$Khân păng nchueng jum nhuat hên jêh Khân păng rmơch lơh gay ma ăn hên prah ta neh.$b$,true),
('bunong-vn','PSA',17,12,null,$b$Păng jêng tâm ban ma yau mŭr ji ngot ngăn ŭch sa hêk bu. Tâm ban ma yau mŭr gŭ kâp tâm rsuăn păng.$b$,true),
('bunong-vn','PSA',17,13,null,$b$Ơ Yêhôva, dâk hom May, Hăn tâm mâp đah nơm ƀai, nklơ̆ ăn păng cha lôt Ăn đao May sâm rklaih huêng gâp tă bơh păng.$b$,true),
('bunong-vn','PSA',17,14,null,$b$Ơ Yêhôva, dŏng ti May rklaih an gâp tă bơh phung bunuyh, phung bunuyh rnôk aơ geh, nau nkhôm tâm nau rêh aơ, Jêh ri May ăn khân păng sa hơm ndŭl khân păng khân păng, ma drăp ndơ May Khân păng maak yor phung kon khân păng, jêh ri khân păng lơi drăp rmeh ma phung sau khân păng$b$,true),
('bunong-vn','PSA',17,15,null,$b$Bi gâp be, gâp mra saơ muh măt May yor nau sŏng srăng gâp Tơ lah gâp kah rngăl bêch, gâp mra hơm ma rup May Nau Tâm Rnê Ma Yêhôva Yor Păng Ăn Nau Dơi Jêh Ri Nau Chiă Uănh ma Kôranh Phung Mprơ Nau mprơ ơm Y-Đavit, oh mon Yêhôva, păng ngơi rplay sămƀŭt nau mprơ aơ ma Yêhôva nar Yêhôva tâm rklaih păng bơh ti Y-Sôl; jêh ri păng lah:$b$,false),
('bunong-vn','PSA',18,1,null,$b$Gâp rŏng ma May, Ơ Yêhôva, nau ktang gâp.$b$,true),
('bunong-vn','PSA',18,2,null,$b$Yêhôva jêng lŭ gâp, pêr mbâl gâp, jêh ri nơm ăn gâp đăp mpăn Brah Ndu jêng lŭ gâp, gâp gŭ krap tâm May Khêl gâp, nke ma nau tâm rklaih gâp, jay tŭm prêh gâp$b$,true),
('bunong-vn','PSA',18,3,null,$b$Gâp mra kuăl mbơh sơm ma Yêhôva, nơm khư bu mât ton Pô ri gâp klaih jêh tă bơh phung rlăng đah gâp$b$,false),
('bunong-vn','PSA',18,4,null,$b$Brăt nau khĭt kât jêh jum gâp Nkrit jêh gâp ma dak klŏng jru nau ƀai$b$,false),
('bunong-vn','PSA',18,5,null,$b$Brăt Ƀon Phung Khĭt kât jum gâp jêh Ndrŏt jêh gâp ma jal nau khĭt$b$,false),
