('bunong-vn','PSA',18,47,null,$b$Brah Ndu jêng nơm plơng bôk ma gâp. Jêh ri nglăp phung ƀon lan tâm dâng gâp$b$,false),
('bunong-vn','PSA',18,48,null,$b$Păng tâm rklaih gâp bơh phung rlăng gâp Kôranh Brah nhhơk gâp hao prêh lơn đah phung tâm rdâng đah gâp. May tâm rklaih gâp bơh bunuyh janh ƀai.$b$,false),
('bunong-vn','PSA',18,49,null,$b$Yor nây, gâp tâm rnê ma may ơ Yêhôva, ta nkang phung mpôl băl. Jêh ri mprơ tâm rnê ma amoh May$b$,true),
('bunong-vn','PSA',18,50,null,$b$Păng ăn nau tâm rklaih toyh ma hađăch Păng Jêh ri Păng ăn nau ueh lăng ma nơm Păng troch dak ngi Ma Y-Đavit jêh ri ma phung kon sau Păng ƀa ƀơ n'ho ro Kan Brah Ndu Jêh Ri Nau Păng Ngơi Ma Kôranh Phung Mprơ Nau mprơ Y-Đavit$b$,false),
('bunong-vn','PSA',19,1,null,$b$Lĕ rngôch tă bơh trôk nkoch bri nau chrêk rmah Brah Ndu. Lĕ ntŭk ƀa ƀă tâm trôk mbơh nau ti Păng kan.$b$,true),
('bunong-vn','PSA',19,2,null,$b$Nar aơ, nti lah ma nar kăndơ̆ Măng aơ ăn nau gĭt ma măng kăndơ̆$b$,true),
('bunong-vn','PSA',19,3,null,$b$Mâu geh bâr, mâu geh nau ngơi Bu mâu tăng ôh bâr khân păng$b$,false),
('bunong-vn','PSA',19,4,null,$b$Ƀiă lah nau khân păng nhhiăng hăn lam bri neh Bâr khân păng hăn tât ta dŭt bri dŭt neh Ta nây păng ƀư ngih bok ma nar$b$,false),
('bunong-vn','PSA',19,5,null,$b$Nar jêng tâm ban ma du huê sai luh tă bơh jrô păng. Maak ma nau tâm rlong nchuăt tâm ban ma du huê bunuyh dăng ktang.$b$,false),
('bunong-vn','PSA',19,6,null,$b$Păng luh tă bơh ntŭk dŭt bri, pa aơ Jêh ri hăn lôch tât ta ntŭk dŭt bri pa ri Mâu geh ndơ dơi nde ndâp đah nchrat duh păng$b$,true),
('bunong-vn','PSA',19,7,null,$b$Nau Yêhôva jêng rah vah, ntop nau rêh tâm huêng Nau Yêhôva mbơh jêng nanê̆, Păng ăn phung rluk mâl jêng gĭt mleh$b$,false),
('bunong-vn','PSA',19,8,null,$b$Nau Yêhôva jêng sŏng Păng ăn nuih n'hâm maak Nau Yêhôva ntăm jêng kloh, Păng ăn măt bu jêng ang$b$,false),
('bunong-vn','PSA',19,9,null,$b$Nau klach yơk ma Yêhôva ntăm jêng na nê̆ jêh ri di da dê$b$,false),
('bunong-vn','PSA',19,10,null,$b$Lĕ nau nây păng khlay lơn ma mah, nđâp ma mah rhên Njŭng lơn ma dak sŭt, dak sŭt luh tă bơh sêng$b$,false),
('bunong-vn','PSA',19,11,null,$b$Nđâp ma oh mon may lĕ nti tă bơh khân păng Ma mbu nâm gŭ ngao sŏng khân păng Mra geh nau nkhôm toyh ngăn$b$,false),
('bunong-vn','PSA',19,12,null,$b$Mbu nâm dơi gĭt rbăng nau tih păng? Yô̆ an ma gâp moh nau tih gâp mâu gĭt rbăng$b$,false),
