('bunong-vn','PSA',19,14,null,$b$Ăn nau ngơi tă bơh bâr mbung gâp jêh ri nau mĭn bơh nuih n'hâm gâp Ăn jêng khư ma nau may dơn, Ơ Yêhôva, lŭ gâp jêh ri tĭng gâp Mbơh Sơm Gay Ma Geh Nau Dơi Đah Phung Rlăng Ma Phung Kôranh Mprơ Nau mprơ ơm Y-Đavit$b$,false),
('bunong-vn','PSA',20,1,null,$b$Ăn Yêhôva lŏ plơ̆ lah ma may ta nar rêh ni; Ăn amoh Brah Ndu Yakôb king may.$b$,true),
('bunong-vn','PSA',20,2,null,$b$Bơh ngih bok kloh ueh ăn Păng njuăl nau kơl may Bơh Siôn ăn Păng kuăn rdâng may;$b$,true),
('bunong-vn','PSA',20,3,null,$b$Ăn Păng kah gĭt ma lĕ rngôch ndơ may nhhơr, jêh ri ăn păng dơn ndơ may ƀư brah gŭch;$b$,false),
('bunong-vn','PSA',20,4,null,$b$Dăn Păng ăn ma may lĕ nuih n'hâm ŭch Jêh ri gay ma Păng ăn dơi tât lĕ nau may mĭn ƀư$b$,false),
('bunong-vn','PSA',20,5,null,$b$Hên geh nau răm rhơn ma nau may tâm rklaih, hên n'hao kơ ma amoh Brah Ndu he; Yêhôva ăn lĕ nau may dăn$b$,false),
('bunong-vn','PSA',20,6,null,$b$Gâp gĭt jêh Yêhôva tâm rklaih nơm Păng troch dak ngi; Tă bơh trôk, ntŭk kloh ueh Păng, Păng lŏ plơ̆ lah ma ô băl Ma nau kơl brah, bơh ti ma Păng$b$,false),
('bunong-vn','PSA',20,7,null,$b$Geh phung ƀa ƀă rnơm ma ndeh, ƀa ƀă rnơm ma seh, Ƀiă lah rnơm ma amoh Yêhôva, Brah Ndu he.$b$,false),
('bunong-vn','PSA',20,8,null,$b$Khân păng jêng ra ai jêh ri prah; Ƀiă lah he dâk jêh ri gŭ ngao sŏng.$b$,true),
('bunong-vn','PSA',20,9,null,$b$Ơ Yêhôva tâm rklaih hom: Ăn hađăch lŏ plơ̆ lah ma hên tơ lah hên kuăl.$b$,true),
('bunong-vn','PSA',21,1,null,$b$Ơ Yêhôva, hađăch mra geh nau răm maak tâm nau ktang May; Jêh ri păng, mra maak hâu ngăn ngên tâm nau May tâm rklaih!$b$,true),
('bunong-vn','PSA',21,2,null,$b$May ăn jêh ma păng nau nuih n'hâm ŭch Jêh ri May mâu dun ôh moh nau bâr mbung păng dăn$b$,true),
('bunong-vn','PSA',21,3,null,$b$Yor lah ma nau ueh uĭn bơh nau may yô̆, May hăn tâm mâp jêh đah păng. May ndô jêh ta bôk păng đon hađăch mah kloh$b$,false),
('bunong-vn','PSA',21,4,null,$b$Păng dăn ma May nau rêh, May ăn jêh ma păng, Nau rêh ueh jêh ri gŭ n'ho ro$b$,false),
('bunong-vn','PSA',21,5,null,$b$Yor nau Brah Ndu tâm rklaih, păng geh nau chrêk rmah hâu ngăn. May dơm tâm păng nau yơk jêh ri nau rnam.$b$,false),
('bunong-vn','PSA',21,6,null,$b$Yor lah May ăn păng jêng nơm geh nau ueh uĭn âk lơn ƀa ƀơ n'ho ro. May mbêng păng ma nau răm ta năp muh măt May.$b$,true),
('bunong-vn','PSA',21,7,null,$b$Yor hađăch nsing ma Yêhôva, Nsing nau yô̆ tă bơh Nơm prêh klơ, Păng mâu geh nau mpât ôh,$b$,true),
('bunong-vn','PSA',21,8,null,$b$Ti May mra hăn joi lĕ rngôch phung rlăng đah May Ti ma May mra hăn joi di phung rlăng ma May;$b$,false),
('bunong-vn','PSA',21,9,null,$b$May mra ƀư ma khân păng nâm bu ŭnh năk duh, tâm May mra tâm mpơl Yêhôva mra rvăn ăn phung nây tâm nau păng ji nuih Jêh ri ŭnh mra sa khân păng$b$,false),
('bunong-vn','PSA',21,10,null,$b$May mra ăn roh phung kon sau khân păng bơh neh ntu, jêh ri mpôl khân păng tă tâm nklang phung kon bunuyh$b$,false),
('bunong-vn','PSA',21,11,null,$b$Khân păng ŭch ƀư mhĭk ma May, Khân păng mĭn ƀư nau ƀai, ƀiă lah khân păng mâu dơi jêng ôh$b$,false),
('bunong-vn','PSA',21,12,null,$b$Yor lah May mra ăn khân păng du, May nchrŏng na May ma khân păng$b$,false),
('bunong-vn','PSA',21,13,null,$b$Ơ Yêhôva, ăn May geh nau yơk tâm nau ktang May; Pô ri hên mra mprơ, tâm rnê ma nau brah May. Bâr Nđêng Jêh Ri Nau Mprơ Tâm Rnê, Ma Kôranh Phung Mprơ: Di Ma Bâr Ajêlĕt Hassahar Nau mprơ Y-Đavit$b$,false),
('bunong-vn','PSA',22,1,null,$b$Ơ Brah Ndu gâp, Ơ Brah Ndu gâp, Mâm ƀư may cha lơi gâp? Mâm ƀư May gŭ ngai mâu ŭch kơl gâp, jêh ri mâu tăng gâp nđêng?$b$,true),
('bunong-vn','PSA',22,2,null,$b$Ơ Brah Ndu gâp, gâp nter tâm nŭng- nar, ƀiă lah mâu saơ May plơ̆ lah ôh;$b$,true),
('bunong-vn','PSA',22,3,null,$b$Ƀiă lah May jêng Nơm Kloh Ueh. Nau phung Israel tâm rnê.$b$,false),
('bunong-vn','PSA',22,4,null,$b$Phung mbơ̆ hên rnơm jêh, jêh ri May tâm rklaih jêh khân păng.$b$,true),
('bunong-vn','PSA',22,5,null,$b$Khân păng nter jêh ma May, jêh ri May tâm rklaih jêh khân păng; Khân păng rnơm ma May jêh, jêh ri May mâu ƀư bêk khân păng ôh.$b$,true),
('bunong-vn','PSA',22,6,null,$b$Ƀiă lah gâp jêng du mlâm ndrŭng jêh ri mâu tăp du huê bunuyh ôh. Gâp jêng ndơ ƀư bêk ma bunuyh, jêh ri ndơ ƀon lan tâm rmot.$b$,true),
('bunong-vn','PSA',22,7,null,$b$Lĕ rngôch mbu nâm saơ gâp gơm mưch ma gâp Khân păng nsut mbung jêh ri rteh bôk lah,$b$,true),
('bunong-vn','PSA',22,8,null,$b$Păng rnơm jêh ma Yêhôva, gay ma Yêhôva tâm rklaih păng Ăn Yêhôva tâm rklaih păng, Yor lah Yêhôva rŏng ma păng$b$,false),
('bunong-vn','PSA',22,9,null,$b$Ơ, May ngluh jêh gâp tă bơh ndŭl me; May ƀư nâp jêh nau gâp rnơm dôl rnôk gâp gŭ ta ntang ntơh me gâp.$b$,false),
('bunong-vn','PSA',22,10,null,$b$May hŏ chiă uănh jêh gâp ntơm bơh ndŭl me Ntơm bơh me deh ma gâp may hŏ jêng Brah Ndu gâp jêh$b$,true),
('bunong-vn','PSA',22,11,null,$b$Lơi ta gŭ ngai đah gâp, Yor lah nau uh ah hŏ dăch jêh; Yor lah mâu geh du huê văch koh dŏng gâp$b$,false),
('bunong-vn','PSA',22,12,null,$b$Geh âk ndrôk nkuăng nchueng jum gâp. Phung ndrôk nkuăng ktang tă bơh Basan gŭ jum gâp$b$,false),
('bunong-vn','PSA',22,13,null,$b$Khân păng ha mbung ŭch ƀư ma gâp, Tâm ban ma yau mŭr gŭ sa hêk jêh ri ngrông$b$,false),
('bunong-vn','PSA',22,14,null,$b$Gâp jêng tâm ban ma dak bu nkhŭt lơi Jêh ri lĕ rngôch nting gâp mâu hôm tâm nsĭr ôh. Play nuih gâp tâm ban ma mpêt, păng lêk tâm proch, klơm gâp$b$,false),
('bunong-vn','PSA',22,15,null,$b$N'hâm suan gâp sơh kro tâm ban ma neh bŏk pêt Sêk gâp iang ma mơr dơ̆ May ăn gâp bêch tâm neh rmuy nau khĭt$b$,false),
('bunong-vn','PSA',22,16,null,$b$Yor lah phung so gŭ jum gâp Du phung janh nchueng jum gâp Khân păng ntâp bluh jâng ti gâp.$b$,false),
('bunong-vn','PSA',22,17,null,$b$Gâp dơi kơp lĕ rngôch nting gâp Phung rlăng đah gâp uănh gâp jêh ri sŏt măt ma gâp.$b$,true),
('bunong-vn','PSA',22,18,null,$b$Khân păng tâm pă ndrăng khân păng nơm bok ao gâp. Jêh ri khân păng ƀư tâm nchroh ma ao jâr gâp.$b$,true),
('bunong-vn','PSA',22,19,null,$b$Ƀiă lah lơi ta gŭ ngai ôh đah gâp, ơ Yêhôva Nau Brah May jêng ktang, koh dŏng gâp gơnh$b$,true),
('bunong-vn','PSA',22,20,null,$b$King an huêng gâp bơh đao gưm, Nau rêh gâp bơh phung so.$b$,false),
('bunong-vn','PSA',22,21,null,$b$Rklaih an gâp bơh trôm mbung yau mŭr, Bơh nke phung rpu bri, May hŏ tăng jêh bâr gâp.$b$,true),
('bunong-vn','PSA',22,22,null,$b$Gâp mra mbơh amoh May ma phung oh nâu gâp Tâm rnê ma Brah Ndu tâm nklang phung gŭ rƀŭn$b$,true),
('bunong-vn','PSA',22,23,null,$b$Khân may klach mbah yơk ma Yêhôva, tâm rnê hom ma Păng Lĕ rngôch khân may jêng kon sau Yakôb, ăn nau chrêk rmah ma păng Râm sâr hom ta năp măt păng, lĕ rngôch phung kon sau Israel.$b$,false),
('bunong-vn','PSA',22,24,null,$b$Yor lah păng mâu mâp tâm rmot mâu lah ƀư ƀơ̆ ma nau jêr phung rêh ni ôh, Păng mâu mâp pôn măt ma khân păng ôh Ƀiă lah păng gŭ iăt tơ lah bu nter ma păng$b$,true),
('bunong-vn','PSA',22,25,null,$b$Tâm nau rƀŭn toyh May mra jêng Nơm gâp tâm rnê. Gâp mra ƀư ăn jêh nau gâp ton ta năp phung klach yơk ma păng$b$,false),
('bunong-vn','PSA',22,26,null,$b$Phung blau tông bâr mra sông sa, jêh ri khân păng mra hơm, phung joi Yêhôva mra tâm rnê ma Păng Ăn nuih n'hâm khân may gŭ rêh ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','PSA',22,27,null,$b$Lĕ puăn njônh bri mra plơ̆ kah gĭt ma Yêhôva Lĕ rngôch mpôl bunuyh mra chon mon mbah ta năp May$b$,true),
('bunong-vn','PSA',22,28,null,$b$Yor lah ƀon bri hađăch jêng ndơ Yêhôva păng chiă uănh phung mpôl băl bunuyh.$b$,false),
('bunong-vn','PSA',22,29,null,$b$Lĕ rngôch phung toyh ta neh ntu mra sông sa jêh ri mra chon mon mbah lĕ Lĕ rngôch phung jur tâm neh rmuy mra chon mon mbah ta năp Păng$b$,true),
('bunong-vn','PSA',22,30,null,$b$Phung kon sau mra pah kan ma Păng Bu mra kơp khân păng jêng kon sau Kôranh Brah$b$,false),
('bunong-vn','PSA',22,31,null,$b$Kon sau nây mra tât nsong mbơh nau ueh lăng Păng Mbơh ma bunuyh ƀon lan jêh ri kan Păng mra deh.$b$,false),
('bunong-vn','PSA',23,1,null,$b$Kôranh Brah jêng rmăk gâp, gâp mâu hôm pưt mpa ôh$b$,true),
('bunong-vn','PSA',23,2,null,$b$Păng ăn gâp rlu tâm ndrêch gơ̆ nse. Păng njŭn gâp tâm tu dak rngân đăp mpăn.$b$,false),
('bunong-vn','PSA',23,3,null,$b$Păng ăn gâp sĭt n'hâm suan Păng leo gâp hăn di trong, tĭng nâu nau Păng hŏ ton jêh.$b$,true),
('bunong-vn','PSA',23,4,null,$b$Nđâp tơ lah gâp hăn tâm rlŭng nau khĭt, gâp mâu hôm klach du ntil nau mhĭk ôh. Yor lah May gŭ ndrel ma gâp. May rgong gâp ma mâng jra, n'gang gâp ma mâng kanuăk.$b$,true),
('bunong-vn','PSA',23,5,null,$b$May nkra sưng sông sa ma gâp tă năp phung rlăng gâp. May rom gâp, May tŏ dak ƀâu ta sŏk gâp, May kêt âk dak ma kachok kŏ bêng ler, ăn gâp nhêt$b$,true),
('bunong-vn','PSA',23,6,null,$b$N'hêl nanê̆ nau ueh jêh ri nau yô̆ tă bơh kôranh Brah tĭng ndô̆ gâp ƀa ƀơ lĕ rngôch nar gâp gŭ rêh, jêh ri ngih Păng gŭ jêng ntŭk gâp gŭ n'ho ro.$b$,false),
('bunong-vn','PSA',24,1,null,$b$Neh jêh ri mpô mpa klơ neh, Neh ntu jêh ri lĕ rngôch mbu nâm gŭ tâm nây jêng ndơ Yêhôva da dê.$b$,true),
('bunong-vn','PSA',24,2,null,$b$Yor lah Păng yơh bŏl neh ta klơ dak rlai Jêh ri ăn păng nâp ta klơ lĕ dak toyh,$b$,true),
('bunong-vn','PSA',24,3,null,$b$Mbu mra hao ta yôk Yêhôva? Jêh ri mbu nâm mra dơi gŭ ngao tâm ntŭk kloh ueh Păng?$b$,false),
('bunong-vn','PSA',24,4,null,$b$Nơm geh ti jêh ri nuih n'hâm kloh Nơm mâu jao huêng păng ma nau mƀruh. Mâu lĕ ton săk ma nau mƀruh.$b$,true),
('bunong-vn','PSA',24,5,null,$b$Păng mra geh nau ueh lăng tă bơh Yêhôva Jêh ri nau sŏng srăng tă bơh Brah Ndu, nau tâm rklaih păng$b$,true),
('bunong-vn','PSA',24,6,null,$b$Tâm ban pô aơ jêng phung joi Păng, Phung joi muh măt Brah Ndu Yakôb.$b$,false),
('bunong-vn','PSA',24,7,null,$b$Ơ phung mpông pêr, ngơk hom bôk Ơ phung mpông pêr n'ho ro, pơk ăn prêh, Gay ma hađăch chrêk rmah mra lăp.$b$,true),
('bunong-vn','PSA',24,8,null,$b$Mbu jêng hađăch chrêk rmah aơ Aơ jêng Yêhôva, Nơm ktang Nơm brah Yêhôva ktang tâm nau tâm lơh$b$,true),
('bunong-vn','PSA',24,9,null,$b$Ơ phung mpông pêr, yơk hom bôk! Ơ mpông pêr n'ho ro, pơk hom ăn prêh, Gay ma hađăch chrêk rmah mra lăp$b$,false),
('bunong-vn','PSA',24,10,null,$b$Mbu jêng hađăch chrêk rmah aơ? Aơ jêng Yêhôva tahan âk Păng yơh jêng hađăch chrêk rmah.$b$,false),
('bunong-vn','PSA',25,1,null,$b$Ơ Yêhôva, gâp nhhơr huêng gâp ma May$b$,true),
('bunong-vn','PSA',25,2,null,$b$Ơ Brah Ndu gâp, gâp rnơm ma May Lơi ăn gâp prêng ôh, Lơi ăn phung rlăng dơi đah gâp.$b$,false),
('bunong-vn','PSA',25,3,null,$b$Mâu geh du huê nơm tâm phung rnơm ma May mra prêng$b$,true),
('bunong-vn','PSA',25,4,null,$b$Ơ Yêhôva, ăn gâp gĭt trong May, Sâm nti an gâp tâm trong May$b$,false),
('bunong-vn','PSA',25,5,null,$b$Gai gâp tâm nau nanê̆, jêh ri sâm nti an gâp, Yor lah May jêng Brah Ndu rklaih gâp Gâp kâp May ăp nar ƀa ƀơ.$b$,false),
('bunong-vn','PSA',25,6,null,$b$Ơ Yêhôva, ăn May kah gĭt ma nau May yô̆ jêh ri ma nau ueh May. Yor lah bar ntil nau nây geh ơm bơh kăl e.$b$,true),
('bunong-vn','PSA',25,7,null,$b$Lơi ta May kah gĭt ma nau tih gâp, dôl hôm ndăm, nâu lah nđâp ma nau kue gâp Ơ Yêhôva yô̆ an ma gâp tĭng nâm nau May yô̆, yor nau ueh May$b$,true),
('bunong-vn','PSA',25,8,null,$b$Yêhôva jêng ueh jêh ri sŏng Yor nây Păng mra sâm nti phung tĭng trong Păng.$b$,false),
('bunong-vn','PSA',25,9,null,$b$Păng njŭn leo phung tông bâr tâm trong sŏng; Păng sâm nti phung tông bâr tâm trong Păng.$b$,true),
('bunong-vn','PSA',25,10,null,$b$Lĕ rngôch trong Yêhôva jêng nau ueh jêh ri nau nanê̆Ma phung ndjôt prăp tâm rnglăp jêh ri nau phung mbơh.$b$,true),
('bunong-vn','PSA',25,11,null,$b$Yor amoh May, Ơ Yêhôva, yô̆ an ma nau kue gâp, yor lah păng toyh.$b$,true),
('bunong-vn','PSA',25,12,null,$b$Mbu nâm klach mbah yơk ma Yêhôva? Yêhôva mra nti nơm nây tâm trong păng mra săch.$b$,true),
('bunong-vn','PSA',25,13,null,$b$Huêng srĭng păng mra gŭ tâm ntŭk đăp mpăn Jêh ri phung kon sau păng mra krâm neh ntu$b$,true),
('bunong-vn','PSA',25,14,null,$b$Nau ndâp Yêhôva gŭ ndrel ma phung klach mbah yơk ma Păng Ăn khân păng gĭt nau tâm rnglăp$b$,false),
('bunong-vn','PSA',25,15,null,$b$Măt gâp uănh ƀa ƀơ mpeh ma Yêhôva. Yor Păng mra tĭt jâng gâp tă bơh jal$b$,false),
('bunong-vn','PSA',25,16,null,$b$Uănh ta gâp jêh ri yô̆ nđach an gâp. Yor lah bu cha lơi gâp jêh, jêh ri gâp jêng rêh ni$b$,false),
('bunong-vn','PSA',25,17,null,$b$Nau uh ah tâm nuih n'hâm gâp ƀrư̆ nar ƀrư̆ âk Sâm rklaih an gâp bơh nau rngot$b$,false),
('bunong-vn','PSA',25,18,null,$b$Sek uănh nau rêh ni gâp jêh ri nau jêr gâp; Jêh ri yô̆ an ma lĕ rngôch nau tih gâp$b$,false),
('bunong-vn','PSA',25,19,null,$b$Sek phung rlăng đah gâp, yor lah khân păng âk ngăn Jêh ri khân păng tâm rmot ma gâp hâu ngăn$b$,false),
('bunong-vn','PSA',25,20,null,$b$Chiă uănh huêng gâp jêh ri rklaih an gâp Lơi ăn gâp bêk prêng ôh yor lah gâp krap tâm May.$b$,false),
('bunong-vn','PSA',25,21,null,$b$Ăn nau sŏng jêh ri nau sŏng srăng king gâp Yor lah gâp rnơm ma May$b$,true),
('bunong-vn','PSA',25,22,null,$b$Ơ Brah Ndu. Tâm chuai phung Israel, bơh lĕ nau rngot păng Y-Đavit Mbơh Nau Sŏng Srăng Jêh Ri Mbơh Sơm Ma Nau N'gang Nau mprơ ơm Y-Đavit$b$,false),
('bunong-vn','PSA',26,1,null,$b$Phat hom dôih gâp, Ơ Yêhôva, yor lah gâp hăn tâm nau sŏng. Gâp rnơm ma Yêhôva, gâp mâu chêh prah ôh$b$,true),
('bunong-vn','PSA',26,2,null,$b$Ơ Yêhôva, dăn May sek uănh jêh ri long uănh gâp. Ntĭm nti an nuih n'hâm gâp.$b$,false),
('bunong-vn','PSA',26,3,null,$b$Yor nau ueh lăng May gŭ jêh ta năp măt gâp Jêh ri gâp hăn tâm trong nanê̆ May$b$,true),
('bunong-vn','PSA',26,4,null,$b$Gâp mâu gŭ ndrel ma phung mƀruh ôh, mâu lĕ hăn ndrel ma phung nuih n'hâm mŭr$b$,false),
('bunong-vn','PSA',26,5,null,$b$Gâp tâm rmot ma phung ƀư mhĭk Mâu ŭch gŭ ndrel ma phung hăt janh$b$,false),
('bunong-vn','PSA',26,6,null,$b$Ơ Yêhôva, gâp mra rao ti gâp tâm nau kloh, Gâp mra ndăch jum nơng ƀư brah May.$b$,false),
('bunong-vn','PSA',26,7,null,$b$Gay ma ăn bu tăng bâr gâp tâm rnê, Jêh ri nkoch bri lĕ nau khlay May.$b$,true),
('bunong-vn','PSA',26,8,null,$b$Ơ Yêhôva gâp rŏng gŭ tâm ntŭk May vay gŭ Jêh ri ntŭk chrêk rmah May$b$,true),
('bunong-vn','PSA',26,9,null,$b$Ơ Yêhôva lơi may ăn huêng gâp gŭ ndrel ma phung tih. Mâu lĕ may njŭn nau rêh gâp ndrel ma phung rung mham$b$,false),
('bunong-vn','PSA',26,10,null,$b$Ti khân păng ndjôt nau ƀai Jêh ri ti ma khân păng bêng ma prăk bu nkhôm$b$,false),
('bunong-vn','PSA',26,11,null,$b$Ƀiă lah gâp, gâp mra hăn tâm trong nau kloh ueh Dăn may chuai an gâp, yô̆ an gâp ƀă$b$,false),
('bunong-vn','PSA',26,12,null,$b$Jâng gâp gŭ dâk nâp tâm ntŭk lâng; Gâp mra tâm rnê ma Yêhôva tâm mông tâm rƀŭn.$b$,false),
('bunong-vn','PSA',27,1,null,$b$Yêhôva jêng nau ang jêh ri nau tâm rklaih gâp Ma mbu hôm gâp klach? Yêhôva jêng pôm mbe nau rêh gâp Ma mbu hôm gâp klach?$b$,true),
('bunong-vn','PSA',27,2,null,$b$Tơ lah phung ƀai ƀư ŭch sa hêk rvăn nglay săk gâp Khân păng mra văk jâng prah$b$,true),
('bunong-vn','PSA',27,3,null,$b$Nđâp tơ lah du phung tahan nchueng jum gâp Nuih n'hâm gâp mâu mra klach ôh Nđâp tơ lah nau tâm lơh tât ma gâp, Ăt gâp geh nau rnơm lĕ nâp rjăp$b$,false),
('bunong-vn','PSA',27,4,null,$b$Gâp dăn ma Yêhôva du ntil nau, jêh ri mra joi nau nây! Jêng nau gŭ tâm ngih Yêhôva, Gay uănh nau ueh maak tă bơh Yêhôva jêh ri gay mĭn ma ngih brah Păng$b$,false),
('bunong-vn','PSA',27,5,null,$b$Yor lah tâm nar rêh ni, Păng mra ăn gâp krap tâm ngih bok Păng. Păng mra pôn gâp ăn ndâp tâm ngih bok Păng Păng mra chông gâp ta klơ lŭ prêh.$b$,false),
('bunong-vn','PSA',27,6,null,$b$Aƀaơ Păng chông bôk gâp ta klơ phung rlăng gŭ jum gâp; Jêh ri gâp mra nhhơr ndơ ƀư brah tâm ngih bok Păng, ma nau nter răm rhơn Gâp mra mprơ, nanê̆ gâp mra mprơ tâm rnê ma Yêhôva$b$,true),
('bunong-vn','PSA',27,7,null,$b$Ơ Yêhôva dăn May iăt bâr gâp, gâp kuăl mbơh sơm ma May; Yô̆ nđach an ma gâp, jêh ri lŏ plơ̆ lah an ma gâp.$b$,false),
('bunong-vn','PSA',27,8,null,$b$Tơ lah May lah, joi hom muh măt gâp, Gâp mra joi muh măt May, Ơ Yêhôva$b$,true),
('bunong-vn','PSA',27,9,null,$b$Ơ Kôranh Brah Ndu, nơm rklaih gâp, Lơi ta pôn măt May ma gâp Lơi ta May mprơh oh mon May ma nau nuih janh ôh May jêng nơm kơl gâp, lơi ta mƀăr lơi gâp$b$,false),
('bunong-vn','PSA',27,10,null,$b$Tơ lah mbơ̆ me gâp cha lơi gâp, Yêhôva mra rom gâp,$b$,false),
('bunong-vn','PSA',27,11,null,$b$Ơ Yêhôva, ntĭm nti an gâp ma trong sŏng May Njŭn leo an gâp tâm trong sŏng srăng$b$,false),
('bunong-vn','PSA',27,12,null,$b$Lơi ta jao gâp ma phung rlăng ôh Yor lah phung nchơt dâk phong gâp, Phung bunuyh thăm ma nau ƀai$b$,false),
('bunong-vn','PSA',27,13,null,$b$Ơ! Tơ lah gâp mâu chroh ôh mra saơ nau ueh Yêhôva tâm neh phung rêh, gâp mra khĭt huăr yơh.$b$,false),
('bunong-vn','PSA',27,14,null,$b$Kâp gân hom ma Yêhôva Ăn nuih n'hâm nâp rjăp! Ăn dơi, kâp gân Yêhôva.$b$,true),
('bunong-vn','PSA',28,1,null,$b$Ơ Yêhôva, gâp nter vơh vơl ma May, Ơ lŭ gâp, lơi ta sêt tôr gâp Klach lah May ƀư rngêl đah gâp Gâp mra jêng tâm ban ma phung jur tâm ntu jru.$b$,true),
('bunong-vn','PSA',28,2,null,$b$Tơ lah gâp yơr ti mpeh pa May, gay ma dăn ma May Iăt hom bâr gâp kuăl vơh vơl ma May.$b$,true),
('bunong-vn','PSA',28,3,null,$b$Lơi ta May mprơh gâp du ndrel ma phung rlăng Mâu lah phung ƀư djơh, Phung pah kan ma nau kue, Khân păng ngơi ma nau đăp mpăn đah phung chiau meng khân păng. Ƀiă lah nau ndơm gŭ tâm nuih n'hâm khân păng$b$,true),
('bunong-vn','PSA',28,4,null,$b$Ăn May mplơ̆ lơi tĭng nâm nau khân păng ƀư ƀai, janh ktang Tâm rmal khân păng tĭng nâm kan khân păng hŏ ƀư Mplơ̆ lơi moh nau khư ma khân păng.$b$,false),
('bunong-vn','PSA',28,5,null,$b$Yor lah khân păng mâu chrê ôh ma Yêhôva Mâu păng chrê lĕ ma kan ti Kôranh Brah ƀư Yêhôva mra n'glưh lơi khân păng Mâu hôm rdâk khân păng ôh.$b$,true),
('bunong-vn','PSA',28,6,null,$b$Mât ton tâm rnê ma Yêhôva Yor Păng hŏ tăng jêh nau bâr gâp kuăl vơh vơl$b$,true),
('bunong-vn','PSA',28,7,null,$b$Yêhôva jêng nau ktang gâp jêh ri khêl gâp nuih n'hâm gâp mra nsing rnơm ma Păng jêh ri gâp mra dơi geh nau kơl. Yor ri nuih n'hâm gâp geh nau răm maak ngăn jêh ri gâp mra tâm rnê ma Păng ma nau mprơ$b$,false),
('bunong-vn','PSA',28,8,null,$b$Brah Yêhôva jêng n'hâm toyh suan dăng ma ƀon lan Păng Păng jêng pôih n'gang nau tâm rklaih ma nơm Păng troch jêh dak ngi$b$,false),
('bunong-vn','PSA',28,9,null,$b$Tâm rklaih hom ƀon lan May jêh ri ăn nau ueh lăng ma phung krâm drăp ndơ May. Ăn May jêng rmăk biăp ma khân păng, jêh ri kuăn rdâng khân păng ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','PSA',29,1,null,$b$Ơ phung kon Brah Ndu. Ăn yơk mbah nau chrêk rmah Yêhôva Jêh ri ăn khư nau dơi ma amoh Păng$b$,true),
('bunong-vn','PSA',29,2,null,$b$Mbah yơk ma Yêhôva chrêk rmah khư ma amoh Păng Soh nkrơ̆ ma nau kloh ueh gay ma yơk mbah ma Yêhôva$b$,false),
('bunong-vn','PSA',29,3,null,$b$Bâr Yêhôva tăng ntoh ta klơ dak Brah Yêhôva chrêk rmah tâm ban ma lơp nglaih rdah, Yêhôva yơh gŭ ta klơ dak jru.$b$,false),
('bunong-vn','PSA',29,4,null,$b$Bâr Yêhôva ktang ngăn; Bâr Yêhôva geh nau n'gôr nau brah chrêk rmah.$b$,true),
('bunong-vn','PSA',29,5,null,$b$Bâr Yêhôva dơi ƀư rai tơm si Sêdrơ Yêhôva yơh ƀư rai tơm si Sêdrơ tâm n'gor Liban,$b$,true),
('bunong-vn','PSA',29,6,null,$b$Kôranh Brah ƀư păng nsăt rlau nâm bu du mlâm ndrôk kon, Liban jêh ri Syri, nsăt nâm bu ndrôk bri$b$,false),
('bunong-vn','PSA',29,7,null,$b$Bâr Yêhôva dơi ngluh lơi mpiăt ŭnh$b$,false),
('bunong-vn','PSA',29,8,null,$b$Bâr Yêhôva ƀư, sâr n'gơ bri rdah Yêhôva ƀư ăn bri rdah sâr n'gơ Yêhôva ƀư an bri Kadês sâr n'gơ$b$,false),
('bunong-vn','PSA',29,9,null,$b$Bâr Yêhôva ăn jun me deh kon Păng plôk hil lĕ bri neh. Tâm ngih Brah Păng lĕ rngôch nter lah, Nau chrêk rmah$b$,false),
('bunong-vn','PSA',29,10,null,$b$Yêhôva gŭ klơ mpiăt dak lip. Yêhôva yơh dơi jêng hađăch n'ho ro$b$,false),
('bunong-vn','PSA',29,11,null,$b$Yêhôva mra ăn n'hâm toyh, suan dăng jêh ri mâu đăp mpăn ma phung ƀon lan Păng.$b$,false),
('bunong-vn','PSA',30,1,null,$b$Ơ Kôranh Brah Yêhôva gâp yơk mbah ma May, yor lah May yơk nhhơ gâp jêh. May mâu ăn phung rlăng geh nau răm maak yor gâp$b$,true),
('bunong-vn','PSA',30,2,null,$b$Ơ Yêhôva Brah Ndu gâp, Gâp dăn vơh vơl ma may, yor May ƀư bah gâp jêh.$b$,false),
('bunong-vn','PSA',30,3,null,$b$Ơ Yêhôva, May hŏ rklaih an gâp tă bơh brŏng nau khĭt. Mât mơh ăn huêng gâp, mâu ăn gâp tŭp tâm brŏng jru$b$,true),
('bunong-vn','PSA',30,4,null,$b$Ơ phung ƀon ueh mprơ tâm rnê hom ma Yêhôva Jêh ri kah gĭt tôr tơ lah Păng ƀư nau kah gĭt ma nau kloh ueh Păng.$b$,false),
('bunong-vn','PSA',30,5,null,$b$Yor lah nau Păng nuih knŏng ƀât lât. Ƀiă lah nau Păng yô̆ gŭ jŏ jong tâm nau bu gŭ rêh. Nau nhĭm nhhiăng geh knŏng tâm măng, Ƀiă lah tât an tâm măng, Ƀiă lah târ ang ôi geh nau maak.$b$,true),
('bunong-vn','PSA',30,6,null,$b$Bi gâp dôl geh nau ƀun lap gâp lah pô aơ; Gâp mâu mra mpât n'gơ ôh.$b$,true),
('bunong-vn','PSA',30,7,null,$b$Ơ Yêhôva, yor nau May ƀư ueh gâp dơi gŭ nâp ta yôk gâp. May pôn măt May, gâp geh nau uh ah$b$,true),
('bunong-vn','PSA',30,8,null,$b$Ơ Yêhôva gâp hŏ kuăl vơh vơl ma May$b$,false),
('bunong-vn','PSA',30,9,null,$b$Moh nau khlay geh tâm mham gâp, lah jêh gâp jur tâm môch. Ndruyh neh mra mât ton ma May lĕ, păng mra mbơh nau nanê̆ May lĕ?$b$,false),
('bunong-vn','PSA',30,10,null,$b$Ơ Yêhôva, dăn May iăt jêh ri yô̆ an gâp ƀă. Ơ Yêhôva, văch kơl hom gâp.$b$,true),
('bunong-vn','PSA',30,11,null,$b$May tâm rgâl jêh nau gâp klân ndrê jêng nau gâp kadŏ May doh jêh ao gâp soh jêh ri May vân gâp ma nau răm rhơn.$b$,true),
('bunong-vn','PSA',30,12,null,$b$Gay ma nuih n'hâm gâp mprơ ma nau tâm rnê ma May jêh ri mâu gŭ rklăk ôh Ơ Yêhôva Brah Ndu gâp, gâp mra tâm rnê ma May ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',31,1,null,$b$Ơ Yêhôva, gâp mra krap tâm may. Lơi ăn gâp mâp nau bêk prêng. Tâm rklaih an gâp ma nau sŏng srăng may.$b$,true),
('bunong-vn','PSA',31,2,null,$b$Rkêng tôr may ma gâp, may gơnh rklaih gâp Ƀư ăn jêng du mlâm lŭ nâp Jêng ntŭk gay ma rklaih gâp.$b$,true),
('bunong-vn','PSA',31,3,null,$b$Yor lah Kôranh Brah jêng lŭ jêh ri pôih n'gang gâp. Yor ma amoh may, njŭn leo gâp.$b$,true),
('bunong-vn','PSA',31,4,null,$b$Đŏt lơi gâp bơh pôih bu sân jêh ma gâp Yor lah may jêng ntŭk king gâp.$b$,true),
('bunong-vn','PSA',31,5,null,$b$Gâp jao huêng gâp tâm ti may Ơ Yêhôva, may hŏ chuai gâp jêh, Brah Ndu nau nanê̆.$b$,true),
('bunong-vn','PSA',31,6,null,$b$Gâp tâm rmot ma phung mbah ma rup brah mâu khlay. Ƀiă lah gâp rnơm ma Yêhôva$b$,true),
('bunong-vn','PSA',31,7,null,$b$Yor nau ueh may gâp mra bêng ma nau răm maak. Yor may hŏ saơ jêh nau rêh ni gâp may hŏ năl jêh nau rngot huêng gâp.$b$,false),
('bunong-vn','PSA',31,8,null,$b$May mâu jao gâp tâm ti nơm rlăng ôh may dơm jêh jâng gâp tâm ntŭk huy$b$,true),
('bunong-vn','PSA',31,9,null,$b$Ơ Yêhôva yô̆ an gâp ƀă, yor lah gâp gŭ tâm nau rngot. Măt huêng jêh ri săk jăn gâp klêu ma nau rngot$b$,false),
('bunong-vn','PSA',31,10,null,$b$Yor lah nau rêh gâp roh huach tâm nau rngot klâng. Lĕ năm gâp huch yor nter vơh vơl Nau srôih gâp lĕ jêh yor nau kue Jêh ri nting nđăng gâp lĕ lêk rai$b$,false),
('bunong-vn','PSA',31,11,null,$b$Yor ma lĕ rngôch phung rlăng đah gâp Gâp jêng ndơ bu bêk prêng Nau tâm nkrit đah phung băl gâp; Bu nâm saơ gâp pa dih, du ăn ngai đah gâp.$b$,false),
('bunong-vn','PSA',31,12,null,$b$Bu chuêl gâp tâm ban ma du huê bunuyh khĭt, mâu hôm kah gĭt. Gâp jêng tâm ban ma du play yăng chah.$b$,true),
('bunong-vn','PSA',31,13,null,$b$Yor lah gâp tăng jêh âk bunuyh ngơi nchơt Nau krit gŭ jum gâp; Dôl khân păng tâm nchră ƀư rlăng đah gâp Khân păng ŭch ngroh lơi nau rêh gâp.$b$,true),
('bunong-vn','PSA',31,14,null,$b$Ƀiă lah gâp rnơm ma may yơh, Ơ Yêhôva Gâp lah: May jêng Brah Ndu gâp.$b$,true),
('bunong-vn','PSA',31,15,null,$b$Nau rêh gâp gŭ tâm ti Kôranh Brah. Tâm rklaih gâp bơh phung rlăng jêh ri phung ƀư ƀai ma gâp.$b$,true),
('bunong-vn','PSA',31,16,null,$b$Ăn muh măt may sol ang ta oh mon may. Tâm rklaih gâp ma nau ueh may.$b$,true),
('bunong-vn','PSA',31,17,null,$b$Ơ Yêhôva, lơi ăn bu ƀư bêk gâp ôh, yor lah gâp mbơh sơm ma may jêh Ăn bu ƀư bêk phung ƀai, ăn khân păng gŭ rklăk tâm ban phung khĭt.$b$,true),
('bunong-vn','PSA',31,18,null,$b$Ăn mbung phung mƀruh jêng mlo Ma nau mhĭk khân păng ngơi tâm rdâng đah phung sŏng Ăn jêng mlo hom.$b$,true),
('bunong-vn','PSA',31,19,null,$b$Nau amoh khlay may toyh ngăn Prăp jêh ma phung klach mbah yơk ma may. Ƀư ta năp măt phung mpôl băl kon bunuyh Nau may ƀư ma phung du krap tâm may.$b$,true),
('bunong-vn','PSA',31,20,null,$b$May mra pôn khân păng ăn ndâp tâm ntŭk may gŭ ta năp măt Brah may, ăn bah ngai đah nau rlăng phung kon bunuyh. May mra pôn khân păng tâm ngih bok ma phung mpiăt tâm djel.$b$,true),
('bunong-vn','PSA',31,21,null,$b$Mât ton ma Yêhôva; Yor lah Păng tâm mpơl jêh ma gâp nau ueh khlay Păng tâm du rplay ƀon toyh nâp rjăp$b$,true),
('bunong-vn','PSA',31,22,null,$b$Tâm nau gâp mâu mĭn gâp lah pô aơ; Bu koh jêh gâp ta năp măt may Ƀiă lah tơ lah gâp kuăl vơh vơl ma may may hŏ tăng jêh nau gâp dăn$b$,false),
('bunong-vn','PSA',31,23,null,$b$Rŏng hom ma Yêhôva, ơ lĕ rngôch khân may Phung kloh ueh Păng Yêhôva mât mơh phung vay răp jăp Jêh ri Păng tâm rmal ktang ngăn phung sưr rlau$b$,false),
('bunong-vn','PSA',31,24,null,$b$Ƀư ktang hom khân may jêh ri ăn nuih n'hâm khân may gŭ rjăp Ơ lĕ rngôch phung khân may geh nau rnơm ma Yêhôva. Ăn khân may geh nuih n'hâm nâp rjăp.$b$,false),
('bunong-vn','PSA',32,1,null,$b$Ueh maak yơh ma nơm geh nau yô̆ an ma nau păng rlau nau vay. Ma nơm bu nkŭm an jêh nau tih păng$b$,true),
('bunong-vn','PSA',32,2,null,$b$Ueh maak yơh ma nơm Yêhôva mâu kơp ôh nau kue păng, Jêh ri tâm huêng nơm nây mâu geh nau ndơm ôh.$b$,false),
('bunong-vn','PSA',32,3,null,$b$Dôl gâp gŭ rklăk, nting gâp jêng rai Jêh ri gâp nter nar măng;$b$,true),
('bunong-vn','PSA',32,4,null,$b$Yor lah măng nâm nar ti may n'grŭn jâk gâp Nau nsrôih gâp jêng sơh tâm ban ma kăl vai (Sêla)$b$,false),
('bunong-vn','PSA',32,5,null,$b$Gâp mbơh jêh nau tih gâp ma may Gâp mâu pôn mo nau mhĭk gâp ôh; Gâp lah: Gâp mra mbơh nau gâp rlau nau vay Yêhôva; Jêh ri may yô̆ an jêh nau kue ma nau tih gâp (Sêla)$b$,false),
('bunong-vn','PSA',32,6,null,$b$Yor nây ăn lĕ rngôch blau yơk, mbơh sơm ta mông bu dơi tâm mâp đah may; Nanê̆ tơ lah dak toyh ler, dak nây mâu mra tât ma păng ôh.$b$,false),
('bunong-vn','PSA',32,7,null,$b$May jêng ntŭk gâp mbe: May n'gang gâp bơh nau djơh mhĭk may ăn nau mprơ ma nau tâm rklaih gŭ jum gâp. (Sêla)$b$,true),
('bunong-vn','PSA',32,8,null,$b$Gâp mra nti may jêh ri ntĭm ma may trong may mra tĭng ndô̆. Măt Gâp mra treng ta may tâm nau nti lah may.$b$,false),
('bunong-vn','PSA',32,9,null,$b$Lơi ta ăn may jêng nâm bu du mlâm seh, mâu lah seh bri mâu geh nau gĭt rbăng Bu nsro trôm mbung ma loih khưp jêh ri ma gang, gay ma păng dơi iăt nau. Tơ lah mâu ƀư pô nây, khân păng mâu mra hăn dăch may ôh.$b$,true),
('bunong-vn','PSA',32,10,null,$b$Âk nau rngot mra tŭp tâm phung ƀai; Ƀiă lah mbu nâm rnơm ma Yêhôva, mra geh nau maak gŭ jum păng$b$,true),
('bunong-vn','PSA',32,11,null,$b$Ơ Phung sŏng, răm rhơn hom khân may tâm Yêhôva, răm rhơn hom khân may; Nter maak hom, lĕ rngôch khân may geh nuih n'hâm sŏng.$b$,false),
('bunong-vn','PSA',33,1,null,$b$Ơ Phung sŏng, maak hom khân may tâm Yêhôva Nau mât ton tâm rnê di ma phung bunuyh sŏng$b$,true),
('bunong-vn','PSA',33,2,null,$b$Mprơ tâm rnê hom ma Yêhôva ma nau mât ton Dŏng gong rêng jât rse mprơ tâm rnê hom ma Păng.$b$,false),
('bunong-vn','PSA',33,3,null,$b$Mprơ tâm rnê ma Păng du ntil nau mprơ mhe Ăn khân may kreh dĭng khân may ma nau Săr lah jêh ri ăn nteh huy$b$,true),
('bunong-vn','PSA',33,4,null,$b$Yor lah nau Yêhôva ngơi jêng sŏng Lĕ kan Păng jêng nau nanê̆ ngăn$b$,false),
('bunong-vn','PSA',33,5,null,$b$Păng rŏng nau sŏng jêh ri nau di Nau ueh Yêhôva lam neh ntu$b$,false),
('bunong-vn','PSA',33,6,null,$b$Yêhôva rhăk trôk ma nau Păng ngơi Lĕ gưl trôk dơi jêng tă luh bơh n'hâm mbung bâr Păng$b$,false),
('bunong-vn','PSA',33,7,null,$b$Păng rgum lĕ dak rlai jêng dak sial njach ryă Păng ăn dak jru nsŭn du ntŭk.$b$,false),
('bunong-vn','PSA',33,8,null,$b$Ăn lĕ rngôch neh ntu klach ma Yêhôva. Ăn lĕ rngôch bunuyh ta neh ntu klach mbah yơk ma Yêhôva.$b$,true),
('bunong-vn','PSA',33,9,null,$b$Yor lah mâm nau Păng ngơi, jêng da dê ro. Mâm nau Păng ntăm mra jêng nâp rjăp ngăn.$b$,true),
('bunong-vn','PSA',33,10,null,$b$Yêhôva ƀư rai lĕ nau mhĭk neh ntu Păng ăn nau phung ƀon lan mĭn jêng dơm dam Nau mĭn, Yêhôva dơi nâp rjăp n'ho ro. Nuih n'hâm Păng mĭn gŭ n'ho ro ăp rnôk.$b$,true),
('bunong-vn','PSA',33,11,null,$b$Ƀiă lah nau Yêhôva blau mĭn gŭ nâp n'ho ro. Nau nuih n'hâm Păng mĭn gŭ tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','PSA',33,12,null,$b$Ueh maak yơh mpôl băl geh Yêhôva jêng Brah Ndu Ueh maak yơh ƀon lan Păng săch jêh, jêng drăp ndơ Păng krâm$b$,true),
('bunong-vn','PSA',33,13,null,$b$Yêhôva nchrâng uănh tă bơh klơ trôk. Păng saơ lĕ rngôch kon bunuyh.$b$,false),
('bunong-vn','PSA',33,14,null,$b$Păng sek uănh tă bơh ntŭk păng gŭ Lĕ rngôch phung gŭ ta neh ntu.$b$,true),
('bunong-vn','PSA',33,15,null,$b$Păng yơh njêng nuih n'hâm ăp nơm khân păng Jêh ri Păng sek uănh lĕ rngôch kan khân păng.$b$,true),
('bunong-vn','PSA',33,16,null,$b$Mâu geh ôh du huê hađăch geh nau tâm rklaih Yor Păng geh ka han âk. Du huê bunuyh ktang mâu dơi geh nau tâm rklaih yor nau ktang păng ôh.$b$,true),
('bunong-vn','PSA',33,17,null,$b$Mbu nâm rnơm ma seh, nau nây jêng dơm dam, mâu dơi geh nau rnam ôh, mâu lĕ păng dơi tâm rklaih ma du huê yor nau ktang păng.$b$,true),
('bunong-vn','PSA',33,18,null,$b$Aơ, Yêhôva uănh măt ma phung klach mbah yơk ma Păng Ma phung blau rnơm ma nau ueh Păng$b$,true),
('bunong-vn','PSA',33,19,null,$b$Gay ma tâm rklaih huêng khân păng bơh nau khĭt Prăp nau rêh khân păng dôl nau sa sât ji ngot$b$,false),
('bunong-vn','PSA',33,20,null,$b$Huêng he kâp gân ma Yêhôva Păng jêng nơm kơl he jêh ri jêng khêl he.$b$,false),
('bunong-vn','PSA',33,21,null,$b$Tâm Păng yơh nuih n'hâm he geh nau răm maak. Yor lah he rnơm jêh tâm amoh kloh ueh Păng$b$,true),
('bunong-vn','PSA',33,22,null,$b$Ơ Yêhôva, ăn nau ueh May gŭ tâm hên Tĭng nâm hên kâp gân jêh ma May.$b$,false),
('bunong-vn','PSA',34,1,null,$b$Gâp mra tâm rnê ma Yêhôva mro mrăng Nau tâm rnê ma Păng gŭ tâm bâr mbung gâp ƀa ƀơ.$b$,true),
('bunong-vn','PSA',34,2,null,$b$Huêng gâp mra tâm rnê êng păng nơm tâm Yêhôva Phung tông bâr mra iăt nau nây jêh ri maak$b$,true),
('bunong-vn','PSA',34,3,null,$b$Ơ tâm rnê ma Yêhôva ndrel ma gâp. Ăn lĕ rngôch phung he ndrel n'grŭp tâm rnê ma amoh Păng.$b$,false),
('bunong-vn','PSA',34,4,null,$b$Gâp joi jêh Yêhôva, jêh ri Păng hŏ plơ̆ lah jêh ma gâp. Păng hŏ tâm rklaih jêh gâp bơh lĕ nau gâp klach$b$,true),
('bunong-vn','PSA',34,5,null,$b$Khân păng uănh n'gơr ma Kôranh Brah, muh măt khân păng mra sol ang. Jêh ri muh măt khân păng mâu mra prêng ôh.$b$,false),
('bunong-vn','PSA',34,6,null,$b$Du huê nơm rêh ni aơ nter Yêhôva tăng Jêh ri sâm rklaih an păng bơh lĕ rngôch nau rêh ni.$b$,true),
('bunong-vn','PSA',34,7,null,$b$Tông mpăr ueh Yêhôva gŭ jum phung klach yơk mbah ma Păng jêh ri tâm rklaih khân păng.$b$,true),
('bunong-vn','PSA',34,8,null,$b$Lep jêh ri saơ Yêhôva jêng ueh Ueh maak ngăn mbu nâm gŭ krap tâm Păng$b$,true),
('bunong-vn','PSA',34,9,null,$b$Ơ Phung kloh ueh Yêhôva, klach yơk mbah hom ma Păng. Yor lah bu nâm klach yơk mbah ma Păng mâu mra pưt ôh.$b$,false),
('bunong-vn','PSA',34,10,null,$b$Phung kon yau mŭr gĭt nau ât, jêh ri nau ji ngot Ƀiă lah phung joi Yêhôva, mâu mra pưt du ntil nau ueh ôh.$b$,true),
('bunong-vn','PSA',34,11,null,$b$Văch hom, ơ phung kon gâp, văch iăt hom nau gâp gâp mra nti phung kon gâp, nau blau klach mbah yơk ma Yêhôva.$b$,true),
('bunong-vn','PSA',34,12,null,$b$Mbu nâm rŏng ma nau rêh, Kâp gân gŭ rêh jŏ năm, gay ma dơi saơ nau ueh maak$b$,true),
('bunong-vn','PSA',34,13,null,$b$Njrăng mpiăt may, lơi ngơi djơh, Jêh ri mbung may lơi ngơi nau ndơm.$b$,false),
('bunong-vn','PSA',34,14,null,$b$Du hom may đah nau djơh jêh ri ƀư nau ueh. Tĭng joi jêh ri tĭng nau đăp mpăn.$b$,true),
('bunong-vn','PSA',34,15,null,$b$Măt Yêhôva treng uănh ma phung sŏng jêh ri trôm tôr Păng iăt bâr nter kuăl$b$,true),
('bunong-vn','PSA',34,16,null,$b$Muh măt păng ƀư rlăng đah phung ƀai Gay jut lơi nau bu dơi kah gĭt ma khân păng bơh neh ntu.$b$,false),
('bunong-vn','PSA',34,17,null,$b$Phung sŏng nter Yêhôva tăng, jêh ri tâm rklaih khân păng bơh lĕ nau rêh ni.$b$,true),
('bunong-vn','PSA',34,18,null,$b$Yêhôva gŭ dăch đah phung bunuyh geh nuih n'hâm hŏt rgănh. Jêh ri tâm rklaih phung geh huêng rngot ma nau tih$b$,true),
('bunong-vn','PSA',34,19,null,$b$Nơm sŏng geh âk nau rêh ni Ƀiă lah Yêhôva rklaih khân păng bơh nau khĭt$b$,false),
('bunong-vn','PSA',34,20,null,$b$Păng n'gang an lĕ nting nđăng khân păng Mâu geh du mlâm deh$b$,false),
('bunong-vn','PSA',34,21,null,$b$Nau ƀai mra nkhĭt nơm ƀai Jêh ri phung tâm rmot ma nơm sŏng mra dơn nau tâm rmal.$b$,false),
('bunong-vn','PSA',34,22,null,$b$Yêhôva tâm chuai huêng phung oh mon Păng. Jêh ri mâu geh du huê nơm du krap tâm Păng mra dơn nau tâm rmal.$b$,true),
('bunong-vn','PSA',35,1,null,$b$Ơ Yêhôva dăn May tâm rdâng đah phung vay tâm rdâng đah gâp. Ăn May tâm lơh đah phung vay tâm lơh đah gâp$b$,true),
('bunong-vn','PSA',35,2,null,$b$Dăn May djôt khêl jê̆ jêh ri toyh. Jêh ri dâk hom May kơl koh dŏng gâp$b$,false),
('bunong-vn','PSA',35,3,null,$b$Kâp rjăng ma tak May, king trong phung tĭng gâp lah ma huêng gâp, gâp jêng nau May tâm rklaih$b$,false),
('bunong-vn','PSA',35,4,null,$b$Ăn phung tĭng huêng gâp geh nau bêk prêng Ăn khân păng plơ̆ jêh ri tâm rlŭk nau mĭn phung ŭch ƀư ƀai ma gâp.$b$,false),
('bunong-vn','PSA',35,5,null,$b$Ăn khân păng jêng nâm bu lâk sial đô̆Jêh ri ăn tông mpăr ueh Yêhôva mprơh lơi khân păng.$b$,true),
('bunong-vn','PSA',35,6,null,$b$Ăn trong khân păng jêng ngo jêh ri mbĭr Jêh ri ăn phung Tông mpăr ueh Yêhôva tĭng khân păng$b$,true),
('bunong-vn','PSA',35,7,null,$b$Mâu geh nô nau ôh khân păng gŭ ta bâr ntu jru Mâu geh nô nau ôh khân păng kuyh ntu gay ma nklăch huêng gâp$b$,false),
('bunong-vn','PSA',35,8,null,$b$Ăn nau ƀư rai tât ma khân păng dôl khân păng mâu mĭn: Ăn khân păng geh văk nhuăl khân păng nơm sân Ăn păng tŭp tâm rnê jêh ri mra rai yot.$b$,false),
('bunong-vn','PSA',35,9,null,$b$Pô ri huêng gâp mra răm maak tâm Yêhôva Răm maak ngăn nau păng tâm rklaih,$b$,true),
('bunong-vn','PSA',35,10,null,$b$Lĕ nting nđăng gâp mra lah mbu nâm jêng tâm ban ma May? Nau mra rklaih ma phung rêh ni bơh phung ktang lơn ma păng. Nơm rêh ni jêh ri nơm o-ach bơh nơm sŏk pit ndơ khân păng$b$,false),
('bunong-vn','PSA',35,11,null,$b$Phung mbơh nau nchơt dâk: Khân păng tâm rmot ma nau gâp mâu gĭt$b$,false),
('bunong-vn','PSA',35,12,null,$b$Khân păng sŏk nau djơh ntrok nau ueh gâp hŏ ƀư jêh, Cha lơi huêng gâp gŭ êng$b$,false),
('bunong-vn','PSA',35,13,null,$b$Ƀiă lah gâp, tơ lah khân păng ji kuet gâp soh ao duêng. Gâp rngot huêng gâp ma nau ver sông sa Jêh ri nau gâp mbơh sơm plơ̆ sĭt ta ntang ntơh gâp.$b$,false),
('bunong-vn','PSA',35,14,null,$b$Gâp ƀư tâm ban ma khân păng jêng mĭt jiăng gâp mâu lah oh nâu gâp. Gâp jâk ma nau rngot ndrê tâm ban ma bu nhĭm klâng me păng.$b$,true),
('bunong-vn','PSA',35,15,null,$b$Ƀiă lah, tơ lah gâp prah, khân păng răm rhơn jêh ri tâm rƀŭn. Phung nchơt tâm rƀŭn ŭch ƀư ma gâp, ƀiă lah gâp mâu gĭt ôh. Khân păng sa hêk gâp, mâu geh rlu ôh.$b$,true),
('bunong-vn','PSA',35,16,null,$b$Ndrel ma phung mâu chroh, phung vay mưch, Khân păng rket sêk ŭch ƀư ma gâp$b$,true),
('bunong-vn','PSA',35,17,null,$b$Ơ Kôranh Brah, dŭm jŏ May mra uănh nau nây? King an huêng gâp ma nau ƀai khân păng. Sŏk lơi huêng gâp bơh yau mŭr.$b$,false),
('bunong-vn','PSA',35,18,null,$b$Pô ri gâp mra tâm rnê ma May tâm mông rƀŭn toyh. Gâp mra tâm rnê ma May tâm nklang phung ƀon lan âk.$b$,true),
('bunong-vn','PSA',35,19,null,$b$Lơi ăn phung rlăng đah gâp mâu geh nô nau gŭ maak yor gâp, mâu ăn lĕ phung rmot ma gâp mâu geh nô nau ntơ̆ măt mưch ma gâp.$b$,true),
('bunong-vn','PSA',35,20,null,$b$Yor lah khân păng mâu ngơi ôh nau đăp mpăn Ƀiă lah khân păng tâm nchră nau ndơm gay ƀư ma phung gŭ đăp mpăn tâm păng.$b$,true),
('bunong-vn','PSA',35,21,null,$b$N'hêl nanê̆ khân păng hă mbung gay ƀư mhĭk ma gâp. Khân păng lah. Ơ, ơ măt he hŏ saơ jêh nau nây.$b$,true),
('bunong-vn','PSA',35,22,null,$b$Ơ Yêhôva, May hŏ saơ tâm ban lĕ, lơi ta gŭ rklăk ôh. Ơ Kôranh Brah, lơi ta gŭ ngai đah gâp ôh.$b$,true),
('bunong-vn','PSA',35,23,null,$b$Kah rngăl hom, dâk hom, gay ma mplơ̆ nau sŏng ma gâp, Ơ Brah Ndu gâp, Kôranh Brah gâp, n'gang nau gâp.$b$,true),
('bunong-vn','PSA',35,24,null,$b$Phat an dôih gâp tĭng nâm nau sŏng May, Ơ Yêhôva Brah Ndu gâp. Jêh ri lơi ăn khân păng răm yor ma gâp ôh$b$,true),
('bunong-vn','PSA',35,25,null,$b$Lơi ăn khân păng lah tâm nuih n'hâm, Ơ, pô aơ nau he ŭch Lơi ăn khân păng lah, he rvăn jêh păng$b$,false),
('bunong-vn','PSA',35,26,null,$b$Ƀư ăn phung ŭch ma nau sŏng gâp dơi nter kuăl maak jêh ri gŭ maak. Ăn phung n'hao khân păng nơm ƀư ma gâp mra bêk ngăn.$b$,false),
('bunong-vn','PSA',35,27,null,$b$Ăn phung ŭch ma nau sŏng gâp dơi nter kuăl maak jêh ri gŭ maak. Nanê̆ ăn khân păng lah ƀa ƀơ Chrêk rmah ma Yêhôva Nơm ŭch nau ueh ma oh mon Păng.$b$,true),
('bunong-vn','PSA',35,28,null,$b$Jêh ri mpiăt gâp mra ngơi ma nau sŏng May Ma nau tâm rnê ma May lĕ nar.$b$,true),
('bunong-vn','PSA',36,1,null,$b$Nau phung ƀai rlau nau vay lah tâm nuih n'hâm gâp. Mâu geh nau klach yơk mbah ma Brah Ndu ta năp măt păng.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PSA',36,2,null,$b$Yor lah păng n'hi rnê êng păng nơm Gay ma bu mâu saơ ôh nau kue păng jêh ri tâm rmot ma păng.$b$,true),
('bunong-vn','PSA',36,3,null,$b$Nau ngơi tă bơh mbung păng jêng kue jêh ri ndơm. Păng cha lơi jêh ƀư nau blau mĭn, jêh ri nau ueh.$b$,true),
('bunong-vn','PSA',36,4,null,$b$Păng mĭn nau mhĭk tă bơh klơ sưng păng Păng gŭ tâm trong mâu ueh. Păng mâu tâm rmot ma nau tih ôh$b$,true),
('bunong-vn','PSA',36,5,null,$b$Ơ Yêhôva, nau ueh May gŭ tâm trôk Jêh ri nau nanê̆ May hao tât tâm ndâr tŭk.$b$,false),
('bunong-vn','PSA',36,6,null,$b$Nau sŏng srăng May jêng tâm ban ma phung yôk Brah Ndu Nau May phat dôih jêng tâm ban ma ntu toyh jru. Ơ Yêhôva, May prăp phung bunuyh jêh ri mpô mpa$b$,true),
('bunong-vn','PSA',36,7,null,$b$Ơ Brah Ndu, nau ueh May khlay ngăn ngên Phung kon bunuyh gŭ krap tâm dâng n'hâm năr May$b$,false),
('bunong-vn','PSA',36,8,null,$b$Khân păng mra hơm ma nau rmeh rmai tâm ngih May. Jêh ri may ăn khân păng nhêt dak krong ueh maak May.$b$,false),
('bunong-vn','PSA',36,9,null,$b$Yor lah tâm May jêng tơm nau rêh Ma nau ang May hên mra saơ nau ang.$b$,true),
('bunong-vn','PSA',36,10,null,$b$Ăn nau ueh May gŭ jŏ ta phung gĭt năl May Jêh ri nau sŏng srăng May ta phung geh nuih n'hâm sŏng$b$,true),
('bunong-vn','PSA',36,11,null,$b$Lơi ăn jâng phung sưr rlau jot gâp. Jêh ri lơi ăn ti phung ƀai nsot gâp du.$b$,false),
('bunong-vn','PSA',36,12,null,$b$Ta nây phung ƀư nau kue tŭp jêh. Bu nklơ̆ lơi khân păng jêh ri khân păng mâu hôm dơi dâk ôh.$b$,true),
('bunong-vn','PSA',37,1,null,$b$Lơi ta rŭng may nơm yor phung ƀai ôh Mâu dơi kơnh lĕ phung ƀư nau kue$b$,true),
('bunong-vn','PSA',37,2,null,$b$Yor lah bu mra rek khân păng gơnh nâm bu gơ̆ . Jêh ri khân păng mra klêu tâm ban ma gơ̆ ndrêh.$b$,false),
('bunong-vn','PSA',37,3,null,$b$Rnơm hom ma Brah Ndu jêh ri ƀư nau ueh. Pô ri bu mra ăn may gŭ tâm n'gor Păng jêh ri mbu mra siăm may ma nau nanê̆ Păng.$b$,true),
('bunong-vn','PSA',37,4,null,$b$Maak hom may nơm tâm Yêhôva, jêh ri Păng mra ăn ma may nau nuih n'hâm may ŭch.$b$,true),
('bunong-vn','PSA',37,5,null,$b$Jao trong may ma Yêhôva. Rnơm ma Păng, jêh ri Păng mra ăn jêh nau nây$b$,true),
('bunong-vn','PSA',37,6,null,$b$Păng mra tâm mpơl nau sŏng may tâm ban ma nau ang. Jêh ri nau di may tâm ban ma nar nklang bôk$b$,false),
('bunong-vn','PSA',37,7,null,$b$Gŭ rklăk ta năp Yêhôva, jêh ri kâp gân ma Păng. Lơi ăn rŭng may nơm yor du huê bunuyh dơi tâm trong Păng. Yor bunuyh dơi ƀư lĕ nau Păng ŭch ƀư mhĭk$b$,false),
('bunong-vn','PSA',37,8,null,$b$Dun nau ji nuih, cha lơi nau ji nuih Lơi ƀư rŭng may nơm ôh, nau nây mra njŭn leo may ma nau mhĭk.$b$,false),
('bunong-vn','PSA',37,9,null,$b$Yor lah phung ƀai bu mra koh lơi, Ƀiă lah phung kâp gân ma Yêhôva mra krâm neh ntu$b$,true),
('bunong-vn','PSA',37,10,null,$b$Hôm ƀât lât phung ƀai mra rai yot may mra uănh ntŭk Păng, nanê̆ mâu hôm ôh.$b$,false),
('bunong-vn','PSA',37,11,null,$b$Ƀiă lah phung oh mon mra krâm neh ntu jêh ri mra gŭ hâk răm nau đăp mpăn bêng ler.$b$,true),
('bunong-vn','PSA',37,12,null,$b$Nơm rlăng tâm nchră ƀư mhĭk ma nơm sŏng srăng. Jêh rket sêk ŭch ƀư ma ô băl.$b$,true),
('bunong-vn','PSA',37,13,null,$b$Brah Ndu mra mưch rmot Păng Yor lah saơ nar tâm rmal Păng dăch tât$b$,true),
('bunong-vn','PSA',37,14,null,$b$Phung ƀai tŏk đao jêh ri van ma khân păng. Gay ma ăn prah nơm rêh ni jêh ri nơm o-ach. Gay ma nkhĭt phung hăn tâm trong sŏng$b$,false),
('bunong-vn','PSA',37,15,null,$b$Đao khân păng mra ntâp nuih n'hâm khân păng nơm. Jêh ri na khân păng mra deh$b$,false),
('bunong-vn','PSA',37,16,null,$b$Nơm sŏng geh djê̆ ndơ jêng ueh lơn ma rmeh rmai phung ƀai geh.$b$,false),
('bunong-vn','PSA',37,17,null,$b$Yor lah ti nơm mhĭk mra deh Ƀiă lah Yêhôva yơk rdâng an phung sŏng.$b$,true),
('bunong-vn','PSA',37,18,null,$b$Yêhôva gĭt nar phung rah vah jêh ri drăp khân păng krâm mra gŭ n'ho ro.$b$,true),
('bunong-vn','PSA',37,19,null,$b$Bu mâu mra ƀư bêk khân păng ôh dôl nau rêh ni; Tâm nar sa-sât ji-ngot khân păng mra hơm.$b$,true),
('bunong-vn','PSA',37,20,null,$b$Ƀiă lah phung ƀai mra rai yot Phung rlăng Yêhôva mra jêng tâm ban ma ngi kon biăp. Khân păng mra rai lêk roh hêt nâm bu mbrui ŭnh nhhŭk.$b$,true),
('bunong-vn','PSA',37,21,null,$b$Nơm ƀai chan jêh ri Păng mâu mplơ̆ sĭt ôh. Ƀiă lah nơm sŏng blau yô̆ jêh ri Păng ăn$b$,true),
('bunong-vn','PSA',37,22,null,$b$Phung Brah Ndu ăn nau ueh uĭn mra krâm neh ntu. Ƀiă lah phung Păng rtăp bu mra nkhĭt lơi$b$,false),
('bunong-vn','PSA',37,23,null,$b$Yêhôva ăn nâp nhuat du huê bunuyh Jêh ri ô băl gŭ maak tâm trong Păng$b$,false),
('bunong-vn','PSA',37,24,null,$b$Nđâp tơ lah Păng prah, Păng mâu mra rai lôch ôh. Yor lah Yêhôva chông an ma ti Păng.$b$,false),
('bunong-vn','PSA',37,25,null,$b$Gâp hŏ jêng jêh ndăm, aƀaơ gâp hŏ ranh jêh; Ƀiă lah gâp mâu mâp saơ ôh bu cha lơi nơm sŏng. Mâu mâp saơ lĕ phung kon sau khân păng nsong ƀư dan, dăn ndơ sông sa bu.$b$,true),
('bunong-vn','PSA',37,26,null,$b$Ăp năr Păng blau yô̆ jêh ri ăn bu chan; Jêh ri phung kon sau Păng geh nau ueh uĭn.$b$,true),
('bunong-vn','PSA',37,27,null,$b$Der nau mhĭk, jêh ri ƀư nau ueh Pô ri mra gŭ n'ho ro.$b$,true),
('bunong-vn','PSA',37,28,null,$b$Yor lah Yêhôva rŏng ma nau sŏng Mâu cha lơi ôh-phung kloh ueh Păng Chiă uănh khân păng ƀa ƀơ. Ƀiă lah kon sau phung ƀai bu mra nkhĭt lơi.$b$,true),
('bunong-vn','PSA',37,29,null,$b$Phung sŏng mra dơn neh ntu, jêh ri khân păng mra gŭ ta nây ƀa ƀơ.$b$,true),
('bunong-vn','PSA',37,30,null,$b$Trôm mbung bunuyh sŏng ngơi nau blau mĭn. Jêh ri mpiăt păng nkoch nau sŏng.$b$,true),
('bunong-vn','PSA',37,31,null,$b$Nau vay Brah Ndu păng, gŭ tâm nuih n'hâm păng. Jâng păng mâu prah ôh$b$,true),
('bunong-vn','PSA',37,32,null,$b$Nơm ƀai rmơch nơm sŏng Joi gay ma nkhĭt ô băl.$b$,false),
('bunong-vn','PSA',37,33,null,$b$Brah Yêhôva mâu mra cha lơi khân păng tâm ti phung ƀai Tâm nar phat dôih Păng mâu mra tâm rmal lĕ.$b$,true),
('bunong-vn','PSA',37,34,null,$b$Kâp gân hom ma Yêhôva tĭng trong Păng Jêh ri Păng mra n'hao may ăn dơn krâm neh ntu. May mra saơ tơ lah bu koh lơi phung ƀai$b$,true),
('bunong-vn','PSA',37,35,null,$b$Gâp mâp saơ jêh phung ƀai geh nau ktang toyh păng, jêng toyh tâm ban ma tơm si jŏ năm.$b$,false),
('bunong-vn','PSA',37,36,null,$b$Ƀiă lah păng rgăn, jêh ri aơ, mâu hôm saơ păng ôh. Gâp joi păng, ƀiă lah mâu mâp.$b$,true),
('bunong-vn','PSA',37,37,null,$b$Sek uănh hom ma bunuyh rah vah, jêh ri uănh ma bunuyh sŏng, Yor lah dăch ma lôch mra tât ma bunuyh đăp mpăn.$b$,true),
('bunong-vn','PSA',37,38,null,$b$Ƀiă lah phung rlau nau vay, mra dơn nau rai yot ndrel. Bu mra koh lơi phung ƀai tâm nar dăch lôch$b$,true),
('bunong-vn','PSA',37,39,null,$b$Ƀiă lah nau tâm rklaih phung sŏng luh tă bơh Yêhôva Kôranh Brah jêng pôih n'gang khân păng tâm nau rêh ni.$b$,false),
('bunong-vn','PSA',37,40,null,$b$Yêhôva koh dŏng jêh ri kơl rklaih khân păng Kôranh Brah rklaih khân păng bơh ti phung ƀai, jêh ri ăn khân păng jêng kon me Yor lah khân păng krap mbe tâm Kôranh Brah.$b$,true),
('bunong-vn','PSA',38,1,null,$b$Hơi Yêhôva! Lơi ta May nduyh gâp, tâm nau May ji nuih Mâu lĕ mbang gâp tâm nau May ji nuih$b$,true),
('bunong-vn','PSA',38,2,null,$b$Yor lah hăr May geh ta gâp jêh. Jêh ri ti May grun gâp jâk ngăn$b$,false),
('bunong-vn','PSA',38,3,null,$b$Yor nau May ji nuih, nglay săk gâp mâu ngăch prăl ôh. Mâu geh nau rlu lĕ ma nting gâp yor nau tih gâp.$b$,false),
('bunong-vn','PSA',38,4,null,$b$Yor lah nau tih gâp hao tât ta klơ bôk gâp. Păng jêng tâm ban ma ndơ rdeng jâk ir tâm gâp.$b$,true),
('bunong-vn','PSA',38,5,null,$b$Ntŭk sôt gâp ôm jêh ri ndâng. Yor nau gâp ƀư lă lêng.$b$,true),
('bunong-vn','PSA',38,6,null,$b$Ndur kơi gâp jêng gô kuăt jêh ri rdja nuih n'hâm ngăn. Gâp hăn nsong lĕ nar ma nau klân ndrê$b$,true),
('bunong-vn','PSA',38,7,null,$b$Ŭnh duh ring sa huêt klơm gâp. Jêh ri tâm nglay săk gâp mâu geh nau ngăch prăl$b$,false),
('bunong-vn','PSA',38,8,null,$b$gâp huăr jêh, jêh ri bĭ sôt Nau uh ah tâm nuih n'hâm gâp, ăn gâp nđêng$b$,false),
('bunong-vn','PSA',38,9,null,$b$Ơ Kôranh brah, lĕ rngôch nau gâp ŭch gŭ ta năp may. Jêh ri nau gâp nđêng mâu pôn mo ma may ôh.$b$,false),
('bunong-vn','PSA',38,10,null,$b$Nuih n'hâm gâp nsâr, nau nđơr gâp luh tă bơh gâp jêh ri nau ang măt gâp, cha lơi gâp jêh$b$,true),
('bunong-vn','PSA',38,11,null,$b$Phung mĭt jăng, phung băl gâp tĭt trơn ngai đah nau sôt gâp Jêh ri phung mpôl băl gâp gŭ ngai$b$,false),
('bunong-vn','PSA',38,12,null,$b$Nđâp ma phung joi nau rêh gâp sân dăk ma gâp Phung ŭch ƀư jêr ma gâp ngơi nau mhĭk Ăp nar khân păng rvê ma nau ndơm.$b$,false),
('bunong-vn','PSA',38,13,null,$b$Ƀiă lah gâp jêng tâm ban ma du huê tĭk mâu tăng nau Tâm ban ma du huê mlo, mâu blau ngơi$b$,true),
('bunong-vn','PSA',38,14,null,$b$Gâp jêng tâm ban ma du huê bunuyh mâu tăng nau. Jêh ri mâu hôm geh nau tâm rlăch ôh tâm trôm mbung gâp.$b$,false),
('bunong-vn','PSA',38,15,null,$b$Ơ Yêhôva, tâm May yơh gâp kâp gân May mra lŏ plơ̆ lah, Ơ Kôranh Brah,$b$,true),
('bunong-vn','PSA',38,16,null,$b$Yor lah gâp lah: Lơi ta ăn khân păng hâk răm yor gâp. Tơ lah jâng gâp prah mbĭr. Khân păng dâk ŭch ƀư mhĭk ma gâp.$b$,false),
('bunong-vn','PSA',38,17,null,$b$Yor lah gâp, bơi ma prah Jêh ri nau rngot gâp gŭ ta năp gâp ƀa ƀơ$b$,true),
('bunong-vn','PSA',38,18,null,$b$Pô ri gâp mra mbơh nau mhĭk gâp Gâp mra rngot yor nau tih gâp$b$,false),
('bunong-vn','PSA',38,19,null,$b$Ƀiă lah phung rlăng đah gâp ngăch ngăn Phung tâm rmot ma gâp mâu geh nau âk ôh$b$,false),
('bunong-vn','PSA',38,20,null,$b$Phung mplơ̆ nau mhĭk, ntrok nau ueh gâp ƀư jêh Jêng phung rlăng gâp, Yor lah gâp tĭng nau ueh.$b$,false),
('bunong-vn','PSA',38,21,null,$b$Lơi ta cha lơi gâp ôh, Ơ Yêhôva, Ơ Brah Ndu gâp, lơi gŭ ngai đah gâp ôh.$b$,true),
('bunong-vn','PSA',38,22,null,$b$Dăn May văch gơnh kơl gâp, Ơ Kôranh Brah, nau tâm rklaih gâp Nau Dơm Dam Tâm Nau Rêh Nau mprơ ơm Y-Đavit, kôranh mprơ Y-Yêduthun$b$,true),
('bunong-vn','PSA',39,1,null,$b$Gâp lah, gâp mra njrăng ma nau gâp gŭ ngao. Klach mpiăt gâp ngơi tih. Gâp mra sêt lơi trôm mbung gâp Dôl phung ƀai gŭ ta năp măt gâp.$b$,true),
('bunong-vn','PSA',39,2,null,$b$Gâp jêng mlo, mâu hôm ngluh nau ngơi Gâp gŭ rklăk, mâu dơi ngluh ngơi nđâp tơ lah nau ueh kđôi lĕ. Jêh ri nau rngot gâp hao âk lơn đŏng.$b$,true),
('bunong-vn','PSA',39,3,null,$b$Nuih n'hâm gâp tâm dâng săk jêng duh Dôl gâp gŭ mĭn ŭnh sa hit Aƀaơ mpiăt gâp luh ngơi$b$,true),
('bunong-vn','PSA',39,4,null,$b$Ơ Yêhôva, ăn gâp gĭt nar gâp dăch lôch. Jêh ri dŭm âk nar May veh nau rêh gâp.$b$,false),
('bunong-vn','PSA',39,5,null,$b$Aơ, May ăn jêh nar, mông gâp jong tâm ban ma mpang ti Jêh ri nau rêh gâp jêng dơm dam ta năp May. Nanê̆, ăp nơm bunuyh dôl păng hôm janh ktang, ƀiă lah ăt jêng dơm dam lĕ (Sêla)$b$,true),
('bunong-vn','PSA',39,6,null,$b$N'hêl nanê̆ ăp nơm he sak nsong tâm ban ma gui. Păng geh nau uh ah dơm dam Nơm bun drăp ndơ, ƀiă lah mâu gĭt mbu mra sŏk dônh.$b$,false),
('bunong-vn','PSA',39,7,null,$b$Ơ Kôranh Brah, moh ndơ gâp dơi kâp gân? Tâm May yơh gâp kâp gân$b$,true),
('bunong-vn','PSA',39,8,null,$b$Dăn May rklaih an gâp bơh lĕ rngôch nau tih. Jêh ri lơi ăn phung rluk ƀư bêk gâp ôh$b$,false),
('bunong-vn','PSA',39,9,null,$b$Gâp gŭ mlo, gâp mâu hă mbung ôh Yor lah May nơm ƀư nau nây.$b$,false),
('bunong-vn','PSA',39,10,null,$b$Rlu hom nau May rmal gâp Gâp lĕ ioh huach n'hâm suan yor ti May dong gâp$b$,true),
('bunong-vn','PSA',39,11,null,$b$Yor nau kue kon bunuyh May dơi nduyh May ƀư roh nau ueh uĭn bu nâm bu ndrŭng Nanê̆ ăp nơm bunuyh jêng dơm dam$b$,false),
('bunong-vn','PSA',39,12,null,$b$Ơ Yêhôva, iăt hom nau gâp mbơh sơm, rkêng tôr iăt nau gâp kuăl vơh vơl. Lơi ta jêng dăng ma dak măt gâp ôh Yor lah gâp jêng bu năch tâm ngih May. Du huê rgăn ƀât lât tâm ban lĕ phung mbơ̆ gâp.$b$,false),
('bunong-vn','PSA',39,13,null,$b$Yô̆ an ma gâp, gay ma gâp lơ geh nau ktang Lor ma gâp hăn du, jêh ri bu mâu hôm saơ gâp ôh.$b$,true),
('bunong-vn','PSA',40,1,null,$b$Gâp srôih kâp gân Yêhôva. Jêh ri Păng rkêng leo mpeh ma gâp, iăt bâr gâp kuăl ma Păng.$b$,true),
('bunong-vn','PSA',40,2,null,$b$Păng mphâk gâp tă bơh ntu jru, nau rai yot. Tă bơh neh bŏk ƀlĭt, dơm jâng ta lŭ Jêh ri nhuat gâp chuat jêng nâp ngăn$b$,true),
('bunong-vn','PSA',40,3,null,$b$Păng dơm jêh tâm trôm mbung gâp du nau mprơ mhe, nau mprơ tâm rnê ma Brah Ndu he. Geh âk bunuyh saơ nau nây jêh ri klach, jêh ri rnơm ma Yêhôva$b$,false),
('bunong-vn','PSA',40,4,null,$b$Ueh maak yơh ma phung geh nuih n'hâm rnơm ma Yêhôva Nơm mâu chrê ôh ma phung sưr rlau, mâu lah ma phung mbruh$b$,false),
('bunong-vn','PSA',40,5,null,$b$Ơ Yêhôva, Brah Ndu gâp, kan khlay May ƀư jêh Nđâp ma nau mĭn May ŭch ăn ma hên geh âk ngăn Mâu geh nơm dơi blau rep nkra ta năp măt May. Tơ lah gâp ŭch mpơl jêh ri mbơh nau nây Geh âk ngăn tât mâu dơi kơp.$b$,false),
('bunong-vn','PSA',40,6,null,$b$May mâu ŭch ôh ma mpa ƀư brah, mâu lah ndơ nhhơr gŭch May pơk jêh tôr gâp May mâu dăn ôh mpa gŭch nhhơr, mâu lah mpa ƀư brah chuai nau tih.$b$,true),
('bunong-vn','PSA',40,7,null,$b$Pô ri gâp lah, aơ gâp văch Tâm ndrom sămƀŭt bu klôt, bu chih jêh ma gâp.$b$,true),
('bunong-vn','PSA',40,8,null,$b$Ơ Kôranh Brah Ndu, gâp maak ngăn ƀư nau May ŭch. N'hêl nanê̆ nau vay May gŭ tâm nuih n'hâm gâp$b$,true),
('bunong-vn','PSA',40,9,null,$b$Gâp nkoch nau mhe mhan ueh tâm mông âk bunuyh tâm rƀŭn Aơ gâp mâu mêm ôh trôm mbung gâp. Ơ Yêhôva, may gĭt jêh nau nây.$b$,false),
('bunong-vn','PSA',40,10,null,$b$Gâp mâu pôn ôh nau sŏng May tâm nuih n'hâm gâp Gâp mbơh jêh nau nanê̆ jêh ri nau Brah Ndu tâm rklaih Gâp mâu pôn ôh nau ueh jêh ri nau nanê̆ May tâm phung tâm rƀŭn âk.$b$,true),
('bunong-vn','PSA',40,11,null,$b$Ơ Yêhôva, lơi dun ôh ma gâp nau May yô̆Ăn nau ueh jêh ri nau nanê̆ May chiă uănh gâp ƀa ƀơ$b$,true),
('bunong-vn','PSA',40,12,null,$b$Yor lah nau mhĭk gŭ jum gâp. Nau kue gâp ban gâp, tât gâp mâu dơi n'gơr măt ôh. Khân păng jêng âk lơn ma sŏk tâm bôk gâp Jêh ri gâp geh nau rdja nuih n'hâm$b$,false),
('bunong-vn','PSA',40,13,null,$b$Ăn May geh nau ŭch tâm rklaih gâp, ơ Yêhôva Ơ Yêhôva kơl koh dŏng hom gâp$b$,false),
('bunong-vn','PSA',40,14,null,$b$Klach geh nơm joi nkhĭt huêng gâp. Geh nau bêk prêng ndrel n'grŭp jêh ri mĭn tâm rlŭk Ăn phung vay ƀư mhĭk ma gâp plơ̆ sĭt Jêh ri mâu geh nau bu yơk mbah ma khân păng ôh.$b$,false),
('bunong-vn','PSA',40,15,null,$b$Ăn khân păng jêng ndrŏt glo yor nau khân păng bêk Phung nây lah ma gâp: “Ah! Ha!”$b$,true),
('bunong-vn','PSA',40,16,null,$b$Ăn lĕ rngôch phung joi May gŭ tâm nau hâk răm, jêh ri geh nau maak tâm May. Ăn phung rŏng ma nau May tâm rklaih, may lah ƀa ƀơ, Chrêk rmah ma Yêhôva$b$,true),
('bunong-vn','PSA',40,17,null,$b$Gâp jêng o ach jêh ri rêh ni Ƀiă lah Kôranh Brah mĭn ma gâp May jêng nơm kơl gâp jêh ri nơm ăn gâp đăp mpăn Ơ Brah Ndu gâp, lơi lŏ ƀư njong ôh.$b$,false),
('bunong-vn','PSA',41,1,null,$b$Ueh maak yơh ma phung blau chrê ma phung o ach Tâm nar geh nau rêh ni Yêhôva mra rklaih păng$b$,true),
('bunong-vn','PSA',41,2,null,$b$Yêhôva chiă uănh păng jêh ri mât mơh nau rêh păng. Păng mra geh nau ueh uĭn ta neh ntu jêh ri lơi ta jao păng ma phung rlăng ŭch ƀư păng$b$,false),
('bunong-vn','PSA',41,3,null,$b$Yêhôva mra kơl păng, dôl păng bêch ta sưng nau rêh ni. May mra kơl păng, tơ lah geh nau ji kuet$b$,false),
('bunong-vn','PSA',41,4,null,$b$Gâp lah: Ơ Yêhôva, kơl jêh ri yô̆ an gâp Ƀư bah an huêng gâp, Yor lah gâp ƀư tih jêh đah May.$b$,false),
('bunong-vn','PSA',41,5,null,$b$Phung rlăng đah gâp, ngơi nau ƀai đah gâp Ndah jŏ păng mra khĭt? Ndah jŏ amoh păng mra rai yot?$b$,true),
('bunong-vn','PSA',41,6,null,$b$Tơ lah du huê tâm phung khân păng chop gâp, păng ngơi nau mƀruh đah gâp. Păng bun tâm nuih n'hâm păng nau kue, tơ lah păng du bah dih, păng nkoch bri nau nây.$b$,true),
('bunong-vn','PSA',41,7,null,$b$Lĕ rngôch phung tâm rmot ma gâp, ngơi ƀŭk dŭk suyh ndrăng nơm gay ma ƀư ma gâp Khân păng mĭn ŭch ƀư mhĭk ma gâp.$b$,true),
('bunong-vn','PSA',41,8,null,$b$Bu nti nau ji hâu, krêp tâm săk păng Aƀaơ păng hŏ bêch jêh, păng mâu mra hôm dơi dâk ôh.$b$,true),
('bunong-vn','PSA',41,9,null,$b$Nđâp ma mĭt jăng dăch lơn, nơm gâp rnơm Nơm sa kapŭng gâp. Yơk nđâp jâng păng ŭch chưng gâp.$b$,true),
('bunong-vn','PSA',41,10,null,$b$Ƀiă lah, ơ Yêhôva, yô̆ nđach gâp ƀă, yơk chông an gâp ƀă Gay ma gâp dơi mplơ̆ nau khư ma păng Tơ lah phung rlăng mâu dơi đah gâp$b$,true),
('bunong-vn','PSA',41,11,null,$b$Ma nau nây yơh gâp gĭt May rŏng ma gâp$b$,false),
('bunong-vn','PSA',41,12,null,$b$May kuăn rdâng gâp jêh yor nau sŏng gâp Jêh ri May dơm gâp ta năp May ƀa ƀơ.$b$,false),
('bunong-vn','PSA',41,13,null,$b$Mât ton ma Yêhôva, Brah Ndu phung Israel. Ntơm bơh rnôk n'ho ro tât rnôk n'ho ro Amen, Amen.$b$,true),
('bunong-vn','PSA',42,1,null,$b$Ơ Brah Ndu, huêng gâp ji hir ma May, tâm ban ma du mlâm jun me joi n'hor dak.$b$,true),
('bunong-vn','PSA',42,2,null,$b$Huêng gâp ji hir ma Brah Ndu nau rêh Ndah jŏ gâp mra hăn mpơl muh măt ta năp Brah Ndu?$b$,true),
('bunong-vn','PSA',42,3,null,$b$Dak măt gâp jêng ndơ gâp sông sa nar nâm măng Dôl bu lah ma gâp, mâu geh rlu tâm Brah Ndu gâp?$b$,true),
('bunong-vn','PSA',42,4,null,$b$Kăl e gâp hăn ndrel ma băl âk leo khân păng tât ta ngih Brah Ndu, Geh bâr troh drơu maak jêh ri tâm rnê Du phung âk ƀư nau maak, Nuih ma gâp ăn kah gĭt nau nây, jêh ri nuih n'hâm rngot.$b$,true),
('bunong-vn','PSA',42,5,null,$b$Ơ huêng gâp, mâm ƀư may rdja nuih n'hâm, jêh ri uh ah tâm săk jăn gâp? Kâp gân hom ma Brah Ndu Yor lah gâp mra lŏ mât ton ma Păng Yor geh nau tâm rklaih tă bơh muh măt Păng$b$,true),
('bunong-vn','PSA',42,6,null,$b$Ơ Brah Ndu gâp ah, huêng gâp rdja nuih n'hâm tâm săk jăn gâp. Yor lah tă bơh bri Yurdan, bơh yôk Hêrmôn jêh ri tă bơh mbon Mitsar Gâp kah gĭt rvê ma May.$b$,false),
('bunong-vn','PSA',42,7,null,$b$Brŏng jru kuăl brŏng jru, dôl tăng nteh dak leng Brah Ndu Lĕ rngôch dak njach ryă may rdja jêh ri ktang rgăn jêh ta klơ gâp.$b$,true),
('bunong-vn','PSA',42,8,null,$b$Dôl nar Yêhôva ăt Păng ăn nau yô̆Jêh ri tâm măng gâp mprơ tâm rnê ma Păng gâp mbơh sơm ma Brah Ndu jêng nau rêh gâp$b$,true),
('bunong-vn','PSA',42,9,null,$b$Gâp lah ma Brah Ndu, jêng glo lŭ gâp. Mâm ƀư May chuêl gâp? Mâm ƀư gâp hăn tâm nau rngot klâng Yor nơm rlăng tŭn jot gâp yơh.$b$,false),
('bunong-vn','PSA',42,10,null,$b$Nau phung rlăng suai rak, jêng tâm ban ma nchah lơi nting gâp. Dôl khân păng lah ƀa ƀơ ma gâp, Mbah Brah Ndu may?$b$,true),
('bunong-vn','PSA',42,11,null,$b$Ơ Huêng gâp mâm ƀư may rdja nuih n'hâm tâm săk jăn gâp? Kâp gân hom ma Brah Ndu, Yor lah gâp mra lŏ mât ton ma Păng. Păng jêng nau tâm rklaih ma muh măt gâp jêh ri Brah Ndu gâp.$b$,true),
('bunong-vn','PSA',43,1,null,$b$Ơ Brah Ndu ah, ăn May phat dôih gâp, king mpeh ma gâp. Tâm rdâng đah du mpôl băl mâu yơk ma Brah Ndu. Tâm rklaih gâp bơh phung bunuyh ndơm jêh ri tih mhĭk.$b$,true),
('bunong-vn','PSA',43,2,null,$b$Ơ Brah Ndu, May yơh jêng nau ktang gâp. Mâm ƀư May dun jêh ri cha lơi gâp? Mâm ƀư gâp hăn tâm nau rngot klâng. Yor phung rlăng tŭn jot gâp yơh.$b$,true),
('bunong-vn','PSA',43,3,null,$b$Dăn ma May ăn gâp nau ang jêh ri nau nanê̆, ăn khân păng njŭn leo an gâp ƀă. Ăn khân păng njŭn gâp ta yôk kloh ueh May, jêh ri ta ntŭk May gŭ.$b$,true),
('bunong-vn','PSA',43,4,null,$b$Pô ri gâp mra hăn ta nơng Brah Ndu, Tât ta Brah Ndu, nau răm maak gâp Jêh ri gâp mra mât ton ma May ma gong rêng. Ơ Brah Ndu, jêng Brah Ndu gâp.$b$,true),
('bunong-vn','PSA',43,5,null,$b$Mâm ƀư may djoh n'hâm, ơ huêng gâp, jêh ri mâm ƀư may uh ah tâm săk jăn gâp. Kâp gân ma Brah Ndu gâp mra tâm rnê ma Păng đŏng. Păng jêng nau tâm rklaih ma muh măt gâp, jêh ri Brah Ndu gâp.$b$,true),
('bunong-vn','PSA',44,1,null,$b$Ơ Brah Ndu, trôm tôr hên tăng. Phung mbơ̆ hên nkoch jêh ma hên Kan May ƀư jêh tâm rnôk khân păng kăl e dơh$b$,true),
('bunong-vn','PSA',44,2,null,$b$Mpang ti May mprơh nsot jêh phung mpôl băl bunuyh May ăn nau rêh ni ma phung mpôl băl bunuyh Ƀiă lah rdâk nkra jêh phung mbơ̆ hên nâp rjăp ngăn.$b$,false),
('bunong-vn','PSA',44,3,null,$b$Mâu tăp yor ma đao gưm khân păng ôh dơi sŏk sĭt bri neh. Mâu lĕ yor ma ti khân păng dơi geh nau tâm rklaih jêh Ƀiă lah ma ti ma May, ma nting tur ti May jêh ri ma nau ang tă bơh muh măt May yơh. Yor lah May ƀư nau ueh ma khân păng$b$,true),
('bunong-vn','PSA',44,4,null,$b$Ơ Brah Ndu, May jêng hađăch gâp Ăn nau dơi ma Yakôb$b$,false),
('bunong-vn','PSA',44,5,null,$b$Yor May hên mra ăn phung rlăng prah. Ma amoh May hên mra jot phung ŭch tâm rdâng đah hên$b$,false),
('bunong-vn','PSA',44,6,null,$b$Gâp mâu rnơm ma na gâp ôh Mâu lah đao gưm, gâp mâu rnơm lĕ nau tâm rklaih.$b$,false),
('bunong-vn','PSA',44,7,null,$b$Ƀiă lah May yơh tâm rklaih jêh hên bơh phung rlăng đah hên. Jêh ri May ƀư bêk jêh phung vay tâm rmot ma hên.$b$,true),
('bunong-vn','PSA',44,8,null,$b$Hên tâm rnê hên nơm tâm Brah Ndu lĕ nar. Jêh ri hên mra mât ton ƀa ƀơ ma amoh May (Sêla)$b$,true),
('bunong-vn','PSA',44,9,null,$b$Ƀiă lah aƀaơ May dun hên, jêh ri ƀư bêk hên May mâu hăn ôh ndrel ma phung tahan hên.$b$,false),
('bunong-vn','PSA',44,10,null,$b$May ăn hên rŭch jêh ta năp phung rlăng Jêh ri phung tâm rmot ma hên tâm pă ndơ pit tă bơh hên.$b$,true),
('bunong-vn','PSA',44,11,null,$b$May ăn hên jêng tâm ban ma biăp prăp gŭch sa. May nsot hên bra du tâm phung mpôl băl.$b$,true),
('bunong-vn','PSA',44,12,null,$b$May tăch phung ƀon lan May ma rnoh mâu khlay. Jêh ri nau ndrŏng may mâu hao ôh đah rnoh khân păng$b$,true),
('bunong-vn','PSA',44,13,null,$b$May ăn hên jêng ndơ ăn bêk phung chiau meng hên Hên jêng ndơ bu gơm mưch, ndơ pâl ma phung gŭ jum hên.$b$,false),
('bunong-vn','PSA',44,14,null,$b$May ăn hên jêng ndơ mpôl băl êng mưch, jêh ri ma phung ƀon lan bu rteh bôk ma hên.$b$,true),
('bunong-vn','PSA',44,15,null,$b$Nau bêk prêng gŭ ta năp gâp ăp nar, jêh ri nau bêk nkŭm muh măt gâp.$b$,true),
('bunong-vn','PSA',44,16,null,$b$Yor iăt bâr nơm suai rak jêh ri rtăp thô ma gâp, Yor nơm rlăng jêh ri nơm plơng bôk.$b$,true),
('bunong-vn','PSA',44,17,null,$b$Lĕ nau rêh ni nây tât ma hên jêh, ƀiă lah hên mâu chuêl May ôh. Hên mâu rlau lĕ nau tâm rnglăp đah May.$b$,true),
('bunong-vn','PSA',44,18,null,$b$Nuih n'hâm hên mâu rle nkơi cha lơi May ôh, Nhuat hên mâu lĕ der trong May$b$,true),
('bunong-vn','PSA',44,19,null,$b$Nđâp tơ lah May jot jêh hên tâm ntŭk phung so bri, Jêh ri nkŭm jêh hên ma n'hâm nau khĭt.$b$,false),
('bunong-vn','PSA',44,20,null,$b$Tơ lah hên kah gĭt jêh ri Brah Ndu hên, mâu lah hên yơr jêh ti hên ma brah êng.$b$,true),
('bunong-vn','PSA',44,21,null,$b$Brah Ndu mâu mra sek uănh nau nây hĕ, Yor lah Păng nơm gĭt nau ndâp tâm nuih n'hâm.$b$,true),
('bunong-vn','PSA',44,22,null,$b$N'hêl nanê̆ yor May yơh bu nkhĭt hên ăp nar bu uănh ma hên tâm ban ma biăp prăp gŭch sa.$b$,true),
('bunong-vn','PSA',44,23,null,$b$Kah rngăl hom May, mâm ƀư May bêch, Ơ Kôranh Brah? Dâk hom May, lơi ta dun ma hên mro ôh.$b$,true),
('bunong-vn','PSA',44,24,null,$b$Mâm ƀư May pôn măt May? Mâm ƀư may chuêl nau rêh ni Jêh ri nau bu tŭn jot hên?$b$,true),
('bunong-vn','PSA',44,25,null,$b$Yor lah huêng hên gŭ djoh n'hâm tât ta ndruyh neh. Săk jăn hên gŭ krêp ma neh.$b$,true),
('bunong-vn','PSA',44,26,null,$b$Dâk hom May văch kơl hên Jêh ri chuai an hên yor nau ueh May.$b$,true),
('bunong-vn','PSA',45,1,null,$b$Nuih n'hâm gâp bêng ler ma nau ueh ngăn. Gâp ngơi ma nau gâp ƀư prăp ma hađăch Mpiăt gâp tâm ban ma du mlâm mâng chih du huê nơm njêh$b$,true),
('bunong-vn','PSA',45,2,null,$b$may jêng ueh lơn ma lĕ rngôch kon bu klâu bunuyh Nau yô̆ nkhŭt jêh ta mbung may, Yor nây Brah Ndu ăn nau ueh uĭn ƀa ƀơ ma may$b$,false),
('bunong-vn','PSA',45,3,null,$b$Ơ Kôranh Brah, cheng hom đao. Jêng nau chrêk rmah jêh ri nau rnam May.$b$,false),
('bunong-vn','PSA',45,4,null,$b$Ma nau nkrơ̆ May ăn ncho ta ndeh seh ma nau dơi, yor nau nanê̆, nau rdơ̆ rbăn jêh ri nau sŏng srăng. Jêh ri ti ma May mra tâm mpơl kan toyh ngăn ngên.$b$,true),
('bunong-vn','PSA',45,5,null,$b$Hăr May mplanh ngăn Pănh geh ta play nuih phung rlăng đah hađăch Phung ƀon lan mra tŭp tâm dâng jâng May.$b$,true),
('bunong-vn','PSA',45,6,null,$b$Ơ, Brah Ndu, sưng hađăch May hôm ƀa ƀơ n'ho ro, lôch rnôk aơ, pơh rnôk êng. Mâng ƀon bri hađăch May jêng mâng hađăch nau sŏng.$b$,true),
('bunong-vn','PSA',45,7,null,$b$May rŏng nau sŏng jêh ri tâm rmot ma nau ƀai. Yor ri Brah Ndu, jêng Brah Ndu may Brah troch jêh dak ngi ma may, dak ngi nau maak hŏ lư n'găr lơn ma lĕ rngôch phung mĭt jăng may.$b$,true),
('bunong-vn','PSA',45,8,null,$b$Dak myr, alôê, jêh ri kas ƀâu kah tâm bok ao May Tâm ngih hađăch bu ƀư ma la, nau bu uh dĭng vưt ƀư maak May.$b$,true),
('bunong-vn','PSA',45,9,null,$b$Phung kon bu ur hađăch jêng tâm phung bu ur May yơk Bu ur hađăch gŭ pa ma May ndrăp ma mah ô phia (Ôphir).$b$,true),
('bunong-vn','PSA',45,10,null,$b$Ơ kon bu ur gâp, gŭ iăt hom, uănh jêh ri rkêng tôr ay. Lơi chuêl ƀon lan ay jêh ri ngih mbơ̆ ay.$b$,true),
('bunong-vn','PSA',45,11,null,$b$Jêh ri hađăch mra ŭch ma nau ueh ay Yor Păng jêng kôranh ay, chon mon mbah hom ta năp Păng.$b$,true),
('bunong-vn','PSA',45,12,null,$b$Kon bu ur ƀon tir mra gŭ pa năp ndjôt ndơ nhhơr, nđâp phung ndrŏng tâm ƀon lan mra dăn nau yô̆ ay.$b$,true),
('bunong-vn','PSA',45,13,null,$b$Chrêk rmah ngăn kon bu ur hađăch gŭ tâm ngih hađăch Păng soh bok ao tanh ma mhay$b$,true),
('bunong-vn','PSA',45,14,null,$b$Păng mra nsoh bok ao cheh jêh ri bu njŭn păng ta năp hađăch phung băl bu ur druh gŭ pa kơi păng bu mra njŭn ta năp may.$b$,false),
('bunong-vn','PSA',45,15,null,$b$Bu mra ăn khân păng lăp Tâm nklang ngih hađăch ma nau răm maak.$b$,true),
('bunong-vn','PSA',45,16,null,$b$Phung kon May mra ntrok ntŭk mbơ̆ May May mra nkăt njêng khân păng jêng kôranh chiă uănh tâm lam bri$b$,true),
('bunong-vn','PSA',45,17,null,$b$Gâp mra ăn amoh May jêng lư n'găr tâm lĕ rnôk. Yor nây phung ƀon lan mra tâm rnê ma May ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','PSA',46,1,null,$b$Brah Ndu jêng ntŭk he mbe krap jêh ri jêng n'hâm suan phung he.$b$,true),
('bunong-vn','PSA',46,2,null,$b$Yor ri hên mâu klach ôh, nđâp tơ lah neh ntu geh nau rgâl, jêng nơm kơl koh dŏng, mâu mâp roh măt tâm lĕ nau rêh ni Jêh ri nđâp tơ lah yôk n'gơ jêh ri bu klŭp tâm nklang dak rlai kđôi lĕ.$b$,true),
('bunong-vn','PSA',46,3,null,$b$Nđâp tơ lah dak rlai ngrông luh mpuênh Jêh ri lĕ yôk n'gơ. Yor nau n'gŏch dâk păng.$b$,true),
('bunong-vn','PSA',46,4,null,$b$Geh du n'hor dak krong jêh ri n'hor Păng ƀư maak ma Brah Ndu. Ntŭk kloh ueh tâm ngih bok ma nơm ta klơ lơn.$b$,true),
('bunong-vn','PSA',46,5,null,$b$Brah Ndu gŭ ta nklang păng, păng mâu mra n'gơ ôh. Brah Ndu mra kơl khân păng ntơm bơh ơm ôi$b$,true),
('bunong-vn','PSA',46,6,null,$b$Phung mpôl băl geh nau nuih, ƀon bri hađăch n'gơ. Păng ăn bu tăng bâr Păng jêh ri neh ntu lêk$b$,false),
('bunong-vn','PSA',46,7,null,$b$Brah Yêhôva ma phung tahan gŭ ndrel ma he Brah Ndu Yakôb jêng ntŭk hên mbe krap (Sêla)$b$,false),
('bunong-vn','PSA',46,8,null,$b$Văch hom, uănh kan Yêhôva, nau Păng ƀư rai ƀư jêh ta neh ntu$b$,false),
('bunong-vn','PSA',46,9,null,$b$Păng ăn lôch nau tâm lơh tât ta dŭt bri neh. Păng nklah lơi na, koh lơi tak pe puăn gâl Lĕ ndeh klư dŏng nau tâm lơh, Păng su lơi ma ŭnh.$b$,false),
('bunong-vn','PSA',46,10,null,$b$Gŭ răk klăk hom, jêh ri ăn may gĭt gâp jêng Brah Ndu Gâp mra geh nau yơk mbah tă bơh phung mpôl băl, tâm neh ntu.$b$,true),
('bunong-vn','PSA',46,11,null,$b$Yêhôva ma phung tahan gŭ ndrel hên. Brah Ndu Yakôb jêng ntŭk he mbe krap. (Sêla) Brah Ndu Jêng Hađăch Neh Ntu. Ma Kôranh Phung Mprơ Nau mprơ phung kon Kôrê$b$,true),
('bunong-vn','PSA',47,1,null,$b$Hơi lĕ rngôch bunuyh ƀon lan, tap ti khân ay may troh, nter maak ma Brah Ndu ma bâr nau dơi.$b$,true),
('bunong-vn','PSA',47,2,null,$b$Yor lah Yêhôva Nơm Klơ Lơn jêng khư bu klach. Păng jêng hađăch toyh ma neh ntu$b$,true),
('bunong-vn','PSA',47,3,null,$b$Păng nglăp phung ƀon lan tâm dâng hên Păng dơm phung mpôl băl tâm dâng jâng hên$b$,false),
('bunong-vn','PSA',47,4,null,$b$Păng săch jêh drăp ăn ma he krâm Jêng nau chrêk rmah Yakôb, jêng nơm Păng rŏng. (Sêla)$b$,false),
('bunong-vn','PSA',47,5,null,$b$Brah Ndu drâm klơ geh bâr troh maak Yêhôva hao ndrel ma bâr nŭng nke.$b$,false),
('bunong-vn','PSA',47,6,null,$b$Mprơ tâm rnê hom ma Brah Ndu, Mprơ tâm rnê hom Mprơ tâm rnê hom ma hađăch he, Mprơ tâm rnê hom$b$,true),
('bunong-vn','PSA',47,7,null,$b$Yor lah Brah Ndu jêng hađăch ma lam neh ntu Mprơ tâm rnê hom ma nau gĭt rbăng$b$,false),
('bunong-vn','PSA',47,8,null,$b$Brah Ndu chiă uănh lĕ rngôch mpôl băl bunuyh Brah Ndu gŭ drâm ta sưng hađăch kloh ueh Păng.$b$,false),
('bunong-vn','PSA',47,9,null,$b$Phung kon hađăch phung ƀon lan tâm rƀŭn ndrel n'grŭp Gay ma jêng phung ƀon lan ma Brah Ndu Abraham. Yor lah khêl neh ntu jêng ndơ Brah Ndu Păng geh nau yơk toyh hâu ngăn.$b$,true),
('bunong-vn','PSA',48,1,null,$b$Yêhôva jêng toyh, jêh ri khư ma lĕ nau tâm rnê Tâm ƀon Brah Ndu he ta klơ yôk kloh ueh Păng$b$,true),
('bunong-vn','PSA',48,2,null,$b$Yôk Siôn jêng ueh mpeh bah yôk ƀon hađăch toyh, geh nau răm maak ma lĕ rngôch neh ntu.$b$,false),
('bunong-vn','PSA',48,3,null,$b$Tâm phung ngih hađăch păng Brah Ndu tâm mpơl Păng nơm jêng ntŭk du krap.$b$,true),
('bunong-vn','PSA',48,4,null,$b$Yor lah, aơ, phung hađăch tâm nal jêh Khân păng rgăn ndrel n'grŭp$b$,true),
('bunong-vn','PSA',48,5,null,$b$Khân păng uănh ta Siôn, jêh ri hih rhâl Uh ah jêh ri du krap gơnh.$b$,false),
('bunong-vn','PSA',48,6,null,$b$Ta ntŭk nây khân păng geh nau râm sâr Khân păng geh nau ji ngăn, tâm ban ma bu ur dôl n'gơch.$b$,true),
('bunong-vn','PSA',48,7,null,$b$Brah Ndu dŏng rmlông sial tă bơh lơ Njach chah kŭmpăn Tarêsi.$b$,true),
('bunong-vn','PSA',48,8,null,$b$Nau phung hên hŏ tăng, hŏ saơ ngăn Tâm ƀon Yêhôva ma phung tahan âk tâm ƀon Brah Ndu hên. Brah Ndu rdâk njêng păng ma nau nâp rjăp n'ho ro.$b$,true),
('bunong-vn','PSA',48,9,null,$b$Ơ Brah Ndu tâm nklang sưng hađăch May Phung hên mĭn ma nau ueh lăng May.$b$,true),
('bunong-vn','PSA',48,10,null,$b$Ơ Kôranh Brah Ndu mâm ƀư amoh May, jêh ri nau tâm rnê ma May tâm ban pô nây lĕ, ăn tât ta ntŭk dŭt bri neh. Ti ma May bêng ma nau sŏng srăng$b$,true),
('bunong-vn','PSA',48,11,null,$b$Yor nau May phat dôih Ăn yôk Siôn maak Ăn phung kon bu ur Yuđa răm rhơn$b$,false),
('bunong-vn','PSA',48,12,null,$b$Hăn ndăch jum yôk Siôn. Hăn nsong ndăch jŭm păng. Kơp tŭm păng.$b$,false),
('bunong-vn','PSA',48,13,null,$b$Uănh pêr n'gar păng Sek uănh phung ngih hađăch păng; Gay ma nkoch bri ma phung mpôl băl kăndơ̆ .$b$,true),
('bunong-vn','PSA',48,14,null,$b$Yor lah Brah Ndu aơ jêng Brah Ndu phung hên n'ho ro mro mrăng. Păng njŭn leo he tât nar he khĭt.$b$,true),
('bunong-vn','PSA',49,1,null,$b$Hơi lĕ rngôch phung ƀon lan, iăt hom nau aơ: Ăn lĕ rngôch rkêng tôr. Ơ phung gŭ tâm neh ntu.$b$,true),
('bunong-vn','PSA',49,2,null,$b$Phung jê̆ jêh ri phung toyh. Ndrŏng jêh ri o ach.$b$,true),
('bunong-vn','PSA',49,3,null,$b$Bâr mbung gâp mra ngơi ma nau blau mĭn Nau mĭn tă bơh nuih n'hâm gâp, mra luh tă bơh nau gĭt rbăng$b$,true),
('bunong-vn','PSA',49,4,null,$b$Gâp mra rkêng tôr nau ngơi hôr Gâp mra sŏk gong rêng gay ma pơk nau ngơi hôr gâp$b$,false),
('bunong-vn','PSA',49,5,null,$b$Mâm ƀư gâp mra klach tâm nau rêh ni Tơ lah nau kue phung rlăng gâp gŭ jum gâp$b$,false),
('bunong-vn','PSA',49,6,null,$b$Phung rnơm ma nau ndrŏng khân păng nơm Ntưih êng nơm geh drăp ndơ âk rmeh.$b$,false),
('bunong-vn','PSA',49,7,null,$b$Mâu geh ôh du huê nơm dơi tâm chuai an oh nâu Mâu lĕ dơi ăn ma Brah Ndu rnoh tâm chuai$b$,true),
('bunong-vn','PSA',49,8,null,$b$Yor nau tâm chuai huêng khân păng khlay ngăn Bu mâu mra dơi nkhôm rnoh nây ôh.$b$,false),
('bunong-vn','PSA',49,9,null,$b$Gay ma bunuyh geh nau rêh n'ho ro. Gay ma Păng mâu mra saơ nau rai yot ôh.$b$,true),
('bunong-vn','PSA',49,10,null,$b$Yor may saơ nơm gĭt mleh khĭt. Phung brŭt rluk jêh ri bunuyh rluk mâl rai yot tâm ban lĕ. Jêh ri cha lơi drăp ndơ ăn ma bu êng$b$,true),
('bunong-vn','PSA',49,11,null,$b$Nuih n'hâm khân păng, mĭn ma ngih khân păng gŭ hôm ƀa ƀơ n'ho ro. Jêh ri ntŭk păng gŭ lôch rơh aơ pơh rơh êng Khân păng sŏk amoh khân păng nơm jêng rnha moh neh lŏ-mir.$b$,false),
('bunong-vn','PSA',49,12,null,$b$Ƀiă lah kon bunuyh, nđâp tơ lah ndrŏng kuăng toyh, mâu dơi hôm n'ho ro ôh. Păng jêng tâm ban ma mpô mpa rai lôch.$b$,true),
('bunong-vn','PSA',49,13,null,$b$Bu chôk amoh khân păng jêng tâm ban ma du mpôl biăp prăp ma ƀon phung khĭt. Nau khĭt mra jêng rmăk khân păng$b$,true),
('bunong-vn','PSA',49,14,null,$b$Tơ lah tât ôi, phung sŏng mra geh nau dơi chiă uănh khân păng Ƀon phung khĭt mra sa nau ueh khân păng Tât mâu hôm geh ntŭk khân păng gŭ$b$,false),
('bunong-vn','PSA',49,15,null,$b$Ƀiă lah Brah Ndu mra tâm chuai huêng gâp bơh ti phung ƀon khĭt; Yor lah păng mra rom gâp. (Sêla)$b$,false),
('bunong-vn','PSA',49,16,null,$b$Lơi ta klach ôh tơ lah geh bunuyh plơ̆ jêng ndrŏng kuăng Yor lah drăp ndơ tâm ngih păng mra jêng bĭk. Dôl geh nau chrêk rmah ngih păng geh nau hao$b$,false),
('bunong-vn','PSA',49,17,null,$b$Yor lah păng mâu mra djôt leo du ntil ndơ ôh tơ lah păng khĭt. Nau lư n'găr păng mâu dơi tĭng păng jur tâm trôm môch lĕ$b$,false),
('bunong-vn','PSA',49,18,null,$b$Nđâp tơ lah păng tâm rnê ma huêng păng dôl păng gŭ rêh Jêh ri phung bunuyh tâm rnê ma may tơ lah may ƀư ueh ma may nơm,$b$,false),
('bunong-vn','PSA',49,19,null,$b$Phung mra hăn ta ntŭk phung mbơ̆ păng. Khân păng mâu mra hôm dơi saơ nau ang ôh.$b$,false),
('bunong-vn','PSA',49,20,null,$b$Nơm gŭ tâm nau bu yơk jêh ri mâu geh nau gĭt rbăng, Jêng tâm ban ma mpô mpa hăn tâm nau rai yot.$b$,true),
('bunong-vn','PSA',50,1,null,$b$Tâm nau dơi, Brah Ndu, Yêhôva, ngơi jêh Păng kuăl neh ntu ntơm bah ntŭk nar luh tât ta ntŭk nar nhâp.$b$,true),
('bunong-vn','PSA',50,2,null,$b$Tă bơh Siôn, nau ueh rah vah, Brah Ndu sol nau nchrat ang Păng.$b$,true),
('bunong-vn','PSA',50,3,null,$b$Brah Ndu hên văch tât, mâu gŭ rklăk ôh Ta năp Brah Ndu geh ŭnh hit, Jum Păng geh sial chuănh toyh$b$,true),
('bunong-vn','PSA',50,4,null,$b$Păng kuăl phung trôk klơ, Nđâp ma neh ntu ŭch phat dôih phung ƀon lan Păng$b$,false),
('bunong-vn','PSA',50,5,null,$b$Tâm rƀŭn hom ndrel ma Gâp phung kloh ueh Gâp Phung hŏ ƀư jêh nau tâm rnglăp đah Gâp ma nau ƀư brah$b$,false),
('bunong-vn','PSA',50,6,null,$b$Tâm trôk mra mbơh nau sŏng Gâp. Yor lah Brah Ndu yơh jêng kôranh phat dôih (Sêla)$b$,false),
('bunong-vn','PSA',50,7,null,$b$Gŭ iăt hom, ơ phung ƀon lan Gâp iăt hom, Gâp mra ngơi: Ơ Israel, iăt hom Gâp mra mbơh nau bu ƀư rlăng ma khân ay may. Gâp jêng Brah Ndu, jêng Brah Ndu khân ay may.$b$,false),
('bunong-vn','PSA',50,8,null,$b$Gâp mâu nduyh may ôh yor nau may ƀư brah Mâu di lĕ ma nau ƀư brah gŭch gŭ ta năp Gâp mro.$b$,true),
('bunong-vn','PSA',50,9,null,$b$Gâp mâu mra nhŭp lĕ ndrôk nkuăng tă bơh ngih may Mâu mra nhŭp lĕ be nkuăng tă bơh ndrung biăp may.$b$,true),
('bunong-vn','PSA',50,10,null,$b$Yor lah lah lĕ rngôch mpô mpa tâm bri jêng ndơ Gâp da dê. Lĕ ntil mpô mpa gŭ tâm ăp yôk tâm ban lĕ.$b$,true),
('bunong-vn','PSA',50,11,null,$b$Gâp dơi gĭt năl lĕ ntil sĭm tâm ăp yôk Jêh ri lĕ mpô mpa bri jêng ndơ Gâp da dê$b$,true),
('bunong-vn','PSA',50,12,null,$b$Tơ lah gâp ji ngot Gâp mâu mra mbơh nau nây ma may ôh. Yor lah neh ntu jêh ri lĕ mpa tâm neh ntu jêng ndơ Gâp$b$,false),
('bunong-vn','PSA',50,13,null,$b$Gâp mra sa puăch ndrôk nkuăng lĕ, Mâu lah nhêt mham be nkuăng lĕ.$b$,false),
('bunong-vn','PSA',50,14,null,$b$Nhhơr nau may tâm rnê lah ueh, jêng ndơ ƀư brah ma Brah Ndu Jêh ri ƀư nanê̆ nau may ton đah Nơm Ta Klơ Lơn.$b$,true),
('bunong-vn','PSA',50,15,null,$b$Jêh ri kuăl mbơh sơm vơh vơl ma Gâp tâm nar Gâp mra tâm rklaih may, jêh ri may mât ton tâm rnê ma Gâp$b$,true),
('bunong-vn','PSA',50,16,null,$b$Ƀiă lah Brah Ndu lah ma phung mhĭk pô aơ: Mâm ƀư may răk nau vay Gâp? Jêh ri ndjôt nau Gâp tâm rnglăp tâm bâr mbung may.$b$,false),
('bunong-vn','PSA',50,17,null,$b$Nanê̆ may ji nuih ma nau vay ntĭm nti Nau Gâp ngơi may mƀăr lơi pa kơi$b$,true),
('bunong-vn','PSA',50,18,null,$b$Tơ lah may saơ nơm ntung may tâm di du ai nuih đah păng. Du ai nau đah nơm văng tĭr.$b$,false),
('bunong-vn','PSA',50,19,null,$b$May mƀơk bâr mbung may ngơi nau mhĭk. Mpiăt may ngơi nau ndơm.$b$,true),
('bunong-vn','PSA',50,20,null,$b$May gŭ jêh ri ngơi ŭch ƀư ma phung oh nâu may. May ngơi nchơt ma kon bu klâu me may.$b$,true),
('bunong-vn','PSA',50,21,null,$b$Nây jêng nau may hŏ ƀư jêh, jêh ri gâp gŭ rklăk. May mĭn gâp du ai nau đah may Ƀiă lah gâp mra nduyh may. Nhhơ lĕ nau nây ta năp măt may.$b$,true),
('bunong-vn','PSA',50,22,null,$b$Ăn may mĭn ma nau aơ, Ơ phung vay chuêl Brah Ndu, klach lah Gâp sa hêk ăn rai khân may, jêh ri mâu geh nơm dơi tâm rklaih khân may.$b$,true),
('bunong-vn','PSA',50,23,null,$b$Mbu nâm nhhơr nau tâm rnê, jêng nau ƀư brah, jêng păng ăn nau chrêk rmah ma Gâp yơh. Jêh ri mbu nâm njrăng ma nau păng gŭ ngao krau sach ma nau sŏng srăng, gâp mra tâm mpơl ma păng nau Brah Ndu tâm rklaih. Nơm Tih Geh Nuih N'hâm Chah Rai Mbơh Sơm Ŭch Dăn Nau Yô̆ An Ma kôranh phung mprơ. Nau mprơ ơm Y-Đavit.$b$,true),
('bunong-vn','PSA',51,1,null,$b$Ơ Brah Ndu, yô̆ nđach ma gâp, tĭng nâm nau ueh May; Jêh ri lâm nau gâp rlau nau vay tĭng nâm nau yô̆ May toyh.$b$,true),
('bunong-vn','PSA',51,2,null,$b$Rao gâp ăn kloh ngăn nau kue gâp, Jêh ri ƀư kloh gâp ma nau tih.$b$,true),
('bunong-vn','PSA',51,3,null,$b$Yor lah gâp năl nau gâp rlau nau vay; Jêh ri nau tih gâp gŭ ta năp gâp ƀa ƀơ.$b$,true),
('bunong-vn','PSA',51,4,null,$b$Gâp ƀư tih đah May, knŏng đah May. Jêh ri gâp ƀư jêh nau mhĭk ta năp măt May. Pô ri bu mra gĭt May jêng sŏng tơ lah May mra ngơi. Jêh ri mâu geh nau bu dơi nduyh ôh tơ lah May mra phat dôih.$b$,true),
('bunong-vn','PSA',51,5,null,$b$Aơ, bu deh ma gâp tâm nau kue; Jêh ri mê̆ gâp ntreo jêh ma gâp tâm nau tih.$b$,true),
('bunong-vn','PSA',51,6,null,$b$Aơ, May ŭch ma nau răp jăp tâm nuih n'hâm; jêh ri tâm ntŭk ndâp tâm nuih n'hâm May mra ăn gâp gĭt năl nau blau mĭn.$b$,true),
('bunong-vn','PSA',51,7,null,$b$Ƀư kloh gâp ma gơ̆ hysôp jêh ri gâp mra jêng kloh; Rao gâp jêh ri gâp mra jêng nglang lơn ma dak pler.$b$,true),
('bunong-vn','PSA',51,8,null,$b$Ăn gâp tăng nau hâk răm jêh ri maak. Gay ma nting may nkêch jêh dơi geh nau hâk.$b$,true),
('bunong-vn','PSA',51,9,null,$b$Pôn muh măt ma nau tih gâp, Ăn May lâm lơi lĕ nau kue gâp.$b$,true),
('bunong-vn','PSA',51,10,null,$b$Ơ Brah Ndu njêng tâm gâp nuih n'hâm kloh; Jêh ri ƀư mhe tâm gâp huêng nâp.$b$,true),
('bunong-vn','PSA',51,11,null,$b$Lơi May nsot gâp bơh muh măt may ôh; Lơi sŏk sĭt Brah Huêng Ueh May bơh gâp.$b$,true),
('bunong-vn','PSA',51,12,null,$b$Lŏ mplơ̆ ma gâp nau răm maak geh tâm nau May tâm rklaih; Jêh ri ăn huêng nau ŭch ueh kuăn gâp.$b$,true),
('bunong-vn','PSA',51,13,null,$b$Pô ri gâp mra nti trong May ma phung rlau nau vay; jêh ri phung tih mra sĭt ta May.$b$,true),
('bunong-vn','PSA',51,14,null,$b$Ơ Brah Ndu, Brah Ndu nau tâm rklaih gâp bơh mham nkhŭt jêh; Pô ri trong gâp mra mprơ huy ma nau sŏng May.$b$,true),
('bunong-vn','PSA',51,15,null,$b$Ơ Kôranh Brah pơk trôm mbung gâp; jêh ri trôm bâr gâp mra mbơh nau tâm rnê ma May.$b$,true),
('bunong-vn','PSA',51,16,null,$b$Yor lah May mâu maak ôh ma mpa ƀư brah, gay gâp mra nhhơr ma May; Mpa nhhơr gŭch mâu ƀư maak ma May ôh.$b$,true),
('bunong-vn','PSA',51,17,null,$b$Mpa ƀư brah, ƀư maak ma Brah Ndu jêng huêng chah rai; Ơ Brah Ndu, May mâu tâm rmot ôh ma nuih n'hâm chah rai jêh ri rngot.$b$,true),
('bunong-vn','PSA',51,18,null,$b$Ƀư ueh hom ma ƀon Siôn, tâm nau May ŭch ueh; Rdâk pêr ƀon Yêrusalem.$b$,true),
('bunong-vn','PSA',51,19,null,$b$Pô ri May mra maak ma mpa ƀư brah tĭng nâm nau sŏng srăng, Ma mpa nhhơr gŭch, jêh ri ma mpa gŭch mlâm; Pô ri bu mra nhhơr ndrôk nkuăng ta nơng ƀư brah May.$b$,true),
('bunong-vn','PSA',52,1,null,$b$Ơ Bunuyh janh ktang, mâm ƀư may ntưih êng săk jăn may nơm jêng hăt janh? Nau ueh Brah Ndu hôm ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',52,2,null,$b$Mpiăt may bêng ma nau ƀai, tâm ban ma pêih bu poih ndơ, hơr ngăn blau ndơm bu.$b$,true),
('bunong-vn','PSA',52,3,null,$b$May rŏng nau mhĭk âk lơn ma nau ueh, Rŏng ngơi mƀruh, âk lơn ma ngơi ngăn$b$,true),
('bunong-vn','PSA',52,4,null,$b$Ơ mpiăt mƀruh, may rŏng ngơi nau ƀai jêh ri mpiăt nau ndơm$b$,false),
('bunong-vn','PSA',52,5,null,$b$Brah Ndu mra ƀư rai may n'ho ro. Păng mra nhŭp may jêh ri ngluh lơi may luh bơh ngih bok Jêh ri tŏk lơi may bơh neh phung rêh$b$,false),
('bunong-vn','PSA',52,6,null,$b$Phung sŏng mra saơ nau nây jêh ri klach Jêh ri mra gơm mưch ma păng, dôl lah pô aơ:$b$,false),
('bunong-vn','PSA',52,7,null,$b$Ri, jêng bunuyh mâu dơn Brah Ndu, jêng n'hâm toyh suan dăng Păng, ƀiă lah păng rnơm ma nau ndrŏng kuăng păng. Jêh ri păng rnơm nau ƀai păng, jêng nau ktang$b$,false),
('bunong-vn','PSA',52,8,null,$b$Bi gâp, gâp gŭ tâm ngih Brah Ndu jêng tơm play ôlivơ ndrêh Gâp nsing rnơm ma nau sŏng Kôranh Brah ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','PSA',52,9,null,$b$Gâp mra tâm rnê ma May ƀa ƀơ, Yor lah May ƀư jêh nau nây. Jêh ri gâp mra kâp gân tâm amoh May Ta năp măt phung kloh ueh Brah Ndu, yor nau nây jêng nau ueh lăng.$b$,true),
('bunong-vn','PSA',53,1,null,$b$Bunuyh rluk lah êng tâm nuih n'hâm Păng, Mâu geh Brah Ndu ôh. Khân păng geh kanuyh ôm rai lêk ƀư nau djơh mhĭk Mâu geh du huê ƀư nau ueh.$b$,true),
('bunong-vn','PSA',53,2,null,$b$Tă bơh trôk Brah Ndu uănh lĕ rngôch mpôl kon bunuyh. Gay ma rlong uănh phung kon bunuyh mbu nâm geh nau gĭt rbăng, joi Brah Ndu.$b$,true),
('bunong-vn','PSA',53,3,null,$b$Lĕ rngôch khân păng rŭch plơ̆ jêh ri ƀư âk nau mhĭk Mâu geh ôh nơm ƀư ueh, du huê mâu geh lĕ.$b$,true),
('bunong-vn','PSA',53,4,null,$b$Di lĕ, lĕ rngôch ƀư nau mhĭk, mâu geh nau mĭn. Khân păng sa phung ƀon lan gâp tâm ban ma sa kapŭng. Khân păng mâu kuăl mbơh sơm ma Brah Ndu ôh.$b$,true),
('bunong-vn','PSA',53,5,null,$b$Dôl nây khân păng geh nau klach ngăn ngên, ƀiă lah khân păng mâu geh ndơ gay nkrit bu. Yor lah Brah Ndu tâm nkhah lơi êng êng nting phung rlăng đah may. Khân may ăn khân păng geh nau bêk prêng Yor lah Brah Ndu dun khân păng$b$,true),
('bunong-vn','PSA',53,6,null,$b$Ơ, ŭch ngăn ma nau tâm rklaih phung Israel, luh jêh tă bơh ƀon Siôn! Tơ lah Brah Ndu njŭn sĭt phung bu nă ƀon lan Păng. Jêh ri Yakôb mra răm rhơn jêh ri Israel maak.$b$,false),
('bunong-vn','PSA',54,1,null,$b$Ơ Brah Ndu, tâm rklaih an gâp ma amoh May. Jêh ri phat an dôih gâp ma nau brah May$b$,true),
('bunong-vn','PSA',54,2,null,$b$Ơ Brah Ndu, iăt hom nau gâp mbơh sơm Rkêng tôr May, iăt lĕ nau ngơi tă bơh bâr mbung gâp$b$,false),
('bunong-vn','PSA',54,3,null,$b$Yor lah phung bu năch dâk jêh ŭch ƀư rlăng ma gâp Nơm ƀai joi huêng nau rêh gâp. Khân păng mâu ăn Brah Ndu gŭ ta năp măt khân păng (Sêla)$b$,false),
('bunong-vn','PSA',54,4,null,$b$Aơ, Brah Ndu jêng nơm koh dŏng gâp Kôranh Brah gŭ ndrel ma phung kuăn mât huêng gâp.$b$,false),
('bunong-vn','PSA',54,5,null,$b$Păng mra mplơ̆ lơi nau ƀai ta phung rlăng đah gâp Tâm nau nanê̆ May, ƀư rai hom khân păng$b$,true),
('bunong-vn','PSA',54,6,null,$b$Ơ Yêhôva gâp mra nhhơr ma May ndơ ƀư brah sân săk. Gâp mra tâm rnê ma amoh May, Yor lah păng jêng ueh.$b$,false),
('bunong-vn','PSA',54,7,null,$b$Yor lah păng tâm rklaih jêh gâp bơh lĕ rngôch nau uh ah Jêh ri măt gâp saơ jêh mâm nau gâp ŭch ăn tât ma phung rlăng đah gâp.$b$,true),
('bunong-vn','PSA',55,1,null,$b$Ơ Brah Ndu, rkêng tôr May ma nau gâp mbơh sơm. Jêh ri lơi du krap đah nau gâp kuăl vơh vơl.$b$,true),
('bunong-vn','PSA',55,2,null,$b$Iăt nau gâp jêh ri plơ̆ lah đŏng Gâp hơp hơr kuăl vơl jêh ri nđêng nhhiăng$b$,true),
('bunong-vn','PSA',55,3,null,$b$Yor bâr nơm rlăng jêh ri nau tŭn jot tă bơh phung ƀai. Yor lah khân păng ntop nau kue ma gâp. Jêh ri khân păng tĭng gâp ma nau nuih janh.$b$,false),
('bunong-vn','PSA',55,4,null,$b$Nuih n'hâm gâp bêng ma nau râm sâr tâm nuih n'hâm. Jêh ri nau klach khĭt ƀư ndrŏt gâp.$b$,true),
('bunong-vn','PSA',55,5,null,$b$Nau klach jêh ri nau nsâr tât ƀư ma gâp Nau klach jêh ri nau râm sâr nkŭm gâp.$b$,true),
('bunong-vn','PSA',55,6,null,$b$Gâp lah: Ơ, tơ lah gâp geh năr tâm ban ma plŭk. Pô ri, gâp dơi mpăr du, jêh ri geh nau đăp mpăn$b$,true),
('bunong-vn','PSA',55,7,null,$b$Di ngăn, gâp mra du ngai gâp mra gŭ tâm bri rdah$b$,false),
('bunong-vn','PSA',55,8,null,$b$Gâp mra mƀih mƀâp du krap ndal klach sial ktang, sial vănh blông$b$,false),
('bunong-vn','PSA',55,9,null,$b$Ơ Kôranh Brah, rvăn lơi khân păng jêh ri tâm rlŭk nau khân păng ngơi, Yor lah gâp saơ jêh tâm ƀon toyh geh nau ƀai jêh ri nau tâm lơh tâm dong.$b$,false),
('bunong-vn','PSA',55,10,null,$b$Măng nâm nar khân păng ƀư nau nây ndăch jum pêr ƀon nây. Nau kue jêh ri nau plăch rlăm gŭ tâm nklang păng$b$,true),
('bunong-vn','PSA',55,11,null,$b$Nau sa ƀĭt ƀer gŭ tâm nklang păng Nau tâm jot jêh ri nau ndơm mâu ƀah đah trong păng$b$,false),
('bunong-vn','PSA',55,12,null,$b$Mâu tăp nơm rlăng ma gâp ôh suai rak gâp. Tơ lah pô nây gâp dơi dơn yơh Mâu tăp nơm rlăng ma gâp tâm rmot ma gâp. Tơ lah pô nây, gâp mra du krap đah păng.$b$,false),
('bunong-vn','PSA',55,13,null,$b$Ƀiă lah may yơh jêng nơm tâm ban ma gâp. May nơm jêng băl gâp, jêh ri mĭt jiăng gâp$b$,true),
('bunong-vn','PSA',55,14,null,$b$Phung he hŏ tâm nchră ndrel ma nau ueh rŏng ngăn He hăn ndrel n'grŭp phung âk ta ngih Brah Ndu$b$,false),
('bunong-vn','PSA',55,15,null,$b$Ăn nau khĭt nhŭp khân păng gơnh ro. Ăn khân păng jur gŭ rêh tâm ntŭk phan Yor lah nau ƀai gŭ tâm ngih khân păng, tâm nklang khân păng.$b$,false),
('bunong-vn','PSA',55,16,null,$b$Bi gâp, gâp mra kuăl mbơh sơm ma Brah Ndu Jêh ri Yêhôva mra rklaih gâp.$b$,true),
('bunong-vn','PSA',55,17,null,$b$Ôi, mhaơ jêh ri nklang bôk nar, gâp mra nter vơh ma nau rngot jêh ri nđêng. Jêh ri Păng mra tăng bâr gâp.$b$,true),
('bunong-vn','PSA',55,18,null,$b$Păng tâm chuai gâp bơh nau tâm lơh, jêh ri ăn nau đăp mpăn ma gâp. Yor lah âk ngăn phung ŭch tâm lơh đah gâp$b$,true),
('bunong-vn','PSA',55,19,null,$b$Brah Ndu jêng brah, geh jêh bơh kăl e ƀa ƀơ n'ho ro, mra iăt jêh ri mplơ̆ sĭt ma khân păng (Sêla) Yor lah tâm khân păng mâu geh nau rgâl ôh. Mâu lĕ khân păng klach ma Brah Ndu.$b$,false),
('bunong-vn','PSA',55,20,null,$b$Phung mhĭk rơm ti, gay ma ƀư ma phung bunuyh geh nau đăp mpăn ndrel ma păng, păng rơih lơi nau tâm rnglăp.$b$,true),
('bunong-vn','PSA',55,21,null,$b$Bâr mbung păng ngơi sŏng ngăn. Ƀiă lah nau tâm lơh gŭ tâm nuih n'hâm păng. Nau ngơi ueh mbĭr tâm ban ma ngi Ƀiă lah jêng đao tŏk rơm lơi jêh.$b$,true),
('bunong-vn','PSA',55,22,null,$b$Juih nau jâk may ma Yêhôva, Păng mra kơl yơk nhhơr may, Păng mâu ăn phung geh nau sŏng srăng mpât n'gơ$b$,true),
('bunong-vn','PSA',55,23,null,$b$Ƀiă lah may yơh Brah Ndu, mra njŭr khân păng tâm ntu jru nau rai lôch. Phung bunuyh rung mham, jêh ri nau ndơm, nau rêh Păng mâu dơi tât klong nar tâm nal ma nau rêh păng. Kôranh Brah mra nklơ̆ khân păng tŭp tâm ntu roh rai. Ƀiă lah gâp, gâp rnơm ma Brah Ndu.$b$,false),
('bunong-vn','PSA',56,1,null,$b$Ơ Brah Ndu, yô̆ an ma gâp, Yor lah phung bunuyh ŭch rvăn gâp; Ăp nar ƀư jêr ma gâp, jêh ri ŭch tâm lơh đah gâp.$b$,true),
('bunong-vn','PSA',56,2,null,$b$Ăp nar phung rlăng đah gâp ŭch rvăn gâp. Yor lah phung ŭch tâm lơh đah gâp, âk sưr rlau$b$,true),
('bunong-vn','PSA',56,3,null,$b$Tơ lah gâp klach, gâp mra rnơm ma May$b$,false),
('bunong-vn','PSA',56,4,null,$b$Tâm Brah Ndu gâp mra tâm rnê ma nau Păng ngơi Tâm Brah Ndu gâp geh nau rnơm jêh ri mâu hôm geh nau klach ôh Bunuyh tâm nglay săk, moh nau păng dơi ƀư ma gâp$b$,false),
('bunong-vn','PSA',56,5,null,$b$Ăp nar khân păng mâu tâm di ma nau gâp ngơi Lĕ nau mĭn khân păng, ŭch ƀư mhĭk ma gâp da dê$b$,false),
('bunong-vn','PSA',56,6,null,$b$Khân păng tâm rƀŭn, khân păng yôk nchron, khân păng sek joi têl gâp. Yor lah khân păng ŭch ƀư mhĭk huêng nau rêh gâp$b$,false),
('bunong-vn','PSA',56,7,null,$b$Dơi lĕ, nau mhĭk dơi tâm rklaih khân păng? Ơ Brah Ndu, ăn hao nuih n'glưh lơi lĕ rngôch ƀon lan$b$,false),
('bunong-vn','PSA',56,8,null,$b$may kơp nhuat gâp chuat sĭt chuat hăn Dơ dak măt gâp tâm kachok may. Mâm ƀư dak măt gâp, mâu geh chih tâm ndrom samƀuêt may hĕ?$b$,false),
('bunong-vn','PSA',56,9,null,$b$Tâm nar gâp nter, phung rlăng đah gâp mra rŭch du Gâp gĭt Brah Ndu koh dŏng gâp$b$,true),
('bunong-vn','PSA',56,10,null,$b$Tâm Brah Ndu, gâp mra tâm rnê ma nau Păng ngơi Tâm Yêhôva gâp mra tâm rnê ma nau Păng ngơi$b$,false),
('bunong-vn','PSA',56,11,null,$b$Tâm Brah Ndu, gâp mra geh nau rnơm jêh ri mâu hôm geh nau klach ôh. Mâm kon bunuyh dơi ƀư ma gâp?$b$,false),
('bunong-vn','PSA',56,12,null,$b$Ơ Brah Ndu, lĕ nau gâp ton jêh đah May jêng nanê̆ ngăn Gâp mra nhhơr mpa ƀư brah ma nau rŏng ma May$b$,true),
('bunong-vn','PSA',56,13,null,$b$Yor lah may tâm rklaih jêh huêng gâp tă bơh nau khĭt Mâu di hĕ, May kuăn rdâng an jâng gâp klach tŭp. Gay ma gâp hăn ta năp măt Brah Ndu, tâm nau ang ma nau rêh.$b$,false),
('bunong-vn','PSA',57,1,null,$b$Yô̆ an ma gâp ơ Brah Ndu, yô̆ an ma gâp. Yor lah huêng gâp krap tâm May Nanê̆, gâp gŭ krap tâm dâng năr May Ăn tât nar nau mhĭk rlau lôch.$b$,true),
('bunong-vn','PSA',57,2,null,$b$Gâp mra kuăl vơh vơl ma Brah Ndu Nơm Klơ Lơn Brah Ndu nơm hŏ ƀư jêh lĕ rngôch nau dơi jêng da dê$b$,true),
('bunong-vn','PSA',57,3,null,$b$Păng mra njuăl ma gâp nau tâm rklaih tă bơh trôk, tơ lah geh nơm ŭch rvăn gâp, mâu lah soai rak gâp. Brah Ndu mra njuăl nau ueh Păng jêh ri nau nanê̆ Păng$b$,false),
('bunong-vn','PSA',57,4,null,$b$Huêng gâp gŭ tâm nklang phung yau mŭr Gâp gŭ bêch tâm nklang phung hok mpiăt ŭnh Ta nklang bunuyh geh sêk tâm ban ma tak jêh ri hăr Jêh ri mpiăt khân păng jêng tâm ban ma du mlâm đao gưm hơr ngăn.$b$,false),
('bunong-vn','PSA',57,5,null,$b$Ơ Brah Ndu ăn May geh nau n'hao prêh lơn klơ trôk Ăn nau chrêk rmah May gŭ ta klơ lĕ neh ntu.$b$,true),
('bunong-vn','PSA',57,6,null,$b$Khân păng kuyh ntu jru ta năp gâp. Huêng gâp klach jêh ri prah, khân păng kuih ntu jru ta năp gâp. Khân păng nơm tŭp jêh tâm ntu nây (Sêla)$b$,true),
('bunong-vn','PSA',57,7,null,$b$Ơ Brah Ndu, nuih n'hâm gâp nâp rjăp jêh, nuih n'hâm gâp nâp rjăp jêh. Gâp mra mprơ, di ngăn, gâp mra mprơ ma nau tâm rnê$b$,false),
('bunong-vn','PSA',57,8,null,$b$Ơ, nau chrêk rmah gâp, kah rngăl hom, Kah rngăl hom may ơ nŭng adjơl jêh ri brŏ Gâp nơm mra kah rngăl ơm lĕ.$b$,false),
('bunong-vn','PSA',57,9,null,$b$Ơ Kôranh Brah, gâp mra tâm rnê ma May tâm phung ƀon lan Mprơ tâm rnê ma Brah Ndu tâm lĕ n'gor bri$b$,true),
('bunong-vn','PSA',57,10,null,$b$Yor lah nau ueh May hao tât ta klơ trôk Jêh ri nau nanê̆ May hao tât tâm ndâr tŭk.$b$,false),
('bunong-vn','PSA',57,11,null,$b$Ơ Brah Ndu ăn May geh nau n'hao prêh lơn ma trôk. Ăn nau chrêk rmah May gŭ ta klơ lĕ neh ntu.$b$,true),
('bunong-vn','PSA',58,1,null,$b$Di lĕ tâm nau khân may gŭ rklăk, khân may ngơi nau sŏng srăng. Ơ kon bunuyh, khân may phat dôih ma nau sŏng lĕ$b$,true),
('bunong-vn','PSA',58,2,null,$b$Mâu, tâm nuih n'hâm khân may ƀư mhĭk Tâm neh ntu khân may veh nau mhĭk ti khân may ƀư.$b$,false),
('bunong-vn','PSA',58,3,null,$b$Phung ƀai tih ơm tă bơh ndŭl me khân păng Phung mbruh nhhơt trong ntơm bơh nar bu deh ma khân păng.$b$,true),
('bunong-vn','PSA',58,4,null,$b$Khân păng geh dak kăch tâm ban ma dak kăch bêh. Khân păng jêng tâm ban ma bêh rmâng tĭk sêt lơi tôr păng$b$,true),
('bunong-vn','PSA',58,5,null,$b$Păng mâu tăng ôh nau nơm rthi khân păng Nđâp tơ lah bunuyh blau rthi kđôi lĕ$b$,false),
('bunong-vn','PSA',58,6,null,$b$Ơ Brah Ndu kêch lơi sêk tâm mbung khân păng Ơ Yêhôva kêch lơi sêk neng phung kon yau mŭr$b$,false),
('bunong-vn','PSA',58,7,null,$b$Ăn khân păng jêng roh rai nâm bu dak hoch Tơ lah păng chrâng pănh, ăn hăr păng nâm bu koh lơi$b$,false),
('bunong-vn','PSA',58,8,null,$b$Ăn khân păng jêng rai lêk tâm ban ma klo lưn mâu geh rsong. Ăn khân păng jêng tâm ban ma kon bê, bu lât lơi mâu mâp saơ ang nar$b$,false),
('bunong-vn','PSA',58,9,null,$b$Lor ma lok tât ta glah khân may Gĭt lah khân păng ndrêh mâu lah ŭnh sa, păng mra ăn sial phŭt khôm lơi khân păng.$b$,false),
('bunong-vn','PSA',58,10,null,$b$Nơm sŏng mra răm maak, tơ lah păng mra saơ nau plơng bôk. Păng mra rao jâng păng ma mham phung ƀai.$b$,true),
('bunong-vn','PSA',58,11,null,$b$Bu mra lah pô aơ: Nanê̆ geh nau nkhôm ma nơm sŏng Nanê̆ geh du huê Brah Ndu phat dôih tâm neh ntu.$b$,true),
('bunong-vn','PSA',59,1,null,$b$Ơ Brah Ndu gâp, rklaih an gâp tă bơh phung rlăng King an gâp đah phung tâm rdâng ma gâp$b$,true),
('bunong-vn','PSA',59,2,null,$b$Tâm rklaih an gâp tă bơh phung ƀư mhĭk, jêh ri rklaih an gâp bơh phung ƀư nau rung mham$b$,false),
('bunong-vn','PSA',59,3,null,$b$Aơ, khân păng gŭ kâp gay nhŭp lơi huêng gâp. Phung rlăng tâm rƀŭn, ŭch ƀư mhĭk ma gâp. Mâu tăp ôh yor gâp rlau nau vay, mâu lĕ yor nau tih gâp, Ơ Yêhôva!$b$,false),
('bunong-vn','PSA',59,4,null,$b$Nđâp tơ lah gâp mâu ƀư tih, khân păng nchuăt ran ŭch dong gâp. Kah rngăl hom may, kơl gâp jêh ri uănh$b$,true),
('bunong-vn','PSA',59,5,null,$b$Ơ Yêhôva, Brah Ndu phung kôranh âk, Brah Ndu phung Israel. Dâk hom may gay ma khâl ro ăp n'gor bri. Lơi ta yô̆ du huê tâm phung ƀai nây ôh. (Sêla)$b$,false),
('bunong-vn','PSA',59,6,null,$b$Dăch kêng mhaơ khân păng plơ̆ sĭt mblu tâm ban ma so. Jêh ri hăn ndăch jum ƀon$b$,false),
('bunong-vn','PSA',59,7,null,$b$Mbung khân păng hok luh nau mhĭk Đao gưm gŭ tâm mbung khân păng Khân păng lah: Mâu geh nơm dơi tăng.$b$,false),
('bunong-vn','PSA',59,8,null,$b$Ƀiă lah, May, Ơ Yêhôva, mra gơm mưch ma khân păng May mra mưch ma lĕ rngôch mpôl băl bunuyh.$b$,true),
('bunong-vn','PSA',59,9,null,$b$Nau ktang khân păng mâm jêng kđôi lĕ, gâp mra rnơm ma May. Yor lah Brah Ndu jêng tŭm prêh gâp.$b$,true),
('bunong-vn','PSA',59,10,null,$b$Brah Ndu gâp, mra tâm mâp đah gâp ma nau ueh păng. Brah Ndu mra ăn gâp uănh nau gâp ŭch ăn mplơ̆ lơi ma phung rlăng ma gâp.$b$,true),
('bunong-vn','PSA',59,11,null,$b$Ơ Brah Ndu, jêng khêl king hên, Lơi ta nkhĭt khân păng ôh, klach phung ƀon lan gâp mra chuêl sâm nchah khân păng ma nau brah may jêh ri n'glưh lơi khân păng.$b$,true),
('bunong-vn','PSA',59,12,null,$b$Yor nau tih tă bơh mbung khân păng, jêh ri nau ngơi tă bơh trôm bâr Jêh ri, yor nau khân păng rtăp rak, jêh ri nau mƀruh khân păng ngơi. Ăn bu nhŭp khân păng, yor nau khân păng ntưih nhhưr êng khân păng nơm.$b$,true),
('bunong-vn','PSA',59,13,null,$b$Ƀư rai lơi khân păng yor nau May ji nuih, Su lơi ma ŭnh, ăn khân păng rai lêk lĕ Jêh ri ăn khân păng gĭt Brah Ndu yơh chiă uănh tâm Yakôb, tât ta dŭt bri dŭt neh. (Sêla)$b$,true),
('bunong-vn','PSA',59,14,null,$b$Tât măng ăn khân păng sĭt, ăn khân păng mblu tâm ban ma so. Jêh ri ndăch jum ƀon.$b$,false),
('bunong-vn','PSA',59,15,null,$b$Khân păng nsong văng sa lam aơ lam bri lah ê hơm khân păng mra gŭ tât măng.$b$,true),
('bunong-vn','PSA',59,16,null,$b$Ƀiă lah gâp mra mprơ ma nau brah May Nanê̆, ơm ôi gâp mra mprơ huy ma nau ueh May, Yor lah May jêng tŭm prêh gâp. Ntŭk gâp gŭ krap tâm nar rêh ni.$b$,true),
('bunong-vn','PSA',59,17,null,$b$Ma may yơh, ơ nau ktang gâp, gâp mra mprơ tâm rnê: Yor lah Brah Ndu jêng tŭm prêh gâp, Brah Ndu nơm yô̆ gâp.$b$,true),
('bunong-vn','PSA',60,1,null,$b$Ơ Brah Ndu, May dun jêh hên, May ăn hên jêng prah prŭng rŭng rai jêh. May nuih jêh, lŏ rdâk an hên đŏng$b$,true),
('bunong-vn','PSA',60,2,null,$b$May ăn neh ntu jêng sâr, jêh ri đang Lŏ nkra lơi ntŭk rluh đang yor păng n'gơ$b$,false),
('bunong-vn','PSA',60,3,null,$b$May ăn jêh phung ƀon lan saơ ndơ dăng May ăn jêh hên nhêt du ntil ndrănh nhŭl ji bôk$b$,false),
('bunong-vn','PSA',60,4,null,$b$May ăn bok rup kơ ma phung klach yơk ma May. Gay ma bu tâm mpơl păng, yor nau nanê̆. (Sêla)$b$,false),
('bunong-vn','PSA',60,5,null,$b$Gay ma nơm May rŏng, dơi geh nau tâm rklaih Tâm rklaih hên ma ti ma May, jêh ri lŏ plơ̆ lah ma hên.$b$,false),
('bunong-vn','PSA',60,6,null,$b$Brah Ndu ngơi jêh tâm nau kloh ueh păng, gâp mra dơi. Gâp mra tâm pă Sichem, gâp mra veh rlung Sulkôt$b$,true),
('bunong-vn','PSA',60,7,null,$b$Gilêat jêng ndơ gâp, Manase tâm ban lĕ Êphraim jêng n'gang bôk gâp tâm ban lĕ Yuđa jêng mâng hađăch gâp.$b$,false),
('bunong-vn','PSA',60,8,null,$b$Môab jêng ntu dak gâp um Gâp mra klŭp ndrom jâng gâp ta klơ Êđôm Ơ n'gor Phillistin, nter răm maak hom yor gâp$b$,true),
('bunong-vn','PSA',60,9,null,$b$Mbu mra njŭn leo gâp tâm ƀon nâp rjăp Mbu njŭn gâp tâm Êđôm?$b$,false),
('bunong-vn','PSA',60,10,null,$b$Ơ Brah Ndu, mâu di may hĕ dun jêh hên? Jêh ri May mâu hôm ŭch hăn ndrel ma phung tahan hên, Ơ Brah Ndu ah.$b$,true),
('bunong-vn','PSA',60,11,null,$b$Kơl koh dŏng an hên đah phung rlăng Yor lah nau bunuyh koh dŏng jêng dơm dam$b$,true),
('bunong-vn','PSA',60,12,null,$b$Ma Brah Ndu he ƀư dơi lĕ rngôch Yor lah Păng yơh mra jot blên phung rlăng.$b$,false),
('bunong-vn','PSA',61,1,null,$b$Ơ Brah Ndu gŭ iăt nau gâp nter, Gŭ iăt rklêng ma nau gâp mbơh sơm,$b$,true),
('bunong-vn','PSA',61,2,null,$b$Tă bơh dŭt bri neh, gâp mra kuăl May lah nuih n'hâm gâp rdja jêh. Njŭn gâp ta lŭ prêh lơn ma gâp$b$,false),
('bunong-vn','PSA',61,3,null,$b$Yor lah may jêng ntŭk gâp gŭ krap Du play ngih tŭm nâp ta năp phung rlăng.$b$,false),
('bunong-vn','PSA',61,4,null,$b$Gâp mra gŭ tâm ngih bok May ƀa ƀơ Gâp mra hăn krap tâm dâng năr May$b$,true),
('bunong-vn','PSA',61,5,null,$b$Ơ Brah Ndu Yor lah May tăng jêh nau gâp ton Hŏ ăn jêh ma gâp drăp ndơ krâm ndrel ma phung klach yơk ma amoh May.$b$,false),
('bunong-vn','PSA',61,6,null,$b$May mra ntop nar ma phung hađăch gŭ rêh, năm păng tâm âk rnôk.$b$,true),
('bunong-vn','PSA',61,7,null,$b$May mra gŭ ta năp Brah Ndu ƀa ƀơ n'ho ro. Hơi, Brah Ndu, dăn ma May rơm ndrăp nau nanê̆ chiă uănh păng$b$,true),
('bunong-vn','PSA',61,8,null,$b$Pô ri, gâp mra mprơ tâm rnê amoh Brah Ndu ƀa ƀơ. Jêh ri ăp nar gâp ƀư ăn num lĕ nau gâp ton.$b$,false),
('bunong-vn','PSA',62,1,null,$b$Huêng gâp gŭ rklăk tâm nau kâp gân ma Brah Ndu. Tă bơh Păng gâp geh nau tâm rklaih$b$,true),
('bunong-vn','PSA',62,2,null,$b$Knŏng êng Păng jêng lŭ gâp, jêh ri nau tâm rklaih gâp Păng jêng tŭm prêh gâp, jêng ntŭk gâp krap Gâp mâu hôm mpât n'gơ âk ôh.$b$,false),
('bunong-vn','PSA',62,3,null,$b$Dŭm nau jŏ may ƀư ma du huê bunuyh. Gay ma lĕ rngôch lơh ăn rlâm Nâm bu mpir ngih tâm ban ma pêr bu nklơ̆ lơi.$b$,true),
('bunong-vn','PSA',62,4,null,$b$Khân păng tâm nchră gay ma nklơ̆ lơi păng cha lôt tă bơh ntŭk bu yơk mbah. Khân păng rŏng ma nau mƀruh. Khân păng mât ton ma bâr mbung khân păng, ƀiă lah tâm nuih n'hâm khân păng rtăp rak (Sêla)$b$,true),
('bunong-vn','PSA',62,5,null,$b$Ơ huêng gâp, gŭ rklăk hom tâm nau kâp gân knŏng ma Brah Ndu. Yor lah tă bơh Păng luh nau gâp kâp gân$b$,false),
('bunong-vn','PSA',62,6,null,$b$Knŏng êng Păng yơh jêng lŭ gâp jêh ri nau tâm rklaih gâp. Păng jêng tŭm gâp, gâp mâu mra mpât n'gơ ôh.$b$,false),
('bunong-vn','PSA',62,7,null,$b$Nau tâm rklaih jêh ri nau chrêk rmah gâp gŭ tâm Brah Ndu$b$,true),
('bunong-vn','PSA',62,8,null,$b$Ơ phung ƀon lan, rnơm hom ma Păng nkhŭt lĕ nuih n'hâm ta năp măt Păng. Brah Ndu jêng ntŭk he mbe krap. (Sêla)$b$,false),
('bunong-vn','PSA',62,9,null,$b$Nanê̆ phung bunuyh bu mâu vay yơk mbah, jêng dơm dam, nđâp ma phung bu yơk mbah ma nau mƀruh. Khân păng mra hao tâm njing, khân păng jêng n'gơch lơn ma n'hâm,$b$,false),
('bunong-vn','PSA',62,10,null,$b$Lơi ta rnơm ma nau bu tŭn jot, Lơi ăn nuih n'hâm rnơm ma nau sŏk ntung Tơ lah drăp ndơ khân may geh âk rmeh, lơi ăn nuih n'hâm khân may rnơm ma nau nây ôh.$b$,false),
('bunong-vn','PSA',62,11,null,$b$Brah Ndu lah jêh du tơ̆ Jêh ri gâp tăng nau nây bar tơ̆ pô aơ. Nau ktang jêng ndơ Brah Ndu.$b$,true),
('bunong-vn','PSA',62,12,null,$b$Tâm ban lĕ, ơ Kôranh Brah, nau ueh jêng ndơ May. Yor lah May mplơ̆ lơi ma ăp nơm tĭng nâm nau păng ƀư.$b$,true),
('bunong-vn','PSA',63,1,null,$b$Ơ Brah Ndu, May jêng Brah Ndu gâp, gâp joi May ma lĕ nuih n'hâm. Huêng gâp ji hir ma May, nglay săk gâp nđêng ma May Tâm neh duh, sơh, mâu geh dak$b$,true),
('bunong-vn','PSA',63,2,null,$b$Pô ri gâp gŭ uănh May tâm ngih bok gay ma saơ nau brah jêh ri nau chrêk rmah May$b$,false),
('bunong-vn','PSA',63,3,null,$b$Yor nau ueh May khlay lơn ma nau huêng rêh. Bâr mbung gâp mra tâm rnê ma May$b$,false),
('bunong-vn','PSA',63,4,null,$b$Pô ri gâp mra tâm rnê lah ueh ma May tâm lĕ nau rêh gâp Gâp mra yơr ti gâp tâm amoh May$b$,false),
('bunong-vn','PSA',63,5,null,$b$Huêng gâp mra hơm, tâm ban ma sa glo tâm nting Bâr mbung gâp mra tâm rnê ma May ma nau răm maak$b$,false),
('bunong-vn','PSA',63,6,null,$b$Dôl gŭ bêch klơ sưng gâp kah gĭt ma May Jêh ri gŭ mĭn rvê ma May mro tâm măng.$b$,false),
('bunong-vn','PSA',63,7,null,$b$Yor lah May koh dŏng gâp jêh. Jêh ri gâp gŭ răm maak tâm dâng nar brah May.$b$,true),
('bunong-vn','PSA',63,8,null,$b$Huêng gâp tĭng ndô̆ May ma lĕ nuih n'hâm Ti ma kuăn rdâng gâp.$b$,true),
('bunong-vn','PSA',63,9,null,$b$Mbu nâm joi nau ƀư mhĭk ma huêng nau rêh gâp. Mra tŭp tâm brŏng nau rai yot neh ntu.$b$,true),
('bunong-vn','PSA',63,10,null,$b$Đao gưm mra sreh khân păng Khân păng mra jêng mpa so bri sa.$b$,true),
('bunong-vn','PSA',63,11,null,$b$Ƀiă lah hađăch mra hâk răm tâm Brah Ndu. Ăp nơm, bu nâm dŏng amoh gâp ma nau ton săk nơm; Yor mbung phung mƀruh mra mêm lơi.$b$,true),
('bunong-vn','PSA',64,1,null,$b$Ơ Brah Ndu gŭ iăt bâr gâp, lah gâp nter vơh vơl N'gang an nau rêh gâp bơh nau klach ma phung rlăng$b$,true),
('bunong-vn','PSA',64,2,null,$b$Pôn an gâp ma nau phung ƀư mhĭk tâm nchră tâm ntŭk ndâp Ma phung bunuyh kue ƀư drưh$b$,false),
('bunong-vn','PSA',64,3,null,$b$Khân păng tôl mpiăt ndôi hơr nâm bu đao gưm Nau khân păng ngơi, nâm bu rjăng hăr mplanh, nau ngơi tăng.$b$,false),
('bunong-vn','PSA',64,4,null,$b$Gay ma pănh phung mâu geh nau tih tă bơh ntŭk ndâp Ƀât lât khân păng pănh jêh ri khân păng mâu klach ôh$b$,true),
('bunong-vn','PSA',64,5,null,$b$Khân păng ƀư ktang êng khân păng nơm tâm nau ƀư ƀai. Khân păng tâm nchră sân dăk, Khân păng lah, mbu nâm mra saơ ndơ nây?$b$,false),
('bunong-vn','PSA',64,6,null,$b$Khân păng ƀư âk nau kue toyh; Khân păng lah, hên nkra jêh nau hên ŭch ƀư Nau mĭn ndâp tâm săk, jêh ri nuih n'hâm ăp nơm jru ngăn.$b$,true),
('bunong-vn','PSA',64,7,null,$b$Ƀiă lah Brah Ndu mra rjăng hăr ma khân păng ƀât lât hăr mra geh tât ta khân păng nơm ro.$b$,true),
('bunong-vn','PSA',64,8,null,$b$Mpiăt khân păng nơm ƀư tŭp khân păng Lĕ rngôch saơ khân păng mra rteh bôk$b$,true),
('bunong-vn','PSA',64,9,null,$b$Lĕ rngôch bu nuyh mra klach; Jêh ri khân păng mra mbơh, moh nau Brah Ndu ƀư jêh. Jêh ri mra mĭn ma nau păng ƀư jêh.$b$,false),
('bunong-vn','PSA',64,10,null,$b$Nơm sŏng mra geh nau răm maak tâm Yêhôva jêh ri mra krap tâm păng. Jêh ri lĕ rngôch phung geh nuih n'hâm sŏng mra bêng ma nau hâk răm. Nau Ueh Uĭn Brah Ndu Ăn Ma Neh Ntu,$b$,true),
('bunong-vn','PSA',65,1,null,$b$Ơ Brah Ndu, bu kâp ta ƀon Siôn gay ma tâm rnê ma May. Jêh ri bu mra ăn nanê̆ nau păng ton jêh ma May$b$,true),
('bunong-vn','PSA',65,2,null,$b$Ơ Nơm gŭ iăt nau mbơh sơm Lĕ rngôch nglay săk mra tât ta May.$b$,false),
('bunong-vn','PSA',65,3,null,$b$Nau djơh mhĭk dơi lơn ma gâp May mra yô̆ an nau hên rlau nau vay.$b$,true),
('bunong-vn','PSA',65,4,null,$b$Ueh maak ngăn nơm May săch, jêh ri ăn păng hăn ta May Gay ăn păng gŭ tâm nkual ngih May. Hên mra hơm ma nau ueh tă bơh ngih May. Ngih brah kloh ueh May.$b$,true),
('bunong-vn','PSA',65,5,null,$b$Ơ Brah Ndu ma nau tâm rklaih hên, lŏ plơ̆ lah ma hên ma nau sŏng srăng. May jêng nau rnơm ma lĕ rngôch dŭt neh ntu, Nđâp ma phung gŭ ngai tâm dak rlai$b$,true),
('bunong-vn','PSA',65,6,null,$b$Brah Ndu dŏng, nau dơi păng rdâk ăn nâp lĕ yôk. Păng rêt păng nơm ma rse bŭt nau brah$b$,false),
('bunong-vn','PSA',65,7,null,$b$păng buay lĕ sial ktang tâm dak rlai Mpiăt dak khuh ƀư nteh. Nau kon bunuyh ƀư uh ah.$b$,false),
('bunong-vn','PSA',65,8,null,$b$Phung gŭ ta ntŭk dŭt bri, neh geh nau klach ma nau tâm mbên May, May ăn mông ƀhit rvi ang, jêh ri mông nar nhâp geh nau răm maak.$b$,true),
('bunong-vn','PSA',65,9,null,$b$May văch khâl neh ntu, jêh ri djrah păng bĕ May ăn păng jêng ndrŏng. N'hor dak Brah Ndu geh âk dak Jêh Brah Ndu rhăk njêng neh ntu, May ăn ba ma khân păng$b$,true),
('bunong-vn','PSA',65,10,null,$b$May djrah dak ta kau kai, May châm ăn rai glo neh May djrah ăn rdơ̆ neh ma dak mih May ăn ndơ ueh hon ta klơ neh$b$,false),
('bunong-vn','PSA',65,11,null,$b$May ƀư lôch dŭt năm ma nau ueh May Nhuat May nkhŭt mbêng rmeh ler.$b$,false),
('bunong-vn','PSA',65,12,null,$b$Khân păng nkhŭt jêh ta gơ̆ nse tâm bri rdah, Jêh ri yôk dor geh nau hâk maak ndrel$b$,true),
('bunong-vn','PSA',65,13,null,$b$Ndrêch gơ̆ nse bêng ma phung biăp, Jêh ri rlŭng nkŭm ma ba. Khân păng nter maak, khân păng mprơ tâm ban lĕ. Tâm Rnê Ma Brah Ndu Yor Kan Brah Păng Ƀư Jêh Ri Yor Nau Mbơh Sơm Ma kôranh phung mprơ. Du nau mprơ ơm.$b$,false),
('bunong-vn','PSA',66,1,null,$b$Ơ lĕ neh ntu, nter răm hom ma Brah Ndu$b$,true),
('bunong-vn','PSA',66,2,null,$b$Mprơ hom nau chrêk rmah ma amoh Păng Tâm rnê jêh ri yơk mbah ma Brah Ndu$b$,false),
('bunong-vn','PSA',66,3,null,$b$lah ma Brah Ndu pô aơ: “Kon may toyh ngăn ngên! Phung rlăng đah may mra sĭt lăp may.$b$,false),
('bunong-vn','PSA',66,4,null,$b$Lĕ neh ntu mra mbah yơk ma May, jêh ri mprơ tâm rnê ma May. Khân păng mprơ tâm rnê ma amoh May. (Sêla)$b$,true),
('bunong-vn','PSA',66,5,null,$b$Văch jêh ri uănh lĕ nau Brah Ndu ƀư. Khân păng ƀư ma kon bunuyh jêng khlay ngăn.$b$,false),
('bunong-vn','PSA',66,6,null,$b$Păng tâm rgâl dak rlai jêng neh sơh Khân păng hăn jâng rgăn dak krong. Yor nau nây he geh nau răm maak tâm Păng.$b$,true),
('bunong-vn','PSA',66,7,null,$b$Păng chiă uănh n'ho ro ma nau brah Păng Măt Păng sek uănh lĕ mpôl băl bunuyh Lơi ta ăn phung rlăng n'hao êng khân păng (Sêla)$b$,true),
('bunong-vn','PSA',66,8,null,$b$Ơ phung bunuyh ƀon lan tâm rnê hom ma Brah Ndu he. Ăn bu iăt bâr ma nau tâm rnê Păng.$b$,false),
('bunong-vn','PSA',66,9,null,$b$Păng yơh mât huêng he gŭ rêh. Mâu ăn jâng he mpât.$b$,true),
('bunong-vn','PSA',66,10,null,$b$Yor lah May long uănh jêh hên, ơ Kôranh Brah ah. Đăp nti hên tâm ban ma bu nkra prăk$b$,true),
('bunong-vn','PSA',66,11,null,$b$May njŭn jêh hên tâm jal. Dăp ndơ ăn hên anh jâk ngăn.$b$,false),
('bunong-vn','PSA',66,12,null,$b$Brah Ndu ăn bu ncho seh ta klơ bôk hên. Hên rgăn jêh ŭnh jêh ri dak Ƀiă lah Brah Ndu njŭn leo hên ta ntŭk ndrŏng kuăng.$b$,true),
('bunong-vn','PSA',66,13,null,$b$Gâp mra lăp tâm ngih brah May ma ndơ ƀư brah gŭch. Gâp mra mplơ̆ ăn lĕ nau gâp ton jêh ma May$b$,true),
('bunong-vn','PSA',66,14,null,$b$Nau bâr mbung gâp hŏ ton jêh Jêh ri bâr mbung gâp hŏ ngơi jêh dôl geh nau uh ah.$b$,false),
('bunong-vn','PSA',66,15,null,$b$Gâp mra nhhơr ma may biăp lay jêng mpa ƀư brah gŭch, Ma ngi biăp nkuăng; gâp mra nhhơr ndrôk nkuăng, nđâp ma biăp nkuăng. (Sêla)$b$,true),
('bunong-vn','PSA',66,16,null,$b$Ơ phung blau klach yơk mbah ma Brah Ndu, hăn iăt hom Jêh ri gâp mra nkoch bri moh nau păng ƀư jêh ma huêng gâp.$b$,false),
('bunong-vn','PSA',66,17,null,$b$Gâp kuăl mbơh sơm jêh ma Păng ma bâr mbung gâp. Jêh ri mpiăt gâp mprơ tâm rnê ma Păng$b$,true),
('bunong-vn','PSA',66,18,null,$b$Tơ lah nuih n'hâm gâp geh nau mĭn mhĭk. Kôranh Brah mâu mra iăt nau gâp ôh.$b$,false),
('bunong-vn','PSA',66,19,null,$b$Ƀiă lah nanê̆ Brah Ndu hŏ tăng jêh; păng rkêng jêh tôr, iăt nau, iăt bâr gâp ngơi.$b$,true),
('bunong-vn','PSA',66,20,null,$b$Mât ton tâm rnê ma Brah Ndu. Păng mâu mâp dun ôh nau gâp kuăl mbơh sơm Mâu lĕ păng sŏk sĭt lơi nau ueh Păng tâm gâp.$b$,true),
('bunong-vn','PSA',67,1,null,$b$Ăn Brah Ndu yô̆ an ma hên. Jêh ri ăn nau ueh lăng ma hên. Nau chrêk rmah muh măt păng, sol nchrat tâm hên. (Sêla)$b$,true),
('bunong-vn','PSA',67,2,null,$b$gay ma bu dơi năl trong May tâm neh ntu aơ Nau May tâm rklaih lĕ mpôl bunuyh lam bri neh.$b$,false),
('bunong-vn','PSA',67,3,null,$b$Ăn phung ƀon lan tâm rnê ma May, Ơ Brah Ndu! Ăn lĕ rngôch bunuyh tâm rnê ma May.$b$,true),
('bunong-vn','PSA',67,4,null,$b$Ăn lĕ rngôch bunuyh răm maak mprơ tâm rnê ma May. Yor lah May mra phat dôih phung ƀon lan ma nau sŏng Jêh ri njŭn leo phung mpôl băl tâm neh ntu.$b$,true),
('bunong-vn','PSA',67,5,null,$b$Ăn phung ƀon lan tâm rnê ma May, Ơ Brah Ndu. Lĕ rngôch bunuyh tâm rnê ma May.$b$,true),
('bunong-vn','PSA',67,6,null,$b$Neh ntu hon geh play khlay Brah Ndu jêng Brah Ndu phung hên, mra ăn nau ueh lăng ma hên.$b$,true),
('bunong-vn','PSA',67,7,null,$b$Brah Ndu mra ăn nau ueh lăng ma hên Jêh ri lĕ ntŭk bri neh mra klach yơk ma Păng.$b$,true),
('bunong-vn','PSA',68,1,null,$b$Ăn Brah Ndu dâk, jêh ri phung rlăng păng mra nchuăt du.$b$,true),
('bunong-vn','PSA',68,2,null,$b$Ăn khân păng roh rai nâm bu nhhŭk ŭnh. Tâm ban ma mpêt lêk tâm ŭnh Nâm nđĕ yơh, ăn phung ƀai roh rai ta năp măt Brah Ndu.$b$,true),
('bunong-vn','PSA',68,3,null,$b$Ƀiă lah phung sŏng mra răm maak ta năp măt Brah Ndu. Nanê̆ ăn khân păng maak ma nau răm rhơn.$b$,true),
('bunong-vn','PSA',68,4,null,$b$Mprơ hom ma Brah Ndu, mprơ tâm rnê hom ma amoh Păng Nkra hom ăn lâng trong, ăn Kôranh Brah ncho seh hăn rgăn bri rdah. Yêhôva jêng amoh Kôranh Brah, ăn geh nau răm maak ta năp măt Păng.$b$,true),
('bunong-vn','PSA',68,5,null,$b$Mbơ̆ ma phung kon đơi, nơm n'gang phung bu ur khĭt sai$b$,true),
('bunong-vn','PSA',68,6,null,$b$Brah Ndu ăn ma phung rêh rngloi geh ngih gŭ. ta năp phung ƀon lan May$b$,false),
('bunong-vn','PSA',68,7,null,$b$Tơ lah May hăn tâm bri rdah (Sêla)$b$,false),
('bunong-vn','PSA',68,8,null,$b$Neh ntu nsâr, Trôk tŭp ta năp măt Brah Ndu Yôk Sinai n'gơ ta năp măt Brah Ndu,$b$,false),
('bunong-vn','PSA',68,9,null,$b$Ơ Brah Ndu, ăn dak mih tŭp âk May ƀư ăn ktang drăp ndơ may krâm, tơ lah păng rgănh jêh.$b$,false),
('bunong-vn','PSA',68,10,null,$b$Phung ƀon lan May gŭ ta nây, Ơ Brah Ndu, tâm nau ueh May, may nkra jêh ma phung o ach.$b$,true),
('bunong-vn','PSA',68,11,null,$b$Kôranh Brah ntăm nau Lĕ phung bu ur hăn mbơh nau mhe mhan ueh jêng du phung âk ngăn.$b$,true),
('bunong-vn','PSA',68,12,null,$b$Phung hađăch geh tahan nchuăt du, nchuăt du. Phung bu ur hôm gŭ tâm ngih pă drăp ndơ$b$,true),
('bunong-vn','PSA',68,13,null,$b$Tơ lah khân may gŭ rlu tâm nklang ndrung biăp. Khân may mra jêng nâm bu năr plŭk nsrom ma prăk. Jêh ri rsau păng êr tâm ban ma mah.$b$,false),
('bunong-vn','PSA',68,14,null,$b$Tơ lah nơm Brah lơn tâm nchah du phung hađăch ta nây Neh jêng nglang tâm ban ma pler ta yôk Salmôn.$b$,true),
('bunong-vn','PSA',68,15,null,$b$Yôk Basan jêng yôk Brah Ndu. Yôk Basan geh âk ntŭk prêh.$b$,true),
('bunong-vn','PSA',68,16,null,$b$Ơ lĕ yôk geh âk ntŭk prêh, mâm ƀư khân may n'gơr ma nau kơnh Jêng yôk Brah Ndu săch ƀư ntŭk gŭ. Nanê̆ Yêhôva mra gŭ ta nây mro mrăng.$b$,true),
('bunong-vn','PSA',68,17,null,$b$Mrô ndeh seh Yêhôva âk, bar âk rbăn rmưn, jêh ri âk rbăn. Kôranh Brah gŭ tâm nklang khân păng, yôk Siani gŭ tâm ntŭk kloh ueh.$b$,true),
('bunong-vn','PSA',68,18,null,$b$Kôranh Brah hŏ gŭ jêh klơ prêh, may njŭn leo phung bu nă may sŏk dơn mpa ăn ta nklang bunuyh, Nđâp ta nklang phung dăng bôk, gay ma Yêhôva, Brah Ndu gŭ ndrel ma khân păng.$b$,true),
('bunong-vn','PSA',68,19,null,$b$Mât ton ma Brah Ndu ăp nar. Jêng Brah kơl mbăk an ndơ jâk he ăp nar. Jêh ri Kôranh Brah Ndu, jêng nau tâm rklaih hên.$b$,true),
('bunong-vn','PSA',68,20,null,$b$Yor lah Brah Ndu, jêng Brah Ndu tâm rklaih he Nây jêng yor nau Brah Yêhôva, kon bunuyh geh nau rklaih bơh nau khĭt.$b$,true),
('bunong-vn','PSA',68,21,null,$b$Ƀiă lah Brah Ndu mra jot ăn chah bôk phung ƀư rlăng đah păng. Ŭch ƀư ma phung hôm tĭng nau tih.$b$,true),
('bunong-vn','PSA',68,22,null,$b$Kôranh Brah lah: Tă bơh yôk Basan gâp mra njŭn khân păng sĭt. Gâp njŭn khân păng ngai đah dak rlai jru.$b$,true),
('bunong-vn','PSA',68,23,null,$b$Gay ma jot blên ma jâng tâm mham. Jêh ri mpiăt so may dơi ler sa nglay puăch phung rlăng đah may.$b$,true),
('bunong-vn','PSA',68,24,null,$b$Ơ Brah Ndu, khân păng hŏ saơ trong May Nau Brah Ndu gâp, hađăch gâp, hăn tâm ntŭk kloh ueh.$b$,true),
('bunong-vn','PSA',68,25,null,$b$Phung mprơ hăn lor, phung uh dĭng groi kơi Tâm nklang geh phung bu ur druh goh gâr.$b$,true),
('bunong-vn','PSA',68,26,null,$b$Mât ton tâm rnê ma Brah Ndu tâm nau tâm rƀŭn. Mât ton ma Kôranh Brah khân may, phung kon sau Israel Mât ton tâm rnê ma Brah Ndu jêng Brah$b$,true),
('bunong-vn','PSA',68,27,null,$b$Aơ, Benjamin hôm ndăm, chiă uănh khân păng Phung kon hađăch Yuđa, jêh ri phung păng Phung kon hađăch Sabulôn jêh ri phung kon hađăch Neptali.$b$,false),
('bunong-vn','PSA',68,28,null,$b$Brah Ndu may, ăn n'hâm toyh suan dăng ma may. Ơ Brah Ndu, dăn May ƀư ăn nâp kan May hŏ ƀư jêh ma hên.$b$,true),
('bunong-vn','PSA',68,29,null,$b$Yor ngih Brah May ta ƀon Yêrusalem Phung hađăch mra njŭn leo mpa nhhơr ma May.$b$,true),
('bunong-vn','PSA',68,30,null,$b$Nduyh ma mpa bri gŭ tâm rpho Âk phung ndrôk kon nkuăng phung ƀon lan. Jêng phung tât geh nhhơr rlay prăk khlay Păng ntrŭt lơi phung ŭch ma nau tâm lơh$b$,true),
('bunong-vn','PSA',68,31,null,$b$Phung kon hađăch mra luh tă bơh Êjipt. Phung Êthiôpi mƀih mƀâp yơr ti ma Brah Ndu.$b$,false),
('bunong-vn','PSA',68,32,null,$b$Ơ phung ƀon bri hađăch ta neh ntu, mprơ hom ma Brah Ndu. Mprơ tâm rnê hom ma Kôranh Brah (Sêla)$b$,true),
('bunong-vn','PSA',68,33,null,$b$Ma nau hăn hao ta klơ trôk, ma phung trôk, trôk kăl e ri. Aơ, păng ăn bu iăt bâr păng, bâr brah păng.$b$,false),
('bunong-vn','PSA',68,34,null,$b$Ăn nau ktang ma Brah Ndu Nau rnam păng tâm phung Israel, jêh ri nau rnam păng tâm trôk.$b$,true),
('bunong-vn','PSA',68,35,null,$b$Khư ma nau klach tâm ntŭk kloh ueh May. Brah Ndu phung Israel, khư ăn nau dơi ma phung ƀon lan păng. Mât ton ma Brah Ndu.$b$,true),
('bunong-vn','PSA',69,1,null,$b$Ơ Brah Ndu rklaih an gâp ƀă. Yor lah dak lip tât jêh ta huêng gâp.$b$,true),
('bunong-vn','PSA',69,2,null,$b$Gâp rluh tâm bŏk jru mâu blau dŭt Gâp lĕ ngâm tâm dak jru, gâp rmok tâm dak jru.$b$,true),
('bunong-vn','PSA',69,3,null,$b$Gâp nter kŏ rgănh, lĕ kroh hôt mbung gâp. Muh măt gâp huănh dôl kâp Brah Ndu gâp.$b$,true),
('bunong-vn','PSA',69,4,null,$b$Phung ji nuih ma gâp, mâu geh nau. Âk lơn ma sŏk tâm bôk. Phung rlăng ma gâp, mâu geh, mâu geh nau ŭch ƀư ƀai ma gâp hâu ngăn. Bu đă gâp ntrok ndơ gâp mâu mâp ntŭng$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PSA',69,5,null,$b$Ơ Brah Ndu gâp, May gĭt jêh nau rluk mâl gâp Lĕ nau tih gâp mâu dơi pôn ma may ôh.$b$,false),
('bunong-vn','PSA',69,6,null,$b$Ơ Kôranh Brah Yêhôva tahan âk, lơi ăn phung kâp gân may prêng yor gâp. Ơ Brah Ndu Israel$b$,true),
('bunong-vn','PSA',69,7,null,$b$Yor May gâp anh nau bu suai rak, bir srơh, nau bêk prêng nkŭm muh măt gâp.$b$,false),
('bunong-vn','PSA',69,8,null,$b$Nâm bu, gâp jêng bu năch đah phung oh nâu gâp. Jêng du huê tâm phung kon me gâp mâu gĭt năl.$b$,true),
('bunong-vn','PSA',69,9,null,$b$Yor nau huch rhuêl ma ngih may rvăn lơi gâp Nau ngơi bir-srơh tă bơh nơm suai rak may hŏ nkhŭt jêh tâm gâp.$b$,true),
('bunong-vn','PSA',69,10,null,$b$Gâp nhĭm jêh ri ât sa gay ma nchâp huêng gâp Nau nây ăt jêng ƀư nau bir srơh ma gâp.$b$,true),
('bunong-vn','PSA',69,11,null,$b$Gâp sŏk ƀau lok soh ƀư ao jâr, jêng nau ngơi hôr ma khân păng.$b$,true),
('bunong-vn','PSA',69,12,null,$b$Phung gŭ ta mpông pêr ăt nkoch bri yor ma gâp. Jêh ri phung nhŭl ndrănh ngơi n'găp rlơn ma gâp, tâm nau khân păng mprơ.$b$,true),
('bunong-vn','PSA',69,13,null,$b$Ƀiă lah, Ơ Yêhôva ơi! Gâp ndăn rnôk nơih, gay mbơh sơm ma May Kôranh Brah Ndu ơi, tĭng nâm nau yô̆ toyh tă bah May.$b$,true),
('bunong-vn','PSA',69,14,null,$b$Dăn kơl gâp, lơi ăn rluh tâm bŏk jru. Dăn ăn gâp dơi du ngai đah phung vay ji nuih ma gâp, jêh ri đah dak jru$b$,true),
('bunong-vn','PSA',69,15,null,$b$Lơi ăn gâp rmok tâm dak sial njach, lơi lĕ ăn gâp tŭp tâm brŏng jru. Lơi ta nkŭm bâr ntu gâp.$b$,false),
('bunong-vn','PSA',69,16,null,$b$Ơ Yêhôva, lŏ plơ̆ lah an ma gâp. Yor lah nau ueh May jêng toyh ngăn. Tĭng nâm nau May yô̆ toyh ma gâp, May n'gĭl uănh gâp bă.$b$,true),
('bunong-vn','PSA',69,17,null,$b$Lơi ta May pôn măt đah phung oh mon May. Tâm nar gâp geh nau rêh ni may plơ̆ lah ma gâp ăn gơnh.$b$,true),
('bunong-vn','PSA',69,18,null,$b$Dăn Kôranh Brah hăn dăch ta huêng gâp jêh ri sâm chuai an păng. Tâm chuai an gâp yor phung rlăng gâp.$b$,true),
('bunong-vn','PSA',69,19,null,$b$May gĭt nau bir-srơh, bêk prêng, prêng jum gâp Lĕ phung rlăng ma gâp gŭ ta năp măt May.$b$,true),
('bunong-vn','PSA',69,20,null,$b$Nau suai rak nchah jêh nuih n'hâm gâp, jêh ri gâp jêng ji kuet Gâp kâp gân nơm yô̆ ma gâp, ƀiă lah mâu geh du huê.$b$,true),
('bunong-vn','PSA',69,21,null,$b$Khân păng ăn ma gâp ndơ sa tăng Jêh ri tơ lah gâp ji hir, khân păng ăn nhêt dak srat.$b$,true),
('bunong-vn','PSA',69,22,null,$b$Ăn sưng sông sa ta năp khân păng jêng sân dăk ma khân păng nơm. Tâm nklang nau đăp mpăn khân păng geh jal$b$,true),
('bunong-vn','PSA',69,23,null,$b$Măt khân păng jêng ngo, tât mâu hôm dơi saơ, Jêh ri nau May nuih ăn khân păng râm sâr mro.$b$,false),
('bunong-vn','PSA',69,24,null,$b$Nkhŭt nau May, nuih janh tâm khân păng Ăn nau May nuih ktang ma khân păng.$b$,true),
('bunong-vn','PSA',69,25,null,$b$Ăn ntŭk khân păng gŭ jêng rngol Jêh ri mâu hôm geh bunuyh gŭ tâm ngih bok khân păng ôh.$b$,true),
('bunong-vn','PSA',69,26,null,$b$Yor lah khân păng ƀư mhĭk jêh ma nơm May dong Jêh ri khân păng nkoch bri nau rêh ni phung May ƀư sôt rmanh jêh.$b$,true),
('bunong-vn','PSA',69,27,null,$b$Dăn Kôranh Brah lŏ ntop nau tih ma nau tih khân păng. Lơi ăn khân păng lăp tâm nau sŏng srăng May.$b$,true),
('bunong-vn','PSA',69,28,null,$b$Lâm lơi amoh khân păng, bơh ndrom sambuêt nau rêh. Mâu dơi chih ndrel ma phung sŏng.$b$,true),
('bunong-vn','PSA',69,29,null,$b$Ƀiă lah gâp jêng o ach jêh ri rêh ni Ơ Brah Ndu dăn nau May tâm rklaih n'gang an gâp.$b$,true),
('bunong-vn','PSA',69,30,null,$b$Gâp mra tâm rnê ma Brah Ndu tâm nau gâp mprơ. Gâp mra mât ton ma păng ma nau tâm rnê.$b$,true),
('bunong-vn','PSA',69,31,null,$b$Nau nây mra maak lơn ma Yêhôva, rlau lơn ma nau ƀư brah ma ndrôk nkuăng. Mâu lah du mlâm ndrôk nkuăng geh nke jêh ri nchop.$b$,true),
('bunong-vn','PSA',69,32,null,$b$Phung tông bâr mra saơ nau nây jêh ri maak Ơ phung joi Brah Ndu ăn nuih n'hâm khân may gŭ rêh.$b$,true),
('bunong-vn','PSA',69,33,null,$b$Yor lah Brah Ndu iăt nau phung o ach Jêh ri păng mâu tâm rmot ma phung bu nă păng.$b$,true),
('bunong-vn','PSA',69,34,null,$b$Ăn trôk, neh ntu, dak rlai Jêh ri lĕ mpô mpa tâm Păng, tâm rnê ma Păng da dê.$b$,true),
('bunong-vn','PSA',69,35,null,$b$Yor lah Brah Ndu mra tâm rklaih Siôn, jêh ri lŏ rdâk njêng phung ƀon Yuđa. Ƀon lan mra gŭ ta nây jêh ri khân păng mra geh neh ntu ta nây.$b$,true),
('bunong-vn','PSA',69,36,null,$b$Phung oh kon, phung oh mon păng mra krâm n'gor nây. Jêh ri phung rŏng ma amoh păng mra gŭ ta nây.$b$,true),
('bunong-vn','PSA',70,1,null,$b$Ơ Brah Ndu, dăn May rklaih hom gâp ăn gơnh. Yêhôva, dăn May kơl gâp ăn gơnh.$b$,true),
('bunong-vn','PSA',70,2,null,$b$Ăn phung vay joi ƀư ƀai huêng nau rêh gâp, Ăn phung geh nau maak tâm nau rêh ni, gâp mra rŭch du jêh ri ƀư bêk khân păng. Ăn khân păng plơ̆ sĭt pa kơi yor nau khân păng bêk.$b$,true),
('bunong-vn','PSA',70,3,null,$b$Phung vay lah Ha ha! Ha ha!$b$,true),
('bunong-vn','PSA',70,4,null,$b$Ăn lĕ rngôch mbu nâm joi Brah Ndu. Geh nau răm maak tâm Păng. Ăn phung rŏng ma nau tâm rklaih, lah pô aơ: Chrêk rmah ma Brah Ndu$b$,true),
('bunong-vn','PSA',70,5,null,$b$Ƀiă lah gâp jêng o-ach jêh ri rêh ni. Ơ Brah Ndu koh dŏng hom gâp May jêng nơm kơl gâp jêh ri nơm ăn gâp geh nau đăp mpăn. Ơ Yêhôva, lơi hôm nđom ôh.$b$,false),
('bunong-vn','PSA',71,1,null,$b$Ơ Yêhôva, gâp du krap tâm May: Lơi ăn bu mâp ƀư bêk gâp ôh.$b$,true),
('bunong-vn','PSA',71,2,null,$b$Tâm nau sŏng May tâm rklaih gâp, jêh ri ăn gâp jêng kon me. Rkêng tôr May ma gâp, jêh ri tâm rklaih gâp.$b$,true),
('bunong-vn','PSA',71,3,null,$b$Ăn May jêng lŭ gâp dơi gŭ, ta nây gâp dơi mbe ƀa ƀơ: May ăn jêh nau ntăm, gay May tâm rklaih gâp;$b$,true),
('bunong-vn','PSA',71,4,null,$b$Yor lah May jêng lŭ gâp, tâm rklaih gâp bơh ti bunuyh ƀai, Ma ti bunuyh kue jêh ri janh ƀai$b$,false),
('bunong-vn','PSA',71,5,null,$b$Yor lah may jêng nau gâp kâp gân, Ơ kôranh Brah Yêhôva; Ma may gâp rnơm bơh gâp jêng mom.$b$,false),
('bunong-vn','PSA',71,6,null,$b$Gâp nsing ma May ntơm bơh nar ma deh ma gâp; May yơh ăn gâp du luh tă bơh ndŭl me gâp; Gâp mra tâm rnê ma may ƀa ƀơ.$b$,true),
('bunong-vn','PSA',71,7,null,$b$Gâp jêng nau hih rhâl ma lĕ rngôch bunuyh Ƀiă lah May jêng ntŭk nâp gâp krap$b$,true),
('bunong-vn','PSA',71,8,null,$b$Mbung gâp mra tâm rnê ma May Jêh ri yơk mbah ma May ăp nar$b$,false),
('bunong-vn','PSA',71,9,null,$b$Lơi ta dun gâp tơ lah gâp lĕ ranh, Tơ lah n'hâm suan gâp lĕ djoh, lơi ta cha lơi gâp;$b$,false),
('bunong-vn','PSA',71,10,null,$b$Yor lah phung rlăng đah gâp ngơi ma gâp, Phung rmiăt huêng gâp tâm nchră ndrăng khân păng,$b$,false),
('bunong-vn','PSA',71,11,null,$b$Khân păng lah, Brah Ndu cha lơi păng jêh; Ntâp păng, kuăn rdâng păng, Yor lah mâu geh bunuyh tâm rklaih păng ôh$b$,false),
('bunong-vn','PSA',71,12,null,$b$Ơ Brah Ndu, lơi gŭ ngai đah gâp ôh; Ơ Brah Ndu gâp, ndal kơl gâp.$b$,false),
('bunong-vn','PSA',71,13,null,$b$Ăn phung ƀư ngroh huêng gâp, geh nau bêk jêh ri rai yot; Mbu nâm joi nau ƀư mhĭk ma gâp, geh nau bêk jêh ri nau gơm mưch, nkŭm khân păng.$b$,true),
('bunong-vn','PSA',71,14,null,$b$Ƀiă lah gâp mra kâp gân ƀa ƀơ Jêh ri gâp mra tâm rnê ma May lơ hô âk.$b$,true),
('bunong-vn','PSA',71,15,null,$b$Bâr mbung gâp mra mbơh nau sŏng srăng May; Jêh ri nau May tâm nklaih ăp nar; Yor lah gâp mâu dơi kơp mrô khân păng$b$,true),
('bunong-vn','PSA',71,16,null,$b$Gâp mra nkoch bri nau brah Kôranh Brah Yêhôva; Gâp mra mbơh nau sŏng May, knŏng ma nau sŏng May.$b$,false),
('bunong-vn','PSA',71,17,null,$b$Ơ Brah Ndu, May ntĭm nti an jêh gâp bơh gâp hôm mom. Jêh ri tât ta nar aơ, gâp mbơh kan khlay May$b$,true),
('bunong-vn','PSA',71,18,null,$b$Lơi ta cha lơi gâp ôh, Ơ Brah Ndu, tơ lah gâp ranh jêh ri mra jêh. Tât gâp mbơh jêh nau dăng ktang ma rnôk kăndơ̆ , Nau brah May ma ăp kon sau.$b$,false),
('bunong-vn','PSA',71,19,null,$b$Nau rŏng may, Ơ Brah Ndu, prêh ngăn; Nơm ƀư jêh âk kan toyh, Ơ Brah Ndu, mbu mra jêng tâm ban ma May?$b$,true),
('bunong-vn','PSA',71,20,null,$b$May yơh tâm mpơl jêh ma hên âk nau rêh ni toyh, Mra mplơ̆ nau rêh ma hên. Jêh ri mra ăn hên hao luh tă bơh ntu jru tâm neh ntu.$b$,true),
('bunong-vn','PSA',71,21,null,$b$Ăn may n'hao an nau toyh gâp, Jêh ri lŏ plơ̆ rthi nuih gâp.$b$,true),
('bunong-vn','PSA',71,22,null,$b$Gâp mra tâm rnê ma May ma bâr dĭng. Gâp mra mprơ ma nau nanê̆ May, Ơ Brah Ndu gâp; Ma May yơh gâp mra mprơ, tâm rnê ma gong rêng Ơ Nơm kloh Ueh ma Israel.$b$,true),
('bunong-vn','PSA',71,23,null,$b$Bâr mbung mra nter hâk tơ lah gâp mprơ tâm rnê ma May. Nđâp ma huêng gâp May hŏ tâm chuai jêh.$b$,true),
('bunong-vn','PSA',71,24,null,$b$Mpiăt gâp tâm ban lĕ mra mbơh nau sŏng May ăp nar; Yor lah bu ƀư bêk, jêh ri tâm rlŭk jêh nau mĭn phung ŭch ƀư ma gâp.$b$,true),
('bunong-vn','PSA',72,1,null,$b$Ơ Brah Ndu, ăn nau May phat dôih ma hađăch, jêh ri nau sŏng May ma kon hađăch.$b$,true),
('bunong-vn','PSA',72,2,null,$b$Păng mra phat dôih phung ƀon lan may ma nau sŏng srăng, Jêh ri phung o ach may ma nau di;$b$,true),
('bunong-vn','PSA',72,3,null,$b$Phung yôk toyh, jê̆ tâm nau sŏng srăng Mra ăn nau đăp mpăn ma phung ƀon lan.$b$,false),
('bunong-vn','PSA',72,4,null,$b$Păng mra phat dôih phung o ach tâm ƀon lan, Păng mra tâm rklaih phung kon bunuyh pưt mpa, Jêh ri păng mra jot plên phung tŭn jot$b$,true),
('bunong-vn','PSA',72,5,null,$b$Bu mra klach ma may dôl ang nar, jêh ri khay tâm lĕ rnôk.$b$,false),
('bunong-vn','PSA',72,6,null,$b$Hađăch mra jêng nâm bu dak mih tŭp tâm gơ̆ bu mhe muyh; Tâm ban ma mih rhêh ăn bĕ neh ntu.$b$,true),
('bunong-vn','PSA',72,7,null,$b$Dôl păng chiă uănh phung sŏng mra geh kao; jêh ri nau đăp mpăn mra ăn ler kŏ mâu hôm geh khay ôh.$b$,true),
('bunong-vn','PSA',72,8,null,$b$Păng mra chiă uănh bơh dak rlai aơ, tât ta dak rlai êng; Bơh dak krong tât ta ntŭk dŭt bri dŭt neh.$b$,true),
('bunong-vn','PSA',72,9,null,$b$Ta năp păng phung ƀon lan tâm bri rdah mra chon kômâk; Jêh ri phung rlăng păng mra ler ndruyh neh$b$,true),
('bunong-vn','PSA',72,10,null,$b$Phung hađăch n'gor Tarsis jêh ri phung kô dak rlai mra chê̆ pi; Phung hađăch bơh Sêba jêh ri Sêba mra nhhơr ndơ.$b$,false),
('bunong-vn','PSA',72,11,null,$b$Nanê̆, lĕ rngôch phung hađăch mra chon ta năp păng; lĕ rngôch mpôl băl mra pah kan ma păng;$b$,true),
('bunong-vn','PSA',72,12,null,$b$Yor lah păng mra kơl phung o ach nter vơh, Jêh ri nơm rêh ni mâu geh nơm kơl.$b$,false),
('bunong-vn','PSA',72,13,null,$b$Păng mra yô̆ ma phung rêh ni jêh ri o ach; Jêh ri păng mra rklaih huêng phung pưt ndơ.$b$,true),
('bunong-vn','PSA',72,14,null,$b$Păng mra tâm chuai huêng khân păng bơh nau tŭn jot, jêh ri nau ƀai; Jêh ri mham khân păng mra geh rnoh khlay ta năp măt păng.$b$,true),
('bunong-vn','PSA',72,15,null,$b$Khân păng mra gŭ rêh jêh ri bu ăn ma hađăch mah bơh Sêba; Phung bunuyh mra mbơh sơm ma hađăch ƀa ƀơ. Khân păng mra ăn nau ueh lăng ma ô băl ăp nar.$b$,true),
('bunong-vn','PSA',72,16,null,$b$Ba mra jêng âk rmeh tâm neh ntu klơ kô yôk; Jêh ri ndrŏng ba nây mra mpât dai nâm bu tơm Si Liban; Phung ƀon lan mra luh kao nâm bu gơ̆ tâm neh.$b$,true),
('bunong-vn','PSA',72,17,null,$b$Amoh Păng mra gŭ ƀa ƀơ; Amoh Păng mra gŭ ƀa ƀơ dôl duh nar; Jêh ri phung bunuyh mra geh nau ueh uĭn tâm Păng; Lĕ rngôch mpôl băl bunuyh mra lah ma Păng ueh maak yơh.$b$,true),
('bunong-vn','PSA',72,18,null,$b$Mât ton ma Yêhôva, Brah Ndu, Brah Ndu phung Israel; Knŏng Păng ƀư kan khlay ngăn,$b$,true),
('bunong-vn','PSA',72,19,null,$b$Mât ƀon ƀa ƀơ ma amoh păng chrêk rmah; Ăn lĕ rngôch neh ntu mra bêng ma nau chrêk rmah Păng. Amen. Amen.$b$,false),
('bunong-vn','PSA',72,20,null,$b$Lôch yơh nau Yor lah-Đavit, Kon Yêsê, mbơh sơm. Ndrom Sămƀŭt Rơh Pe Nau nglĕ dŭt phung ƀai đah phung sŏng.$b$,true),
('bunong-vn','PSA',73,1,null,$b$Nanê̆ Brah Ndu jêng ueh ma phung Israel; Ma phung geh nuih n'hâm kloh$b$,true),
('bunong-vn','PSA',73,2,null,$b$Ƀiă lah jâng gâp bơi ma văk prah, nhuat gâp bơi ma prah$b$,false),
('bunong-vn','PSA',73,3,null,$b$Yor lah gâp geh nau kơnh ma phung sưr; Tơ lah gâp saơ nau ueh maak phung ƀai.$b$,false),
('bunong-vn','PSA',73,4,null,$b$Yor lah khân păng mâu geh ôh nau rêh ni, tơ lah khân păng khĭt; Ƀiă lah nau ktang khân păng gŭ nâp.$b$,true),
('bunong-vn','PSA',73,5,null,$b$Khân păng mâu gŭ ôh tâm nau rêh ni nâm bu phung bunuyh êng$b$,true),
('bunong-vn','PSA',73,6,null,$b$Yor nây nau sưr jêng bok ao khân păng soh n'gut.$b$,false),
('bunong-vn','PSA',73,7,null,$b$Măt khân păng gloh pa dih yor lah khân păng geh rmeh lơn ma nuih n'hâm ŭch$b$,true),
('bunong-vn','PSA',73,8,null,$b$Khân păng mưch, jêh ri ma nau ƀai ngơi ma nau tŭn jot; Khân păng ngơi bêng ma nau sưr.$b$,false),
('bunong-vn','PSA',73,9,null,$b$Bâr mbung khân păng ngơi tâm rdâng tât ta klơ trôk; Jêh ri mpiăt khân păng nsong lam bri neh$b$,true),
('bunong-vn','PSA',73,10,null,$b$Păng mra lŏ njŭn leo phung ƀon lan păng; Khân păng rvăn dak âk rmeh.$b$,false),
('bunong-vn','PSA',73,11,null,$b$Jêh ri khân păng lah, mâm ƀư Brah Ndu dơi gĭt? Mâm ƀư Nơm Klơ Lơn dơi năl?$b$,true),
('bunong-vn','PSA',73,12,null,$b$Aơ, pô aơ phung ƀai; Khân păng hâk răm ƀa ƀơ, khân păng bun drăp ndơ.$b$,true),
('bunong-vn','PSA',73,13,null,$b$Pô ri mâu khlay ôh gâp ƀư kloh jêh nuih n'hâm gâp; Jêh ri rao jêh ti gâp tâm nau mâu mâp tih;$b$,true),
('bunong-vn','PSA',73,14,null,$b$Yor lah ăp nar bu dong gâp; ăp ôi nau tâm rmal tŭp ta gâp;$b$,false),
('bunong-vn','PSA',73,15,null,$b$Tơ lah gâp lah, gâp mra ngơi pô aơ; Aơ, gâp mra rlăng ma mpôl phung kon may$b$,false),
('bunong-vn','PSA',73,16,null,$b$Tơ lah gâp joi ŭch gĭt rbăng nau nây, Păng jêng nau jê̆, toyh ta năp măt gâp;$b$,false),
('bunong-vn','PSA',73,17,null,$b$Kŏ gâp lăp tâm ntŭk kloh ueh Brah Ndu; Jêh ri mĭn ma nar dăch lôch khân păng.$b$,false),
('bunong-vn','PSA',73,18,null,$b$Nanê̆, May dơm khân păng ta trong mbĭr; May ăn prah khân păng tâm nau rai lôch.$b$,true),
('bunong-vn','PSA',73,19,null,$b$Uănh khân păng rai lôch ƀât lât! Khân păng roh ngăn ma nau klach toyh,$b$,true),
('bunong-vn','PSA',73,20,null,$b$Nâm bu nau mbơi tơ lah bu kah rngăl; kah rngăl, May mra tâm rmot ma rup khân păng;$b$,false),
('bunong-vn','PSA',73,21,null,$b$Yor lah huêng gâp rngot, jêh ri nuih n'hâm gâp nâm bu ntâp jêh;$b$,false),
('bunong-vn','PSA',73,22,null,$b$Rnôk nây gâp jêng rluk jêh ri mâu gĭt rbăng ôh; Ta năp măt May gâp jêng tâm ban ma jun$b$,false),
('bunong-vn','PSA',73,23,null,$b$Ƀiă lah gâp gŭ ndrel ma may ƀa ƀơ; May kuăn jêh gâp tâm ti ma May$b$,false),
('bunong-vn','PSA',73,24,null,$b$May mra njŭn leo gâp ma nau May mƀăp nti; Jêh ri kăndơ̆ May mra rom gâp tâm nau chrêk rmah.$b$,false),
('bunong-vn','PSA',73,25,null,$b$Mbu hôm geh êng đŏng ma May tâm trôk? Ta neh ntu tâm ban lĕ, gâp mâu hôm ŭch ma bu êng ôh, knŏng May yơh.$b$,true),
('bunong-vn','PSA',73,26,null,$b$Nglay săk jêh ri play nuih gâp mra roh rai; Ƀiă lah Brah Ndu jêng nau ktang ma nuih n'hâm gâp jêh ri jêng drăp gâp krâm n'ho ro.$b$,true),
('bunong-vn','PSA',73,27,null,$b$Yor lah pô aơ; Phung gŭ ngai đah May mra rai yot; May ƀư rai jêh phung du tă bơh may ƀư nau văng tĭr.$b$,true),
('bunong-vn','PSA',73,28,null,$b$Ƀiă lah hăn dăch ta Brah Ndu jêng nau ueh ma gâp; Gâp dơn Kôranh Brah Yêhôva jêng ntŭk gâp gŭ krap; Gay ma gâp dơi nkoch bri lĕ rngôch kan May.$b$,true),
('bunong-vn','PSA',74,1,null,$b$Ơ Brah Ndu, mâm ƀư May dun hên ƀa ƀơ? Mâm ƀư May ji nuih ma phung biăp tâm ndrêch gơ̆ nse May?$b$,true),
('bunong-vn','PSA',74,2,null,$b$Ăn May kah gĭt ma phung ƀon lan May mbu nâm bơh kăl e Phung May tâm chuai jêh, gay njêng khân păng jêng oh mon May rdơn; Ăn May kah gĭt ma yôk Siôn, ntŭk May tă gŭ jêh.$b$,true),
('bunong-vn','PSA',74,3,null,$b$Hăn hom ta ntŭk geh nau ƀư rai ƀa ƀơ, Nơm rlăng ƀư rai lĕ jêh tâm ntŭk kloh ueh.$b$,true),
('bunong-vn','PSA',74,4,null,$b$Phung rlăng May ngrông jêh ta nklang nau May tâm rƀŭn; Khân păng n'hao jêh ta nây bok kơ khân păng jêng nau tâm mbên.$b$,true),
('bunong-vn','PSA',74,5,null,$b$Bu saơ khân păng nâm bu phung yơr sung kŭk tâm krŏng mbâl$b$,true),
('bunong-vn','PSA',74,6,null,$b$Jêh ri aƀaơ khân păng khân păng nchah rup bu trah tâm ngih brah ma sung kŭk jêh ri ma kon nôp$b$,false),
('bunong-vn','PSA',74,7,null,$b$Khân păng su jêh ntŭk kloh ueh May; Khân păng ƀư ƀơ̆ jêh ntŭk may prăp ma amoh May, gŭ tâm nau khân păng klŭp jêh ta neh.$b$,false),
('bunong-vn','PSA',74,8,null,$b$Khân păng lah jêh tâm nuih n'hâm khân păng, Ăn he ƀư rai lĕ; Khân păng su lĕ rngôch jêh ntŭk tâm rƀŭn tâm n'gor.$b$,true),
('bunong-vn','PSA',74,9,null,$b$He mâu hôm saơ bok kơ he ôh; Mâu hôm geh Kôranh nơm mbơh lor ôh; Mâu lĕ geh nơm tâm phung he gĭt ndah nâm jŏ.$b$,true),
('bunong-vn','PSA',74,10,null,$b$Ndah nâm jŏ, Ơ Brah Ndu, nơm tŭn jot mra suai rak? Nơm rlăng mra suai mro lĕ ma amoh may?$b$,true),
('bunong-vn','PSA',74,11,null,$b$Mâm ƀư May rŭt lơi ti may, ti ma May? Ngluh hom ti May ƀư rai hom khân păng.$b$,true),
('bunong-vn','PSA',74,12,null,$b$Ăt Brah Ndu jêng hađăch gâp bơh kăl e, Păng ƀư nau tâm rklaih ta nklang neh ntu.$b$,true),
('bunong-vn','PSA',74,13,null,$b$May pă rnglah jêh dak rlai ma nau brah May; May nchah jêh bôk phung jun toyh tâm dak rlai.$b$,true),
('bunong-vn','PSA',74,14,null,$b$May yơh nchah lơi bôk Lêviathan May ăn păng jêng ndơ sông sa ma phung gŭ tâm bri rdah.$b$,true),
('bunong-vn','PSA',74,15,null,$b$May yơh ăn tu dak luh jêh ri dak lip. May yơh ăn suăt dak krong toyh.$b$,true),
('bunong-vn','PSA',74,16,null,$b$Nar jêng ndơ may, nđâp ma măng jêng ndơ May; May nơm rhăk njêng nau ang jêh ri nar.$b$,true),
('bunong-vn','PSA',74,17,null,$b$May yơh tâm nal jêh n'har neh ntu. Yăn vai jêh ri yăn puh jêng kan May.$b$,true),
('bunong-vn','PSA',74,18,null,$b$Ăn May kah gĭt ma nau nơm rlăng suai rak ma Yêhôva, Phung mpôl băl rluk mâl ngơi sưr ma amoh May.$b$,true),
('bunong-vn','PSA',74,19,null,$b$Lơi jao ma jun bri ôh huêng plŭk May; Lơi ta chuêl mro nau rêh phung May gŭ rêh ni.$b$,true),
('bunong-vn','PSA',74,20,null,$b$Ăn May kah gĭt ma nau May tâm rnglăp; Yor lah ntŭk ngo tâm neh ntu bêng ma rsuăn phung ƀai.$b$,true),
('bunong-vn','PSA',74,21,null,$b$Lơi ăn nơm bu tŭn jot ndrel ma nau bêk ôh; Ăn phung rêh ni jêh ri o ach dơi tâm rnê ma amoh May.$b$,true),
('bunong-vn','PSA',74,22,null,$b$Dâk hom May, Ơ Brah Ndu, n'gang nau May; Ăn May kah gĭt ma nau phung rluk suai rak lĕ nar,$b$,true),
('bunong-vn','PSA',74,23,null,$b$Lơi chuêl ôh bâr phung rlăng đah May; Nau nter troh uh ah phung tâm rdâng đah May hao ƀa ƀơ.$b$,false),
('bunong-vn','PSA',75,1,null,$b$Hên tâm rnê ma May, Ơ Brah Ndu, hên tâm rnê ma May; Yor amoh May gŭ dăch; Phung bunuyh nkoch bri kan khlay May.$b$,true),
('bunong-vn','PSA',75,2,null,$b$Tơ lah mra tât nar gâp tâm nal jêh, Gâp mra phat dôih ma nau sŏng,$b$,true),
('bunong-vn','PSA',75,3,null,$b$Neh ntu nđâp lĕ phung gŭ tâm păng rai jêh; Gâp tăm jêh meh păng. (Sêla)$b$,false),
('bunong-vn','PSA',75,4,null,$b$Gâp lah ma phung sưr, Lơi ta khân may sưr ôh; Jêh ri ma phung ƀai, lơi ƀư janh ma nke khân may ôh.$b$,false),
('bunong-vn','PSA',75,5,null,$b$Lơi ta n'gơr ta klơ nke khân may; Lơi ir ngơi sưr rlau ôh.$b$,true),
('bunong-vn','PSA',75,6,null,$b$Yor lah mâu tăp pa lơ pa dâng ôh, mâu lĕ tă bơh rđŭng luh nau tâm n'hao.$b$,true),
('bunong-vn','PSA',75,7,null,$b$Ƀiă lah Brah Ndu jêng nơm phat dôih; Păng ntrŭnh du huê aơ, păng n'hao nơm êng.$b$,true),
('bunong-vn','PSA',75,8,null,$b$Tâm ti Yêhôva geh du mlâm kachok, Tâm nây geh dak play kriăk ƀâu chăng; Dak nây lŭk lai jêh, păng mra kêt lơi ka chok nây; Nanê̆ lĕ rngôch phung ƀai tâm neh ntu mra ntru nhêt kŏ lĕ,$b$,true),
('bunong-vn','PSA',75,9,null,$b$Ƀiă lah gâp mra mbơh ƀa ƀơ, gâp mra mprơ tâm rnê ma Brah Ndu Yakôb.$b$,false),
('bunong-vn','PSA',75,10,null,$b$Gâp mra koh lĕ rngôch nke phung ƀai; Ƀiă lah nke phung sŏng mra n'hao.$b$,true),
('bunong-vn','PSA',76,1,null,$b$Tâm n'gor Yuđa bu gĭt năl Brah Ndu; Amoh Păng jêng toyh tâm n'gor Israel.$b$,true),
('bunong-vn','PSA',76,2,null,$b$Ngih bok Păng gŭ tâm ƀon Salem. Jêh ri ntŭk Păng gŭ ta ƀon Siôn.$b$,true),
('bunong-vn','PSA',76,3,null,$b$Ta nây Păng nkêch lơi hăr; Khêl, đao gưm, jêh ri ndơ tâm lơh, (Sêla)$b$,true),
