('bunong-vn','PSA',76,6,null,$b$Tơ lah May nduyh, Ơ Brah Ndu Yakôb, Phung seh nđâp ma ndeh seh May mƀăr jêh tâm nau bêch nâm bu khĭt.$b$,true),
('bunong-vn','PSA',76,7,null,$b$Nanê̆ May khư ma bu klach; Mbu nâm dơi gŭ râng ta năp May, tơ lah May nuih?$b$,true),
('bunong-vn','PSA',76,8,null,$b$Bơh trôk klơ May ăn bu tăng nau May phat dôih; Neh ntu klach jêh ri gŭ rklăk.$b$,true),
('bunong-vn','PSA',76,9,null,$b$Tơ lah Brah Ndu dâk phat dôih, Gay tâm rklaih lĕ rngôch phung tông bâr ta neh ntu. (Sêla)$b$,true),
('bunong-vn','PSA',76,10,null,$b$Nanê̆ nau bunuyh ji nuih mra tâm rnê ma May; May mra nkân nau ji nuih ăt gŭ,$b$,false),
('bunong-vn','PSA',76,11,null,$b$Ton ma Yêhôva, Brah Ndu khân may, jêh ri ƀư nanê̆ hom. Ăn lĕ rngôch ƀon lan chiau meng păng, văch nhhơr ndơ ma Brah Ndu, khư ma bu klach.$b$,false),
('bunong-vn','PSA',76,12,null,$b$Brah Ndu mra koh lơi, nau sưr phung kon hađăch ta neh ntu klach ma păng.$b$,true),
('bunong-vn','PSA',77,1,null,$b$Gâp mra nter ma Brah Ndu ma bâr gâp, Ma Brah Ndu yơh đah bâr gâp, jêh ri Păng mra rkêng tôr ma gâp.$b$,true),
('bunong-vn','PSA',77,2,null,$b$Ta nar rêh ni gâp joi Kôranh Brah, Dôl măng gâp yơr ti gâp, mâu rlu ôh; Huêng gâp dun dơn nau bonh leng,$b$,true),
('bunong-vn','PSA',77,3,null,$b$Gâp kah gĭt ma Brah Ndu, jêh ri gâp mra uh ah; Gâp nter rđêng jêh ri huêng gâp huăr jêh. (Sêla)$b$,false),
('bunong-vn','PSA',77,4,null,$b$May kuăn kô măt gâp gŭ kuăn rdâng ƀa ƀơ; Gâp rŭng răng hâu ngăn ngên, tât gâp mâu dơi ngơi.$b$,false),
('bunong-vn','PSA',77,5,null,$b$Gâp rnê ma nar kăl e, ma năm kăl e.$b$,true),
('bunong-vn','PSA',77,6,null,$b$Gâp kah gĭt ma nau gâp mprơ dôl măng; Gâp gŭ mĭn tâm nuih n'hâm gâp.$b$,true),
('bunong-vn','PSA',77,7,null,$b$Kôranh Brah mra dun mro lĕ? Păng mâu mra hôm jêng ueh lĕ?$b$,true),
('bunong-vn','PSA',77,8,null,$b$Nau ueh păng du jêh mro lĕ? Nau păng ton roh n'ho ro lĕ?$b$,true),
('bunong-vn','PSA',77,9,null,$b$Brah Ndu chuêl lĕ nau Păng blau kơp Dôl păng ji nuih, păng mâp chăng lơi lĕ nau păng vay yô̆ ? (Sela)$b$,true),
('bunong-vn','PSA',77,10,null,$b$Jêh ri gâp lah, aơ, nau rêh ni gâp; Ƀiă lah gâp mra kah gĭt năm, ti ma Nơm klơ Lơn gŭ ndrel.$b$,false),
('bunong-vn','PSA',77,11,null,$b$Gâp mra mbơh kan Yêhôva; Yor lah gâp mra kah gĭt ma kan khlay May kăl e.$b$,true),
('bunong-vn','PSA',77,12,null,$b$Gâp mra mĭn lĕ ma lĕ rngôch kan May, Jêh ri mĭn ma nau May ƀư.$b$,true),
('bunong-vn','PSA',77,13,null,$b$Ơ Brah Ndu, trong May jêng tâm nau kloh ueh; Ntă brah jêng toyh tâm ban ma Brah Ndu?$b$,true),
('bunong-vn','PSA',77,14,null,$b$May jêng Brah Ndu ƀư nau khlay; May tâm mpơl jêh nau brah May ma phung ƀon lan.$b$,true),
('bunong-vn','PSA',77,15,null,$b$Ma ti May, May tâm chuai jêh phung ƀon lan May, Phung kon bu klâu Yakôb jêh ri Yôsep (Sêla)$b$,true),
('bunong-vn','PSA',77,16,null,$b$Ơ Brah Ndu, phung dak saơ jêh May; Phung dak saơ jêh May, jêh ri khân păng klach; Phung ntu jru n'găr.$b$,false),
('bunong-vn','PSA',77,17,null,$b$Phung ndâr tŭk nkhŭt dak mih; nglaih rdah tâm ndâr tŭk; Jêh ri hăr may mpăr lam ntŭk.$b$,true),
('bunong-vn','PSA',77,18,null,$b$Nglaih May rdah tâm sial hĭt; Lơp nchrat tâm neh ntu; neh ntu n'găr jêh ri nsâr.$b$,true),
('bunong-vn','PSA',77,19,null,$b$May nkra trong tâm dak rlai, Ƀa ƀă trong May ta dak toyh. Jêh ri têl May bu mâu gĭt ôh.$b$,true),
