('bunong-vn','PSA',78,1,null,$b$Ơ phung ƀon lan Gâp; gŭ iăt hom nau vay Gâp; Rkêng hom tôr khân may ma bâr ngơi tă bơh trôm mbung Gâp,$b$,true),
('bunong-vn','PSA',78,2,null,$b$Gâp mra hă trôm mbung ngơi nau hôr; Gâp mra mbơh nau ndâp bơh rnôk kăl e,$b$,false),
('bunong-vn','PSA',78,3,null,$b$Nau hên tăng jêh ri gĭt jêh, Nau phung mbơ̆ hên nkoch bri jêh,$b$,false),
('bunong-vn','PSA',78,4,null,$b$Hên mâu mra pôn ôh nau nây ma phung kon khân păng, Hên mra lah ma phung ndŭl mpôl pa kơi nau tâm rnê ma Yêhôva, Nau brah Păng, jêh ri kan khlay păng ƀư jêh.$b$,false),
('bunong-vn','PSA',78,5,null,$b$Yor lah Păng njêng jêh du nau mbơh tâm Yakôb, Păng dơm du nau vay tâm phung Israel, Jêh ri Păng đă jêh mbơ̆ he ăn nti nau nây ma phung kon khân păng.$b$,true),
('bunong-vn','PSA',78,6,null,$b$Gay ma phung mpôl băl kăndơ̆ dơi gĭt nau vay; Phung kon bu mra deh; Jêh văch ma toyh, khân păng mra ngơi ma kon khân păng tâm ban lĕ,$b$,true),
('bunong-vn','PSA',78,7,null,$b$Gay ma khân păng kâp gân ma Brah Ndu, Mâu chuêl ôh kan Brah Ndu, ƀiă lah djôt prăp nau păng ntăm,$b$,false),
('bunong-vn','PSA',78,8,null,$b$Jêh ri mâu jêng nâm bu phung mbơ̆ khân păng, Mpôl băl mâu blau tông jêh ri dăng bôk. Mpôl băl geh nuih n'hâm mâu mâp nâp rjăp, Jêh ri huêng khân păng mâu răp jăp đah Brah Ndu ôh.$b$,false),
('bunong-vn','PSA',78,9,null,$b$Phung kon bu klâu Êphraim geh jêh ndơ tâm lơh, jêh ri djôt na, Rle hom ndŭr kơi tâm nau tâm lơh,$b$,true),
('bunong-vn','PSA',78,10,null,$b$Khân păng mâu djôt prăp ôh nau Brah Ndu tâm rnglăp, jêh ri dun nsong hăn tĭng nâm nau vay Păng;$b$,false),
('bunong-vn','PSA',78,11,null,$b$Khân păng chuêl kan Păng, Jêh ri kan khlay Brah Ndu ăn khân păng saơ.$b$,false),
('bunong-vn','PSA',78,12,null,$b$Ta năp phung mbơ̆ khân păng Brah Ndu ƀư jêh nau khlay, Tâm n'gor Êjipt, tâm bri Tsôan$b$,true),
('bunong-vn','PSA',78,13,null,$b$Păng pă rnglah dak rlai, jêh ri ăn khân păng rgăn; Păng ăn dak gŭ nâm bu mpir$b$,false),
('bunong-vn','PSA',78,14,null,$b$Dôl nar păng njŭn khân păng ma ndâr tŭk. Jêh ri lĕ măng ma ŭnh ang.$b$,false),
('bunong-vn','PSA',78,15,null,$b$Păng rlah lŭ tâm bri rdah, jêh ri ăn khân păng nhêt dak âk tâm ban ma tă bơh tu jru.$b$,true),
('bunong-vn','PSA',78,16,null,$b$Bơh lŭ păng luh dak n'hor, Jêh ri ăn dak hoch nâm bu dak krong,$b$,true),
('bunong-vn','PSA',78,17,null,$b$Ƀiă lah khân păng ăt ƀư tih đah Brah Ndu Ƀư nau tâm rdâng đah Nơm Klơ Lơn tâm bri rdah.$b$,false),
('bunong-vn','PSA',78,18,null,$b$Khân păng rlong uănh Brah Ndu tâm nuih n'hâm khân păng Ma nau khân păng dăn ndơ sông sa tĭng nâm khân păng ŭch.$b$,true),
('bunong-vn','PSA',78,19,null,$b$Khân păng ngơi tâm rdâng đah Brah Ndu; Khân păng lah, dơi lĕ Brah Ndu nkra sưng sông sa tâm bri rdah?$b$,true),
