('bunong-vn','PSA',78,21,null,$b$Pô ri Yêhôva tăng, jêh ri Păng ji nuih; Jêh ri geh ŭnh sênh ta phung Yakôb, Jêh ri Păng hao nuih, ji nuih ma phung Israel;$b$,true),
('bunong-vn','PSA',78,22,null,$b$Yor lah khân păng mâu chroh ma Brah Ndu ôh, Jêh ri khân păng mâu rnơm ôh ma nau tâm rklaih.$b$,false),
('bunong-vn','PSA',78,23,null,$b$Ăt păng ntăm ma ndâr tŭk ta klơ; Jêh ri pơk mpông trôk.$b$,true),
('bunong-vn','PSA',78,24,null,$b$Păng ăn mana tŭp nâm bu dak mih jêng ndơ khân păng sa, Păng ăn ndơ sông sa tă bơh trôk,$b$,true),
('bunong-vn','PSA',78,25,null,$b$Phung bunuyh sa jêh kapŭng phung brah; Brah Ndu njuăl an ma khân păng ndơ sông sa tât hơm.$b$,false),
('bunong-vn','PSA',78,26,null,$b$Păng ăn sial khôm tâm trôk tă bơh lơ; Jêh ri ma nau brah Păng, Păng đă sial khôm tă bơh rđŭng.$b$,true),
('bunong-vn','PSA',78,27,null,$b$Păng ăn sĭm tŭp nâm bu mih, âk nâm bu ndruyh neh, Jêh ri sĭm geh năr âk nâm bu choih tâm dak rlai;$b$,true),
('bunong-vn','PSA',78,28,null,$b$Păng ăn phung sĭm nây tŭp ta nklang ntŭk khân păng jưh, jŭm ntŭk khân păng gŭ.$b$,false),
