('bunong-vn','PSA',78,30,null,$b$Nau khân păng ŭch ê mpay ôh, ndơ khân păng sa, ăt hôm tâm trôm mbung,$b$,true),
('bunong-vn','PSA',78,31,null,$b$Tơ lah Brah Ndu hao nuih, ji nuih ma khân păng; Păng nkhĭt phung lay lơn, Păng dong phung bu klâu mom Israel$b$,false),
('bunong-vn','PSA',78,32,null,$b$Nđâp tơ lah lĕ nau nây khân păng ăt ƀư tih, jêh ri khân păng mâu chroh ôh ma nau khlay păng.$b$,false),
('bunong-vn','PSA',78,33,null,$b$Pô ri Brah Ndu ƀư roh nar khân păng tâm nau dơm dam. Jêh ri năm khân păng lôch tâm nau klach ngăn.$b$,true),
('bunong-vn','PSA',78,34,null,$b$Tơ lah Brah Ndu nkhĭt khân păng, pô ri khân păng joi Brah Ndu; Khân păng lŏ plơ̆ sĭt, jêh ri joi Brah Ndu; ma lĕ nuih n'hâm$b$,true),
('bunong-vn','PSA',78,35,null,$b$Khân păng kah gĭt ma Brah Ndu jêng lŭ khân păng Jêh ri Brah Ndu Nơm Klơ lơn jêng nơm tâm chuai khân păng$b$,false),
('bunong-vn','PSA',78,36,null,$b$Ƀiă lah mbung khân păng ngơi nhhưnh, jêh ri mpiăt khân păng ngơi mƀruh$b$,false),
('bunong-vn','PSA',78,37,null,$b$Yor lah nuih n'hâm khân păng mâu jêng nâp ôh đah Brah Ndu, Mâu lĕ khân păng gŭ răp jăp đah nau Brah Ndu tâm rnglăp.$b$,false),
('bunong-vn','PSA',78,38,null,$b$Ƀiă lah tâm nau păng yô̆, Păng yô̆ an nau kue jêh ri mâu ƀư rai ôh; Jêh ri mâu jao păng nơm ma nau ji nuih toyh ôh.$b$,true),
('bunong-vn','PSA',78,39,null,$b$Păng kah gĭt ma phung nây jêng knŏng, nglay săk, Du n'hâm sial hăn, jêh ri mâu hôm sĭt ôh.$b$,true),
('bunong-vn','PSA',78,40,null,$b$Âk tơ̆ khân păng ƀư nau tâm rdâng đah Brah Ndu tâm ntŭk bri hŏng, Âk tơ̆ khân păng ƀư rngot ma Brah Ndu tâm bri rdah;$b$,true),
('bunong-vn','PSA',78,41,null,$b$Khân păng lŏ vir jêh ri rlong uănh Brah Ndu, Jêh ri lŏk lôr Nơm Kloh Ueh Israel.$b$,false),
('bunong-vn','PSA',78,42,null,$b$Khân păng mâu kah gĭt ôh ti Brah Ndu. Mâu kah gĭt lĕ, ma nar tâm rklaih păng bơh phung tŭn jot;$b$,true),
('bunong-vn','PSA',78,43,null,$b$Nau tâm mbên Brah Ndu ƀư jêh tâm bri Êjipt Jêh ri kan khlay Păng tâm bri Tsôan$b$,false),
('bunong-vn','PSA',78,44,null,$b$Păng plăch dak krong jêng mham, Jêh ri dak n'hor khân păng, tât khân păng mâu dơi nhêt.$b$,false),
('bunong-vn','PSA',78,45,null,$b$Păng njuăl phung rhuay ta nklang khân păng, ăn sa khân păng; Jêh ri kĭt ƀư rai khân păng$b$,true),
('bunong-vn','PSA',78,46,null,$b$Păng ăn ndrŭng sa lơi ba khân păng Rplay kao bơh kan khân păng ma krah,$b$,false),
('bunong-vn','PSA',78,47,null,$b$Păng ƀư rai tơm play kriăk ƀâu khân păng ma pler. Jêh ri tơm si Sikômor ma pler toyh.$b$,false),
('bunong-vn','PSA',78,48,null,$b$Păng jao phung ndrôk khân păng ma pler tâm ban lĕ; Jêh ri phung biăp khân păng ma ŭnh tă bơh trôk$b$,true),
('bunong-vn','PSA',78,49,null,$b$Brah Ndu nkhŭt nau nuih ktang ma khân păng, Nau khĭt, nau biănh jêh ri nau uh ah, Tâm nau păng njuăl phung tông mpăr mhĭk,$b$,false),
('bunong-vn','PSA',78,50,null,$b$Păng ăn trong ma nau păng nuih, Brah Ndu mâu tâm rklaih huêng khân păng bơh nau khĭt ôh, Ƀiă lah Brah Ndu jao mpô mpa khân păng ma nau rai yot;$b$,false),
('bunong-vn','PSA',78,51,null,$b$Păng dong lĕ rngôch kon bu klâu bôk rah tâm n'gor Êjipt Rplay lor nau ktang khân păng tâm ngih bok Cham. Ƀiă lah Păng njŭn leo phung ƀon lan Păng nâm bu phung biăp,$b$,false),
('bunong-vn','PSA',78,52,null,$b$Brah Ndu gai khân păng nâm bu phung biăp tâm bri rdah.$b$,false),
('bunong-vn','PSA',78,53,null,$b$Brah Ndu njŭn leo khân păng ma nau đăp mpăn, gay lơi ăn khân păng klach ôh; Ƀiă lah dak rlai nkŭm lơi phung rlăng khân păng$b$,true),
('bunong-vn','PSA',78,54,null,$b$Brah Ndu njŭn khân păng ta n'har ntŭk Păng gŭ, Tât ta yôk aơ, ti ma păng tâm chuai jêh.$b$,false),
('bunong-vn','PSA',78,55,null,$b$Brah Ndu mprơh âk băl mpôl ta năp khân păng; Brah Ndu tâm pă neh ma khân păng jêng drăp ndơ khân păng, Jêh ri ăn phung mpôl băl Israel gŭ tâm ngih bok khân păng$b$,true),
('bunong-vn','PSA',78,56,null,$b$Ƀiă lah phung Israel rlong uănh, jêh ri tâm rdâng đah Brah Ndu, Nơm Klơ Lơn, Jêh ri khân păng mâu tĭng ndô̆ ôh nau Brah Ndu mbơh;$b$,false),
('bunong-vn','PSA',78,57,null,$b$Khân păng rŭch, jêh ri ƀư rlăng nâm bu phung mbơ̆ ; Khân păng teng nâm bu pănh na mhĭk.$b$,false),
('bunong-vn','PSA',78,58,null,$b$Khân păng lŏk lôr ăn Yêhôva ji nuih đah ntŭk ta Klơ khân păng Jêh ri yơk mbah ma rup, dĭng geh Kôranh Brah ji nuih ma khân păng$b$,true),
('bunong-vn','PSA',78,59,null,$b$Tơ lah Brah Ndu tăng nau nây păng ji nuih; Păng tâm rmot hâu ngăn ma phung Israel;$b$,false),
('bunong-vn','PSA',78,60,null,$b$Yor nây Păng cha lơi ngih bok ta ƀon Silô; Ngih bok Păng dơm jêh ta nklang bunuyh;$b$,false),
('bunong-vn','PSA',78,61,null,$b$Păng jao nau ktang Păng ma nau jêng dĭk; Jêh ri nau chrêk rmah Păng ma ti nơm rlăng;$b$,false),
('bunong-vn','PSA',78,62,null,$b$Păng jao phung ƀon lan Păng ma đao gưm; Păng nuih ma drăp păng krâm$b$,false),
('bunong-vn','PSA',78,63,null,$b$Ŭnh sa phung bu klâu ndăm khân păng; Jêh ri phung bu ur druh khân păng mâu geh nau mprơ tâm nkol ôh;$b$,false),
('bunong-vn','PSA',78,64,null,$b$Phung Kôranh ƀư brah khân păng tŭp tâm đao gưm; Jêh ri phung bu ur ndrô khân păng mâu nhĭm nhhiăng ôh.$b$,false),
('bunong-vn','PSA',78,65,null,$b$Dôl nây Kôranh Brah nâm bu bunuyh kah rngăl bêch; Nâm bu du huê janh ktang nter. Yor dak play kriăk ƀâu ƀư ma Păng.$b$,true),
('bunong-vn','PSA',78,66,null,$b$Păng dong mprơh lơi phung rlăng; Ƀư bêk khân păng n'ho ro.$b$,true),
('bunong-vn','PSA',78,67,null,$b$Păng n'ho ma dun ngih bok Yôsep, Jêh ri mâu săch ôh mpôl băl Êphraim.$b$,true),
('bunong-vn','PSA',78,68,null,$b$Ƀiă lah Păng săch mpôl băl Yuđa, Yôk Siôn, Yôk păng rŏng.$b$,true),
('bunong-vn','PSA',78,69,null,$b$Păng ƀư ntŭk kloh ueh Păng tâm ban ma ntŭk klơ, Tâm ban ma neh ntu, Păng ƀư nâp rjăp n'ho ro.$b$,true),
('bunong-vn','PSA',78,70,null,$b$Păng săch Y-Đavit oh mon Păng Păng têk sŏk tă bơh n'gar biăp;$b$,true),
('bunong-vn','PSA',78,71,null,$b$Păng sŏk tă bơh kơi phung biăp me gŭ pu kon; Gay ma Păng jêng rmăk biăp Y-Yakôb, phung ƀon lan Păng.$b$,false),
('bunong-vn','PSA',78,72,null,$b$Pô ri Y-Đavit jêng rmăk biăp khân păng ma nuih n'hâm sŏng, Jêh ri njŭn leo khân păng ma ti gĭt rbăng.$b$,true),
('bunong-vn','PSA',79,1,null,$b$Ơ Brah Ndu, phung mpôl băl bri êng pit in jêh drăp ndơ May; Khân păng ƀư ƀơ̆ jêh ngih brah kloh ueh May; Khân păng ƀư ma ƀon Yêrusalem jêng du nku lŭ.$b$,true),
('bunong-vn','PSA',79,2,null,$b$Khân păng jao săk jăn khĭt phung oh mon May, jêng ndơ sa phung sĭm tâm trôk, mlay puăch phung kloh ueh May ma phung mpa bri$b$,true),
('bunong-vn','PSA',79,3,null,$b$Mham khân păng nkhŭt djrah lam ƀon Yêrasalem; Mâu geh bunuyh brôi khân păng ôh.$b$,false),
('bunong-vn','PSA',79,4,null,$b$He jêng ndơ phung chiau meng he rmot, Ndơ phung gŭ jŭm he mưch jêh ri mhĭk bir.$b$,true),
('bunong-vn','PSA',79,5,null,$b$Ndah jŏ bah nau May ji nuih ơ Yêhôva? Ndah jŏ mra nhhât ŭnh May sa, Jêh ri nau May nach mra nâm bu ŭnh sa lĕ?$b$,true),
('bunong-vn','PSA',79,6,null,$b$Nkhŭt nau May ji nuih ta phung mpôl băl mâu gĭt năl May, Jêh ri ta phung ƀon hađăch mâu kuăl mbơh sơm ma amoh May.$b$,true),
('bunong-vn','PSA',79,7,null,$b$Yor lah khân păng sa rvăn jêh Yakôb, Jêh ri ƀư rai jêh ntŭk păng gŭ.$b$,true),
('bunong-vn','PSA',79,8,null,$b$Lơi May kah gĭt ƀư ma hên ôh yor nau kue phung chô hên; Ăn nau May yô̆ văch gơnh tâm mâp đah hên; Yor lah hên rêh ni hâu ngăn ngên.$b$,true),
('bunong-vn','PSA',79,9,null,$b$Koh dŏng an hên, Ơ Brah Ndu ma nau tâm rklaih hên, jêh ri yô̆ an ma nau tih hên yor amoh May.$b$,true),
('bunong-vn','PSA',79,10,null,$b$Mâm ƀư phung mpôl băl mra lah, Mbah ntŭk Brah Ndu khân păng? Ăn bu gĭt ta năp hên tâm nklang phung mpôl băl. May plơng mham phung oh mon may, mham bu nkhŭt jêh.$b$,true),
('bunong-vn','PSA',79,11,null,$b$Ăn nau phung bu nă nđêng tât ta May. Ma nting tur brah May, ăn may prăp phung bu ăn ma nau khĭt:$b$,true),
('bunong-vn','PSA',79,12,null,$b$Mplơ̆ lơi ma phung chiau meng hên, pơh tơ̆ ta ntang ntơh khân păng. Nau bu suai rak ma May jêh, Ơ Kôranh Brah$b$,false),
('bunong-vn','PSA',79,13,null,$b$Pô ri hên, phung ƀon lan May, Phung biăp tâm ndrêch gơ̆ nse May. Mra tâm rnê ma May n'ho ro: Tâm lĕ rngôch rnôk hên mra mbơh nau tâm rnê ma May. Nau Vơh Vơl Ma Brah Ndu Kơl Koh Dŏng Phung ƀon lan păng, bơh nau rêh ni Sôsanim, Êdut. Nau mprơ Y-Asap di ma bâr$b$,false),
('bunong-vn','PSA',80,1,null,$b$Rkêng tôr May, Ơ rmăk biăp Israel, May nơm njŭn Yôsep nâm bu du phung biăp; Sol hom, Ơ Nơm gŭ ta klơ phung chêrubim.$b$,true),
('bunong-vn','PSA',80,2,null,$b$Ta năp Êphraim, Benjamin, jêh ri Manasê, tâm rlay nau brah May, Jêh ri văch koh dŏng hên.$b$,true),
('bunong-vn','PSA',80,3,null,$b$Ơ Brah Ndu rdâk nhhơk hên Ăn nchrat ral măt May, jêh ri hên mra klaih,$b$,true),
('bunong-vn','PSA',80,4,null,$b$Ơ Yêhôva, Brah Ndu phung tahan Ndah hôm jong May mra ji nuih ma nau phung ƀon lan May mbơh sơm?$b$,false),
('bunong-vn','PSA',80,5,null,$b$May ăn khân păng sa kapŭng nau rngot; Jêh ri ăn khân păng nhêt âk rmeh dak măt.$b$,true),
('bunong-vn','PSA',80,6,null,$b$May ăn phung chiau meng hên tâm ndjrel yor hên; Jêh ri phung rlăng đah hên gơm mưch ndrăng khân păng nơm.$b$,true),
('bunong-vn','PSA',80,7,null,$b$Ơ Brah Ndu phung tahan, rdâng nhhơk hom hên. Ăn sol muh măt May, jêh ri hên mra klaih.$b$,true),
('bunong-vn','PSA',80,8,null,$b$May hŏ ngluh jêh tă bơh n'gor Êjipt du tơm play kriăk ƀâu; May mprơh jêh phung mpôl băl, jêh ri May tăm jêh păng.$b$,true),
('bunong-vn','PSA',80,9,null,$b$May nkra jêh ntŭk ta năp păng, Păng njŭr reh, jêh ri brôi bêng neh.$b$,true),
('bunong-vn','PSA',80,10,null,$b$Gui păng nkŭm jêh phung yôk, N'gĭng păng jêng nâm bu phung tơm si Sêdrơ Brah Ndu.$b$,true),
('bunong-vn','PSA',80,11,null,$b$N'gĭng păng nchrông tât ta dak rlai, jêh ri nkeh păng tât ta dak krong.$b$,true),
('bunong-vn','PSA',80,12,null,$b$Mâm ƀư may ƀư deh jêh pêr păng kŏ lĕ rngôch phung prot ta nây tŏk lơi păng?$b$,true),
('bunong-vn','PSA',80,13,null,$b$Phung rke krŏng nhuyh chuk sa păng, Jêh ri jun bri sa păng tâm ban lĕ,$b$,true),
('bunong-vn','PSA',80,14,null,$b$Ơ Brah Ndu phung tahan, hên vơh vơl ma May, plơ̆ văch hom; Uănh bơh trôk ta klơ, saơ jêh ri tâm khâl đah tơm play kriăk ƀâu aơ;$b$,false),
('bunong-vn','PSA',80,15,null,$b$King hom, moh ndơ ti pa ma May hŏ tăm jêh, jêh ri kon bu klâu May săch jêh ma May nơm.$b$,false),
('bunong-vn','PSA',80,16,null,$b$Ŭnh sa jêh păng, bu koh jêh păng; Khân păng rai lôch ta năp nau nduyh muh măt May,$b$,true),
('bunong-vn','PSA',80,17,null,$b$Pah ti May ta nơm pa ma May. Ta kon bunuyh May săch jêh ma May nơm$b$,false),
('bunong-vn','PSA',80,18,null,$b$Pô ri hên mâu mra du bơh May ôh; Lŏ ăn hên rêh, jêh ri hên mra kuăl amoh May,$b$,false),
('bunong-vn','PSA',80,19,null,$b$Ơ Yêhôva Brah Ndu phung tahan, rdâk nhhơk hom hên; Sol muh măt May, jêh ri hên mra klaih.$b$,false),
('bunong-vn','PSA',81,1,null,$b$Mprơ ăn huy ma Brah Ndu, nau ktang he; răm maak hom ma bâr mprơ ma Brah Ndu Yakôb,$b$,true),
('bunong-vn','PSA',81,2,null,$b$N'hao hom bâr mprơ, goh hom gâr; Kreh gong rêng găl jêh ri uh rlet.$b$,false),
('bunong-vn','PSA',81,3,null,$b$Uh nŭng tâm nar khay mhe luh, Khay bŏng, tâm nar sa nau maak.$b$,true),
('bunong-vn','PSA',81,4,null,$b$Yor lah jêng du ntil nau vay ma Israel; Du nau ntăm tă bơh Brah Ndu Yakôb.$b$,true),
('bunong-vn','PSA',81,5,null,$b$Păng rdâk nau nây jêng nau mbơh ta nklang phung Yôsep, Tơ lah păng hăn tâm rdâng đah bri Êjipt, Ntŭk gâp tăng nau ngơi gâp mâu gĭt rbăng ôh.$b$,true),
('bunong-vn','PSA',81,6,null,$b$Gâp săch rlak ndơ jâk bơh săng nglik păng; Gâp ƀư mpăn jêh ti păng tă bơh bĭ.$b$,true),
('bunong-vn','PSA',81,7,null,$b$May nter jêh tâm nau rêh ni, jêh ri gâp rklaih jêh may; Gâp lĕ plơ̆ lah jêh ma may bơh ntŭk ndâp nglaih gŭ. Gâp rlong uănh jêh may ta dak Mêriba (Sêla)$b$,true),
('bunong-vn','PSA',81,8,null,$b$Gŭ iăt hom, Ơ phung ƀon lan gâp, jêh ri gâp mra mbơh ma khân may. Ơ Israel, tơ lah khân may mra gŭ iăt gâp!$b$,false),
('bunong-vn','PSA',81,9,null,$b$Mâu mra geh ta nklang khân may du ntil brah bu năch ôh Mâu lĕ khân may chon mon mbah ta năp brah êng$b$,true),
('bunong-vn','PSA',81,10,null,$b$Gâp jêng Yêhôva, Brah Ndu may, Nơm ăn luh jêh tă bơh bri Êjipt; Hă mbung may, jêh ri gâp mra mbêng păng.$b$,false),
('bunong-vn','PSA',81,11,null,$b$Ƀiă lah phung ƀon lan gâp mâu mâp gŭ iăt bâr gâp ôh; Phung Israel mâu mâp tông bâr gâp ôh.$b$,true),
('bunong-vn','PSA',81,12,null,$b$Pô ri gâp jao jêh khân păng tĭng nâm nuih n'hâm dăng khân păng; Gay ma khân păng dơi hăn tĭng nâm nuih n'hâm khân păng nơm mĭn.$b$,true),
('bunong-vn','PSA',81,13,null,$b$Ơ, tơ lah phung ƀon lan gâp mra gŭ iăt gâp, Tơ lah Israel mra hăn tâm trong gâp!$b$,true),
('bunong-vn','PSA',81,14,null,$b$Gâp mra ƀư rai ro phung rlăng khân păng, Jêh ri ti gâp mra tâm rdâng đah phung ƀư mhĭk ma khân păng.$b$,true),
('bunong-vn','PSA',81,15,null,$b$Phung tâm rmot ma Yêhôva mra jan lah lăp păng; Ƀiă lah phung ƀon lan gâp mra gŭ n'ho ro.$b$,true),
('bunong-vn','PSA',81,16,null,$b$Gâp mra siăm khân păng ma ba kapŭng ueh lơn; Jêh ri gâp mra ăn khân păng hơm ma dak sŭt tă bơh lŭ. Nau Nduyh Ma Nau Phat Dôih Mâu sŏng nau mprơ ơm Y-Asap.$b$,true),
('bunong-vn','PSA',82,1,null,$b$Brah Ndu dâk tâm nau phung Brah Ndu tâm rƀŭn; Păng phat dôih ta nklang phung brah.$b$,true),
('bunong-vn','PSA',82,2,null,$b$Ndah nâm jŏ May mra phat dôih ma nau kue. Jêh ri sŏng ma phung ƀai$b$,true),
('bunong-vn','PSA',82,3,null,$b$Mplơ̆ nau sŏng ma phung o ach jêh ri kon đơi khĭt mbơ̆ ; Ƀư nau di ma phung rêh ni jêh ri phung pưt kƀah ndơ.$b$,false),
('bunong-vn','PSA',82,4,null,$b$Tâm rklaih phung rdja jêh ri phung o ach. Ăn khân păng jêng kon me tă bơh ti phung ƀai.$b$,true),
('bunong-vn','PSA',82,5,null,$b$Khân păng mâu gĭt năl, mâu lĕ gĭt rbăng; Khân păng sak nsong tâm nau ngo; Lĕ rngôch ntur neh ntu n'gơ jêh,$b$,true),
('bunong-vn','PSA',82,6,null,$b$Gâp lah jêh, khân may jêng phung brah. Lĕ rngôch khân may jêng kon Nơm klơ lơn.$b$,false),
('bunong-vn','PSA',82,7,null,$b$Ƀiă lah khân may mra khĭt nâm bu phung bunuyh, Khân may mra tŭp nâm bu du huê kon hađăch,$b$,true),
('bunong-vn','PSA',82,8,null,$b$Dâk hom May, Ơ Brah Ndu, phat hôm dôih neh ntu; Yor lah May mra dơn lĕ rngôch phung mpôl băl.$b$,false),
('bunong-vn','PSA',83,1,null,$b$Ơ Brah Ndu lơi gŭ rklăk ôh; Lơi May gŭ iăt săk ôh, Jêh ri lơi May gŭ rlu ôh, Ơ Brah Ndu.$b$,true),
('bunong-vn','PSA',83,2,null,$b$Yor lah aơ, phung rlăng May ƀư nau uh ah; Phung ƀư rlăng đah May ngơ̆ bôk.$b$,true),
('bunong-vn','PSA',83,3,null,$b$Ma phung ƀon lan May khân păng mĭn nau mra ƀư ma nau plăch. Jêh ri khân păng tâm nchră ŭch ƀư ma phung May n'gang$b$,true),
('bunong-vn','PSA',83,4,null,$b$Khân păng lah, văch hom, ăn he ngroh lơi khân păng bơh phung mpôl băl; Gay ma bu mâu hôm kah gĭt ma amoh Israel.$b$,false),
('bunong-vn','PSA',83,5,null,$b$Khân păng tâm nchră jêh du nuih n'hâm; Khân păng tâm rnglăp ndrăng khân păng gay ƀư ma May;$b$,true),
('bunong-vn','PSA',83,6,null,$b$Ngih bok Êđôm jêh ri phung Ismaêl; Phung Môap jêh ri phung Hagar;$b$,false),
('bunong-vn','PSA',83,7,null,$b$Phung Gebal, phung Amôn, jêh ri phung Amalek; Phung Philistin đah phung ƀon lan tir.$b$,false),
('bunong-vn','PSA',83,8,null,$b$Phung Asiri tâm rnglăp đah khân păng lĕ; Khân păng ăn phung kon Y-Lot manh ti khân păng.$b$,true),
('bunong-vn','PSA',83,9,null,$b$Ƀư ma khân păng nâm bu may ƀư jêh kăl e ma phung Madian. Nâm bu ma phung Sêsêra, nâm bu ma Jabin ta n'hor dak Kisôn.$b$,true),
('bunong-vn','PSA',83,10,null,$b$Khân păng rai jêh ta Êndôr Khân păng jêng nâm bu ek jêng neh$b$,true),
('bunong-vn','PSA',83,11,null,$b$N'glưh lơi Kôranh khân păng nâm bu ma Ôreb jêh ri ma Sêeb; Jêh ri ma lĕ phung kon hađăch khân păng, nâm bu ma Sêbol jêh ri ma Salmuna;$b$,false),
('bunong-vn','PSA',83,12,null,$b$Yor lah khân păng lah, Ăn he sŏk pit ntŭk Brah Ndu gŭ.$b$,false),
('bunong-vn','PSA',83,13,null,$b$Ơ Brah Ndu gâp, ăn khân păng jêng nâm bu ndruyh sial đô̆, Nâm bu rhe ba sial đô̆ rdu.$b$,true),
('bunong-vn','PSA',83,14,null,$b$Nâm bu ŭnh sa bri; Nâm bu mpiăt ŭnh sa yôk$b$,true),
('bunong-vn','PSA',83,15,null,$b$Pô ri lĕ, ăn sial phŭt tĭng khân păng; Jêh ri nkrit nhhu khân păng ma sial phŭt ktang$b$,false),
('bunong-vn','PSA',83,16,null,$b$Nkŭm muh măt khân păng ma nau bêk; Gay ma khân păng joi amoh May, Ơ Yêhôva$b$,false),
('bunong-vn','PSA',83,17,null,$b$Ƀư bêk khân păng jêh ri ƀư rŭng khân păng ƀa ƀơ; Nanê̆, tâm rlŭk nau mĭn khân păng, jêh ri ăn khân păng rai lôch;$b$,false),
('bunong-vn','PSA',83,18,null,$b$Gay ma khân păng gĭt knŏng May yơh djôt amoh Yêhôva. Jêng Nơm Ta klơ Lơn ma lĕ neh ntu.$b$,false),
('bunong-vn','PSA',84,1,null,$b$Bu rŏng ngăn ma ntŭk May gŭ, Ơ Yêhôva ma phung tahan!$b$,true),
('bunong-vn','PSA',84,2,null,$b$Huêng gâp ŭch ngăn jêh ri klêu ma nkuah ngih Yêhôva; Nuih n'hâm gâp jêh ri nglay săk nter ma Brah Ndu rêh.$b$,true),
('bunong-vn','PSA',84,3,null,$b$Nđâp ma sĭm djrăch djrao geh ngih gŭ, Jêh ri sĭm rlêng geh rsuăn dơm kon păng gŭ. Jêng nơng ƀư brah May, Ơ Yêhôva ma phung Tahan, Hađăch gâp, jêh ri Brah Ndu gâp.$b$,true),
('bunong-vn','PSA',84,4,null,$b$Ueh maak yơh phung gŭ tâm ngih May; Khân păng mra gŭ tâm rnê ma May (Sêla)$b$,true),
('bunong-vn','PSA',84,5,null,$b$Ueh maak yơh ma phung bunuyh geh nau ktang tâm May; Phung geh tâm nuih n'hâm trong hăn ta Siôn.$b$,false),
('bunong-vn','PSA',84,6,null,$b$Tơ lah khân păng rgăn rlŭng Baka, njêng păng jêng ntŭk bêng ma bôk dak; Jêh ri dak mih bôk rah nkŭm păng ma nau ueh uĭn.$b$,true),
('bunong-vn','PSA',84,7,null,$b$Nau ktang khân păng lŏ hao dôl khân păng hăn; Ăp nơm khân păng hăn, nhhơ khân păng nơm ta năp Brah Ndu ta Siôn.$b$,true),
('bunong-vn','PSA',84,8,null,$b$Ơ Yêhôva, Brah Ndu ma phung tahan, gŭ iăt nau gâp mbơh sơm; Rkêng hom tôr May, Ơ Brah Ndu Yakôb. (Sêla)$b$,true),
('bunong-vn','PSA',84,9,null,$b$Uănh hom, ơ Brah Ndu, nơm jêng khêl hên, Jêh ri uănh muh măt, nơm may hŏ troch jêh dak ngi.$b$,false),
('bunong-vn','PSA',84,10,null,$b$Yor lah du nar tâm nkual may jêng ueh lơn ma du rbăn ta ntŭk êng. Gâp ŭch lơn gŭ chiă uănh mpông bloh ngih Brah Ndu gâp, Ma gŭ tâm ngih bok nau ƀai.$b$,true),
('bunong-vn','PSA',84,11,null,$b$Yor lah Yêhôva Brah Ndu jêng nar jêh ri khêl; Yêhôva mra ăn nau yô̆ jêh ri nau chrêk rmah; Păng mâu dun du ntil nau ueh ôh ma phung hăn tâm nau sŏng;$b$,true),
('bunong-vn','PSA',84,12,null,$b$Ơ Yêhôva ma phung tahan, Ueh maak yơh ma bunuyh rnơm ma May.$b$,false),
('bunong-vn','PSA',85,1,null,$b$Ơ Yêhôva, May ăn jêh nau ueh ma n'gor May nơm; May njŭn sĭt jêh phung bu nă Yakôb.$b$,true),
('bunong-vn','PSA',85,2,null,$b$May yô̆ an jêh ma nau kue phung ƀon lan May; May nkŭm jêh lĕ rngôch nau tih khân păng. (Sêla)$b$,true),
('bunong-vn','PSA',85,3,null,$b$May lơi lĕ jêh nau may ji nuih; May vir jêh bơh nau May duh nuih.$b$,false),
('bunong-vn','PSA',85,4,null,$b$Rdâk nhhơk hên, Ơ Brah Ndu nau tâm rklaih hên, Ăn May cha lơi nau May ji nuih ma hên.$b$,true),
('bunong-vn','PSA',85,5,null,$b$May mra ji nuih ma hên n'ho ro lĕ? May prăp lĕ nau May nuih n'ho ma lĕ rngôch rnôk?$b$,true),
('bunong-vn','PSA',85,6,null,$b$May mâu mra lŏ ăn nau rêh ma hên lĕ? Gay ma phung ƀon lan may dơi geh nau maak tâm May?$b$,true),
('bunong-vn','PSA',85,7,null,$b$Ơ Yêhôva, ăn hên saơ nau ueh May, Jêh ri ăn ma hên nau May tâm rklaih$b$,true),
('bunong-vn','PSA',85,8,null,$b$Gâp mra iăt moh nau Brah Ndu Yêhôva lah, Yor lah Păng mra ngơi nau đăp mpăn ma phung ƀon lan păng, nđâp ma phung kloh ueh păng; Ƀiă lah lơi ăn khân păng lŏ vir ma nau rluk ôh.$b$,false),
('bunong-vn','PSA',85,9,null,$b$Na nê̆ nau păng tâm rklaih gŭ dăch phung klach ma păng, Gay ma nau chrêk rmah dơi gŭ tâm bri he.$b$,true),
('bunong-vn','PSA',85,10,null,$b$Nau yô̆ đah nau nanê̆ tâm mâp; Nau sŏng srăng jêh ri nau đăp mpăn tâm ut.$b$,true),
('bunong-vn','PSA',85,11,null,$b$Nau nanê̆ hon tă bơh neh; Jêh ri nau sŏng srăng gŭ uănh bơh klơ trôk.$b$,true),
('bunong-vn','PSA',85,12,null,$b$Nanê̆ Yêhôva mra ăn nau ueh; Jêh ri neh he mra geh play;$b$,true),
('bunong-vn','PSA',85,13,null,$b$Nau sŏng srăng mra hăn ta năp Păng, Jêh ri mra ăn he tĭng têl jâng Păng.$b$,false),
('bunong-vn','PSA',86,1,null,$b$Ơ Yêhôva, rkêng tôr May, plơ̆ lah hom ma gâp; Yor lah gâp jêng rêh ni jêh ri o ach.$b$,true),
('bunong-vn','PSA',86,2,null,$b$Chiă uănh huêng gâp; Yor lah gâp yơk ma May; Ơ Brah Ndu gâp, tâm rklaih hom oh mon May, nơm rnơm ma May;$b$,true),
('bunong-vn','PSA',86,3,null,$b$Yô̆ nđach an ma gâp, Ơ Kôranh Brah; Yor lah gâp nter ma May lĕ nar.$b$,false),
('bunong-vn','PSA',86,4,null,$b$Ƀư maak hom huêng oh mon May; Yor ma May, Ơ Kôranh Brah, gâp nhhơr huêng gâp.$b$,true),
('bunong-vn','PSA',86,5,null,$b$Yor lah May jêng ueh, Ơ Kôranh Brah, May blau yô̆ an, May bêng ma nau ueh ma lĕ rngôch phung kuăl mbơh sơm ma May.$b$,true),
('bunong-vn','PSA',86,6,null,$b$Ơ Yêhôva rkêng tôr May ma nau gâp mbơh sơm; Iăt nanê̆ ma bâr gâp vơh vơl;$b$,true),
('bunong-vn','PSA',86,7,null,$b$Gâp kuăl mbơh sơm ma May tâm nar rêh ni; Yor lah May mra lŏ plơ̆ lah ma gâp,$b$,false),
('bunong-vn','PSA',86,8,null,$b$Ơ Kôranh Brah, mâu geh nơm jêng nâm bu May tâm phung brah; Mâu lĕ geh kan nâm bu kan May.$b$,false),
('bunong-vn','PSA',86,9,null,$b$Lĕ rngôch phung mpôl băl May mra văch chon mon mbah ta năp May, Ơ Kôranh Brah; Jêh ri khân păng mra ăn nau chrêk rmah ma amoh May.$b$,true),
('bunong-vn','PSA',86,10,null,$b$Yor lah May jêng toyh, jêh ri May ƀư nau khlay; Knŏng êng may jêng Brah Ndu.$b$,true),
('bunong-vn','PSA',86,11,null,$b$Ơ Yêhôva, sâm nti gâp trong May; Gâp mra hăn tâm nau nanê̆ May; Nkra nuih n'hâm gâp ăn blau klach yơk ma amoh May.$b$,true),
('bunong-vn','PSA',86,12,null,$b$Gâp mra tâm rnê ma May, Ơ Kôranh Brah, Brah Ndu gâp, ma lĕ nuih n'hâm; Jêh ri gâp mra mât ton ma amoh May ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',86,13,null,$b$Yor lah nau ueh May toyh ngăn ma gâp; Jêh ri may tâm rklaih jêh huêng gâp bơh ƀon phung khĭt jru lơn.$b$,true),
('bunong-vn','PSA',86,14,null,$b$Ơ Brah Ndu, phung sưr dâk ƀư ma gâp. Du phung bunuyh ƀai tĭng ƀư ma huêng gâp, Khân păng mâu mâp mĭn ma May ôh.$b$,true),
('bunong-vn','PSA',86,15,null,$b$Ƀiă lah May, Ơ Kôranh Brah, May jêng Kôranh Brah Ndu blau yô̆, jêh ri geh nuih n'hâm ueh. Mâu gơnh nuih, ndrŏng ma nau ueh, jêh ri ma nau nanê̆.$b$,true),
('bunong-vn','PSA',86,16,null,$b$N'gĭl uănh ta gâp, jêh ri yô̆ nđach ma gâp; Ăn nau ktang may ma oh mon May. Jêh ri tâm rklaih kon bu klâu oh mon bu ur May.$b$,true),
('bunong-vn','PSA',86,17,null,$b$Ăn ma gâp du nau tâm mbên ma nau May yô̆, gay ma phung tâm rmot ma gâp mra saơ, jêh ri bêk. Yor lah May, Ơ Yêhôva, koh dŏng gâp jêh ri bonh gâp.$b$,true),
('bunong-vn','PSA',87,1,null,$b$Ntur păng n'gân gŭ tâm yôk kloh ueh,$b$,true),
('bunong-vn','PSA',87,2,null,$b$Yêhôva rŏng ma mpông pêr Siôn âk lơn ma lĕ rngôch ntŭk Yakôb.$b$,false),
('bunong-vn','PSA',87,3,null,$b$Bu ngơi nau chrêk rmah ma may, Ơ ƀon Brah Ndu. (Sêla)$b$,true),
('bunong-vn','PSA',87,4,null,$b$Gâp mra mbơh bri Êjipt jêh ri Babilôn ndrel ma phung gĭt năl gâp; Aơ bri Philistin, ƀon Tir đah bri Êthiôpi; tâm Siôn bu deh jêh ma khân păng.$b$,false),
('bunong-vn','PSA',87,5,null,$b$Nanê̆ ma Siôn bu mra lah, phung aơ nđâp phung nây bu deh jêh ta nây; jêh ri Nơm Klơ Lơn yơh mra ƀư nâp păng.$b$,true),
('bunong-vn','PSA',87,6,null,$b$Tơ lah Yêhôva mra chih phung ƀon lan, Păng mra kơp ma phung aơ bu deh ta nây. (Sêla)$b$,true),
('bunong-vn','PSA',87,7,null,$b$Phung mprơ jêh ri phung kadŏ mra lah, Lĕ rngôch nau gâp geh bôk tâm May.$b$,false),
('bunong-vn','PSA',88,1,null,$b$Ơ Yêhôva, Brah Ndu ma nau tâm rklaih gâp, Gâp nter măng nâm nar ta năp May.$b$,true),
('bunong-vn','PSA',88,2,null,$b$Ăn nau gâp mbơh sơm hao tât ta May; rkêng tôr May ma nau gâp dăn vơh vơl;$b$,true),
('bunong-vn','PSA',88,3,null,$b$Yor lah huêng gâp bêng ma nau rŭng, Jêh ri nau rêh gâp hăn dăch ta Ƀon Phung khĭt.$b$,false),
('bunong-vn','PSA',88,4,null,$b$Bu kơp gâp ndrel ma phung jŭr ta trôm jru; Gâp jêng nâm bu du huê bu klâu mâu geh nau ktang,$b$,true),
('bunong-vn','PSA',88,5,null,$b$Bu cha lơi jêh gâp ndrel ma phung khĭt; Tâm ban ma phung bu khĭt jêh, njor jêh tâm môch, Ma phung nây May mâu hôm kah gĭt ôh. Khân păng tâm nkhah jêh bơh ti May.$b$,false),
('bunong-vn','PSA',88,6,null,$b$May hŏ njor jêh gâp tâm ntu jru lơn Tâm ntŭk ngo, tâm ntu jru.$b$,true),
('bunong-vn','PSA',88,7,null,$b$Nau May ji nuih ƀư jâk gâp, May ƀư rêh ni gâp ma lĕ rngôch dak sial njach. (Sêla)$b$,true),
('bunong-vn','PSA',88,8,null,$b$May ƀư ngai đah gâp phung mĭt jiăng gâp; May njêng gâp du ndơ nhhu khân păng; Bu krŭng gâp, jêh ri gâp mâu dơi lah ôh.$b$,false),
('bunong-vn','PSA',88,9,null,$b$Măt gâp ngo tâm nau rêh ni; Gâp kuăl mbơh sơm ma May ăp nar, Ơ Yêhôva; Gâp yơr jêh ti gâp ma May.$b$,true),
('bunong-vn','PSA',88,10,null,$b$Ma phung khĭt hĕ May mra tâm mpơl nau khlay? Phung khĭt mra dâk tâm rnê ma May lĕ? (Sêla)$b$,true),
('bunong-vn','PSA',88,11,null,$b$Bu mra mbơh lĕ nau ueh May tâm môch? Mâu lah nau răp jăp May tâm Abadôn?$b$,false),
('bunong-vn','PSA',88,12,null,$b$Kan khlay bu mra gĭt năl lĕ tâm ntŭk ngo? Jêh ri nau sŏng srăng May tâm n'gor nau chuêl?$b$,true),
('bunong-vn','PSA',88,13,null,$b$Ƀiă lah, Ơ Yêhôva, gâp vơh vơl ma May; Tâm ôi nau gâp mbơh sơm mra hao ma May.$b$,true),
('bunong-vn','PSA',88,14,null,$b$Ơ Yêhôva, mâm ƀư may lơi huêng gâp? Mâm ƀư may pôn muh măt May ma gâp?$b$,true),
('bunong-vn','PSA',88,15,null,$b$Gâp jêng rêh ni jêh ri dăch khĭt ntơm bơh gâp hôm mom Dôl gâp mâp đah nau May nhhu gâp jêng rŭng răng.$b$,true),
('bunong-vn','PSA',88,16,null,$b$Nau May ji nuih ktang ngăn ta klơ gâp; Nau May nhhu koh lơi gâp.$b$,true),
('bunong-vn','PSA',88,17,null,$b$Khân păng gŭ jŭm gâp lĕ nar nâm bu dak; Khân păng nchueng gâp ndrel n'grŭp.$b$,true),
('bunong-vn','PSA',88,18,null,$b$May ƀư ngai đah gâp, phung mĭt jiăng gâp jêh ri phung gâp rŏng, Jêh ri phung băl gâp tâm ntŭk ngo.$b$,true),
('bunong-vn','PSA',89,1,null,$b$Gâp mra mprơ ƀa ƀơ ma nau ueh Yêhôva; Bâr mbung gâp mra mbơh nau răp jăp may tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','PSA',89,2,null,$b$Yor lah gâp lah jêh, nau yô̆ geh ntur gŭ n'ho ro; May mra rdâk nau răp jăp May tâm trôk.$b$,true),
('bunong-vn','PSA',89,3,null,$b$Gâp ƀư jêh nau tâm rnglăp đah nơm gâp săch jêh, Gâp sân săk jêh đah Y-Đavit oh mon gâp;$b$,true),
('bunong-vn','PSA',89,4,null,$b$Gâp mra ăn nâp phung kon sau may ƀa ƀơ. Jêh ri gâp mra rdâk sưng hađăch may gŭ tâm lĕ rngôch rnôk, (Sêla)$b$,false),
('bunong-vn','PSA',89,5,null,$b$Ơ Yêhôva, trôk mra tâm rnê ma kan khlay May; Jêh ri nau răp jăp May tâm nau tâm rƀŭn phung kloh ueh.$b$,false),
('bunong-vn','PSA',89,6,null,$b$Yor lah tâm trôk mbu nâm ƀư, dơi tâm ban ma Yêhôva? Mbu nâm jêng tâm ban ma Yêhôva, tâm phung kon bu klâu Brah Ndu?$b$,true),
('bunong-vn','PSA',89,7,null,$b$Brah Ndu khư ma nau bu rnam klach, tâm nau tâm rƀŭn toyh phung kloh ueh. Jêh ri khư klach yơk, âk lơn ma lĕ rngôch phung gŭ jŭm păng.$b$,true),
('bunong-vn','PSA',89,8,null,$b$Ơ Yêhôva, Brah Ndu phung tahan, Mbu nâm brah tâm ban ma May, Ơ Yêhôva? Nau răp jăp May gŭ jŭm May.$b$,true),
('bunong-vn','PSA',89,9,null,$b$May chiă uănh nau sưr phung dak rlai; Tơ lah dak rlai ntơm sial njach. May ăn khân păng gŭ đăp mpăn,$b$,true),
('bunong-vn','PSA',89,10,null,$b$may ƀư chah bri Êjipt nâm bu du mlâm săk jăn khĭt; May ntrŭt jêh phung rlăng May ma nau brah ti May.$b$,false),
('bunong-vn','PSA',89,11,null,$b$Trôk jêh ri neh ntu jêng ndơ May; May yơh rdâk jêh ntur neh ntu, jêh ri lĕ ndơ tâm păng.$b$,true),
('bunong-vn','PSA',89,12,null,$b$May njêng jêh yôk jêh ri rđŭng. Yôk tabôr jêh ri yôk Hêrmôn hâk răm tâm amoh May.$b$,true),
('bunong-vn','PSA',89,13,null,$b$Nting tur May brah; Ti May ktang, jêh ri ti ma May yơr ta klơ.$b$,true),
('bunong-vn','PSA',89,14,null,$b$Nau sŏng srăng jêh ri nau di, jêng ntur ma sưng hađăch May; Nau ueh jêh ri nau nanê̆ hăn ta năp May$b$,true),
('bunong-vn','PSA',89,15,null,$b$Ueh maak yơh ma phung ƀon lan gĭt năl bâr nau răm maak; Khân păng hăn tâm nau ang, bơh muh măt May, Ơ Yêhôva.$b$,false),
('bunong-vn','PSA',89,16,null,$b$Khân păng răm maak lĕ nar tâm amoh May; Jêh ri tâm nau sŏng srăng May khân păng geh nau yơk.$b$,true),
('bunong-vn','PSA',89,17,null,$b$Yor lah may jêng nau chrêk rmah ma nau ktang khân păng; Ma nau yô̆ may yơh nke hên mra hao lơn.$b$,true),
('bunong-vn','PSA',89,18,null,$b$Yor lah Yêhôva jêng khêl hên. Nơm kloh ueh Israel jêng hađăch hên.$b$,true),
('bunong-vn','PSA',89,19,null,$b$Dôl may ngơi tâm nau tâm saơ ma nơm kloh ueh May; Jêh ri lah, gâp ăn nau kơl jêh ma du huê nơm ktang; Gâp n'hao jêh bơh nklang phung ƀon lan du huê gâp dăch.$b$,true),
('bunong-vn','PSA',89,20,null,$b$Gâp tâm mâp jêh đah Y-Đavit, oh mon gâp; Gâp troch jêh dak ngi kloh ueh gâp ta păng.$b$,true),
('bunong-vn','PSA',89,21,null,$b$Ti gâp mra kuăn rdâng păng; Jêh ri nting tur gâp mra ƀư ktang păng.$b$,true),
('bunong-vn','PSA',89,22,null,$b$Nơm rlăng mâu mra dơi ƀư ma păng, Kon ƀai mâu lĕ mra tŭn jot păng.$b$,true),
('bunong-vn','PSA',89,23,null,$b$Gâp mra tâm nchah ta năp păng phung rlăng đah păng, Jêh ri gâp mra dong phung tâm rmot ma păng.$b$,true),
('bunong-vn','PSA',89,24,null,$b$Ƀiă lah nau răp jăp gâp, jêh ri nau ueh gâp mra gŭ ndrel păng; Jêh ri nke păng mra hao yor amoh gâp.$b$,true),
('bunong-vn','PSA',89,25,null,$b$Gâp mra dơm ti păng ta dak rlai, Jêh ri ti ma păng ta dak krong.$b$,true),
('bunong-vn','PSA',89,26,null,$b$Păng mra nter ma gâp, may jêng Mbơ̆ gâp, Brah Ndu gâp jêh ri lŭ nau tâm rklaih gâp.$b$,true),
('bunong-vn','PSA',89,27,null,$b$Jêh ri gâp mra ăn păng jêng nơm gâp deh lor. Hađăch klơ lơn ma phung hađăch ta neh ntu.$b$,true),
('bunong-vn','PSA',89,28,null,$b$Gâp mra prăp nau ueh gâp ma păng n'ho ro; Nau gâp tâm rnglăp mra gŭ răp jăp đah Păng.$b$,true),
('bunong-vn','PSA',89,29,null,$b$Gâp mra ăn phung kon sau Păng gŭ n'ho ro. Jêh ri sưng hađăch păng nâm bu nar tâm trôk.$b$,true),
('bunong-vn','PSA',89,30,null,$b$Tơ lah phung kon bu klâu păng lơi nau vay gâp. Jêh ri mâu hăn ôh tĭng nâm nau gâp ntăm;$b$,true),
('bunong-vn','PSA',89,31,null,$b$Tơ lah khân păng rlau nau vay gâp; Jêh ri mâu tông ôh nau vay gâp ntăm;$b$,false),
('bunong-vn','PSA',89,32,null,$b$Pô ri gâp mra tâm rmal ma mâng, nau khân păng rlau, Jêh ri nau kue khân păng đah nau gâp dong.$b$,false),
('bunong-vn','PSA',89,33,null,$b$Ƀiă lah gâp mâu mra sŏk sĭt ôh, nau ueh gâp tă bơh păng. Mâu lĕ gâp mra cha lơi nau răp jăp gâp.$b$,true),
('bunong-vn','PSA',89,34,null,$b$Gâp mâu mra rlau ôh nau gâp tâm rnglăp. Mâu lĕ gâp mra tâm rgâl, moh nau luh jêh bơh bâr mbung gâp.$b$,true),
('bunong-vn','PSA',89,35,null,$b$Gâp sân jêh săk gâp du tơ̆ ma nau kloh ueh gâp. Gâp mâu mra mƀruh ôh đah Y-Đavit:$b$,true),
('bunong-vn','PSA',89,36,null,$b$Phung kon sau păng mra gŭ ƀa ƀơ. Sưng hađăch păng mra jêng nâm bu nar ta năp gâp.$b$,false),
('bunong-vn','PSA',89,37,null,$b$Păng mra gŭ n'ho ro nâm bu khay; Nơm mbơh tâm trôk jêng răp jăp. (Sêla)$b$,true),
('bunong-vn','PSA',89,38,null,$b$Ƀiă lah may dun jêh ri cha lơi nơm may troch jêh dak ngi, may nuih jêh ma păng$b$,false),
('bunong-vn','PSA',89,39,null,$b$may tâm rmot jêh nau tâm rnglăp đah oh mon may, may nklơ̆ jêh, ƀư ƀơ̆ jêh đon hađăch păng.$b$,false),
('bunong-vn','PSA',89,40,null,$b$Ƀư cha lôt lĕ jêh pêr mbâl păng; may ƀư rai lĕ jêh pôih n'gang păng$b$,true),
('bunong-vn','PSA',89,41,null,$b$Lĕ rngôch phung rgăn pit sŏk ndơ bơh păng; Păng jêng ndơ ƀư bêk ma phung chiau meng păng.$b$,false),
('bunong-vn','PSA',89,42,null,$b$May n'hao jêh ti ma phung rlăng păng; may ăn jêh lĕ rngôch phung rlăng păng răm maak.$b$,true),
('bunong-vn','PSA',89,43,null,$b$Nanê̆ may plăch lơi măt đao gưm Păng, Jêh ri may mâu kuăn rdâng păng ôh, tâm nau tâm lơh.$b$,true),
('bunong-vn','PSA',89,44,null,$b$May ƀư lôch jêh nau chrêk rmah păng. Jêh ri may klŭp lơi jêh sưng hađăch păng ta neh.$b$,true),
('bunong-vn','PSA',89,45,null,$b$May ăn gleh jêh nar păng jêng mom; may nkŭm jêh păng ma nau bêk. (Sêla)$b$,true),
('bunong-vn','PSA',89,46,null,$b$Dŭm nâm jŏ, Ơ Yêhôva, may mra pôn may nơm? Jêh ri nau may ji nuih mra su nâm bu ŭnh lĕ?$b$,false),
('bunong-vn','PSA',89,47,null,$b$Ăn may kah gĭt ma rnôk gâp jêng gleh; Yor nau dơm dam may njêng jêh lĕ rngôch, kon bu klâu phung bu nuyh?$b$,true),
('bunong-vn','PSA',89,48,null,$b$Mbu bunuyh dơi gŭ rêh, jêh ri mâu saơ nau khĭt ôh. Nơm dơi tâm rklaih huêng păng nơm, ma nau brah Ƀon Phung khĭt? (Sêla)$b$,true),
('bunong-vn','PSA',89,49,null,$b$Ơ Kôranh Brah, mbah nau ueh May kăl e. Nau May sơm săk jêh đah Y-Đavit tâm nau May gŭ răp jăp?$b$,false),
('bunong-vn','PSA',89,50,null,$b$Kah gĭt hom, Ơ Kôranh Brah, ma nau bêk phung oh mon May; Ma nau gâp ndjôt tâm nuih n'hâm gâp, nau bêk bah lĕ rngôch bunuyh ƀon lan âk ngăn.$b$,true),
('bunong-vn','PSA',89,51,null,$b$Ma nau phung rlăng May suai rak, Ơ Yêhôva, Ma nau khân păng suai rak ma nhuat nơm May troch jêh dak ngi.$b$,true),
('bunong-vn','PSA',89,52,null,$b$Mât ton ƀa ƀơ ma Yêhôva Amen. Amen.$b$,true),
('bunong-vn','PSA',90,1,null,$b$Ơ Kôranh Brah, May jêng jêh ntŭk hên gŭ. Tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','PSA',90,2,null,$b$Lor ma bu deh ma phung yôk, Jêh ri lor May njêng neh jêh ri neh ntu. Bơh rnôk n'ho ro, ma rnôk n'ho ro May jêng Brah Ndu.$b$,true),
('bunong-vn','PSA',90,3,null,$b$May mplơ̆ lơi bunuyh ma ndruyh neh, Jêh ri May lah, Ơ phung kon bunuyh, plơ̆ sĭt hom.$b$,true),
('bunong-vn','PSA',90,4,null,$b$Yor lah du rbăn năm ta năp măt May; Jêng nâm bu nar nđaơ lăn jêh, jêh ri tâm ban ma du sruh gak dôl măng.$b$,true),
('bunong-vn','PSA',90,5,null,$b$May sŏk lơi khân păng nâm bu dak rdu; nâm bu lêt bêch; Khân păng jêng nâm bu gơ̆ hon ôi.$b$,true),
('bunong-vn','PSA',90,6,null,$b$Păng kao ơm ôi; jêh ri hon; Bu koh păng mhaơ, jêh ri kro.$b$,true),
('bunong-vn','PSA',90,7,null,$b$Yor lah nau May nuih su hên jêh, Jêh ri nau May nuih ƀư rŭng hên.$b$,true),
('bunong-vn','PSA',90,8,null,$b$May dơn jêh nau kue hên ta năp May; Jêh ri ta năp nau ang muh măt May nau tih hên ndâp.$b$,true),
('bunong-vn','PSA',90,9,null,$b$Lĕ rngôch nar hên roh ta năp nau May ji nuih; Hên saơ năm hên lôch nâm bu suh n'hâm.$b$,true),
('bunong-vn','PSA',90,10,null,$b$Nar năm hên gŭ rêh jêng pơh jât năm Mâu lah ma phung ktang lơn jêng pham jât năm; Ăt nau sưr khân păng jêng nau ŏk jêh ri nau rngot; Yor lah Păng rgăn ngăch jêh ri hên mpăr du.$b$,true),
('bunong-vn','PSA',90,11,null,$b$Mbu gĭt năl nau brah nau May ji nuih; Nđâp ma nau May nuih tĭng nâm nau klach yơk khư ma May?$b$,true),
('bunong-vn','PSA',90,12,null,$b$Pô ri sâm nti hom hên blau kơp nar hên. Gay ma nuih n'hâm hên pơk nau gĭt mĭn.$b$,true),
('bunong-vn','PSA',90,13,null,$b$Lŏ sĭt, Ơ Yêhôva; ndah nâm jŏ? Tâm rgâl lơi nau May ƀư di ma phung oh mon May.$b$,true),
('bunong-vn','PSA',90,14,null,$b$Ăp ôi n'hơm hên ma nau ueh May; Gay ma hên mra răm jêh ri maak lĕ nau rêh hên.$b$,true),
('bunong-vn','PSA',90,15,null,$b$Ƀư maak nuih n'hâm hên, ăn tâm ban đah nar May ƀư rêh ni jêh hên. Ăn tâm ban đah năm hên saơ jêh nau mhĭk.$b$,true),
('bunong-vn','PSA',90,16,null,$b$Ăn kan May tâm mpơl ma phung oh mon May. Jêh ri nau chrêk rmah May ma phung kon khân păng.$b$,true),
('bunong-vn','PSA',90,17,null,$b$Ăn nau yô̆ Kôranh Brah, Brah Ndu hên, gŭ ta klơ hên; Ƀư nâp hom kan hên ƀư; Nanê̆, ƀư nâp hom kan ti hên ƀư.$b$,true),
('bunong-vn','PSA',91,1,null,$b$Mbu nâm gŭ tâm ntŭk ndâp Nơm Klơ Lơn. Mra gŭ tâm dâng gui Nơm Brah Lơn.$b$,true),
('bunong-vn','PSA',91,2,null,$b$Gâp mra lah ma Yêhôva, Păng jêng ntŭk gâp gŭ krap jêh ri pôih n'gang gâp. Brah Ndu gâp, tâm păng gâp rnơm.$b$,true),
('bunong-vn','PSA',91,3,null,$b$Păng yơh bu tâm rklaih may bơh nhuăl nơm djang sĭm, Jêh ri nau ji nkhĭt âk bunuyh.$b$,true),
('bunong-vn','PSA',91,4,null,$b$Păng mra nkŭm may ma rsau năr Păng. Jêh ri may mra du krap tâm dâng năr Păng. Nau nanê̆ păng jêng khêl toyh jêh ri khêl jê̆.$b$,true),
('bunong-vn','PSA',91,5,null,$b$May mâu mra klach ôh ma nau djơh mhĭk dôl măng. Mâu lĕ klach ma hăr mpăr dôl nar;$b$,true),
('bunong-vn','PSA',91,6,null,$b$Mâu lah nau ji tưp tâm nau ngo, mâu lah nau rai yot dôl nôk nar.$b$,false),
('bunong-vn','PSA',91,7,null,$b$Du rbăn nuyh mra prah ta meng may. Jêh ri jât rbăn nuyh cha lôt khĭt jŭm may; Ƀiă lah nau nây mâu mra tât dăch may ôh.$b$,true),
('bunong-vn','PSA',91,8,null,$b$Ƀiă lah knŏng may mra uănh ma măt may; Jêh ri saơ nau lŏ mplơ̆ sĭt ma phung ƀai.$b$,true),
('bunong-vn','PSA',91,9,null,$b$Yor lah May jêng ntŭk du krap, Ơ Yêhôva! May njêng jêh Nơm klơ Lơn ntŭk may du krap;$b$,true),
('bunong-vn','PSA',91,10,null,$b$Mâu geh du ntil ndơ mhĭk mra tât ma may ôh, Mâu lĕ mra geh du ntil nau tưp hăn dăch ngih bok may.$b$,false),
('bunong-vn','PSA',91,11,null,$b$Yor lah Păng mra đă tông mpăr păng N'gang may tâm lĕ rngôch trong may nsong.$b$,true),
('bunong-vn','PSA',91,12,null,$b$Khân păng mra chông may ma mpang ti khân păng, Klach lah jâng may nchânh ma lŭ$b$,true),
('bunong-vn','PSA',91,13,null,$b$may mra hăn ta klơ yau mŭr jêh ri bêh rmâng; may mra jot nkrâm kon yau mŭr jêh ri bêh nhŭk nhăk.$b$,false),
('bunong-vn','PSA',91,14,null,$b$Yor lah păng rŏng ma gâp, gâp mra tâm rklaih păng. Gâp mra n'gang păng, Yor lah păng gĭt năl amoh gâp.$b$,true),
('bunong-vn','PSA',91,15,null,$b$Păng mra kuăl mbơh sơm ma gâp, Jêh ri gâp mra lŏ plơ̆ lah ma Păng; gâp mra gŭ ndrel ma Păng tâm nau rŭng răng; Gâp mra tâm rklaih păng, jêh ri gâp mra yơk ma păng.$b$,true),
('bunong-vn','PSA',91,16,null,$b$Gâp mra ăn păng hơm ma nau rêh jong; Jêh ri gâp mra ăn păng saơ nau gâp tâm rklaih. Mât Ton Tâm Rnê Yor Nau Ueh Yêhôva.$b$,true),
('bunong-vn','PSA',92,1,null,$b$Ueh maak tâm rnê ma Yêhôva, Jêh ri mprơ tâm rnê ma amoh May. Ơ Nơm Klơ Lơn;$b$,true),
('bunong-vn','PSA',92,2,null,$b$Ŭch mbơh bơh ôi nau ueh May. Jêh ri ăp măng nau răp jăp May.$b$,false),
('bunong-vn','PSA',92,3,null,$b$Ma gong rêng jât rse, nđâp ma rlet; Kreh gong rêng ma bâr nau yơk.$b$,true),
('bunong-vn','PSA',92,4,null,$b$Ơ Yêhôva, May ƀư maak jêh gâp ma kan May. Gâp mra dơi tâm kan ti May.$b$,true),
('bunong-vn','PSA',92,5,null,$b$Ơ Yêhôva, kan May toyh ngăn! Nau mĭn May jêng jru ngăn.$b$,true),
('bunong-vn','PSA',92,6,null,$b$Bunuyh rluk mâu gĭt năl nau nây ôh; Bunuyh rluk mâu gĭt lĕ;$b$,true),
('bunong-vn','PSA',92,7,null,$b$Tơ lah phung ƀai văch ma toyh nâm bu gơ̆ . Jêh ri tơ lah lĕ rngôch phung ƀư nau kue ăn kao; Knŏng prăp khân păng ma nau ƀư rai n'ho ro.$b$,false),
('bunong-vn','PSA',92,8,null,$b$Ƀiă lah May, Ơ Yêhôva, gŭ ta klơ lơn n'ho ro.$b$,true),
('bunong-vn','PSA',92,9,null,$b$Yor lah, aơ, phung rlăng May, Ơ Yêhôva, Yor lah aơ, phung rlăng May mra rai lôch; Lĕ rngôch phung ƀư nau kue mra nchah du.$b$,true),
('bunong-vn','PSA',92,10,null,$b$Ƀiă lah May ăn nke gâp hao nâm bu nke ndrôk bri; Bu troch jêh gâp ma dak ngi mhe.$b$,true),
('bunong-vn','PSA',92,11,null,$b$Măt gâp saơ jêh nau gâp ŭch ăn tât ma phung rlăng đah gâp. Tôr gâp tăng jêh nau gâp ŭch, ăn tât ma phung tâm rdâng đah gâp.$b$,true),
('bunong-vn','PSA',92,12,null,$b$Phung sŏng srăng mra văch ma toyh nâm bu tơm Tră Khân păng mra văch ma toyh nâm bu tơm si Sêdrơ ta n'gor Liban.$b$,true),
('bunong-vn','PSA',92,13,null,$b$Bu tăm khân păng tâm ngih Yêhôva; Khân păng mra kao ta nkual Brah Ndu hên.$b$,true),
('bunong-vn','PSA',92,14,null,$b$Păng mra ăt play dôl ranh; Păng bêng ma ntăk jêh ri ndrêh;$b$,true),
('bunong-vn','PSA',92,15,null,$b$Gay tâm mpơl ma Yêhôva jêng sŏng; Păng yơh jêng lŭ gâp, jêh ri mâu geh du ntil nau kue ôh tâm păng.$b$,false),
('bunong-vn','PSA',93,1,null,$b$Yêhôva chiă uănh, Păng nsoh jêh nau chrêk rmah. Yêhôva nsoh jêh nau ktang; Păng rêt jêh Păng nơm ma nau nây. Pô ri lĕ neh ntu jêng nâp, păng mâu n'gơ ôh.$b$,true),
('bunong-vn','PSA',93,2,null,$b$Sưng hađăch May jêng nâp bơh rnôk kăl e; May gŭ n'ho ro.$b$,true),
('bunong-vn','PSA',93,3,null,$b$Phung dak krong tâm n'hao, Ơ Yêhôva; Phung dak krong tâm n'hao jêh bâr khân păng; Phung dak krong tâm n'hao nteh.$b$,true),
('bunong-vn','PSA',93,4,null,$b$Huy lơn ma nteh dak âk, Mpiăt dak rlai njach ktang, Yêhôva ta klơ jêng brah.$b$,true),
('bunong-vn','PSA',93,5,null,$b$Nau May mbơh jêng nâp ngăn; Nau kloh ueh jêng di ma ngih May, Ơ Yêhôva, ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',94,1,null,$b$Ơ Yêhôva, May jêng Brah Ndu ma nau plơng, sol hom.$b$,true),
('bunong-vn','PSA',94,2,null,$b$Dâk hom May, Ơ Kôranh phat dôih ma neh ntu; Nsĭt lơi ma phung sưr tĭng nâm khân păng khư.$b$,true),
('bunong-vn','PSA',94,3,null,$b$Ndah nâm jŏ phung ƀai mra geh nau dơi?$b$,true),
('bunong-vn','PSA',94,4,null,$b$Khân păng ngơi ta năp bu, khân păng ngơi ma nau sưr; Lĕ rngôch phung ƀư nau kue, tâm rnê ma khân păng nơm.$b$,true),
('bunong-vn','PSA',94,5,null,$b$Khân păng jot blên phung ƀon lan May. Jêh ri khân păng ƀư rêh ni phung drăp ndơ May.$b$,true),
('bunong-vn','PSA',94,6,null,$b$Khân păng nkhĭt phung bu ur ndrô khĭt sai, jêh ri bu năch. Khân păng nkhĭt lơi phung kon đơi mbơ̆ .$b$,true),
('bunong-vn','PSA',94,7,null,$b$Jêh ri khân păng lah, Yêhôva mâu mra saơ ôh. Mâu lĕ Brah Ndu Yakôb mra njrăng ma nau nây.$b$,true),
('bunong-vn','PSA',94,8,null,$b$Njrăng hom ơ phung rluk; Jêh ri phung rluk, ndah jŏ khân may mra jêng phung blau mĭn?$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PSA',94,9,null,$b$Nơm tăm jêh, păng mâu mra tăng hĕ?$b$,true),
('bunong-vn','PSA',94,10,null,$b$Nơm nkra phung mpôl băl bunuyh, mâu hĕ păng mra tâm rmal? Păng nơm ăn nau gĭt rbăng ma bunuyh.$b$,true),
('bunong-vn','PSA',94,11,null,$b$Yêhôva gĭt năl nau mĭn bunuyh. Păng gĭt nau mĭn khân păng jêng dơm dam.$b$,true),
('bunong-vn','PSA',94,12,null,$b$Ueh maak yơh bunuyh May nkra, Ơ Yêhôva, Jêh ri nti ma păng nau vay May;$b$,true),
('bunong-vn','PSA',94,13,null,$b$Gay ăn ma păng nau rlu dôl nar mhĭk, Kŏ bu kuyh jêh ntu jru ma phung ƀai.$b$,false),
('bunong-vn','PSA',94,14,null,$b$Yor lah Yêhôva mâu mra cha lơi ôh phung ƀon lan Păng, Mâu lĕ Păng mra cha lơi phung drăp ndơ Păng.$b$,true),
('bunong-vn','PSA',94,15,null,$b$Yor lah nau phat dôih mra lŏ plơ̆ sĭt ma nau sŏng; Jêh ri lĕ rngôch phung geh nuih n'hâm sŏng mra tĭng ndô̆ nau nây.$b$,true),
('bunong-vn','PSA',94,16,null,$b$Mbu mra dâk ăn ma gâp, gay ƀư ma phung ƀai? Mbu nâm mra n'gang gâp ƀư ma phung kơt nau kue?$b$,true),
('bunong-vn','PSA',94,17,null,$b$Tơ lah Yêhôva mâu jêng nơm koh dŏng gâp. Huêng gâp gŭ jêh tâm ntŭk nau rklăk.$b$,true),
('bunong-vn','PSA',94,18,null,$b$Tơ lah gâp lah, jâng gâp prah; Nau ueh May, Ơ Yêhôva, Kuăn rdâng gâp jêh.$b$,true),
('bunong-vn','PSA',94,19,null,$b$Tơ lah gâp geh âk nau mĭn. Nau May bonh jêng maak huêng gâp.$b$,true),
('bunong-vn','PSA',94,20,null,$b$Dơi lĕ sưng hađăch nau ƀai geh nau tâm rnglăp đah May? Phung nây njêng nau tih đah nau vay.$b$,true),
('bunong-vn','PSA',94,21,null,$b$Khân păng tâm rƀŭn gay ƀư ma huêng bunuyh sŏng, Jêh ri khân păng tâm rmal mham bunuyh sŏng,$b$,true),
('bunong-vn','PSA',94,22,null,$b$Ƀiă lah Yêhôva jêng tŭm prêh gâp, Brah Ndu gâp jêng lŭ, ntŭk gâp gŭ krap.$b$,false),
('bunong-vn','PSA',94,23,null,$b$Păng ăn tŭp jêh ta khân păng nau kue khân păng, Păng mra koh lơi phung nây tâm nau ƀai khân păng; Yêhôva; Brah Ndu he, mra koh lơi khân păng.$b$,true),
('bunong-vn','PSA',95,1,null,$b$Văch hom, ăn he tâm rnê ma Yêhôva. Ăn he nter maak ma Lŭ nau tâm rklaih he.$b$,true),
('bunong-vn','PSA',95,2,null,$b$Ăn he hăn ta năp Păng ma nau tâm rnê; Ăn he nter hâk ma Păng ma nau mprơ ơm.$b$,true),
('bunong-vn','PSA',95,3,null,$b$Yor lah Yêhôva jêng Brah Ndu toyh. Păng jêng hađăch toyh ta klơ lơn ma lĕ rngôch brah.$b$,true),
('bunong-vn','PSA',95,4,null,$b$Ntŭk jru tâm neh ntu gŭ tâm ti Păng; Jêh ri kô yôk jêng ndơ Păng;$b$,true),
('bunong-vn','PSA',95,5,null,$b$Dak rlai jêng ndơ Păng jêh ri Păng njêng; Neh sơh tâm ban lĕ, ti Păng yơh nkra.$b$,false),
('bunong-vn','PSA',95,6,null,$b$Văch hom, ăn he chon mon jêh ri yơk; Ăn he chon kômâk ta năp Yêhôva, Nơm rhăk njêng he.$b$,true),
('bunong-vn','PSA',95,7,null,$b$Yor lah Păng jêng Brah Ndu he, He jêng phung ƀon lan tâm ndrêch gơ̆ nse Păng. Jêh ri phung biăp ti Păng njŭn, Nar aơ tơ lah khân ay may tăng bâr Păng.$b$,true),
('bunong-vn','PSA',95,8,null,$b$Lơi ƀư dăng ôh nuih n'hâm khân may nâm bu ta Mêriba. Nâm bu ta nar Masa, tâm ndrêch rdah;$b$,true),
('bunong-vn','PSA',95,9,null,$b$Ta nây phung mbơ̆ khân may rlong uănh jêh Gâp, Khân păng rlong uănh Gâp, jêh ri saơ jêh kan Gâp.$b$,false),
('bunong-vn','PSA',95,10,null,$b$Dôl tâm puăn jât năm gâp rngot yor phung mpôl băl nây, Pô ri Gâp lah, khân păng jêng du phung ƀon lan teng trong mâu gĭt năl ôh trong Gâp;$b$,true),
('bunong-vn','PSA',95,11,null,$b$Yor nây Gâp sân săk jêh tâm nau gâp ji nuih. Khân păng mâu mra lăp tâm nau Gâp rlu ôh.$b$,false),
('bunong-vn','PSA',96,1,null,$b$Mprơ hom ma Yêhôva du nau mprơ mhe. Mprơ hom ma Yêhôva, lĕ rngôch phung gŭ ta neh ntu.$b$,true),
('bunong-vn','PSA',96,2,null,$b$Mprơ hom ma Yêhôva, mât ton hom ma amoh Păng; Mbơh ăp nar nau Păng tâm rklaih.$b$,true),
('bunong-vn','PSA',96,3,null,$b$Nkoch bri nau chrêk rmah Păng ta nklang phung mpôl băl. Kan khlay Păng ta nklang lĕ rngôch phung ƀon lan.$b$,true),
('bunong-vn','PSA',96,4,null,$b$Yor lah Yêhôva jêng toyh, jêh ri khư tâm rnê; Păng khư bu klach yơk rlau lơn ma lĕ rngôch brah,$b$,true),
('bunong-vn','PSA',96,5,null,$b$Yor lah lĕ rngôch brah phung ƀon lan mbah jêng knŏng rup; Ƀiă lah Yêhôva rhăk jêh trôk.$b$,false),
('bunong-vn','PSA',96,6,null,$b$Nau yơk jêh ri nau chrêk rmah gŭ ta năp Păng; Nau ktang jêh ri nau ueh gŭ tâm ntŭk kloh ueh Păng,$b$,true),
('bunong-vn','PSA',96,7,null,$b$Mpôl băl phung ƀon lan mplơ̆ hom ma Yêhôva. Mplơ̆ hom ma Yêhôva nau chrêk rmah, jêh ri nau ktang.$b$,false),
('bunong-vn','PSA',96,8,null,$b$Mplơ̆ hom ma Yêhôva nau chrêk rmah khư ma amoh Păng; Ndjôt leo ndơ nhhơr jêh ri lăp tâm nkual Păng.$b$,true),
('bunong-vn','PSA',96,9,null,$b$Yơk hom ma Yêhôva ma nau nkrơ̆ nau kloh ueh. Râm nsâr hom ta năp Păng, Ơ lĕ rngôch phung ta neh ntu.$b$,true),
('bunong-vn','PSA',96,10,null,$b$Lah hom ta nklang phung mpôl băl, Yêhôva chiă uănh; Tâm ban lĕ neh ntu jêng nâp, jêh ri păng mâu dơi n'gơ ôh. Yêhôva mra phat dôih phung ƀon lan ma nau sŏng.$b$,true),
('bunong-vn','PSA',96,11,null,$b$Ăn trôk maak, jêh ri ăn neh ntu hâk răm. Ăn dak rlai nteh, nđâp lĕ rngôch mpa tâm Păng;$b$,true),
('bunong-vn','PSA',96,12,null,$b$Ăn bri geh nau hâk, nđâp ma lĕ rngôch mpa tâm păng; Pô ri lĕ rngôch tơm si tâm bri mra mprơ răm maak.$b$,false),
('bunong-vn','PSA',96,13,null,$b$Ta năp Yêhôva; Yor lah Păng văch gay phat dôih neh ntu; Păng mra phat dôih neh ntu; ma nau sŏng srăng. Jêh ri phung ƀon lan ma nau nanê̆ Păng.$b$,true),
('bunong-vn','PSA',97,1,null,$b$Yêhôva chiă uănh; ăn neh ntu geh nau hâk răm; Ăn phung kô dak âk geh nau maak$b$,true),
('bunong-vn','PSA',97,2,null,$b$Ndâr tŭk jêh ri nau ngo gŭ jŭm Păng. Nau sŏng srăng jêh ri nau di, jêng ntur ma sưng hađăch Păng,$b$,false),
('bunong-vn','PSA',97,3,null,$b$Ŭnh hăn ta năp Păng, jêh ri su phung rlăng gŭ jŭm Păng.$b$,false),
('bunong-vn','PSA',97,4,null,$b$Lơp păng ƀư ang neh ntu; Neh ntu saơ jêh râm sâr.$b$,true),
('bunong-vn','PSA',97,5,null,$b$Phung yôk lêk nâm bu mpêt ta năp Yêhôva. Ta năp Kôranh Brah ma lĕ neh ntu.$b$,true),
('bunong-vn','PSA',97,6,null,$b$Trôk mbơh nau sŏng srăng Păng. Jêh ri lĕ rngôch phung ƀon lan saơ jêh nau chrêk rmah Păng.$b$,true),
('bunong-vn','PSA',97,7,null,$b$Ăn ƀư bêk khân păng, lĕ rngôch phung mbah ma rup brah. Phung rnơm tâm rup brah khân păng; Yơk hom ma Păng, Ơ lĕ rngôch khân may phung brah.$b$,true),
('bunong-vn','PSA',97,8,null,$b$Ƀon Siôn tăng nau nây jêh ri gŭ maak. Phung kon bu ur Yuđa hâk răm. Yor nau may phat dôih, Ơ Yêhôva.$b$,true),
('bunong-vn','PSA',97,9,null,$b$Yor lah may, Ơ Yêhôva, jêng klơ lơn ma lĕ neh ntu; may geh nau yơk âk lơn ma lĕ rngôch brah.$b$,true),
('bunong-vn','PSA',97,10,null,$b$Tâm rmot ma nau djơh, Ơ khân may phung rŏng ma Yêhôva; Păng chiă uănh huêng phung kloh ueh Păng; Tâm rklaih khân păng bơh ti phung ƀai.$b$,true),
('bunong-vn','PSA',97,11,null,$b$Bu tăm nau ang ma phung sŏng. Jêh ri nau maak ma phung geh nuih n'hâm sŏng.$b$,true),
('bunong-vn','PSA',97,12,null,$b$Ơ phung sŏng, maak hom khân may tâm Yêhôva; Jêh ri kah gĭt tôr, tơ lah kah gĭt ma nau kloh ueh Păng. Kuăl Phung Ƀon Lan Tâm Rnê Ma Yêhôva Yor nau sŏng păng. Nau mprơ ơm.$b$,true),
('bunong-vn','PSA',98,1,null,$b$Mprơ hom ma Yêhôva nau mprơ mhe; Yor lah păng ƀư jêh nau khlay; Ti ma jêh ri nting tur kloh Păng, ƀư jêh nau tâm rklaih Păng.$b$,true),
('bunong-vn','PSA',98,2,null,$b$Yêhôva tâm mpơl jêh nau Păng tâm rklaih; Păng tâm mpơl rah vah jêh nau sŏng srăng Păng, ta năp măt phung mpôl băl bunuyh.$b$,true),
('bunong-vn','PSA',98,3,null,$b$Păng kah gĭt jêh ma nau ueh Păng, jêh ri ma nau răp jăp Păng đah ngih Israel; Lĕ rngôch pĭt lôch bri neh, saơ jêh nau Brah Ndu he tâm rklaih.$b$,true),
('bunong-vn','PSA',98,4,null,$b$Ăn khân may nter răm maak ma Yêhôva, Hơi lĕ rngôch phung gŭ ta neh ntu, răm maak hom ma Yêhôva, mprơ tâm rnê hom ma nau răm maak!$b$,true),
('bunong-vn','PSA',98,5,null,$b$Mprơ tâm rnê hom ma Yêhôva ma gong rêng; Ma gong rêng, mprơ hom nau mprơ.$b$,true),
('bunong-vn','PSA',98,6,null,$b$Ma nŭng jêh ri ma bâr nŭng jê̆, Nter hâk răm hom ta năp hađăch, Yêhôva.$b$,true),
('bunong-vn','PSA',98,7,null,$b$Ăn dak rlai ƀư nteh, nđâp lĕ rngôch mpa tâm păng; Neh ntu, nđâp phung gŭ tâm păng;$b$,true),
('bunong-vn','PSA',98,8,null,$b$Ăn phung dak krong tap ti; Ăn lĕ rngôch yôk mprơ maak n'grŭp ndrel.$b$,false),
('bunong-vn','PSA',98,9,null,$b$Ta năp Yêhôva; Yor lah Păng văch phat dôih neh ntu; Păng mra phat dôih neh ntu ma nau sŏng srăng, Jêh ri phung ƀon lan ma nau di. Kuăl Phung Ƀon Lan Tâm Rnê Ma Yêhôva Yor nau sŏng păng. Nau mprơ ơm.$b$,true),
('bunong-vn','PSA',99,1,null,$b$Yêhôva chiă uănh; ăn phung ƀon lan râm sâr; Păng gŭ tâm dâng phung Chêrubim, ăn neh ntu n'gơ.$b$,true),
('bunong-vn','PSA',99,2,null,$b$Yêhôva jêng toyh tâm Siôn; Jêh ri Păng jêng klơ lơn ma lĕ rngôch phung ƀon lan.$b$,true),
('bunong-vn','PSA',99,3,null,$b$Ăn khân păng tâm rnê ma amoh May, toyh jêh ri khư ma nau klach; păng yơh jêng kloh ueh.$b$,true),
('bunong-vn','PSA',99,4,null,$b$Nau ktang hađăch rŏng ma nau sŏng; May yơh rdâk nau di; May yơh ƀư nau phat dôih jêh ri nau sŏng srăng tâm Yakôb$b$,true),
('bunong-vn','PSA',99,5,null,$b$Yơk mbah hom ma Yêhôva, Brah Ndu he, ăn khân may chon mbah, ta năp ntŭk Păng chrong jâng; Păng yơh jêng Kloh Ueh.$b$,false),
('bunong-vn','PSA',99,6,null,$b$Y-Môis jêh ri Y-Arôn gŭ ta nklang phung Kôranh ƀư brah Păng. Jêh ri Y-Samuel ta nklang phung kuăl mbơh sơm ma amoh Păng; Khân păng kuăl mbơh sơm ma Yêhôva, jêh ri păng lŏ plơ̆ lah ma khân păng.$b$,true),
('bunong-vn','PSA',99,7,null,$b$Yêhôva ngơi ma khân păng tâm ndâr tŭk mbâl; Khân păng djôt prăp nau Yêhôva mbơh. Jêh ri nau vay Păng ăn ma khân păng jêh.$b$,true),
('bunong-vn','PSA',99,8,null,$b$Ơ Yêhôva, Brah Ndu hên, may lŏ plơ̆ lah jêh ma khân păng; may jêng nguay Brah Ndu yô̆ an ma khân păng. Nđâp tơ lah may plơng bôk jêh ma nau khân păng ƀư.$b$,true),
('bunong-vn','PSA',99,9,null,$b$Yơk hom khân may ma Yêhôva, Brah Ndu he, Jêh ri mbah hom ta yôk kloh ueh Păng; Yor lah Yêhôva, Brah Ndu he, jêng kloh ueh.$b$,true),
('bunong-vn','PSA',100,1,null,$b$Nter răm maak hom ma Yêhôva, Ơ lĕ rngôch khân may phung gŭ ta neh ntu.$b$,true),
('bunong-vn','PSA',100,2,null,$b$Pah kan hom ma Yêhôva ma nau maak; Hăn ta năp Păng ma nau mprơ.$b$,true),
('bunong-vn','PSA',100,3,null,$b$Ăn khân may gĭt ma Yêhôva jêng Brah Ndu; Păng yơh njêng jêh he, he jêng ndơ Păng; He jêng phung ƀon lan Păng jêh ri phung biăp tâm ndrêch gơ̆ Păng.$b$,true),
('bunong-vn','PSA',100,4,null,$b$Lăp hom tâm mpông pêr Păng ma nau tâm rnê, jêh ri tâm nkual ngih Păng ma nau mât ton; Tâm rnê Păng, mât ton ma amoh Păng.$b$,true),
('bunong-vn','PSA',100,5,null,$b$Yor lah Yêhôva jêng ueh; nau ueh Păng gŭ ƀa ƀơ. Jêh ri nau răp jăp Păng ăt gŭ tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','PSA',101,1,null,$b$Gâp mra mprơ ma nau ueh jêh ri nau sŏng; Ma May yơh, Ơ Yêhôva gâp mra mprơ tâm rnê;$b$,true),
('bunong-vn','PSA',101,2,null,$b$Gâp mra njrăng tâm trong rah vah, Ndah jŏ May mra văch ta gâp? Gâp mra hăn tâm ngih gâp ma nuih n'hâm rah vah.$b$,false),
('bunong-vn','PSA',101,3,null,$b$Gâp mâu mra dơm du ntil ndơ mhĭk ôh ta năp măt gâp; Gâp tâm rmot ma kan phung mâu rjăp; Kan nây mâu mra khan ma gâp ôh$b$,true),
('bunong-vn','PSA',101,4,null,$b$Nuih n'hâm tih mhĭk mra du ngai đah gâp; Gâp mâu mra gĭt năl bunuyh mhĭk ôh.$b$,false),
('bunong-vn','PSA',101,5,null,$b$Mbu nâm nchơt ma nau ndâp ma phung chiau meng păng, gâp mra ƀư rai păng, Bu nâm geh nau uănh sưr, jêh ri nuih n'hâm sưr, gâp mâu mra dơn păng ôh.$b$,true),
('bunong-vn','PSA',101,6,null,$b$Măt gâp mra uănh ma phung răp jăp tâm n'gor, gay ăn khân păng gŭ ndrel ma gâp; Mbu nâm hăn tâm nau rah vah, nơm nây mra pah kan ma gâp.$b$,true),
('bunong-vn','PSA',101,7,null,$b$Mbu nâm jao păng nơm, ma nau ndơm, mâu mra gŭ tâm ngih gâp ôh; Mbu nâm ngơi nau mƀruh, mâu mra gŭ rjăp ta năp măt gâp ôh.$b$,true),
('bunong-vn','PSA',101,8,null,$b$Ăp ôi gâp mra ƀư rai lĕ rngôch phung ƀai tâm n'gor; Gay ma lĕ rngôch phung ƀư kue mra roh bơh ƀon Yêhôva. Nau Du Huê Nơm Rêh Ni Vơh Vơl Nau Yô̆ Ma Păng Nơm, Jêh Ri Ma Ƀon Siôn. Nau mbơh sơm du huê nơm rdja nuih n'hâm jêh ri păng tâm mpơl nau păng nđêng rngot ta năp Yêhôva$b$,true),
('bunong-vn','PSA',102,1,null,$b$Ơ Yêhôva, iăt hom nau gâp mbơh sơm, Jêh ri ăn nau gâp nter hao tât ta may.$b$,true),
('bunong-vn','PSA',102,2,null,$b$Lơi pôn muh măt may ma gâp ôh, dôl nar gâp geh nau rêh ni; Rkêng tôr may ma gâp; Tơ lah gâp nter may plơ̆ lah ma gâp ăn gơnh.$b$,true),
('bunong-vn','PSA',102,3,null,$b$Yor lah nar gâp roh, du nâm bu nhhŭk ŭnh. Jêh ri nting gâp rai nâm bu ŭnh sa sa-ônh.$b$,true),
('bunong-vn','PSA',102,4,null,$b$Nuih n'hâm gâp bu dong, jêh ri jêng kro nâm bu gơ̆ ; Kŏ gâp chuêl sa kapŭng gâp.$b$,true),
('bunong-vn','PSA',102,5,null,$b$Yor bâr gâp nđêng. Nting gâp krăp đah nglay gâp.$b$,true),
('bunong-vn','PSA',102,6,null,$b$Gâp jêng nâm bu sĭm djrăch djrao tâm ndrêch rdah. Gâp jêng nâm bu klang kô tâm bri hŏng.$b$,true),
('bunong-vn','PSA',102,7,null,$b$Gâp rngeh, jêh ri gâp jêng nâm bu du mlâm sĭm srai. Gŭ êng ta chor bôk pho.$b$,true),
('bunong-vn','PSA',102,8,null,$b$Lĕ nar phung rlăng đah gâp suai rak ma gâp; Jêh ri phung nuih ma gâp, dŏng amoh gâp rtăp rak.$b$,true),
('bunong-vn','PSA',102,9,null,$b$Yor lah gâp sa jêh buh nâm bu kapŭng. Jêh ri gâp lŭk lai dak, gâp nhêt ndrel ma dak măt.$b$,true),
('bunong-vn','PSA',102,10,null,$b$Yor lah nau may ji nuih jêh ri ji nuih; Yor may rƀiah nhŭp gâp, jêh ri mƀăr gâp ngai.$b$,true),
('bunong-vn','PSA',102,11,null,$b$Nar gâp jêng nâm bu gui dăch roh; Jêh ri gâp kro jêh nâm bu gơ̆ .$b$,true),
('bunong-vn','PSA',102,12,null,$b$Ƀiă lah May, Ơ Yêhôva, mra gŭ n'ho ro; Jêh ri nau kah gĭt ma May tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','PSA',102,13,null,$b$May mra dâk, jêh ri May yô̆ ma ƀon Siôn; Yor lah tât jêh nar yô̆ ma păng, nanê̆, nar tâm nal tât jêh.$b$,true),
('bunong-vn','PSA',102,14,null,$b$Yor lah phung oh mon May rŏng ma lŭ păng, Khân păng yô̆ ma ndruyh neh păng.$b$,true),
('bunong-vn','PSA',102,15,null,$b$Pô ri phung mpôl băl mra klach yơk mbah ma amoh Yêhôva, Lĕ rngôch phung hađăch ta neh ntu, mra klach yơk mbah ma nau chrêk rmah May.$b$,true),
('bunong-vn','PSA',102,16,null,$b$Yor lah Yêhôva rdâk jêh ƀon Siôn, Păng tâm mpơl jêh tâm nau chrêk rmah Păng.$b$,true),
('bunong-vn','PSA',102,17,null,$b$Păng kâp iăt jêh nau phung rêh ni mbơh sơm, Păng mâu tâm rmot ma nau bu mbơh sơm ôh.$b$,true),
('bunong-vn','PSA',102,18,null,$b$Nau nây bu mra chih tâm rnôk kăndơ̆ ; Jêh ri phung ƀon lan bu mra rhăk njêng pa kơi, mra tâm rnê ma Yêhôva.$b$,true),
('bunong-vn','PSA',102,19,null,$b$Yor lah Yêhôva uănh jêh tâm dâng bơh ngih kloh ueh Păng klơ; Bơh trôk Yêhôva uănh ta neh ntu;$b$,true),
('bunong-vn','PSA',102,20,null,$b$Ŭch iăt nau phung bu nă nđêng; Gay ma klaih phung bu jao jêh ma nau khĭt;$b$,false),
('bunong-vn','PSA',102,21,null,$b$Gay ma phung bunuyh mbơh amoh Yêhôva tâm ƀon Siôn, Jêh ri nau tâm rnê Păng tâm ƀon Yêrusalem;$b$,false),
('bunong-vn','PSA',102,22,null,$b$Tơ lah lĕ rngôch phung ƀon lan tâm rƀŭn, Jêh ri phung ƀon bri hađăch, gay pah kan ma Yêhôva.$b$,false),
('bunong-vn','PSA',102,23,null,$b$Brah Ndu ƀư rdja jêh nau ktang gâp ta trong; Păng ƀư gleh n'hŭch lơi nar gâp.$b$,true),
('bunong-vn','PSA',102,24,null,$b$Gâp lah, Ơ Brah Ndu gâp, lơi sŏk gâp ta n'gul nar gâp ôh; Năm May gŭ tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','PSA',102,25,null,$b$Kăl e May rhăk njêng jêh neh ntu; Jêh ri trôk jêng kan ti May nơm.$b$,true),
('bunong-vn','PSA',102,26,null,$b$Khân păng mra rai lôch, ƀiă lah May ăt hôm; Nanê̆ khân păng mra rmŭch lĕ nâm bu bok ao; may mra tâm rgâl khân păng nâm bu du blah ao, Jêh ri khân păng mra tâm rgâl;$b$,true),
('bunong-vn','PSA',102,27,null,$b$Ƀiă lah May ăt hôm tâm ban, Jêh ri năm May mâu mra lĕ ôh.$b$,false),
('bunong-vn','PSA',102,28,null,$b$Phung kon phung oh mon May mra gŭ hôm nâp, Jêh ri phung kon sau khân păng gŭ rjăp ta năp May.$b$,true),
('bunong-vn','PSA',103,1,null,$b$Ơ huêng gâp tâm rnê hom ma Yêhôva; Lĕ săk jăn nuih n'hâm gâp tâm rnê yơk mbah ma amoh Păng.$b$,true),
('bunong-vn','PSA',103,2,null,$b$Ơ huêng gâp tâm rnê hom ma Yêhôva; Lơi dĭng chuêl ôh lĕ ntil nau ueh Păng ăn.$b$,true),
('bunong-vn','PSA',103,3,null,$b$Păng yơh yô̆ an lĕ nau tih gâp. Păng ƀư bah lĕ nau ji kuet gâp.$b$,true),
('bunong-vn','PSA',103,4,null,$b$Păng yơh tâm rklaih gâp tă bơh trôm môch, Păng yô̆, Păng rŏng ma gâp hâu ngăn.$b$,true),
('bunong-vn','PSA',103,5,null,$b$Păng n'hơm ko gâp ma ndơ kah, Gay ăn gâp văch n'hâm suan dăng ktang nâm bu klang.$b$,true),
('bunong-vn','PSA',103,6,null,$b$Yêhôva ƀư nau sŏng, Păng ƀư nau di ma lĕ rngôch phung bu tŭn jot.$b$,true),
('bunong-vn','PSA',103,7,null,$b$Păng tâm mpơl jêh trong Păng ma Y-Môis. Kan Păng ma phung kon Israel.$b$,true),
('bunong-vn','PSA',103,8,null,$b$Kôranh Brah yô̆ jêh ri rŏng ma he, Păng mâu gơnh nuih ôh.$b$,true),
('bunong-vn','PSA',103,9,null,$b$Păng mâu ir nduyh he ƀa ƀơ ôh, Mâu lĕ Păng nđom jŏ n'ho ro, nau Păng ji nuih ma he$b$,true),
('bunong-vn','PSA',103,10,null,$b$Păng mâu tâm rmal he ôh, tĭng nâm nau tih he ƀư, Mâu lĕ Păng mplơ̆ tĭng nâm nau tih, nau kue he.$b$,false),
('bunong-vn','PSA',103,11,null,$b$Nau Păng rŏng ma mbu nâm yơk ma Păng jêng toyh ngăn, Prêh nâm bu trôk đah neh.$b$,true),
('bunong-vn','PSA',103,12,null,$b$Păng sŏk nkhah lơi nau tih đah he, ngai nâm bu dâng đah lơ.$b$,true),
('bunong-vn','PSA',103,13,null,$b$Păng yô̆ ma mbu nâm yơk ma Păng, nâm bu mbơ̆ yô̆ ma kon.$b$,true),
('bunong-vn','PSA',103,14,null,$b$Yor lah Păng gĭt mbă ndơ bu njêng he, Păng kah gĭt he jêng ndruyh neh.$b$,true),
('bunong-vn','PSA',103,15,null,$b$Nau rêh kon bunuyh gơnh dŭt tâm ban ma gơ̆ , Păng hon rêh ƀât lât dơm, tâm ban ma kao si tâm bri.$b$,true),
('bunong-vn','PSA',103,16,null,$b$Lah sial khôm du tong, păng mpăr roh hêng, bu mâu hôm saơ păng ôh,$b$,true),
('bunong-vn','PSA',103,17,null,$b$Ƀiă lah Kôranh Brah hôm rŏng ƀa ƀơ mbu nâm yơk ma Păng, Păng ăn nau ueh ƀa ƀơ tât sau tât se.$b$,false),
('bunong-vn','PSA',103,18,null,$b$Păng rŏng ma mbu nâm ƀư di tĭng nâm nau Păng tâm nkol, Jêh ri ma phung kah gĭt tông nanê̆ lĕ nau Păng đă.$b$,true),
('bunong-vn','PSA',103,19,null,$b$Yêhôva rdâk jêh sưng hađăch Păng tâm trôk; Jêh ri ƀon bri hađăch Păng chiă uănh lĕ rngôch ndơ.$b$,true),
('bunong-vn','PSA',103,20,null,$b$Mât ton hom ma Yêhôva, khân may phung oh mon ueh Păng, Phung jêng brah tâm nau ktang, gay ma nanê̆ nau Păng ngơi. Phung gŭ iăt bâr Păng ngơi.$b$,true),
('bunong-vn','PSA',103,21,null,$b$Mât ton hom ma Yêhôva, lĕ rngôch khân may phung tahan Păng, Phung khân may pah kan ma Păng, jêh ri ƀư nau Păng ŭch.$b$,true),
('bunong-vn','PSA',103,22,null,$b$Mât ton hom ma Yêhôva, lĕ rngôch khân may jêng kan Păng, Tâm lĕ rngôch ntŭk Păng chiă uănh;$b$,true),
('bunong-vn','PSA',104,1,null,$b$Ơ huêng gâp, mât ton hom ma Yêhôva. Ơ Yêhôva, Brah Ndu gâp, May jêng toyh ngăn; May nsoh jêh nau yơk jêh ri nau rnam nchrat ral (majesty)$b$,true),
('bunong-vn','PSA',104,2,null,$b$Yêhôva nkŭm Păng Nơm ma nau ang, nâm bu du bu lah ao mbâl; Păng lăk trôk nâm bu du bu lah ngih bok.$b$,false),
('bunong-vn','PSA',104,3,null,$b$Păng ƀư ngih ta klơ mpiăt dak; Păng ăn ndâr tŭk jêng ndeh Păng; Păng hăn ta klơ năr sial;$b$,true),
('bunong-vn','PSA',104,4,null,$b$Păng ăn sial jêng oh mon ueh Păng; Jêh ri mpiăt ŭnh jêng oh mon ktang Păng;$b$,false),
('bunong-vn','PSA',104,5,null,$b$Păng dơm neh ta klơ ntur Păng, Gay ma păng mâu mra mâp n'gơ ôh.$b$,false),
('bunong-vn','PSA',104,6,null,$b$May nkŭm jêh păng ma ntŭk jru nâm bu bok ao; Phung dak hao prêh lơn ma phung yôk.$b$,true),
('bunong-vn','PSA',104,7,null,$b$Ta năp nau May nduyh, khân păng du jêh; Tăng nteh nglaih May, khân păng du gơnh.$b$,true),
('bunong-vn','PSA',104,8,null,$b$(Phung yôk hao ta klơ, jêh ri phung rđŭng jêng nduh) Ta ntŭk May tâm nal jêh ma khân păng.$b$,true),
('bunong-vn','PSA',104,9,null,$b$May nkra n'har jêh, gay ma dak mâu rlau ôh; Gay lơi ăn khân păng lŏ sĭt nkŭm lơi neh ntu.$b$,true),
('bunong-vn','PSA',104,10,null,$b$Brah Ndu ăn tu dak hoch tâm rlŭng; Khân păng hoch vah vang phung yôk.$b$,true),
('bunong-vn','PSA',104,11,null,$b$Khân păng ăn lĕ rngôch jun tâm bri nhêt; Phung seh bri bah ji hir yor dak nây.$b$,true),
('bunong-vn','PSA',104,12,null,$b$Phung sĭm tâm trôk gŭ rŏ kơh păng; Jêh ri gŭ nhhiăng tâm n'gĭng si.$b$,true),
('bunong-vn','PSA',104,13,null,$b$Bơh ntŭk păng klơ, păng djrah phung yôk. Neh ntu hơm ma play bah kan May.$b$,true),
('bunong-vn','PSA',104,14,null,$b$Păng ăn gơ̆ hon ma phung ndrôk, Jêh ri trau ma bunuyh dŏng; Gay ma păng dơi ăn hon ndơ sông sa bơh neh.$b$,true),
('bunong-vn','PSA',104,15,null,$b$Dak play kriăk ƀâu, ƀư maak nuih n'hâm bunuyh. Jêh ri dak ngi ăn muh măt păng ang. Jêh ri kapŭng ƀư ktang nuih n'hâm păng.$b$,true),
('bunong-vn','PSA',104,16,null,$b$Tơm si Yêhôva geh nau hơm jêh, Tơm si Sêdrơ n'gor Liban păng tăm jêh;$b$,true),
('bunong-vn','PSA',104,17,null,$b$Ta nây phung sĭm ƀư rsuăn khân păng Bi phung sĭm klang kok geh ntŭk ma khân păng tâm tơm n'ho.$b$,false),
('bunong-vn','PSA',104,18,null,$b$Phung yôk prêh prăp ma phung be bri; Lŭ prăp ma phung rpai gŭ.$b$,true),
('bunong-vn','PSA',104,19,null,$b$Yêhôva ăn jêh khay ŭch ăn bu gĭt yăn; Nar nđat jŏ păng nhâp.$b$,true),
('bunong-vn','PSA',104,20,null,$b$May njêng nau ngo, jêh ri geh măng, Dôl nây lĕ rngôch jun tâm bri mpât nsong.$b$,true),
('bunong-vn','PSA',104,21,null,$b$Phung kon yau mŭr ngrông ma mpô mpa, khân păng tĭng nhŭp, jêh ri joi ndơ khân păng sa bơh Brah Ndu.$b$,true),
('bunong-vn','PSA',104,22,null,$b$Nar luh, khân păng hăn sĭt, Jêh ri hăn bêch tâm trôm khân păng gŭ.$b$,true),
('bunong-vn','PSA',104,23,null,$b$Bunuyh luh hăn ma kan păng pah Jêh ri ma nau păng ƀư kŏ măng trôk.$b$,true),
('bunong-vn','PSA',104,24,null,$b$Ơ Yêhôva, kan may âk ngăn ngên! May ƀư lĕ khân păng ma nau blau mĭn; Neh ntu bêng jêh ma drăp May.$b$,true),
('bunong-vn','PSA',104,25,null,$b$Aơ, dak rlai toyh jêh ri dĭ. Ta nây geh mpa vơr, mâu dơi kơp mpô mpa jê̆ jêh ri toyh.$b$,true),
('bunong-vn','PSA',104,26,null,$b$Ta nây phung kumpăn nsong; Jêh ri Lêviathan, May njêng jêh ăn nsong pâl tâm mpiăt dak.$b$,true),
('bunong-vn','PSA',104,27,null,$b$Lĕ rngôch phung jun nây kâp May, Gay ma May ăn ndơ ma khân păng sa tâm mông găl.$b$,true),
('bunong-vn','PSA',104,28,null,$b$May ăn ndơ sa, jêh ri khân păng sŏk dơn; May mplơt ti May, jêh ri khân păng bêng ler ma drăp ndơ May.$b$,true),
('bunong-vn','PSA',104,29,null,$b$May pôn măt May, khân păng rŭng; May sŏk lơi n'hâm tă bơh khân păng, khân păng khĭt.$b$,true),
('bunong-vn','PSA',104,30,null,$b$May njuăl Brah Huêng May, khân păng jêng ro; Jêh ri May ƀư mhe muh măt neh ntu.$b$,true),
('bunong-vn','PSA',104,31,null,$b$Ăn nau chrêk rmah Yêhôva gŭ ƀa ƀơ; Ăn Yêhôva răm maak tâm kan Păng;$b$,true),
('bunong-vn','PSA',104,32,null,$b$Păng uănh ma neh ntu, jêh ri păng râm sâr; Păng rbot phung yôk, jêh ri khân păng luh nhhŭk ŭnh.$b$,false),
('bunong-vn','PSA',104,33,null,$b$Gâp mra mprơ ma Yêhôva dôl gâp geh nau rêh; Gâp mra mprơ tâm rnê ma Brah Ndu gâp dôl gâp gŭ rêh,$b$,true),
('bunong-vn','PSA',104,34,null,$b$Ăn nau gâp mĭn dơi ƀư maak ma Păng; Gâp mra răm maak tâm Yêhôva,$b$,false),
('bunong-vn','PSA',104,35,null,$b$Ăn phung tih rai lôch bơh neh ntu. Jêh ri lơi hôm geh phung ƀai. Ơ huêng gâp, mât ton hom ma Yêhôva Halêluya.$b$,false),
('bunong-vn','PSA',105,1,null,$b$Tâm rnê hom ma Yêhôva, kuăl mbơh sơm ma amoh Păng; Mbơh ăn gĭt ta nklang phung mpôl băl kan Păng.$b$,true),
('bunong-vn','PSA',105,2,null,$b$Mprơ hom ma Păng; mprơ tâm rnê hom ma Păng; Ngơi hom ma lĕ kan khlay Păng$b$,true),
('bunong-vn','PSA',105,3,null,$b$Ăn khân may tâm rnê ma khân may nơm, tâm amoh kloh ueh Păng: Ăn nuih n'hâm phung joi Yêhôva răm maak.$b$,false),
('bunong-vn','PSA',105,4,null,$b$Joi hom Yêhôva jêh ri nau ktang Păng; Joi hom ƀa ƀơ muh măt Păng.$b$,true),
('bunong-vn','PSA',105,5,null,$b$Ăn khân may kah gĭt nau khlay Păng ƀư jêh. Nau khlay Păng, jêh ri nau phat dôih bơh bâr mbung Păng,$b$,true),
('bunong-vn','PSA',105,6,null,$b$Ơ phung kon sau Abraham oh mon păng, Phung kon Y-Yakôb, phung păng săch jêh.$b$,false),
('bunong-vn','PSA',105,7,null,$b$Păng jêng Yêhôva, Brah Ndu he, Nau păng phat dôih gŭ lam neh ntu.$b$,true),
('bunong-vn','PSA',105,8,null,$b$Păng kah gĭt ƀa ƀơ ma nau Păng tâm rnglăp, Nau Păng ton prăp ma rbăn rnôk,$b$,true),
('bunong-vn','PSA',105,9,null,$b$Nau tâm rnglăp Păng ƀư jêh đah Abraham. Jêh ri nau păng sân săk đah Isăk,$b$,false),
('bunong-vn','PSA',105,10,null,$b$Păng nanê̆ jêh nau nây ma Yakôb jêng nau vay. Ma phung Israel jêng nau rnglăp n'ho ro,$b$,false),
('bunong-vn','PSA',105,11,null,$b$lah gâp mra ăn ma may n'gor Kanan. Jêng drăp dơn di ma khân may.$b$,false),
('bunong-vn','PSA',105,12,null,$b$Rnôk nây khân păng jêng knŏng phung djê̆, Nanê̆, djê̆ ngăn, jêh ri jêng bu năch tâm n'gor.$b$,true),
('bunong-vn','PSA',105,13,null,$b$Khân păng hăn tă bơh ndŭl mpôl aơ, ma ndŭl mpôl êng bơh ƀon bri hađăch aơ ma ƀon bri hađăch ri.$b$,true),
('bunong-vn','PSA',105,14,null,$b$Yêhôva mâu ăn bu tŭn jot khân păng ôh; Jêh ri păng nduyh phung hađăch yor khân păng,$b$,true),
('bunong-vn','PSA',105,15,null,$b$lah, lơi pah phung gâp troch dak ngi ôh, Jêh ri lơi ƀư djơh ma phung kôranh mbơh lor gâp.$b$,false),
('bunong-vn','PSA',105,16,null,$b$Păng kuăl an nau sa sât ji ngot tât ta n'gor; Păng sŏk lơi lĕ ndơ sông sa.$b$,true),
('bunong-vn','PSA',105,17,null,$b$Păng njuăl du huê bunuyh hăn lor ma khân păng; Bu tăch jêh Yôsep jêng du huê dĭk;$b$,true),
('bunong-vn','PSA',105,18,null,$b$Bu klêng jâng păng; Bu kât păng ma rse rvăk loih.$b$,false),
('bunong-vn','PSA',105,19,null,$b$Kŏ tât nar nau păng ngơi tât ngăn, Nau Yêhôva ngơi rlong uănh păng.$b$,true),
('bunong-vn','PSA',105,20,null,$b$Hađăch njuăl bu doh păng; Nơm chiă uănh phung ƀon lan sâm rklaih păng.$b$,true),
('bunong-vn','PSA',105,21,null,$b$Păng njêng nơm nây kôranh ngih păng, Jêh ri kôranh chiă uănh lĕ rngôch drăp păng;$b$,true),
('bunong-vn','PSA',105,22,null,$b$Gay păng dơi kât phung kon hađăch păng tĭng nâm ŭch. Jêh ri sâm nti nau blau mĭn ma phung bu ranh păng.$b$,false),
('bunong-vn','PSA',105,23,null,$b$Rnôk nây Israel hăn ta bri Êjipt; Yakôb gŭ tâm bri Cham.$b$,true),
('bunong-vn','PSA',105,24,null,$b$Păng ăn phung ƀon lan păng jêng bĭk ngăn, Jêh ri ăn phung nây, jêng ktang lơn ma phung tŭn jot khân păng.$b$,true),
('bunong-vn','PSA',105,25,null,$b$Jêh ri păng tâm rgâl nuih n'hâm phung Êjipt, ăn tâm rmot ma phung ƀon lan păng, Ŭch ƀư ƀlăch ƀlêr ma phung oh mon Păng.$b$,true),
('bunong-vn','PSA',105,26,null,$b$Păng njuăl Y-Môis oh mon păng, jêh ri Y-Arôn nơm păng săch jêh.$b$,true),
('bunong-vn','PSA',105,27,null,$b$Khân păng tâm mbên Brah Ndu ta nklang phung nây, Jêh ri nau khlay tâm bri Cham.$b$,true),
('bunong-vn','PSA',105,28,null,$b$Păng njuăl nau ngo, jêh ri ngo lĕ; Jêh ri phung nây, mâu hôm tâm rdâng ôh đah bâr păng ngơi.$b$,true),
('bunong-vn','PSA',105,29,null,$b$Brah Ndu tâm rgâl dak khân păng jêng mham, Jêh ri nkhĭt lơi ka khân păng.$b$,true),
('bunong-vn','PSA',105,30,null,$b$Neh khân păng bêng ma kĭt. Kŏ tât tâm jrô hađăch khân păng.$b$,true),
('bunong-vn','PSA',105,31,null,$b$Păng lah, jêh ri phung rhuay tât ro. Geh si tâm lam bri khân păng.$b$,true),
('bunong-vn','PSA',105,32,null,$b$Păng ăn geh pler tŭp tâm bri khân păng ntrok mih. Geh mpiăt ŭnh tâm bri.$b$,true),
('bunong-vn','PSA',105,33,null,$b$Păng dong tơm play kriăk ƀâu khân păng, jêh ri tơm play rvi khân păng. Păng ƀư deh tơm si tâm bri khân păng.$b$,true),
('bunong-vn','PSA',105,34,null,$b$Păng ngơi, jêh ri geh krah, krah mâu dơi kơp,$b$,true),
('bunong-vn','PSA',105,35,null,$b$Krah sa lĕ gơ̆ tâm bri, jêh ri sa play tâm mir khân păng.$b$,false),
('bunong-vn','PSA',105,36,null,$b$Păng dong lĕ rngôch, phung kon bu klâu bôk rah tâm bri khân păng. Lĕ play lor nau ktang khân păng.$b$,true),
('bunong-vn','PSA',105,37,null,$b$Păng ngluh phung ƀon lan păng, djôt prăk jêh ri mah; Jêh ri mâu geh du huê jêng rdja ôh, tâm phung mpôl băl păng.$b$,true),
('bunong-vn','PSA',105,38,null,$b$Phung Êjipt maak ma nau khân păng hăn, Yor lah nau tâm nhhu, ƀư jêh ma khân păng.$b$,true),
('bunong-vn','PSA',105,39,null,$b$Yêhôva lăk ndâr tŭk gay nkŭm khân păng, Jêh ri ŭnh ŭch ƀư ăn khân păng ang dôl tâm măng.$b$,true),
('bunong-vn','PSA',105,40,null,$b$Khân păng dăn, jêh ri Yêhôva ăn phung sĭm gôi văch. Păng ăn sĭm sa hơm kapŭng bơh trôk.$b$,true),
('bunong-vn','PSA',105,41,null,$b$Păng pơk lŭ, jêh ri dak luh hoch; Khân păng hoch rgăn rdrĭch rdah, nâm bu du n'hor dak krong.$b$,true),
('bunong-vn','PSA',105,42,null,$b$Yor lah Păng kah gĭt ma nau Păng ngơi kloh ueh, Jêh ri Abraham, oh mon Păng.$b$,true),
('bunong-vn','PSA',105,43,null,$b$Păng ngluh phung ƀon lan Păng, ma nau răm maak. Phung Păng săch ma nau mprơ.$b$,true),
('bunong-vn','PSA',105,44,null,$b$Păng ăn ma bu n'gor bri phung mpôl băl êng; Jêh ri khân păng sŏk play bơh kan phung ƀon lan;$b$,true),
('bunong-vn','PSA',105,45,null,$b$Gay ma khân păng djôt prăp nau vay Păng, Jêh ri tông nau vay Păng. Halêluya.$b$,false),
('bunong-vn','PSA',106,1,null,$b$Halêluya! Tâm rnê hom ma Yêhôva; Yor lah Păng jêng ueh; Yor lah nau ueh Păng gŭ n'ho ro.$b$,true),
('bunong-vn','PSA',106,2,null,$b$Mbu dơi nkoch bri kan toyh Yêhôva ƀư jêh, Mbu dơi nkoch lĕ nau tâm rnê ma Păng?$b$,true),
('bunong-vn','PSA',106,3,null,$b$Ueh maak yơh phung bu năch tĭng ndô̆ nau di, Jêh ri nơm ƀư ƀa ƀơ sŏng srăng.$b$,true),
('bunong-vn','PSA',106,4,null,$b$Ơ Yêhôva, ăn May kah gĭt ma gâp, ma nau ueh May ăn ma phung ƀon lan May; Văch hom, kơl tâm rklaih gâp ƀă.$b$,true),
('bunong-vn','PSA',106,5,null,$b$Gay ma gâp dơi saơ nau ueh ma phung May săch jêh, Jêh ri gŭ ueh maak đah nau phung mpôl băl May maak. Jêh ri dơi tâm rnê ma gâp nơm, ndrel ma phung drăp May krâm (dơn).$b$,true),
('bunong-vn','PSA',106,6,null,$b$Hên ƀư tih jêh nâm bu phung mbơ̆ hên, Hên ƀư nau kue jêh, hên ƀư nau djơh jêh.$b$,true),
('bunong-vn','PSA',106,7,null,$b$Phung mbơ̆ hên tâm bri Êjipt, mâu gĭt rbăng ma nau khlay May ƀư jêh; Khân păng mâu hôm kah gĭt ma nau ueh May ƀư âk ngăn ngên, Khân păng ƀư nau tâm rdâng ta dak rlai, ta Dak Rlai Chăng.$b$,true),
('bunong-vn','PSA',106,8,null,$b$Ƀiă lah Păng tâm rklaih khân păng yor amoh Păng, Gay ma tâm mpơl nau brah Păng.$b$,true),
('bunong-vn','PSA',106,9,null,$b$Păng nduyh ma Dak Rlai Chăng, jêh ri păng sơh; Pô ri păng njŭn khân păng rgăn ntŭk jru, nâm bu rgăn ndrêch rdah.$b$,true),
('bunong-vn','PSA',106,10,null,$b$Păng tâm rklaih khân păng bơh ti phung tâm rmot ma khân păng, Jêh ri rklaih khân păng jêng kon me bơh ti phung rlăng.$b$,true),
('bunong-vn','PSA',106,11,null,$b$Mpiăt dak nkŭm phung rlăng khân păng, Mâu geh du huê hôm ôh.$b$,true),
('bunong-vn','PSA',106,12,null,$b$Rnôk nây khân păng chroh ma nau Brah Ndu ngơi; Khân păng mprơ tâm rnê ma Păng.$b$,true),
('bunong-vn','PSA',106,13,null,$b$Ƀiă lah phung aơ chuêl kan păng gơnh ngăn; Khân păng mâu kâp ôh ma nau Brah Ndu ntăm.$b$,true),
('bunong-vn','PSA',106,14,null,$b$Ƀiă lah khân păng kơnh ngăn tâm ndrêch rdah; Jêh ri khân păng rlong uănh Brah Ndu tâm ntŭk bri hŏng.$b$,true),
('bunong-vn','PSA',106,15,null,$b$Brah Ndu ăn ma khân păng, moh ndơ khân păng dăn, Ƀiă lah ăn huêng khân păng kƀah ngăn.$b$,true),
('bunong-vn','PSA',106,16,null,$b$Khân păng nach lĕ ma Y-Môis, ta ntŭk khân păng jưh, Nđâp ma Y-Arôn, nơm kloh ueh Yêhôva.$b$,true),
('bunong-vn','PSA',106,17,null,$b$Neh đang jêh ri rvăn Dathan, Jêh ri păng lŏ njĭr ta klơ phung Abiram,$b$,true),
('bunong-vn','PSA',106,18,null,$b$Ŭnh sa lĕ rngôch ndrel ma khân păng; Mpiăt ŭnh sa phung ƀai.$b$,false),
('bunong-vn','PSA',106,19,null,$b$Khân păng ƀư du mlâm rup kon ndrôk tâm Hôreb. Khân păng chon mon mbah ta năp rup khân păng tŏ.$b$,true),
('bunong-vn','PSA',106,20,null,$b$Pô ri khân păng tâm rgâl nau chrêk rmah khân păng. Jêng rup ndrôk blau sa gơ̆ .$b$,true),
('bunong-vn','PSA',106,21,null,$b$Khân păng chuêl Brah Ndu, nơm tâm rklaih khân păng, Nơm ƀư kan toyh tâm bri Êjipt$b$,true),
('bunong-vn','PSA',106,22,null,$b$Kan khlay tâm bri Cham. Nau toyh ngăn ngên ta Dak Rlai Chăng.$b$,false),
('bunong-vn','PSA',106,23,null,$b$Pô ri Brah Ndu lah, Păng mra ƀư rai khân păng, Ƀiă lah Y-Môis, nơm Păng săch jêh, gŭ râng vah vang khân păng đah Brah Ndu, Gay tâm teng nau păng nuih, klach păng mra ƀư rai.$b$,true),
('bunong-vn','PSA',106,24,null,$b$Khân păng tâm rmot ma n'gor ueh uĭn, Khân păng mâu chroh ôh ma nau Brah Ndu ngơi.$b$,true),
('bunong-vn','PSA',106,25,null,$b$Ƀiă lah khân păng ngơi ƀŭk dŭk suyh tâm ngih bok khân păng. Jêh ri mâu iăt ôh bâr Brah Ndu Yêhôva.$b$,true),
('bunong-vn','PSA',106,26,null,$b$Pô ri Brah Ndu sân săk ma khân păng, Mra ƀư rai khân păng tâm bri rdah,$b$,true),
('bunong-vn','PSA',106,27,null,$b$Jêh ri bu ƀư rai phung kon sau khân păng ta nklang phung mpôl băl, Jêh ri mprơh khân păng nchah du tâm âk rplay bri$b$,false),
('bunong-vn','PSA',106,28,null,$b$Khân păng tâm rnglăp khân păng nơm đah Baal pêor, Jêh ri sa ndơ ƀư brah ma phung khĭt.$b$,false),
('bunong-vn','PSA',106,29,null,$b$Pô ri khân păng djrel, nuih n'hâm Yêhôva ji nuih ma kan khân păng; Jêh ri nau ji khĭt tưp tât ma khân păng$b$,true),
('bunong-vn','PSA',106,30,null,$b$Y-Phênêas dâk ŭch ăn nau tâm rmal; Pô ri nau ji tưp nây rlu jêh,$b$,false),
('bunong-vn','PSA',106,31,null,$b$Nau nây ăn nau kơp sŏng tât ma păng. Tâm lĕ rngôch rnôk ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','PSA',106,32,null,$b$Khân păng djrel nuih Yêhôva, ji nuih tâm ban lĕ ta dak Mêriba, Kŏ Môis geh nau tâm rmal yor khân păng;$b$,true),
('bunong-vn','PSA',106,33,null,$b$Yor lah khân păng tâm rdâng đah huêng păng; Kŏ tât păng ngơi ma nau mâu njrăng.$b$,false),
('bunong-vn','PSA',106,34,null,$b$Khân păng mâu ƀư rai ôh phung ƀon lan, tĭng nâm Yêhôva ntăm jêh ma khân păng.$b$,true),
('bunong-vn','PSA',106,35,null,$b$Ƀiă lah khân păng tâm rlŭk, dah phung mpôl băl êng, Jêh ri nti ƀư nâm bu phung nây,$b$,true),
('bunong-vn','PSA',106,36,null,$b$Jêh ri pah kan ma rup brah phung nây, Nau nây jêng dăk sân ma khân păng.$b$,false),
('bunong-vn','PSA',106,37,null,$b$Khân păng ƀư brah ma phung brah mhĭk, ma kon bu klâu nđâp ma kon bu ur khân păng,$b$,true),
('bunong-vn','PSA',106,38,null,$b$Khân păng nkhŭt mham mâu geh tih, Mham kon bu klâu, jêh ri kon bu ur khân păng; Jêng ndơ ƀư brah ma rup brah bri Kanan; Jêh ri bri jêng ƀơ̆ ma mham.$b$,false),
('bunong-vn','PSA',106,39,null,$b$Pô ri khân păng jêng ƀơ̆ jêh, đah kan khân păng, Jêh ri njêng khân păng, jêng văng tĭr ma kan khân păng pah.$b$,true),
('bunong-vn','PSA',106,40,null,$b$Yor nây Yêhôva nuih ma phung ƀon lan păng, Jêh ri tâm rmot ngăn ma drăp păng dơn;$b$,true),
('bunong-vn','PSA',106,41,null,$b$Phung jao phung Israel tâm ti phung mpôl băl êng; Phung rlăng ma khân păng chiă uănh khân păng.$b$,false),
('bunong-vn','PSA',106,42,null,$b$Phung rlăng khân păng tŭn jot khân păng; Jêh ri bu nglăp khân păng tâm dâng ti phung rlăng.$b$,true),
('bunong-vn','PSA',106,43,null,$b$Âk tơ̆ Brah Ndu tâm rklaih jêh khân păng; Ƀiă lah khân păng tâm rdâng. Jêh ri bu ntrŭnh khân păng yor nau kue.$b$,true),
('bunong-vn','PSA',106,44,null,$b$Ƀiă lah Brah Ndu saơ nau rêh ni khân păng, Tơ lah Brah Ndu tăng nau khân păng vơh vơl;$b$,true),
('bunong-vn','PSA',106,45,null,$b$Păng kah gĭt yô̆ ma phung nây, yor nau păng tâm rnglăp. Păng yô̆ an ma phung nây, yor nau ueh păng toyh ngăn.$b$,false),
('bunong-vn','PSA',106,46,null,$b$Jêh ri păng ăn bu geh nau yô̆. Ta năp lĕ rngôch phung njêng khân păng, jêng bu nă.$b$,true),
('bunong-vn','PSA',106,47,null,$b$Sâm rklaih hên, Ơ Yêhôva, Brah Ndu hên, Jêh ri tâm rƀŭn hên bơh nklang phung mpôl băl. Gay ma hên mra tâm rnê ma amoh kloh ueh May. Jêh ri dơi tâm nau tâm rnê ma May.$b$,true),
('bunong-vn','PSA',106,48,null,$b$Mât ton ma Yêhôva, Brah Ndu phung Israel. Bơh rnôk n'ho ro sa ơm tât rnôk n'ho ro nglĕ dŭt! Jêh ri ăn lĕ rngôch phung ƀon lan lah. Amen. Halêluya!$b$,true),
('bunong-vn','PSA',107,1,null,$b$Tâm rnê hom ma Yêhôva, Yor lah Păng jêng ueh; Yor lah nau ueh Păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',107,2,null,$b$Ăn phung Yêhôva tâm chuai jêh lah pô aơ phung Păng tâm rklaih jêh ma ti phung rlăng,$b$,true),
('bunong-vn','PSA',107,3,null,$b$Jêh ri phung Păng tâm rƀŭn jêh bơh lĕ rngôch bri. Pa lơ jêh ri pa dâng, pa yôk jêh ri pa rđŭng.$b$,false),
('bunong-vn','PSA',107,4,null,$b$Khân păng nsong mblêng tâm bri rdah, tâm trong bri hŏng, Mâu saơ ôh du rplay ƀon khân păng dơi gŭ.$b$,true),
('bunong-vn','PSA',107,5,null,$b$Khân păng ji ngot jêh ri ji hir, Huêng khân păng jêng rdja ra ai.$b$,true),
('bunong-vn','PSA',107,6,null,$b$Tâm nau rêh ni, khân păng nter ma Yêhôva, Jêh ri Păng tâm rklaih khân păng bơh nau rngot,$b$,true),
('bunong-vn','PSA',107,7,null,$b$Păng njŭn leo khân păng ta trong sŏng, Gay ma khân păng tât tâm ƀon khân păng dơi gŭ.$b$,false),
('bunong-vn','PSA',107,8,null,$b$Gay ma phung bunuyh mra tâm rnê ma Yêhôva, yor nau ueh Păng, Jêh ri yor kan khlay Păng ƀư jêh ma phung bunuyh!$b$,true),
('bunong-vn','PSA',107,9,null,$b$Yor lah Păng ăn mpay huêng ji hir, Păng ăn hơm huêng ji ngot, ma nau ueh.$b$,true),
('bunong-vn','PSA',107,10,null,$b$Phung gŭ tâm nau ngo jêh ri tâm gui nau khĭt, Kât jêh tâm nau rêh ni jêh ri loih,$b$,true),
('bunong-vn','PSA',107,11,null,$b$Yor lah khân păng tâm rdâng đah nau Brah Ndu ngơi; Jêh ri tâm rmot ma nau nti lah bơh Nơm Klơ Lơn;$b$,false),
('bunong-vn','PSA',107,12,null,$b$Pô ri păng tông nuih n'hâm khân păng ma nau rêh ni; Khân păng cha lôt, jêh ri mâu geh nơm koh dŏng khân păng ôh.$b$,false),
('bunong-vn','PSA',107,13,null,$b$Tâm nau rêh ni, khân păng nter ma Yêhôva, Jêh ri păng tâm rklaih khân păng, bơh nau rngot klâng.$b$,true),
('bunong-vn','PSA',107,14,null,$b$Păng mphâk đŏt jêh khân păng, bơh nau ngo jêh ri gui nau khĭt, păng ƀư tăch jêh rse rvăk khân păng.$b$,true),
('bunong-vn','PSA',107,15,null,$b$Gay ma phung bunuyh mra tâm rnê ma Yêhôva, yor nau ueh Păng, Jêh ri yor kan khlay Păng ƀư jêh ma phung kon bunuyh!$b$,true),
('bunong-vn','PSA',107,16,null,$b$Yor lah păng ƀư chah jêh mpông pêr kông Jêh ri ƀư deh lơi mâng loih nđăng.$b$,true),
('bunong-vn','PSA',107,17,null,$b$Yor lah nau khân păng rlau nau vay, jêh ri yor nau kue khân păng. Phung rluk jêng rêh ni.$b$,true),
('bunong-vn','PSA',107,18,null,$b$Huêng khân păng tâm rmot ngăn, ma lĕ rngôch ndơ sông sa; Jêh ri khân păng hăn dăch, ta mpông pêr nau khĭt.$b$,true),
('bunong-vn','PSA',107,19,null,$b$Dôl nây khân păng nter ma Yêhôva, yor nau rêh ni khân păng. Jêh ri Yêhôva tâm rklaih khân păng, bơh nau rngot klâng.$b$,true),
('bunong-vn','PSA',107,20,null,$b$Păng njuăl nau Păng ngơi, jêh ri ƀư bah bu. Jêh ri Păng tâm rklaih jêh bu bơh trôm ntu jru.$b$,true),
('bunong-vn','PSA',107,21,null,$b$Gay ma phung bunuyh mra tâm rnê ma Yêhôva, Yor nau ueh Păng, Jêh ri yor kan khlay Păng, ƀư jêh ma phung kon bunuyh!$b$,true),
('bunong-vn','PSA',107,22,null,$b$Ăn khân păng nhhơr ndơ ƀư brah nau tâm rnê, Jêh ri nkoch bri kan Păng, ma nau mprơ.$b$,true),
('bunong-vn','PSA',107,23,null,$b$Phung jŭr ta dak rlai ncho kumpăn, Jêh ri pah kan ta klơ dak toyh;$b$,true),
('bunong-vn','PSA',107,24,null,$b$Phung nây saơ kan Yêhôva ƀư, jêh ri nau khlay Păng ƀư tâm nklang dak jru.$b$,false),
('bunong-vn','PSA',107,25,null,$b$Yor lah Păng ntăm, jêh ri păng n'hao sial toyh, Ăn geh mpiăt dak tâm dak rlai.$b$,true),
('bunong-vn','PSA',107,26,null,$b$Khân păng hao leo ta trôk, khân păng lŏ jŭr tâm ntu jru. Huêng khân păng lêk yor nau rŭng răng.$b$,true),
('bunong-vn','PSA',107,27,null,$b$Khân păng hăn nâm bu du huê bunuyh nhŭl ndrănh, mâu di trong ôh, jêh ri mâu hôm gĭt rbăng ôh.$b$,true),
('bunong-vn','PSA',107,28,null,$b$Tâm nau rêh ni, khân păng nter ma Yêhôva, jêh ri Yêhôva tâm rklaih khân păng ma nau rngot klâng.$b$,true),
('bunong-vn','PSA',107,29,null,$b$Păng nkân sial toyh, jêh ri lŏ njŭn nau rngân. Jêh ri sial njach rngơt yơh$b$,true),
('bunong-vn','PSA',107,30,null,$b$Khân păng maak, Yor lah dak njach hŏ đăp mpăn jêh; Jêh ri Brah Ndu njŭn leo khân păng, ta ƀon khân păng ŭch.$b$,false),
('bunong-vn','PSA',107,31,null,$b$Gay ma phung bunuyh mra tâm rnê ma Yêhôva, yor nau ueh Păng. Jêh ri yor nau khlay Păng ƀư jêh, ma phung kon bunuyh!$b$,true),
('bunong-vn','PSA',107,32,null,$b$Ăn khân păng mât ton ma Brah Ndu, lĕ tâm nau tâm rƀŭn phung ƀon lan, jêh ri tâm rnê ma Păng, tâm nau tâm rƀŭn phung bu ranh.$b$,true),
('bunong-vn','PSA',107,33,null,$b$Yêhôva tâm rgâl dak krong jêng ndrêch rdah. Phung tu dak jêng neh sơh.$b$,true),
('bunong-vn','PSA',107,34,null,$b$Jêh ri neh hon ndơ jêng neh chiăt Yor nau ƀai phung gŭ ta nây.$b$,true),
('bunong-vn','PSA',107,35,null,$b$Păng tâm rgâl ndrêch rdah jêng dak nglau, Jêh ri neh sơh jêng tu dak.$b$,true),
('bunong-vn','PSA',107,36,null,$b$Jêh ri Păng ăn phung ji ngot gŭ ta ntŭk nây. Gay ma khân păng dơi rdâk du rplay ƀon gŭ.$b$,true),
('bunong-vn','PSA',107,37,null,$b$Dơi ƀư mir, dơi tăm tơm play kriăk ƀâu, Jêh ri dơi geh play âk.$b$,true),
('bunong-vn','PSA',107,38,null,$b$Brah Ndu ăn nau ueh uĭn, gay ma khân păng jêng âk ngăn ngên; Jêh ri păng mâu huach, phung ndrôk biăp khân păng.$b$,true),
('bunong-vn','PSA',107,39,null,$b$Lŏ du tơ̆ , khân păng n'hŭch jêh ri jŭr. Yor nau tŭn jot, nau rêh ni, jêh ri nau rngot.$b$,true),
('bunong-vn','PSA',107,40,null,$b$Yêhôva nkhŭt nau tâm rmot ta phung kon hađăch. Jêh ri păng nsong mblêng tâm ndrêch rdah, ntŭk mâu geh trong.$b$,true),
('bunong-vn','PSA',107,41,null,$b$Ƀiă lah păng n'gang phung o ach ma nau rêh ni. Jêh ri ăn ndŭl mpôl khân păng, jêng âk nâm bu phung biăp.$b$,true),
('bunong-vn','PSA',107,42,null,$b$Phung sŏng mra saơ nau nây jêh ri maak; Jêh ri lĕ rngôch nau kue mra mêm mbung.$b$,true),
('bunong-vn','PSA',107,43,null,$b$Mbu nâm jêng bunuyh blau mĭn, mra njrăng ma nau nây, Jêh ri mra sek uănh nau ueh Yêhôva.$b$,true),
('bunong-vn','PSA',108,1,null,$b$Nuih n'hâm gâp nâp jêh, Ơ Brah Ndu; Gâp mra mprơ tâm rnê ma nuih n'hâm gâp.$b$,true),
('bunong-vn','PSA',108,2,null,$b$Kah rngăl hom may, Ơ dĭng rlet, jêh ri gong rêng; Gâp nơm mra dâk kah rngăl ơm ngăn,$b$,true),
('bunong-vn','PSA',108,3,null,$b$Gâp mra tâm rnê ma may tâm phung ƀon lan, Ơ Yêhôva; Jêh ri gâp mra mprơ tâm rnê ma May, tâm phung mpôl băl.$b$,false),
('bunong-vn','PSA',108,4,null,$b$Yor lah nau ueh May, hao ta klơ lơn ma trôk; Jêh ri nau na nê̆ ta ndâr ntŭk.$b$,true),
('bunong-vn','PSA',108,5,null,$b$Ơ Brah Ndu, n'hao hom May nơm ta klơ trôk, Ăn nau chrêk rmah May gŭ ta klơ lĕ neh ntu.$b$,true),
('bunong-vn','PSA',108,6,null,$b$Gay tâm rklaih phung May rŏng, Tâm rklaih hên ma ti ma May, jêh ri lŏ plơ̆ lah ma hên,$b$,true),
('bunong-vn','PSA',108,7,null,$b$Brah Ndu ngơi jêh tâm nau ueh păng; Gâp mra răm maak; Gâp mra tâm pă Sichem. Gâp mra veh rlŭng Sukôt.$b$,false),
('bunong-vn','PSA',108,8,null,$b$Galêad jêng ndơ gâp, Manasê jêng ndơ gâp; Êphraim jêng ndơ n'gang bôk gâp; Yuđa jêng mâng hađăch gâp.$b$,true),
('bunong-vn','PSA',108,9,null,$b$Môab jêng ntu lŭng, ta nây gâp ŭm. Ta Êđôm gâp klŭp ntâu jot gâp; Gâp mra nter dơi đah bri Philistin.$b$,true),
('bunong-vn','PSA',108,10,null,$b$Mbu mra njŭn gâp tâm ƀon ktang? Mbu mra njŭn jêh gâp, tât ta bri Êđôm?$b$,true),
('bunong-vn','PSA',108,11,null,$b$Ơ Brah Ndu, mâu di hĕ may yơh dun jêh hên? Jêh ri may yơh mâu hăn ndrel phung tahan hên, Ơ Brah Ndu?$b$,true),
('bunong-vn','PSA',108,12,null,$b$Văch kơl hên ƀư ma phung rlăng; Yor lah nau bunuyh kơl mâu khlay ôh.$b$,true),
('bunong-vn','PSA',108,13,null,$b$Đah Brah Ndu he mra geh nau dơi; Păng yơh mra jot blên phung rlăng he.$b$,true),
('bunong-vn','PSA',109,1,null,$b$Ơ Brah Ndu, Nơm gâp tâm rnê, lơi gŭ rklăk ôh;$b$,true),
('bunong-vn','PSA',109,2,null,$b$Yor lah trôm mbung phung ƀai jêh ri phung ndơm hă jêh ma gâp; khân păng ngơi jêh nau mƀruh ma gâp.$b$,false),
('bunong-vn','PSA',109,3,null,$b$Khân păng nchueng jêh gâp ma nau ngơi tâm rmot. Jêh ri tâm lơh đah gâp mâu geh nau.$b$,true),
('bunong-vn','PSA',109,4,null,$b$Nđâp tơ lah gâp rŏng ma khân păng, khân păng jêng phung rlăng đah gâp; ƀiă lah gâp jao gâp nơm ma nau mbơh sơm.$b$,true),
('bunong-vn','PSA',109,5,null,$b$Khân păng mplơ̆ nau mhĭk ma gâp ntrok nau ueh. Jêh ri nau tâm rmot nsro ma nau gâp rŏng.$b$,true),
('bunong-vn','PSA',109,6,null,$b$Ăn du huê bunuyh ƀai mra chiă uănh păng. Ăn du huê bunuyh phong gŭ mpeh pa ma păng.$b$,true),
('bunong-vn','PSA',109,7,null,$b$Tơ lah bu phat dôih păng, ăn bu kơp păng tih jêh; Jêh ri ăn bu kơp, nau păng mbơh sơm jêng nau tih.$b$,true),
('bunong-vn','PSA',109,8,null,$b$Ăn ƀon păng jêng djê̆, Ăn du huê nơm êng djôt kan păng.$b$,true),
('bunong-vn','PSA',109,9,null,$b$Ăn phung kon păng jêng kon đơi mbơ̆ , Jêh ri ur păng jêng bu ur ndrô khĭt sai.$b$,true),
('bunong-vn','PSA',109,10,null,$b$Ăn phung kon păng jêng phung nsong mblêng, jêh ri nsong dan dăn ndơ bu; Ăn khân păng joi kapŭng, ngai đah ntŭk khân păng gŭ, sat rơch jêh.$b$,true),
('bunong-vn','PSA',109,11,null,$b$Ăn nơm tâm pit, sŏk pit lĕ rngôch ndơ păng geh; Jêh ri ăn phung bu năch, sŏk rdu lơi play tă bơh kan păng.$b$,true),
('bunong-vn','PSA',109,12,null,$b$Lơi ăn du huê ƀư ueh ma păng; Jêh ri mâu lĕ, ăn du huê yô̆ ma phung kon păng kon đơi mbơ̆ .$b$,true),
('bunong-vn','PSA',109,13,null,$b$Ăn bu koh lơi phung kon sau păng; Jêh ri jut lơi amoh păng tâm rnôk kăndơ̆ .$b$,true),
('bunong-vn','PSA',109,14,null,$b$Ăn Yêhôva kah gĭt ma nau kue phung mbơ̆ păng; Jêh ri lơi jut ôh nau tih me păng.$b$,true),
('bunong-vn','PSA',109,15,null,$b$Ăn khân păng gŭ ƀa ƀơ ta năp Yêhôva Gay ma păng koh lơi nau kah gĭt, khân păng bơh neh ntu;$b$,true),
('bunong-vn','PSA',109,16,null,$b$Yor lah khân păng mâu kah gĭt, ƀư nau yô̆ ôh. Ƀiă lah khân păng ƀư mhĭk ma phung rêh ni, ma nơm o ach. Nđâp ma nơm geh nuih n'hâm chah rai, gay ma nkhĭt lơi khân ô băl.$b$,false),
('bunong-vn','PSA',109,17,null,$b$Păng rŏng ma nau rtăp rak, jêh ri nau nây tŭp ta păng. Păng mâu maak ma nau ueh uĭn ôh, Jêh ri nau ueh uĭn du ngai đah păng.$b$,true),
('bunong-vn','PSA',109,18,null,$b$Păng nsoh păng nơm ma nau rtăp rak, jêng bok ao păng. Jêh ri nau rtăp rak nây, lăp jêh tâm păng nâm bu dak. Jêh ri nâm bu ngi, gŭ tâm nting păng.$b$,true),
('bunong-vn','PSA',109,19,null,$b$Ăn nau nây jêng nâm bu bok ao păng prăp nsoh. Jêh ri nâm bu du njăr rse, rêt kŭr bŭt păng rêt ƀa ƀơ.$b$,true),
('bunong-vn','PSA',109,20,null,$b$Tâm ban pô nây, jêng nau nkhôm ma phung rlăng gâp bơh Yêhôva; Jêh ri ma phung ngơi nau ƀai ma huêng gâp.$b$,true),
('bunong-vn','PSA',109,21,null,$b$Ƀiă lah, Ơ Yêhôva, Kôranh Brah, ăn May ƀư nau yô̆ ma gâp, yor ma amoh May. Yor lah nau ueh, May jêng toyh, tâm rklaih hom gâp;$b$,true),
('bunong-vn','PSA',109,22,null,$b$Gâp jêng rêh ni jêh ri o ach, Jêh ri nuih n'hâm gâp sôt jêh tâm gâp.$b$,false),
('bunong-vn','PSA',109,23,null,$b$Gâp du hăn nâm bu gui trôk mhaơ. Bu chiă gâp nâm bu krah.$b$,true),
('bunong-vn','PSA',109,24,null,$b$Kô mâk gâp jêng ra ai ma nau ver sông sa; Săk jăn mâu geh bêng ôh.$b$,true),
('bunong-vn','PSA',109,25,null,$b$Gâp jêng ndơ ma khân păng rak lĕ. Tơ lah khân păng saơ gâp, khân păng rteh bôk.$b$,true),
('bunong-vn','PSA',109,26,null,$b$Koh dŏng gâp, Ơ Yêhôva, Brah Ndu gâp, Rklaih hom gâp, tĭng nâm nau ueh May.$b$,true),
('bunong-vn','PSA',109,27,null,$b$Gay ma khân păng gĭt ti May yơh; May yơh, Ơ Yêhôva, ƀư jêh nau nây.$b$,true),
('bunong-vn','PSA',109,28,null,$b$Lơi ăn khân păng suai rak, ƀiă lah May ăn hom nau ueh uĭn. Tơ lah khân păng dâk, bu mra ƀư bêk khân păng, Ƀiă lah phung oh mon May mra răm maak.$b$,true),
('bunong-vn','PSA',109,29,null,$b$Ăn phung rlăng đah gâp soh nau bêk. Ăn khân păng soh khân păng nơm, ma nau bêk, nâm bu du bu lah ao mbâl.$b$,true),
('bunong-vn','PSA',109,30,null,$b$Bâr mbung gâp mra tâm rnê, hâu ngăn ngên ma Yêhôva; Nanê̆, gâp mra tâm rnê ma păng, ta nklang phung âk.$b$,true),
('bunong-vn','PSA',109,31,null,$b$Yor lah păng mra gŭ râng mpeh pa ma nơm o ach. Gay tâm rklaih păng, bơh phung phat dôih huêng păng.$b$,true),
('bunong-vn','PSA',110,1,null,$b$Yêhôva ngơi ma kôranh gâp, Gŭ hom may pa ma gâp. Kŏ gâp ăn phung rlăng đah may jêng ntŭk may chrong jâng.$b$,true),
('bunong-vn','PSA',110,2,null,$b$Yêhôva mra yơr bơh ƀon Siôn, mâng hađăch nau brah may. Ăn may chiă uănh ta nklang phung rlăng may.$b$,true),
('bunong-vn','PSA',110,3,null,$b$Phung ƀon lan may ŭch nhhơr khân păng nơm ma may. Ndrăp nau kloh ueh tâm nar nau brah may. Bah ơm măng jêh nau jêng mom lŏ tât ma may, nâm bu dak ngom$b$,true),
('bunong-vn','PSA',110,4,null,$b$Yêhôva sân săk jêh, păng mâu mra rgâl ôh; may jêng du huê Kôranh ƀư brah gŭ n'ho ro. Tĭng nâm Mêlkisadek.$b$,false),
('bunong-vn','PSA',110,5,null,$b$Kôranh Brah pa ma may, mra dong phung hađăch ta nar păng ji nuih. Păng mra phat dôih ta nklang phung mpôl băl.$b$,true),
('bunong-vn','PSA',110,6,null,$b$Păng mra ƀư bêng ntŭk nây ma săk jăn bunuyh khĭt; Păng mra dong kôranh tâm âk n'gor bri.$b$,true),
('bunong-vn','PSA',110,7,null,$b$Păng mra nhêt dak n'hor ta trong yor nây păng mra n'gơr bôk.$b$,true),
('bunong-vn','PSA',111,1,null,$b$Halêluya. Gâp mra tâm rnê ma Yêhôva, ma lĕ nuih n'hâm gâp, tâm nau tâm nchră, jêh ri nau tâm rƀŭn phung sŏng.$b$,true),
('bunong-vn','PSA',111,2,null,$b$Kan Yêhôva jêng toyh, Lĕ rngôch phung rŏng ma păng tĭng joi kan nây.$b$,true),
('bunong-vn','PSA',111,3,null,$b$Kan păng jêng nau yơk jêh ri nau rnam; Jêh ri nau sŏng păng gŭ n'ho ro.$b$,true),
('bunong-vn','PSA',111,4,null,$b$Păng ăn bu kah gĭt ma kan khlay păng ƀư jêh; Yêhôva jêng ueh jêh ri blau yô̆.$b$,true),
('bunong-vn','PSA',111,5,null,$b$Păng ăn jêh ndơ sông sa, ma phung klach yơk ma Păng; Păng kah gĭt ƀa ƀơ, ma nau Păng tâm rnglăp.$b$,true),
('bunong-vn','PSA',111,6,null,$b$Păng tâm mpơl jêh, ma phung ƀon lan Păng, nau brah kan Păng. Tơ lah păng jao ma khân păng, drăp ndơ dơn phung mpôl băl.$b$,true),
('bunong-vn','PSA',111,7,null,$b$Kan ti Păng jêng nau ngăn, jêh ri nau di; Lĕ nau Păng chih, jêng nau nanê̆.$b$,true),
('bunong-vn','PSA',111,8,null,$b$Khân păng gŭ nâp n'ho ro; Ƀư jêh ma nau na nê̆, jêh ri nau sŏng.$b$,true),
('bunong-vn','PSA',111,9,null,$b$Păng njuăl jêh nau tâm rnê, ma phung ƀon lan Păng; Păng ntăm an, nau Păng tâm rnglăp gŭ n'ho ro. Amoh Păng kloh ueh, jêh ri khư klach.$b$,true),
('bunong-vn','PSA',111,10,null,$b$Nau klach yơk mbah ma Yêhôva, jêng tơm ma nau blau mĭn; Mbu nâm tĭng ndô̆ nau Păng ntăm, geh nau gĭt rbăng ueh; Nau tâm rnê ma Păng gŭ n'ho ro.$b$,true),
('bunong-vn','PSA',112,1,null,$b$Halêluya, Ueh maak yơh, nơm blau klach yơk ma Yêhôva, Jêh ri rŏng ngăn ma nau păng ntăm.$b$,true),
('bunong-vn','PSA',112,2,null,$b$Phung kon sau păng, mra jêng ktang ta neh ntu; Rnôk phung bunuyh sŏng mra geh nau ueh.$b$,true),
('bunong-vn','PSA',112,3,null,$b$Nau rmeh ler, jêh ri nau ndrŏng gŭ tâm ngih păng; Jêh ri nau sŏng srăng păng, gŭ ƀa ƀơ.$b$,true),
('bunong-vn','PSA',112,4,null,$b$Nau ang sol tâm nau ngo, ma nơm sŏng. Ma nơm ueh, blau yô̆, jêh ri sŏng.$b$,true),
('bunong-vn','PSA',112,5,null,$b$Ueh maak bunuyh ƀư nau yô̆, jêh ri ăn bu chan; Păng mra nkra nau păng gŭ ngao krau sach, tĭng nâm nau sŏng.$b$,true),
('bunong-vn','PSA',112,6,null,$b$Yor lah păng mâu mra n'gơ ôh; Bu mra kah gĭt ƀa ƀơ ma nau sŏng.$b$,true),
('bunong-vn','PSA',112,7,null,$b$Păng mâu mra klach, ma nau mhe nkoch nau mhĭk; Nuih n'hâm păng nâp rjăp, rnơm ma Yêhôva.$b$,true),
('bunong-vn','PSA',112,8,null,$b$Nuih n'hâm păng jêng nâp jêh, păng mâu mra klach ôh. Kŏ saơ nau păng ŭch ăn tât ma phung rlăng păng.$b$,true),
('bunong-vn','PSA',112,9,null,$b$Păng tâm pă jêh; păng ăn jêh ma phung o ach; Nau sŏng srăng păng gŭ n'ho ro; Nke păng mra hao ma nau yơk.$b$,true),
('bunong-vn','PSA',112,10,null,$b$Bunuyh ƀai mra saơ, jêh ri ji nuih n'hâm; Păng mra rket sêk; jêh ri roh; Nau phung ƀai ŭch mra rai lôch.$b$,true),
('bunong-vn','PSA',113,1,null,$b$Halêluya, Ơ phung oh mon Yêhôva, tâm rnê hom ma amoh Yêhôva.$b$,true),
('bunong-vn','PSA',113,2,null,$b$Mât ton hom ma amoh Yêhôva. Ntơm bơh aƀaơ n'ho ro.$b$,true),
('bunong-vn','PSA',113,3,null,$b$Bơh nar luh tât ta nar nhâp. Amoh Yêhôva khư ma nau tâm rnê.$b$,true),
('bunong-vn','PSA',113,4,null,$b$Yêhôva gŭ ta klơ lơn ma lĕ rngôch phung mpôl băl, Nau chrêk rmah păng gŭ ta klơ lơn ma trôk.$b$,true),
('bunong-vn','PSA',113,5,null,$b$Mbu nâm jêng tâm ban Yêhôva. Brah Ndu he? Nơm gŭ tâm ntŭk klơ lơn,$b$,true),
('bunong-vn','PSA',113,6,null,$b$Păng ƀư dêh rhêt êng păng nơm, ŭch uănh ma ndơ tâm trôk nđâp ma neh ntu.$b$,false),
('bunong-vn','PSA',113,7,null,$b$Păng rdâk nhhơk nơm rêh ni bơh neh muy, Jêh ri păng mphâk nơm o ach bơh dak bŏk rhang,$b$,true),
('bunong-vn','PSA',113,8,null,$b$Gay ăn păng gŭ ndrel, phung kon hađăch phung ƀon lan păng.$b$,false),
('bunong-vn','PSA',113,9,null,$b$Păng ăn bu ur lô geh ngih, Jêh ri jêng me maak ta nklang phung kon păng Halêluya.$b$,true),
('bunong-vn','PSA',114,1,null,$b$Tơ lah Israel du luh tă bơh bri Êjipt; Ngih Yakôb bơh du phung mpôl băl, ngơi nau bu năch;$b$,true),
('bunong-vn','PSA',114,2,null,$b$Yuđa jêng ngih kloh ueh Păng Israel jêng phung păng chiă uănh.$b$,false),
('bunong-vn','PSA',114,3,null,$b$Dak rlai saơ, jêh ri du; Dak krong Yurdan lŏ plơ̆ sĭt pa kơi.$b$,true),
('bunong-vn','PSA',114,4,null,$b$Phung yôk nsăt nâm bu phung biăp nkuăng, Phung gôl yôk nâm bu phung kon biăp$b$,true),
('bunong-vn','PSA',114,5,null,$b$Moh tât ma may, Ơ dak rlai, kŏ may du? Ơ dak krong Yurdan, kŏ may plơ̆ sĭt pa kơi?$b$,false),
('bunong-vn','PSA',114,6,null,$b$Ơ khân may phung yôk, kŏ khân may nsăt nâm bu biăp nkuăng? Ơ khân may phung gôl yôk, kŏ tâm ban ma phung kon biăp?$b$,true),
('bunong-vn','PSA',114,7,null,$b$Ơ neh ntu, râm sâr hom ta năp Kôranh Brah. Ta năp Brah Ndu Yakôb,$b$,true),
('bunong-vn','PSA',114,8,null,$b$Nơm tâm rgâl lŭ jêng dak nglau, lŭ dăng jêng tu dak.$b$,false),
('bunong-vn','PSA',115,1,null,$b$Mâu di ma hên, Ơ Yêhôva, mâu di ma hên. Ƀiă lah ma amoh May ăn geh nau chrêk rmah. Yor nau ueh jêh ri nau nanê̆ May.$b$,true),
('bunong-vn','PSA',115,2,null,$b$Mâm ƀư phung mpôl băl mra lah, Ta ntŭk Brah Ndu khân păng?$b$,true),
('bunong-vn','PSA',115,3,null,$b$Ƀiă lah Brah Ndu he gŭ tâm trôk; păng ƀư lĕ nau păng ŭch.$b$,true),
('bunong-vn','PSA',115,4,null,$b$Rup brah khân păng ƀư ma prăk jêh ri mah. Khân păng jêng kan ti bunuyh$b$,true),
('bunong-vn','PSA',115,5,null,$b$Khân păng geh trôm mbung, ƀiă lah mâu ngơi ôh; Khân păng geh măt, ƀiă lah mâu saơ ôh;$b$,false),
('bunong-vn','PSA',115,6,null,$b$Khân păng geh tôr, ƀiă lah mâu tăng ôh; Khân păng geh trôm muh, ƀiă lah mâu blau ƀâu ôh;$b$,false),
('bunong-vn','PSA',115,7,null,$b$Khân păng geh ti, ƀiă lah mâu blau rbot ôh. Khân păng geh jâng, ƀiă lah mâu blau hăn ôh; Mâu lĕ khân păng blau ngơi ma hôt mbung.$b$,false),
('bunong-vn','PSA',115,8,null,$b$Phung ƀư khân păng, mra jêng nâm bu khân păng; Nanê̆ lĕ rngôch phung rnơm ma khân păng;$b$,true),
('bunong-vn','PSA',115,9,null,$b$Ơ Israel, rnơm hom may ma Yêhôva; Yêhôva jêng nơm kơl, jêh ri khêl khân păng.$b$,false),
('bunong-vn','PSA',115,10,null,$b$Ơ ngih Arôn, rnơm hom, may ma Yêhôva Yêhôva jêng nơm kơl jêh ri khêl khân păng$b$,true),
('bunong-vn','PSA',115,11,null,$b$Khân may phung klach yơk ma Yêhôva, nsing hom ma Yêhôva: Yêhôva jêng nơm kơl jêh ri khêl khân păng$b$,false),
('bunong-vn','PSA',115,12,null,$b$Yêhôva kah gĭt rvê ma he; păng mra ăn nau ueh uĭn; Păng mra ăn nau ueh uĭn ma ngih Israel; Păng mra ăn nau ueh uĭn ma ngih Arôn.$b$,false),
('bunong-vn','PSA',115,13,null,$b$Păng mra ăn nau ueh uĭn ma phung klach yơk ma Yêhôva; Phung jê̆ jêh ri phung toyh.$b$,true),
('bunong-vn','PSA',115,14,null,$b$Yêhôva mra ăn bĭk nau ueh ma khân may, Ma khân may jêh ri ma phung kon khân may.$b$,true),
('bunong-vn','PSA',115,15,null,$b$Khân may geh jêh nau ueh uĭn bơh Yêhôva, Nơm rhăk jêh trôk jêh ri neh ntu.$b$,true),
('bunong-vn','PSA',115,16,null,$b$Trôk jêng trôk Yêhôva; ƀiă lah păng ăn neh ntu ma phung kon bunuyh.$b$,true),
('bunong-vn','PSA',115,17,null,$b$Phung khĭt mâu tâm rnê ma Yêhôva ôh. Mâu lĕ nơm jŭr tâm ntŭk rklăk.$b$,true),
('bunong-vn','PSA',115,18,null,$b$Ƀiă lah he mra mât ton ma Yêhôva. Ntơm bơh aƀaơ n'ho ro. Halêluya.$b$,true),
('bunong-vn','PSA',116,1,null,$b$Gâp rŏng ma Yêhôva Yor lah păng iăt bâr gâp jêh ri nau gâp vơh vơl.$b$,true),
('bunong-vn','PSA',116,2,null,$b$Yor lah păng rkêng jêh tôr păng ma gâp, Pô ri gâp mra kuăl mbơh sơm ma păng lĕ nar gâp gŭ rêh.$b$,true),
('bunong-vn','PSA',116,3,null,$b$Brăt nau khĭt vân jêh jŭm gâp, jêh ri nau ji Ƀon Phung Khĭt, kuăn rdâng jêh gâp; nau uh ah jêh ri nau rngot klâng, ƀư jêh ma gâp.$b$,true),
('bunong-vn','PSA',116,4,null,$b$Dôl nây gâp kuăl mbơh sơm jêh ma amoh Yêhôva, Ơ Yêhôva, gâp vơh vơl ma May, tâm rklaih huêng gâp.$b$,true),
('bunong-vn','PSA',116,5,null,$b$Yêhôva jêng ueh jêh ri sŏng; Nanê̆, Brah Ndu he blau yô̆.$b$,true),
('bunong-vn','PSA',116,6,null,$b$Yêhôva chiă uănh phung tông bâr; Gâp jêng rêh ni, jêh ri păng rklaih jêh gâp.$b$,true),
('bunong-vn','PSA',116,7,null,$b$Ơ huêng gâp, lŏ sĭt hom ma nau may rlu; Yor lah Yêhôva ƀư ueh ma may rmeh ler.$b$,true),
('bunong-vn','PSA',116,8,null,$b$Yor lah May rklaih jêh huêng gâp bơh nau khĭt, Măt gâp bơh nau nhĭm, Jâng gâp bơh nau prah.$b$,true),
('bunong-vn','PSA',116,9,null,$b$Gâp mra hăn ta năp Yêhôva ta neh phung rêh.$b$,true),
('bunong-vn','PSA',116,10,null,$b$Gâp chroh, yor nây gâp ngơi, gâp jêng rêh ni ngăn;$b$,true),
('bunong-vn','PSA',116,11,null,$b$Gâp lah tâm nau gâp mâu geh mĭn, Lĕ rngôch phung bunuyh jêng phung mƀruh$b$,false),
('bunong-vn','PSA',116,12,null,$b$Moh gâp mra mplơ̆ ma Yêhôva. Yor lĕ nau ueh Păng ƀư jêh ma gâp?$b$,false),
('bunong-vn','PSA',116,13,null,$b$Gâp mra sŏk kachok nau tâm rklaih Jêh ri kuăl mbơh sơm ma amoh Yêhôva.$b$,true),
('bunong-vn','PSA',116,14,null,$b$Gâp mra nanê̆ nau gâp ton ma Yêhôva, Na nê̆, ta năp lĕ rngôch phung ƀon lan Păng.$b$,true),
('bunong-vn','PSA',116,15,null,$b$Nau phung kloh ueh Păng khĭt. Jêng khlay ngăn ta năp măt Yêhôva.$b$,true),
('bunong-vn','PSA',116,16,null,$b$Ơ Yêhôva, nanê̆ gâp jêng oh mon May May doh jêh brăt kât gâp.$b$,true),
('bunong-vn','PSA',116,17,null,$b$Gâp mra nhhơr ma May ndơ nhhơr tâm rnê ma May. Jêh ri gâp mra kuăl mbơh sơm ma amoh Yêhôva.$b$,true),
('bunong-vn','PSA',116,18,null,$b$Gâp mra ƀư na nê̆ nau gâp ton ma Yêhôva, Na nê̆, ta năp lĕ rngôch phung ƀon lan păng,$b$,true),
('bunong-vn','PSA',116,19,null,$b$Tâm nkual ngih Yêhôva, ta nklang may, Ơ ƀon Yêrusalem, Halêluya.$b$,false),
('bunong-vn','PSA',117,1,null,$b$Tâm rnê hom ma Yêhôva, lĕ rngôch khân may phung mpôl băl; Mât ton ma Păng, lĕ rngôch khân may phung ƀon lan.$b$,true),
('bunong-vn','PSA',117,2,null,$b$Yor lah nau ueh Păng đah he jêng toyh; Jêh ri nau na nê̆ Yêhôva gŭ ƀa ƀơ. Halêluya!$b$,true),
('bunong-vn','PSA',118,1,null,$b$Tâm rnê hom ma Yêhôva; Yor lah Păng jêng ueh; Yor lah nau ueh Păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',118,2,null,$b$Ăn phung Israel lah, nau ueh Păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',118,3,null,$b$Ăn ngih Y-Arôn lah, nau ueh Păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',118,4,null,$b$Ăn phung klach yơk ma Yêhôva lah, nau ueh Păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',118,5,null,$b$Ta nklang nau rêh ni, gâp kuăl mbơh sơm ma Yêhôva; Yêhôva hŏ plơ̆ lah jêh ma gâp, jêh ri dơm gâp tâm ntŭk huy.$b$,true),
('bunong-vn','PSA',118,6,null,$b$Yêhôva gŭ pa gâp; gâp mâu mra klach ôh; Moh bunuyh dơi ƀư ma gâp?$b$,true),
('bunong-vn','PSA',118,7,null,$b$Yêhôva gŭ mpeh ma gâp, ndrel ma phung kơl gâp; Pô ri gâp mra saơ nau gâp ŭch, ăn tât ma phung tâm rmot ma gâp.$b$,true),
('bunong-vn','PSA',118,8,null,$b$Ueh lơn du krap tâm Yêhôva, ma rnơm ma bunuyh.$b$,true),
('bunong-vn','PSA',118,9,null,$b$Ueh lơn du krap tâm Yêhôva, ma rnơm ma phung kon hađăch.$b$,true),
('bunong-vn','PSA',118,10,null,$b$Lĕ rngôch mpôl băl gŭ jŭm gâp; Ma amoh Yêhôva gâp mra koh lơi khân păng.$b$,true),
('bunong-vn','PSA',118,11,null,$b$Khân păng gŭ jŭm gâp, nanê̆ khân păng nchueng gâp Ma amoh Yêhôva gâp mra koh lơi khân păng.$b$,true),
('bunong-vn','PSA',118,12,null,$b$Khân păng gŭ jŭm gâp, nâm bu me sŭt, Khân păng su nâm bu ŭnh sa lok; Ma amoh Yêhôva gâp mra koh lơi khân păng.$b$,true),
('bunong-vn','PSA',118,13,null,$b$May nklơ̆ gay ma cha lôt gâp; ƀiă lah Yêhôva koh dŏng jêh gâp.$b$,true),
('bunong-vn','PSA',118,14,null,$b$Yêhôva jêng nau ktang gâp jêh ri nau mprơ gâp; Păng yơh jêng nau tâm rklaih gâp.$b$,true),
('bunong-vn','PSA',118,15,null,$b$Bâr nau ueh maak, jêh ri nau tâm rklaih, bu tăng tâm ngih bok phung sŏng. Ti ma Yêhôva geh nau dơi.$b$,true),
('bunong-vn','PSA',118,16,null,$b$Ti ma Yêhôva yơr jêh; Ti ma Yêhôva geh nau dơi.$b$,true),
('bunong-vn','PSA',118,17,null,$b$Gâp mâu mra khĭt ôh, ƀiă lah gŭ rêh. Jêh ri gâp mra mbơh kan Yêhôva.$b$,true),
('bunong-vn','PSA',118,18,null,$b$Yêhôva dong nkra gâp âk jêh; Ƀiă lah Păng mâu jao gâp ma nau khĭt ôh.$b$,true),
('bunong-vn','PSA',118,19,null,$b$Pơk an ma gâp mpông pêr nau sŏng srăng; Gâp mra lăp, gâp mra tâm rnê ma Yêhôva.$b$,true),
('bunong-vn','PSA',118,20,null,$b$Aơ, mpông pêr Yêhôva; Phung sŏng mra lăp ta nây.$b$,true),
('bunong-vn','PSA',118,21,null,$b$Gâp mra tâm rnê ma May; Yor lah May lŏ plơ̆ lah jêh ma gâp, Jêh ri May jêng nau tâm rklaih gâp.$b$,true),
('bunong-vn','PSA',118,22,null,$b$Lŭ phung ƀư ngih mƀăr lơi jêh. Hŏ jêng jêh lŭ ntur ta njônh.$b$,true),
('bunong-vn','PSA',118,23,null,$b$Yêhôva yơh ƀư kan aơ; Jêng kan khlay ngăn ta năp măt he.$b$,true),
('bunong-vn','PSA',118,24,null,$b$Aơ, jêng nar Yêhôva ƀư jêh; He mra răm jêh ri maak.$b$,true),
('bunong-vn','PSA',118,25,null,$b$Ơ Yêhôva tâm rklaih gâp ƀă; Ơ Yêhôva, hên vơh vơl ma May, ăn ma hên nau ueh maak.$b$,true),
('bunong-vn','PSA',118,26,null,$b$Mât ton ma nơm văch ma amoh Yêhôva Bơh ngih Yêhôva hên mât ton ma may.$b$,true),
('bunong-vn','PSA',118,27,null,$b$Yêhôva jêng Brah Ndu, jêh ri Păng ƀư ang jêh hên. Kât ndơ nhhơr ma rse brăt, kât păng ta nke nơng ƀư brah.$b$,true),
('bunong-vn','PSA',118,28,null,$b$May jêng Brah Ndu gâp, jêh ri gâp mra tâm rnê ma May, May jêng Brah Ndu gâp, gâp mra yơk ma May.$b$,true),
('bunong-vn','PSA',118,29,null,$b$Tâm rnê hom ma Yêhôva; Yor lah Păng jêng ueh; Yor lah nau ueh Păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',119,1,null,$b$Ueh maak yơh phung sŏng srăng tâm trong khân păng, Phung hăn tĭng ndô̆ trong Yêhôva.$b$,true),
('bunong-vn','PSA',119,2,null,$b$Ueh maak yơh phung djôt prăp nau Păng mbơh, Tĭng joi păng ma lĕ nuih n'hâm$b$,true),
('bunong-vn','PSA',119,3,null,$b$Nanê̆ phung nây mâu ƀư nau kue ôh; Khân păng hăn tâm trong Yêhôva$b$,false),
('bunong-vn','PSA',119,4,null,$b$may ăn jêh nau may chih ma hên, Gay ma hên gơih tĭng ndô̆.$b$,false),
('bunong-vn','PSA',119,5,null,$b$Gâp ŭch ma trong gâp jêng nâp. Dơi tông nau vay May.$b$,true),
('bunong-vn','PSA',119,6,null,$b$Pô ri gâp mâu mra bêk ôh. Tơ lah gâp yơk ma lĕ nau May ntăm.$b$,true),
('bunong-vn','PSA',119,7,null,$b$Gâp mra tâm rnê ma May ma nuih n'hâm sŏng. Dôl nti nau May phat dôih sŏng,$b$,true),
('bunong-vn','PSA',119,8,null,$b$Gâp mra tông nau vay May; Lơi ta cha lơi gâp ôh.$b$,false),
('bunong-vn','PSA',119,9,null,$b$Mâm bu klâu ndăm mra ƀư, dĭng geh ma kloh tâm nau rêh jêng păng?$b$,true),
('bunong-vn','PSA',119,10,null,$b$Gâp tĭng ndô̆ May ma lĕ nuih n'hâm. Lơi ăn gâp der bơh nau May ntăm ôh.$b$,true),
('bunong-vn','PSA',119,11,null,$b$Gâp ndjôt prăp Nau Vay May tâm nuih n'hâm gâp, gay ma gâp mâu hôm ƀư tih đah May.$b$,true),
('bunong-vn','PSA',119,12,null,$b$Mât ton ma May, Ơ Yêhôva; Sâm nti an gâp nau vay May.$b$,true),
('bunong-vn','PSA',119,13,null,$b$Ma bâr mbung gâp mbơh jêh, Lĕ nau bâr mbung May ntăm.$b$,true),
('bunong-vn','PSA',119,14,null,$b$Gâp maak jêh tĭng trong May mbơh, Tâm ban ma gâp geh lĕ nau ndrŏng.$b$,true),
('bunong-vn','PSA',119,15,null,$b$Gâp mra gŭ mĭn ma nau May chih Jêh ri yơk ma trong May.$b$,true),
('bunong-vn','PSA',119,16,null,$b$Gâp mra maak tâm nau vay May; Gâp mâu mra chuêl ôh nau May ngơi.$b$,true),
('bunong-vn','PSA',119,17,null,$b$Ƀư nau ueh rmeh ler ma oh mon May, gay ma gâp dơi gŭ rêh; Pô ri gâp mra tĭng ndô̆ nau May ngơi.$b$,true),
('bunong-vn','PSA',119,18,null,$b$Dăn may pơk an măt gâp, gay ma gâp dơi saơ ntil khlay tâm Nau Vay May.$b$,true),
('bunong-vn','PSA',119,19,null,$b$Gâp jêng bu năch ta neh ntu. Lơi pôn nau May ntăm ma gâp ôh.$b$,true),
('bunong-vn','PSA',119,20,null,$b$Huêng gâp nchah jêh ma nau rŏng. Păng geh ƀa ƀơ nau May ntăm.$b$,true),
('bunong-vn','PSA',119,21,null,$b$May nduyh jêh phung sưr, phung bu rtăp rak jêh. Phung teng đah nau May ntăm.$b$,true),
('bunong-vn','PSA',119,22,null,$b$Sŏk lơi nau bêk tă bơh gâp, jêh ri nau tâm rmot. Yor lah gâp djôt prăp jêh nau May mbơh.$b$,true),
('bunong-vn','PSA',119,23,null,$b$Phung Kon hađăch gŭ ngơi tâm rdâng đah gâp; Ƀiă lah oh mon May gŭ mĭn jêh ma nau vay May.$b$,true),
('bunong-vn','PSA',119,24,null,$b$Nau May mbơh jêng nau gâp rŏng Khân păng jêng phung nchŏng an trong ma gâp.$b$,true),
('bunong-vn','PSA',119,25,null,$b$Huêng gâp iang đah ndruyh neh; Ăn rêh gâp tĭng nau May ngơi.$b$,true),
('bunong-vn','PSA',119,26,null,$b$Gâp mbơh trong gâp, jêh ri may lŏ plơ̆ lah jêh ma gâp. Sâm nti an nau vay May ma gâp.$b$,true),
('bunong-vn','PSA',119,27,null,$b$Ăn gâp gĭt rbăng trong nau May chih; Pô ri gâp mra gŭ mĭn ma nau khlay May.$b$,true),
('bunong-vn','PSA',119,28,null,$b$Huêng gâp nhĭm yor nau rngot jâk; Ƀư ăn ktang gâp tĭng nâm nau May ngơi;$b$,true),
('bunong-vn','PSA',119,29,null,$b$Sŏk lơi trong nau mƀruh tâm gâp; Jêh ri ăn ma gâp nau yô̆, dơi tĭng ndô̆ nau vay May.$b$,false),
('bunong-vn','PSA',119,30,null,$b$Gâp săch jêh trong nau răp jăp; May dơm nau gâp ntăm ta năp gâp.$b$,true),
('bunong-vn','PSA',119,31,null,$b$Gâp iang ma nau May mbơh; Ơ Yêhôva lơi ƀư bêk gâp ôh.$b$,true),
('bunong-vn','PSA',119,32,null,$b$Gâp mra nchuăt tâm trong nau May ntăm; Yor lah gâp rŏng nau nây.$b$,true),
('bunong-vn','PSA',119,33,null,$b$Sâm nti gâp, Ơ Yêhôva, trong nau vay May; Jêh ri gâp mra djôt prăp păng tât lôch.$b$,true),
('bunong-vn','PSA',119,34,null,$b$Ăn gâp nau gĭt rbăng, jêh ri gâp mra djôt prăp nau vay May; Na nê̆, gâp mra tông păng ma lĕ nuih n'hâm.$b$,true),
('bunong-vn','PSA',119,35,null,$b$Ăn gâp tĭng trong nau May ntăm; Yor lah gâp rŏng nau nây,$b$,true),
('bunong-vn','PSA',119,36,null,$b$Rkêng nuih n'hâm gâp leo pa nau May mbơh.$b$,false),
('bunong-vn','PSA',119,37,null,$b$Lơi ăn măt gâp uănh nau dơm dam. Ăn gâp gŭ rêh tâm trong May$b$,true),
('bunong-vn','PSA',119,38,null,$b$Ăn may ƀư na nê̆ nau may ngơi đah phung oh mon May; Nơm rŏng ma nau klach yơk mbah ma May.$b$,false),
('bunong-vn','PSA',119,39,null,$b$Sŏk lơi tă bơh gâp nau bêk gâp klach, Yor lah nau May ntăm jêng ueh.$b$,true),
('bunong-vn','PSA',119,40,null,$b$Aơ, gâp rŏng ngăn ma nau May chih; Ăn gâp gŭ rêh tâm nau sŏng May.$b$,true),
('bunong-vn','PSA',119,41,null,$b$Ơ Yêhôva, ăn nau ueh May tât ta gâp, Jêng nau may tâm rklaih tĭng nâm nau May ngơi.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PSA',119,42,null,$b$Pô ri gâp mra dơi lŏ plơ̆ lah ma nơm suai rak gâp. Yor lah gâp rnơm ma nau May ngơi.$b$,true),
('bunong-vn','PSA',119,43,null,$b$Lơi ta sŏk lĕ nau ngơi ngăn bơh trôm mbung gâp ôh; Yor lah gâp kâp gân jêh ma nau May ntăm.$b$,true),
('bunong-vn','PSA',119,44,null,$b$Pô ri gâp mra tĭng ndô̆ mro nau vay May ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',119,45,null,$b$Gâp mra hăn ma nau mpăn; Yor lah gâp tĭng joi nau May chih.$b$,true),
('bunong-vn','PSA',119,46,null,$b$Gâp mra ngơi lĕ nau May mbơh ta năp phung hađăch, Jêh ri bu mâu mra ƀư bêk gâp ôh.$b$,true),
('bunong-vn','PSA',119,47,null,$b$Gâp mra maak tâm nau May ntăm. Jêng nau gâp rŏng jêh.$b$,true),
('bunong-vn','PSA',119,48,null,$b$Gâp mra yơr ti gâp bơh nau May ntăm, nau gâp rŏng jêh; Jêh ri gâp mra gŭ mĭn ma nau vay ay$b$,true),
('bunong-vn','PSA',119,49,null,$b$Kah gĭt hom nau May ngơi ma oh mon May, Yor lah May ăn gâp kâp gân jêh.$b$,false),
('bunong-vn','PSA',119,50,null,$b$Nau aơ jêng nau bonh gâp tâm nau rêh ni; Yor lah nau May ngơi jêng ăn nau rêh ma gâp,$b$,true),
('bunong-vn','PSA',119,51,null,$b$Phung sưr mưch ma gâp hâu ngăn, Ƀiă lah ăt gâp mâu teng ôh bơh nau vay May.$b$,false),
('bunong-vn','PSA',119,52,null,$b$Gâp kah gĭt jêh ma nau May ntăm bơh kăl e ri, Ơ Yêhôva, Jêh ri gâp bonh gâp nơm.$b$,true),
('bunong-vn','PSA',119,53,null,$b$Gâp ji nuih hâu ngăn, Yor phung ƀai hŏ lơi jêh nau vay May.$b$,true),
('bunong-vn','PSA',119,54,null,$b$Nau vay May jêng nau vay gâp mprơ, Tâm ngih ntŭk gâp jêng bu năch.$b$,true),
('bunong-vn','PSA',119,55,null,$b$Dôl măng gâp kah gĭt ma amoh May, Ơ Yêhôva, jêh ri gâp tĭng ndô̆ nau vay May.$b$,true),
('bunong-vn','PSA',119,56,null,$b$Gâp geh nau aơ, Yor lah gâp djôt prăp nau May chih.$b$,true),
('bunong-vn','PSA',119,57,null,$b$Yêhôva jêng kô̆ ma gâp. Gâp lah jêh, gâp mra tông nau May ntăm.$b$,true),
('bunong-vn','PSA',119,58,null,$b$Gâp vơh vơl nau ueh May ma lĕ nuih n'hâm, Yô̆ nđach an ma gâp tĭng nâm nau May ngơi.$b$,true),
('bunong-vn','PSA',119,59,null,$b$Gâp gŭ mĭn ma trong gâp. Jêh ri gâp dai jâng gâp leo pa nau May mbơh.$b$,true),
('bunong-vn','PSA',119,60,null,$b$Gâp ndal, gâp mâu kâp ôh, Gay tĭng ndô̆ nau May ntăm.$b$,true),
('bunong-vn','PSA',119,61,null,$b$Brăt phung ƀai put chăp gâp. Ƀiă lah gâp mâu chuêl nau vay May ôh.$b$,true),
('bunong-vn','PSA',119,62,null,$b$Ta klong măng gâp mra dâk gay tâm rnê ma May Yor nau May ntăm jêng sŏng.$b$,true),
('bunong-vn','PSA',119,63,null,$b$Gâp jêng mĭt jiăng ma lĕ rngôch phung klach yơk mbah ma May. Jêh ri phung tĭng ndô̆ nau May chih.$b$,true),
('bunong-vn','PSA',119,64,null,$b$Neh ntu, Ơ Yêhôva, bêng ma nau ueh May Sâm nti nau vay ma gâp.$b$,true),
('bunong-vn','PSA',119,65,null,$b$May ƀư nau ueh ma phung oh mon May, Ơ Yêhôva, tĭng nâm nau may ngơi.$b$,true),
('bunong-vn','PSA',119,66,null,$b$Sâm nti gâp nau blau ƀư ueh jêh ri nau blau mĭn; Yor lah gâp chroh jêh ma nau May ntăm.$b$,true),
('bunong-vn','PSA',119,67,null,$b$Lor gâp geh nau rêh ni, gâp chuêl trong jêh; Ƀiă lah aƀaơ gâp tĭng ndô̆ nau May ngơi.$b$,true),
('bunong-vn','PSA',119,68,null,$b$May jêng ueh, jêh ri may ƀư nau ueh; Sâm nti gâp nau vay May.$b$,true),
('bunong-vn','PSA',119,69,null,$b$Phung sưr mĭn nau mƀruh đah gâp; Gâp mra tông ma lĕ nuih n'hâm nau May chih.$b$,true),
('bunong-vn','PSA',119,70,null,$b$Nuih n'hâm khân păng mbâl nâm bu ngi. Ƀiă lah gâp maak tâm nau vay May.$b$,true),
('bunong-vn','PSA',119,71,null,$b$Nau gâp dơn jêh nau rêh ni, jêng nau ueh ma gâp; Gay ma gâp dơi nti nau vay May.$b$,true),
('bunong-vn','PSA',119,72,null,$b$Nau vay tă bah bâr mbung May jêng ueh lơn ma gâp. Maak rbăn ndơ mah jêh ri prăk$b$,true),
('bunong-vn','PSA',119,73,null,$b$Ti may rhăk jêh gâp, khân păng mon jêh gâp; Ăn ma gâp nau gĭt rbăng, gay ma gâp dơi nti nau May ntăm.$b$,false),
('bunong-vn','PSA',119,74,null,$b$Phung klach yơk mbah ma May mra saơ gâp jêh ri răm maak. Yor lah gâp kâp gân jêh tâm nau May ngơi.$b$,true),
('bunong-vn','PSA',119,75,null,$b$Gâp gĭt, Ơ Yêhôva, nau May phat dôih jêng sŏng, jêh ri ma nau na nê̆, May ăn jêh gâp rêh ni.$b$,true),
('bunong-vn','PSA',119,76,null,$b$Gâp vơh vơl ma May, ăn nau ueh may jêng nau bonh leng gâp, Nâm bu May ngơi jêh đah oh mon May.$b$,true),
('bunong-vn','PSA',119,77,null,$b$Ăn nau May yô̆ văch ma gâp, gay ma gâp dơi rêh; Yor lah gâp rŏng ma nau vay May.$b$,true),
('bunong-vn','PSA',119,78,null,$b$Ăn bêk phung sưr; Yor lah khân păng tŭn jot gâp mâu geh nau. Ƀiă lah gâp mra gŭ mĭn ma nau May chih.$b$,true),
('bunong-vn','PSA',119,79,null,$b$Ăn phung klach yơk mbah ma May sĭt ta gâp; Jêh ri khân păng mra gĭt nau May mbơh.$b$,true),
('bunong-vn','PSA',119,80,null,$b$Ăn rah vah nuih n'hâm gâp tâm nau vay May; Gay ma gâp mâu bêk ôh.$b$,true),
('bunong-vn','PSA',119,81,null,$b$Huêng gâp rdja ngăn ma nau May tâm rklaih; Ƀiă lah gâp kâp gân ma nau May ngơi.$b$,true),
('bunong-vn','PSA',119,82,null,$b$Măt gâp jêng huănh ma nau May ngơi, Dôl gâp lah, Ndah jŏ May mra bonh gâp?$b$,true),
('bunong-vn','PSA',119,83,null,$b$Yor lah gâp jêng nâm bu dŭng ntâu ta nhhuay ŭnh; Ƀiă lah ăt gâp mâu chuêl ôh nau vay May.$b$,true),
('bunong-vn','PSA',119,84,null,$b$Dŭm nar oh mon May mra gŭ rêh? Ndah jŏ May mra phat dôih phung ƀư mhĭk ma gâp?$b$,true),
('bunong-vn','PSA',119,85,null,$b$Phung sưr kuyh ntu jru ta năp gâp. Khân păng mâu ƀư tĭng nau vay May ôh$b$,true),
('bunong-vn','PSA',119,86,null,$b$Lĕ rngôch nau May ntăm jêng răp jăp; Khân păng ƀư mhĭk ma gâp, mâu geh nau văch koh dŏng gâp.$b$,false),
('bunong-vn','PSA',119,87,null,$b$Khân păng bơi ma ƀư rai gâp ta neh ntu; Ƀiă lah gâp mâu lơi nau May chih ôh.$b$,true),
('bunong-vn','PSA',119,88,null,$b$Ăn gâp rêh tĭng nâm nau ueh May; Pô ri gâp mra tĭng ndô̆ nau May mbơh, tă bơh trôm mbung May.$b$,true),
('bunong-vn','PSA',119,89,null,$b$Ơ Yêhôva, nau may ngơi gŭ nâp ƀa ƀơ tâm trôk.$b$,true),
('bunong-vn','PSA',119,90,null,$b$Nau rjăp May gŭ tâm lĕ rnôk. May njêng jêh neh ntu, jêh ri păng gŭ nâp.$b$,true),
('bunong-vn','PSA',119,91,null,$b$Tĭng nâm nau May ntăm, khân păng ăt gŭ tât ta nar aơ, Yor lah lĕ rngôch ndơ pah kan May da dê.$b$,true),
('bunong-vn','PSA',119,92,null,$b$Tơ lah nau vay May mâu jêng nau ma gâp, gâp rai lôch jêh tâm nau rêh ni gâp.$b$,true),
('bunong-vn','PSA',119,93,null,$b$Gâp mâu mra chuêl nau May chih ôh; Yor lah ma păng yơh May ăn gâp gŭ rêh.$b$,true),
('bunong-vn','PSA',119,94,null,$b$Gâp jêng ndơ May, rklaih hom gâp; Yor lah gâp joi nau May chih.$b$,true),
('bunong-vn','PSA',119,95,null,$b$Phung ƀai gŭ kâp gâp, gay ƀư rai; Ƀiă lah gâp mra gŭ mĭn ma nau May mbơh.$b$,true),
