('bunong-vn','PSA',124,6,null,$b$Mât ton ma Yêhôva, Nơm mâu jao ôh he jêng ndơ sêk khân păng sa.$b$,false),
('bunong-vn','PSA',124,7,null,$b$Huêng he klaih jêh nâm bu sĭm bơh nhuăl văk, Nhuăl khêk, jêh ri he klaih yơh.$b$,true),
('bunong-vn','PSA',124,8,null,$b$Nau kơl he gŭ tâm amoh Yêhôva, Nơm rhăk trôk jêh ri neh ntu. Yêhôva Gŭ Jŭm Phung Ƀon Lan Păng. Nau phung hăn nsong ta ƀon kloh ueh mprơ$b$,true),
('bunong-vn','PSA',125,1,null,$b$Phung rnơm ma Yêhôva jêng nâm bu yôk Siôn, Păng mâu dơi n'gơ ôh, păng gŭ n'ho ro.$b$,true),
('bunong-vn','PSA',125,2,null,$b$Nâm bu phung yôk gŭ jŭm ƀon Yêrusalem, Pô nây lĕ Yêhôva gŭ jŭm phung ƀon lan Păng. Ntơm bơh aƀaơ n'ho ro.$b$,true),
('bunong-vn','PSA',125,3,null,$b$Yor lah mâng hađăch nau ƀai mâu mra gŭ chiă ôh drăp krâm phung sŏng, gay ma phung sŏng mâu yơr ti khân păng ma nau kue.$b$,true),
('bunong-vn','PSA',125,4,null,$b$Ơ Yêhôva, ƀư ueh hom ma phung ueh, Jêh ri ma phung geh nuih n'hâm sŏng.$b$,true),
('bunong-vn','PSA',125,5,null,$b$Ƀiă lah ma phung teng du ŭch tĭng ndô̆ nau kue. Ăn nau đăp mpăn gŭ ndrel ma phung Israel.$b$,true),
('bunong-vn','PSA',126,1,null,$b$Tơ lah Yêhôva njŭn phung sĭt ta ƀon Siôn. He jêng nâm bu phung gŭ mbơi.$b$,true),
('bunong-vn','PSA',126,2,null,$b$Dôl nây trôm mbung he bêng ma nau gơm, Jêh ri mpiăt he ma nau mprơ; Dôl nây bu lah ta nklang phung mpôl băl, Yêhôva ƀư nau khlay jêh ma khân păng;$b$,true),
('bunong-vn','PSA',126,3,null,$b$Brah Yêhôva hŏ ƀư nau kan khlay jêh ma phung he, Yor nây phung he maak.$b$,false),
('bunong-vn','PSA',126,4,null,$b$Ơ Yêhôva, njŭn phung bu nă hên sĭt, Nâm bu dak n'hor tâm n'gor bah rđŭng.$b$,true),
('bunong-vn','PSA',126,5,null,$b$Phung tuch ma dak măt mra kăch tâm nau gơm maak.$b$,true),
('bunong-vn','PSA',126,6,null,$b$Mbu nâm hăn srih grăp ma nau nhĭm, mra plơ̆ sĭt mbăk nchăp ba ma nau răm maak.$b$,true),
('bunong-vn','PSA',127,1,null,$b$Tơ lah Yêhôva mâu rdâk ngih. Phung rdâk pah kan dơm dam. Tơ lah Yêhôva mâu chiă ƀon, nơm gak rngeh dăng măt dơm dam yơh.$b$,true),
('bunong-vn','PSA',127,2,null,$b$Mâu khlay ôh khân may kah rngăl ơm, jêh ri la khân may bêch, Sa kapŭng nau ŏk ra ah Yor lah Brah Ndu ăn ma phung păng rŏng dơi bêch.$b$,true),
('bunong-vn','PSA',127,3,null,$b$Aơ, phung kon jêng drăp krâm bơh Yêhôva; Jêh ri play bơh ndŭl proch jêng nau nkhôm.$b$,true),
('bunong-vn','PSA',127,4,null,$b$Tâm ban ma hăr tâm ti du huê nơm ktang. Tâm ban pô nây lĕ kon bu geh dôl hôm mom.$b$,true),
('bunong-vn','PSA',127,5,null,$b$Ueh maak yơh bunuyh geh jêh hăr bêng dĭng; Khân păng mâu mra bêk ôh, Tơ lah khân păng mra ngơi đah phung rlăng ta mpông pêr.$b$,true),
('bunong-vn','PSA',128,1,null,$b$Ueh maak yơh ma ăp nơm klach yơk ma Yêhôva, jêh ri hăn tâm trong păng$b$,true),
('bunong-vn','PSA',128,2,null,$b$Yor lah may mra sa play bơh kan ti may may mra maak, jêh ri may mra geh nau ueh.$b$,false),
('bunong-vn','PSA',128,3,null,$b$Ur may mra jêng nâm bu du tơm play kriăk ƀâu play âk; Tâm trôm ngih may; jêh ri phung kon nâm bu tơm play Ôlivơ. Jŭm sưng may sông.$b$,true),
('bunong-vn','PSA',128,4,null,$b$Tâm ban pô nây nơm klach yơk ma Yêhôva mra geh nau ueh uĭn.$b$,true),
('bunong-vn','PSA',128,5,null,$b$Dăn Yêhôva ăn nau ueh uĭn ma may bơh ƀon Siôn; Jêh ri ăn may saơ nau ueh ma ƀon Yêrusalem lĕ nar may gŭ rêh.$b$,true),
('bunong-vn','PSA',128,6,null,$b$Na nê̆, ăn may saơ phung sau se may, Ăn nau đăp mpăn gŭ ta nklang phung Israel.$b$,true),
('bunong-vn','PSA',129,1,null,$b$Âk tơ̆ jêh khân păng tŭn jot gâp bơh hôm jêng mom. Ăn phung Israel roh nau nây.$b$,true),
('bunong-vn','PSA',129,2,null,$b$Âk tơ̆ jêh khân păng tŭn jot gâp, bơh hôm jêng mom; Ƀiă lah khân păng mâu mâp dơi đah gâp ôh.$b$,true),
('bunong-vn','PSA',129,3,null,$b$Phung kai mir, kai jêh ndŭr kơi gâp, khân păng kai chruih jêh trong jong,$b$,true),
('bunong-vn','PSA',129,4,null,$b$Yêhôva jêng sŏng; Păng koh jêh rse rvăk phung ƀai nkra.$b$,false),
('bunong-vn','PSA',129,5,null,$b$Ăn bu ƀư bêk jêh ri rŭch lơi, Lĕ rngôch phung tâm rmot ma ƀon Siôn.$b$,true),
('bunong-vn','PSA',129,6,null,$b$Ăn khân păng jêng nâm bu gơ̆ hon ta chor bôk pho; Păng kro jêh lor ma bu rôk păng;$b$,true),
('bunong-vn','PSA',129,7,null,$b$Ma amoh nơm rek ba mâu tât bêng ôh ti păng. Nơm kât nchăp ba mâu lĕ ndjôt ra-u.$b$,false),
('bunong-vn','PSA',129,8,null,$b$Phung rgăn ta nây mâu lah lĕ; Ăn nau ueh uĭn Yêhôva gŭ ta khân may; Hên mât ton ma khân may ma amoh Yêhôva.$b$,true),
('bunong-vn','PSA',130,1,null,$b$Bơh ntŭk jru gâp nter ma may, Ơ Yêhôva.$b$,true),
('bunong-vn','PSA',130,2,null,$b$Ơ Kôranh Brah iăt hom bâr gâp; Ăn tôr may gŭ rkêng ma bâr gâp vơh vơl.$b$,true),
('bunong-vn','PSA',130,3,null,$b$Ơ Yêhôva, tơ lah may kah gĭt prăp nau kue, Ơ Kôranh Brah, mbu nâm mra dơi gŭ râng?$b$,true),
('bunong-vn','PSA',130,4,null,$b$Ƀiă lah geh nau yô̆ an ndrel ma May, Gay ma bu klach yơk mbah ma may$b$,true),
('bunong-vn','PSA',130,5,null,$b$Gâp kâp gân Yêhôva, huêng gâp kâp gân, Jêh ri gâp kâp gân tâm nau păng ngơi.$b$,false),
('bunong-vn','PSA',130,6,null,$b$Huêng gâp kâp gân ma Kôranh Brah. Rlau lơn ma phung gak kâp ang ôi; Na nê̆ rlau lơn ma phung gak kâp ang ôi.$b$,true),
('bunong-vn','PSA',130,7,null,$b$Ơ phung Israel, kâp gân hom ma Yêhôva; Yor lah tâm Yêhôva geh nau ueh. Jêh ri nau tâm chuai gŭ rmeh ler ndrel ma păng.$b$,true),
('bunong-vn','PSA',130,8,null,$b$Păng yơh mra tâm chuai phung Israel bơh lĕ nau kue.$b$,true),
('bunong-vn','PSA',131,1,null,$b$Ơ Yêhôva, gâp mâu geh nuih n'hâm sưr ôh, măt gâp mâu lĕ uănh ma nau nkrơ̆ ueh, mâu lĕ mĭn ma ndơ toyh ir, Mâu lah kan rlau keh ir đah gâp.$b$,true),
('bunong-vn','PSA',131,2,null,$b$Nanê̆, huêng gâp gŭ rklăk jêh ri đăp mpăn; nâm bu du huê kon se mhe lơi pu toh.$b$,true),
('bunong-vn','PSA',131,3,null,$b$Ơ phung Israel, ăn may kâp gân tâm Yêhôva. Ntơm bơh aƀaơ n'ho ro.$b$,true),
('bunong-vn','PSA',132,1,null,$b$Ơ Yêhôva ăn may kah gĭt ma Đavit, Ma lĕ nau rêh ni păng;$b$,true),
('bunong-vn','PSA',132,2,null,$b$Nau păng sân săk ma Yêhôva, Jêh ri nau păng ton ma Nơm Brah Yakôb.$b$,false),
('bunong-vn','PSA',132,3,null,$b$Na nê̆ gâp mâu mra lăp ôh tâm ngih bok ntŭk gâp gŭ, Mâu lĕ gâp mra hao ta sưng bêch;$b$,true),
('bunong-vn','PSA',132,4,null,$b$Gâp mâu mra ăn măt gâp bêch ôh, Mâu lĕ geh nau rlu ndô măt gâp;$b$,false),
('bunong-vn','PSA',132,5,null,$b$Kŏ gâp geh ntŭk gŭ ma Yêhôva, Du rplay ngih bok ma Nơm Brah Yakôb,$b$,false),
('bunong-vn','PSA',132,6,null,$b$Aơ, he tăng bu lah ma hip nau tâm rnglăp, gŭ ta n'gor Êphratha; He saơ jêh păng tâm mir Ja-ar.$b$,false),
('bunong-vn','PSA',132,7,null,$b$He mra lăp tâm ngih bok păng; He mra mbah yơk ta năp ntŭk păng chrong jâng.$b$,true),
('bunong-vn','PSA',132,8,null,$b$Dâk hom may, Ơ Yêhôva, văch ta ntŭk may rlu; may, jêh ri hip nau ktang may.$b$,true),
('bunong-vn','PSA',132,9,null,$b$Ăn phung Kôranh ƀư brah may nsoh nau sŏng srăng; Jêh ri ăn phung kloh ueh may nter hâk.$b$,true),
('bunong-vn','PSA',132,10,null,$b$Yor Đavit, oh mon may, Lơi dun ôh ma nơm may troch dak ngi$b$,true),
('bunong-vn','PSA',132,11,null,$b$Yêhôva sân săk jêh ma nau nanê̆ Đavit Păng mâu mra rgâl ôh, Gâp mra n'hao ta klơ sưng hađăch may du huê bơh ndŭl proch may.$b$,false),
('bunong-vn','PSA',132,12,null,$b$Tơ lah phung kon may djôt prăp nau Gâp tâm rnglăp, jêh ri nau mbơh gâp mra sâm nti khân păng, Pô ri phung kon khân păng mra gŭ ta sưng hađăch may ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',132,13,null,$b$Yor lah Yêhôva săch jêh ƀon Siôn; Păng ŭch njêng ntŭk păng gŭ.$b$,true),
('bunong-vn','PSA',132,14,null,$b$Ta aơ jêng ntŭk gâp ƀa ƀơ n'ho ro; Gâp mra gŭ tâm păng; Yor lah gâp ŭch jêh ma păng.$b$,true),
('bunong-vn','PSA',132,15,null,$b$Gâp mra ăn nau ueh uĭn ma ndơ păng sông sa; Gâp mra n'hơm ma kapŭng phung o ach păng.$b$,true),
('bunong-vn','PSA',132,16,null,$b$Gâp mra sâm nsoh ma nau tâm rklaih, phung Kôranh ƀư brah păng. Jêh ri phung kloh ueh păng mra nter hâk.$b$,true),
('bunong-vn','PSA',132,17,null,$b$Ta nây gâp mra ăn nke Đavit luh nkur ƀa ƀơ n'ho ro. Gâp nkra jêh du mlâm ŭnh kađen ma nơm gâp troch jêh dak ngi.$b$,true),
('bunong-vn','PSA',132,18,null,$b$Gâp mra sâm nsoh phung rlăng păng ma nau bêk; Ƀiă lah đon hađăch păng mra hao ta nau chrêk rmah lơn ta klơ păng nơm.$b$,true),
('bunong-vn','PSA',133,1,null,$b$Nĕ aơ, ueh ngăn, maak ngăn, Ma phung oh nâu gŭ ndrel du nuih n'hâm!$b$,true),
('bunong-vn','PSA',133,2,null,$b$Păng jêng nâm bu dak ngi khlay lĭng ta klơ bôk. Hoch ta têp kang; Ta têp kang Arôn. Hoch ta trô ko ao păng,$b$,true),
('bunong-vn','PSA',133,3,null,$b$Păng jêng nâm bu dak ngom ta yôk Hêrmon. Jŭr ta phung yôk Siôn; Yor lah ta nây Yêhôva ntăm nau ueh uĭn, Jêng nau rêh ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','PSA',134,1,null,$b$Aơ, mât ton hom ma Yêhôva, lĕ rngôch khân may phung oh mon Yêhôva, phung gŭ tâm ngih Yêhôva dôl măng.$b$,true),
('bunong-vn','PSA',134,2,null,$b$Yơr hom ti khân may bah ntŭk kloh ueh, Jêh ri mât ton hom ma Yêhôva.$b$,true),
('bunong-vn','PSA',134,3,null,$b$Dăn ma Yêhôva ăn nau ueh lăng ma khân may bơh ƀon Siôn; Păng yơh nơm rhăk trôk jêh ri neh ntu. Mât Ton Ma Yêhôva Yor Kan Păng Khlay.$b$,true),
('bunong-vn','PSA',135,1,null,$b$Halêluya, Tâm rnê hom ma amoh Yêhôva; Tâm rnê hom ma Păng; Ơ phung khân may oh mon Yêhôva;$b$,true),
('bunong-vn','PSA',135,2,null,$b$Khân may phung gŭ tâm ngih Yêhôva. Tâm nkual ngih Brah Ndu he.$b$,false),
('bunong-vn','PSA',135,3,null,$b$Tâm rnê hom ma Yêhôva; Yor lah Yêhôva jêng nơm ueh; Mprơ nau tâm rnê ma amoh păng; Yor lah nau nây maak.$b$,true),
('bunong-vn','PSA',135,4,null,$b$Yor lah Yêhôva săch jêh Yakôb ma păng nơm Jêh ri păng sŏk phung Israel jêng drăp păng krâm.$b$,true),
('bunong-vn','PSA',135,5,null,$b$Yor lah gâp gĭt Yêhôva jêng toyh Jêh ri Kôranh Brah he ta klơ lơn ma lĕ rngôch brah.$b$,true),
('bunong-vn','PSA',135,6,null,$b$Lĕ nau Yêhôva ŭch, păng ƀư jêh, Tâm trôk, tâm neh ntu, tâm dak rlai, jêh ri tâm lĕ rngôch ntŭk jru;$b$,true),
('bunong-vn','PSA',135,7,null,$b$Păng ăn phung ndâr tŭk hao bơh bôl neh. Păng ăn lơp jêh ri mih; păng ăn sial luh tă bơh ntŭk nau ndrŏng păng;$b$,false),
('bunong-vn','PSA',135,8,null,$b$Păng dong phung kon bu klâu bôk rah tâm n'gor Êjipt, nđâp ma bunuyh jêh ri mpô mpa;$b$,false),
('bunong-vn','PSA',135,9,null,$b$Păng tâm mpơl nau mbên jêh ri nau khlay ta nklang may, Ơ n'gor Êjipt. Ƀư ma hađăch Pharaôn jêh ri ma lĕ rngôch phung oh mon păng;$b$,false),
('bunong-vn','PSA',135,10,null,$b$Păng dong âk jêh phung mpôl băl, Jêh ri păng nkhĭt phung hađăch janh ktang.$b$,false),
('bunong-vn','PSA',135,11,null,$b$Si hôn hađăch phung Amôrit. Ŏk, hađăch ma phung Basan jêh ri lĕ rngôch ƀon bri hađăch n'gor Kanan.$b$,true),
('bunong-vn','PSA',135,12,null,$b$Jêh ri păng jao n'gor khân păng jêng drăp krâm. Drăp krâm ma phung Israel.$b$,true),
('bunong-vn','PSA',135,13,null,$b$Ơ Yêhôva, amoh may gŭ ƀa ƀơ, Ơ Yêhôva amoh may bu kah gĭt tâm lĕ rnôk,$b$,true),
('bunong-vn','PSA',135,14,null,$b$Yor lah Yêhôva mra phat dôih phung ƀon lan păng, jêh ri păng mra yô̆ ma phung oh mon păng.$b$,false),
('bunong-vn','PSA',135,15,null,$b$Phung rup brah, phung ƀon lan ƀư ma mah, jêh ri prăk. Kan ti bunuyh ƀư.$b$,true),
('bunong-vn','PSA',135,16,null,$b$Khân păng geh trôm mbung, ƀiă lah mâu blau ngơi ôh; Khân păng geh măt, ƀiă lah mâu saơ ôh.$b$,true),
('bunong-vn','PSA',135,17,null,$b$Khân păng geh tôr, ƀiă lah mâu tăng ôh. Mâu lĕ khân păng geh n'hâm tâm trôm mbung.$b$,true),
('bunong-vn','PSA',135,18,null,$b$Phung ƀư khân păng, mra jêng nâm bu khân păng; Nđâp ma lĕ rngôch phung rnơm ma khân păng.$b$,true),
('bunong-vn','PSA',135,19,null,$b$Ơ ngih Israel, mât ton hom ma Yêhôva, Ơ ngih Arôn, mât ton hom ma Yêhôva.$b$,true),
('bunong-vn','PSA',135,20,null,$b$Ơ ngih Lêvi, mât ton hom ma Yêhôva, Khân may phung klach yơk ma Yêhôva, mât ton hom ma Yêhôva.$b$,true),
('bunong-vn','PSA',135,21,null,$b$Mât ton hom ma Yêhôva bơh ƀon Siôn, Nơm gŭ ta ƀon Yêrusalem. Halêluya.$b$,true),
('bunong-vn','PSA',136,1,null,$b$Tâm rnê hom ma Yêhôva, Yor lah păng jêng nơm ueh; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,2,null,$b$Tâm rnê hom ma Brah Ndu ma lĕ phung brah; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,3,null,$b$Tâm rnê hom ma Kôranh Brah ma lĕ phung brah; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,4,null,$b$Knŏng păng nơm ƀư kan khlay; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,5,null,$b$Nơm rhăk jêh trôk ma nau gĭt rbăng; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,6,null,$b$Nơm lăk jêh neh ta klơ dak; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,7,null,$b$Nơm ƀư jêh âk rplay ang toyh; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,8,null,$b$Nar ŭch chiă uănh tâm nôk nar; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,9,null,$b$Khay jêh ri chiă uănh măng; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,10,null,$b$Păng yơh nơm dong phung kon bu klâu bôk rah bri Êjipt; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,11,null,$b$Jêh ri ăn phung Israel lah, tă bơh tâm nklang khân păng. Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,12,null,$b$Ma ti brah jêh ri nting tur yơr; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,13,null,$b$Păng tâm pă Dak Rlai chăng jêng bar kô̆ ; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,14,null,$b$Păng ăn phung Israel rgăn ta nklang păng Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,15,null,$b$Ƀiă lah păng ăn roh Pharaôn, jêh ri phung tahan păng tâm Dak Rlai Chăng; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,16,null,$b$Nơm njŭn phung ƀon lan păng rgăn ndrêch rdah; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,17,null,$b$Nơm dong jêh phung hađăch toyh; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,18,null,$b$Nơm nkhĭt phung hađăch lư n'găr; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,19,null,$b$Y-Sihôn phung hađăch Amôrit; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,20,null,$b$Jêh ri Ŏk, hađăch n'gor Basan; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,21,null,$b$Jêh ri jao ndơ khân păng, n'gor khân păng jêng drăp krâm; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,22,null,$b$Drăp krâm ma phung Israel, oh mon Păng; Yor nau ueh Păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,23,null,$b$Nơm kah gĭt ma he tơ lah he tông; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,24,null,$b$Jêh ri tâm rklaih he bơh phung rlăng. Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,25,null,$b$Nơm ăn ndơ sông sa ma lĕ rngôch nglay săk; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',136,26,null,$b$Tâm rnê hom ma Brah Ndu tâm trôk; Yor nau ueh păng gŭ ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',137,1,null,$b$Ta kơh dak krong Babilôn, He gŭ, jêh ri nhĭm, Tơ lah he kah gĭt ma ƀon Siôn.$b$,true),
('bunong-vn','PSA',137,2,null,$b$Ta tơm si Y-Sôl ta kơh dak krong nây. He mƀăk lơi gong rêng he$b$,true),
('bunong-vn','PSA',137,3,null,$b$Ta nây phung dơi đah he, ntăm ma he mprơ, Jêh ri phung tŭn jot he, ntăm nau hâk răm lah, Mprơ hom ma hên, du nau mprơ bơh ƀon Siôn.$b$,false),
('bunong-vn','PSA',137,4,null,$b$Mâm ƀư hên dơi mprơ nau mprơ ma Yêhôva tâm bri phung bu năch?$b$,true),
('bunong-vn','PSA',137,5,null,$b$Tơ lah gâp chuêl may, Ơ ƀon Yêrusalem Ăn ti ma gâp chuêl nau blau păng$b$,true),
('bunong-vn','PSA',137,6,null,$b$Ăn mpiăt gâp lĭl đah mơr gâp; Tơ lah gâp mâu kah gĭt đah may; Tơ lah gâp mâu ăn ƀon Yêrusalem jêng khlay lơn, ma nau răm maak gâp rŏng lơn.$b$,false),
('bunong-vn','PSA',137,7,null,$b$Ơ Yêhôva, ăn may kah gĭt ma phung kon bri Êđôm. Tâm nar ƀon Yêrusalem khân păng lah, Rơih lơi păng, rơih lơi păng kŏ tât ta ntur păng.$b$,true),
('bunong-vn','PSA',137,8,null,$b$Ơ Kon bu ur Babilôn, nơm bu mra ƀư rai; Ueh maak yơh ma nơm mra mplơ̆ ma may, nau mhĭk may ƀư jêh ma hên.$b$,true),
('bunong-vn','PSA',137,9,null,$b$Ueh maak yơh ma nơm mra sŏk phung kon may. Jêh ri mra nchah khân păng ma lŭ.$b$,true),
('bunong-vn','PSA',138,1,null,$b$Gâp mra tâm rnê ma May ma lĕ nuih n'hâm. Gâp mra mprơ nau tâm rnê ma may ta năp phung brah.$b$,true),
('bunong-vn','PSA',138,2,null,$b$Gâp mra yơk mbah mpeh bơh ngih brah kloh ueh May; Jêh ri gâp mra tâm rnê ma amoh May, Yor nau ueh May jêh ri nau na nê̆ May. Yor nau lư n'găr May, n'hao jêh ma nau May ƀư na nê̆, nau May ton.$b$,true),
('bunong-vn','PSA',138,3,null,$b$Nar gâp kuăl mbơh sơm ma May, may hŏ plơ̆ lah jêh ma gâp.$b$,true),
('bunong-vn','PSA',138,4,null,$b$Lĕ rngôch phung hađăch ta neh ntu, mra tâm rnê ma May, Ơ Yêhôva, Yor lah khân păng tăng jêh nau ngơi bơh bâr mbung May.$b$,true),
('bunong-vn','PSA',138,5,null,$b$Na nê̆ khân păng mra mprơ ma trong Yêhôva Yor lah nau chrêk rmah Yêhôva jêng toyh$b$,true),
('bunong-vn','PSA',138,6,null,$b$Nđâp tơ lah Yêhôva jêng prêh; ăt păng yơk ma phung tông bâr; Ƀiă lah păng gĭt năl phung sưr bơh ngai.$b$,false),
('bunong-vn','PSA',138,7,null,$b$Nđâp tơ lah gâp hăn tâm nklang nau uh ah; may mra ăn gâp rêh; May mra yơr ti May ƀư ma phung rlăng bêk. Jêh ri ti ma May mra tâm rklaih gâp.$b$,true),
('bunong-vn','PSA',138,8,null,$b$Yêhôva mra ƀư rah vah lĕ nau di ma gâp Ơ Yêhôva, nau ueh May gŭ ƀa ƀơ n'ho ro; Lơi ta cha lơi ôh kan ti May nơm ƀư jêh.$b$,true),
('bunong-vn','PSA',139,1,null,$b$Hơi Yêhôva! May hŏ sek uănh gâp jêh, jêh ri May gĭt năl gâp.$b$,true),
('bunong-vn','PSA',139,2,null,$b$May gĭt lĕ nau gâp gŭ ngao. Ntơm bơh ngai may gĭt lĕ moh nau gâp rvê.$b$,true),
('bunong-vn','PSA',139,3,null,$b$Lah gâp pah kan mâu lah rlu, May saơ đŏng.$b$,true),
('bunong-vn','PSA',139,4,null,$b$May gĭt dĭng lĕ đŏng mâm nau gâp ƀư. Ê lor gâp ngơi, Hơi Yêhôva! May hŏ gĭt jêh.$b$,true),
('bunong-vn','PSA',139,5,null,$b$Mâm nau gâp ŭch lah, May hŏ gĭt da dê jêh, May gŭ jŭm gâp, pa năp nđâp ma pa kơi.$b$,true),
('bunong-vn','PSA',139,6,null,$b$May king gâp ma ti brah May. Khlay hâu ngăn nau May gĭt tâm nau rêh gâp pô nây, jru ir ngăn, gâp mâu dơi gĭt rbăng ôh.$b$,true),
('bunong-vn','PSA',139,7,null,$b$Ntă nâm trong gâp mra dơi du krap ma Huêng Brah May? Gâp mâu dơi du ndâp bơh muh măt may ôh.$b$,true),
('bunong-vn','PSA',139,8,null,$b$Gâp hao ta klơ trôk, May gŭ ta nây lĕ.$b$,true),
('bunong-vn','PSA',139,9,null,$b$Gâp jŭr bêch tâm ntŭk phan, May gŭ ta nây lĕ. Lah gâp mpăr leo ta n'har bri pa lơ, mâu lah gŭ pa dâng kơh ri dak rlai,$b$,true),
('bunong-vn','PSA',139,10,null,$b$Ta nây ăt geh may lĕ njŭn leo gâp, jêh ri geh ti May mra kơl gâp.$b$,false),
('bunong-vn','PSA',139,11,null,$b$Lah gâp đă nau ngo nkŭm lơi gâp, đă nau ang jŭm gâp jêng măng,$b$,true),
('bunong-vn','PSA',139,12,null,$b$Ƀiă lah măng ăt mâu jêng ngo ma May ôh, măng jêng ang hô tâm ban ma nar.$b$,false),
('bunong-vn','PSA',139,13,null,$b$Nau ngo, nau ang jêng tâm ban da dê ma May. May njêng jêh ăp ntil ndơ tâm săk gâp, May dăp nkra săk jăn gâp tâm ndŭl me gâp.$b$,true),
('bunong-vn','PSA',139,14,null,$b$Gâp ŭch tâm rnê jêh ri yơk ma May, lĕ nau may ƀư jêng êng ngăn, khlay ngăn. Nuih n'hâm gâp gĭt ngăn nau nây.$b$,true),
('bunong-vn','PSA',139,15,null,$b$May saơ nting nđăng gâp hon tâm nau ndâp, dăp nkra tâm ntrŭp tâm trôm ndŭl me.$b$,true),
('bunong-vn','PSA',139,16,null,$b$Ê lor bu deh ma gâp, may hŏ saơ jêh gâp, tâm ndrom sămƀŭt May hŏ chih nal jêh tâm lĕ nar gâp mra gŭ rêh, ê lor ma nar bu ntơm kơp ma gâp.$b$,true),
('bunong-vn','PSA',139,17,null,$b$Ơ Brah Ndu nau mĭn May khlay ngăn ma gâp! Jêh ri păng jêng âk ngăn ngên?$b$,true),
('bunong-vn','PSA',139,18,null,$b$Tơ lah gâp kơp khân păng, khân păng âk lơn ma choih; Tơ lah gâp kah rngăl ăt gâp gŭ ndrel ma May.$b$,true),
('bunong-vn','PSA',139,19,null,$b$Ơ Brah Ndu, nanê̆ may mra nkhĭt phung ƀai; Ơ phung bunuyh rung mham du hom khân may ƀah đah gâp.$b$,true),
('bunong-vn','PSA',139,20,null,$b$Khân păng ngơi ma May ma nau ƀai, Jêh ri phung rlăng dŏng amoh May gay pâl$b$,true),
('bunong-vn','PSA',139,21,null,$b$Hơi Yêhôva! Mâu di hĕ gâp tâm rmot ma phung tâm rmot ma May? Jêh ri geh nau nuih ma phung dâk ƀư nau rdâng đah May?$b$,false),
('bunong-vn','PSA',139,22,null,$b$Gâp tâm rmot ma khân păng ma nau tâm rmot rah vah rĭng Khân păng jêng phung rlăng đah gâp.$b$,true),
('bunong-vn','PSA',139,23,null,$b$Sek uănh nuih n'hâm gâp, Ơ Brah Ndu, rlong uănh gâp gay ma gĭt nau gâp rvê.$b$,true),
('bunong-vn','PSA',139,24,null,$b$Lah geh nau mhĭk tâm gâp, ăn may ntĭm, jêh ri sâm njŭn leo gâp tâm trong nau rêh n'ho ro.$b$,true),
('bunong-vn','PSA',140,1,null,$b$Ơ Yêhôva, rklaih gâp bơh phung ƀai. N'gang gâp đah bunuyh janh, ƀai.$b$,true),
('bunong-vn','PSA',140,2,null,$b$Tâm nuih n'hâm khân păng tâm nchră nau ŭch ƀư djơh; Khân păng nchâp ma nau tâm lơh ƀa ƀơ.$b$,true),
('bunong-vn','PSA',140,3,null,$b$Khân păng tôl mpiăt khân păng, nâm bu mpiăt bêh; Khân păng geh dak kăch bêh rmâng tâm dâng trô yoi khân păng. (Sêla)$b$,true),
('bunong-vn','PSA',140,4,null,$b$Ơ Yêhôva, rklaih an gâp bơh ti phung ƀai N'gang gâp đah bunuyh janh ƀai; Ma phung mĭn gay ƀư prah gâp.$b$,false),
('bunong-vn','PSA',140,5,null,$b$Phung sưr sân dăk, jêh ri nthăng nhuăl gay ma geh gâp; Khân păng dơm nglĕ dăch trong; Khân păng gŭ kâp gâp. (Sêla)$b$,true),
('bunong-vn','PSA',140,6,null,$b$Gâp lah ma Yêhôva, may jêng Brah Ndu gâp Ơ Yêhôva, rkêng hom tôr may ma bâr gâp, vơh ma may.$b$,false),
('bunong-vn','PSA',140,7,null,$b$Ơ Yêhôva Kôranh Brah nau ktang ma nau tâm rklaih gâp, may nkŭm bôk gâp ta nar tâm lơh.$b$,true),
('bunong-vn','PSA',140,8,null,$b$Ơ Yêhôva, lơi May ăn tât nau phung ƀai ŭch. Lơi ăn nau khân păng ŭch mra jêng, klach khân păng tâm rnê ma khân păng nơm. (Sêla)$b$,true),
('bunong-vn','PSA',140,9,null,$b$Ăn tŭp ta bôk phung nchueng jŭm gâp. Nau mhĭk khân păng ngơi jêh ma gâp.$b$,false),
('bunong-vn','PSA',140,10,null,$b$Ăn sa ônh duh tŭp ta klơ khân păng Ăn bu klŭp khân păng tâm ŭnh, Tâm ntu jru, ta nây khân păng mâu hôm dơi dâk ôh.$b$,true),
('bunong-vn','PSA',140,11,null,$b$Bunuyh nchơt mâu mra gŭ nâp ôh ta neh ntu; Jêh ri nau djơh mra joi bunuyh janh ƀai, gay ma ngroh lơi păng.$b$,true),
('bunong-vn','PSA',140,12,null,$b$Gâp gĭt Yêhôva mra ƀư nau sŏng ma phung rêh ni; Nau di ma phung o ach.$b$,true),
('bunong-vn','PSA',140,13,null,$b$Na nê̆ phung sŏng mra tâm rnê ma amoh May. Phung sŏng mra gŭ ta năp May. Nau Mbơh Sơm Mhaơ Gay Ma Nau Ƀư Kloh Jêh Ri Nau N'gang An Nau mprơ ơm Y-Đavit.$b$,true),
('bunong-vn','PSA',141,1,null,$b$Ơ Yêhôva, Gâp kuăl mbơh sơm jêh ma May; Văch gơnh dăch gâp; Rkêng hom tôr ma bâr gâp, tơ lah gâp kuăl mbơh sơm ma May.$b$,true),
('bunong-vn','PSA',141,2,null,$b$Ăn nau gâp mbơh sơm jêng nâm bu ndơ ƀâu kah ta năp May; Jêh ri nau gâp yơr ti, jêng nâm bu ndơ nhhơr mhaơ.$b$,true),
('bunong-vn','PSA',141,3,null,$b$Ơ Yêhôva, chiă uănh trôm mbung gâp; Njrăng ma trô yoi gâp, tơ lah păng hă.$b$,true),
('bunong-vn','PSA',141,4,null,$b$Lơi ăn nuih n'hâm gâp rŏng ma nau mhĭk ôh, ŭch ƀư nau ƀai, ndrel ma phung bunuyh ƀư nau kue; Jêh ri lơi ăn gâp sa ndơ khlay khân păng.$b$,true),
('bunong-vn','PSA',141,5,null,$b$Ăn nơm sŏng dong gâp, nau nây mra jêng nau ueh ma gâp; Ăn păng nduyh gâp, nau nây mra jêng nâm bu dak ngi ta klơ bôk gâp; Lơi ăn bôk gâp dun ma nau nây ôh. Yor lah, nđâp tơ lah khân păng ƀư nau ƀai, gâp ăt mbơh sơm.$b$,true),
('bunong-vn','PSA',141,6,null,$b$Bu mra klŭp Kôranh phat dôih khân păng ta keng lŭ; Jêh ri khân păng mra tăng nau gâp ngơi; Yor nau ngơi nây jêng maak.$b$,true),
('bunong-vn','PSA',141,7,null,$b$Tâm ban ma bu kai neh, jêh ri blah neh ma kau kai; Nting hên nchah du ta mpông pêr Ƀon Phung Khĭt.$b$,true),
('bunong-vn','PSA',141,8,null,$b$Mpeh pa may yơh, Ơ Yêhôva Kôranh Brah, măt gâp uănh, Tâm may yơh gâp krap, lơi cha lơi huêng gâp ôh.$b$,true),
('bunong-vn','PSA',141,9,null,$b$Rklaih gâp bơh dăk khân păng sân jêh ma gâp; Jêh ri ma nau phung ƀư mhĭk kâp gâp.$b$,true),
('bunong-vn','PSA',141,10,null,$b$Ăn phung ƀai prah tâm nhuăl khân păng nơm, Dôl nây gâp klaih yơh.$b$,true),
('bunong-vn','PSA',142,1,null,$b$Bâr gâp nter ma Yêhôva; Bâr gâp vơh vơl ma Yêhôva.$b$,true),
('bunong-vn','PSA',142,2,null,$b$Gâp tâm mpơl nau rêh ni gâp ta năp Păng; Gâp nkoch bri nau uh ah gâp ma Păng.$b$,true),
('bunong-vn','PSA',142,3,null,$b$Tơ lah huêng gâp rdơ̆ tâm trôm gâp, may gĭt năl jêh trong gâp. Mbah trong gâp hăn. Bu sân dăk jêh ma gâp.$b$,true),
('bunong-vn','PSA',142,4,null,$b$Uănh pa ma gâp, jêh ri saơ; Yor lah mâu geh bunuyh gĭt năl gâp ôh. Gâp mâu geh ntŭk krap ôh; Mâu geh nơm chrê ma huêng gâp ôh.$b$,true),
('bunong-vn','PSA',142,5,null,$b$Gâp nter ma may, Ơ Yêhôva; Jêh ri gâp lah, may jêng ntŭk gâp gŭ krap, Ndơ bu pă ma gâp ta neh ntu phung rêh.$b$,true),
('bunong-vn','PSA',142,6,null,$b$Rkêng hom may ma nau gâp nter; Yor gâp jêng rêh ni ngăn ngên; Rklaih an gâp bơh phung ƀư mhĭk đah gâp. Yor khân păng ktang lơn ma gâp.$b$,true),
('bunong-vn','PSA',142,7,null,$b$Mphâk lơi huêng gâp tă bơh ndrung bu nă; Gay ma gâp dơi tâm rnê ma amoh may. Phung sŏng mra gŭ jŭm gâp; Yor lah may mra ƀư âk nau ueh ma gâp.$b$,true),
('bunong-vn','PSA',143,1,null,$b$Ơ Yêhôva, iăt hom nau gâp mbơh sơm. Rkêng hom tôr ma nau gâp vơh vơl; Lŏ plơ̆ lah ma gâp tâm nau may gŭ răp jăp, jêh ri tâm nau sŏng srăng may.$b$,true),
('bunong-vn','PSA',143,2,null,$b$Lơi ƀư nau phat dôih ma phung oh mon may ôh; Yor lah mâu geh du huê jêng sŏng ta năp may ôh.$b$,true),
('bunong-vn','PSA',143,3,null,$b$Yor lah nơm rlăng tĭng huêng gâp; Păng jot ta neh nau rêh gâp; Păng ăn gâp gŭ tâm ntŭk nau ngo, nâm bu phung khĭt bơh jŏ jêh.$b$,true),
('bunong-vn','PSA',143,4,null,$b$Yor nây huêng gâp huơi tâm trôm gâp; Nuih n'hâm gâp uh ah tâm gâp.$b$,true),
('bunong-vn','PSA',143,5,null,$b$Gâp kah gĭt ma nar rnôk kăl e; Gâp gŭ mĭn ma lĕ rngôch kan May; Gâp mĭn ma kan ti May.$b$,true),
('bunong-vn','PSA',143,6,null,$b$Gâp yơr ti gâp ma May; Huêng gâp ji hir ma May, nâm bu neh sơh. (Sêla)$b$,true),
('bunong-vn','PSA',143,7,null,$b$Ăn May ndal lŏ plơ̆ lah ma gâp; Ơ Yêhôva huêng gâp gŭ rdja; Lơi pôn măt May ma gâp, klach lah gâp jêng phung jŭr ta ntu jru.$b$,false),
('bunong-vn','PSA',143,8,null,$b$Ăn gâp iăt nau ueh May bơh ôi ơm; Yor gâp rnơm ma May; Ăn gâp gĭt trong gâp mra hăn; Yor gâp n'hao huêng gâp pa May.$b$,true),
('bunong-vn','PSA',143,9,null,$b$Ơ Yêhôva, rklaih an gâp bơh phung rlăng, Gâp hăn ma may gay krap.$b$,true),
('bunong-vn','PSA',143,10,null,$b$Sâm nti gâp ƀư nau May ŭch; Yor may jêng Brah Ndu gâp; Brah Huêng May jêng ueh; Njŭn leo gâp tâm n'gor sŏng srăng.$b$,true),
('bunong-vn','PSA',143,11,null,$b$Yor nây may, Ơ Yêhôva, ƀư rêh hom gâp; Tâm nau sŏng srăng May, mphâk lơi huêng gâp bơh nau uh ah.$b$,true),
('bunong-vn','PSA',143,12,null,$b$Tâm nau ueh May, ƀư roh lơi phung rlăng gâp. Jêh ri ƀư rai lĕ rngôch phung ƀư rêh ni huêng gâp; Yor gâp jêng oh mon May.$b$,true),
('bunong-vn','PSA',144,1,null,$b$Mât ton hom ma Yêhôva, lŭ gâp, Nơm nti an ti gâp ma nau tâm lơh. Nglau ti gâp ma nau tâm ƀư;$b$,true),
('bunong-vn','PSA',144,2,null,$b$Nơm ƀư ueh ma gâp, nơm jêng pôih n'gang gâp, Ngih tŭm gâp jêh ri nơm tâm rklaih gâp; Khêl gâp, jêh ri ntŭk gâp gŭ krap; Nơm nglăp phung ƀon lan ma gâp.$b$,false),
('bunong-vn','PSA',144,3,null,$b$Ơ Yêhôva, moh bunuyh jêng, kŏ may njê ma păng? Mâu lah Kon bunuyh, kŏ may chiă uănh păng?$b$,true),
('bunong-vn','PSA',144,4,null,$b$Bunuyh jêng nâm bu suh n'hâm, Nar păng gŭ rêh jêng nâm bu gui rgăn.$b$,true),
('bunong-vn','PSA',144,5,null,$b$Ơ Yêhôva, n'glưh trôk may jêh ri jŭr hom Rbot phung yôk, jêh ri khân păng mra luh nhhŭk ŭnh.$b$,true),
('bunong-vn','PSA',144,6,null,$b$Ăn lơp sol, jêh ri mprơh lơi phung rlăng gâp; Rjăng hăr may, jêh ri dơi đah khân păng,$b$,true),
('bunong-vn','PSA',144,7,null,$b$Yor ti may bơh klơ; Koh dŏng hom gâp, jêh ri rklaih an gâp ma dak toyh, ma ti phung bu năch;$b$,false),
('bunong-vn','PSA',144,8,null,$b$Trôm mbung khân păng ngơi ma nau ndơm, ti ma khân păng jêng mƀruh$b$,false),
('bunong-vn','PSA',144,9,null,$b$Ơ Brah Ndu, gâp mra mprơ ma may du nau mprơ mhe; Gâp mra mprơ nau tâm rnê ma may ma gong rêng jât rse.$b$,false),
('bunong-vn','PSA',144,10,null,$b$May jêng nơm ăn nau tâm rklaih ma phung hađăch; Nơm tâm rklaih Đavit, oh mon păng, ma đao gưm ƀư rai.$b$,true),
('bunong-vn','PSA',144,11,null,$b$Koh dŏng hom gâp, jêh ri rklaih gâp ma ti phung bu năch. Mbung khân păng ngơi nau ndơm, jêh ri ti ma khân păng jêng ti ma mƀruh.$b$,true),
('bunong-vn','PSA',144,12,null,$b$Tơ lah phung kon bu klâu he mra jêng nâm bu ndơ bu tăm, Dôl văch ma toyh tâm rnôk khân păng hôm mom, Jêh ri phung kon bu ur he jêng nâm bu lŭ njônh bu kach. Jêng nkrơ̆ ma ngih hađăch.$b$,true),
('bunong-vn','PSA',144,13,null,$b$Tơ lah jay he bêng jêh ma ăp ndơ prăp, Jêh ri phung biăp he jêng bĭk rbăn rbăn, rmưn rmưn tâm ndrêch bri he;$b$,true),
('bunong-vn','PSA',144,14,null,$b$Tơ lah phung ndrôk me he deh âk kon; Tơ lah mâu geh nau ƀư rai, mâu geh nau jêng bu nă, mâu geh nau nter ôh tâm trong he;$b$,false),
('bunong-vn','PSA',144,15,null,$b$Ueh maak yơh ma phung ƀon lan geh nau tâm ban pô nây; Nanê̆, ueh maak yơh phung ƀon lan geh Yêhôva jêng Brah Ndu.$b$,false),
('bunong-vn','PSA',145,1,null,$b$Ơ Brah Ndu gâp, hađăch gâp, gâp mra yơk tâm rnê ma May; Jêh ri gâp mra mât ton ma amoh May ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',145,2,null,$b$Ăp nar gâp mra mât ton ma May; Jêh ri gâp mra tâm rnê ma amoh May ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',145,3,null,$b$Yêhôva jêng toyh, jêh ri khư ma nau tâm rnê; Jêh ri nau toyh păng mâu dơi veh ôh.$b$,true),
('bunong-vn','PSA',145,4,null,$b$Ăp rnôk phung bunuyh, mra tâm rnê ma kan May, Jêh ri mra mbơh Kon Brah May.$b$,true),
('bunong-vn','PSA',145,5,null,$b$Gâp mra mĭn ma nau yơk ma May, geh nau lư n'găr chrêk rmah; Jêh ri ma kan khlay May.$b$,true),
('bunong-vn','PSA',145,6,null,$b$Phung bunuyh mra ngơi ma nau brah kan May toyh ngăn ngên. Jêh ri gâp mra nkoch bri ma nau lư n'găr May.$b$,true),
('bunong-vn','PSA',145,7,null,$b$Khân păng mra mbơh nau kah gĭt ma nau ueh May toyh, Jêh ri mra mprơ ma nau sŏng srăng May.$b$,true),
('bunong-vn','PSA',145,8,null,$b$Yêhôva jêng nơm blau yô̆, jêh ri jêng nơm ueh; Mâu gơnh nuih ôh, jêh ri bêng ma nau ueh.$b$,true),
('bunong-vn','PSA',145,9,null,$b$Yêhôva jêng nơm ueh đah lĕ rngôch; Jêh ri nau păng yô̆ gŭ ta lĕ rngôch kan păng.$b$,true),
('bunong-vn','PSA',145,10,null,$b$Ơ Yêhôva; lĕ rngôch kan May mra tâm rnê ma May; Jêh ri phung kloh ueh May, mra mât ton ma May.$b$,true),
('bunong-vn','PSA',145,11,null,$b$Khân păng mra ngơi ma nau chrêk rmah ƀon bri hađăch May. Jêh ri khân păng mra mbơh nau brah May.$b$,true),
('bunong-vn','PSA',145,12,null,$b$Gay ăn phung kon bunuyh gĭt năl kon brah păng jêh ri nau chrêk rmah, nau ma ƀon bri hađăch păng.$b$,true),
('bunong-vn','PSA',145,13,null,$b$Ƀon bri hađăch May jêng ƀon bri hađăch n'ho ro. Jêh ri nau May chiă uănh gŭ tâm lĕ rngôch rnôk.$b$,true),
('bunong-vn','PSA',145,14,null,$b$Yêhôva rdâng lĕ rngôch phung tŭp, Jêh ri păng rdâk nhhơk lĕ rngôch hŏ kŭnh jêh.$b$,true),
('bunong-vn','PSA',145,15,null,$b$Măt bunuyh kâp gân ma May; Jêh ri May ăn ndơ sông sa ma khân păng di yăn.$b$,true),
('bunong-vn','PSA',145,16,null,$b$May mplơt ti May, jêh ri ăn hơm lĕ rngôch mpa, geh nau rêh tĭng nâm khân păng ŭch.$b$,true),
('bunong-vn','PSA',145,17,null,$b$Yêhôva jêng sŏng tâm lĕ trong Păng Jêh ri gĭt yô̆ tâm lĕ kan Păng.$b$,true),
('bunong-vn','PSA',145,18,null,$b$Yêhôva gŭ dăch lĕ rngôch phung kuăl mbơh sơm ma Păng; Đah lĕ rngôch phung kuăl mbơh sơm ma Păng ma nau nanê̆ ngăn.$b$,true),
('bunong-vn','PSA',145,19,null,$b$Păng mra ăn tât tĭng nâm nau ŭch phung klach yơk ma Păng; Păng mra iăt lĕ nau bu nter, jêh ri rklaih an.$b$,true),
('bunong-vn','PSA',145,20,null,$b$Yêhôva chiă uănh lĕ rngôch phung rŏng ma păng; ƀiă lah Păng mra ƀư rai lĕ rngôch phung ƀai.$b$,true),
('bunong-vn','PSA',145,21,null,$b$Bâr mbung gâp mra ngơi tâm rnê ma Yêhôva; Jêh ri ăn lĕ rngôch nglay săk mât ton ma amoh kloh ueh. Păng ƀa ƀơ n'ho ro.$b$,true),
('bunong-vn','PSA',146,1,null,$b$Halêluya, Ơ huêng gâp, tâm rnê hom ma Yêhôva,$b$,true),
('bunong-vn','PSA',146,2,null,$b$Gâp mra tâm rnê ma Yêhôva dôl gâp gŭ rêh; Gâp mra mprơ tâm rnê ma Brah Ndu gâp, dôl dŭm nar gâp gŭ rêh.$b$,false),
('bunong-vn','PSA',146,3,null,$b$Lơi ta khân may rnơm ma phung kon hađăch ôh,$b$,true),
('bunong-vn','PSA',146,4,null,$b$N'hâm păng hăn, păng sĭt ta ndruyh neh; Tâm nar nây yơh nau păng ŭch ƀư rai lôch.$b$,false),
('bunong-vn','PSA',146,5,null,$b$Ueh maak yơh nơm geh Brah Ndu Yakôb jêng nơm kơl, Ma nơm kâp gân tâm Yêhôva, Brah Ndu păng,$b$,true),
('bunong-vn','PSA',146,6,null,$b$Nơm rhăk trôk jêh ri neh ntu, Dak rlai jêh ri lĕ rngôch mpa tâm khân păng; Nơm djôt prăp nau nanê̆ n'ho ro,$b$,false),
('bunong-vn','PSA',146,7,null,$b$Nơm ƀư nau di ma phung bu tŭn jot; Nơm ăn ndơ sông sa ma phung ji ngot, Yêhôva ăn phung bu nă jêng kon me,$b$,false),
('bunong-vn','PSA',146,8,null,$b$Yêhôva ăn phung chieh măt dơi lin Yêhôva lŏ ăn phung kuăt bŭt jêng sŏng Yêhôva rŏng ma phung sŏng, Yêhôva chiă uănh phung bu năch,$b$,false),
('bunong-vn','PSA',146,9,null,$b$Păng kơl rđâng phung kon đơi khĭt mbơ̆ jêh ri bu ur ndrô, Ƀiă lah păng ƀư prah trong phung ƀai.$b$,false),
('bunong-vn','PSA',146,10,null,$b$Yêhôva mra chiă uănh n'ho ro, Brah Ndu may, Hơi ƀon Siôn gŭ tâm lĕ rnôk. Halêluya.$b$,true),
('bunong-vn','PSA',147,1,null,$b$Halêluya; Yor lah ueh yơh mprơ tâm rnê ma Brah Ndu he; Yor lah maak jêh ri di tâm rnê ma Păng.$b$,true),
('bunong-vn','PSA',147,2,null,$b$Yêhôva rdâk ƀon Yêrusalem; Păng tâm rƀŭn phung kon Israel nchah du jêh.$b$,true),
('bunong-vn','PSA',147,3,null,$b$Păng ƀư bah phung geh nuih n'hâm nchah, jêh ri păng put ntŭk sôt khân păng.$b$,true),
('bunong-vn','PSA',147,4,null,$b$Păng kơp dŭm âk play mănh. Păng tâm amoh jêh lĕ rngôch mănh.$b$,true),
('bunong-vn','PSA',147,5,null,$b$Kôranh Brah he jêng toyh, brah ma nau ktang păng; Nau gĭt rbăng păng mâu geh lôch bôl ôh.$b$,true),
('bunong-vn','PSA',147,6,null,$b$Yêhôva kâp kơl phung dêh rhêt. Păng njŭr tâm dâng phung ƀai tât ta neh.$b$,true),
('bunong-vn','PSA',147,7,null,$b$Mprơ hom ma Yêhôva ma nau tâm rnê; Mprơ tâm rnê hom ma Brah Ndu he ma gong rêng.$b$,true),
('bunong-vn','PSA',147,8,null,$b$Nơm nkŭm trôk ma ndâr tŭk, Nơm nkra dak mih ma neh ntu, Nơm ăn gơ̆ hon tâm yôk.$b$,true),
('bunong-vn','PSA',147,9,null,$b$Nơm ăn ndơ ma phung mpa bri, Jêh ri ma phung kon nđak, tơ lah khân păng nter.$b$,true),
('bunong-vn','PSA',147,10,null,$b$Păng mâu maak ôh ma nau dăng seh. Păng mâu maak lĕ tâm jâng bunuyh.$b$,true),
('bunong-vn','PSA',147,11,null,$b$Yêhôva maak tâm phung klach yơk ma Păng, Tâm phung kâp gân ma nau ueh Păng.$b$,true),
('bunong-vn','PSA',147,12,null,$b$Ơ ƀon Yêrusalem tâm rnê hom ma Yêhôva Ơ ƀon Siôn, tâm rnê hom ma Brah Ndu may.$b$,true),
('bunong-vn','PSA',147,13,null,$b$Yor păng ƀư nâp mâng nđăng mpông pêr may; Păng ăn nau ueh uĭn ma phung kon may ta nklang may.$b$,true),
('bunong-vn','PSA',147,14,null,$b$Păng ăn nau đăp mpăn ma bri may. Păng n'hơm may ma phe blê ueh lơn$b$,true),
('bunong-vn','PSA',147,15,null,$b$Păng njuăl nau păng ntăm ta neh ntu; Nau păng ngơi nchuăt ngăch ngăn$b$,false),
('bunong-vn','PSA',147,16,null,$b$Păng ăn dak pler nâm bu rsau biăp. Păng nkhŭt glo dak nđik nglang, nâm bu ŭnh buh.$b$,false),
('bunong-vn','PSA',147,17,null,$b$Păng klŭp phung rchuăl dak nđik, Mbu dơi gŭ ta năp nau nđik păng?$b$,true),
('bunong-vn','PSA',147,18,null,$b$Păng njuăl nau păng ngơi, jêh ri ƀư lêk lơi; Păng ăn sial n'hĭt, jêh ri dak hoch.$b$,true),
('bunong-vn','PSA',147,19,null,$b$Păng tâm mpơl nau Păng ngơi ma Yakôb; Nau vay Păng jêh ri nau Păng ntăm ma phung Israel.$b$,true),
('bunong-vn','PSA',147,20,null,$b$Păng mâu ƀư pô nây ôh ma moh mpôl băl; Jêh ri khân păng mâu gĭt rbăng ôh nau păng ntăm. Halêluya.$b$,true),
('bunong-vn','PSA',148,1,null,$b$Halêluya. Tâm rnê hom ma Yêhôva tă bơh trôk; Tâm rnê hom ma Păng tâm ntŭk klơ lơn.$b$,true),
('bunong-vn','PSA',148,2,null,$b$Tâm rnê hom ma Păng, lĕ rngôch khân may phung oh mon ueh păng; Tâm rnê hom ma Păng lĕ rngôch khân may phung tahan păng.$b$,true),
('bunong-vn','PSA',148,3,null,$b$Tâm rnê hom ma păng, nar jêh ri khay: Tâm rnê hom khân may phung mănh ang.$b$,true),
('bunong-vn','PSA',148,4,null,$b$Tâm rnê hom ma păng, Ơ phung trôk ta klơ trôk Jêh ri khân may, phung dak gŭ ta klơ trôk;$b$,true),
('bunong-vn','PSA',148,5,null,$b$Ăn khân păng tâm rnê ma amoh Yêhôva; Yor lah păng ntăm jêh, pô ri khân păng jêng.$b$,false),
('bunong-vn','PSA',148,6,null,$b$Kôranh Brah ƀư nâp lĕ phung nây ƀa ƀơ n'ho ro. Păng ăn jêh nau vay, jêh ri khân păng mâu mra lăn gao ôh.$b$,true),
('bunong-vn','PSA',148,7,null,$b$Tâm rnê hom ma Yêhôva bơh neh ntu, Phung ka toyh tâm dak rlai, jêh ri lĕ rngôch ntu jru;$b$,true),
('bunong-vn','PSA',148,8,null,$b$Ŭnh jêh ri pler, dak pler jêh ri thŭl; Sial ktang tông bâr păng ngơi,$b$,false),
('bunong-vn','PSA',148,9,null,$b$Phung yôk jêh ri lĕ rngôch mƀon; Phung tơm play jêh ri lĕ rngôch tơm play Sêdrơ;$b$,false),
('bunong-vn','PSA',148,10,null,$b$Phung mpa bri jêh ri lĕ rngôch ndrôk rpu; Phung mpa vơr, jêh ri phung sĭm mpăr;$b$,false),
('bunong-vn','PSA',148,11,null,$b$Phung hađăch neh ntu jêh ri lĕ rngôch phung ƀon lan; Phung kon hađăch jêh ri lĕ rngôch phung Kôranh phat dôih ta neh ntu;$b$,false),
('bunong-vn','PSA',148,12,null,$b$Phung bu klâu ndăm nđâp phung bu ur druh; Phung ranh nđâp phung kon se;$b$,false),
('bunong-vn','PSA',148,13,null,$b$Ăn khân păng tâm rnê ma amoh Yêhôva; Yor lah Knŏng amoh Păng jêng klơ lơn ma neh ntu jêh ri trôk$b$,false),
('bunong-vn','PSA',148,14,null,$b$Păng ntop n'hâm suan phung ƀon lan, gay ma khân păng tâm rnê ma Kôranh brah; Nâm bu ntĭt ma phung kon Israel, Phung ƀon lan gŭ dăch păng. Halêluya.$b$,false),
('bunong-vn','PSA',149,1,null,$b$Halêluya, Mprơ hom ma Yêhôva du nau mprơ mhe, Mprơ hom nau tâm rnê ma Păng, tâm nau tâm rƀŭn phung kloh ueh.$b$,true),
('bunong-vn','PSA',149,2,null,$b$Ăn phung Israel răm maak tâm nơm rhăk njêng jêh khân păng. Ăn phung kon ƀon Siôn răm maak tâm hađăch khân păng.$b$,true),
('bunong-vn','PSA',149,3,null,$b$Ăn khân păng tâm rnê ma amoh Yêhôva ma nau kadŏ. Ăn khân păng tâm rnê ma Kôranh Brah ma gâr jê̆ jêh ri ma gong rêng.$b$,true),
('bunong-vn','PSA',149,4,null,$b$Yor lah Yêhôva geh nau maak tâm phung ƀon lan Păng; Păng mra ndrăp phung tông bâr ma nau tâm rklaih.$b$,true),
('bunong-vn','PSA',149,5,null,$b$Ăn phung kloh ueh geh nau maak tâm nau chrêk rmah. Ăn khân păng mprơ hâk maak ta sưng bêch khân păng.$b$,true),
('bunong-vn','PSA',149,6,null,$b$Ăn nau tâm rnê ma Brah Ndu gŭ tâm trôm mbung khân păng, Jêh ri đao gưm măt bar gŭ tâm ti khân păng;$b$,true),
('bunong-vn','PSA',149,7,null,$b$Ŭch ƀư nau plơng bôk ma phung mpôl băl, Gay ma tâm rmal phung ƀon lan;$b$,false),
('bunong-vn','PSA',149,8,null,$b$Ŭch kât chăp phung hađăch khân păng ma rse rvăk, jêh ri phung toyh khân păng chăp ma rse loih.$b$,false),
('bunong-vn','PSA',149,9,null,$b$Ŭch ƀư ma khân păng nau phat dôih bu chih jêh; Lĕ rngôch phung kloh ueh păng geh nau chrêk rmah nây. Halêluya.$b$,true),
('bunong-vn','PSA',150,1,null,$b$Halêluya Tâm rnê hom ma Brah Ndu tâm ntŭk kloh ueh Păng; tâm rnê hom ma Păng tâm ntŭk huy ngai nau brah Păng.$b$,true),
('bunong-vn','PSA',150,2,null,$b$Tâm rnê hom ma Păng yor kan khlay Păng. Tâm rnê hom ma Păng tĭng nâm nau toyh Păng mâu blau lôch bôl.$b$,true),
('bunong-vn','PSA',150,3,null,$b$Tâm rnê hom ma Păng ma bâr nŭng. Tâm rnê hom ma Păng ma dĭng rlet jêh ri ma gong rêng.$b$,true),
('bunong-vn','PSA',150,4,null,$b$Tâm rnê hom ma Păng ma gâr jê̆ jêh ri ma nau kadŏ; Tâm rnê hom ma Păng ma gong rêng jêh ri dĭng vưt.$b$,true),
('bunong-vn','PSA',150,5,null,$b$Tâm rnê hom ma Păng ma dang nteh huy ngăn.$b$,true),
('bunong-vn','PSA',150,6,null,$b$Ăn lĕ rngôch mpa blau suh n'hâm tâm rnê ma Yêhôva. Halêluya.$b$,true);
