insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'PRO', $b$Nau Hôr$b$, $b$["NAU HÔR"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PRO',1,1,null,$b$Nau hôr Y-Salômôn, kon bu klâu Y-Đavit, hađăch phung Israel:$b$,true),
('bunong-vn','PRO',1,2,null,$b$Gay ma bunuyh gĭt vât nau blau mĭn jêh ri nau sâm nti, gay sek uănh nau ngơi bơh nau gĭt rbăng;$b$,false),
('bunong-vn','PRO',1,3,null,$b$Gay sŏk dơn ntil nau nti bơh nau blau mĭn gay ƀư nau sŏng, nau di, jêh ri nau n'hêl nanê̆.$b$,false),
('bunong-vn','PRO',1,4,null,$b$Gay ăn nau blau sek uănh ma phung rluk, jêh ri nau gĭt mĭn âk phung mom ndăm.$b$,true),
('bunong-vn','PRO',1,5,null,$b$Nđâp nơm gĭt rbăng dơi gŭ iăt tâm ban lĕ, jêh ri nti gay gĭt mĭn lơn; jêh ri nơm gĭt rbăng dơi geh nau blau âk.$b$,true),
('bunong-vn','PRO',1,6,null,$b$Gay gĭt vât hôr jêh ri nau bu tâm ntĭt nau phung blau mĭn ngơi, jêh ri nau khân păng ngơi nau chroh n'hôr.$b$,true),
('bunong-vn','PRO',1,7,null,$b$Nau klach yơk ma Yêhôva jêng tơm ma nau gĭt rbăng; phung rluk tâm rmot ma nau blau mĭn jêh ri nau bu sâm nti.$b$,true),
('bunong-vn','PRO',1,8,null,$b$Hơi kon, iăt hom nau mbơ̆ may sâm nti may, jêh ri lơi ta dun ôh nau mê̆ may nti;$b$,true),
('bunong-vn','PRO',1,9,null,$b$yor lah nau nây jêng rvang kao si ueh ma bôk may, jêh ri ndơ ueh văn trô ko may.$b$,false),
('bunong-vn','PRO',1,10,null,$b$Hơi kon, tơ lah phung tih ŭch ndơm may, lơi may tông ôh.$b$,true),
('bunong-vn','PRO',1,11,null,$b$Tơ lah khân păng lah: “Văch ndrel ma hên, ăn he kâp pling mham păng, ƀư ndrap kâp lơh ma nơm mâu geh nau tih ôh.$b$,true),
('bunong-vn','PRO',1,12,null,$b$Nâm bu Ƀon Phung Khĭt, ăn he rvăn mlâm glom rêh khân păng nâm bu phung trŭnh ma ntu môch.$b$,true),
('bunong-vn','PRO',1,13,null,$b$He mra dơi geh ăp ntil drăp khlay, prăp bêng ngih vâl he lĕ đơ ndơ pit in.$b$,true),
('bunong-vn','PRO',1,14,null,$b$Sŏk hom drăp khân may ăn ndrel ma hên, lĕ rngôch he mra geh knŏng du dŭng prăk dơm.”$b$,true),
('bunong-vn','PRO',1,15,null,$b$Hơi kon, lơi hăn ndrel ôh ma khân păng, nkân hom jâng khân may lơi tĭng ndô̆ trong khân păng;$b$,true),
('bunong-vn','PRO',1,16,null,$b$Yor lah jâng khân păng nchuăt ran ŭch ƀư nau mhĭk jêh ri khân păng ndal ƀư pling mham bu ro.$b$,false),
('bunong-vn','PRO',1,17,null,$b$Yor lah drăng dơm dam yơh nhuăl ta năp phung sĭm och saơ.$b$,true),
('bunong-vn','PRO',1,18,null,$b$Ƀiă lah phung aơ gŭ kâp ŭch pling mham khân păng nơm, khân păng ƀư ndrap gay ƀư mhĭk nau rêh khân păng nơm.$b$,true),
('bunong-vn','PRO',1,19,null,$b$Nây yơh jêng trong ma lĕ rngôch phung ŭch ƀư nau mhĭk kơnh sa drăp ndơ; phung rŏng ma drăp ndơ mra ƀư roh nau rêh khân păng nơm.$b$,true),
('bunong-vn','PRO',1,20,null,$b$Nau blau mĭn nter rŏ trong sâng, păng nter tâm nklang ngih tăch drăp;$b$,true),
('bunong-vn','PRO',1,21,null,$b$păng kuăl tâm ntŭk rdjŭm trong, păng ngơi ta mpông ƀon toyh jêh ri tâm trôm ƀon.$b$,false),
('bunong-vn','PRO',1,22,null,$b$Păng lah: “Hơi phung rluk, ndah nâm jŏ khân may mra rŏng nau jêng rluk” Ndah nâm jŏ phung mưch mra maak ma nau khân păng mưch, jêh ri phung rluk tâm rmot ma nau blau mĭn?$b$,true),
('bunong-vn','PRO',1,23,null,$b$Gŭ iăt nau gâp nduyh, aơ, gâp mra nkhŭt Brah Huêng gâp mĭn ma khân may; Gâp mra ăn khân may gĭt nau gâp ngơi.”$b$,true),
('bunong-vn','PRO',1,24,null,$b$Yor lah gâp kuăl jêh ri khân may dun, mâu ŭch iăt ôh; gâp vơch ti jă may, jêh ri mâu geh ôh nơm chrê ma nau nây.$b$,true),
('bunong-vn','PRO',1,25,null,$b$Ƀiă lah khân may dun lơi lĕ rngôch nau gâp ntĭm nti. Jêh ri mâu sŏk dơn ôh nau gâp nduyh.$b$,true),
('bunong-vn','PRO',1,26,null,$b$Yor ri dôl khân may geh nau rêh ni, gâp mra gơm; gâp mra mưch tơ lah geh nau krit klach tât ma khân may.$b$,true),
('bunong-vn','PRO',1,27,null,$b$Tơ lah nau klach tât ma khân may nâm bu phŭt chuănh, jêh ri nau rêh ni tât ma khân may nâm bu sial vănh blông tơ lah geh nau uh ah jêh ri nau rngot tât ma khân may.$b$,true),
('bunong-vn','PRO',1,28,null,$b$Rnôk nây khân păng ma kuăl gâp, ƀiă lah gâp mâu mra plơ̆ lah ôh; khân păng mra joi gâp ma lĕ nuih n'hâm, ƀiă lah khân păng mâu mra saơ gâp ôh.$b$,true),
('bunong-vn','PRO',1,29,null,$b$Yor lah khân păng tâm rmot jêh ma nau gĭt vât, jêh ri mâu săch ôh nau klach yơk ma Yêhôva.$b$,true),
('bunong-vn','PRO',1,30,null,$b$Mâu dơm ôh tĭng nau gâp ntĭm nti jêh ri tâm rmot lĕ rngôch nau gâp nduyh.$b$,true),
('bunong-vn','PRO',1,31,null,$b$Yor nây khân păng mra sa play tĭng nâm trong khân păng tĭng, jêh ri hơm ma nau khân pĕ nau ndơm.$b$,true),
('bunong-vn','PRO',1,32,null,$b$Phung rluk khĭt yor lah khân păng tĭng trong kue jêh ri khân păng mâu chrê ôh mra ƀư rai khân păng.$b$,true),
('bunong-vn','PRO',1,33,null,$b$Ƀiă mbu nơm gŭ iăt gâp mra gŭ nđơh rngêt jêh ri mra gŭ đăp mpăn mâu klach ma nau mhĭk ôh.”$b$,true),
('bunong-vn','PRO',2,1,null,$b$Hơi kon, tơ lah may sŏk dơn nau gâp ngơi, jêh ri djôt prăp nau gâp ntăm tâm nuih n'hâm may.$b$,true),
('bunong-vn','PRO',2,2,null,$b$Rkêng tôr ma nau blau mĭn, geh nuih n'hâm ma nau gĭt rbăng;$b$,true),
('bunong-vn','PRO',2,3,null,$b$Ngăn yơh, tơ lah may joi, sek uănh ăn n'hêl nanê̆jêh ri tơ lah may dăn ma nau gĭt rbăng,$b$,false),
('bunong-vn','PRO',2,4,null,$b$tơ lah may joi păng nâm bu prăk, jêh ri tĭng păng nâm bu drăp ndơ bu pôn jêh.$b$,false),
('bunong-vn','PRO',2,5,null,$b$Nôk nây may gĭt rbăng nau klach yơk ma Yêhôva, jêh ri dơi saơ ntil nau blau mĭn Brah Ndu.$b$,true),
('bunong-vn','PRO',2,6,null,$b$Yor lah Yêhôva ăn nau blau mĭn, bơh bâr Păng tă luh nau blau mĭn jêh ri nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',2,7,null,$b$Păng prăp nau tâm rklaih ma bunuyh sŏng, Păng jêng khêl ma phung chuat tâm nau di.$b$,true),
('bunong-vn','PRO',2,8,null,$b$Păng n'gang trong phung sŏng, jêh ri mât mray trong phung kloh ueh Păng.$b$,true),
('bunong-vn','PRO',2,9,null,$b$Nôk nây may mra gĭt rbăng nau sŏng, nau di, nau n'hêl nanê̆ jêh ri lĕ rngôch trong ueh.$b$,true),
('bunong-vn','PRO',2,10,null,$b$Yor lah nau gĭt rbăng mra lăp tâm nuih n'hâm may, jêh ri huêng may mra sŏk nau blau mĭn mra ƀư maak huêng may.$b$,true),
('bunong-vn','PRO',2,11,null,$b$Nau blau sek uănh mra mât njrăng may, nau gĭt rbăng mra king may.$b$,true),
('bunong-vn','PRO',2,12,null,$b$Gay tâm rklaih may tă bơh trong mhĭk, tă bơh bunuyh ngơi nau kue.$b$,true),
('bunong-vn','PRO',2,13,null,$b$Phung nây cha lơi trong nau sŏng-srăng gay chuat tâm nau ngo klĕng.$b$,true),
('bunong-vn','PRO',2,14,null,$b$Khân păng nđơr ƀư nau mhĭk, khân păng hâk ma nau ƀai phung ƀai.$b$,true),
('bunong-vn','PRO',2,15,null,$b$Khân păng tĭng trong nau kue, jêh nây ƀư nau ngơi ndơm, jêh ri ƀư nhhơt trong khân păng nơm.$b$,true),
('bunong-vn','PRO',2,16,null,$b$Pô ri nau blau mĭn mra rklaih may bơh nau bu ur văng tĭr nơm joi ndơm may ma nau ngơi n'hi.$b$,true),
('bunong-vn','PRO',2,17,null,$b$Nơm cha lơi sai păng ơm geh jêh bơh păng hôm druh mom. Jêh ri chuêl nau tâm rnglăp đah Brah Ndu păng.$b$,true),
('bunong-vn','PRO',2,18,null,$b$Yor lah ngih păng rklĭng mpeh nau khĭt jêh ri trong păng njŭn tât ta ntŭk ƀon phung khĭt gŭ.$b$,true),
('bunong-vn','PRO',2,19,null,$b$Phung hăn ma păng mâu mâp plơ̆ sĭt ôh; mâu lĕ khân păng dơi tât ma trong nau rêh.$b$,true),
('bunong-vn','PRO',2,20,null,$b$Pô ri may blau mĭn mra chuat hăn tâm trong bunuyh ueh. Jêh ri tĭng trong phung sŏng.$b$,true),
('bunong-vn','PRO',2,21,null,$b$Yor lah phung sŏng mra dơi chăm bri, jêh ri phung mleh mra gŭ ta nây ƀa ƀơ.$b$,true),
('bunong-vn','PRO',2,22,null,$b$Ƀiă lah phung djơh mhĭk bu mra ƀư rai lơi bơh bri neh, jêh ri phung ƀlêp-ƀlêr bu mra mprơh lơi.$b$,true),
('bunong-vn','PRO',3,1,null,$b$Hơi kon, lơi ta chuêl ôh nau gâp ntĭm nti, ƀiă lah ăn nuih n'hâm may djôt prăp nau gâp ntăm.$b$,true),
('bunong-vn','PRO',3,2,null,$b$Yor lah nau gâp nti mra ntop ăn jŏ nar, năm may gŭ rêh jêh ri mra ăn may geh nau đăp mpăn.$b$,true),
('bunong-vn','PRO',3,3,null,$b$Lơi ta cha lơi ôh nau ueh jêh nau n'hêl nanê̆, kât nau nây ta trô ko may; chih nau nây tâm trôm nuih n'hâm may.$b$,true),
('bunong-vn','PRO',3,4,null,$b$Pô ri ta năp Brah Ndu jêh ri bunuyh, may dơi geh nau yô̆ an jêh ri nau blau mĭn ngăn.$b$,true),
('bunong-vn','PRO',3,5,null,$b$Rnơm hom ma Yêhôva ma lĕ nuih n'hâm jêh ri lơi nsing ôh tâm nau gĭt rbăng may nơm.$b$,true),
('bunong-vn','PRO',3,6,null,$b$Moh nau kan may ƀư kah gĭt hom ma Păng, jêh ri Păng leo ntĭm trong may.$b$,true),
('bunong-vn','PRO',3,7,null,$b$Lơi ta kơp may nơm blau mĭn ôh, klach yơk hom ma Yêhôva; jêh ri cha lơi hom bơh nau mhĭk.$b$,true),
('bunong-vn','PRO',3,8,null,$b$Nau nây mra ƀư bah sôt jreng klŏ may, jêh ri dơi sĭt suan ƀư nđik nting may,$b$,true),
('bunong-vn','PRO',3,9,null,$b$Tâm rnê hom ma Yêhôva ma drăp ndơ may, nhhơr ma păng lĕ ndơ dak bôk tâm mir may.$b$,false),
('bunong-vn','PRO',3,10,null,$b$Ri mơ jay ba may roch ma ba bêng ba rhiăng, jêh ri yăng may bêng ler dak n'heng dak play kriăk ƀâu.$b$,true),
('bunong-vn','PRO',3,11,null,$b$Hơi kon, lơi may tâm rmot ôh ma nau Yêhôva nkra jêh ri lơi ta rdja nuih ôh ma nau păng nduyh.$b$,true),
('bunong-vn','PRO',3,12,null,$b$Yor lah Yêhôva nkra ma mbu nơm păng rŏng. Nâm bu du huê mbơ̆ ƀư ma kon păng rŏng.$b$,true),
('bunong-vn','PRO',3,13,null,$b$Ueh maak ngăn ma bunuyh geh nau blau mĭn, jêh ri bunuyh geh nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',3,14,null,$b$Yor lah ueh lơn geh păng ma đah geh prăk rêl. Kao păng ueh lơn ma prăk, khlay lơn ma mah;$b$,true),
('bunong-vn','PRO',3,15,null,$b$Nau blau mĭn khlay lơn ma lŭ rsang, mâu geh du ntil may dơi rđĭl đah ndơ bu dơi ŭch.$b$,false),
('bunong-vn','PRO',3,16,null,$b$Tâm ti ma păng djôt nau jong rêh, tâm ti chiau păng djôt nau ndrŏng kuăng jêh ri nau chrêk rmah.$b$,true),
('bunong-vn','PRO',3,17,null,$b$Trong păng jêng trong ueh maak jêh ri lĕ rngôch trong nây jêng nau đăp mpăn.$b$,true),
('bunong-vn','PRO',3,18,null,$b$Păng jêng tơm si nau rêh ma phung joi păng; jêh ri mbu nơm djôt prăp păng dơi geh nau ueh lăng da dê.$b$,true),
('bunong-vn','PRO',3,19,null,$b$Ma nau blau mĭn Yêhôva njêng neh ntu; jêh ri ma nau gĭt rbăng păng dăp njêng phung mpa tâm trôk.$b$,true),
('bunong-vn','PRO',3,20,null,$b$Ma nau gĭt vât păng pơk trôm jru luh dak, jêh ri dơm tŭk ăn truh dak ngom.$b$,true),
('bunong-vn','PRO',3,21,null,$b$Hơi kon, djôt prăp nau blau âk jêh ri nau blau mĭn, lơi ăn păng trơn ngai ôh bơh ntŭk may.$b$,true),
('bunong-vn','PRO',3,22,null,$b$Pô ri khân păng mra jêng nau rêh ma huêng may jêh ri jêng ndơ nkrơ̆ văn trô ko may.$b$,true),
('bunong-vn','PRO',3,23,null,$b$Nôk nây may mra chuat hăn tâm trong may ma nau đăp rmên.$b$,true),
('bunong-vn','PRO',3,24,null,$b$Tơ lah may bêch, mâu mra geh ntil ndơ klach ôh. Ngăn yơh, may mra hăk bêch đăp mpăn.$b$,true),
('bunong-vn','PRO',3,25,null,$b$Lơi ta phit phơr ôh ma nau tât ndal, ăt may mâu krit klach lĕ dôl geh nau bu ƀư rai ma phung djơh mhĭk.$b$,true),
('bunong-vn','PRO',3,26,null,$b$Yor lah Yêhôva jêng ntŭk may nsing. Păng mra mât jâng may lơi ăn geh dăk.$b$,true),
('bunong-vn','PRO',3,27,null,$b$Lơi ta dun ôh ƀư nau ueh ma mbu nơm geh nau khư, tơ lah may dơn ƀư nau nây ma păng.$b$,true),
('bunong-vn','PRO',3,28,null,$b$Lơi ta lah ôh ma nơm chiau meng dăn ma may: “Hăn hom jêh ri plơ̆ tay đŏng, ôi taơ gâp mra ăn ma may.” Tơ lah may lĕ geh jêh ndơ ăn nây.$b$,true),
('bunong-vn','PRO',3,29,null,$b$Lơi tâm nchră ŭch ƀư mhĭk ma bunuyh chiau meng may ôh, yor păng gŭ ngao mơih rmên êp kêng may.$b$,true),
('bunong-vn','PRO',3,30,null,$b$Tơ lah bu mâu mâp ôh ƀư mhĭk đah may, lơi tâm rlăch đah bu mâu khlay ôh.$b$,true),
('bunong-vn','PRO',3,31,null,$b$Lơi ta ndăng ôh kơt nâm bu bu nuyh djơh mhĭk, jêh ri lơi tĭng ndô̆ trong păng ôh.$b$,true),
('bunong-vn','PRO',3,32,null,$b$Yor lah Yêhôva tâm rmot ngăn ma bunuyh kue, ƀiă lah lah păng njêng mĭt jiăng đah bunuyh sŏng srăng.$b$,true),
('bunong-vn','PRO',3,33,null,$b$Nau Yêhôva rtăp rak gŭ tâm ngih phung ƀai, ƀiă lah păng mât ton nau ueh uĭn ma ngih nơm sŏng.$b$,true),
('bunong-vn','PRO',3,34,null,$b$Nanê̆ păng mưch ma phung mưch; ƀiă lah păng yô̆ ma bunuyh dêh-rhêt.$b$,true),
('bunong-vn','PRO',3,35,null,$b$Bunuyh blau mĭn mra dơi dơn nau chrêk rmah; ƀiă lah phung bunuyh rluk mra geh nau prêng.$b$,true),
('bunong-vn','PRO',4,1,null,$b$Hơi phung kon bu klâu gâp, iăt hom nau ntĭm nti bơh du huê mbơ̆ , rkêng tôr gay ma khân may dơi geh nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',4,2,null,$b$Yor lah gâp ăn ma khân may du nau nti ueh ngăn; Lơi ta cha lơi ôh nau gâp nti.$b$,true),
('bunong-vn','PRO',4,3,null,$b$Dôl gâp jêng du huê kon bu klâu ma mbơ̆ gâp, knŏng êng du huê kon bu klâu, kon dul mê̆ gâp deh.$b$,true),
('bunong-vn','PRO',4,4,null,$b$Mbơ̆ gâp sâm nti gâp, lah: “Ăn nuih n'hâm may djôt nau gâp ngơi; tông hom ma nau gâp ntăm, ri mơ may mra rêh.$b$,true),
('bunong-vn','PRO',4,5,null,$b$Lơi ta chuêl jêh ri lơi teng ôh đah nau ngơi bơh bâr mbung gâp; sŏk dơn hom nau blau mĭn jêh ri nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',4,6,null,$b$Lơi ta cha lơi nau blau mĭn jêh ri păng mra chiă uănh may, rŏng hom ma păng, jêh ri păng mra king n'gang may.$b$,true),
('bunong-vn','PRO',4,7,null,$b$Nau blau mĭn jêng du ntil khlay lơn, pô ri, sŏk hom nau blau mĭn, dŏng hom ăn lĕ ndơ may hŏ geh gay rvăt hom nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',4,8,null,$b$Yơk ma nau blau mĭn jêh ri păng mra n'hao may, Păng mra yơk ma may, tơ lah may ut ra-u păng.$b$,true),
('bunong-vn','PRO',4,9,null,$b$Păng mra ndô ta klơ bôk may du mlâm rvang kao si nau yô̆. Păng mra rơm ăn may đon hađăch chrêk ma lơp.$b$,true),
('bunong-vn','PRO',4,10,null,$b$Hơi kon, iăt hom jêh ri sŏk dơn nau gâp ngơi gay ma năm, khay may gŭ rêh ntop âk lơn.$b$,true),
('bunong-vn','PRO',4,11,null,$b$Gâp hŏ nti jêh may tâm trong blau mĭn, njŭn leo may tâm trong sŏng srăng.$b$,true),
('bunong-vn','PRO',4,12,null,$b$Tơ lah may hăn, nhuat may chuat mâu lĕ may chêh prah.$b$,true),
('bunong-vn','PRO',4,13,null,$b$Djôt prăp nau ntĭm nti lơi ta cha lơi păng ôh, djôt prăp păng ăn nâp; yor lah păng jêng nau rêh may.$b$,true),
('bunong-vn','PRO',4,14,null,$b$Lơi ta lăp ôh trong phung ƀai, jêh ri lơi ta hăn trong phung mhĭk$b$,true),
('bunong-vn','PRO',4,15,null,$b$Du teng hom trong êng, lơi ta jot ôh ta nây. Der hom bơh nây jêh ri hăn trong sŏng$b$,false),
('bunong-vn','PRO',4,16,null,$b$Yor lah khân păng mâu dơi hăk bêch ôh, tơ lah khân păng mâu hŏ ƀư tih ôh; khân păng gŭ rngeh tơ lah khân păng ê hŏ ăn tŭp du huê bunuyh ƀư tih.$b$,false),
('bunong-vn','PRO',4,17,null,$b$Yor lah khân păng sa piăng let sŏk ma nau ƀai, jêh ri nhêt dak play kriăk ƀâu sŏk ma nau mhĭk.$b$,true),
('bunong-vn','PRO',4,18,null,$b$Ƀiă lah trong phung sŏng jêng nâm bu nchrang luh nar ơm ôi, nau ang păng jêng ktang lơn kŏ tât nchrat nar.$b$,true),
('bunong-vn','PRO',4,19,null,$b$Trong ma phung djơh mhĭk jêng nâm bu ngo klĕng. Khân păng mâu gĭt ôh moh ndơ khân păng geh chêh.$b$,true),
('bunong-vn','PRO',4,20,null,$b$Hơi kon, ăn may gơih hom iăt nau gâp ngơi, rkêng tôr iăt nau gâp lah.$b$,true),
('bunong-vn','PRO',4,21,null,$b$Lĕ nau ngơi nây lơi ăn păng du ngai bơh măt may ôh, djôt prăp păng tâm nuih n'hâm may.$b$,true),
('bunong-vn','PRO',4,22,null,$b$Yor lah păng jêng nau rêh ma phung saơ păng, jêh ri nau dăng ktang ma lĕ săk jăn khân păng.$b$,true),
('bunong-vn','PRO',4,23,null,$b$Njrăng hom ƀa ƀơ gay mât mray nuih n'hâm may ăn ueh ma lĕ ndơ êng yor lah tă bơh păng yơh luh tu nau rêh.$b$,true),
('bunong-vn','PRO',4,24,null,$b$Lơi hôm ngơi nau mƀruh ôh du ngai bơh nau ngơi plăch rlăm tâm bâr mbung.$b$,true),
('bunong-vn','PRO',4,25,null,$b$Ăn măt may uănh rlet pa năp jêh ri lơi ta uănh pa chiau pa ma ôh.$b$,true),
('bunong-vn','PRO',4,26,null,$b$Rli hom ăn lâng trong jâng may hăn pô ri mơ lĕ trong may hăn mra jêng nâp.$b$,true),
('bunong-vn','PRO',4,27,null,$b$Lơi teng pa chiau mâu lah pa ma ôh, Trơn hom jâng may bơh nau mhĭk.$b$,true),
('bunong-vn','PRO',5,1,null,$b$Hơi kon, gơih iăt n'hêl nanê̆ ma nau blau mĭn gâp, rkêng tôr iăt nau gâp gĭt rbăng,$b$,true),
('bunong-vn','PRO',5,2,null,$b$gay ma may dơi djôt prăp nau blau mĭn, jêh ri gay ma mbung may djôt prăp nau gĭt rbăng.$b$,false),
('bunong-vn','PRO',5,3,null,$b$Yor lah mbung bu ur văng tĭr kah nâm dak sŭt, jêh ri nau păng ngơi mbĭr lơn ma dak ngi.$b$,true),
('bunong-vn','PRO',5,4,null,$b$Ƀiă lah ta nglĕ dŭt jêng tăng ngăn, hơr lơn nâm bu mpiăt đao bar đah măt.$b$,true),
('bunong-vn','PRO',5,5,null,$b$Jâng păng trŭnh rlet ma ntŭk khĭt; nhuat păng hăn tĭng trong bri phan (Ƀon Phung Khĭt)$b$,true),
('bunong-vn','PRO',5,6,null,$b$Păng mâu ŭch joi ôh trong sâng hăn ma nau rêh; păng mblêng lĕ nhhơt trong jêh, ƀiă lah păng mâu hôm gĭt ôh.$b$,false),
('bunong-vn','PRO',5,7,null,$b$Pô ri aƀaơ, Hơi phung kon bu klâu gâp, iăt hom nau gâp; lơi ta cha lơi ôh lĕ nau ngơi bơh bâr mbung gâp.$b$,true),
('bunong-vn','PRO',5,8,null,$b$Du ngai tă bơh păng, jêh ri lơi hăn prot dăch mpông ngih păng ôh;$b$,true),
('bunong-vn','PRO',5,9,null,$b$Klach lah khân ay may ăn nau ktang ay may ma phung êng, jêh ri năm ay may gŭ rêh ăn ma nơm tŭn jot.$b$,false),
('bunong-vn','PRO',5,10,null,$b$Klach lah phung bunăch sŏk lơi drăp ndơ ay may, jêh ri n'hâm suan ay may pah kan sĭt ma ngih phung bunăch.$b$,true),
('bunong-vn','PRO',5,11,null,$b$Tât kêng dăch dŭt ay may mra nter, yor lah puăch jêh ri săk jăn khân păng djoh jêh.$b$,true),
('bunong-vn','PRO',5,12,null,$b$Jêh ri ay mâu lah: “Mâm dĭng gâp tâm rmot lơi ma nau bu ntĭm nti, jêh ri nuih n'hâm gâp dun lơi ma nau bu nduyh$b$,true),
('bunong-vn','PRO',5,13,null,$b$Mâm gâp mâu tông ôh bâr phung sâm nti ma gâp, mâu lĕ ŭch rkêng tôr iăt nau bunuyh ntĭm gâp?$b$,false),
('bunong-vn','PRO',5,14,null,$b$Ta nklang phung ƀon lan jêh ri phung tâm rƀŭn, gâp lĕ dăch roh jêh ŭch tŭp tâm nau tât jêr.$b$,true),
('bunong-vn','PRO',5,15,null,$b$Nhêt hom dak bât may jêh ri nhêt dak hoch luh bơh ndrâm ntu may.$b$,true),
('bunong-vn','PRO',5,16,null,$b$Di lĕ tu dak may mra hoch pa dih, jêh ri n'hor dak may hoch rŏ trong sâng?$b$,true),
('bunong-vn','PRO',5,17,null,$b$Prăp hom khân păng knŏng êng ma may nơm, jêh ri mâu di ma phung bunăch ndrel ma may ôh.$b$,true),
('bunong-vn','PRO',5,18,null,$b$Ăn tu dak may geh nau ueh uĭn, jêh ri hâk răm hom ndrel ur may nơm geh ntơm bơh druh ndăm.$b$,true),
('bunong-vn','PRO',5,19,null,$b$Nâm bu du mlâm jun me tâm rŏng, jêh ri du mlâm kon jun me ueh ngăn, pô nây lĕ toh păng ăn mpay ma may ƀa ƀơ jêh ri ăn may hâk răm ma nau păng rŏng mro mrăng.$b$,true),
('bunong-vn','PRO',5,20,null,$b$Hơi kon, yor lah moh nau khlay may rŏng ma bu ur văng tĭr, jêh ri ut ntang ntơh du huê bu ur blă blơ?$b$,true),
('bunong-vn','PRO',5,21,null,$b$Yor lah trong bunuyh hăn gŭ pa năp măt Yêhôva, jêh ri păng sek uănh lĕ rngôch trong khân păng.$b$,true),
('bunong-vn','PRO',5,22,null,$b$Nau kue phung tih ƀư jêng dăk sân ma păng, nau tih păng nơm mra chăp păng.$b$,true),
('bunong-vn','PRO',5,23,null,$b$Păng mra khĭt yor mâu geh nau ntĭm nti, păng mra roh yor nau rluk păng toyh ngăn.$b$,true),
('bunong-vn','PRO',6,1,null,$b$Hơi kon, tơ lah may ƀư nau dơn râng ma nơm chiau meng may, jêh ri may lĕ ƀư nau ton jêh ma bunuyh bunăch,$b$,true),
('bunong-vn','PRO',6,2,null,$b$Pô ri nau may ngơi kât rêt jêh may, bu nhŭp jêh may yor nau ngơi tă bơh bâr may.$b$,false),
('bunong-vn','PRO',6,3,null,$b$Hơi kon, yor lah may tŭp jêh tâm ti nơm chiau meng may. Pô ri ƀư hom nau aơ jêh ri tâm rklaih may nơm; hăn hom ma nau dêh nhêt, jêh ri vơl dăn ma păng mƀơk may.$b$,true),
('bunong-vn','PRO',6,4,null,$b$Lơi ăn măt may bêch ôh, mâu lah rsâng măt may mƀrêh mro.$b$,true),
('bunong-vn','PRO',6,5,null,$b$Tâm rklaih hom may nơm nâm bu yơng nsăt rlau klaih bơh ti bunuyh nchron, nâm bu sĭm klaih bơh ti bunuyh ndơm jêh.$b$,true),
('bunong-vn','PRO',6,6,null,$b$Hơi nơm ƀlao, hăn uănh hom phung ngonh, sam, mêt uănh nau gŭ ngao păng, gay nti nau blau mĭn.$b$,true),
('bunong-vn','PRO',6,7,null,$b$Nđâp tơ lah păng mâu geh kôranh ôh, mâu lĕ geh nơm chop mâu lah nơm nti.$b$,true),
('bunong-vn','PRO',6,8,null,$b$Ăt păng gĭt lĕ ndrăp rơm lơi mpa sa khân păng dôl yan ta vai, jêh ri nchuăn bun lơi ndơ sa păng dôl yan rek ba.$b$,true),
('bunong-vn','PRO',6,9,null,$b$Hơi bunuyh ƀlao, ndah nâm jŏ may gŭ bêch ta nĕ? Ndah nâm jŏ may kah rngăl bêch?$b$,true),
('bunong-vn','PRO',6,10,null,$b$Bêch ƀa lât, mƀrêh măt ƀât lât, ut ti lâng bêch ƀât lât.$b$,true),
('bunong-vn','PRO',6,11,null,$b$Pô ri nau o ach mra tât ma may nâm bu bunuyh ntŭng, jêh ri nau pah pât mra tât ma may nâm bu du huê djôt ndơ tâm lơh.$b$,true),
('bunong-vn','PRO',6,12,null,$b$Du huê bunuyh dơm dam, bunuyh kue, dăng ngơi nau kue mro mrăng.$b$,true),
('bunong-vn','PRO',6,13,null,$b$Păng ntơ̆ măt, dŏng nchêh ma jâng tâm ntĭt nau ŭch, jêh ri sŏk nglau ti păng gay tâm mpơl.$b$,true),
('bunong-vn','PRO',6,14,null,$b$Nuih n'hâm kue păng ŭch nchră ma nau mhĭk, joi nau tâm djrel ƀa ƀơ.$b$,true),
('bunong-vn','PRO',6,15,null,$b$Yor nây nau rêh ni mra tât ma păng ƀât lât dơm păng mra rai roh mâu hôm dơi bah ôh.$b$,true),
('bunong-vn','PRO',6,16,null,$b$Geh prao ntil Yêhôva tâm rmot, jêh ri pơh ntil păng ji nuih.$b$,true),
('bunong-vn','PRO',6,17,null,$b$Măt uănh ma nau sưr, mpiăt ngơi nau mƀruh, ti ƀư pling mham bunuyh mâu geh nau tih ôh.$b$,true),
('bunong-vn','PRO',6,18,null,$b$Nuih n'hâm ŭch nchră ma nau mhĭk, jâng gơnh nchuăt ran ma nau djơh.$b$,true),
('bunong-vn','PRO',6,19,null,$b$Nơm nkoch nau nchơt jêh ri ngơi nau mƀruh, ndrel nơm joi nau tâm lah tâm djrel ndrăng oh nâu.$b$,true),
('bunong-vn','PRO',6,20,null,$b$Hơi kon, djôt prăp hom nau mbơ̆ may ntăm, jêh ri lơi ta cha lơi ôh nau mê̆ may nti$b$,true),
('bunong-vn','PRO',6,21,null,$b$Prăp khân păng ƀa ƀơ tâm nuih n'hâm may, jêh ri văn khân păng ta trô ko may.$b$,false),
('bunong-vn','PRO',6,22,null,$b$Tơ lah may hăn, lĕ nau ngơi nây mra njŭn leo may; Dôl may bêch, păng chiă njrăng may; Jêh ri tơ lah may kah rngăl păng yơh mra nkoch bri đah may.$b$,true),
('bunong-vn','PRO',6,23,null,$b$Yor lah nau ntăm jêng ŭnh kađen, nau nti jêng nau ang, jêh ri nau nduyh gay ntĭm nti jêng trong hăn ma nau rêh.$b$,true),
('bunong-vn','PRO',6,24,null,$b$Gay king may bơh bu ur tih mhĭk jêh ri mpiăt bu ur văng tĭr ngơi njĭp.$b$,true),
('bunong-vn','PRO',6,25,null,$b$Tâm nuih n'hâm may lơi kơnh nau ueh păng, jêh ri lơi ăn rsâng măt păng ndơm may ôh.$b$,true),
('bunong-vn','PRO',6,26,null,$b$Yor tă bu ur văng tĭr dơi ăn hŭch lơi rnoh khlay du huê bu klâu hôm knŏng du glo piăng let dơm, bu ur văng tĭr ăt kâp ndơm huêng khlay.$b$,true),
('bunong-vn','PRO',6,27,null,$b$Dơi lĕ du huê bunuyh ăn ŭnh rnga ta ntang ntơh păng, ƀiă lah ao păng mâu dơi ŭnh sa ôh?$b$,true),
('bunong-vn','PRO',6,28,null,$b$Mâu lah dơi lĕ du huê bunuyh hăn jot ta klơ ŭnh rnga, jêh ri ŭnh mâu sa ôh jâng păng?$b$,true),
('bunong-vn','PRO',6,29,null,$b$Tâm ban pô nây lĕ mbu nơm gŭ ndrel ma ur phung chiau meng păng. Mbu nơm pah bi ô băl mâu mra klaih ôh đah nau tâm rmal.$b$,true),
('bunong-vn','PRO',6,30,null,$b$Bu mâu mra tâm rmot ôh ma du huê bunuyh ntŭng, tơ lah păng ntŭng gay ma hơm ndŭl păng dôl păng ji ngot.$b$,true),
('bunong-vn','PRO',6,31,null,$b$Jêh ri tơ lah bu ban nhŭp păng, păng mra trok pơh tơ̆ âk lơn, păng mra ăn lĕ ndơ păng geh tâm ngih.$b$,true),
('bunong-vn','PRO',6,32,null,$b$Mbu nơm văng tĭr đah du huê bu ur mâu geh nau gĭt mĭn ôh: Mbu nơm ƀư pô nây, ăn ma huêng păng geh nau rai yot.$b$,true),
('bunong-vn','PRO',6,33,null,$b$Bunuyh nây geh nau sôt jêh ri bêk prêng, mâu dơi jut ôh nau prêng păng.$b$,true),
('bunong-vn','PRO',6,34,null,$b$Yor lah nau nach jêng nau ji nuih ngăn ma du huê bu klâu. Tâm nar păng plơng bôk, păng mâu nhhuach ôh.$b$,true),
('bunong-vn','PRO',6,35,null,$b$Păng mâu mra dơn ôh drăp bu jan dôih, nđâp lah may ăn âk drăp ndơ ma păng ăt mâu dơi lĕ rthi nuih păng.$b$,true),
('bunong-vn','PRO',7,1,null,$b$Hơi kon, djôt prăp hom nau gâp ngơi jêh ri sŏk prăp tâm nuih n'hâm nau gâp ntăm.$b$,true),
('bunong-vn','PRO',7,2,null,$b$Tông hom nau gâp ntăm, jêh ri may mra gŭ rêh, sŏk prăp nau gâp ntăm jêng nâm bu găr măt may.$b$,true),
('bunong-vn','PRO',7,3,null,$b$Kât hom păng ta nglau ti may, chih prăp păng tâm trôm nuih n'hâm may.$b$,true),
('bunong-vn','PRO',7,4,null,$b$Lah hom ma nau blau mĭn: “Aơ jêng yuh gâp.” Bu ntơ nau gĭt rbăng jêng jiăng may.$b$,true),
('bunong-vn','PRO',7,5,null,$b$Gay ma khân păng nking may ma bu ur văng tĭr, ma bu ur blă blơ ngơi njĭp n'hĭr.$b$,true),
('bunong-vn','PRO',7,6,null,$b$Yor lah gâp gŭ ta mpông bloh ngih gâp, gâp gŭ n'gơr uănh bơh ntŭk nây.$b$,true),
('bunong-vn','PRO',7,7,null,$b$Gâp gŭ uănh ma phung rluk gâp saơ tâm phung mom ndăm, mâu geh ôh du huê ndăm geh nau blau mĭn;$b$,true),
('bunong-vn','PRO',7,8,null,$b$Păng nsong rŏ trong dăch ngih bu ur văng tĭr nây gŭ; păng đă hăn rlet ma ngih păng.$b$,false),
('bunong-vn','PRO',7,9,null,$b$Dôl ngo nsrŭp măng, tơ lah lĕ nhâp nar, mâu lah klong măng dôl ngo vêt-vê.$b$,true),
('bunong-vn','PRO',7,10,null,$b$Aơ, du huê bu ur tâm mâp đah păng, bu ur nây nkrơ̆ nâm bu du huê bu ur văng tĭr, nuih n'hâm bêng ma nau ndơm.$b$,true),
('bunong-vn','PRO',7,11,null,$b$Păng lĕ mơng ngơi nteh jêh ri mâu gĭt bêk ôh, păng mâu kơn gŭ tâm ngih vâl păng nơm ôh;$b$,true),
('bunong-vn','PRO',7,12,null,$b$geh tơ̆ gŭ tâm trong sâng, geh tơ̆ gŭ kâp bu tâm ăp njônh trong.$b$,false),
('bunong-vn','PRO',7,13,null,$b$Bu ur nây kuăn rdâng păng jêh ri chŭm păng, jêh ri păng janh lah ma bu klâu ndăm nây:$b$,true),
('bunong-vn','PRO',7,14,null,$b$“Gâp nhhơr jêh ndơ nhhơr nau đăp mpăn ta ngih gâp; nar aơ gâp trok lôch jêh rnoh gâp ton.$b$,false),
('bunong-vn','PRO',7,15,null,$b$Yor nau nây, gâp luh vơt chuă may gay joi may, gâp hŏ saơ jêh may?$b$,true),
('bunong-vn','PRO',7,16,null,$b$Gâp hŏ rơm ơm jêh, gâp lăk sưng bêch gâp ma phôi ueh ƀư đah brai mhay tă bơh bri Êjipt.$b$,true),
('bunong-vn','PRO',7,17,null,$b$Gâp djrah jêh sưng bêch gâp ma ndơ ƀâu kah, dak si tăng alôê, jêh ri ma Sinamon.$b$,true),
('bunong-vn','PRO',7,18,null,$b$Văch hom ăn he ƀư mpay he nơm ma nau rŏng ăn tât ang ôi; ăn he ƀư maak ma he nơm ma nau rŏng!$b$,true),
('bunong-vn','PRO',7,19,null,$b$Yor lah sai gâp mâu gŭ ôh gŭ tâm ngih, păng hăn nsong jêh ma ntŭk ngai.$b$,true),
('bunong-vn','PRO',7,20,null,$b$Păng ndjôt leo dŭng prăk ndrel ma păng, păng plơ̆ sĭt ma ngih tơ lah bŏng khay.$b$,true),
('bunong-vn','PRO',7,21,null,$b$Păng ngơi ndơm ô băl đah âk nau ngơi ueh, ma nau ngơi njĭp n'hĭr păng nchâp ô băl.$b$,true),
('bunong-vn','PRO',7,22,null,$b$Gơnh ro ô băl tĭng ndô̆ păng, nâm bu ndrôk hăn leo ntŭk bu gŭch, nâm bu du huê bunuyh rluk bu nkông hăn ma nau tâm rmal;$b$,true),
('bunong-vn','PRO',7,23,null,$b$tât du tong hăr sŏr ta klơm păng, nâm bu sĭm geh nhuăl; păng mâu gĭt ôh nau nây mra roh nau rêh păng.$b$,false),
('bunong-vn','PRO',7,24,null,$b$Pô ri aƀaơ, Hơi phung kon, iăt hom nau gâp jêh ri rkêng tôr ma nau gâp ngơi;$b$,true),
('bunong-vn','PRO',7,25,null,$b$lơi ăn nuih n'hâm may tĭng ôh trong du huê bu ur kơt nây; lơi hăn vĭ tâm trong păng.$b$,false),
('bunong-vn','PRO',7,26,null,$b$Yor lah păng hŏ nsŭk âk jêh bunuyh, tŭp tâm nau ndơm jêh ri âk ngăn phung păng hŏ nkhĭt.$b$,true),
('bunong-vn','PRO',7,27,null,$b$Ngih păng jêng trong hăn ma ƀon khĭt, njŭr leo tâm jrô nau khĭt.$b$,true),
('bunong-vn','PRO',8,1,null,$b$Mâu di hĕ nau blau mĭn gŭ kuăl. Mâu di hĕ nau blau mĭn ngơi nteh?$b$,true),
('bunong-vn','PRO',8,2,null,$b$Nau blau mĭn dâk ta klơ yôk prêh, ta meng trong păng gŭ nđâp ta rdjŭm trong.$b$,true),
('bunong-vn','PRO',8,3,null,$b$Ta meng êp mpông sâng, ta ntŭk lăp ƀon toyh, ta ntŭk gum bunuyh âk ta mpông ƀon toyh, nau blau mĭn nter lah:$b$,true),
('bunong-vn','PRO',8,4,null,$b$“Hơi kon bunuyh, ma khân may yơh gâp kuăl dat aơ, jêh ri bâr gâp rle ma phung kon bunuyh!$b$,false),
('bunong-vn','PRO',8,5,null,$b$Hơi phung rluk, ăn khân may nti nau blau mĭn: Hơi phung rluk nuih n'hâm khân may ăn dơi jêng blau ngăn.$b$,true),
('bunong-vn','PRO',8,6,null,$b$Iăt hom, yor lah gâp mra ngơi nau khlay, mbung gâp mra ngơi nau di.$b$,true),
('bunong-vn','PRO',8,7,null,$b$Yor lah bâr mbung gâp mra mbơh nau n'hêl nanê̆jêh ri mbung gâp tâm rmot ma nau ngơi mƀruh.$b$,true),
('bunong-vn','PRO',8,8,null,$b$Lĕ rngôch nau ngơi bơh bâr mbung gâp jêng sŏng, păng mâu geh nau kue mâu lah vĭ ôh.$b$,true),
('bunong-vn','PRO',8,9,null,$b$Lĕ rngôch nau ngơi nây jêng sŏng ma nơm gĭt vât, jêh ri di ma phung geh jêh ma nau blau mĭn.$b$,true),
('bunong-vn','PRO',8,10,null,$b$Săch hom nau gâp nti âk lơn ma prăk, jêh ri nau gĭt rbăng âk lơn ma mah khlay.$b$,true),
