('bunong-vn','PRO',8,12,null,$b$Gâp yơh, nau blau mĭn gŭ ndrel ma nau gĭt rbăng âk jêh ri gâp geh nau gĭt vât jêh ri nau sek uănh.$b$,true),
('bunong-vn','PRO',8,13,null,$b$Nau klach yơk ma Yêhôva jêng nau tâm rmot đah nau mhĭk, gâp tâm rmot đah nau sưr, nau n'hao êng nơm; trong nau ngơi mhĭk jêh ri nau ngơi kue.$b$,true),
('bunong-vn','PRO',8,14,null,$b$Gâp gĭt mplăch jêh ri nau gĭt mĭn, gâp geh nau gĭt rbăng jêh ri nau ktang.$b$,true),
('bunong-vn','PRO',8,15,null,$b$Tă bơh gâp, phung hađăch blau chiă uănh. Jêh ri phung kôranh chiă uănh ŭch mĭn nau sŏng.$b$,true),
('bunong-vn','PRO',8,16,null,$b$Tă bơh gâp, lĕ phung kôranh blau chiă uănh jêh ri phung toyh chiă uănh neh ntu.$b$,true),
('bunong-vn','PRO',8,17,null,$b$Gâp rŏng ma phung rŏng ma gâp, jêh ri mbu nâm tĭng joi gâp mra mâp gâp.$b$,true),
('bunong-vn','PRO',8,18,null,$b$Nau ndrŏng kuăng, nau bu yơk, drăp ndơ jŏ nâp jêh ri nau sŏng, gŭ ta ntŭk gâp da dê.$b$,true),
('bunong-vn','PRO',8,19,null,$b$Play gâp jêng ueh lơn ma mah, rlau lơn ma mah khlay; jêh ri kao gâp khlay rlau lơn prăk chrêk.$b$,true),
('bunong-vn','PRO',8,20,null,$b$Gâp hăn tâm trong nau sŏng; ta nklang trong di,$b$,true),
('bunong-vn','PRO',8,21,null,$b$gay ăn ndrŏng phung rŏng ma gâp, sŏk dơn drăp ndơ ngăn, jêh ri ăn bêng roch jay drăp ndơ khân păng.$b$,false),
('bunong-vn','PRO',8,22,null,$b$Yêhôva rhăk njêng gâp lor lơn, kan ntơm sa ơm păng ƀư kăl e.$b$,true),
('bunong-vn','PRO',8,23,null,$b$Bu njêng jêh gâp bơh rnôk kăl e, ntơm bơh geh neh ntu.$b$,true),
('bunong-vn','PRO',8,24,null,$b$Bu njêng gâp dôl ê geh brŏng jru, rnôk ê geh ôh tu dak hoch gâp hŏ geh jêh.$b$,true),
('bunong-vn','PRO',8,25,null,$b$Ê lor bu rhăk yôk, jêh ri ê lor geh gôl bu njêng jêh gâp.$b$,true),
('bunong-vn','PRO',8,26,null,$b$Ê lor ma Yêhôva rhăk njêng neh ntu ndrel ma mir jêh ri ê lor geh ndruyh neh; gâp hŏ jêh.$b$,true),
('bunong-vn','PRO',8,27,null,$b$Tơ lah Brah Ndu rhăk tâm trôk jêh ri păng lăk rvang trôk ta klơ brŏng jru, gâp lĕ gŭ ta nĕ jêh.$b$,true),
('bunong-vn','PRO',8,28,null,$b$Tơ lah păng ƀư nâp ndâr tŭk klơ trôk jêh ri păng ƀư tu dak jru nâp ngăn.$b$,true),
('bunong-vn','PRO',8,29,null,$b$Păng tâm nal n'har dak mƀŭt, gay ma dak mâu băm rlau ir ma păng hŏ veh jêh, jêh ri tơ lah păng hŏ njêng jêh rplay neh;$b$,true),
('bunong-vn','PRO',8,30,null,$b$rnôk nây gâp gŭ êp kêng meng ndrel ma păng njêng du huê nơm njêh, jêh ri ăp nar gâp ƀư maak ma păng hâk răm ƀa ƀơ ta năp păng$b$,false),
('bunong-vn','PRO',8,31,null,$b$gŭ maak ta klơ neh ntu păng,$b$,false),
('bunong-vn','PRO',8,32,null,$b$jêh ri geh nau maak ma phung kon bu klâu gâp! Ueh maak ngăn ma phung djôt prăp nau chroh gâp.$b$,false),
('bunong-vn','PRO',8,33,null,$b$Gŭ iăt hom nau gâp nti jêh ri jêng bunuyh blau mĭn, lơi ta cha lơi păng ôh.$b$,true),
('bunong-vn','PRO',8,34,null,$b$Ueh maak ngăn bunuyh gŭ iăt gâp, gŭ rngeh ăp nar ta mpông pêr gâp; jêh ri gŭ kâp ta bôk mpông gâp.$b$,true),
('bunong-vn','PRO',8,35,null,$b$Yor lah mbu nâm joi gâp mra mâp nau rêh, geh nau yô̆ bơh Yêhôva.$b$,true),
