('bunong-vn','PRO',9,1,null,$b$Nau blau mĭn hŏ ndâk jêh ngih păng; păng trah jêh pơh mlâm meh păng.$b$,true),
('bunong-vn','PRO',9,2,null,$b$Păng nkhĭt jêh mpô mpa păng, tâm pot đah dak play kriăk ƀâu păng, jêh ri ndrăp jêh sưng sông păng.$b$,true),
('bunong-vn','PRO',9,3,null,$b$Păng prơh hăn jêh oh mon bu ur păng, păng nter tă bơh ntŭk prêh ta klơ lơn tâm ƀon toyh.$b$,true),
('bunong-vn','PRO',9,4,null,$b$“Mbu nâm rluk ăn păng lăp ta nây!” Pô ri păng lah ma phung mâu geh nau gĭt vât, nau gĭt rbăng lah:$b$,true),
('bunong-vn','PRO',9,5,null,$b$“Văch hom, sa piăng let gâp jêh ri nhêt dak play kriăk ƀâu gâp hŏ tâm pot jêh.$b$,false),
('bunong-vn','PRO',9,6,null,$b$Cha lơi hom nau rluk, jêh ri mra dơi rêh; hăn hom tĭng trong nau gĭt rbăng.”$b$,true),
('bunong-vn','PRO',9,7,null,$b$Mbu nơm nkra bunuyh dăng mưch mra sŏk dơn nau mhĭk ma păng nơm, jêh ri mbu nơm nduyh bunuyh brơl (ƀai) mra sŏk dơn nau sôt.$b$,true),
('bunong-vn','PRO',9,8,null,$b$Lơi ta nduyh ôh ma bunuyh dăng mưch, klach lah păng tâm rmot ma may; nduyh ma bunuyh blau mĭn jêh ri păng mra rŏng ma may.$b$,true),
('bunong-vn','PRO',9,9,null,$b$Sâm nti ma bunuyh blau mĭn, jêh ri păng mra blau mĭn lơn, sâm nti ma du huê bunuyh sŏng, păng mra gĭt âk lơn.$b$,true),
('bunong-vn','PRO',9,10,null,$b$Nau klach yơh ma Yêhôva jêng tơm ma nau blau mĭn jêh ri gĭt năl Nơm Kloh Ueh Jêng nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',9,11,null,$b$Yor lah ma gâp yơh may mra gŭ rêh jŏ lơn, jêh ri bu mra ntop tay năm may gŭ rêh.$b$,true),
('bunong-vn','PRO',9,12,null,$b$Tơ lah may blau mĭn jêng khlay ma may nơm, tơ lah may dăng mưch; êng may nơm mra anh lĕ nau nây.$b$,true),
('bunong-vn','PRO',9,13,null,$b$Du huê bu ur rluk jêng rsĭk dăng ngơi, jêh ri mâu gĭt ôh moh nau.$b$,true),
('bunong-vn','PRO',9,14,null,$b$Bu ur nây gŭ ta bôk mpông ngih păng, păng gŭ tâm ntŭk prêh lơn tâm ƀon,$b$,true),
('bunong-vn','PRO',9,15,null,$b$gay kuăl ma phung prot găn hăn rŏ trong khân păng jêh ri lah:$b$,false),
('bunong-vn','PRO',9,16,null,$b$“Ăn mbu moh rluk lăp ta aơ.” Păng lah ma nơm mâu geh nau mĭn pô aơ:$b$,false),
('bunong-vn','PRO',9,17,null,$b$“Dak bu ntŭng jêng dak njŭng; jêh ri sa ndơ ma nau ndâp jêng kah ngăn.$b$,false),
('bunong-vn','PRO',9,18,null,$b$Ƀiă lah khân păng mâu gĭt ôh phung khĭt gŭ ta nây jêh ri phung bu năch bu ur nây jă gŭ ta ntŭk jru lơn tâm Ƀon Phung Khĭt.$b$,true),
('bunong-vn','PRO',10,1,null,$b$Du huê bu klâu blau mĭn ƀư maak ma mbơ̆ păng; ƀiă lah du huê kon bu klâu rluk ƀư rngot ma mê̆ păng.$b$,true),
('bunong-vn','PRO',10,2,null,$b$Drăp ndơ bu geh ma nau ƀư djơh mâu jêng khlay ôh, ƀiă lah nau sŏng srăng tâm rklaih bơh nau khĭt.$b$,true),
('bunong-vn','PRO',10,3,null,$b$Yêhôva mâu ăn ôh huêng phung sŏng ât ji ngot; ƀiă lah păng mprơh lơi nau phung djơh ŭch kơnh.$b$,true),
('bunong-vn','PRO',10,4,null,$b$Mbu nơm ƀlao pah kan jêng nau o-ach păng nơm; ƀiă lah ti nơm gơih jêng ndrŏng.$b$,true),
('bunong-vn','PRO',10,5,null,$b$Du huê kon bu klâu prăp bun dôl yan vai jêng blau mĭn; ƀiă lah du huê kon bu klâu bêch dôl yan kăch ăn nau bêk prêng.$b$,true),
('bunong-vn','PRO',10,6,null,$b$Geh nau ueh uĭn ta klơ bôk bunuyh sŏng, ƀiă lah bâr mbung phung ƀai pôn nau mhĭk.$b$,true),
('bunong-vn','PRO',10,7,null,$b$Nau kah gĭt ndray ma bunuyh sŏng geh nau tâm rnê; ƀiă lah amoh phung tih mra ôm.$b$,true),
('bunong-vn','PRO',10,8,null,$b$Bunuyh geh nuih n'hâm blau mĭn mra sŏk dơn nau vay, ƀiă lah mbung nơm ngai rluk mra cha lôt.$b$,true),
('bunong-vn','PRO',10,9,null,$b$Mbu nơm chuat tâm nau sŏng srăng hăn ma nau đăp mpăn; ƀiă lah ma nơm chuat tâm trong kue bu mra tâm rmal.$b$,true),
('bunong-vn','PRO',10,10,null,$b$Mbu nơm ntơ̆ măt ƀư ăn nau uh ah, jêh ri ma nơm geh bâr mbung dăng ngơi rluk mra cha lôt.$b$,true),
('bunong-vn','PRO',10,11,null,$b$Bâr mbung bunuyh sŏng jêng tu ma nau rêh; ƀiă lah bâr mbung phung ƀai pôn lơi nau mhĭk.$b$,true),
('bunong-vn','PRO',10,12,null,$b$Nau tâm rmot nsônh ma nau tâm djrel; ƀiă lah nau rŏng nkŭm lĕ nau tih.$b$,true),
('bunong-vn','PRO',10,13,null,$b$Bunuyh gĭt rbăng ngơi nau blau mĭn; ƀiă lah nơm mâu geh nau gĭt rbăng bu mra prăp đah mâng.$b$,true),
('bunong-vn','PRO',10,14,null,$b$Phung blau mĭn prăp nkrem nau gĭt rbăng âk; ƀiă lah nau bunuyh rluk ngơi ăn nau ƀư rai văch tât.$b$,true),
('bunong-vn','PRO',10,15,null,$b$Drăp ndơ bunuyh ndrŏng jêng nâm bu ƀon toyh dŭt nâp ma păng, ƀiă lah nau ƀư rai ma bunuyh rêh ni njêng nau o ach ma khân păng.$b$,true),
('bunong-vn','PRO',10,16,null,$b$Rnoh nkhôm ma bunuyh sŏng njŭn leo ma nau rêh; rnoh nkhôm ma bunuyh mhĭk njŭn leo ma nau tâm rmal.$b$,true),
('bunong-vn','PRO',10,17,null,$b$Mbu nơm dơn nau bu sâm nti gŭ tâm trong nau rêh; ƀiă lah mbu nơm chuêl ma nau bu nkra mra vĭ-nhhơt.$b$,true),
('bunong-vn','PRO',10,18,null,$b$Bunuyh pôn mo nau ji nuih geh trôm mbung mƀruh; jêh ri mbu nơm ngơi nchơt jêng du huê bunuyh rluk.$b$,true),
('bunong-vn','PRO',10,19,null,$b$Tâm nau ngơi âk, nơih ngăn geh nau tih; ƀiă lah nơm blau njrăng ma mpiăt păng jêng nau blau mĭn.$b$,true),
('bunong-vn','PRO',10,20,null,$b$Mpiăt bunuyh sŏng jêng nâm bu prăk khlay, nuih n'hâm phung ƀai jêng mâu khlay ôh.$b$,true),
('bunong-vn','PRO',10,21,null,$b$Mpiăt bunuyh sŏng siăm âk bunuyh, ƀiă lah phung rluk mra khĭt yor mâu geh nau gĭt vât.$b$,true),
('bunong-vn','PRO',10,22,null,$b$Nau ueh uĭn Yêhôva ăn ndrŏng bunuyh, jêh ri păng mâu hôm ntop nau rngot ôh.$b$,true),
('bunong-vn','PRO',10,23,null,$b$Du huê nơm rluk kơp nau ƀư tih jêng nau pâl; ƀiă lah bunuyh gĭt rbăng ŭch ma nau blau mĭn.$b$,true),
('bunong-vn','PRO',10,24,null,$b$Moh ntil ndơ phung ƀai klach, nanê̆ nau nây mra tât ma păng; ƀiă lah phung sŏng mra dơi geh tĭng nâm păng ŭch.$b$,true),
('bunong-vn','PRO',10,25,null,$b$Tơ lah phŭt chuănh lĕ lăn jêh, mâu hôm geh phung ƀai ôh. Ƀiă lah phung sŏng gŭ nâp n'ho ro.$b$,true),
('bunong-vn','PRO',10,26,null,$b$Nâm bu dak srat ƀư kĭr sêk, nâm bu nhhŭk ŭnh ƀư ji sa măt, kơt nây lĕ bunuyh ƀlao njêng đah nơm prơh păng hăn.$b$,true),
('bunong-vn','PRO',10,27,null,$b$Nau klach yơk ma Yêhôva ntop jŏ nar khay ma bu gŭ rêh. Ƀiă lah năm ma phung mhĭk gŭ rêh mra n'hŭch lơi ăn ƀhôi.$b$,true),
('bunong-vn','PRO',10,28,null,$b$Nau phung sŏng gŭ kâp gân mra tât nau hâk răm, ƀiă lah nau kâp gân ma phung mhĭk mra rai yot.$b$,true),
('bunong-vn','PRO',10,29,null,$b$Trong Yêhôva nâm bu mpêr ma phung sŏng; ƀiă lah păng jêng nơm ƀư rai ma nau phung ƀư mhĭk.$b$,true),
('bunong-vn','PRO',10,30,null,$b$Phung sŏng mâu mra n'gơ ôh; ƀiă lah phung mhĭk mâu mra gŭ chăm bri ôh.$b$,true),
('bunong-vn','PRO',10,31,null,$b$Bâr mbung bunuyh sŏng deh nau blau mĭn; ƀiă lah mpiăt phung kue bu mra koh lơi.$b$,true),
('bunong-vn','PRO',10,32,null,$b$Mpiăt bunuyh sŏng blau ngơi maak; ƀiă lah bâr mbung phung mhĭk ngơi kue.$b$,true),
('bunong-vn','PRO',11,1,null,$b$Yêhôva rmot ngăn ma njing veh tih; ƀiă lah păng maak ma njing veh di.$b$,true),
('bunong-vn','PRO',11,2,null,$b$Tơ lah nau sưr tât, nau prêng tât lĕ; ƀiă lah nau blau mĭn gŭ ndrel ma phung gŭ dêh rhêt$b$,true),
('bunong-vn','PRO',11,3,null,$b$Nau mơih rmên phung sŏng têk ndrêng khân păng; ƀiă lah nau plăch rlăm phung ƀlêp- ƀlêr ƀư rai khân păng nơm.$b$,false),
('bunong-vn','PRO',11,4,null,$b$Drăp ndơ mâu khlay ôh ta nar nau ji nuih tât; ƀiă lah nau sŏng tâm rklaih bu bơh nau khĭt.$b$,true),
('bunong-vn','PRO',11,5,null,$b$Nau sŏng ma bunuyh răp jăp mra ƀư lâng trong păng; ƀiă lah bunuyh ƀai mra cha lôt yor nau ƀai păng.$b$,true),
('bunong-vn','PRO',11,6,null,$b$Nau sŏng srăng ma phung sŏng mra tâm rklaih khân păng, ƀiă lah phung ƀlêp ƀlêr mra djang tâm nau djơh mhĭk-khân păng nơm.$b$,true),
('bunong-vn','PRO',11,7,null,$b$Tơ lah bunuyh ƀai khĭt, nau păng kâp gân rai lôch; jêh ri nau bunuyh kue gŭ kâp mâu yŏng tât ôh.$b$,true),
('bunong-vn','PRO',11,8,null,$b$Bu tâm rklaih bunuyh sŏng bơh nau rŭng răng; ƀiă lah nau rŭng răng nây ma bunuyh ƀai.$b$,true),
('bunong-vn','PRO',11,9,null,$b$Du huê bunuyh ƀai sŏk nau ngơi ŭch ƀư rai phung chiau meng păng, bi ma bunuyh sŏng sŏk nau blau mĭn dơi tâm rklaih.$b$,true),
('bunong-vn','PRO',11,10,null,$b$Lĕ rngôch ƀon toyh gŭ răm maak tơ lah phung sŏng geh nau ueh uĭn. Jêh ri tơ lah phung ƀai rai lôch, bu troh rhơn.$b$,true),
('bunong-vn','PRO',11,11,null,$b$Ma nau ueh uĭn phung sŏng, ƀon geh nau hao; ƀiă lah yor mbung phung ƀai ngơi bu n'glưh lơi păng.$b$,true),
('bunong-vn','PRO',11,12,null,$b$Nơm mưch ma phung chiau meng păng mâu geh nau gĭt vât ôh; ƀiă lah bunuyh gĭt rbăng gŭ rklăk.$b$,true),
('bunong-vn','PRO',11,13,null,$b$Nơm dăng nkoch bri tâm mpơl nau ndâp bu; ƀiă lah mbu nơm geh nuih n'hâm răp jăp djôt prăp ndâp nau kan.$b$,true),
('bunong-vn','PRO',11,14,null,$b$Phung ƀon lan tŭp yor mâu tông nau ƀĭt gai, ƀiă lah yor geh âk phung nchră păng dơi geh gŭ nau nây;$b$,true),
('bunong-vn','PRO',11,15,null,$b$Mbu nơm dơn râng ma phung pa dih mra mâp nau mhĭk. Ƀiă lah mbu tâm rmot nau dơn râng nây geh nau đăp mpăn ngăn.$b$,false),
('bunong-vn','PRO',11,16,null,$b$Bu mra yơk ma bu ur geh nau blau yô̆jêh ri phung bu klâu janh ƀai dơi geh drăp ndơ.$b$,true),
('bunong-vn','PRO',11,17,null,$b$Bunuyh blau yô̆ ƀư ueh ma huêng păng nơm; bi ma bunuyh janh ƀư rêh ni ma nglay săk păng.$b$,true),
('bunong-vn','PRO',11,18,null,$b$Bunuyh ƀai sa rnoh ma nau ndơm, ƀiă lah mbu nơm ƀư nau sŏng srăng mra geh nau nkhôm n'hêl nanê̆ ngăn.$b$,true),
('bunong-vn','PRO',11,19,null,$b$Mbu nơm gŭ nâp tâm nau sŏng srăng mra dơi geh nau rêh, ƀiă lah mbu nơm joi nau ƀai ăn nau mhĭk ma păng nơm.$b$,true),
('bunong-vn','PRO',11,20,null,$b$Yêhôva tâm rmot ngăn phung geh nau mĭn kue. Ƀiă lah phung mâu geh tih ôh ƀư maak ma păng.$b$,true),
('bunong-vn','PRO',11,21,null,$b$Ăn ay may gĭt nanê̆ ma bunuyh tih mhĭk mâu mra klaih ôh đah nau tâm rmal; ƀiă lah noi deh phung sŏng mra klaih.$b$,true),
('bunong-vn','PRO',11,22,null,$b$Du huê bu ur ueh ƀiă lah mâu geh ôh nau gĭt mĭn. Nâm bu pô nây lĕ du mlâm kông mah ta trô muh sŭr.$b$,true),
('bunong-vn','PRO',11,23,null,$b$Nau phung sŏng ŭch tât knŏng nau ueh, ntil phung ƀai gŭ kâp nây jêng nau ji nuih$b$,true),
('bunong-vn','PRO',11,24,null,$b$Du huê bunuyh ăn ndơ ma nau lŏng, lơ ntop geh âk lơn đŏng. Geh du huê bunuyh êng tâm ban lĕ dŭt nhhuach mbeh, ăt hôm pah pât.$b$,false),
('bunong-vn','PRO',11,25,null,$b$Nuih n'hâm lŏng mra dơi geh nau hơm răm; jêh ri mbu nơm kơl bu, bu mra kơl păng tâm ban lĕ.$b$,true),
('bunong-vn','PRO',11,26,null,$b$Mbu moh prăp đem ba ma păng nơm geh nau ƀon lan rak rtăp ma păng, bi ma nơm tăch lơi mra geh nau ƀun lap.$b$,true),
('bunong-vn','PRO',11,27,null,$b$Mbu moh nsrôih joi nau ueh, tĭng joi nau yô̆, ƀiă lah mbu tĭng joi nau mhĭk, nau mhĭk mra tât ma păng.$b$,true),
('bunong-vn','PRO',11,28,null,$b$Mbu nơm nsing ma drăp ndơ păng nơm mra tŭp; ƀiă lah phung sŏng mra chăt nse nâm bu n'ha si ndrêh.$b$,true),
('bunong-vn','PRO',11,29,null,$b$Mbu nơm ƀư rŭng rnăk vâl păng nơm, mra dơn sial jêng ndơ păng jêh ri bunuyh rluk mra jêng dĭk ma bunuyh blau mĭn.$b$,true),
('bunong-vn','PRO',11,30,null,$b$Play bunuyh sŏng jêng tâm ban ma tơm si nau rêh. Bi ma nơm blau njŭn leo huêng bunuyh blau mĭn.$b$,true),
('bunong-vn','PRO',11,31,null,$b$Bunuyh sŏng tơ lah dơi mplơ̆ lah nau di ma bunuyh ta neh ntu, rlau lơn ma nây mra plơ̆ lah nau di ma nơm ƀai jêh ri nơm tih.$b$,true),
('bunong-vn','PRO',12,1,null,$b$Mbu nơm rŏng ma nau bu nkra rŏng ma nau blau mĭn âk, ƀiă lah mbu nơm tâm rmot ma nau bu nduyh jêng rluk mâl yơh.$b$,true),
('bunong-vn','PRO',12,2,null,$b$Bunuyh ueh sŏng dơn nau yô̆ bơh Yêhôva, ƀiă lah Yêhôva tâm rmal nơm ƀư nau kue.$b$,true),
('bunong-vn','PRO',12,3,null,$b$Kon bunuyh mâu jêng nâp ôh yor nau djơh mhĭk, ƀiă lah reh phung sŏng bu mâu mra rôk ôh.$b$,true),
('bunong-vn','PRO',12,4,null,$b$Du huê bu ur geh nau ueh jêng nâm bu đon hađăch ma sai păng; bi ma ur ƀư nau bêk prêng jêng tâm ban ma ƀư rmŭk nting păng.$b$,true),
('bunong-vn','PRO',12,5,null,$b$Mbor kan phung sŏng jêng di, nau phung ƀai ntĭm knŏng ŭch ndơm.$b$,true),
('bunong-vn','PRO',12,6,null,$b$Nau phung ƀai ngơi kâp ƀư pling mham, ƀiă lah bâr phung sŏng tâm rklaih bunuyh.$b$,true),
('bunong-vn','PRO',12,7,null,$b$Bu n'glưh phung ƀai jêh ri mâu hôm geh khân păng ôh; ƀiă lah ngih phung sŏng mra gŭ nâp.$b$,true),
('bunong-vn','PRO',12,8,null,$b$Mbu nơm geh nau blau mĭn bu mra tâm rnê, ƀiă lah lah mbu nơm geh nuih n'hâm kue bu mra tâm rmot.$b$,true),
('bunong-vn','PRO',12,9,null,$b$Ueh lơn geh nau dêh rhêt jêh ri geh oh mon ma nau n'hi săk nơm jêng du huê nơm toyh jêh ri pưt mpa sông sa.$b$,true),
('bunong-vn','PRO',12,10,null,$b$Bunuyh sŏng mât mray mpô mpa păng rong; bi ma nuih n'hâm yô̆ tă bơh phung mhĭk ăt jêng tâm ban nau ƀư mhĭk lĕ.$b$,true),
('bunong-vn','PRO',12,11,null,$b$Mbu nơm pah kan tâm mir păng mra geh ndơ sông sa, bi ma nơm tĭng bunuyh ƀlao mâu geh nau gĭt rbăng ôh.$b$,true),
('bunong-vn','PRO',12,12,null,$b$Phung mhĭk hưp ma ndơ ndơm, tă phung djơh mhĭk, ƀiă lah reh phung sŏng mra geh play âk.$b$,true),
('bunong-vn','PRO',12,13,null,$b$Du huê bunuyh ƀai geh dăk păng nơm sân ma nau păng ngơi tih, bi phung sŏng klaih lĕ nau tât.$b$,true),
('bunong-vn','PRO',12,14,null,$b$Play bơh bâr mbung păng bu geh nau nkhôm ueh tĭng nâm nau păng ngơi, jêh ri ăp nơm sŏk dơn tĭng nâm kan ti păng ƀư.$b$,true),
('bunong-vn','PRO',12,15,null,$b$Bunuyh rluk kơp trong păng nơm jêng sŏng, bi bunuyh blau mĭn kâp iăt bu ntĭm nti.$b$,true),
('bunong-vn','PRO',12,16,null,$b$Du huê bunuyh rluk mpơl ro nau păng ji nuih, ƀiă lah bunuyh blau mĭn păng mâu ji ôh ma nau bu suai rak.$b$,true),
('bunong-vn','PRO',12,17,null,$b$Bunuyh ngơi ngăn mbơh nkoch nau sŏng, ƀiă lah bunuyh ngơi nau mƀruh nkoch bri nau ndơm.$b$,true),
('bunong-vn','PRO',12,18,null,$b$Nau bunuyh ngơi mâu njrăng ôh jêng nau bu ntâp ma đao, bi mpiăt phung gĭt mĭn jêng dak si blau ƀư bah.$b$,true),
('bunong-vn','PRO',12,19,null,$b$Mpiăt ngơi nau n'hêl na nê̆ gŭ nâp n'ho ro; ƀiă lah mpiăt ngơi mƀruh gŭ knŏng ƀât lât dơm.$b$,true),
('bunong-vn','PRO',12,20,null,$b$Nau ndơm gŭ tâm nuih n'hâm phung tâm chră ma nau mhĭk, ƀiă lah nau răm maak bơh bunuyh ntĭm nti jêng nau ueh đăp mpăn.$b$,true),
('bunong-vn','PRO',12,21,null,$b$Mâu geh du ntil nau mhĭk ôh tât ma bunuyh sŏng, ƀiă lah phung ƀai bêng ma nau nđêh nji.$b$,true),
('bunong-vn','PRO',12,22,null,$b$Yêhôva tâm rmot mpiăt ngơi mƀruh, ƀiă lah Păng maak ma nau ngơi ngăn.$b$,true),
('bunong-vn','PRO',12,23,null,$b$Bunuyh blau njrăng pôn nau blau mĭn, ƀiă lah phung rluk mbơh nau rluk khân păng.$b$,true),
('bunong-vn','PRO',12,24,null,$b$Ti bunuyh gơih mra chiă uănh, ƀiă lah phung ƀlao mra jêng dĭk.$b$,true),
('bunong-vn','PRO',12,25,null,$b$Nau rngot gŭ tâm nuih n'hâm bunuyh ƀư rngot ô băl; ƀiă lah nau ngơi ueh ƀư maak ma ô băl.$b$,true),
('bunong-vn','PRO',12,26,null,$b$Bunuyh sŏng njŭn leo trong ma phung chiau meng păng; ƀiă lah trong phung ƀai tâm nkah đah khân păng.$b$,true),
('bunong-vn','PRO',12,27,null,$b$Bunuyh ƀlao mâu ŭch gŭch pâr ôh puăch puăch păng hŏ pănh; ƀiă lah bunuyh gơih rŏng ma drăp ndơ păng geh.$b$,true),
('bunong-vn','PRO',12,28,null,$b$Trong nau sŏng njŭn leo nau rêh, jêh ri tâm trong mâu geh nau khĭt ôh.$b$,true),
('bunong-vn','PRO',13,1,null,$b$Du huê kon bu klâu blau mĭn iăt nau mbơ̆ păng nti; ƀiă lah bunuyh mưch mâu ŭch iăt ôh nau bu nduyh.$b$,true),
('bunong-vn','PRO',13,2,null,$b$Bunuyh ueh sa play ueh tĭng nâm nau păng ngơi, ƀiă lah huêng phung ƀlêp ƀlêr mra sa nau djơh mhĭk.$b$,true),
('bunong-vn','PRO',13,3,null,$b$Mbu nơm blau njrăng ma bâr mbung păng, mât chiă nau rêh păng nơm; mbu nơm nđar huy mbung păng hăn ma nau rai yot.$b$,true),
('bunong-vn','PRO',13,4,null,$b$Bunuyh ƀlao geh nau kơnh ƀiă lah mâu geh ndô ndơ ôh; bi ma huêng phung bunuyh gơih mra dơi geh ăp ntil ndơ.$b$,true),
('bunong-vn','PRO',13,5,null,$b$Bunuyh sŏng tâm rmot ma nau mƀruh; ƀiă lah bunuyh djơh mhĭk ƀư nau bu tâm rmot jêh ri ma nau bêk-prêng.$b$,true),
('bunong-vn','PRO',13,6,null,$b$Nau sŏng king mbu nơm gŭ ngao sŏng srăng, ƀiă lah nau tih mhĭk n'glưh lơi phung ƀư tih.$b$,true),
('bunong-vn','PRO',13,7,null,$b$Geh bunuyh n'hi săk ƀư ndrŏng, ƀiă lah mâu geh du ntil ndô ndơ ôh; ăt geh lĕ nơm êng n'hi săk ƀư bunuyh o-ach, ƀiă lah geh âk drăp ndơ.$b$,true),
('bunong-vn','PRO',13,8,null,$b$Rnoh tâm chuai ma nau rêh păng, nây jêng drăp ndơ păng nơm; bi ma bunuyh o ach mâu ŭch iăt ôh nau bu nduyh.$b$,true),
('bunong-vn','PRO',13,9,null,$b$Ŭnh kađen phung sŏng dơi sol ang, ƀiă lah ŭnh kađen phung ƀai bu mra khôm nhhât.$b$,true),
('bunong-vn','PRO',13,10,null,$b$Nau sưr njŭn tât ma nau tâm djrel, bi ma nau blau mĭn gŭ ndrel ma bunuyh iăt nau bu ntĭm nti.$b$,true),
('bunong-vn','PRO',13,11,null,$b$Nau ndrŏng tă bơh nau ndơm mra roh mbrơi mbrơi, ƀiă lah mbu nơm bun prăp tă bơh mpang ti ntop mbrơi mbrơi mra hao lơn.$b$,true),
('bunong-vn','PRO',13,12,null,$b$Ŭch njong nau kâp gân ƀư nuih n'hâm geh nau ji, ƀiă lah nau kâp gân tât jêh jêng nâm bu tơm si nau rêh.$b$,true),
('bunong-vn','PRO',13,13,null,$b$Mbu nơm tâm rmot ma nau bu nti, ƀư ngroh lơi săk păng nơm; bi ma nơm klach yơk ma nau bu ntăm, nây mơ geh nau nkhôm.$b$,true),
('bunong-vn','PRO',13,14,null,$b$Nau ntĭm nti bơh bunuyh blau mĭn jêng tu nau rêh. Gay ăn bu der bơh dăk nau khĭt.$b$,true),
('bunong-vn','PRO',13,15,null,$b$Nau gĭt rbăng ngăn dơi geh nau yô̆, ƀiă lah trong phung tih jêng nau rêh ni ngăn.$b$,true),
('bunong-vn','PRO',13,16,null,$b$Bunuyh blau njrăng pah kan ma nau gĭt vât; ƀiă lah bunuyh rluk tâm mpơl nau păng rluk mâl.$b$,true),
('bunong-vn','PRO',13,17,null,$b$Bunuyh mhĭk njŭn leo tât tâm nau uh ah; bi ma oh mon răp jăp nâm bu dak si tam rjăp.$b$,true),
('bunong-vn','PRO',13,18,null,$b$Mbu nơm dun nau bu ntĭm nti mra jêng o ach jêh ri dơn nau bêk prêng; ƀiă lah mbu nơm dơn nau bu nduyh nkra mra geh nau bu yơk.$b$,true),
('bunong-vn','PRO',13,19,null,$b$Nau vơl ŭch tât jêng ndơ ăn ma huêng, bi ma nau cha lơi nau mhĭk, nây jêng nau ăn ma phung rluk tâm rmot.$b$,true),
('bunong-vn','PRO',13,20,null,$b$Mbu nơm dơh dăch đah bunuyh blau mĭn, mra dơi jêng blau mĭn; ƀiă lah mbu nơm sa jiăng đah bunuyh rluk mra dơn nau roh rai.$b$,true),
('bunong-vn','PRO',13,21,null,$b$Nau rêh ni tĭng groi phung ƀư tih; ƀiă lah nau ueh lăng jêng nau nkhôm ma bunuyh sŏng.$b$,true),
('bunong-vn','PRO',13,22,null,$b$Bunuyh ueh ăn drăp ma phung kon sau păng ndơn; ƀiă lah drăp ndơ phung tih prăp ma bunuyh sŏng.$b$,true),
('bunong-vn','PRO',13,23,null,$b$Mir mhe bunuyh o ach dơi geh play ndơ sông sa tŏng rmeh; ƀiă lah geh bunuyh lĕ roh jêh yor lah bu mâu geh nau sŏng.$b$,true),
('bunong-vn','PRO',13,24,null,$b$Mbu nơm mâu rpăt nkra kon khân păng nơm; tâm rmot ma ô băl yơh; ƀiă lah mbu rŏng ma kon păng ăn gơih nkra ntĭm ô băl.$b$,true),
('bunong-vn','PRO',13,25,null,$b$Bunuyh sŏng geh mpa sông tŏng ma păng nơm; ƀiă lah ndŭl phung ƀai geh nau ji ngot.$b$,true),
('bunong-vn','PRO',14,1,null,$b$Bu ur blau mĭn ndâk ngih păng; ƀiă lah bu ur rluk sŏk ti păng nơm rơih lơi ngih păng.$b$,true),
('bunong-vn','PRO',14,2,null,$b$Mbu nơm hăn tĭng nau sŏng klach yơk ma Yêhôva, bi ma nơm ƀư nau kue tâm rmot ma Păng.$b$,true),
('bunong-vn','PRO',14,3,null,$b$Tâm mbung bunuyh rluk mra geh mâng nkhôm ma nau sưr păng; ƀiă lah bâr mbung bunuyh blau mĭn mra mât săk păng nơm.$b$,true),
('bunong-vn','PRO',14,4,null,$b$Ta ntŭk mâu geh ndrôk ta nây ndrêch gơ̆ dơm; ƀiă lah geh play ba âk luh tă n'hâm suan ndrôk nkuăng.$b$,true),
('bunong-vn','PRO',14,5,null,$b$Du huê bunuyh răp jăp mbơh mâu geh ndơm ôh. Ƀiă lah du huê bunuyh mbơh mâu geh nau nanê̆ ôh jêng nơm mƀruh.$b$,true),
('bunong-vn','PRO',14,6,null,$b$Bunuyh dăng mưch joi nau blau mĭn, ƀiă lah nau gĭt mĭn jêng nơih ma nơm gĭt rbăng.$b$,true),
('bunong-vn','PRO',14,7,null,$b$Ăn may der ngai hom bơh bunuyh rluk, khân păng mâu dơi sâm nti may ma nau blau mĭn ôh.$b$,true),
('bunong-vn','PRO',14,8,null,$b$Nau blau mĭn bunuyh blau njrăng nây jêng gĭt rbăng tâm trong păng; ƀiă lah nau mâl phung rluk jêng nau ndơm.$b$,true),
('bunong-vn','PRO',14,9,null,$b$Phung rluk mưch rmot ma nau tâm rmal ma nau tih; ƀiă lah bunuyh sŏng ƀư ma nuih n'hâm ueh.$b$,true),
('bunong-vn','PRO',14,10,null,$b$Nuih n'hâm gĭt năl nau rngot păng nơm, du huê bu năch mâu blau tâm pă ôh nau păng maak.$b$,true),
('bunong-vn','PRO',14,11,null,$b$Bu mra ƀư rai ngih phung ƀai, ƀiă lah ngih phung sŏng mra văch ma hao.$b$,true),
('bunong-vn','PRO',14,12,null,$b$Geh trong bunuyh kơp ntôn lah sŏng; ƀiă lah nglĕ dŭt păng njŭn ma nau khĭt.$b$,true),
('bunong-vn','PRO',14,13,null,$b$Nđâp lah dôl geh nau gơm nuih n'hâm ăt hôm geh nau rngot; jêh ri pa kơi ma nau răm rhơn nây jêng nau rngot rvê.$b$,true),
('bunong-vn','PRO',14,14,null,$b$Nuih n'hâm mhĭk mra mplơ̆ tâm trong nau mhĭk păng nơm, Jêh ri bunuyh ueh mra geh nau nkhôm bơh kan ueh păng.$b$,true),
('bunong-vn','PRO',14,15,null,$b$Bunuyh rluk rnơm iăt lĕ rngôch nau; ƀiă lah bunuyh blau njrăng sek uănh lĕ trong păng chuat hăn.$b$,true),
('bunong-vn','PRO',14,16,null,$b$Bunuyh blau mĭn blau njrăng jêh ri der bơh nau tih; ƀiă lah bunuyh rluk ƀư sưr mâu blau njrăng ôh.$b$,true),
('bunong-vn','PRO',14,17,null,$b$Mbu nơm gơnh ji nuih ƀư nau rluk; jêh ri bunuyh ƀlêp-ƀlêr bu tâm rmot.$b$,true),
('bunong-vn','PRO',14,18,null,$b$Phung mâu blau mĭn ôh sŏk dơn nau rluk. Ƀiă lah phung blau njrăng geh nau nkhôm đon hađăch nau gĭt rbăng$b$,true),
('bunong-vn','PRO',14,19,null,$b$Phung mhĭk mra chon mon ta năp phung ueh; jêh ri phung ƀai chon mbah pa năp mpôl phung sŏng.$b$,false),
('bunong-vn','PRO',14,20,null,$b$Du huê bunuyh o ach nđâp lah phung chiau meng ăt biănh đŏng. Ƀiă lah phung ndrŏng geh âk mĭt jiăng.$b$,true),
('bunong-vn','PRO',14,21,null,$b$Mbu nơm tâm rmot ma phung chiau meng păng jêng bunuyh tih: Ƀiă lah ueh maak ngăn ma nơm yô̆ ma phung o ach.$b$,true),
('bunong-vn','PRO',14,22,null,$b$Phung tâm chră ma nau ƀư mhĭk mâu hĕ tih? Bi ma nau ueh jêh ri n'hêl nanê̆ jêng phung tâm chră ƀư nau di.$b$,true),
('bunong-vn','PRO',14,23,null,$b$Tâm lĕ rngôch nau kan geh nau khlay da dê. Ƀiă lah bâr mbung knŏng ngơi dơm mra njŭn ma nau mâu geh.$b$,true),
('bunong-vn','PRO',14,24,null,$b$Đon hađăch ma phung blau mĭn jêng nau ndrŏng. Ƀiă lah nau rluk mâl ma phung rluk knŏng tâm rvang nau rluk.$b$,true),
('bunong-vn','PRO',14,25,null,$b$Nơm mbơh nau ngăn gay tâm rklaih huêng bu; ƀiă lah bunuyh ngơi mƀruh jêng nau ƀlêp ƀlêr.$b$,true),
('bunong-vn','PRO',14,26,null,$b$Mbu nơm klach yơk ma Yêhôva geh ntŭk nsing nâp ngăn. Jêh ri phung jêng kon Păng mra dơn geh du ntŭk nde.$b$,true),
('bunong-vn','PRO',14,27,null,$b$Nau klach yơk ma Yêhôva jêng du tu nau rêh, gay ăn bu der bơh dăk nau khĭt.$b$,true),
('bunong-vn','PRO',14,28,null,$b$Nau chrêk rmah ma hađăch jêng phung ƀon lan âk; ƀiă lah nau mâu geh bunuyh, nây jêng rai lôch ma kôranh chiă uănh.$b$,true),
('bunong-vn','PRO',14,29,null,$b$Mbu nơm băt (mâu gơnh) nuih geh nau gĭt rbăng toyh. Ƀiă lah mbu nơm gơnh nuih n'hao nau rluk.$b$,true),
('bunong-vn','PRO',14,30,null,$b$Nuih n'hâm đăp rmên ăn nau rêh ma săk jăn.$b$,true),
('bunong-vn','PRO',14,31,null,$b$Phung tŭn jot bunuyh o ach rak suai ma Nơm Njêng ô băl. Ƀiă lah mbu nơm yô̆ ma bunuyh o ach jêng yơk ma Nơm Njêng Ô băl.$b$,true),
('bunong-vn','PRO',14,32,null,$b$Bunuyh mhĭk rai roh yor nau tih păng nơm ƀư. Ƀiă lah bunuyh sŏng ăt hôm geh ntŭk nde nđâp tơ lah dôl păng khĭt.$b$,true),
('bunong-vn','PRO',14,33,null,$b$Nau blau mĭn gŭ tâm nuih n'hâm bunuyh gĭt rbăng. Ƀiă lah nuih n'hâm bunuyh rluk mâu gĭt rbăng ôh.$b$,true),
('bunong-vn','PRO',14,34,null,$b$Nau sŏng srăng n'hao ăn bri dak dơi hao. Ƀiă lah nau tih jêng nau ƀư prêng ntil mpôl bunuyh.$b$,true),
('bunong-vn','PRO',14,35,null,$b$Hađăch yô̆ ma oh mon gŭ ngao blau mĭn; ƀiă lah păng ji nuih ma nơm ƀư nau prêng.$b$,true),
('bunong-vn','PRO',15,1,null,$b$Nau plơ̆ lah ma bâr rdơ̆ ăn djoh nau ji nuih. Ƀiă lah nau ngơi dăng nsônh tay nau ji nuih.$b$,true),
('bunong-vn','PRO',15,2,null,$b$Mpiăt phung blau mĭn ngơi nau gĭt rbăng ƀiă lah bâr mbung phung rluk knŏng luh nau mhĭk.$b$,true),
('bunong-vn','PRO',15,3,null,$b$Măt Yêhôva uănh lam ntŭk, kâp uănh phung djơh jêh ri phung ueh.$b$,true),
('bunong-vn','PRO',15,4,null,$b$Mpiăt ngơi nau ueh jêng nâm bu tơm si nau rêh. Bi ma mpiăt ngơi kue ƀư chah rai nuih n'hâm.$b$,true),
('bunong-vn','PRO',15,5,null,$b$Bunuyh rluk tâm rmot đah mbơ̆ păng ntĭm nti; ƀiă lah mbu nơm sŏk dơn nau nkra geh nau blau mĭn.$b$,true),
('bunong-vn','PRO',15,6,null,$b$Tâm ngih bunuyh sŏng geh âk drăp ndơ khlay. Ƀiă lah ndô ndơ bunuyh ƀai geh tât nau uh ah.$b$,true),
('bunong-vn','PRO',15,7,null,$b$Bâr mbung bunuyh blau mĭn srih nau gĭt mĭn âk. Ƀiă lah nau mĭn phung rluk mâu ƀư pô nây ôh.$b$,true),
('bunong-vn','PRO',15,8,null,$b$Yêhôva tâm rmot ma ndơ phung kue ƀư brah. Ƀiă lah nau phung sŏng mbơh sơm ƀư maak ma Păng.$b$,true),
('bunong-vn','PRO',15,9,null,$b$Yêhôva tâm rmot ma trong phung djơh mhĭk. Ƀiă lah Păng rŏng ma nơm tĭng ndô̆ nau sŏng,$b$,true),
('bunong-vn','PRO',15,10,null,$b$Mbu nơm cha lơi trong sŏng mra dơn nau tâm rmal ktang. Mbu nơm tâm rmot nau bu nduyh nkra păng mra khĭt.$b$,false),
('bunong-vn','PRO',15,11,null,$b$Yêhôva hŏ saơ jêh lĕ rngôch ndơ tâm Ƀon Phung Khĭt jêh ri ntŭk bri phan, rlau lơn ma nây păng gĭt năl jêh nuih n'hâm phung bunuyh!$b$,true),
('bunong-vn','PRO',15,12,null,$b$Phung dăng mưch mâu ŭch ôh bu nduyh nkra. Păng mâu hăn dăch ôh ma phung blau mĭn.$b$,true),
('bunong-vn','PRO',15,13,null,$b$Nuih n'hâm gơih nđơr tâm mpơl muh măt răm maak. Ƀiă lah nuih n'hâm rngot huêng geh nau rdja.$b$,true),
('bunong-vn','PRO',15,14,null,$b$Nuih n'hâm nơm gĭt rbăng tĭng joi nau blau mĭn âk. Ƀiă lah bâr mbung rluk mra dơn nau rluk păng.$b$,true),
('bunong-vn','PRO',15,15,null,$b$Lĕ rngôch nar phung rêh ni jêng mhĭk da dê. Ƀiă lah nuih n'hâm hâk răm geh nau nhêt sa ƀa ƀơ.$b$,true),
('bunong-vn','PRO',15,16,null,$b$Ueh lơn geh djê̆ drăp ndơ ndrel ma nau klach yơk ma Yêhôva đah geh âk drăp ndơ ndrel ma nau uh ah.$b$,true),
('bunong-vn','PRO',15,17,null,$b$Ueh lơn geh biăp trao sông sa ma nau rŏng đah du mlâm ndrôk lay sa ndrel geh nau tâm rmot.$b$,true),
('bunong-vn','PRO',15,18,null,$b$Bunuyh gơnh nuih nsônh nau tâm djrel. Ƀiă lah bunuyh băt nuih ƀư rplai lơi nau tâm djrel.$b$,true),
('bunong-vn','PRO',15,19,null,$b$Trong phung ƀlao nâm bu mpâr lok, bi trong ma bunuyh sŏng lĕ rli lâng.$b$,true),
('bunong-vn','PRO',15,20,null,$b$Du huê kon bu klâu blau mĭn ƀư maak ma mbơ̆ păng. Ƀiă lah du huê kon rluk tâm rmot ma mê̆ păng.$b$,true),
('bunong-vn','PRO',15,21,null,$b$Bunuyh mâu gĭt vât jêng nau răm maak ma nơm mâu geh nau blau mĭn ôh. Ƀiă lah du huê gĭt rbăng nkra ăn sŏng trong păng jêh ri mơ hăn.$b$,true),
('bunong-vn','PRO',15,22,null,$b$Tơ lah mâu geh nau tâm nchră, nau ŭch nchră nây mra roh. Ƀiă lah yor geh âk bunuyh nchră nau may ŭch nchră mra jêng.$b$,true),
('bunong-vn','PRO',15,23,null,$b$Bâr ueh plơ̆ lah di, ƀư maak ma bu jêh ri nau ngơi tâm di jêng nau ueh ngăn.$b$,true),
('bunong-vn','PRO',15,24,null,$b$Trong ma bunuyh blau mĭn njŭn leo hao klơ ma nau rêh. Gay ma klaih bơh Ƀon Phung Khĭt tâm dâng.$b$,true),
('bunong-vn','PRO',15,25,null,$b$Yêhôva ƀư rlâm lơi ngih phung sưr, Ƀiă lah Păng king nâp n'har bri bu ur ndrô.$b$,true),
('bunong-vn','PRO',15,26,null,$b$Yêhôva tâm rmot nau mĭn phung ƀai. Ƀiă lah nau phung kloh ueh ngơi ƀư maak ma Păng.$b$,true),
('bunong-vn','PRO',15,27,null,$b$Bunuyh hay sa drăp ndơ bu ƀư uh ah ma rnăk vâl păng nơm. Mbu nơm tâm rmot ma drăp bu blŏl mra dơi geh nau rêh.$b$,true),
('bunong-vn','PRO',15,28,null,$b$Nuih n'hâm bunuyh sŏng mĭn rvê mâm nau mra plơ̆ lah; Ƀiă lah bâr mbung bunuyh mhĭk ngơi luh âk nau mhĭk.$b$,true),
('bunong-vn','PRO',15,29,null,$b$Yêhôva gŭ ngai đah phung ƀai, ƀiă lah Păng gŭ iăt nau phung sŏng mbơh sơm.$b$,true),
('bunong-vn','PRO',15,30,null,$b$Nau ang trôm măt gay ăn nuih n'hâm răm maak. Jêh ri du nau mhe mhan ueh gay ăn nting nđăng dơi ueh.$b$,true),
('bunong-vn','PRO',15,31,null,$b$Mbu nơm rkêng tôr iăt ma nau bu nduyh nkra dơi geh nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',15,32,null,$b$Mbu nơm dun nau bu ntĭm nti tâm rmot ma huêng păng nơm. Ƀiă lah mbu nơm iăt nau bu nduyh nkra dơi geh nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',15,33,null,$b$Nau klach yơk ma Yêhôva sâm nti nau blau mĭn. Jêh ri nau dêh rhêt hăn lor pa năp nau yơk.$b$,true),
('bunong-vn','PRO',16,1,null,$b$Nau kan nuih n'hâm ŭch nkra luh bơh bunuyh, ƀiă lah nau plơ̆ lah tâm mpiăt luh bơh Yêhôva.$b$,true),
('bunong-vn','PRO',16,2,null,$b$Lĕ rngôch bunuyh jêng kloh rsang da dê tĭng nâm măt păng nơm, ƀiă lah Yêhôva sek uănh tâm nuih n'hâm.$b$,true),
('bunong-vn','PRO',16,3,null,$b$Jao hom kan may ma Yêhôva, ri mơ nau kan may ŭch mra dơi jêng.$b$,true),
('bunong-vn','PRO',16,4,null,$b$Yêhôva hŏ rhăk njêng jêh lĕ rngôch mpô mpa prăp ma nau Păng săch; nđâp bunuyh ƀai tâm ban lĕ prăp ma nar rêh ni.$b$,true),
('bunong-vn','PRO',16,5,null,$b$Yêhôva tâm rmot ngăn ma ăp nơm geh nuih n'hâm sưr; N'hêl nanê̆ păng mâu mra klaih ôh ma nau tâm rmal.$b$,true),
('bunong-vn','PRO',16,6,null,$b$Ma nau ueh jêh ri ma nau n'hêl nanê̆ bu dơi jut nau tih mhĭk. Yor ma nau klach yơk ma Yêhôva bu cha lơi nau tih.$b$,true),
('bunong-vn','PRO',16,7,null,$b$Tơ lah nau rêh du huê bunuyh ƀư maak ma Yêhôva. Păng ăn nđâp ma phung rlăng ma ô băl gŭ đăp rmên đah ô băl.$b$,true),
('bunong-vn','PRO',16,8,null,$b$Ueh lơn geh djê̆ ndơ ma nau sŏng srăng, đah geh âk ndô ndơ sa kao ma nau kue.$b$,true),
('bunong-vn','PRO',16,9,null,$b$Nau mĭn bunuyh săch trong păng ŭch ƀư; ƀiă lah Yêhôva njŭn leo lĕ nhuat păng chuat.$b$,true),
('bunong-vn','PRO',16,10,null,$b$Nau ngơi Păng gŭ ta mbung hađăch; mbung păng mâu ngơi tih ôh tơ lah păng phat dôih.$b$,true),
('bunong-vn','PRO',16,11,null,$b$Play njing jêh ri mâng njing nau sŏng jêng ndơ Yêhôva; Lĕ rngôch play njing tâm dŭng jêng kan Păng.$b$,true),
('bunong-vn','PRO',16,12,null,$b$Ƀư nau mhĭk, nây jêng ndơ nau djơh ma phung hađăch; yor nau sŏng srăng yơh nau chiă uănh dĭng dơi nâp.$b$,true),
('bunong-vn','PRO',16,13,null,$b$Nau ngơi bunuyh sŏng ƀư maak ma hađăch jêh ri hađăch rŏng ma nơm ngơi ngăn.$b$,true),
('bunong-vn','PRO',16,14,null,$b$Nau hađăch ji nuih jêng nâm bu du huê nơm mbơh ma nau khĭt. Ƀiă lah bunuyh gĭt mĭn mra rplai nuih n'hâm păng.$b$,true),
('bunong-vn','PRO',16,15,null,$b$Nau pơk ang muh măt hađăch mơ dơi geh nau rêh; jêh ri nau păng yô̆ jêng nâm bu tŭk krŭl tơm mih.$b$,true),
('bunong-vn','PRO',16,16,null,$b$Sŏk nau blau mĭn khlay lơn ma mah; săch sŏk nau gĭt rbăng khlay lơn ma prăk.$b$,true),
('bunong-vn','PRO',16,17,null,$b$Trong bunuyh sŏng du ndăch bơh nau tih, mbu nơm mât njrăng ma trong păng mra mât huêng păng nơm.$b$,true),
('bunong-vn','PRO',16,18,null,$b$Nau sưr hăn lor, nau rai lôch groi pa kơi; jêh ri nau n'hao êng nơm hăn lor tâm nau tŭp.$b$,true),
('bunong-vn','PRO',16,19,null,$b$Ueh lơn dêh rhêt gŭ ndrel phung hêt rhôi ma đah nau tâm pă ndơ geh sŏk pit ndrel phung sưr.$b$,true),
('bunong-vn','PRO',16,20,null,$b$Mbu nơm tông nau nti mra rnơm ma Yêhôva geh nau hâk răm ngăn.$b$,true),
('bunong-vn','PRO',16,21,null,$b$Mbu nơm geh nuih n'hâm blau mĭn bu ntơ păng jêng nơm gĭt rbăng; jêh ri nau ngơi rdơ̆ sâm n'hao nau blau.$b$,true),
('bunong-vn','PRO',16,22,null,$b$Nau gĭt mĭn jêng tu ma nau rêh ma mbu nơm geh păng. Ƀiă lah nau rluk jêng nau tâm rmal ma phung rluk.$b$,true),
('bunong-vn','PRO',16,23,null,$b$Nuih n'hâm phung blau mĭn gai nau păng ngơi, jêh ri dơi ntop nau gĭt mĭn ta bơh bâr mbung păng.$b$,true),
('bunong-vn','PRO',16,24,null,$b$Nau ngơi ueh jêng nâm bu mpơng sŭt, njŭng ăn ma huêng jêh ri nau ngăch prăl ma săk jăn.$b$,true),
('bunong-vn','PRO',16,25,null,$b$Geh du trong uănh nâm bu di ăn ma bunuyh, nglĕ dŭt nkhơng jêng trong nau khĭt.$b$,true),
('bunong-vn','PRO',16,26,null,$b$Nau du huê pah kan ji ngot ntrôl păng pah kan, yor lah păng ŭch ăn hơm nau păng ji ngot.$b$,true),
('bunong-vn','PRO',16,27,null,$b$Bunuyh dơm dam tâm chră ƀư nau mhĭk, jêh ri nau păng ngơi jêng nâm bu ŭnh n'hâng.$b$,true),
('bunong-vn','PRO',16,28,null,$b$Bunuyh kue srih nau tâm djrel, jêh ri bunuyh nkoch bri nsak ƀư tâm nkhah phung mĭt jiăng bu.$b$,true),
('bunong-vn','PRO',16,29,null,$b$Bunuyh janh ƀai ndơm ma nơm chiau meng păng, jêh ri njŭn leo ô băl tâm trong mâu ueh ôh.$b$,true),
('bunong-vn','PRO',16,30,null,$b$Mbu nơm ntơ̆ măt joi uănh ƀư nau kue, mbu nơm hŏ ƀư nau mhĭk.$b$,true),
('bunong-vn','PRO',16,31,null,$b$Sŏk mra jêng đon hađăch ma nau chrêk rmah, bu dơi geh nau nây ma nau rêh sŏng.$b$,true),
('bunong-vn','PRO',16,32,null,$b$Bunuyh băt ji nuih jêng ueh lơn ma du huê janh ktang.$b$,true),
('bunong-vn','PRO',16,33,null,$b$Bu ƀư nau tâm nchroh tâm trô ko ao; ƀiă lah nau geh ngăn tă bơh Yêhôva.$b$,true),
('bunong-vn','PRO',17,1,null,$b$Ueh lơn geh du glo piăng let kro, ndrel ma nau đăp mpăn khlay lơn ma ngih bêng ma ndơ sông sa, nkhơng geh nau tâm djrel.$b$,true),
('bunong-vn','PRO',17,2,null,$b$Du huê dĭk, bu ƀư ma nau blau mĭn mra jêng kôranh ma kon bu klâu ƀư nau prêng, jêh ri păng mra ndơn drăp ndrel ma phung oh nâu.$b$,true),
('bunong-vn','PRO',17,3,null,$b$Glah ƀŭng prăp nkret prăk dăng, jêh ri năk gay nkret mah; ƀiă lah Yêhôva rlong uănh nuih n'hâm kon bunuyh.$b$,true),
('bunong-vn','PRO',17,4,null,$b$Bunuyh ƀai gơih ngăn bâr păng ngơi djơh; bunuyh ngơi mƀruh tôr păng ueh ngăn iăt bâr ngơi mhĭk.$b$,true),
('bunong-vn','PRO',17,5,null,$b$Mbu nơm mưch bunuyh ndĭt trơi, rak suai ma Nơm Rhăk Njêng păng. Mbu nơm maak ma nau rêh ni tât mâu mra klaih ôh đah nau tâm rmal.$b$,true),
('bunong-vn','PRO',17,6,null,$b$Phung kon sau jêng đon hađăch ma phung bu ranh; jêh ri phung mbơ̆ jêng nau chrêk rmah ma phung kon sau păng.$b$,true),
('bunong-vn','PRO',17,7,null,$b$Nau ngơi ueh mâu khư ôh ma du huê rluk, rlau lơn ma nây nau ngơi mƀruh mâu khư lĕ ma du huê kôranh chiă uănh.$b$,true),
('bunong-vn','PRO',17,8,null,$b$Drăp ndơ bu blŏl nâm bu du mlâm lŭ rsang ta năp nơm dơi geh păng, ta ntŭk păng hăn ăt dơi geh nau dơi.$b$,true),
('bunong-vn','PRO',17,9,null,$b$Mbu nơm yô̆ an nau tih joi nau rŏng, ƀiă lah mbu nơm nkah tay nau tih roh mĭt jiăng.$b$,true),
('bunong-vn','PRO',17,10,null,$b$Nau nduyh lăp jru lơn tâm bunuyh geh nau gĭt mĭn, ma đah rhiăng tơ̆ dong bunuyh rluk$b$,true),
('bunong-vn','PRO',17,11,null,$b$Bunuyh ƀai knŏng joi nau tâm rdâng, yor nây mra prơh du huê janh ngăn hăn mbơh nau lơh păng.$b$,false),
('bunong-vn','PRO',17,12,null,$b$Ueh lơn mâp kau me lĕ bu ntŭng kon ma đah tâm mâp ma bunuyh rluk dôl păng ƀư nau rluk.$b$,true),
('bunong-vn','PRO',17,13,null,$b$Tơ lah du huê bunuyh mplơ̆ nau mhĭk ma nau ueh, nau rêh ni mâu mra du ôh bơh ngih păng.$b$,true),
('bunong-vn','PRO',17,14,null,$b$Ntơm nau tâm djrel, nâm bu pling ntât dak, pô ri rlu lơi lor ma nau tâm djrel ktang lơn.$b$,true),
('bunong-vn','PRO',17,15,null,$b$Mbu nơm kơp bunuyh mhĭk jêng sŏng jêh ri tâm rmal bunuyh sŏng, Yêhôva tâm rmot lĕ bar hê khân păng.$b$,true),
('bunong-vn','PRO',17,16,null,$b$Moh khlay bunuyh rluk geh prăk tâm ti păng; ƀiă lah dôl păng mâu geh nau ŭch ôh?$b$,true),
('bunong-vn','PRO',17,17,null,$b$Du huê mĭt jiăng tâm rŏng ƀa ƀơ, jêh ri păng jêng soh nâu gay tâm kơl dôl geh nau rêh ni.$b$,true),
('bunong-vn','PRO',17,18,null,$b$Nơm mâu geh nau blau mĭn ƀư nau tâm nkol dơn râng, păng râng ma bunuyh ta năp nơm chiau meng păng.$b$,true),
('bunong-vn','PRO',17,19,null,$b$Mbu nơm kơnh tâm djrel rŏng ma nau tih; mbu nơm ƀư mpông păng ăn prêh joi gay rlâm.$b$,true),
('bunong-vn','PRO',17,20,null,$b$Du huê geh nau mĭn kue mâu geh ôh nau ueh maak jêh ri mbu nơm geh mpiăt tih tŭp tâm nau rêh ni.$b$,true),
('bunong-vn','PRO',17,21,null,$b$Du huê kon bu klâu rluk ƀư rngot ma mbơ̆ păng; bi mbơ̆ ma phung rluk mâu geh nau maak ôh.$b$,true),
('bunong-vn','PRO',17,22,null,$b$Nuih n'hâm hâk răm jêng du ntil dak si ueh, ƀiă lah nau rdja nuih ăn sơh kro nting.$b$,true),
('bunong-vn','PRO',17,23,null,$b$Bunuyh ƀai dơn ndơ bu blŏl ma nau ndâp gay ƀư vĭ lĕ trong phat dôih sŏng.$b$,true),
('bunong-vn','PRO',17,24,null,$b$Geh nau blau mĭn gŭ pa năp bunuyh gĭt rbăng; ƀiă lah trôm măt phung rluk uănh ta bôl dŭt neh ntu.$b$,true),
('bunong-vn','PRO',17,25,null,$b$Du huê kon bu klâu rluk ƀư rngot ma mbơ̆ păng, jêh ri ƀư jâk ma mê̆ hŏ deh nkeng jêh ma păng.$b$,true),
('bunong-vn','PRO',17,26,null,$b$Mâu ueh ôh ăn (kuh lah) bunuyh sŏng, jan dôih, mâu ueh lĕ dong phung kôranh yor nau sŏng khân păng.$b$,true),
('bunong-vn','PRO',17,27,null,$b$Mbu nơm njrăng ma nau păng ngơi geh nau blau mĭn âk bi ma bunuyh geh nau mĭn mơih rmên jêng du huê bunuyh gĭt rbăng.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PRO',17,28,null,$b$Tơ lah gŭ rklăk, nđâp tơ lah bât rluk, ăt kơp păng jêng blau mĭn, nơm mêm bâr mbung păng bu kơp păng jêng bunuyh gĭt rbăng.$b$,true),
('bunong-vn','PRO',18,1,null,$b$Du huê bunuyh gŭ êng mâu lăp băl ôh gay joi nau păng nơm ŭch păng tâm rlăch ma lĕ nau mĭn di.$b$,true),
('bunong-vn','PRO',18,2,null,$b$Bunuyh rluk mâu ŭch ôh ma nau gĭt rbăng; ƀiă lah knŏng ŭch mbơh nau păng nơm mĭn.$b$,true),
('bunong-vn','PRO',18,3,null,$b$Tơ lah phung ƀai văch tât geh nau mưch rmot ăt tât đŏng; tơ lah geh nau prêng geh nau nduyh tâm ban lĕ.$b$,true),
('bunong-vn','PRO',18,4,null,$b$Nau ngơi tâm bâr mbung bunuyh jêng tâm ban dak klŏng jru; tu nau blau mĭn jêng dak n'hor dôl hoch.$b$,true),
('bunong-vn','PRO',18,5,null,$b$Mâu ueh ôh gŭ mpeh bunuyh ƀai, gay nsŭk ndơm bunuyh sŏng tâm nau phat nkra di.$b$,true),
('bunong-vn','PRO',18,6,null,$b$Mpiăt bunuyh rluk ăn tât ma nau tâm djrel; jêh ri bâr mbung păng ngơi nsônh ăn bu dong păng.$b$,true),
('bunong-vn','PRO',18,7,null,$b$Bâr mbung bunuyh rluk jêng nau ƀư roh păng nơm jêh ri mpiăt păng jêng dăk sân ma huêng păng.$b$,true),
('bunong-vn','PRO',18,8,null,$b$Nau ngơi bunuyh nkoch bri njĭp jêng nâm bu ndơ sa kah, jêh ri păng lăp jru tâm proch klơm.$b$,true),
('bunong-vn','PRO',18,9,null,$b$Mbu nơm ƀlao tâm kan păng pah ăt jêng oh mon đah nơm ƀư rai đŏng.$b$,true),
('bunong-vn','PRO',18,10,null,$b$Moh Yêhôva jêng pôih nâp ngăn; bunuyh sŏng srăng nchuăt ran ta nây, dơi geh ntŭk nde đăp rmên ngăn.$b$,true),
('bunong-vn','PRO',18,11,null,$b$Drăp ndơ bunuyh ndrŏng, nây jêng ƀon toyh nâp ma păng; ntôn lah nâm bu pêr prêh nking păng.$b$,true),
('bunong-vn','PRO',18,12,null,$b$Êlor ma nau rai lôch tât, nuih n'hâm păng ăt ngơi sưr; ƀiă lah nau dêh rhêt hăn pa năp ma nau bu yơk.$b$,true),
('bunong-vn','PRO',18,13,null,$b$Mplơ̆ lah ro ê hŏ iăt lor, nau nây jêng nau rluk jêh ri ƀư prêng ma mbu nơm ƀư pô nây.$b$,true),
('bunong-vn','PRO',18,14,null,$b$Huêng bunuyh kuăn rdâng păng roh jêh nau kâp gân mâm păng dơi srôih?$b$,true),
('bunong-vn','PRO',18,15,null,$b$Nuih n'hâm gĭt vât joi nau gĭt mĭn âk, jêh ri tôr phung blau mĭn tĭng joi nau gĭt rbăng.$b$,true),
('bunong-vn','PRO',18,16,null,$b$Ndơ du huê bunuyh djôt leo nhhơr mra pơk trong ma păng; jêh ri dơi ăn păng lăp pa năp phung toyh.$b$,true),
('bunong-vn','PRO',18,17,null,$b$Nơm ngơi lor bu mĭn lĕ di nau păng; ƀiă lah mpeh đah ri văch tât, bu ôp sek păng.$b$,true),
('bunong-vn','PRO',18,18,null,$b$Nau sŏk nchroh dơi ƀư lôch nau tâm rlăch, gay geh nau săch dơn ndrăng phung geh nau dơi toyh.$b$,true),
('bunong-vn','PRO',18,19,null,$b$Du huê oh mon bu nsak jêh jêng jêr lơn gay dơi geh tay păng ma đah pit in ƀon toyh; jêh ri nau tâm djrel jêng nâm bu rnăng mpông loih lĕ nchăng jêh.$b$,true),
('bunong-vn','PRO',18,20,null,$b$Du huê bunuyh ngơi mra dơi hơm ndŭl păng; păng hơm ma play rek bơh nau bâr păng ngơi.$b$,true),
('bunong-vn','PRO',18,21,null,$b$Rêh khĭt gŭ tâm nau dơi mpiăt; pô ri bu mra sŏk dơn tĭng nau păng ngơi.$b$,true),
('bunong-vn','PRO',18,22,null,$b$Mbu nơm joi du huê ur, geh jêh nau ueh; jêh ri sŏk dơn nau yô̆ bơh Yêhôva.$b$,true),
('bunong-vn','PRO',18,23,null,$b$Bunuyh o ach vơl nau yô̆ ; ƀiă lah bunuyh ndrŏng plơ̆ lah ma nau ngơi dăng.$b$,true),
('bunong-vn','PRO',18,24,null,$b$Bunuyh geh âk mĭt jiăng ƀư djơh păng nơm; ƀiă lah geh du huê mĭt jiăng vay dơh dăch lơn ma oh nâu du ndŭl deh.$b$,true),
('bunong-vn','PRO',19,1,null,$b$Bunuyh o ach gŭ ngao mơih rmên, jêng ueh lơn ma du huê bunuyh ngơi mƀruh.$b$,true),
('bunong-vn','PRO',19,2,null,$b$Nuih n'hâm mâu geh nau gĭt mĭn âk nau nây ăt mâu ueh lĕ; pô ri ma mbu nơm chuat ndal mra chêh prah.$b$,true),
('bunong-vn','PRO',19,3,null,$b$Nau rluk ma du huê bunuyh ƀư rai nau rêh păng nơm, ƀiă lah nuih n'hâm păng ji nuih ma Yêhôva.$b$,true),
('bunong-vn','PRO',19,4,null,$b$Nau ndrŏng ntop âk mĭt jiăng; bi ma nơm o ach nđâp lah geh mĭt jiăng ăt bu cha lơi lơi ô băl.$b$,true),
('bunong-vn','PRO',19,5,null,$b$Nơm mƀruh mâu dơi klaih ôh đah nau tâm rmal, jêh ri ma nơm ngơi nchơt nklă mâu mra klaih lĕ.$b$,true),
('bunong-vn','PRO',19,6,null,$b$Geh âk bunuyh mra yô̆ ma bunuyh lŏng, jêh ri lĕ rngôch bunuyh jêng mĭt jiăng da dê ma nơm nta ndơ.$b$,true),
('bunong-vn','PRO',19,7,null,$b$Lĕ rngôch oh nâu ndŭl deh bunuyh o ach tâm rmot da dê ma ô băl; lơ hâu phung mĭt jiăng păng mra du ngai bơh păng. Păng vơh ma khân păng, ƀiă lah khân păng lĕ du jêh.$b$,true),
('bunong-vn','PRO',19,8,null,$b$Mbu nơm joi nau blau mĭn rŏng ma huêng păng nơm, mbu nơm rŏng ma nau gĭt rbăng dơi geh nau ueh uĭn.$b$,true),
('bunong-vn','PRO',19,9,null,$b$Nơm mbơh mƀruh mâu mra klaih ôh bơh nau tâm rmal; jêh ri mbu nơm ngơi mƀruh mra rai yot.$b$,true),
('bunong-vn','PRO',19,10,null,$b$Mâu ueh ôh du huê rluk gay ma gŭ ngao păn thơ; lơ hâu ma nây du huê dĭk bu, jêng kôranh ma kon hađăch!$b$,true),
('bunong-vn','PRO',19,11,null,$b$Bunuyh geh nau blau mĭn jêng nơm băt ji nuih, jêng nau chrêk rmah ma păng; jêh ri păng mâu klăp ôh nau bu nsŭk ma păng tih.$b$,true),
('bunong-vn','PRO',19,12,null,$b$Nau hađăch nuih nâm bu ngrông yau mŭr, ƀiă lah nau păng yô̆ nâm bu dak ngom kăr ta gơ̆ .$b$,true),
('bunong-vn','PRO',19,13,null,$b$Du huê kon bu klâu rluk jêng nau ƀư rai ma mbơ̆ păng, jêh ri nau ur tâm djrel jêng nâm bu dak mih truh ƀa ƀơ.$b$,true),
('bunong-vn','PRO',19,14,null,$b$Ngih vâl jêh ri drăp ndơ, jêng ndơn drăp u che kăl e; bi ma du huê ur blau mĭn yor tă bơh Yêhôva ăn.$b$,true),
('bunong-vn','PRO',19,15,null,$b$Nau ƀlao ƀư ăn bu lêt bêch, jêh ri huêng gŭ dơm mra ât ji ngot.$b$,true),
('bunong-vn','PRO',19,16,null,$b$Mbu nơm djôt prăp nau ntăm, mât mray huêng păng nơm; ƀiă lah mbu nơm mâu blau njrăng nau rêh păng mra khĭt.$b$,true),
('bunong-vn','PRO',19,17,null,$b$Mbu nơm gĭt yô̆ ma phung o ach, nâm bu ntĭt ăn Yêhôva manh; jêh ri Yêhôva mra mplơ̆ sĭt nau ueh ma păng tĭng nâm kan păng ƀư.$b$,true),
('bunong-vn','PRO',19,18,null,$b$Nkra hom kon may dôl hôm e nau kâp gân; ƀiă lah lơi ta thăm nkhĭt păng.$b$,true),
('bunong-vn','PRO',19,19,null,$b$Mbu nơm ji nuih ngăn mra dơn nau tâm rmal, tơ lah may dơi rklaih păng du tơ̆ , ăt may dơi rklaih tay đŏng.$b$,true),
('bunong-vn','PRO',19,20,null,$b$Iăt hom nau ntĭm nti, jêh ri sŏk dơn nau bu ntĭm gay ma may geh nau blau mĭn nar nglĕ dŭt.$b$,true),
('bunong-vn','PRO',19,21,null,$b$Nuih n'hâm bunuyh geh âk nau kan ŭch ƀư, ƀiă lah nau Yêhôva ŭch dơi jêng.$b$,true),
('bunong-vn','PRO',19,22,null,$b$Bu ŭch saơ nau bunuyh ƀư ueh, bunuyh o ach khlay lơn ma đah bunuyh mƀruh.$b$,true),
('bunong-vn','PRO',19,23,null,$b$Nau klach yơk ma Yêhôva njŭn ma nau rêh, mbu nơm geh nau nây mra maak; nau uh ah mâu mra tât ma păng ôh.$b$,true),
('bunong-vn','PRO',19,24,null,$b$Bunuyh ƀlao nto ti păng tâm ngan, jêh ri mâu hôm nsiăm ôh tâm trôm mbung păng nơm.$b$,true),
('bunong-vn','PRO',19,25,null,$b$Dong hom bunuyh mưch, ri mơ bunuyh rluk mra nti nau blau mĭn; nduyh bunuyh gĭt rbăng ri mơ mra ntop geh nau blau mĭn âk.$b$,true),
('bunong-vn','PRO',19,26,null,$b$Mbu nơm ƀư mhĭk ma mbơ̆ păng jêh ri mprơh mê̆ păng; jêng du huê kon bu klâu ƀư ƀap păng, bêk prêng ma săk păng nơm.$b$,true),
('bunong-vn','PRO',19,27,null,$b$Hơi kon, lơi ta iăt nau nti nsak, klach lah may vĭ đah nau blau mĭn âk.$b$,true),
('bunong-vn','PRO',19,28,null,$b$Nơm nkoch nau mƀruh gay mưch rmot nau sŏng, bâr mbung phung mhĭk rvăn nau tih mhĭk.$b$,true),
('bunong-vn','PRO',19,29,null,$b$Nau tâm rmal hŏ ndrăp jêh ma phung mưch, jêh ri mâng rvĕ hŏ rơm jêh ma chŭr kuyh phung rluk.$b$,true),
('bunong-vn','PRO',20,1,null,$b$Dak play kriăk ƀâu jêng nơm blau mưch, ndrănh ktang jêng nơm tâm djrel; mbu nơm nhêt rlau keh ir mâu di ôh jêng bunuyh gĭt nau.$b$,true),
('bunong-vn','PRO',20,2,null,$b$Nau hađăch ji nuih nâm bu yau mŭr rđuh ngrông, mbu nơm nsônh păng ăn roh nau rêh păng nơm.$b$,true),
('bunong-vn','PRO',20,3,null,$b$Der mâu ƀư ôh nau tâm djrel jêng nau yơk ma bunuyh, ƀiă lah knŏng bunuyh rluk tŭp tâm nau nây.$b$,true),
('bunong-vn','PRO',20,4,null,$b$Bunuyh ƀlao mâu kai ôh mir dôl yan ji kăt, ta yan kăch păng mâu mra geh play ôh.$b$,true),
('bunong-vn','PRO',20,5,null,$b$Nau mĭn ŭch tâm nuih n'hâm jêng nâm bu dak jru, ƀiă lah bunuyh gĭt rbăng mra bâk tă bơh nây.$b$,true),
('bunong-vn','PRO',20,6,null,$b$Âk bunuyh nkoch ma nau păng nơm jêng ueh ƀiă lah mbu dơi saơ nơm răp jăp?$b$,true),
('bunong-vn','PRO',20,7,null,$b$Bunuyh sŏng chuat tâm nau mơih rmên, ueh lăng ngăn ma kon sau păng nar kăndơ̆$b$,true),
('bunong-vn','PRO',20,8,null,$b$Hađăch gŭ ta sưng phat dôih, mprơh lĕ nau mhĭk ma măt păng uănh.$b$,false),
('bunong-vn','PRO',20,9,null,$b$Mbu dơi lah: “Gâp hŏ djôt prăp nuih n'hâm gâp kloh ueh, gâp kloh ueh jêh mâu geh nau tih ôh?”$b$,true),
('bunong-vn','PRO',20,10,null,$b$Bar rplay njing, jêh ri bar njing n'gơch. Yêhôva tâm rmot lĕ bar nây.$b$,true),
('bunong-vn','PRO',20,11,null,$b$Nđâp kon se jê̆ mâm păng jêng dơi mpơl ma nau păng ƀư, gĭt lah nau păng ƀư jêng kloh mâu lah sŏng srăng.$b$,true),
('bunong-vn','PRO',20,12,null,$b$Tôr gĭt tăng jêh ri măt gĭt saơ, Yêhôva da dê njêng lĕ bar.$b$,true),
('bunong-vn','PRO',20,13,null,$b$Lơi ta rŏng ir ôh ma nau bêch klach lah may mra jêng o ach, lin măt may mra geh ăp ntil ndơ sông sa.$b$,true),
('bunong-vn','PRO',20,14,null,$b$Nơm rvăt lah ma ndơ nây mhĭk, mhĭk ngăn, ƀiă lah jêh păng dâk hăn păng tâm rnê ma păng nơm.$b$,true),
('bunong-vn','PRO',20,15,null,$b$Geh mah jêh ri ăp ntil lŭ khlay, ƀiă lah mpiăt gĭt mĭn âk jêng khlay ngăn ngên.$b$,true),
('bunong-vn','PRO',20,16,null,$b$Sŏk hom ao păng nchăm yor lah păng râng ma bunuyh bunăch, ăn păng geh ndơ chăm tơ lah păng râng ma bu ur êng.$b$,true),
('bunong-vn','PRO',20,17,null,$b$Ƀănh geh ma nau ndơm jêng njŭng ma bunuyh, ƀiă lah dăch dŭt trôm mbung păng bêng ma choih.$b$,true),
('bunong-vn','PRO',20,18,null,$b$Lĕ nau ŭch jêng nâp yor ma nau tâm chră, ƀư nau tâm lơh dơi gay ntĭm ma nau gĭt njrăng.$b$,true),
('bunong-vn','PRO',20,19,null,$b$Mbu nơm nkoch bri n'hi ƀlêp ƀlêr pơk mpơl nau ndâp, pô ri lơi tâm rnglăp ôh đah nơm hay ngơi.$b$,true),
('bunong-vn','PRO',20,20,null,$b$Tơ lah du huê bunuyh rak rtăp me mbơ̆ păng; ŭnh kađen păng mra nhhât tâm ntŭk ngo klĕng.$b$,true),
('bunong-vn','PRO',20,21,null,$b$Drăp ndơn gơnh geh ndal ir bơh ntơm bôk sa ơm mâu mra ăn tât nau ueh uĭn ôh ta nglĕ dŭt.$b$,true),
('bunong-vn','PRO',20,22,null,$b$Lơi lah ôh: “Gâp mra har plơng ma nau mhĭk”, gŭ kâp hom Yêhôva, Păng mra tâm rklaih may.$b$,true),
('bunong-vn','PRO',20,23,null,$b$Yêhôva mra tâm rmot ma rplay njing mâu di ôh. Jêh ri njing mâu di mâu ƀư maak ma Păng ôh.$b$,true),
('bunong-vn','PRO',20,24,null,$b$Yêhôva yơh ƀĭt gai nhuat bunuyh, pô nây mâm bunuyh dơi gĭt rbăng trong păng nơm?$b$,true),
('bunong-vn','PRO',20,25,null,$b$Jêng dăk bu sân yơh ma bunuyh mâu chrê ma nau păng ton nhhơr ăn ndơ kloh ueh, jêh ri pa kơi jêh nau păng ton ri mơ plơ̆ mĭn rvê tay đŏng.$b$,true),
('bunong-vn','PRO',20,26,null,$b$Du huê hađăch gĭt nau ƀư roh lơi phung mhĭk. Jêh ri păng ăn bu rvah jâng ndeh ta klơ phung nây.$b$,true),
('bunong-vn','PRO',20,27,null,$b$Huêng tâm kon bunuyh jêng ŭnh kađen Yêhôva, păng sek uănh tât ta ntŭk ndâp tâm trôm nuih n'hâm.$b$,true),
('bunong-vn','PRO',20,28,null,$b$Nau tâm rŏng jêh ri nau răp jăp king hađăch, sưng hađăch dơi jêng nâp yor tă nau tâm rŏng.$b$,true),
('bunong-vn','PRO',20,29,null,$b$Nau chrêk ma lơp jêng nau ktang phung bu klâu ndăm, ƀiă lah sŏk nglang mra jêng nau nkrơ̆ ma phung bu ranh.$b$,true),
('bunong-vn','PRO',20,30,null,$b$Khap sôt rmanh ƀư kloh nau djơh mhĭk, jêh ri nau bu dong ƀư kloh ntŭk ndâp tâm trôm nuih n'hâm.$b$,true),
('bunong-vn','PRO',21,1,null,$b$Nuih n'hâm hađăch jêng nâm bu du n'hor dak tâm ti Yêhôva, Yêhôva ăn păng hoch rlet ntŭk Păng ŭch.$b$,true),
('bunong-vn','PRO',21,2,null,$b$Lĕ rngôch trong du huê bunuyh jêng sŏng di tĭng măt păng nơm, ƀiă lah Yêhôva sek uănh nuih n'hâm.$b$,true),
('bunong-vn','PRO',21,3,null,$b$Ƀư nau sŏng jêh ri nau di jêng nau Yêhôva ŭch âk lơn ma ndơ ƀư brah.$b$,true),
('bunong-vn','PRO',21,4,null,$b$Măt uănh n'hao nơm, nuih n'hâm sưr rlau. Ŭnh kađen ma nơm kue, lĕ nau nây ăt jêng nau tih đŏng!$b$,true),
('bunong-vn','PRO',21,5,null,$b$Nau mĭn bunuyh gơih njŭn tât ma nau rmeh ler, bi ma nơm rluk ƀư ndal ir mra njŭn ma nau pưt.$b$,true),
('bunong-vn','PRO',21,6,null,$b$Drăp ndơ geh tă nau ngơi mƀruh jêng du nau dơm dam gơnh roh hêng ma phung tĭng joi nau khĭt.$b$,true),
('bunong-vn','PRO',21,7,null,$b$Nau djơh mhĭk phung kue mra dŭng đŏt nau rêh khân păng nơm, yor lah khân păng mâu ŭch ƀư nau di.$b$,true),
('bunong-vn','PRO',21,8,null,$b$Trong bunuyh tih jêng kue kuăt, ƀiă lah kan bunuyh kloh rsang jêng sŏng.$b$,true),
('bunong-vn','PRO',21,9,null,$b$Ueh lơn gŭ ta njônh chor ngih, ma đah gŭ du vâl ndrel ma du huê mơng tâm djrel.$b$,true),
('bunong-vn','PRO',21,10,null,$b$Bunuyh djơh gay kơnh ŭch nau mhĭk, păng mâu gĭt yô̆ ôh ma nơm pĭt meng păng.$b$,true),
('bunong-vn','PRO',21,11,null,$b$Tơ lah bu tâm rmal nơm bu mưch, bunuyh rluk mra jêng gĭt nau tơ lah bu ntĭm nti bunuyh gĭt nau, păng mra geh nau gĭt mĭn.$b$,true),
('bunong-vn','PRO',21,12,null,$b$Nơm Sŏng Ngăn sek uănh n'hêl nanê̆ ngih vâl bunuyh djơh mhĭk, Nơm nây nklơ̆ phung djơh tâm nau rêh ni.$b$,true),
('bunong-vn','PRO',21,13,null,$b$Mbu nơm nsêt tôr ma nau bunuyh o-ach nter, tơ lah bunuyh nây mra nter ăt mâu geh lĕ bunuyh mra plơ̆ sĭt lah.$b$,true),
('bunong-vn','PRO',21,14,null,$b$Ndơ ăn ma nau ndâp rthi nau ji nuih, jêh ri ăn ndơ blŏl ma nau ndâp dơi ƀư ăn djoh nau hâu ji nuih.$b$,true),
('bunong-vn','PRO',21,15,null,$b$Tơ lah ƀư nau di, nây jêng nau maak ăn ma phung mơih-rmên ƀiă lah jêng nau krit ăn ma phung ƀư nau mhĭk.$b$,true),
('bunong-vn','PRO',21,16,null,$b$Mbu moh du bơh trong nau gĭt rbăng mra gŭ rgum ta ntŭk phung khĭt.$b$,true),
('bunong-vn','PRO',21,17,null,$b$Mbu nđơr ir ma nau pâl rlưn mra jêng o ach, mbu ji hir ma ndrănh jêh ri dak play ôlivơ mâu mra jêng ndrŏng ôh.$b$,true),
('bunong-vn','PRO',21,18,null,$b$Bunuyh djơh jêng rnoh chuai ăn ma bunuyh sŏng, jêh ri bunuyh mƀruh rlăm ntrok ntŭk ma bunuyh mơih-rmên.$b$,true),
('bunong-vn','PRO',21,19,null,$b$Ueh lơn gŭ tâm ntŭk rngơt-rklăk, ma đah gŭ ndrel ma du huê bu ur vay mơng tâm djrel jêh ri hay ji nuih.$b$,true),
('bunong-vn','PRO',21,20,null,$b$Phung gĭt nau prăp drăp ndơ khlay jêh ri dak play ôlivơ tâm vâl păng, ƀiă lah bunuyh rluk sa lơi ăn lĕ ndơ păng geh.$b$,true),
('bunong-vn','PRO',21,21,null,$b$Mbu nơm tĭng joi nau sŏng jêh ri nau ueh mra saơ nau rêh, nau mơih-rmên jêh ri nau bu yơk.$b$,true),
('bunong-vn','PRO',21,22,null,$b$Bunuyh gĭt nau hao mpêr ƀon toyh phung janh ktang, jêh ri păng lơh rlâm ntŭk pôih khân păng nsing.$b$,true),
('bunong-vn','PRO',21,23,null,$b$Mbu moh mêm prăp trôm mbung jêh ri mpiăt păng mât huêng păng nơm klaih bơh nau uh ah.$b$,true),
('bunong-vn','PRO',21,24,null,$b$Bu ntơ “bunuyh vay mơng mưch” jêng nơm sưr jêh ri n'hao săk nơm, păng ƀư nau mƀruh jêh ri sưr rlau.$b$,true),
('bunong-vn','PRO',21,25,null,$b$Nau kơnh bunuyh ƀlao gay ŭch nkhĭt êng păng nơm, yor lah ti păng dun pah kan.$b$,true),
('bunong-vn','PRO',21,26,null,$b$Geh bunuyh kêng lôch nar knŏng gay ŭch geh ndơ dơm, ƀiă lah bunuyh sŏng ăn dơm mâu nhhuach ôh.$b$,true),
('bunong-vn','PRO',21,27,null,$b$Yêhôva tâm rmot ngăn ma ndơ phung ƀai ƀư brah, lơ hâu ma nây tơ lah khân păng nhhơr ma nau mĭn djơh mhĭk.$b$,true),
('bunong-vn','PRO',21,28,null,$b$Nơm nkoch mƀruh mra rai roh, ƀiă lah bunuyh tông bâr mra dơi ngơi mro.$b$,true),
('bunong-vn','PRO',21,29,null,$b$Bunuyh djơh jan lah ƀư janh, ƀiă lah bunuyh sŏng ƀư nâp rjăp trong păng nơm.$b$,true),
('bunong-vn','PRO',21,30,null,$b$Mâu dơi geh ôh nau blau mĭn mâu lah nau gĭt rbăng, kŏ mâu geh lĕ nau nchră dơi tâm rdâng đah Yêhôva.$b$,true),
('bunong-vn','PRO',21,31,null,$b$Bu ndrăp seh prăp ma nar tâm lơh, ƀiă lah Yêhôva mơ ăn nau dơi.$b$,true),
('bunong-vn','PRO',22,1,null,$b$Nau lư n'găr ueh jêng ueh lơn ma drăp ndơ âk; jêh ri nau bu vơt rom jêng khlay lơn ma prăk jêh ri mah.$b$,true),
('bunong-vn','PRO',22,2,null,$b$Phung ndrŏng jêh ri phung ndĭt trơi tâm mâp ndrel da dê; Yêhôva hŏ rhăk njêng lĕ bar khân păng.$b$,true),
('bunong-vn','PRO',22,3,null,$b$Bunuyh gĭt nau saơ da dê nau mhĭk djơh, jêh ri du krap. Ƀiă lah bunuyh rluk n'ho hăn rlet pa năp jêh ri dơn nau rêh ni.$b$,true),
('bunong-vn','PRO',22,4,null,$b$Nau nkhôm ma nau dêh rhêt jêh ri klach yơk ma Yêhôva jêng nau ndrŏng, nau bu yơk, jêh ri nau rêh.$b$,true),
('bunong-vn','PRO',22,5,null,$b$Lok rting jêh ri dăk sân gŭ ta trong bunuyh djơh, mbu mât njrăng huêng păng nơm mra der ngai bơh trong nây.$b$,true),
('bunong-vn','PRO',22,6,null,$b$Sâm nti du huê kon se jê̆ trong khân păng mra tĭng, jêh ri tơ lah păng ranh, păng mâu mra cha lơi ôh trong nây.$b$,true),
('bunong-vn','PRO',22,7,null,$b$Bunuyh ndrŏng jêng kôranh ma phung ndĭt trơi jêh ri mbu moh manh dăn jêng dĭk ma nơm ăn manh.$b$,true),
('bunong-vn','PRO',22,8,null,$b$Mbu nơm srih nau mâu di mra rek tât nau rêh ni. Jêh ri mâng rvĕ nau păng ji nuih mra pă (deh).$b$,true),
('bunong-vn','PRO',22,9,null,$b$Mbu nơm uănh ma nau yô̆ mra geh nau ueh lăng, yor lah păng tâm pă ăn ndơ sông sa păng ma phung o ach.$b$,true),
('bunong-vn','PRO',22,10,null,$b$Mprơh lơi bunuyh mơng mưch, pô ri nau tâm lah, tâm djrel mra roh; nau tâm rlăch jêh ri nau suai rak mra lôch.$b$,true),
('bunong-vn','PRO',22,11,null,$b$Mbu rŏng ma nuih n'hâm kloh rsang jêh ri ngơi ma nau yô̆ mra dơi jan jiăng đah hađăch.$b$,true),
('bunong-vn','PRO',22,12,null,$b$Măt Yêhôva mât mray bunuyh gĭt rbăng, ƀiă lah păng ngroh lơi nau phung ƀlêp ƀlêr ngơi.$b$,true),
('bunong-vn','PRO',22,13,null,$b$Bunuyh ƀlao lah: “Geh du mlâm yau mŭr pa dih ri? Gâp mra khĭt ta trong.”$b$,true),
('bunong-vn','PRO',22,14,null,$b$Trôm mbung bu ur văng tĭr jêng ntu jru ngăn, nơm Yêhôva ji nuih mra tŭp tâm trôm nây.$b$,true),
('bunong-vn','PRO',22,15,null,$b$Nuih n'hâm kon se bêng ma nau rluk, ƀiă lah nau nkra ma mâng mprơh nau rluk nây ăn ngai đah păng.$b$,true),
('bunong-vn','PRO',22,16,null,$b$Mbu nơm tŭn jot bunuyh ndĭt trơi gay ăn ndrŏng păng nơm, jêh ri blŏl ma bunuyh ndrŏng, lĕ bar mra jêng ndĭt trơi da dê.$b$,true),
('bunong-vn','PRO',22,17,null,$b$Rkêng tôr, jêh ri iăt hom nau phung blau mĭn ngơi, nti hom nau gĭt mĭn bơh gâp.$b$,true),
('bunong-vn','PRO',22,18,null,$b$Yor lah may mra maak tơ lah may djôt prăp nau nây tâm nuih n'hâm, jêh ri may dơi rŏ mro nau nây.$b$,true),
('bunong-vn','PRO',22,19,null,$b$Nar aơ gâp hŏ ăn ma may gĭt nau nây; gay ma may gĭt nsing ma Yêhôva.$b$,true),
('bunong-vn','PRO',22,20,null,$b$Mâu hĕ gâp hŏ chih jêh ma may pe jât ntil nau ngơi di jêng nau sâm nti nau gĭt mĭn.$b$,true),
('bunong-vn','PRO',22,21,null,$b$Nti ăn may gĭt nau di jêh ri nau nanê̆ ngăn, gay ăn may dơi plơ̆ lah ma nau n'hêl nanê̆ ma nơm prơh may hăn?$b$,true),
('bunong-vn','PRO',22,22,null,$b$Lơi sŏk ntŭng ôh ndô ndơ bunuyh o ach yor lah păng jêng nơm ndĭt trơi. Tâm ban đŏng lơi tŭn jot ôh nơm rêh ni ta mpông pêr.$b$,true),
('bunong-vn','PRO',22,23,null,$b$Yor lah Yêhôva mra koh dŏng mpeh khân păng, jêh ri Păng mra sŏk rhuăt ndơ phung pit in jêh ndô ndơ khân păng.$b$,true),
('bunong-vn','PRO',22,24,null,$b$Lơi ta ƀư mĭt jiăng ôh đah bunuyh janh, mâu lĕ hăn ndrel ma bunuyh gơnh ji nuih,$b$,true),
('bunong-vn','PRO',22,25,null,$b$klach lah may kơt tĭng trong păng, jêh ri huêng may mra geh dăk.$b$,false),
('bunong-vn','PRO',22,26,null,$b$Lơi jêng ôh nâm bu phung ton ƀư nau tâm rnglăp mâu lah jêng nơm râng an ma rnon bu.$b$,true),
('bunong-vn','PRO',22,27,null,$b$Tơ lah may mâu geh ndơ trok rnon, moh khlay ăn roh dơm bu sŏk sưng bêch may?$b$,true),
('bunong-vn','PRO',22,28,null,$b$Lơi ta trơn ôh n'har neh ơm kăl e phung chô che may hŏ tâm nal jêh.$b$,true),
('bunong-vn','PRO',22,29,null,$b$May lĕ saơ đŏng bunuyh gơih tâm nau kan păng pah? Păng mra gŭ pa năp phung hađăch, păng mâu mra gŭ ôh pa năp phung jê̆.$b$,true),
('bunong-vn','PRO',23,1,null,$b$Tơ lah may gŭ sông sa ndrel ma du huê kôranh chiă uănh, ăn may njrăng hom ma ndơ bu rep tra năp may,$b$,true),
('bunong-vn','PRO',23,2,null,$b$jêh ri bu dơm pêih ta trô ko may, tơ lah may jêng du huê hay sa.$b$,false),
('bunong-vn','PRO',23,3,null,$b$Lơi kơnh ôh ma ndơ sông sa kah păng, yor lah ndơ nây jêng ndơ sông sa bu ndơm.$b$,true),
('bunong-vn','PRO',23,4,null,$b$Lơi ƀư jêr ôh ma may nơm gay ŭch jêng ndrŏng, ăn may geh nau mĭn blau lơn ma nau nây,$b$,true),
('bunong-vn','PRO',23,5,null,$b$Yor lah tơ lah may treng uănh ma nau ndrŏng kuăng, pô ri păng hŏ mpăr roh jêh yor lah nau ndrŏng hŏ chăt nting năr ma păng nơm jêh ri nâm bu klang păng mpăr du rlet klơ trôk.$b$,false),
('bunong-vn','PRO',23,6,null,$b$Lơi ta sa ôh ndơ sông sa bunuyh geh măt uănh bu ma nau mhĭk, ăt mâu kơnh đŏng ma ndơ sông sa kah păng,$b$,true),
('bunong-vn','PRO',23,7,null,$b$yor lah nâm bu păng mĭn tâm nuih n'hâm mâm nau, pô nây đŏng nau păng lah: “Sa, nhêt hom,” ƀiă lah nuih n'hâm păng mâu mĭn pô nây ôh.$b$,false),
('bunong-vn','PRO',23,8,null,$b$May mra hok ndơ may sa jêh, jêh ri nau may ngơi ueh mra roh dơm dam.$b$,true),
('bunong-vn','PRO',23,9,null,$b$Lơi ngơi nglăp ôh tâm tôr bunuyh rluk, yor lah păng mra mưch rmot ma nau may ngơi.$b$,true),
('bunong-vn','PRO',23,10,null,$b$Lơi ta trơn ôh n'har neh ơm, jêh ri lơi lăp ôh tâm mir phung kon đơi,$b$,true),
('bunong-vn','PRO',23,11,null,$b$yor lah Nơm Tâm Chuai khân păng jêng brah, mra koh dŏng dôih khân păng rŏ đah may.$b$,false),
('bunong-vn','PRO',23,12,null,$b$Ăn gơih lĕ nuih n'hâm joi nau nti, jêh ri rkêng tôr iăt ma nau gĭt mĭn âk.$b$,true),
('bunong-vn','PRO',23,13,null,$b$Lơi ta mƀơk ling ôh nau nkra kon may; nđâp tơ lah may rpăt păng ma mâng rvĕ, păng mâu mra khĭt ôh.$b$,true),
('bunong-vn','PRO',23,14,null,$b$Tơ lah may dong păng ma mâng rvĕ, nanê̆ may mra tâm rklaih huêng păng klaih bơh Ƀon Phung Khĭt.$b$,true),
('bunong-vn','PRO',23,15,null,$b$Hơi kon, tơ lah nuih n'hâm may geh nau blau mĭn, pô ri nuih n'hâm gâp mra răm rhơn.$b$,true),
('bunong-vn','PRO',23,16,null,$b$Proch klơm gâp mra maak ngăn, tơ lah mpiăt may ngơi nau di.$b$,true),
('bunong-vn','PRO',23,17,null,$b$Lơi ăn nuih n'hâm may kơnh ma phung tih ôh, ƀiă lah ăn may klach yơk ma Yêhôva ăp nar.$b$,true),
('bunong-vn','PRO',23,18,null,$b$N'hêl nanê̆ ô klak may mra geh nau nkhôm, jêh ri nau may kâp gân mâu mra roh hêng ôh.$b$,true),
('bunong-vn','PRO',23,19,null,$b$Hơi kon, rkêng tôr iăt hom jêh ri dơi jêng blau mĭn, njŭn leo nuih n'hâm tâm trong di:$b$,true),
('bunong-vn','PRO',23,20,null,$b$Lơi tâm rnglăp ôh ndrel ma phung mơng nhêt ndrănh, mâu lah đah phung hay sa puăch,$b$,false),
('bunong-vn','PRO',23,21,null,$b$yor lah bunuyh mơng nhŭl ndrănh jêh ri hay sa mra jêng ndĭt trơi. Bi ma bunuyh bêch mro mra nsoh n'gut ndơ sat rơch.$b$,false),
('bunong-vn','PRO',23,22,null,$b$Rkêng tôr iăt ma mbơ̆ may, nơm ăn may rêh; lơi mưch rmot ôh ma mê̆ may tơ lah păng lĕ ranh jêh.$b$,true),
('bunong-vn','PRO',23,23,null,$b$Rvăt hom nau nanê̆ ngăn, nau blau mĭn, nau ntĭm nti, jêh ri nau gĭt rbăng; lơi ta tăch lơi ôh.$b$,true),
('bunong-vn','PRO',23,24,null,$b$Mbơ̆ bunuyh sŏng mra răm maak toyh ngăn, mbu nơm geh du huê kon blau mĭn mra răm rhơn ma păng.$b$,true),
('bunong-vn','PRO',23,25,null,$b$Ăn mê̆ mbơ̆ may geh nau rhơn, ăn nơm deh ma may geh nau maak.$b$,true),
('bunong-vn','PRO',23,26,null,$b$Hơi kon, jao hom nuih n'hâm may ma gâp, jêh ri ăn măt may djôt prăp trong gâp.$b$,true),
('bunong-vn','PRO',23,27,null,$b$Yor lah bu ur văng tĭr jêng ntu jru, jêh ri bu ur ka n'hong jêng du ntu huêt.$b$,true),
('bunong-vn','PRO',23,28,null,$b$Păng gŭ kâp nâm bu du huê bunuyh ntŭng, jêh ri păng ăn âk bunuyh cha lơi nau chroh.$b$,true),
('bunong-vn','PRO',23,29,null,$b$Mbu nơm geh nau rêh ni? Mbu nơm geh nau rngot? Mbu nơm tâm djrel? Mbu nơm ngơi ƀrôk? Mbu nơm rmanh mâu gĭt mbah tă păng geh nau sôt rmanh? Mbu nơm geh măt chăng?$b$,true),
('bunong-vn','PRO',23,30,null,$b$Phung gŭ jŏ grem êp ndrănh, phung hăn nhêt ndrănh bu tâm rlŭk.$b$,true),
('bunong-vn','PRO',23,31,null,$b$Lơi ta n'gơr uănh ôh ma ndrănh tơ lah păng lĕ chăng jêh, dôl păng rsang tâm kachok jêh ri bu dơi rvăn njŭng ngăn.$b$,true),
('bunong-vn','PRO',23,32,null,$b$Dăch dŭt păng kăp nâm bu bêh, jêh ri păng chôk nâm bu bêh geh kăch.$b$,true),
('bunong-vn','PRO',23,33,null,$b$Măt may mra uănh ma phung bu ur văng tĭr; nuih n'hâm may ŭch mĭn mra ngơi nau ƀơ̆ ƀơch.$b$,true),
('bunong-vn','PRO',23,34,null,$b$May mra jêng nâm bu du huê bunuyh lâng bêch ta nklang dak mƀŭt, nâm bu du huê bunuyh gŭ tâm drŏng klơ chiông du mlâm meh.$b$,true),
('bunong-vn','PRO',23,35,null,$b$May mra lah: “Bu dong gâp, ƀiă lah gâp mâu tăng ji ôh; Bu mbang gâp, ƀiă lah gâp mâu dơi gĭt. Tơ lah gâp lĕ kah rngăl? Gâp mra joi nhêt tay đŏng.$b$,true),
('bunong-vn','PRO',24,1,null,$b$Lơi tâm jreh ôh đah phung ƀư djơh, mâu lĕ gay ŭch gŭ ndrel ma khân păng.$b$,true),
('bunong-vn','PRO',24,2,null,$b$Yor lah nuih n'hâm khân păng tâm chră ƀư nau djơh mhĭk jêh ri mpiăt khân păng ngơi nau uh ah.$b$,true),
('bunong-vn','PRO',24,3,null,$b$Ma nau blau mĭn bu dơi ndâk ngih, jêh ri ma nau gĭt rbăng păng jêng nâp.$b$,true),
('bunong-vn','PRO',24,4,null,$b$Ma nau blau mĭn âk jrô bêng ma ăp ntil drăp ndơ khlay jêh ri ueh.$b$,true),
('bunong-vn','PRO',24,5,null,$b$Du huê bunuyh blau mĭn geh nau ktang jêh ri bunuyh blau mĭn âk hao ktang lơn.$b$,true),
('bunong-vn','PRO',24,6,null,$b$Yor lah ma nau phung gĭt nau nchră may tâm lơh, jêh ri geh âk bunuyh tâm chră geh nau dơi.$b$,true),
('bunong-vn','PRO',24,7,null,$b$Nau blau mĭn jêng jru ir ma bunuyh rluk, păng mâu hă mbung ôh ta ntŭk mpông pêr.$b$,true),
('bunong-vn','PRO',24,8,null,$b$Mbu nơm mĭn mro ƀư nau mhĭk, bu ntơ păng du huê bunuyh joi nau mhĭk.$b$,true),
('bunong-vn','PRO',24,9,null,$b$Nau mĭn ŭch ƀư bơh nau rluk jêng nau tih jêh ri bunuyh mưch jêng nơm bu tâm rmot.$b$,true),
('bunong-vn','PRO',24,10,null,$b$Tơ lah rdja nuih ta nar rêh ni, nau ktang may jê̆ dơm.$b$,true),
('bunong-vn','PRO',24,11,null,$b$Koh dŏng hom phung bu njŭn ma nau khĭt, tâm rklaih hom phung hăn rlet ntŭk bu nkhĭt.$b$,true),
('bunong-vn','PRO',24,12,null,$b$Tơ lah may lah: “Aơ, hên mâu gĭt ôh nau nây,” mâu hĕ di Nơm sek uănh nuih n'hâm lĕ saơ nau nây? Mâu hĕ di Nơm chiă uănh huêng may lĕ gĭt nau nây? Jêh ri păng mra mplơ̆ ma ăp nơm tĭng nâm kan păng ƀư.$b$,true),
('bunong-vn','PRO',24,13,null,$b$Hơi kon, sa hom dak sŭt, yor lah păng jêng ueh, du mpơng sŭt jêng njŭng ma trôm mbung may.$b$,true),
('bunong-vn','PRO',24,14,null,$b$Ăn may gĭt nau blau mĭn tâm ban pô nây đŏng jêng khlay ma huêng may. Tơ lah may dơi saơ joi păng, may mra geh nau ueh maak du nar kăndơ̆ . Jêh ri nau may kâp gân mâu mra roh hêng ôh.$b$,true),
('bunong-vn','PRO',24,15,null,$b$Lơi ƀư nâm bunuyh djơh gŭ kâp ta ngih bunuyh sŏng, lơi ƀư rai ôh ntŭk păng gŭ,$b$,true),
('bunong-vn','PRO',24,16,null,$b$Yor lah bunuyh sŏng nđâp tơ lah cha lôt pơh tơ̆ , păng mra dâk tay đŏng, ƀiă lah nau rêh ni mra ƀư rai phung djơh.$b$,false),
('bunong-vn','PRO',24,17,null,$b$Lơi ta răm rhơn ôh tơ lah nơm rlăng may cha lôt, lơi ăn nuih n'hâm may hâk răm ôh tơ lah păng lĕ bu n'glưh;$b$,true),
('bunong-vn','PRO',24,18,null,$b$Klach lah Yêhôva mra saơ nau nây jêh ri mâu maak ôh, jêh nây păng mâu hôm ji nuih đŏng ôh ma păng.$b$,false),
('bunong-vn','PRO',24,19,null,$b$Lơi ta ji nuih biănh ôh yor phung ƀư nau mhĭk, lơi kơnh ma phung djơh ôh.$b$,true),
('bunong-vn','PRO',24,20,null,$b$Yor lah bunuyh djơh mâu mra gŭ jŏ ôh, ŭnh kađen phung djơh mra nhhât.$b$,true),
('bunong-vn','PRO',24,21,null,$b$Hơi kon, ăn may klach yơk ma Yêhôva jêh ri ma hađăch, lơi tâm rnglăp ôh đah phung tâm rdâng đah khân păng.$b$,true),
('bunong-vn','PRO',24,22,null,$b$Yor lah khân păng mra ƀư rai khân ô băl ƀât lât dơm, jêh ri mbu nơm gĭt nau rêh ni mra tât ma phung aơ phung ri?$b$,true),
('bunong-vn','PRO',24,23,null,$b$Nau aơ tâm ban đŏng jêng nau phung blau mĭn ngơi: Mâu ueh ôh kôranh phat dôih gŭ mpeh du ding.$b$,true),
('bunong-vn','PRO',24,24,null,$b$Mbu nơm lah ma bunuyh djơh: “May mâu tih ôh,” phung ƀon lan mra rak rtăp, jêh ri phung băl mpôl bunuyh mra tâm rmot ma păng.$b$,true),
('bunong-vn','PRO',24,25,null,$b$Ƀiă lah phung nduyh phung djơh mra geh nau maak, jêh ri bu mra mât ton nau ueh lăng ma khân păng.$b$,true),
('bunong-vn','PRO',24,26,null,$b$Mbu nơm plơ̆ lah ma nau di, jêng nâm bu nau chŭm ta trôm mbung.$b$,true),
('bunong-vn','PRO',24,27,null,$b$Nkra ăn lôch kan may pa dih, muyh jik hom mir may; jêh ta nây ăn may ndâk ngih may.$b$,true),
('bunong-vn','PRO',24,28,null,$b$Lơi ta jêng nơm tâm phong ma nơm chiau meng may mâu geh nau ôh, lơi ngơi nau ndơm bu ôh.$b$,true),
('bunong-vn','PRO',24,29,null,$b$Lơi lah ôh: “Gâp mra ƀư ma păng nâm bu păng hŏ ƀư ma gâp, gâp mra har plơng ma păng tĭng nâm nau păng ƀư jêh.”$b$,true),
('bunong-vn','PRO',24,30,null,$b$Gâp hăn rgăn jêh mir du huê bunuyh ƀlao, rgăn đang play kriăk ƀâu du huê bunuyh mâu ŭch uănh treng ôh;$b$,true),
('bunong-vn','PRO',24,31,null,$b$jêh ri ta aơ, lok dâr lam mir nây, me lok nkâm lam klơ neh; jêh ri mpêr lŭ lĕ rlâm jêh.$b$,false),
('bunong-vn','PRO',24,32,null,$b$Gâp treng uănh, jêh ri gŭ nklân; gâp saơ jêh ri ăn gâp nti.$b$,true),
('bunong-vn','PRO',24,33,null,$b$Bêch du pêp, rlu ƀât lât, ut ti gay bêch ƀât lât,$b$,true),
('bunong-vn','PRO',24,34,null,$b$pô nây nau o ach mra tât ma may nâm bu du huê bunuyh ntŭng, jêh ri nau pưt nâm bu du huê bunuyh djôt ndơ tâm lơh.$b$,false),
('bunong-vn','PRO',25,1,null,$b$Aơ tâm ban đŏng jêng nau hôr bơh Y-Salômôn, phung oh mon Y-Hêsêkia hađăch phung Yuđa kơt chih tay đŏng:$b$,true),
('bunong-vn','PRO',25,2,null,$b$Nau Brah Ndu pôn du nau jêng nau chrêk ma lơp ma păng, nau phung hađăch sek uănh joi gay gĭt rbăng nau nây jêng nau chrêk rmah ma khân păng.$b$,false),
('bunong-vn','PRO',25,3,null,$b$Trôk prêh ndah nâm âk jêh ri ndah nâm jru neh ntu, tâm ban pô nây đŏng bu mâu dơi sek uănh nuih n'hâm phung hađăch.$b$,true),
('bunong-vn','PRO',25,4,null,$b$Sŏk hom ek prăk jêh ri nơm tŏ geh ndơ dŏng ƀư ngan grưng.$b$,true),
('bunong-vn','PRO',25,5,null,$b$Sŏk lơi phung djơh mhĭk bơh ta năp hađăch jêh ri sưng hađăch păng mra jêng nâp ma nau sŏng srăng.$b$,true),
('bunong-vn','PRO',25,6,null,$b$Lơi ta n'hao êng may nơm ôh ta năp hađăch, mâu lah gŭ tâm ntŭk phung lư n'găr;$b$,true),
('bunong-vn','PRO',25,7,null,$b$yor lah ueh lơn tơ lah păng lah ma may “Hao hom ta aơ,” ma nau păng ntrŭnh lơi may ăn dêh pa năp măt du huê kôranh.$b$,false),
('bunong-vn','PRO',25,8,null,$b$Moh nau may lĕ saơ ma măt may nơm lơi ir ndal nkoch ôh ma kôranh phat dôih, yor lah kêng dăch dŭt moh may mra ƀư tơ lah nơm chiau meng may nkoch n'hêl nanê̆ nau êng jêh ri ƀư bêk may?$b$,true),
('bunong-vn','PRO',25,9,null,$b$Tơ lah may tâm dun nau may đah nơm chiau meng may lơi ta mpơl ôh nau ndâp du huê bu êng,$b$,true),
('bunong-vn','PRO',25,10,null,$b$Klach lah nơm tăng nau may ngơi ƀư bêk may, jêh ri nau lư mhĭk may bu kah gĭt ƀa ƀơ.$b$,false),
('bunong-vn','PRO',25,11,null,$b$Nau ngơi ma nau di, jêng rplay mah lĭr tâm prăk.$b$,true),
('bunong-vn','PRO',25,12,null,$b$Nau nơm blau mĭn nduyh ma nơm gŭ iăt, jêng nâm bu rgên mah, mâu lah ndơ nkrơ̆ ƀư ma mah.$b$,true),
('bunong-vn','PRO',25,13,null,$b$Du huê nơm ntuh bâr răp jăp đah nơm prơh păng hăn. Jêng nâm bu nau nđik bơh pler tâm nar yan kăch. Yor lah păng ƀư maak huêng kôranh păng.$b$,true),
('bunong-vn','PRO',25,14,null,$b$Du huê bunuyh ntưih ndơ ăn bu ƀiă lah mâu yŏng ăn ôh jêng nâm bu ndâr tŭk geh sial mâu geh dak mih ôh.$b$,true),
('bunong-vn','PRO',25,15,null,$b$Yor nau nsrôih ri mơ bu dơi ntrôl kôranh chiă uănh, jêh ri mpiăt ngơi rdơ̆ rbăn dơi ăn deh nting.$b$,true),
('bunong-vn','PRO',25,16,null,$b$Tơ lah may saơ dak sŭt, knŏng sa ăn man bah lêu. Klach lah may sa âk ir jêh ri mra hok.$b$,true),
('bunong-vn','PRO',25,17,null,$b$Jâng may lơi ir hăn tât mro ma ngih vâl nơm chiau meng may ôh. Klach lah păng mra dĭl jêh ri nuih ma may.$b$,true),
('bunong-vn','PRO',25,18,null,$b$Du huê bunuyh ngơi nchơt ma nơm chiau meng păng jêng nâm bu me nôp, du mlâm đao, mâu lah hăr mplanh.$b$,true),
('bunong-vn','PRO',25,19,null,$b$Nau nsing ma nơm ƀlêp ƀlêr tâm nar uh ah jêng nâm bu du mlâm sêk pă mâu lah mbĭr du đah jâng.$b$,true),
('bunong-vn','PRO',25,20,null,$b$Mbu nơm mprơ ma bunuyh geh nuih n'hâm rngot jêng nâm bu nơm djôt rdu lơi ao mbâl dôl nar ji kăt, jêh ri nkhŭt dak srat ta ntŭk sôt.$b$,true),
('bunong-vn','PRO',25,21,null,$b$Tơ lah nơm rlăng may ji ngot, ăn ma păng ndơ sông sa, jêh ri tơ lah păng ji hir, may ăn ma păng dak nhêt.$b$,true),
('bunong-vn','PRO',25,22,null,$b$Pô ri may mra bun sa-ônh rnga ta klơ bôk păng, jêh ri Yêhôva mra ăn nau nkhôm ma may.$b$,true),
('bunong-vn','PRO',25,23,null,$b$Nâm bu sial tă bơh dor pa lơ ăn trôk mih tâm ban pô nây đŏng mpiăt ngơi kek ăn bu ji nuih.$b$,true),
('bunong-vn','PRO',25,24,null,$b$Ueh lơn gŭ ta njônh chor ngih ma đah gŭ tâm ngih ndrel ma du huê bu ur vay mơng tâm djrel.$b$,true),
('bunong-vn','PRO',25,25,null,$b$Nau mhe mhan ueh bơh bri ngai jêng nâm bu dak nđik ma du huê bunuyh ji hir.$b$,true),
('bunong-vn','PRO',25,26,null,$b$Bunuyh sŏng tŭp tâm nau bunuyh mhĭk ndơm jêng nâm bu ntu dak rkhăl mâu lah tu dak bu ƀư ƀơ̆ .$b$,true),
('bunong-vn','PRO',25,27,null,$b$Sa dak sŭt âk ir mâu ueh ôh, pô nây đŏng tơ lah bunuyh joi tâm rnê ma păng nơm.$b$,true),
('bunong-vn','PRO',25,28,null,$b$Du huê bunuyh mâu blau chiă uănh nuih n'hâm păng nơm jêng nâm du rplay ƀon toyh bu ƀư rlâm lơi mpêr.$b$,true),
('bunong-vn','PRO',26,1,null,$b$Nau chrêk rmah mâu tâm di ôh ăn ma bunuyh rluk, nâm bu pler tâm yan ta vai, mâu lah mih tâm yan kăch.$b$,true),
('bunong-vn','PRO',26,2,null,$b$Nâm bu sĭm srai, nâm bu rlêng mpăr her tâm ban pô nây đŏng nau rak rtăp mâu geh nau mâu mra tât ôh.$b$,true),
('bunong-vn','PRO',26,3,null,$b$Mâng rvĕ prăp ma seh, loih gang prăp ma seh bri, jêh ri mâng nê̆ prăp ma chŭr kuyh phung rluk!$b$,true),
('bunong-vn','PRO',26,4,null,$b$Lơi hôm ơơh tông (plơ̆ lah) ôh ma bunuyh rluk tĭng nâm nau rluk păng, klach lah may nơm jêng hêng nâm bu păng.$b$,true),
('bunong-vn','PRO',26,5,null,$b$Plơ̆ sĭt lah hom ma bunuyh rluk tĭng nâm nau rluk păng, klach lah păng kơp păng nơm jêng gĭt nau tĭng păng nơm lah.$b$,true),
('bunong-vn','PRO',26,6,null,$b$Mbu nơm nsing ma bunuyh rluk leo nau nkoch ma bu, tâm ban ma koh glăch jâng păng nơm jêh ri nhêt rvăn nau rai yot.$b$,true),
('bunong-vn','PRO',26,7,null,$b$Nau ngơi hôr tâm trôm mbung phung rluk, tâm ban nâm bu jâng kuet mâu blau hăn ôh.$b$,true),
('bunong-vn','PRO',26,8,null,$b$Mbu nơm yơk ma du huê bunuyh rluk jêng nâm bu kât du găr lŭ ta rse ksu van pănh.$b$,true),
('bunong-vn','PRO',26,9,null,$b$Nau ngơi hôr tâm trôm mbung phung rluk jêng nâm bu tôt lok ta ti du huê bunuyh nhŭl ndrănh.$b$,true),
('bunong-vn','PRO',26,10,null,$b$Mbu nơm nkhôm bunuyh rluk jêh ri bu năch trong, tâm ban nâm bu du huê bunuyh pănh na ƀư rmanh lĕ ngôch bunuyh.$b$,true),
('bunong-vn','PRO',26,11,null,$b$Du huê bunuyh rluk plơ̆ ƀư nau rluk đŏng jêng nâm bu du mlâm so plơ̆ sa tay ndơ păng hok jêh.$b$,true),
('bunong-vn','PRO',26,12,null,$b$May saơ lĕ du huê bunuyh kơp păng nơm jêng bunuyh blau mĭn, bunuyh rluk hôm e khlay lơn ma păng nây.$b$,true),
('bunong-vn','PRO',26,13,null,$b$Bunuyh ƀlao lah: “Geh du mlâm yau mŭr gŭ ta trong, geh du mlâm yau mŭr nsong tâm trong ro!”$b$,true),
('bunong-vn','PRO',26,14,null,$b$Nâm bu mbong mpông rvah ta lăk lê tâm khan păng, pô nây đŏng bunuyh ƀlao rlĭ rlang ta klơ sưng bêch păng.$b$,true),
('bunong-vn','PRO',26,15,null,$b$Bunuyh ƀlao mbŭk ti păng tâm ngan pala; jêh ri ƀlao ngăn nsiăm ô băl rlet ma trôm mbung.$b$,true),
('bunong-vn','PRO',26,16,null,$b$Bunuyh ƀlao kơp êng păng nơm blau mĭn lơn ma pơh nuyh dơi plơ̆ lah ma nau di găl ngăn.$b$,true),
('bunong-vn','PRO',26,17,null,$b$Nơm hăn nsong prot rgăn ji nuih rƀiah ma nau bu tâm djrel mâu tât ôh ma păng, tâm ban nâm bu bunuyh têk mphâk tôr so.$b$,true),
('bunong-vn','PRO',26,18,null,$b$Nâm bu bunuyh brŭt rluk klŭp ŭnh rnga, hăr kŭ jêh ri nau khĭt.$b$,true),
('bunong-vn','PRO',26,19,null,$b$Pô nây đŏng mbu moh ndơm nơm chiau meng păng, jêh ri lah: “Knŏng gâp pâl dơm!”$b$,true),
('bunong-vn','PRO',26,20,null,$b$Ŭnh nhhât yor mâu tŏng long; ta ntŭk mâu geh ôh bunuyh nkoch bri nsak, pô ri nau tâm djrel ăt mâu geh lĕ.$b$,true),
('bunong-vn','PRO',26,21,null,$b$Nâm bu ŭnh rnga sa sa ônh jêh ri ŭnh sa long, pô nây đŏng bunuyh vay mơng tâm djrel nsônh nau tâm rlăch.$b$,true),
('bunong-vn','PRO',26,22,null,$b$Nau nơm nkoch bri nsak ngơi jêng nâm bu ndơ sông sa kah, păng lăp tât ta proch khŭng.$b$,true),
('bunong-vn','PRO',26,23,null,$b$Nâm bu yăng ueh mbĭr pa dih, tâm ban pô nây đŏng nau ngơi ueh tă bơh trôm nuih n'hâm mhĭk.$b$,true),
('bunong-vn','PRO',26,24,null,$b$Bunuyh biănh rmot bu n'hi ngơi nau ueh, ƀiă lah tâm trôm nuih n'hâm plĕch nau ngơi ndơm.$b$,true),
('bunong-vn','PRO',26,25,null,$b$Tơ lah păng ngơi ma nau njŭng, lơi ta iăt păng ôh, yor lah geh pơh ntil nau bu tâm rmot tâm nuih n'hâm păng.$b$,true),
('bunong-vn','PRO',26,26,null,$b$Nđâp tơ lah păng pôn nau tâm rmot đah nau ndơm, nau djơh mhĭk păng mra mpơl ntŭk phung tâm rƀŭn.$b$,true),
('bunong-vn','PRO',26,27,null,$b$Mbu nơm kuyh ntu mra tŭp tâm trôm ntu nây, mbu moh rlă lŭ, lŭ mra ntŭn tay păng.$b$,true),
('bunong-vn','PRO',26,28,null,$b$Mpiăt mƀruh tâm rmot ma phung păng suai rak, jêh ri trôm mbung ngơi njĭp n'hi ƀư nau rai yot.$b$,true),
('bunong-vn','PRO',27,1,null,$b$Lơi tâm rnê ôh may nơm ma nar ôi taơ, yor lah may mâu gĭt ôh moh mra tât nar ôi taơ.$b$,true),
('bunong-vn','PRO',27,2,null,$b$Ăn bu êng rnê ma may, mâu di ôh ma trôm mbung may nơm; du huê bu năch, mâu di ôh mpiăt may nơm.$b$,true),
('bunong-vn','PRO',27,3,null,$b$Lŭ jêng jâk, jêh ri choih jêng jâk đŏng, ƀiă lah nau bunuyh rluk ji nuih jêng jâk lơn ma lĕ bar.$b$,true),
('bunong-vn','PRO',27,4,null,$b$Nau ji nuih djơh mhĭk ngăn, jêh ri nau nuih jêng nâm bu dak rdŭl, ƀiă lah mbu moh dơi dơn nau mâu nach?$b$,true),
('bunong-vn','PRO',27,5,null,$b$Nau nduyh tra năp măt khlay lơn ma đah nau rŏng pôn ndâp.$b$,true),
('bunong-vn','PRO',27,6,null,$b$Nau du huê mĭt jiăng ƀư sôt yor nau păng rŏng nanê̆ ngăn. Bi ma nơm rlăng chŭm he jêng nau ndơm.$b$,true),
('bunong-vn','PRO',27,7,null,$b$Mbu moh hơm jêh jot rchal mpơng sŭt tâm dâng jâng, ƀiă lah mbu moh ji ngot nđâp ndơ tăng jêng njŭng ma păng.$b$,true),
('bunong-vn','PRO',27,8,null,$b$Nâm bu sĭm du ngai đah rsuăn păng, tâm ban pô nây đŏng bunuyh mblêng tă bơh ngih păng.$b$,true),
('bunong-vn','PRO',27,9,null,$b$Dak ƀâu kah jêh ri ndơ ƀâu kah su n'hôl ăn nuih n'hâm păng răm maak; Nau ntĭm nti ueh bơh mĭt jiăng jêng khlay nau nchră ăn he.$b$,true),
('bunong-vn','PRO',27,10,null,$b$Lơi ta cha lơi ôh mĭt jiăng may jêh ri mĭt jiăng mbơ̆ may, jêh ri lơi ta hăn ôh tât ma ngih vâl oh nâu may dôl may geh nau uh ah. Du huê nơm chiau meng gŭ dăch jêng ueh lơn đah oh nâu gŭ ngai.$b$,true),
('bunong-vn','PRO',27,11,null,$b$Hơi kon gâp, ăn may geh nau blau mĭn, jêh ri ƀư maak ma nuih n'hâm gâp, pô nây gay gâp dơi plơ̆ lah ma mbu nơm nduyh gâp.$b$,true),
('bunong-vn','PRO',27,12,null,$b$Bunuyh gĭt njrăng saơ lor nau mhĭk jêh ri du krap, ƀiă lah phung rluk n'ho hăn ran pa năp jêh ri dơn nau rêh ni.$b$,true),
('bunong-vn','PRO',27,13,null,$b$Sŏk hom ao bunuyh ƀư nau râng ma du huê bu năch, jêh ri ăn păng geh ndơ nchăm yor lah păng râng an ma bu ur văng tĭr.$b$,true),
('bunong-vn','PRO',27,14,null,$b$Tơ lah du huê bunuyh kah rngăl ơm ôi gay mât ton nau ueh lăng ma mĭt jiăng păng ma bâr ngơi huy, nau mât ton bu mra kơp jêng nơm rak rtăp.$b$,true),
('bunong-vn','PRO',27,15,null,$b$Du huê bu ur vay mơng tâm djrel, tâm ban nâm bu nteh truh dak mro dôl bri mih.$b$,true),
('bunong-vn','PRO',27,16,null,$b$Mbu nơm gay ŭch buay păng jêng nâm bu buay sial jêh ri nâm bu sŏk mpang ti dơ djôt dak play Ôlivơ.$b$,true),
('bunong-vn','PRO',27,17,null,$b$Du huê bunuyh ŭch đăp bunuyh chiau meng, tâm ban nâm bu loih tôl ăn hơr ndrăng loih.$b$,true),
('bunong-vn','PRO',27,18,null,$b$Mbu nơm mât tơm play rvi mra sa play păng, jêh ri mbu nơm njrăng kôranh păng mra geh nau yơk.$b$,true),
('bunong-vn','PRO',27,19,null,$b$Nuih n'hâm bunuyh tâm mpơl mâm muh măt păng jêng; tâm ban nâm bu muh măt du huê bunuyh chrâng tâm dak.$b$,true),
('bunong-vn','PRO',27,20,null,$b$Ƀon Phung Khĭt jêh ri Trôm Jru mâu hŏ blau hơm ôh, tâm ban pô nây lĕ măt bunuyh kŏ mâu blau dŭt đŏng.$b$,true),
('bunong-vn','PRO',27,21,null,$b$Ntŭk kret ăn lêk gay prăp ƀư chrêk prăk, jêh ri năk ŭnh gay prăp ƀư chrêk mah; ƀiă lah bu sek uănh du huê bunuyh tĭng nâm nau bu tâm rnê ma păng.$b$,true),
('bunong-vn','PRO',27,22,null,$b$Nđâp tơ lah may sŏk rnai juh bunuyh rluk tâm mpăl n'hanh ma phe, pô ri nau rluk păng mâu mra luh du ôh tă bơh păng.$b$,true),
('bunong-vn','PRO',27,23,null,$b$Ăn may gĭt năl mâm phung biăp may jêng, ăn may chiăp mât ăn ueh ndrôk may.$b$,true),
('bunong-vn','PRO',27,24,null,$b$Yor lah nau ndrŏng mâu gŭ mro mrăng ôh kŏ mâu đŏng nau jêng hađăch mra gŭ n'ho ro.$b$,true),
('bunong-vn','PRO',27,25,null,$b$Tơ lah gơ̆ kro lĕ roh hêt, gơ̆ mhe chăt luh hon tay, jêh ri gơ̆ klơ yôk bu dơi rek nsĭt tay.$b$,true),
('bunong-vn','PRO',27,26,null,$b$Rsau biăp kon mra ăn may dŏng ƀư ao jâr ma may, jêh ri be nkuăng may mra rvăt mir.$b$,true),
('bunong-vn','PRO',27,27,null,$b$May mra geh dak toh be tŏng ma ndơ may sông sa, nđâp ma phung bunuyh tâm ngih may, jêh ri ma phung oh mon bu ur may.$b$,true),
('bunong-vn','PRO',28,1,null,$b$Bunuyh djơh nchuăt du nđâp lah mâu geh ôh bunuyh tĭng păng, bi bunuyh sŏng gŭ kơ̆ ng nâm bu yau mŭr.$b$,true),
('bunong-vn','PRO',28,2,null,$b$Du bri dak yor geh nau tâm rdâng geh âk kôranh chiă uănh êng êng, ƀiă lah yor geh bunuyh gĭt mĭn jêh ri gĭt rbăng, bri dak dơi nâp rjăp jŏ jong.$b$,true),
('bunong-vn','PRO',28,3,null,$b$Du huê bunuyh ndĭt trơi chiă uănh tŭn jot phung rêh ni jêng nâm bu dak mih ntâng ƀư rai lĕ ndơ tuch tăm.$b$,true),
('bunong-vn','PRO',28,4,null,$b$Phung mâu tông ôh ma nau vay tâm rnê ma phung djơh; bi ma phung djôt prăp nau vay tâm rdâng đah khân păng.$b$,true),
('bunong-vn','PRO',28,5,null,$b$Bunuyh djơh mhĭk mâu gĭt rbăng ôh nau di, ƀiă lah bunuyh joi Yêhôva gĭt rbăng lĕ.$b$,true),
('bunong-vn','PRO',28,6,null,$b$Ach o kđôi ƀiă lah gŭ rêh tâm nau sŏng srăng jêng ueh lơn ma nơm ndrŏng chuat tâm trong tih.$b$,true),
('bunong-vn','PRO',28,7,null,$b$Mbu nơm djôt prăp nau vay jêng du huê kon gĭt mĭn; bi ma nơm tâm rnglăp đah phung blă blơ ƀư bêk mbơ̆ păng.$b$,true),
('bunong-vn','PRO',28,8,null,$b$Mbu nơm n'hao nau ndrŏng păng ma nau sa kao rlau keh, nâm bu ntĭt mkrem prăp prăk nây ăn ma bunuyh geh nuih n'hâm yô̆ ma phung o ach.$b$,true),
('bunong-vn','PRO',28,9,null,$b$Mbu nơm nsêt tôr păng mâu ŭch iăt ôh nau vay, nđâp nau mbơh sơm bunuyh nây jêng nau Yêhôva tâm rmot.$b$,true),
('bunong-vn','PRO',28,10,null,$b$Mbu nơm ƀư nkhah du bunuyh sŏng ăn tĭng trong tih mra tŭp tâm ntu păng nơm kuyh jêh. Ƀiă lah phung mâu geh tih ôh mra dơn nau ueh lăng.$b$,true),
('bunong-vn','PRO',28,11,null,$b$Bunuyh ndrŏng kơp păng nơm jêng bunuyh blau mĭn, ƀiă lah bunuyh o ach geh nau gĭt vât mra gĭt ngăn mâm păng jêng.$b$,true),
('bunong-vn','PRO',28,12,null,$b$Tơ lah phung sŏng dơi, geh nau răm maak toyh ngăn; ƀiă lah tơ lah phung djơh dơi, ăp nơm du krap.$b$,true),
('bunong-vn','PRO',28,13,null,$b$Mbu nơm mo nau tih păng mâu mra geh nau chăt jêng ôh, ƀiă lah mbu nơm mbơh jêh ri cha lơi nau tih nây mra geh nau yô̆.$b$,true),
('bunong-vn','PRO',28,14,null,$b$Ueh maak ngăn mbu nơm klach yơk ma Yêhôva ƀa ƀơ, ƀiă lah bunuyh geh nuih n'hâm dăng păng mra geh nau rêh ni$b$,true),
('bunong-vn','PRO',28,15,null,$b$Du huê bunuyh djơh chiă uănh phung ƀon lan ndĭt trơi; jêng tâm ban nâm bu yau mŭr rđuh ngrông, nâm bu kau tĭng kăp mpa sa.$b$,false),
('bunong-vn','PRO',28,16,null,$b$Du huê kôranh chiă uănh mâu geh nau gĭt rbăng jêng nơm tŭn jot hâu ngăn; ƀiă lah mbu nơm mâu ŭch ôh ma nau sa ndơ mâu tâm di mra jong rêh.$b$,true),
('bunong-vn','PRO',28,17,null,$b$Tơ lah mbu moh ƀư pling mham du huê bunuyh, ăn păng jêng bunuyh mra du mro kŏ tât khĭt; lơi ăn bu kân păng ôh.$b$,true),
('bunong-vn','PRO',28,18,null,$b$Mbu nơm chuat tâm nau sŏng srăng mra geh nau tâm rklaih, ƀiă lah nơm tĭng ndô̆ trong kue mra tŭp ƀât lât dơm.$b$,true),
('bunong-vn','PRO',28,19,null,$b$Mbu nơm ƀư mir mra geh tŏng ndơ sông sa, ƀiă lah mbu nơm tĭng nau dơm dam mra jêng o ach.$b$,true),
('bunong-vn','PRO',28,20,null,$b$Bunuyh răp jăp mra bêng ma nau ueh lăng, ƀiă lah mbu nơm ndal ir gay ŭch jêng ndrŏng mâu mra klaih ôh ma nau tâm rmal.$b$,true),
('bunong-vn','PRO',28,21,null,$b$Tĭng nding jêng nau mâu ueh ôh, ƀiă lah yor ŭch geh du glo ƀănh, bu dơi ƀư nau tih đŏng.$b$,true),
('bunong-vn','PRO',28,22,null,$b$Bunuyh krêp mbeh prăk gay gơnh ŭch jêng ndrŏng, ƀiă lah păng mâu gĭt ôh nau roh hêng mra tât ma păng.$b$,true),
('bunong-vn','PRO',28,23,null,$b$Mbu nơm nduyh du huê bunuyh, du nar kăndơ̆ mra dơi geh nau yô̆ âk lơn ma nơm ngơi pathĭ (rnê săk nơm).$b$,true),
('bunong-vn','PRO',28,24,null,$b$Mbu nơm ntŭng ndơ mê̆ mbơ̆ păng, jêh ri lah: “Nau nây mâu tih ôh.” Nơm nây jêng băl đah nơm ƀư rai.$b$,true),
('bunong-vn','PRO',28,25,null,$b$Mbu nơm geh nuih n'hâm sưr nsônh nau tâm djrel, ƀiă lah mbu nơm nsing rnơm ma Yêhôva mra hơm răm.$b$,true),
('bunong-vn','PRO',28,26,null,$b$Mbu nơm nsing rnơm ma nau mĭn păng nơm jêng bunuyh rluk, ƀiă lah mbu nơm chuat tâm nau blau mĭn mra klaih.$b$,true),
('bunong-vn','PRO',28,27,null,$b$Mbu nơm ăn ma phung o ach mâu mra pưt ôh, ƀiă lah mbu nơm mâu gĭt yô̆ bu mra mâp âk ntil nau rak rtăp.$b$,true),
('bunong-vn','PRO',28,28,null,$b$Tơ lah phung djơh hao chiă uănh, bu mra nchuăt du. Ƀiă lah tơ lah khân păng khĭt, phung sŏng mra bĭk rơ̆ .$b$,true),
('bunong-vn','PRO',29,1,null,$b$Du huê bunuyh bu nduyh ƀa ƀơ ƀiă lah ăt ƀư dăng bôk, mra rai yot ƀât lât dơm, mâu hôm geh trong dơi săm ôh.$b$,true),
('bunong-vn','PRO',29,2,null,$b$Tơ lah bunuyh sŏng jêng toyh phung ƀon lah răm rhơn, ƀiă lah tơ lah phung djơh chiă uănh phung ƀon lan lŭng nter.$b$,true),
('bunong-vn','PRO',29,3,null,$b$Mbu nơm rŏng ma nau blau mĭn ƀư maak ma mbơ̆ păng, ƀiă lah nơm gŭ ndrel ma phung bu ur văng tĭr ƀư roh drăp ndơ păng.$b$,true),
('bunong-vn','PRO',29,4,null,$b$Ma nau sŏng du huê hađăch ƀư nâp bri păng, ƀiă lah mbu nơm sŏk dơn drăp bu blŏl ƀư rai bri dak.$b$,true),
('bunong-vn','PRO',29,5,null,$b$Du huê ngơi n'hĭ ma nơm chiau meng păng drăng nhuăl ăn ma jâng păng nơm.$b$,true),
('bunong-vn','PRO',29,6,null,$b$Bunuyh djơh geh nhuăl nau tih păng nơm, ƀiă lah bunuyh sŏng mprơ jêh ri răm maak.$b$,true),
('bunong-vn','PRO',29,7,null,$b$Bunuyh sŏng joi nau di ma phung o ach, ƀiă lah bunuyh djơh mâu gĭt rbăng ôh nau nây.$b$,true),
('bunong-vn','PRO',29,8,null,$b$Phung mơng mưch mpoh ŭnh ăn hit tâm ƀon toyh gay ŭnh sa, ƀiă lah bunuyh blau mĭn rplai ăn djoh ji nuih.$b$,true),
('bunong-vn','PRO',29,9,null,$b$Tơ lah du huê bunuyh blau mĭn tâm rlăch đah du huê bunuyh rluk; bunuyh rluk knŏng nuih mâu lah gơm jêh ri mâu geh ôh nau đăp mpăn.$b$,true),
('bunong-vn','PRO',29,10,null,$b$Bunuyh ŭch ƀư pling mham bu tâm rmot ma bunuyh mâu geh ôh nau tih, ƀiă lah phung sŏng mra king nau rêh ô băl.$b$,true),
('bunong-vn','PRO',29,11,null,$b$Bunuyh rluk mpơl lĕ nau păng ji nuih, ƀiă lah bunuyh blau mĭn nkrŭn nau păng nuih.$b$,true),
('bunong-vn','PRO',29,12,null,$b$Tơ lah kôranh chiă uănh iăt nau bu ngơi mƀruh, lĕ rngôch phung oh mon păng jêng djơh.$b$,true),
('bunong-vn','PRO',29,13,null,$b$Bunuyh o ach jêh ri nơm tŭn jot tâm mâp geh du nau ndrel; Yêhôva ƀư ang măt lĕ bar hê khân păng.$b$,true),
('bunong-vn','PRO',29,14,null,$b$Tơ lah du huê hađăch phat dôih phung o ach ma nau sŏng, sưng hađăch păng mra dơi nâp rjăp n'ho ro.$b$,true),
('bunong-vn','PRO',29,15,null,$b$Mâng rvĕ jêh ri nau nduyh ăn nau blau mĭn, bi ma kon rlach brơl ăn ƀư tĭng nau păng ŭch ƀư prêng mê̆ păng.$b$,true),
('bunong-vn','PRO',29,16,null,$b$Tơ lah phung djơh hao bĭk, pô ri nau tih lơ bĭk tâm ban đŏng, ƀiă lah phung sŏng mra saơ nau khân păng lĕ glưh jêh.$b$,true),
('bunong-vn','PRO',29,17,null,$b$Nkra hom kon may, jêh ri păng mra bonh leng may, păng mra ƀư maak huêng may.$b$,true),
('bunong-vn','PRO',29,18,null,$b$Tơ lah mâu geh ôh nau tâm mpơl, phung ƀon lan kon me ƀư tih, ƀiă lah ueh maak ngăn nơm djôt prăp nau vay.$b$,true),
('bunong-vn','PRO',29,19,null,$b$Mâu di knŏng ma nau ngơi ôh bu dơi nkra du huê oh mon, yor lah nđâp tơ lah păng gĭt rbăng kđôi, păng mâu mra tông ôh.$b$,true),
('bunong-vn','PRO',29,20,null,$b$May saơ lĕ du huê bunuyh mbơh ngơi ndal ir? Du huê nơm rluk hôm e geh nau kâp gân lơn bunuyh nây.$b$,true),
('bunong-vn','PRO',29,21,null,$b$Mbu nơm mât oh mon mâu buay ơm păng ntơm bơh jê̆. Kêng dŭt păng mra jêng du huê nơm dăng ko.$b$,true),
('bunong-vn','PRO',29,22,null,$b$Bunuyh biănh nsônh nau tâm djrel, jêh ri du huê bunuyh ji nuih ƀư âk nau tih.$b$,true),
('bunong-vn','PRO',29,23,null,$b$Nau bunuyh sưr mra n'glưh păng nơm, ƀiă lah mbu nơm blau dêh rhêt mra geh nau bu yơk.$b$,true),
('bunong-vn','PRO',29,24,null,$b$Mbu nơm tâm rnglăp đah du huê bunuyh ntŭng jêng rlăng đah huêng păng nơm, păng tăng nau rak rtăp ƀiă lah mâu nănh nkoch ôh.$b$,true),
('bunong-vn','PRO',29,25,null,$b$Nau klach ma bunuyh jêng dăk sân ma nơm; ƀiă lah mbu nsing ma Yêhôva geh nau mpăn.$b$,true),
('bunong-vn','PRO',29,26,null,$b$Âk bunuyh tĭng joi nau yô̆ bơh hađăch, ƀiă lah bunuyh mra sŏk dơn nau di bơh Yêhôva.$b$,true),
('bunong-vn','PRO',29,27,null,$b$Phung sŏng tâm rmot ma bunuyh kue, ƀiă lah bunuyh kue tâm rmot ma nơm chuat tâm trong sŏng.$b$,true),
('bunong-vn','PRO',30,1,null,$b$Nau Y-Agur kion bu klâu Y-Yakê ngơi, nau hôr aơ păng ngơi ma Y-Ithiêl, jêh ri ma Y-Ukal.$b$,true),
('bunong-vn','PRO',30,2,null,$b$Nanê̆, gâp rluk lơn ma bunuyh êng, jêh ri gâp mâu geh nau gĭt rbăng nâm bu du huê bunuyh ôh.$b$,true),
('bunong-vn','PRO',30,3,null,$b$Gâp mâu hŏ mâp nti ôh nau blau mĭn, mâu lĕ gâp geh nau gĭt rbăng ma Nơm Kloh Ueh.$b$,true),
('bunong-vn','PRO',30,4,null,$b$Mbu hŏ hao jêh klơ trôk jêh nây plơ̆ jŭr tay? Mbu hŏ rgum jêh sial tâm klŏ mpang ti nơm? Mbu hŏ nklâm jêh dak tâm ao nơm? Mbu hŏ ƀư nâp jêh bôl neh ntu? Mbu amoh păng, jêh ri amoh kon bu klâu păng? Mbơh ma gâp, tơ lah may gĭt?$b$,true),
('bunong-vn','PRO',30,5,null,$b$Lĕ nau Brah Ndu Ngơi bu rlong uănh, Brah Ndu jêng khêl ma mbu nơm nde tâm Păng.$b$,true),
('bunong-vn','PRO',30,6,null,$b$Lơi dĭng ntop ôh ma nau Păng ngơi, klach lah Păng nduyh may jêh ri may jêng bunuyh ngơi mƀruh ngăn.$b$,true),
('bunong-vn','PRO',30,7,null,$b$Gâp geh dăn ma May bar ntil nau, lơi dun ôh ăn nau nây ma gâp, ê lor gâp khĭt.$b$,true),
('bunong-vn','PRO',30,8,null,$b$Sŏk rđah ăn ngai đah gâp nau ngơi mƀruh jêh ri ngơi nchơt; lơi ăn gâp jêng o ach, mâu lĕ jêng kuăng ndrŏng, knŏng ăn ma gâp ndơ sông sa ăn tŏng ăp nar.$b$,true),
('bunong-vn','PRO',30,9,null,$b$Klach lah gâp hơm jêh ri dun ma May, jêh ri lah: “Mbu moh Yêhôva?” Mâu lah tơ lah ndĭt trơi gâp hăn ntŭng jêh ri gâp ƀư bơ̆ amoh Brah Ndu gâp.$b$,true),
('bunong-vn','PRO',30,10,null,$b$Lơi ta ngơi nchơt ôh ma du huê oh mon ta năp kôranh păng, klach lah bu rak rtăp may jêh ri may bu kơp jêng tih.$b$,true),
('bunong-vn','PRO',30,11,null,$b$Geh ntil bunuyh rak rtăp ma mbơ̆ khân păng, jêh ri mâu ŭch mât ton ôh nau ueh lăng ma mê̆ khân păng;$b$,true),
('bunong-vn','PRO',30,12,null,$b$geh phung bunuyh mĭn khân păng jêng kloh, ƀiă lah nau ƀơ̆ ƀơch khân păng mâu hŏ rao ôh;$b$,false),
('bunong-vn','PRO',30,13,null,$b$geh phung bunuyh măt uănh rnam, Muh măt rnam ngăn.$b$,false),
('bunong-vn','PRO',30,14,null,$b$Geh phung bunuyh sêk jêng nâm bu mpiăt đao, găm nâm bu pêih. Khân păng ŭch ƀư rai phung ndĭt trơi ta klơ neh ntu jêh ri bunuyh rêh ni mâu tŏng ndô ndơ ta nklang kon bunuyh.$b$,true),
('bunong-vn','PRO',30,15,null,$b$Plơm geh bar hê kon bu ur, khân păng nter: “Ăn hom, ăn hom.” Geh pe ntil ndơ mâu blau mpay ôh, puăn ntil ndơ mâu ŭch ôh lah: “Găp hơi.”$b$,true),
('bunong-vn','PRO',30,16,null,$b$Ƀon Phung Khĭt, ndŭl bu ur nglên, neh ji hir mro mrăng ma dak, jêh ri ŭnh; khân mâu ŭch ôh lah: “Găp jêh.”$b$,true),
('bunong-vn','PRO',30,17,null,$b$Măt bunuyh mưch ma mbơ̆ jêh ri dun mâu tông ôh ma bâr mê̆, mra geh nđak tâm rlŭng chôk rloch măt.$b$,true),
('bunong-vn','PRO',30,18,null,$b$Geh pe ntil khlay ngăn rlau lơn ma gâp dơi gĭt rbăng; jêh ri puăn ntil nau gâp mâu dơi gĭt rbăng ôh;$b$,true),
('bunong-vn','PRO',30,19,null,$b$trong klang mpăr klơ trôk, trong bêh hung ta klơ lŭ trong Kŭmpăn nsong ta nklang dak mƀŭt jêh ri trong du huê bu klâu rnglăp ndrel đah du huê bu ur.$b$,false),
('bunong-vn','PRO',30,20,null,$b$Aơ jêng nau bu ur văng tĭr ƀư, păng sa jêh ri jut trôm mbung, lah: “Gâp mâu mâp ƀư nau tih ôh.”$b$,true),
('bunong-vn','PRO',30,21,null,$b$Geh pe ntil ƀư ăn ma neh mpât n'găr jêh ri puăn ntil nau păng mâu dơi dơn ôh:$b$,true),
('bunong-vn','PRO',30,22,null,$b$Du huê dĭk tơ lah păng jêng nkhơng hađăch, du huê bunuyh rluk hơm jêh ma ndơ sông sa,$b$,false),
('bunong-vn','PRO',30,23,null,$b$du huê bu ur bu mâu ŭch ôh nkhơng ma geh sai, jêh ri du huê oh mon bu ur ntrok kôranh bu ur păng:$b$,false),
('bunong-vn','PRO',30,24,null,$b$Geh puăn ntil ndơ jê̆ jê̆ ta neh ntu ƀiă lah khân păng jêng nkhơng phung blau mĭn ngăn;$b$,false),
('bunong-vn','PRO',30,25,null,$b$Ngonh (sam) jêng ntil ndơ mâu geh n'hâm suan ktang ôh, ƀiă lah khân păng prăp nkrem ndơ sông sa ma khân păng nơm dôl yan ta vai;$b$,false),
('bunong-vn','PRO',30,26,null,$b$Rpai jêng mpa mâu geh suan ktang ôh, ƀiă lah khân păng ƀư rsuăn tâm trôm lŭ;$b$,false),
('bunong-vn','PRO',30,27,null,$b$krah mâu geh hađăch ôh, ƀiă lah lĕ rngôch nau hăn n'hoch tĭng phung.$b$,false),
('bunong-vn','PRO',30,28,null,$b$Bŭl ka bu dơi nhŭp ma ti, ƀiă lah păng gŭ tâm ngih hađăch.$b$,true),
('bunong-vn','PRO',30,29,null,$b$Geh pe ntil mpa chuat hăn ueh ngăn, geh puăn mpa chuat ma nau rnam ngăn.$b$,true),
('bunong-vn','PRO',30,30,null,$b$Yau mŭr jêng mpa ktang lơn ma lĕ rngôch, ta nklang lĕ ntil mpô mpa; păng mâu dơi seng ôh đah du mlâm mpa êng.$b$,true),
('bunong-vn','PRO',30,31,null,$b$Iăr nkuăng ntoch trô ko ueh ngăn đah be. Jêh ri du huê hađăch phung ta han păng gŭ n'hanh păng.$b$,true),
('bunong-vn','PRO',30,32,null,$b$Tơ lah may geh ƀư nau rluk jêh ri n'hao may nơm, mâu lah tơ lah may mĭn ŭch ƀư nau mhĭk, rdêp trôm mbung ma ti may nơm!$b$,true),
('bunong-vn','PRO',30,33,null,$b$Yor lah nâm bu vâr dak toh ndrôk ƀư ngi dak toh. Jêh ri pet trôm muh luh du mham; tâm ban pô nây đŏng nsônh nau ji nuih mra tât ma nau tâm djrel.$b$,true),
('bunong-vn','PRO',31,1,null,$b$Nau hađăch Y-Lêmuêl ngơi; nau hôr mê̆ păng nti ma păng.$b$,true),
('bunong-vn','PRO',31,2,null,$b$Moh nau gâp mra lah ma may, Hơi kon? Moh nau gâp mra lah ma may, Hơi kon bu klâu tă bơh ndŭl proch gâp nơm? Moh nau gâp mra lah ma may, Hơi kon, nơm gâp mbơh sơm dăn?$b$,true),
('bunong-vn','PRO',31,3,null,$b$Lơi ăn roh dơm ôh n'hâm suan may ma bu ur, mâu lah gŭ ndrel ma phung ƀư rai lơi phung hađăch.$b$,true),
('bunong-vn','PRO',31,4,null,$b$Hơi Y-Lêmuêl, Nây jêng nau mâu ueh ôh ăn ma phung hađăch nhêt ndrănh, mâu lĕ ueh ma phung kôranh chiă uănh joi ndrănh,$b$,true),
('bunong-vn','PRO',31,5,null,$b$Klach lah tơ lah nhêt ndrănh khân păng mra chuêl nau ntĭnh hŏ ntrŭnh jêh. Jêh ri ƀư djơh nau phat dôih ma phung rêh ni.$b$,false),
('bunong-vn','PRO',31,6,null,$b$Ăn ndrănh ma phung dăch khĭt jêh, jêh ri ăn hom ndrănh ma phung geh nau rngot ngăn.$b$,true),
('bunong-vn','PRO',31,7,null,$b$Ăn khân păng nhêt jêh ri chuêl lơi nau khân păng o ach, jêh ri mâu hôm kah gĭt đŏng ôh ma nau rêh ni khân păng.$b$,true),
('bunong-vn','PRO',31,8,null,$b$Hă trôm mbung may sâm ngơi an ma bunuyh mlo, gay ƀư nau di ma phung mâu geh ôh bunuyh kơl.$b$,true),
('bunong-vn','PRO',31,9,null,$b$Hă hom trôm mbung may ngơi dôih ma nau sŏng king an nau di ma phung o ach jêh ri ndĭt trơi.$b$,true),
('bunong-vn','PRO',31,10,null,$b$Mbu dơi joi gay geh du huê ur khư ăn bu yơk? Păng jêng khlay lơn ma lŭ rsang$b$,true),
('bunong-vn','PRO',31,11,null,$b$Nuih n'hâm sai păng rnơm ma păng, jêh ri păng mâu mra pưt ôh.$b$,false),
('bunong-vn','PRO',31,12,null,$b$Du bông rêh, păng leo ăn nau geh jêng ma sai; mâu di nau mhĭk ôh.$b$,true),
('bunong-vn','PRO',31,13,null,$b$Păng joi brai rsau biăp jêh ri brai rôt, jêh ri gơih pah kan ma ti.$b$,true),
('bunong-vn','PRO',31,14,null,$b$Păng jêng nâm bu du mlâm Kŭmpăn phung tăch drăp, leo ndơ sông sa tă bơh ntŭk ngai.$b$,true),
('bunong-vn','PRO',31,15,null,$b$Păng kah rngăl bêch dôl trôk hôm e ngo, jêh ri ăn ndơ sông sa ma phung tâm ngih vâl păng; tâm pă kan ma phung oh mon bu ur păng.$b$,true),
('bunong-vn','PRO',31,16,null,$b$Păng uănh n'hêl du lôk mir jêh ri rvăt mir nây; ma prăk tă bơh ti păng ƀư, păng ntơ đang play kriăk ƀâu.$b$,true),
('bunong-vn','PRO',31,17,null,$b$Păng rêt rse bŭt ma nau gơih pah kan, jêh ri pah kan ma lĕ n'hâm suan.$b$,true),
('bunong-vn','PRO',31,18,null,$b$Păng saơ ndơ păng tăch geh nau hao ueh ngăn, bri măng ngih vâl păng mâu ŭch nhhât ôh ŭnh.$b$,true),
('bunong-vn','PRO',31,19,null,$b$Păng ruy brai êng păng nơm jêh ri ti păng vư̆ ng tanh bok.$b$,true),
('bunong-vn','PRO',31,20,null,$b$Păng ăn ndơ yô̆ kơl ma phung rêh ni, jêh ri păng nta ti păng ăn ndơ ma phung ndĭt trơi.$b$,true),
('bunong-vn','PRO',31,21,null,$b$Păng mâu ir klach ôh ma pler dôl nđik srŏ ngăn ƀư ma ngih vâl păng. Yor lah lĕ rngôch khân păng nsoh jêh bok ao răm sur chăng.$b$,true),
('bunong-vn','PRO',31,22,null,$b$Păng ƀư âk phôi nah, bok ao păng nsoh ƀư jêh ma mhay rhên jêh ri ma bok sut chăng.$b$,true),
('bunong-vn','PRO',31,23,null,$b$Bu gĭt năl sai păng ta mpông pêr ƀon, dơi gŭ ndrel ma phung bu bŭnh bu ranh tâm nklang n'gor bri.$b$,true),
('bunong-vn','PRO',31,24,null,$b$Păng ƀư ao đah mhay jêh ri tăch ao nây, păng tăch rse vân bŭt ma nơm tăch drăp.$b$,true),
('bunong-vn','PRO',31,25,null,$b$Păng geh nau ktang jêh ri nau bu yơk; păng gơm rum lor mâu klach ôh ma nau tât du nar kăndơ̆ .$b$,true),
('bunong-vn','PRO',31,26,null,$b$Păng hă trôm mbung ngơi nau blau mĭn, jêh ri păng nti ntĭm nau rah rơch.$b$,true),
('bunong-vn','PRO',31,27,null,$b$Păng mât njrăng phung tâm ngih vâl păng, jêh ri păng mâu geh nau ƀlao ôh.$b$,true),
('bunong-vn','PRO',31,28,null,$b$Phung kon păng dâk jêh ri mbơh nau khân ô băl kah gĭt tôr ma păng nau ueh lăng, nđâp sai păng tâm ban đŏng tâm rnê ma păng lah:$b$,true),
('bunong-vn','PRO',31,29,null,$b$“Geh âk phung kon bu ur ƀư ueh ngăn khư nau bu yơk, ƀiă lah ay rlau lơn ma lĕ rngôch khân păng.”$b$,false),
('bunong-vn','PRO',31,30,null,$b$Nau ray nkrơ̆ , jêh ri nau ueh dơi roh; ƀiă lah du huê bu ur klach yơk ma Yêhôva mra geh nau tâm rnê.$b$,true),
('bunong-vn','PRO',31,31,null,$b$Ăn ma păng nau nkhôm luh tă bơh kan ti păng ƀư, jêh ri ăn kan păng ƀư tâm rnê ma păng ta mpông pêr pa năp phung ƀon lan.$b$,true);
