insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'ECC', $b$Kôranh Nơm Nti$b$, $b$["Ndrom Sămƀŭt", "KÔRANH NƠM NTI"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ECC',1,1,null,$b$Nau kôranh nơm nti kon bu klâu Y-Đavit hađăch ƀon Yêrusalem ngơi.$b$,true),
('bunong-vn','ECC',1,2,null,$b$Nau dơm dam bơh nau dơm dam, kôranh nơm nti lah, Nau dơm dam bơh nau dơm dam! Lĕ rngôch ndơ jêng dơm dam da dê.$b$,true),
('bunong-vn','ECC',1,3,null,$b$Moh dơ khlay bunuyh geh tă bơh lĕ nau hŏt ra-ah tă bơh nau păng pah kan tâm dâng măt ar?$b$,true),
('bunong-vn','ECC',1,4,null,$b$Du rô̆ nuyh aơ lôch jêh ri du rô̆ nuyh êng ât, ƀiă lah neh ntu hôm e mro mrăng.$b$,true),
('bunong-vn','ECC',1,5,null,$b$Nar luh jêh ri nar nhâp, jêh ri ndal ngăn plơ̆ sĭt ntŭk păng luh.$b$,true),
('bunong-vn','ECC',1,6,null,$b$Sial hôm mpeh rđŭng, jêh ri ndăch mpeh dor; sial ndăch mro mrăng, ndăch rvang tă bơh ntŭk păng ntơm sa ơm plơ̆ sĭt tay ma ntŭk păng ntơm sa ơm đŏng.$b$,true),
('bunong-vn','ECC',1,7,null,$b$Lĕ ngôch dak krong hoch chruh dak mƀŭt, ƀiă lah dak mƀŭt mâu bêng ôh. Ntŭk dak krong vay hŏ hoch jêh, Ta nây yơh păng chruh đŏng.$b$,true),
('bunong-vn','ECC',1,8,null,$b$Lĕ ngôch ndơ bêng ma nau hŏt ra-ah bu; kon bunuyh mâu dơi nkoch bri ôh; trôm măt mâu dơi dĭl lĕ uănh, tôr kŏ mâu mpay lĕ iăt.$b$,true),
('bunong-vn','ECC',1,9,null,$b$Moh nau lĕ tât jêh mra tât đŏng, jêh ri moh nau bu hŏ ƀư jêh, bu mra ƀư tay đŏng; mâu geh nau mhe ôh tâm dâng nar.$b$,true),
('bunong-vn','ECC',1,10,null,$b$Geh lĕ du nau bu mra lah, Aơ, jêng nau mhe? Ndơ nây hŏ geh ngăn jêh. Tâm rnôk rô̆ lor ma he.$b$,true),
('bunong-vn','ECC',1,11,null,$b$Bu mâu kah gĭt đŏng ôh ma rô̆ ơm, mâu lĕ bu mra kah gĭt ma nau mra tât ta nklang phung rô̆ pa kơi Nau Kôranh Nơm Nti Gĭt Vât Yor Nau Tât Ma Păng$b$,true),
('bunong-vn','ECC',1,12,null,$b$Gâp nơm yơh Kôranh Nơm Nti hŏ ƀư hađăch n'gor bri Israel ta ƀon Yêrusalem.$b$,false),
('bunong-vn','ECC',1,13,null,$b$Gâp prăp jêh nau mĭn gâp gay sek uănh jêh ri joi ma nau blau mĭn lĕ rngôch nau bu ƀư tâm dâng trôk; nây jêng nau kan hŏt ra-ah Brah Ndu ăn jêh ma kon bunuyh ƀư.$b$,true),
('bunong-vn','ECC',1,14,null,$b$Gâp hŏ saơ ăp ntil nau bu ƀư jêh tâm dâng măt nar, jêh ri aơ, lĕ rngôch jêng nau dơm dam jêh ri tĭng rlong sial khôm.$b$,true),
('bunong-vn','ECC',1,15,null,$b$Moh dơ lĕ jêng kue jêh bu mâu dơi bât sŏng ôh, jêh ri moh ndơ bu mâu tŏng mâu dơi blau kơp ôh.$b$,true),
('bunong-vn','ECC',1,16,null,$b$Gâp lah ma gâp nơm, Gâp sŏk dơn jêh âk nau blau mĭn, rlau lơn ma lĕ rngôch phung chiă uănh tâm ƀon Yêrusalem lor pa năp gâp; gâp geh âk nau blau mĭn jêh ri nau gĭt rbăng yor nau tât jêh ma gâp.$b$,true),
('bunong-vn','ECC',1,17,null,$b$Gâp prăp jêh nau mĭn gâp ŭch gĭt năl nau blau mĭn jêh ri gay gĭt nau rluk jêh ri nau rluk. Gâp saơ nau nây tâm ban lĕ jêng nau tĭng sial khôm.$b$,false),
('bunong-vn','ECC',1,18,null,$b$Yor lah đah âk nau blau mĭn geh âk nau ji nuih biănh, jêh ri bu nơm n'hao nau gĭt rbăng ƀư n'hao nau rngot rvê lĕ. Nâu Răm Maak, Kuăng Ndrŏng,$b$,true),
('bunong-vn','ECC',2,1,null,$b$Gâp lah êng tâm nuih n'hâm gâp nơm: Kay! Rlong jêng hom nau răm maak; ƀư maak hom may nơm. Ƀiă lah aơ, nau nây jêng dơm dam tâm ban lĕ.$b$,true),
('bunong-vn','ECC',2,2,null,$b$Gâp lah ma nau gơm, Păng jêng nau rluk, ma nau maak, moh khlay ma nau gơm nây?$b$,false),
('bunong-vn','ECC',2,3,null,$b$Gâp mĭn tâm nuih n'hâm gâp sŏk ndrănh nhêt gay ăn săk jăn răm maak, dôl nau gâp mĭn ăt leo gâp ma nau blau mĭn jêh ri plơ̆ tay ƀư nau rluk, kŏ tât gâp dơi saơ moh nau jêng ueh lơn ăn ma kon bunuyh dơi ƀư tâm dâng trôk du bông dôl khân păng gŭ rêh.$b$,true),
('bunong-vn','ECC',2,4,null,$b$Gâp hŏ ƀư nau kan toyh, gâp ndâk ngih vâl ma nơm, hŏ tăm tâm n'gar play kriăk ƀâu ma gâp nơm;$b$,true),
('bunong-vn','ECC',2,5,null,$b$hŏ njêng ma gâp nơm n'gar play đo jêh ri n'gar kao si, jêh ri tăm ăp ntil play đo tâm ntŭk nây;$b$,false),
('bunong-vn','ECC',2,6,null,$b$gâp kuyh ntu dak prăp tŏ djrah âk ntil tơm si nây.$b$,false),
('bunong-vn','ECC',2,7,null,$b$Gâp rvăt dĭk bu ur, dĭk bu klâu, geh âk phung dĭk geh kon tâm ngih vâl gâp. Gâp geh neh ndrôk phung jêh ri biăp phung rlau lơn ma lĕ rngôch phung rô̆ pa năp gâp ta ƀon Yêrusalem.$b$,true),
('bunong-vn','ECC',2,8,null,$b$Tâm ban lĕ gâp hŏ prăp nkrem ma gâp nơm răk mah jêh ri drăp khlay phung hađăch, dơ tâm n'gor. Gâp sâm rvê ăn ma phung mprơ bu ur jêh ri bu klâu, jêh ri sŏk âk ur yông, tĭng nau phung bu klâu ŭch.$b$,false),
('bunong-vn','ECC',2,9,null,$b$Pô ri gâp jêng ndrŏng ngăn jêh ri rlau lơn ma lĕ rngôch phung rô̆ lor pa năp gâp ta ƀon Yêrusalem. Tâm ban lĕ nau blau mĭn gâp ăt gŭ ndrel ma gâp.$b$,true),
('bunong-vn','ECC',2,10,null,$b$Moh ndơ măt gâp kơnh, gâp mâu dun ôh du ntil nau ƀư maak tâm nuih n'hâm gâp nơm, yor lah nuih n'hâm gâp maak ma lĕ rngôch kan hŏt gâp hŏ pah.$b$,true),
('bunong-vn','ECC',2,11,null,$b$Gâp sek uănh lĕ rngôch kan ti gâp hŏ ƀư jêh, jêh ri nau hŏt rgănh gâp ƀư nau nây, jêh ri aơ, lĕ rngôch nau dơm dam jêh ri nau tĭng sial, mâu geh nau khlay ôh tâm dâng măt nar.$b$,true),
('bunong-vn','ECC',2,12,null,$b$Pô ri gâp n'gĭl ŭch sek uănh nau blau mĭn, nau rluk, nau rluk, yor lah moh nau êng bunuyh thoi hađăch dơi ƀư? Knŏng moh nau hađăch hŏ ƀư.$b$,true),
('bunong-vn','ECC',2,13,null,$b$Pô ri gâp saơ nau blau mĭn jêng ueh lơn ma nau rluk nâm bu nau ang jêng ueh lơn ma nau ngo.$b$,true),
('bunong-vn','ECC',2,14,null,$b$Ƀiă lah blau mĭn geh măt păng ta muh măt păng nơm, ƀiă lah nơm rluk chuat hăn tâm nau ngo klĕng. Ƀiă lah gâp saơ jêh du nau nglĕ dŭt tât ma lĕ rngôch khân păng.$b$,true),
('bunong-vn','ECC',2,15,null,$b$Pô nây gâp lah ma gâp nơm, moh nau mra tât ma nuyh rluk, mra tât ma gâp tâm ban lĕ. Pô ri moh khlay gâp jêng blau mĭn hâu ngăn? Jêh ri gâp lah ma gâp nơm, Nau nây tâm ban lĕ jêng dơm dam.$b$,true),
('bunong-vn','ECC',2,16,null,$b$Yor lah bu mâu kah gĭt ôh ma bunuyh blau mĭn tât n'ho ro, ăt tâm ban lĕ mâu kah gĭt ôh ma bunuyh rluk; yor lah tâm nar kăndơ̆ mra tât bu mra chuêl lĕ rngôch. Di ngăn, bunuyh blau mĭn ăt khĭt nâm bu bunuyh rluk lĕ!$b$,true),
('bunong-vn','ECC',2,17,null,$b$Pô ri, gâp tâm rmot đah nau rêh, yor lah lĕ rngôch kan pah tâm dâng măt nar jêng hŏt rgănh ăn gâp; yor lah lĕ rngôch jêng dơm dam, tĭng rlong sial nkhôm.$b$,true),
('bunong-vn','ECC',2,18,null,$b$Gâp tâm rmot ma lĕ nau hŏt gâp ƀư jêh tâm dâng măt nar, yor lah gâp mra lơi ndơ nây ma nơm mra thoi gâp pa kơi taơ;$b$,true),
('bunong-vn','ECC',2,19,null,$b$jêh ri mbu gĭt, gĭt lah păng jêng du huê blau mĭn mâu lah rluk? Nđâp tơ lah mâm jêng, păng mra dơi chiă uănh lĕ rngôch an gâp hŏ sŏk tă bơh nau hŏt rgănh jêh ri nau blau mĭn ƀư tâm dâng măt ar. Nau nây tâm ban lĕ jêng dơm dam.$b$,false),
('bunong-vn','ECC',2,20,null,$b$Pô ri gâp rdja nuih ngăn tâm lĕ nau hŏt rgănh kan gâp pah jêh tâm dâng măt nar,$b$,true),
('bunong-vn','ECC',2,21,null,$b$yor lah geh tơ̆ du huê bunuyh ƀư hŏt jêh păng nơm ma nau blau mĭn, gĭt mĭn âk jêh ri tât jêng njêh, cha lơi lĕ ngôch ndơ păng ma nơm mâu mâp hŏt ra ah ôh ma ndơ nây. Nau nây tâm ban lĕ jêng dơm dam jêh ri jêng du nau mhĭk ngăn.$b$,false),
('bunong-vn','ECC',2,22,null,$b$Pô nây, moh nau khlay ma bunuyh pah kan hŏt rgănh, jêng hŏt gar ƀư kan tâm dâng măt nar?$b$,false),
('bunong-vn','ECC',2,23,null,$b$Yor lah lĕ rngôch nar păng gŭ rêh bêng ma nau jêr, jêh ri kan păng jêng nau sôt nuih bu; nđâp bri dôl măng nau mĭn păng mâu rlu ôh. Nau nây tâm ban lĕ jêng dơm dam.$b$,false),
('bunong-vn','ECC',2,24,null,$b$Mâu geh ôh nau ueh mĭn lơn ăn ma du huê bunuyh rlau ma ndơ ma ndơ sông sa, jêh ri nhêt, gay ăn huêng păng dơn nau ueh maak ma kan păng. Gâp saơ nau nây luh tă bơh ti Brah Ndu$b$,true),
('bunong-vn','ECC',2,25,null,$b$yor lah bu dơi sông sa mâu lah dơi geh nau maak lơn ma gâp?$b$,false),
('bunong-vn','ECC',2,26,null,$b$Yor lah rah Ndu ăn nau blau mĭn, nau gĭt rbăng, jêh ri nau hâk răm ma bunuyh ƀư maak ma păng; ƀiă lah păng ăn ma nuyh tih kan prăp nkrem knŏng ŭch ăn ma nơm ƀư maak ma Brah du. Nau nây tâm ban lĕ jêng dơm dam jêh ri tĭng rlong sial khôm.$b$,true),
('bunong-vn','ECC',3,1,null,$b$Moh ntil nau geh jêng êng êng; lĕ rngôch kan tâm dâng trôk neh nal năng:$b$,true),
('bunong-vn','ECC',3,2,null,$b$Geh năng bu deh ma păng, jêh ri geh năng păng khĭt; geh năng bu tăm, geh năng bu rôk ndơ hŏ tăm jêh;$b$,false),
('bunong-vn','ECC',3,3,null,$b$geh yăn bu nkhĭt, jêh ri geh năng bu ƀư bah; geh năng bu rơih lơi, jêh ri geh năng bu ndâk păng;$b$,false),
('bunong-vn','ECC',3,4,null,$b$geh yăn nhĭm, jêh ri geh năng gơm; geh năng lâng ndrê, jêh ri geh năng pâl nta lô̆ ;$b$,false),
('bunong-vn','ECC',3,5,null,$b$geh yăn joi ndơ, jêh ri geh năng rgum lŭ; geh năng ut ra-u, jêh ri geh năng mâu ut ra-u;$b$,false),
('bunong-vn','ECC',3,6,null,$b$geh yăn joi ndơ, jêh ri geh năng roh ndơ; geh năng prăp ndơ, jêh ri geh năng mƀăr lơi ndơ;$b$,false),
('bunong-vn','ECC',3,7,null,$b$geh yăn nkhêk lơi, jêh ri geh năng jĭm tay; geh năng gŭ rklăk, jêh ri geh năng ngơi;$b$,false),
('bunong-vn','ECC',3,8,null,$b$geh yăn rŏng, jêh ri geh năng tâm rmot; geh năng tâm lơh, jêh ri geh năng geh nau đăp mpăn.$b$,false),
('bunong-vn','ECC',3,9,null,$b$Moh ndơ nau khlay ma nơm pah kan đah nau hŏt rgănh păng?$b$,true),
('bunong-vn','ECC',3,10,null,$b$Gâp saơ jêh nau Brah Ndu jao jêh ma phung kon bunuyh ƀư.$b$,false),
('bunong-vn','ECC',3,11,null,$b$Brah Ndu njêng jêh ăp ntil ndơ ueh tĭng nâm yan păng; tâm ban lĕ păng ăn ma bunuyh mĭn ma rnôk ƀa-ƀơ n'ho ro, ƀiă lah ăt geh lĕ, păng mâu ăn bunuyh dơi gĭt rbăng ôh moh Brah Ndu ƀư jêh ntơm bơh sa ơm tât nglĕ dŭt.$b$,false),
('bunong-vn','ECC',3,12,null,$b$Gâp gĭt mâu geh nau ueh uĭn ôh ma khân păng, knŏng tơ lah khân păng răm maak, jêh ri ƀư ueh du bông nau rêh khân păng;$b$,false),
('bunong-vn','ECC',3,13,null,$b$tâm ban lĕ Brah Ndu ăn ma ăp nơm bunuyh dơi sông sa nhêt jêh âk ma lĕ kan hŏt rgănh păng.$b$,false),
('bunong-vn','ECC',3,14,null,$b$Gâp gĭt moh kan Brah Ndu ƀư gŭ n'ho ro; bu mâu dơi ntop, mâu lĕ bu dơi n'hŭch. Brah Ndu jêng jêh nau tâm ban pô nây, gay ma phung bunuyh dơi klach yơk ma Păng.$b$,true),
('bunong-vn','ECC',3,15,null,$b$Moh ntil nau geh jêh aƀaơ ri, hŏ geh jêh rnôk kăl; moh nau mra tât, hŏ tât jŏ jêh sa ơm ri: Brah Ndu ăn jêng tay moh ndơ kan hŏ rlau jêh.$b$,true),
('bunong-vn','ECC',3,16,null,$b$Rlau lơn ma nau nây gâp saơ tâm dâng măt nar: Tâm ntŭk geh nau sŏng srăng geh nau kue, jêh ri tâm rlŭk tay nau sŏng geh nđâp nau ueh.$b$,true),
('bunong-vn','ECC',3,17,null,$b$Gâp lah tâm nuih n'hâm gâp: Brah ndu mra phat dôih bunuyh sŏng jêh ri bunuyh kue, yor lah păng tâm nal jêh du rô̆ ma lĕ rngôch ntil nau jêh ri ma lĕ rngôch kan.$b$,false),
('bunong-vn','ECC',3,18,null,$b$Gâp lah đŏng tâm nuih n'hâm gâp: Di nâm bu pô nây, yor lah Brah Ndu ŭch rlong uănh kon bunuyh, jêh ri knŏng ăn khân păng gĭt ma khân păng nơm jêng nâm bu mpô mpa.$b$,true),
('bunong-vn','ECC',3,19,null,$b$Yor lah nar dăch kêng lôch ma kon bunuyh jêng tâm ban dơm nar dăch kêng lôch ma mpô mpa; nâm bu du huê bunuyh khĭt, mpô mpa khĭt tâm ban lĕ. Lĕ rngôch khân păng geh n'hâm nsôr tâm ban, jêh ri bunuyh mâu geh nau ueh lơn ma mpô mpa ôh, yor lah lĕ ngôch jêng nau dơm dam.$b$,false),
('bunong-vn','ECC',3,20,null,$b$Lĕ ngôch bu nsŭn du ntŭk; lĕ rngôch luh jêh tă bơh ndruyh neh, jêh ri lĕ rngôch mra sĭt tay ma ndruyh neh.$b$,false),
('bunong-vn','ECC',3,21,null,$b$Mbu gĭt mâu lah huêng bunuyh hao rlet klơ, mâu lah huêng mpô mpa trŭnh tâm dâng neh?$b$,false),
('bunong-vn','ECC',3,22,null,$b$Pô ri, gâp saơ jêh mâu geh nau ueh uĭn ôh knŏng tơ lah du huê bunuyh mra maak ma kan păng, yor lah nau nây prăp ma păng. Mbu dơi ăn păng saơ moh nau mra tât nar kăndơ̆ ma păng?$b$,true),
('bunong-vn','ECC',4,1,null,$b$Gâp plơ̆ tay, uănh saơ lĕ rngôch nau tŭn jot bu ƀư tâm dâng trôk. Gâp saơ dak măt phung bu tŭn jot, jêh ri mâu geh nơm bonh khân ô băl ôh! Phung tŭn jot khân ô băl geh nau dơi, jêh ri mâu geh nơm bonh khân ô băl ôh.$b$,true),
('bunong-vn','ECC',4,2,null,$b$Gâp kơp phung khĭt jêh ueh lơn ma phung hôm rêh;$b$,false),
('bunong-vn','ECC',4,3,null,$b$ƀiă lah Nơm ueh lơn ma lĕ bar jêng bunuyh ê-hŏ deh, ê-hŏ gâp saơ lĕ nau mhĭk tâm dâng măt nar.$b$,false),
('bunong-vn','ECC',4,4,null,$b$Jêh ri gâp saơ jêh lĕ rngôch nau hŏt jêh ri lĕ rngôch kan njêh ngăn ƀư ăn ma bunuyh aơ geh bu êng ji nuih ma ô băl. Nau nây tâm ban lĕ jêng dơm dam jêh ri tĭng rlong sial khôm.$b$,true),
('bunong-vn','ECC',4,5,null,$b$Bunuyh lŭk ut ti păng, jêh ri sa puăch păng nơm.$b$,true),
('bunong-vn','ECC',4,6,null,$b$Ueh lơn bêng du mbăt ti jêh ri geh nau đăp mpăn, ma dah bar đah ti bêng mbăt ma nau hŏt rgănh jêh ri tĭng rlong sial khôm.$b$,true),
('bunong-vn','ECC',4,7,null,$b$Gâp n'gĭl đŏng uănh saơ nau dơm dam tâm dâng măt nar:$b$,true),
('bunong-vn','ECC',4,8,null,$b$Du huê bunuyh jêh rngloi (rêh êng du huê) mâu lĕ geh kon bu klâu jêh ri oh nâu, ƀiă lah nau hŏt păng mâu dơi dŭt, măt păng uănh mâu blau dĭl ma drăp ndơ; păng mâu mĭn ôh pô aơ; Pô ri lah gâp mâu pah kan hŏt ra-ah, gâp ăn huêng mâu geh nau ueh maak ma mbu moh yor? Nau nây tâm ban lĕ jêng dơm dam, na nê̆ kan mâu geh âk ôh.$b$,false),
('bunong-vn','ECC',4,9,null,$b$Bar hê jêng ueh lơn ma du huê, yor lah khân păng mra geh nau nkhôm ueh ma nau hŏt khân păng.$b$,true),
('bunong-vn','ECC',4,10,null,$b$Tơ lah bunuyh aơ cha lôt jêh, bunuyh ri mra sâm rdâk ăn păng; ƀiă lah rêh ni ngăn ma bunuyh gŭ êng du huê tơ lah păng cha lôt, mâu geh nuyh rdâk an!$b$,true),
('bunong-vn','ECC',4,11,null,$b$Tâm ban lĕ, tơ lah bar hê bêch ndrel geh nau răm; bi êng du huê mâm dơi geh nau răm?$b$,false),
('bunong-vn','ECC',4,12,null,$b$Jêh ri tơ lah nơm gŭ êng du huê, bu lơh dơi bu, bar hê mơ dơi rdâng đah păng; du mlâm rse ndrăn bu vah pe pha (mâu lah băr pe) jêng jêr tăch.$b$,false),
('bunong-vn','ECC',4,13,null,$b$Du huê mom ndăm o-ach jêh ri blau mĭn jêng ueh lơn ma du huê hađăch ranh jêh ri rluk, mâu hôm dơn ôh nau bu nchră,$b$,true),
('bunong-vn','ECC',4,14,null,$b$yor lah du huê ndăm păng luh tă bơh ndrung bu ăn hao jêng hađăch, nđâp tơ lah tâm ƀon bri hađăch păng nơm bu deh ma păng o-ach.$b$,false),
('bunong-vn','ECC',4,15,null,$b$Gâp saơ jêh lĕ rngôch phung rêh rô̆ nsong tâm dâng măt nar, tâm ban lĕ tĭng ndô̆ du huê ndăm nây mra trok hađăch ri;$b$,false),
('bunong-vn','ECC',4,16,null,$b$mâu dơi kơp ôh lĕ rngôch phung ƀon lan păng. Ƀiă lah phung tât pa kơi lơn mâu mra răm rhơn ôh ma păng. N'hêl nanê̆ nau nây tâm ban lĕ jêng dơm dam jêh ri tĭng rlong sial khôm.$b$,false),
('bunong-vn','ECC',5,1,null,$b$Njrăng hom ma nhuat may tơ lah may chuat hăn ma ngih Brah Ndu; hăn dăch gay gŭ iăt jêng ueh lơn ma nhhơr ndơ ƀư brah nâm bu phung rluk nhhơr; yor lah khân păng mâu gĭt ôh ma nau khân păng ƀư mhĭk.$b$,true),
('bunong-vn','ECC',5,2,null,$b$Lơi ir ngơi ndal ôh, jêh ri nuih n'hâm khân may lơi ir ndil ndal ôh ngơi ta năp Brah Ndu; yor lah Brah Ndu gŭ klơ trôk, bi may tâm dâng neh ntu. Yor ri ăn may ngơi djê̆ hŏ ngơi djê̆-lê̆.$b$,true),
('bunong-vn','ECC',5,3,null,$b$Lah âk nau mĭn rvê jêng nau mbơi; bi ma nau âk ir ngơi jêng nau rluk.$b$,false),
('bunong-vn','ECC',5,4,null,$b$Tơ lah hăn may ton moh ntil nau ma Brah Ndu, lơi hôm jŏ jong ngăn ôh nau nây, yor lah Brah Ndu mâu maak ôh ma phung rluk. Ngơi ngăn hom moh nau khân may ton.$b$,true),
('bunong-vn','ECC',5,5,null,$b$Ueh lơn may mâu ton ôh ma đah nau may ton jêh, ƀiă lah mâu yŏng ngăn ôh.$b$,false),
('bunong-vn','ECC',5,6,null,$b$Lơi ăn trôm mbung may njŭn may tâm nau tih ôh, jêh ri lơi lah ôh ta năp oh mon ueh Brah Ndu nau ton nây jêng vĭ hêng jêh. Moh khlay ăn bunuyh nuih ma bâr may ngơi, jêh ri ƀư rai kan ti may ƀư?$b$,true),
('bunong-vn','ECC',5,7,null,$b$Yor lah âk nau mbơi jêh ri âk nau ngơi mâu khlay ôh jêng dơm dam; ƀiă lah ăn may klach yơk hom ma Brah Ndu.$b$,false),
('bunong-vn','ECC',5,8,null,$b$Tơ lah may saơ du bri dak bu tŭn jot phung o-ach jêh ri phung rlau jêh nau sŏng jêh ri nau di, lơi hih rhâl ôh ma nau nây. Yor lah du huê kôranh toyh lơn sek uănh păng, jêh ri ăt geh nơm toyh lơn đŏng chiă uănh păng.$b$,true),
('bunong-vn','ECC',5,9,null,$b$Lĕ ngôch bunuyh sŏk play tă bơh mir, jêh ri hađăch tâm ban lĕ sŏk play nây đŏng.$b$,false),
('bunong-vn','ECC',5,10,null,$b$Mbu nơm rŏng ma prăk kŏ mpay lĕ ma prăk, bunuyh ŭch đŏng ma drăp ndơ kŏ mâu dơi dŭt lĕ ma nau ŭch hao; nau nây tâm ban lĕ êng dơm dam.$b$,true),
('bunong-vn','ECC',5,11,null,$b$Tơ lah dô ndơ sông sa hao âk, phung sa ndơ nây êng âk dah nây lĕ; jêh ri nơm geh drăp ndơ nây moh jêng khlay knŏng uănh saơ dơm păng ta năp măt?$b$,false),
('bunong-vn','ECC',5,12,null,$b$Nơm pah kan hŏt ra-ah bêch ueh ngăn, nđâp tơ lah păng sa djê̆ mâu lah âk; ƀiă lah ndô ndơ âk phung ndrŏng mâu hăk bêch ôh.$b$,true),
('bunong-vn','ECC',5,13,null,$b$Geh du nau djơh jru gâp saơ jêh tâm dâng măt nar: Bu prăp nau ndrŏng, jêng nau mhĭk plơ̆ ma păng nơm,$b$,false),
('bunong-vn','ECC',5,14,null,$b$Jêh ri nau ndrŏng aơ roh yot yor tă nau mhĭk nây; tơ lah nơm geh drăp ndơ dơi deh du huê oh bu klâu, mâu geh ndơ ăn ma ô băl ôh knŏng bar đah ti dơm.$b$,false),
('bunong-vn','ECC',5,15,null,$b$Lah he luh bơh ndŭl me, săk lưn dơm, ăt mra plơ̆ sĭt kơt nây lĕ, jêh ri ma nau kan hŏt ra ah păng mâu djôt leo du ntil ndơ ôh.$b$,false),
('bunong-vn','ECC',5,16,null,$b$Nau aơ tâm ban lĕ jêng du nau mhĭk toyh: Nâm bu păng luh bơh ndŭl me, păng mra plơ̆ sĭt nâm bu nây lĕ. Pô ri, dơn nau hŏt rgănh gay tĭng rlong sial khôm, geh ndơ khlay lĕ?$b$,false),
('bunong-vn','ECC',5,17,null,$b$Du bông nau rêh păng dơn tâm nau ngo klĕng, geh âk nau rngot rvê, geh âk nau uh-ah, nau ji kuet, jêh ri âk nau rsuak.$b$,false),
('bunong-vn','ECC',5,18,null,$b$Aơ, nau gâp hŏ saơ jêng ueh jêh ri di jêng nau sông sa, nhêt jêh ri geh nau maak ma lĕ rngôch kan păng ƀư tâm dâng măt nar du bông păng gŭ rêh Brah Ndu ăn; yor lah nau nây hŏ nal jêh ăn ma păng.$b$,true),
('bunong-vn','ECC',5,19,null,$b$Ăp nuyh mbu Brah Ndu păng ăn jêh nau jêng ndrŏng, âk drăp ndơ, ăn ma bunuyh nây dơi dŏng, mra sŏk dơn kô̆ di ma păng jêh ri geh nau maak tâm an păng, -nây jêng du nau Brah Ndu$b$,false),
('bunong-vn','ECC',5,20,null,$b$Yor lah geh âk bunuyh mâu hôm nă kah gĭt ma nar păng gŭ rêh; yor lah Brah Ndu mplơ̆ sĭt jêh ma păng nau răm maak tâm nuih n'hâm păng.$b$,false),
('bunong-vn','ECC',6,1,null,$b$Geh du nau mhĭk êng gâp saơ tâm dâng măt nar, jêh ri nau nây ƀư jâk lĕ rngôch bunuyh:$b$,true),
('bunong-vn','ECC',6,2,null,$b$Aơ, geh du huê Brah Ndu ăn jêh nau ndrŏng, âk drăp ndơ, jêh ri nau bu yơk; kŏ tât dơi geh lĕ ntil ndơ nau nuih n'hâm păng ŭch, mâu pưt du ntil ôh; ƀiă lah Brah Ndu mâu ăn păng dơn đŏng ndơ nây ôh, ƀiă lah geh bu êng dơi dŏng ndơ nây. Nây jêng nau dơm dam, du nau rêh ni ngăn.$b$,false),
('bunong-vn','ECC',6,3,null,$b$Tơ lah du huê bunuyh geh du rhiăng nuyh kon sau, jêh ri gŭ rêh âk năm; ƀiă lah păng mâu geh đŏng ôh nau ueh maak tâm nau rêh; jêh ri khĭt mâu geh lĕ nau tâp brôi ăn ueh, gâp mĭn, du huê kon bu lĕ rlêh jêng ueh lơn ma păng.$b$,false),
('bunong-vn','ECC',6,4,null,$b$Yor lah kon bu rlêh nây tât ma nau dơm dam jêh ri hăn tâm nau ngo klĕng, jêh ri amoh păng tâm ntŭk ngo klĕng; bu mâu hôm kah gĭt ma păng ôh.$b$,false),
('bunong-vn','ECC',6,5,null,$b$Păng mâu saơ măt nar, păng ăt mâu gĭt năl lĕ moh dơ nây; ƀiă lah păng geh nau rlu lơn ma đah bunuyh ri.$b$,false),
('bunong-vn','ECC',6,6,null,$b$Nđâp tơ lah păng mra jŏk rêh bar rbăn năm ƀiă lah mâu geh nau ueh maak ôh nglĕ dŭt lĕ ngôch mâu hĕ sĭt nsum du ntŭk?$b$,false),
('bunong-vn','ECC',6,7,null,$b$Lĕ ngôch nau hŏt ra-ah ma kon bunuyh ƀư yor prăp ta trôm mbung păng nơm, ƀiă lah nau păng ŭch sa mâu blau mpay ôh.$b$,true),
('bunong-vn','ECC',6,8,null,$b$Du huê bunuyh blau mĭn moh nau ueh lơn đah bunuyh rluk-mâl? Jêh ri du huê bunuyh o-ach gĭt nau ti, gŭ ngao ôi măng ueh, ta năp măt bunuyh, moh nau khlay păng geh?$b$,true),
('bunong-vn','ECC',6,9,null,$b$Jêng ueh lơn gŭ maak đah ndơ trôm măt saơ ma đah nau kơnh blă blơ. Nau nây tâm ban lĕ jêng dơm dam, jêh ri tĭng rlong sial khôm.$b$,true),
('bunong-vn','ECC',6,10,null,$b$Moh ndơ geh jêh bu hŏ ntơ amoh bơh sa ơm; jêh ri bu lĕ gĭt mâm bunuyh jêng, jêh ri păng mâu dơi tâm rlăch ôh đah du huê Nơm ktang lơn ma păng.$b$,true),
('bunong-vn','ECC',6,11,null,$b$Dôl ngơi âk lơn jêng dơm dam lơn lĕ, jêh ri moh nau ueh lơn ma bunuyh yor nau nây?$b$,true),
('bunong-vn','ECC',6,12,null,$b$Yor lah bu gĭt moh jêng ueh lơn ma bunuyh dôl gŭ jêh ƀât lât tâm nau rêh dơm dam păng, rlau lôch nâm bu n'hâm tơm si? Yor lah mbu nơm dơi mbơh ma bunuyh nau mra tât kăndơ̆ ma păng tâm dâng măt nar?$b$,false),
('bunong-vn','ECC',7,1,null,$b$Amoh geh nau lư n'găr jêng ueh lơn ma dak kôlônh khlay; jêh ri nar khĭt ueh lơn nar deh nkeng.$b$,true),
('bunong-vn','ECC',7,2,null,$b$Jêng ueh lơn hăn tât ngih vâl nhĭm vơl (klâng ndrê) ma đah hăn tât ngih vâl nhêt sa maak. Yor lah nau khĭt jêng nau lôch dŭt ma lĕ rngôch bunuyh, jêh ri phung hôm-e ăn kah gĭt mĭn ma nau nây.$b$,true),
('bunong-vn','ECC',7,3,null,$b$Nau rngot jêng ueh lơn ma nau gơm, yor lah ma muh măt rngot nuih n'hâm geh nau maak.$b$,true),
('bunong-vn','ECC',7,4,null,$b$Nuih n'hâm nơm blau mĭn gŭ tâm ngih klâng drê; ƀiă lah nuih n'hâm phung rluk gŭ tâm ngih pâl rlưn.$b$,true),
('bunong-vn','ECC',7,5,null,$b$Ueh lơn ma du huê bunuyh tông iăt nau phung blau mĭn nduyh ma đah iăt nau phung rluk mprơ.$b$,true),
('bunong-vn','ECC',7,6,null,$b$Yor lah nau gơm phung rluk nâm bu ŭnh sa lok tâm dâng lah, nau nây tâm ban lĕ, jêng nau dơm dam.$b$,true),
('bunong-vn','ECC',7,7,null,$b$N'hêl nanê̆, nau tŭn jot ăn nơm blau mĭn jêng bunuyh rluk, jêh ri nau sa bêch drăp ndơ bu nsŭk ăn djơh nuih n'hâm nơm.$b$,true),
('bunong-vn','ECC',7,8,null,$b$Nau n'glĕ dŭt, du nau jêng ueh lơn ma nau ntơm sa ơm; jêh ri nau gĭt nsrôih jêng ueh lơn ma nơm sưr$b$,true),
('bunong-vn','ECC',7,9,null,$b$Lơi ir ngăch ji nuih; yor lah nau ji nuih gŭ tâm nuih n'hâm phung rluk.$b$,false),
('bunong-vn','ECC',7,10,null,$b$Lơi ta lah: Tâm ƀư rnôk kăl e jêng ueh lơn ma rnôk aƀaơ? Yor lah mâu di ôh jêng nau blau mĭn ôp nau nây.$b$,true),
('bunong-vn','ECC',7,11,null,$b$Nau blau mĭn jêng nâm bu ndơn drăp; păng jêng khlay ma phung saơ măt nar.$b$,false),
('bunong-vn','ECC',7,12,null,$b$Yor lah nau blau mĭn nching săk jăn nâm bu prăk rêl nching săk jăn tâm ban lĕ; ƀiă lah nau blau mĭn dơi lơn, yor lah păng mât njăng nau rêh ăn bunuyh geh nau blau mĭn.$b$,false),
('bunong-vn','ECC',7,13,null,$b$Mêt uănh hom kan tă bơh Brah Ndu; yor lah moh ndơ Păng hŏ mbang ăn kue jêh, bu dơi bât nsŏng tay?$b$,true),
('bunong-vn','ECC',7,14,null,$b$Dôl nar geh nau chăt hao hâk răm hom, jêh ri tâm nar geh nau rêh ni sek mĭn hom; yor lah Brah Ndu da dê njêng nar aơ jêh ri ôi taơ, lĕ bar nau nây; gay ăn bunuyh mâu dơi gĭt ôh moh nau mra tât ma păng, du nar kăndơ̆ .$b$,true),
('bunong-vn','ECC',7,15,null,$b$Tâm nau rêh dơm dam bơh gâp, gâp saơ jêh lĕ ngôch nau: Geh du huê bunuyh sŏng khă lah păng sŏng ăt păng rai lôch tâm ban lĕ; jêh ri geh du huê bunuyh djơh khă lah păng djơh rlơ̆ ma geh nau jŏk rêh tâm nau ƀư mhĭk.$b$,true),
('bunong-vn','ECC',7,16,null,$b$Lơi jêng sŏng rlau keh ôh, jêh ri lơi njêng may nơm blau mĭn ir ôh; moh khlay may ƀư rai may nơm?$b$,false),
('bunong-vn','ECC',7,17,null,$b$Lơi ta djơh rlau keh ir ôh, mâu lĕ jêng du huê rluk. Moh khlay may khĭt lor pa năp ma nar bu nal?$b$,false),
('bunong-vn','ECC',7,18,null,$b$May dơi djôt prăp nau aơ, nây jêng ueh; ƀiă lah lơi hôm thoi đŏng nau êng ri, yor lah mbu nơm klach yơk ma Brah Ndu der lĕ rngôch ntil nau nây.$b$,false),
('bunong-vn','ECC',7,19,null,$b$Nau blau mĭn may ăn bunuyh blau mĭn geh nau ktang lơn ma jât nuyh kôranh chiă uănh tâm du rplay ƀon toyh.$b$,true),
('bunong-vn','ECC',7,20,null,$b$N'hêl nanê̆ mâu geh ôh du huê bunuyh sŏng ta neh ntu aơ ƀư nau ueh jêh ri mâu mâp ƀư tih ôh.$b$,true),
('bunong-vn','ECC',7,21,null,$b$Lơi rkêng tôr ôh ma lĕ rngôch nau phung bunuyh lah, klach lah may tăng oh mon may rak rtăp ma may;$b$,false),
('bunong-vn','ECC',7,22,null,$b$nuih n'hâm may nơm gĭt jêh geh âk tơ̆ may hŏ rak rtăp jêh ma bu êng.$b$,false),
('bunong-vn','ECC',7,23,null,$b$Gâp rlong uănh jêh ma nau blau mĭn lĕ rngôch nau aơ; gâp lah: Gâp mra jêng blau mĭn, ƀiă lah lah nau blau mĭn jêng ngai ma gâp.$b$,true),
('bunong-vn','ECC',7,24,null,$b$Moh nau lĕ jêng ngai, jru, jru ngăn, mbu dơi gĭt rbăng nau nây?$b$,false),
('bunong-vn','ECC',7,25,null,$b$Gâp prăp nau mĭn ŭch gĭt jêh ri tĭng joi gay saơ nau blau mĭn jêh ri rblang ma lĕ rngôch ndơ, jêh ri ŭch gĭt nau djơh tă bơh nau rluk, jêh ri ŭch gĭt nau djơh tă bơh nau rluk, jêh ri nau rluk jêng rluk.$b$,true),
('bunong-vn','ECC',7,26,null,$b$Gâp saơ jêh nau rngot jâk lơn nau khĭt, jêng du huê bu ur geh nuih n'hâm plĕch jêh ri rlăm ndơm bu, jêh ri ti păng jêng du rse rvăk: Mbu nơm gŭ ngao ueh ta năp Brah Ndu mra dơi klaih bơh păng; bi ma nơm geh nau tih păng nhŭp rdâng.$b$,false),
('bunong-vn','ECC',7,27,null,$b$Aơ nau gâp saơ, Kôranh Nơm Nti lah: Sek uănh lĕ ntil nau, lĕ ntil ndơ, gay ŭch saơ nau di ngăn, pô ri aơ jêng nau gâp dơi saơ nau rblang;$b$,true),
('bunong-vn','ECC',7,28,null,$b$nau nây gâp hôm e joi ƀa ƀơ, ƀiă lah mâu gĭt saơ ôh: Ta nklang du rbăn nuyh gâp saơ du huê bu klâu sŏng, ƀiă lah gâp mâu saơ ôh du huê bu ur sŏng, ta nklang lĕ rngôch phung bu ur.$b$,false),
('bunong-vn','ECC',7,29,null,$b$Aơ, knŏng nau aơ gâp saơ, Brah du njêng jêh bunuyh sŏng, ƀiă lah khân păng tĭng joi âk nau kue.$b$,false),
('bunong-vn','ECC',8,1,null,$b$Mbu nơm jêng nâm bu du huê bunuyh blau mĭn? Jêh ri mbu dơi rblang lĕ ntil ndơ? Nau blau mĭn du huê bunuyh ăn muh măt păng jêng ang, Jêh ri tâm rgâl lơi nau dăng jâk muh măt păng.$b$,true),
('bunong-vn','ECC',8,2,null,$b$Djôt răp hom nau hađăch ntăm, yor nau may sơm săk ta năp Brah Ndu.$b$,true),
('bunong-vn','ECC',8,3,null,$b$Lơi ir ndal rŭch plơ̆ tă bơh ta năp păng; lơi dơh dăch đah nau djơh ôh, yor lah păng ƀư tĭng nau păng ŭch.$b$,false),
('bunong-vn','ECC',8,4,null,$b$Yor lah nau hađăch ngơi geh nau rnam, mbu dơi lah ma păng, Moh may ƀư?$b$,false),
('bunong-vn','ECC',8,5,null,$b$Mbu nơm tông ma nau păng ntăm mâu mra mâp nau mhĭk ôh, jêh ri nau mĭn du huê bunuyh blau mĭn mra gĭt mông găl jêh ri trong ƀư.$b$,true),
('bunong-vn','ECC',8,6,null,$b$Yor lah tĭng nâm bunuyh geh nau rŭng răng tât âk ntil, moh ntil nau tâm ban lĕ geh mông găl jêh ri lĕ ơm trong da dê.$b$,true),
('bunong-vn','ECC',8,7,null,$b$Yor lah păng mâu gĭt ôh moh nau mra tât, yor lah mbu dơi mbơh ma păng mâm mra jêng?$b$,true),
('bunong-vn','ECC',8,8,null,$b$Mâu geh ôh du huê bunuyh geh nau brah dơi mât chiă huêng păng, mâu lah geh nau dơi dun nau khĭt; tơ lah geh nau tâm lơh mâu geh ôh nơm tâm mƀơk an; kŏ mâu geh lĕ nau djơh dơi tâm rklaih phung ƀư nau djơh, nau mhĭk.$b$,true),
('bunong-vn','ECC',8,9,null,$b$Gâp saơ jêh nau nây dôl gâp gŭ mĭn sek uănh ma lĕ rngôch nau bu ƀư tâm dâng măt nar, geh tơ̆ bunuyh ƀư kôranh ma bunuyh êng; nau nây ƀư mhĭk ma păng ơm.$b$,true),
('bunong-vn','ECC',8,10,null,$b$Gâp saơ jêh phung bunuyh djơh khĭt; jêh ri bu tâp brôi ueh djhep; bi ma phung bunuyh ƀư nau ueh nkhơng bu ngluh lơi bơh ntŭk kloh ueh, geh bunuyh gŭ du ƀon chuêl păng. Nây tâm ban lĕ jêng nau dơm dam.$b$,true),
('bunong-vn','ECC',8,11,null,$b$Tơ lah nau phat dôih ma nau mhĭk bu ƀư jêh mâu phat gơnh ro ôh, nuih n'hâm phung kon bunuyh lĕ mơng ƀư nau mhĭk.$b$,true),
('bunong-vn','ECC',8,12,null,$b$Yor lah bunuyh tih ƀư mhĭk rhiăng tơ̆ ăt dơi geh nau jŏk rêh; nđâp tơ lah pô nây, gâp gĭt nau mra tât ma phung klach yơk ma Brah du, nar kêng lôch mra dơi geh nau ueh uĭn.$b$,true),
('bunong-vn','ECC',8,13,null,$b$Ƀiă lah nau tât ma phung djơh mâu jêng ueh ôh, mâu mra geh nau jong rêh ôh, yor lah nau rêh păng nâm bu n'hâm tơm si; yor păng mâu klach yơk ôh ta năp Brah Ndu.$b$,true),
('bunong-vn','ECC',8,14,null,$b$Geh du nau jêng dơm dam tât ta neh ntu: Geh âk phung sŏng geh nau tât nâm bu nau tât ma phung djơh lĕ; jêh ri geh âk phung djơh geh nau tât nâm bu phung sŏng lĕ Gâp lah nau nây tâm ban lĕ jêng nau dơm dam.$b$,true),
('bunong-vn','ECC',8,15,null,$b$Pô ri gâp tâm rnê ma nau hâk răm, yor lah bunuyh mâu geh nau ueh lơn ôh tâm dâng măt nar, knŏng sông sa, nhêt, jêh ri ƀư âk ma păng nơm; yor lah nau nây mra gŭ ndrel ma păng tâm kan păng ƀư du bông nau rêh, păng rêh Brah Ndu ăn ma păng tâm dâng măt nar.$b$,true),
('bunong-vn','ECC',8,16,null,$b$Tơ lah gâp gơih prăp nau mĭn gâp ŭch nti ăn gĭt nau blau mĭn, gay gĭt rbăng lĕ rngôch kan ƀư ta neh ntu, pô ri gâp saơ geh bunuyh nar măng măt mâu geh bêch ôh,$b$,true),
('bunong-vn','ECC',8,17,null,$b$gâp saơ jêh nau Brah Ndu hŏ ƀư jêh. Bunuyh mâu dơi gĭt rbăng ôh lĕ nau tât tâm dâng măt nar. Nđâp tơ lah bunuyh pah kan joi nau nây, păng mâu mra gĭt rbăng ôh; nđâp tơ lah du huê bunuyh blau mĭn, ntôn lah păng gĭt rbăng, ƀiă lah păng mâu dơi gĭt rbăng nau nây ôh.$b$,false),
('bunong-vn','ECC',9,1,null,$b$Aơ jêng du nau kan êng gâp hŏ mĭn rvê jêh ri prăp tâm nuih n'hâm rah vah jêh: Gâp saơ bunuyh đŏng jêh ri bunuyh blau mĭn, nau kan khân păng ƀư gŭ tâm ti Brah Ndu; bunuyh mâu lah nau rŏng gĭt lah nau tâm rmot, bunuyh mâu gĭt rah vah ôh: Lĕ nau nây prăp ma ô klak.$b$,true),
('bunong-vn','ECC',9,2,null,$b$Lĕ rngôch nau ta năp khân păng jêng dơm dam, yor lah geh du nau nglĕ dŭt tât ma lĕ rngôch bunuyh, tâm ban da dê: Ma phung bunuyh sŏng jêh ri ma phung djơh, ma phung ueh jêh ri ma phung mhĭk, ma phung kloh ueh jêh ri ma phung ƀơ̆ , ma nơm nhhơr ndơ ƀư brah jêh ri ma nơm mâu nhhơr ôh. Nâm bu bunuyh ueh jêng, tâm ban nây lĕ bunuyh mhĭk jêng. Jêh ri mbu nơm sân săk jêng nâm bu nơm klach nau sân săk.$b$,false),
('bunong-vn','ECC',9,3,null,$b$Aơ êng du nau mhĭk lơn tâm lĕ rngôch nau bu ƀư tâm dâng măt nar: Du nau lôch dŭt tât ma lĕ rngôch; tâm ban lĕ nuih n'hâm phung bunuyh bêng ma nau mhĭk, jêh ri nau rluk gŭ rêh, jêh nau nây khân păng hăn rlet ntŭk phung khĭt.$b$,true),
('bunong-vn','ECC',9,4,null,$b$Du huê tâm mpôl phung rêh, hôm e geh nau kâp gân; yor lah du mlâm so rêh jêng geh lơn ma du mlâm yau mŭr lĕ khĭt.$b$,true),
('bunong-vn','ECC',9,5,null,$b$Yor lah phung rêh gĭt ma khân păng mra khĭt, ƀiă lah phung lĕ khĭt mâu gĭt rbăng du ntil nau ôh. Jêh ri khân păng mâu hôm geh nau nkhôm ôh, ƀiă lah bu mâu hôm kah gĭt ôh ma khân păng.$b$,true),
('bunong-vn','ECC',9,6,null,$b$Khân păng rŏng nau khân păng tâm rmot, nau ji nuih biănh, jêh ri nau khân păng kơnh hŏ roh jêh lĕ rngôch; khân păng mâu hôm geh du kô̆ ôh tâm lĕ nau bu ƀư tâm dâng măt nar.$b$,true),
('bunong-vn','ECC',9,7,null,$b$Hăn sông sa hom ma nau maak, jêh ri nhêt dak play kriăk ƀâu may ma nuih n'hâm rhơn, yor lah Brah Ndu dơn jêh nau may ƀư.$b$,true),
('bunong-vn','ECC',9,8,null,$b$Ăn kho ao may jêng nglang ƀa ƀơ, lơi tăch yơt ôh dak kôlônh klơ bôk may.$b$,true),
('bunong-vn','ECC',9,9,null,$b$Gŭ rêh hâk răm hom, ndrel ur may rŏng jêh, lĕ rngôch nar may gŭ rêh dơm dam Brah Ndu ăn jêh ma may, tâm dâng măt nar; yor lah nây jêng kô̆ bu pă ma may tâm nau rêh, jêh ri tâm nau kan may ƀư hŏt ra- ah tâm dâng măt nar.$b$,true),
('bunong-vn','ECC',9,10,null,$b$Moh nau ti may ƀư, ƀư hom nau nây ma lĕ n'hâm suan may; yor lah tâm Ƀon Phung Khĭt, jêng ntŭk ma may mra hăn tât, mâu geh ăn kan, mâu geh nau mĭn mâu lah nau blau mĭn ôh.$b$,false),
('bunong-vn','ECC',9,11,null,$b$Gâp rle n'gĭl tay saơ tâm dâng măt nar: Geh nuyh prăl mâu dơi ôh đah nau tâm rlong nchuăt, mâu geh lĕ nau ktang dơi đah nau tâm lơh, mâu geh lĕ ndơ sông sa prăp knŏng ma phung blau mĭn mâu geh lĕ nau ndrŏng prăp ma nơm gĭt rbăng mâu geh lĕ dơi prăp ma nơm njêh; ƀiă lah nar găl jêh ri nau ƀun lap tât ma lĕ rngôch khân păng.$b$,true),
('bunong-vn','ECC',9,12,null,$b$Yor lah bunuyh mâu gĭt ôh nar păng khĭt. Nâm bu ka geh yŭ jêh ri sĭm geh mong (nhuăl), nâm bu nây lĕ phung kon bunuyh geh dăk tâm nar mhĭk, tơ lah nau nây tât ƀât lât dơm, ma khân păng.$b$,true),
('bunong-vn','ECC',9,13,null,$b$Tâm ban lĕ gâp saơ jêng nau ntĭt aơ ma nau blau mĭn tâm dâng măt nar, jêh ri nau nây gâp mĭn jêng toyh.$b$,true),
('bunong-vn','ECC',9,14,null,$b$Geh du rplay ƀon jê̆ geh bunuyh ƀhôi lĕ gŭ ta nây; jêh ri du huê hađăch toyh văch lơh ma ƀon nây jêh ri nchueng jŭm ŭch sŏk ƀon nây lĕ du huê bunuyh o-ach blau mĭn, jêh ri ma nau blau mĭn păng, păng tâm rklaih ƀon nây.$b$,false),
('bunong-vn','ECC',9,15,null,$b$Ƀiă lah mâu geh nuyh kah gĭt ôh ma ô băl jêng ach nây.$b$,false),
('bunong-vn','ECC',9,16,null,$b$Pô ri gâp lah, nau blau mĭn jêng ueh lơn ma nau ktang, ƀiă lah nau blau mĭn bunuyh o-ach bu tâm rmot lơi, nau ngơi ma du huê bunuyh nây bu mâu chrê ôh,$b$,false),
('bunong-vn','ECC',9,17,null,$b$du huê bunuyh blau mĭn ngơi bu gŭ iăt săk răk klăk jêng ueh lơn ma du huê hađăch nter ta klang phung rluk,$b$,false),
('bunong-vn','ECC',9,18,null,$b$Nau blau mĭn jêng ueh lơn ma âk ndô ndơ tâm lơh, ƀiă lah du huê bunuyh tih ƀư rai lơi âk kan ueh.$b$,false),
('bunong-vn','ECC',10,1,null,$b$Rhuay hĭt jêh ƀư ƀâu ôm dak ƀâu kah nơm njêng păng; tâm ban pô nây lĕ nau rluk nkhơng dơi ƀư roh nau blau mĭn jêh ri nau yơk.$b$,true),
('bunong-vn','ECC',10,2,null,$b$Play nuih bunuyh blau mĭn gŭ pa ma (nâm bu ntĭt nuih n'hâm du huê nuyh blau mĭn ntrôl păng peh nau di); bi ma play nuih du huê bunuyh rluk gŭ mpeh pa chiau, nâm bu ntĭt ƀiă lah nuih n'hâm du huê rluk ntrôl păng mpeh nau vĭ jêh.$b$,true),
('bunong-vn','ECC',10,3,null,$b$Nđâp tơ lah păng rluk hăn ta trong, păng mâu geh nau mĭn ôh, jêh ri păng lah ma ăp nuyh pô aơ păng jêng nuyh rluk.$b$,true),
('bunong-vn','ECC',10,4,null,$b$Tơ lah nơm chiă uănh hao ji nuih ma may, lơi may du ôh tă bơh ntŭk may; yor lah nau rdơ̆ rbăn may nching lơi gay bah nau tih toyh.$b$,true),
('bunong-vn','ECC',10,5,null,$b$Geh du nau mhĭk gâp saơ tâm dâng măt nar, nâm bu du huê nơm chiă uănh ƀư nau vĭ-vĭr.$b$,true),
('bunong-vn','ECC',10,6,null,$b$Nau rluk gŭ ta klơ, jêh ri phung ndrŏng gŭ tâm dâng.$b$,true),
('bunong-vn','ECC',10,7,null,$b$Gâp lĕ saơ jêh phung dĭk bu ncho seh, jêh ri phung kôranh jêng nâm bu dĭk bu.$b$,true),
('bunong-vn','ECC',10,8,null,$b$Mbu nơm kuyh ntu mra tŭp tâm ntu nây, jêh ri du mlâm bêh mra chôk nơm lôk mpir.$b$,true),
('bunong-vn','ECC',10,9,null,$b$Mbu nơm rlă lŭ trơn ntŭk păng, mra geh nau sôt lŭ ntŭn, jêh ri nơm rlah long mâu lăng rlăp geh nau mhĭk đah long nây.$b$,true),
('bunong-vn','ECC',10,10,null,$b$Tơ lah măt sung lĕ ƀât jêh, tơ lah bu mâu theng ôh, păng mra nsan dŏng nau dăng suan âk lơn; ƀiă lah nau blau mĭn kơl bu geh nau dơi.$b$,true),
('bunong-vn','ECC',10,11,null,$b$Tơ lah bêh hôk ê-lor bu nđơih păng ăn ơih, pô ri nơm nđơih mâu jêng khlay ôh.$b$,true),
('bunong-vn','ECC',10,12,null,$b$Nau ngơi bơh bâr mbung bunuyh blau mĭn, ngơi ăn tât nau bu yô̆ ma păng, ƀiă lah mpiăt bunuyh rluk ngơi ƀư rai păng nơm.$b$,true),
('bunong-vn','ECC',10,13,null,$b$Nau ngơi bơh bâr mbung păng ngơi, ntơm sa ơm jêng rluk, jêh ri nglĕ dŭt jêng rluk djơh ngăn.$b$,true),
('bunong-vn','ECC',10,14,null,$b$Bunuyh rluk hay ngơi âk nau; nđâp tơ lah pô nây, păng mâu gĭt ôh nau mra tât; jêh ri mbu nơm moh mbơh nau mra geh ma păng kăndơ̆ ?$b$,true),
('bunong-vn','ECC',10,15,null,$b$Kan bunuyh rluk ƀư hŏt ra ah păng nơm, yor lah păng mâu gĭt ta ntŭk trong hăn rlet ma ƀon toyh.$b$,true),
('bunong-vn','ECC',10,16,null,$b$Hơi n'gor ri, rêh ni ngăn ma may; tơ lah geh hađăch hôm-e kon se, jêh ri phung kôranh mâu gŭ nhêt sa ntơm bơh ang ôi!$b$,true),
('bunong-vn','ECC',10,17,null,$b$Hơi n'gor ri, Maak ngăn ma may, tơ lah hađăch may jêng bunuyh kon me (noi lư rnam), jêh ri phung kôranh may geh nau nhêt sa di mông, gay geh nau ngăch prăl, mâu di ôh ŭch ma nhŭl ndrănh!$b$,true),
('bunong-vn','ECC',10,18,null,$b$Yor ti ƀlao pah chor ngih dĭng văm; yor ti ăp năm mâu ƀư ngih vâl dĭng truh.$b$,true),
('bunong-vn','ECC',10,19,null,$b$Bu nkra ndơ nhêt sông sa prăp ma nau pâl rlưn, jêh ri dak play kriăk ƀâu ƀư maak nau rêh; geh prăk rêl kơl lĕ ntil nau bu ŭch.$b$,true),
('bunong-vn','ECC',10,20,null,$b$Nđâp tâm nau mĭn may lơi rak rtăp hađăch ôh; nđâp tơ lah tâm jrô may bêch tâm ban lĕ lơi rtăp rak bunuyh kuăng ndrŏng; yor lah sĭm mpăr klơ trôk mra rƀiah bâr ngơi may, jêh ri du mlâm mpa geh nting năr mra mbơh nau nây.$b$,true),
('bunong-vn','ECC',11,1,null,$b$Mƀăr lơi piăng let may ta klơ mpiăt dak (n'ha dak), yor lah rlau jŏ nar may joi tay păng đŏng.$b$,true),
('bunong-vn','ECC',11,2,null,$b$Tâm pă hom păng ăn ma pơh nuyh mâu lah pham nuyh, yor lah may mâu gĭt ôh moh nau mhĭk dơi ât ta bri neh.$b$,true),
('bunong-vn','ECC',11,3,null,$b$Tơ lah dâr tŭk bêng ma dak mih, trôk mra mih ta neh ntu; tơ lah geh du tơm si cha lôt mpeh rđŭng mâu lah mpeh dor, ntŭk rlet tơm si bông (chôt) păng mra gŭ ta nây.$b$,true),
('bunong-vn','ECC',11,4,null,$b$Mbu nơm sek uănh sial mâu mra srih ôh; mbu nơm uănh ndâr tŭk mâu mra rek lĕ.$b$,true),
('bunong-vn','ECC',11,5,null,$b$Nâm bu may mâu gĭt ôh rlong sial hăn, mâu lah mâm bu njêng săk jăn tâm trôm ndŭl du huê bu ur ntreo tâm ban nây lĕ may mâu gĭt rbăng ôh kan Brah Ndu$b$,true),
('bunong-vn','ECC',11,6,null,$b$Nơm rhăk njêng lĕ rngôch ntil may, Jêh ri kêng mhaơ lơi ut ôh ti may; Yor lah may mâu gĭt ôh moh ntil mra chăt hon, ntil aơ mâu lah ntil ri, mâu lah lĕ bar jêng ueh da dê.$b$,false),
('bunong-vn','ECC',11,7,null,$b$Nau ang jêng ueh, jêh ri jêng maak ma trôm măt uănh ma măt nar.$b$,true),
('bunong-vn','ECC',11,8,null,$b$Yor lah tơ lah du huê bunuyh gŭ rêh âk năm, ăn păng răm rhơn hom dôl lĕ năm nây; ƀiă lah ăn păng kah gĭt ma bri măng ngo klĕng, rluk lĕ rngôch nar jêng âk. Lĕ rngôch nau tât jêng dơm dam.$b$,true),
('bunong-vn','ECC',11,9,null,$b$Hâk răm hom, Hơi bu klâu ndăm, dôl may hôm mom, jêh ri ăn nuih n'hâm may gŭ maak dôl nôk may hôm mom. Chuat hăn hom tĭng trong may ŭch, Jêh ri tĭng nâm măt may saơ. Ƀiă lah ăn may gĭt yor lĕ nau nây Brah Ndu mra leo may ma nau phat dôih.$b$,true),
('bunong-vn','ECC',11,10,null,$b$Pô ri, ăn may ngluh lơi nau rŭng răng tă bơh nuih n'hâm may jêh ri mƀăr lơi lĕ nau ji tă bơh săk jăn may, yor lah nau jêng mom ndăm, jêh ri rnôk druh ndăm jêng dơm dam.$b$,true),
('bunong-vn','ECC',12,1,null,$b$Tâm dôl may hôm jêng kon se jê̆ ăn may kah gĭt hom ma Nơm- Rhăk-Njêng may, ê-lor ma nar mhĭk ê-hŏ tât, jêh ri ê lor năm mra tât rnôk nây may lah, Gâp mâu geh nau maak ôh tâm năm aơ,$b$,true),
('bunong-vn','ECC',12,2,null,$b$ê-lor măt nar sol ang, khay jêh ri mănh ê-hŏ jêng ngo klĕng, jêh ri ndâr tŭk văch may jêh mih;$b$,false),
('bunong-vn','ECC',12,3,null,$b$tâm nar nây phung mât uănh ngih râm nsâr, phung bunuyh ngăch dăng đôn gor kuyh (nting guyh), jêh ri phung rvah kĭn rnih gŭ rlu yor lah khân păng jêng ƀhôi, jêh ri phung gŭ mêt uănh ta mpông bloh lĕ ngo măt$b$,false),
('bunong-vn','ECC',12,4,null,$b$jêh ri bar seng mpông pêr ta trong sâng bu ntĭl lơi, tơ lah nteh bu rvah mpăl kĭn rnih jêng djo-djoch dơm; jêh ri du huê dâk, nôk nây bu tăng ndrau sĭm, jêh ri lĕ rngôch kon se bu ur mprơ gŭ rklăk;$b$,false),
('bunong-vn','ECC',12,5,null,$b$tâm ban lĕ khân păng klach ngăn hao ntŭk ta klơ, jêh ri klach krit ngăn dôl hăn rŏ trong; rnôk nây tơm nhăr luh kao, phung krah mâu hôm lot mpăr ôh, jêh ri nau păng ŭch mâu hôm geh ôh; yor lah rnôk nây bunuyh mra hăn tât ngih păng gŭ n'ho ro, jêh ri phung nhĭm vơl hăn ta trong ndăch jŭm trong ƀon toyh:$b$,false),
('bunong-vn','ECC',12,6,null,$b$Kah gĭt tay hom ma Nơm Rhăk Njêng ê lor ma se prăk tăch, mâu lah ngan rlŭ mah lĕ chah, mâu lah yăng chah ta tu dak, jêh ri jâng ndeh rvah dak lĕ pă gâl ta klơ ndrâm dak;$b$,false),
('bunong-vn','ECC',12,7,null,$b$jêh ri neh muy plơ̆ sĭt tâm neh jêng nâm bu kơt sa ơm, jêh ri huêng plơ̆ sĭt tay ma Brah Ndu nơm ăn păng.$b$,false),
('bunong-vn','ECC',12,8,null,$b$Kôranh nơm Nti lah; Nau dơm dam bơh nau dơm dam; lĕ ngôch jêng nau dơm dam da dê.$b$,true),
('bunong-vn','ECC',12,9,null,$b$Pô ri yơh, yor lah bunuyh jêng Kôranh Nơm Nti jêng du huê bunuyh blau mĭn, yor ri ăn păng nti nau blau mĭn ma phung ƀon lan tâm ban lĕ; păng hŏ nkah nau gĭt rbăng, sek uănh, nau nti, jêh ri chih dăp ăn di tâm tĭng nau hôr ma nau njrăng ngăn.$b$,true),
('bunong-vn','ECC',12,10,null,$b$Kôranh Nơm ti joi rplay ngơi ăn ƀư maak, jêh ri ma nau ngăn păng chih nau ngơi nau n'hêl nanê̆.$b$,false),
('bunong-vn','ECC',12,11,null,$b$Nau blau mĭn lah jêng nâm bu loih mplanh, jêh ri âk nau ngơi tă bơh nơm êng êng Rmăk biăp tâm rƀŭn jêh jêng nâm bu loih kađĭn bu pâng nâp.$b$,false),
('bunong-vn','ECC',12,12,null,$b$Hơi kon (hơi nâu), dơn hom lĕ rngôch nau hôm-e nây. Ăn bu ƀư âk ndrom sămƀŭt mâu blau lôch ôh, jêh ri tơ lah nti âk ir jêng rgănh ma săk jăn.$b$,true),
('bunong-vn','ECC',12,13,null,$b$Ăn he iăt nau nglĕ dŭt ma lĕ rngôch nau nti aơ: Klach yơk hom ma Brah Ndu jêh ri djôt prăp nau păng ntăm; Yor lah nau nây jêng lĕ nau di ăn may ƀư.$b$,true),
('bunong-vn','ECC',12,14,null,$b$Yor lah Brah Ndu mra phat dôih lĕ rngôch nau bu ƀư, ndrel ma lĕ rngôch nau ndâp, gĭt lah ueh mâu lah mhĭk.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','ECC',1,1,0,'heading',$b$Lĕ Rngôch Ndơ Jêng Dơm Dam$b$),
('bunong-vn','ECC',2,1,0,'heading',$b$Kan Pah Jêng Roh Yot Da Dê$b$),
('bunong-vn','ECC',3,1,0,'heading',$b$Brah Ndu Nal Năng Ma Lĕ Rngôch Ndơ$b$),
('bunong-vn','ECC',3,16,1,'heading',$b$Nau Mâu Sŏng Ôh Tât Tâm Rnôk Gŭ Rêh$b$),
('bunong-vn','ECC',4,1,0,'heading',$b$Nau Tŭn Jot, Nau Jêr Jêh Ri Nau Gŭ Êng$b$),
('bunong-vn','ECC',5,1,0,'heading',$b$Jêng Rluk Lah Mâu Mĭn Lor$b$),
('bunong-vn','ECC',5,8,1,'heading',$b$Nau Rêh Jêng Dơm Dam$b$),
('bunong-vn','ECC',6,1,0,'heading',$b$Geh Drăp Ndơ Ƀiă lah Mâu Dơn Ôh Jêng Dơm Dam$b$),
('bunong-vn','ECC',7,1,0,'heading',$b$Nau Ueh Lơn Bơh Nau Gĭt Mleh$b$),
('bunong-vn','ECC',7,23,1,'heading',$b$Tĭng Joi Nau Blau Mĭn$b$),
('bunong-vn','ECC',8,2,0,'heading',$b$Tông Hom Ma Hađăch$b$),
('bunong-vn','ECC',8,11,1,'heading',$b$Nau Mĭn Bunuyh Mâu Dơi Nkra Ôh Lĕ Ntil Nau$b$),
('bunong-vn','ECC',9,1,0,'heading',$b$Nau Lĭn Lơ Tâm Nau Rêh$b$),
('bunong-vn','ECC',9,11,1,'heading',$b$Nau Blau Mĭn Mâu Geh Nau Ueh Ƀa Ƀơ Ôh$b$),
('bunong-vn','ECC',9,13,2,'heading',$b$Nau Blau Mĭn Jêng Ueh Lơn Mơ Nau Ktang$b$),
('bunong-vn','ECC',10,1,0,'heading',$b$Nau Tât Yor Nau Rluk$b$),
('bunong-vn','ECC',11,1,0,'heading',$b$Nau Bunuyh Gĭt Mleh Gŭ Ngao Ôi Măng$b$),
('bunong-vn','ECC',11,9,1,'heading',$b$Nau Nchră Ma Phung Mom Ndăm$b$),
('bunong-vn','ECC',12,9,0,'heading',$b$Nau Di Ăn Bunuyh Ƀư$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'SNG', $b$Nau Mprơ Ueh$b$, $b$["Nau Mprơ Ueh Bơh", "Y-SALÔMÔN"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','SNG',1,1,null,$b$Nau mprơ ueh uĭn ma lĕ nau mprơ, jêng nau Y-Salômôn mprơ. Bu ur gŭ sai:$b$,true),
('bunong-vn','SNG',1,2,null,$b$Ăn may chŭm gâp ma trôm mbung may! Yor lah nau may rŏng jêng ueh ma dak play kriăk ƀâu,$b$,false),
('bunong-vn','SNG',1,3,null,$b$dak kôlônh may ƀâu kah ngăn, amoh may jêng nâm bu dak ƀâu kah n'hôl bu troch; yor nây yơh bu druh tang tat rŏng ma may.$b$,false),
('bunong-vn','SNG',1,4,null,$b$Têk leo hom gâp; ăn he hăn ndrel. Hađăch hŏ leo gâp lăp jrô păng. Phung băl: Hên mra răm maak jêh ri rhơn răm yor may; Hên mra tâm rnê ma nau may rŏng âk lơn ma dak play kriăk ƀâu. Bu ur gŭ sai: Jêng di ngăn yơh bu druh tang tat rŏng ma may.$b$,true),
('bunong-vn','SNG',1,5,null,$b$Hơi bu ur ƀon Yêrusalem, gâp krăk ngăn, ƀiă lah ray nkrơ̆ , Nâm bu ngih bok phung Kêdar, Nâm bu bok nching, Y-Salômôn.$b$,true),
('bunong-vn','SNG',1,6,null,$b$Lơi uănh ma gâp ôh, yor lah ntâu gâp krăk, duh nar nđat jêh gâp. Phung kon bu klâu mê̆ gâp nuih ma gâp, khân păng ăn gâp chiă mât n'gar play kriăk ƀâu; bi n'gar play kriăk ƀâu gâp nơm, gâp mâu hôm mât mray ôh.$b$,true),
('bunong-vn','SNG',1,7,null,$b$Hơi nơm gâp rŏng, mbơh hom ma gâp, ta ntŭk may chiăp biăp may, Nar nklang bôk ta ntŭk may ăn phung biăp may rlu kuen? Mbu moh yor gâp jêng nâm bu du huê bu ur nkŭm muh măt Gŭ ndrel phung biăp phung băl may? Bu klâu gŭ ur:$b$,true),
('bunong-vn','SNG',1,8,null,$b$Hơi bu ur ueh reh lơn tâm lĕ rngôch bu ur êng, Tơ lah ay mâu gĭt, luh hom tĭng têl phung biăp, Jêh ri chiăp phung be kon ay dăch êp ngih bok phung rmăk biăp.$b$,false),
('bunong-vn','SNG',1,9,null,$b$Hơi nơm gâp rŏng, gâp tâm rđĭl ay đah du mlâm seh me uih ndeh Pharaôn.$b$,true),
('bunong-vn','SNG',1,10,null,$b$Trô-bom ay ray ndrel drăp nkrơ̆ , trô ko ay ueh đŏng yor văn lŭ khlay.$b$,true),
('bunong-vn','SNG',1,11,null,$b$Hên mra nkra ma ay ndơ nkrơ̆ đah mah lĭr ndrel dak prăk Bu ur gŭ sai:$b$,true),
('bunong-vn','SNG',1,12,null,$b$Dôl hađăch lâng bêch ta sưng păng dak kôlônh gâp n'hôl ƀâu kah ma păng.$b$,false),
('bunong-vn','SNG',1,13,null,$b$Nơm gâp rŏng nâm bu du nchăp ndơ ƀâu kah đah gâp. Gŭ vah vang toh gâp.$b$,true),
('bunong-vn','SNG',1,14,null,$b$Nơm gâp rŏng nâm bu dun chăo kao hêna đah gâp. Tâm n'gar paly kriăk ƀâu Êngêdi. Bu klâu gŭ ur:$b$,true),
('bunong-vn','SNG',1,15,null,$b$Aơ, ay jêng ueh reh, Hơi nơm gâp rŏng, aơ, ay jêng ueh ngăn ngên; măt ay jêng nâm bu plŭk. Bu ur gŭ sai:$b$,false),
('bunong-vn','SNG',1,16,null,$b$Aơ, may jêng ueh ngăn, Hơi nơm gâp rŏng, Ueh rom ngăn ngên! Bu klâu gŭ ur: Sưng bêch he jêng nđĭk rĭt ngĭt$b$,false),
('bunong-vn','SNG',1,17,null,$b$chor ngih he ma tơm si sêdar jêh ri njon păng ƀư ma tơm n'ho Bu ur gŭ sai:$b$,false),
('bunong-vn','SNG',2,1,null,$b$Gâp jêng kao Rôs rlŭng Sarôn, du ntil li li tâm rlŭng. Bu klâu gŭ ur:$b$,true),
('bunong-vn','SNG',2,2,null,$b$Nâm bu kao lili ta nklang mpach lok, tâm ban nây lĕ gâp rŏng ta nklang phung bu ur druh. Bu ur gŭ sai:$b$,false),
('bunong-vn','SNG',2,3,null,$b$Nâm bu du tơm play pom ta nklang krŏng tâm ban nây lĕ gâp rŏng ta nklang phung bu klâu ndăm. Ma nau maak ngăn gŭ tâm dâng gui păng Jêh ri play păng njŭng rgăn tơ lah gâp sa.$b$,false),
('bunong-vn','SNG',2,4,null,$b$Păng leo gâp rlet ma ngih bu nhêt sa toyh, jêh ri nau păng rŏng jêng nâm bu n'ha bok kơ rpuh ta klơ gâp$b$,true),
('bunong-vn','SNG',2,5,null,$b$Ƀư mpay hom gâp ma play kriăk ƀâu, ƀư ktang gâp ma play pom; Yor lah gâp ji yor ma nau gâp rŏng.$b$,false),
('bunong-vn','SNG',2,6,null,$b$Ti chiau păng rkơl tâm dâng bôk gâp, bi ti pa ma păng rle ut gâp!$b$,true),
('bunong-vn','SNG',2,7,null,$b$Hơi phung bu ur druh ƀon Yêrusalem, gâp ntĭnh khân ay, Yor tă amoh yơng mâu lah jun me tâm bri, Lơi nsônh mâu lah rlay nau rŏng gâp. Ăn tât mông tơ lah păng ŭch$b$,true),
('bunong-vn','SNG',2,8,null,$b$Nây jêng bâr nơm gâp rŏng! Aơ, păng văch nsăt rlau ta klơ yôk, Jêh ri kdăt rlau ta klơ gôl.$b$,false),
('bunong-vn','SNG',2,9,null,$b$Nơm gâp rŏng jêng nâm bu Yơng, mâu lah du mlâm jun ndăm. Aơ, păng dâk pa kơi mpir ngih hên, Păng mêt ta trôm mpông bloh jêh ri uănh ta trôm nđa.$b$,true),
('bunong-vn','SNG',2,10,null,$b$Nơm gâp rŏng ngơi jêh ri lah ma gâp: Dâk hom, Hơi nơm gâp rŏng, nơm ueh reh gâp, Jêh ri hăn hom he,$b$,true),
('bunong-vn','SNG',2,11,null,$b$Yor lah aơ, Yan puh rlau jêh, jêh ri trôk mih lĕ prăng jêh.$b$,false),
('bunong-vn','SNG',2,12,null,$b$Kao si dang ta neh ntu, tât jêh mông mprơ, jêh ri bu tăng jêh ndrau ntơp kutku tâm bri he.$b$,true),
('bunong-vn','SNG',2,13,null,$b$Tơm play rvi lĕ play, jêh ri tơm play kriăk ƀâu luh kao, jêh ri bu ƀâu n'hôl ƀâu kah khân păng Dâk hom, Hơi gâp rŏng, nơm ueh reh gâp, Jêh ri hăn hom he. Bu klâu gŭ ur:$b$,true),
('bunong-vn','SNG',2,14,null,$b$Hơi plŭk gâp, trôm nđa lŭ, jêh ri ta pĭng yôk rdâk, ăn gâp saơ muh măt ay, ăn gâp tăng bâr ay, yor lah bâr ay ngơi jêng maak ăn gâp tăng jêh ri muh măt ay ueh reh.$b$,false),
('bunong-vn','SNG',2,15,null,$b$Sŏk lơi mpik, kon mpik ƀư rai lơi n'gar play kriăk ƀâu, yor lah tơm play kriăk ƀâu he ntơm luh kao. Bu ur gŭ sai:$b$,true),
('bunong-vn','SNG',2,16,null,$b$Nơm gâp rŏng jêng ndơ gâp, jêh ri gâp jêng ndơ păng, păng hŏ chiăp lĕ biăp păng ta nklang kao lili.$b$,false),
('bunong-vn','SNG',2,17,null,$b$Kŏ tât mông geh nau nđĭk jêh ri n'hâm si du roh jêh, Hơi nơm rŏng, plơ̆ văch hom, nâm bu du mlâm Yơng Nâm bu du mlâm jun me druh ta klơ yôk.$b$,true),
('bunong-vn','SNG',3,1,null,$b$Ta klơ sưng bêch gâp dôl bri măng, gâp joi nơm nuih n'hâm gâp rŏng; gâp joi păng, ƀiă lah mâu saơ păng ôh$b$,true),
('bunong-vn','SNG',3,2,null,$b$Aƀaơ ri gâp mra dâk nsong tâm ƀon toyh, n'gŏ trong sâng, lĕ rdjŭm nglah trong, gâp mra joi nơm nuih n'hâm gâp rŏng. Gâp tĭng joi păng, ƀiă lah mâu mâp ôh.$b$,false),
('bunong-vn','SNG',3,3,null,$b$Phung gak nsong jŭm ƀon toyh mâp đah gâp, Gâp ôh: May mâp lĕ nơm nuih n'hâm gâp rŏng?$b$,true),
('bunong-vn','SNG',3,4,null,$b$Gâp tâm rlet bơh khân păng ngai djê̆, gâp mâp bunuyh nuih n'hâm gâp rŏng Gâp ut păng, mâu ăn păng klaih ôh Kŏ tât gâp leo păng rlet ngih mê̆ gâp, Lăp tâm jrô nơm deh nkeng ma gâp.$b$,true),
('bunong-vn','SNG',3,5,null,$b$Hơi phung kon bu ur ƀon Yêrusalem, gâp ntĭnh ma khân ay Yor tă amoh Yơng mâu lah jun me tâm krŏng, Lơi nsônh, mâu lah rlay nau rŏng gâp ôh, ăn tât mông tơ lah păng ŭch$b$,true),
('bunong-vn','SNG',3,6,null,$b$Mbu moh bunuyh nây văch tă bơh bri rdah, nâm bu n'gâng ŭch, geh ƀâu n'hôl âk ndơ ƀâu kah, geh nđâp lĕ ntil rnih ƀâu kah phung tăch drăp?$b$,false),
('bunong-vn','SNG',3,7,null,$b$Aơ, ndơ nây jêng rpê̆ tung Y-Salômôn! Geh prao jât nuyh tâm phung dăng ktang Israel Nchueng jŭm păng;$b$,true),
('bunong-vn','SNG',3,8,null,$b$Lĕ rngôch djôt đao da dê jêh ri jêng phung n'hăk lĕ nau tâm lơh; ăp nơm geh cheng đao ta bŭt gay njrăng rlăng nau ndơl dôl bri măng.$b$,false),
('bunong-vn','SNG',3,9,null,$b$Hađăch Salômôn ƀư ma păng nơm du mlâm rlê̆ma tơm si tă bơh bri Liban.$b$,true),
('bunong-vn','SNG',3,10,null,$b$Păng ƀư mâng rnung păng ma prăk, ntŭk nsing ma mah ntŭk săp gŭ nkŭm ma bok rvanh chăng krăk; ma nau rŏng phung kon bu ur ƀon Yêrusalem tanh bok nkŭm tâm trôm.$b$,true),
('bunong-vn','SNG',3,11,null,$b$Hơi phung kon bu ur Siôn, hăn hom, jêh ri uănh hađăch Salômôn, ndô đon hađăch mê̆ păng ndô jêh ta păng. Ta nar tâm nkol ur sai păng Ta hâk răm ma nuih n'hâm păng. Bu Klâu Gŭ Ur Tâm Rnê Ma Bu Ur Gŭ Sai Bu klâu gŭ ur:$b$,true),
('bunong-vn','SNG',4,1,null,$b$Aơ, ay jêng ueh reh, Hơi nơm gâp rŏng, Aơ, ay jêng ueh ngăn! Măt ay nâm bu plŭk Pa kơi geh bok nkŭm muh măt ay. Sŏk ay jêng nâm bu du mlâm be, Njŭr ta pĭng yôk Galaat.$b$,true),
('bunong-vn','SNG',4,2,null,$b$Sêk ay nâm bu âk biăp me lĕ bu kreh rsau, tă bơh dak nglao khân păng tă ŭm lĕ rngôch khân păng deh kon bar, mâu geh du mlâm ôh rlêh kon.$b$,true),
('bunong-vn','SNG',4,3,null,$b$Mbung ay nâm bu brai chăng, jêh ri trôm mbung ay ueh ngăn. Trô bom ay jêng nâm bu du đah play pom gra nat Pa kơi bok nkŭm muh măt ay.$b$,true),
('bunong-vn','SNG',4,4,null,$b$Trô ko ay jêng nâm bu vâl tŭm Y-Đavit, Lĕ ndâk jêh gay prăp ndơ tâm lơh.$b$,true),
('bunong-vn','SNG',4,5,null,$b$Bar mlâm toh ay jêng nâm bu bar mlâm kon jun, kon yơng deh kon bar, gŭ sa gơ̆ ta nklang kao lili.$b$,true),
('bunong-vn','SNG',4,6,null,$b$Tât mông lĕ nđĭk jêh tơm si n'hâm roh lĕ, gâp mra hăn rlet yôk ndơ ƀâu kah jêh ri ma gôl dak ƀâu kah.$b$,true),
('bunong-vn','SNG',4,7,null,$b$Hơi nơm gâp rŏng, ay jêng ueh reh ngăn, mâu geh ntŭk mhĭk ôh.$b$,true),
('bunong-vn','SNG',4,8,null,$b$Hơi ur gâp, hăn hom ndrel gâp tă bơh bri Liban, hăn hom he. Du tă bơh n'glơn yôk Amana, Tă bơh n'glơn yôk Sênir jêh ri Hermôn, Tă bơh trôm mbung yau mŭr, Tă bơh yôk yau brăch.$b$,true),
('bunong-vn','SNG',4,9,null,$b$Nuih n'hâm gâp lĕ pha ay jêh, Hơi oh gâp, ur gâp, Nuih n'hâm gâp lĕ pha ay jêh, Ma nau ay uănh ntơ̆ măt ma gâp knŏng du tơ̆ , Yor ma du rse văn lŭ khlay ta trô ko ay, Yor ri nuih n'hâm gâp lĕ pha ay.$b$,true),
('bunong-vn','SNG',4,10,null,$b$Hơi oh gâp, ur gâp, kah njŭng ngăn nau ay rŏng ma gâp! Nau ay rŏng ueh rlau lơn ma dak play kriăk ƀâu, Jêh ri dak kôlônh ay ƀâu kah lơn ma ndơ ƀâu kah êng!$b$,true),
('bunong-vn','SNG',4,11,null,$b$Hơi ur gâp, trôm mbung ay ăn truh dak sŭk, dak sŭk jêh ri dak toh ndrôk tâm dâng mpiăt ay; ƀâu nglâm bok ao ay nâm bu ƀâu nglâm bri Liban.$b$,true),
('bunong-vn','SNG',4,12,null,$b$Oh gâp, ur gâp jêng nâm bu du mlâm n'gar trao bu ntĭl jêng, du mlâm n'gar trao bu ntĭl jêng, du ntŭk tu dak lĕ bu nsêt jêh$b$,true),
('bunong-vn','SNG',4,13,null,$b$Lĕ nkeh ay jêng du đang play pom gra nat, geh ăp ntil play ueh reh, kao hêma ndrel ma dak ƀâu kah,$b$,false),
('bunong-vn','SNG',4,14,null,$b$dak ƀâu kah jêh ri rmĭt kring, calamôs jêh ri sinamôn, ndrel ma lĕ rngôch ndơ ƀâu kah$b$,false),
('bunong-vn','SNG',4,15,null,$b$du ntŭk tu dak tâm n'gar trao, du ntŭk ndrâm ntu dak rêh, jêh ri âk n'hor dak tă bơh bri Liban. Bu ur gŭ sai:$b$,false),
('bunong-vn','SNG',4,16,null,$b$Kah rngăl hom, Hơi sial tă bơh dor, jêh ri văch hom, Hơi sial tă bơh rđŭng! Khôm mpruh hom ta n'gar trao gâp, Ăn ƀâu n'hôl dak ƀâu kah păng đô̆ rdu lam ntŭk. Ăn nơm gâp rŏng văch tât n'gar trao păng, Jêh ri sa play ueh reh tâm n'gar trao nây. Bu klâu gŭ ur:$b$,false),
('bunong-vn','SNG',5,1,null,$b$Hơi oh gâp, ur gâp, gâp văch ta n'gar trao gâp, gâp dônh dak mir nđâp ndơ ƀâu kah gâp, gâp sa mpông sŭt nđâp ma dak sŭt gâp, gâp hŏ nhêt dak play kriăk ƀâu gâp nđâp dak toh ndrôk gâp. Phung băl: Hơi mĭt jiăng hên, sa jêh ri nhêt hom; Hơi phung tâm rŏng, nhêt hom ăn mpay! Nau Uh Ah Yor Tâm Nkhah Bu ur gŭ sai:$b$,true),
('bunong-vn','SNG',5,2,null,$b$Gâp hŏ bêch jêh, ƀiă lah nuih n'hâm gâp hom e rngeh. Iăt hom! Nơm gâp rŏng goh mpông. Pơk hom ma gâp, Hơi oh gâp, nơm gâp rŏng, plŭk gâp nơm ueh ngăn ngên; Yor lah bôk gâp bĕ đah dak ngom, Sŏk gâp bĕ dak ngom dôl bri măng.$b$,false),
('bunong-vn','SNG',5,3,null,$b$Gâp doh lơi lĕ kho ao gâp, pô ri mâm dơi gâp nsoh đŏng? Gâp lĕ rao jêh jâng gâp, Pô ri mâm gâp dơi ƀư ƀơ̆ đŏng khân păng?$b$,true),
('bunong-vn','SNG',5,4,null,$b$Nơm gâp rŏng lĕ djôt jêh lăk-lê mpông, jêh ri nuih n'hâm gâp mpât rđŭk ro.$b$,true),
('bunong-vn','SNG',5,5,null,$b$Gâp dâk gay pơk ăn ma nơm gâp rŏng, jêh ri dak mir truh ta ti gâp, ƀư bĕ nglau ti gâp, dôl gâp kuăn lăk-lê mpông.$b$,true),
('bunong-vn','SNG',5,6,null,$b$Gâp hŏ pơk jêh ma nơm gâp rŏng, ƀiă lah nơm gâp rŏng lĕ du sĭt jêh. Nuih n'hâm gâp joi dôl păng ngơi, Gâp joi păng, ƀiă lah mâu saơ păng ôh, Gâp kuăl păng, ƀiă lah păng mâu saơ păng ôh, Gâp kuăl păng, ƀiă lah păng mâu ơh ôh.$b$,true),
('bunong-vn','SNG',5,7,null,$b$Phung gak tâm mâp ma gâp, dôl khân păng nsong tâm ƀon; khân păng dong gâp, ăn gâp sôt, phung gak ta mpêr sŏk rdu ao jâr gâp$b$,true),
('bunong-vn','SNG',5,8,null,$b$Gâp ntĭnh khân ay, Hơi phung kon bu ur ƀon Yêrusalem, tơ lah khân ay saơ nơm gâp rŏng, mbơh an ma păng, gâp ji yor nau gâp rŏng. Phung băl:$b$,false),
('bunong-vn','SNG',5,9,null,$b$Mâm nơm ay rŏng jêng rlau lơn ma nơm bu êng rŏng, Hơi nơm ueh reh lơn ma phung bu ur êng? Mâm nơm rŏng jêng rlau lơn ma nơm bu êng rŏng, Kŏ tât ay ntĭnh ma hên nâm bu pô nây? Bu Ur Gŭ Sai Tâm Rnê Ma Bu Klâu Gŭ Ur Bu ur gŭ sai:$b$,false),
('bunong-vn','SNG',5,10,null,$b$Nơm gâp rŏng jêng ueh ngăn jêh ri bok dŭm, Nau lơn ta nklang phung du rmưn nuyh.$b$,false),
('bunong-vn','SNG',5,11,null,$b$Bôk păng jêng nâm bu mah khlay lơn sŏk păng kruănh, krăk nsrêk nâm bu nđak$b$,true),
('bunong-vn','SNG',5,12,null,$b$Măt păng nâm bu măt plŭk gŭ dăch tu dak, lĕ rao jêh ma dak toh ndrôk, măt păng gŭ di ntŭk.$b$,false),
('bunong-vn','SNG',5,13,null,$b$Bom păng nâm bu n'gar ndơ ƀâu kah, ntô̆ rdu n'hôl ƀâu kah. Mbung păng nâm bu kao lili, Ăn truh dak mir.$b$,true),
('bunong-vn','SNG',5,14,null,$b$Nting tur păng nâm bu glo mah mlâm, lĭr ndop lŭ khlay. Săk jăn păng nâm bu ndơ bu ƀư ma la, Lĭr ndop lŭ saphir$b$,true),
('bunong-vn','SNG',5,15,null,$b$Jâng păng nâm bu meh gâng lŭ marbrơ, bu ndâk ta klơ mbon mah Bu uănh ma păng jêng nâm bu bri Liban, Ueh nâm bu tơm si sêdar.$b$,false),
('bunong-vn','SNG',5,16,null,$b$Nau păng ngơi ueh tôr iăt, jêh ri bu rŏng ngăn ma păng, Nây yơh jêng nơm gâp rŏng jêh ri jêng mĭt jiăng gâp, Hơi phung bu ur ƀon Yêrusalem. Phung băl:$b$,true),
('bunong-vn','SNG',6,1,null,$b$Ta ntŭk nơm ay rŏng du hăn jêh, Hơi nơm ueh reh lơn ma phung bu ur êng? Ta ntŭk nơm ay rŏng du hăn jêh, Gay ma hên dơi joi păng ndrel ma ay? Bu ur gŭ sai:$b$,true),
('bunong-vn','SNG',6,2,null,$b$Nơm gâp rŏng hăn njŭn leo ma n'gar trao păng rlet ma n'gar ndơ ƀâu kah, gay chiăp biăp păng tâm n'gar trao, jêh ri dônh kao lili.$b$,false),
('bunong-vn','SNG',6,3,null,$b$Gâp jêng ndơ ma nơm gâp rŏng, jêh ri nơm gâp rŏng jêng ndơ gâp; păng chiăp biăp păng tâm ntŭk geh kao lili Bu klâu gŭ ur:$b$,true),
('bunong-vn','SNG',6,4,null,$b$Hơi nơm gâp rŏng, ay jêng ueh ngăn nâm bu ƀon Yêrusalem, ay blau nhhu bu nâm bu du phung ta han djôt bok n'ha kơ.$b$,false),
('bunong-vn','SNG',6,5,null,$b$Nhêp lơi măt ay lơi hôm treng uănh gâp, yor lah măt ay rhêp gâp sŏk ay jêng nâm bu phung be njŭr sop pĭng yôk Galaat.$b$,true),
('bunong-vn','SNG',6,6,null,$b$Sêk ay jêng nâm bu du phung biăp me, hao văch tă bơh ntŭk khân păng ŭm, lĕ rngôch khân păng deh kon bar, jêh ri mâu geh du mlâm rlêh kon ôh.$b$,true),
('bunong-vn','SNG',6,7,null,$b$Trô bom ay jêng nâm bu ôlu đah play pom gra nat pa kơi bok nkŭm muh măt ay.$b$,true),
('bunong-vn','SNG',6,8,null,$b$Geh prao jât nuyh hađăch bu ur jêh ri pham jât nuyh ur yông, jêh ri phung bu ur druh mâu dơi kơp ôh.$b$,true),
('bunong-vn','SNG',6,9,null,$b$Plŭk gâp, nơm ueh ngăn ngên gâp, jêng knŏng du huê dơm, nơm me păng rŏng lơn mâu geh ntŭk mhĭk ôh ma mê̆ nơm deh ma păng. Phung bu ur druh saơ păng jêh ri ntơ ma păng nơm hâk răm; Nđâp phung hađăch bu ur jêh ri Phung ur yông saơ păng jêh ri tâm rnê ma păng.$b$,true),
('bunong-vn','SNG',6,10,null,$b$Mbu nơm aơ uănh nâm bu nchrat luh nar, ueh nâm bu khay, nchrang nâm bu măt nar, blau nhhu bu nâm bu du phung ta han djôt bok n'ha kơ?$b$,true),
('bunong-vn','SNG',6,11,null,$b$Gâp jŭr hăn ta n'gar play nhăr gay uănh ma kao tâm rlŭng, gay saơ gĭt lah tơm play kriăk ƀâu chăt nkŭr jêh, gĭt lah play pom gra nat lĕ kao jêh.$b$,true),
('bunong-vn','SNG',6,12,null,$b$Gâp ntôn lah, nâm bu mbơi gâp gŭ tâm du mlâm ndeh seh ta meng kon hađăch gâp. Phung băl:$b$,true),
('bunong-vn','SNG',6,13,null,$b$Sĭt hom, sĭt hom, Hơi bu ur ƀon Sulam, Sĭt hom, sĭt hom gay ma hên dơi uănh ay. Bu klâu gŭ ur: Mâm khân may ŭch gŭ uănh ma bu ur ƀon Sulam, Dôl păng ta lô̆ ta năp bar phung mprơ?$b$,false),
('bunong-vn','SNG',7,1,null,$b$Hơi kon bu ur hađăch, rom ngăn uănh ma jâng ay nsoh ntô jot! Gang bŭt mlâm nâm bu lŭ khlay, Jêng kan ti du huê njêh.$b$,true),
('bunong-vn','SNG',7,2,null,$b$Jreng klŏ ay jêng nâm bu du mlâm ngan rlŭ mlâm mâu mâp tăch yơt ôh dak play kriăk ƀâu. Ndŭl ay jêng nâm bu du mbŭch ba răch (ba ƀlê), kao lili rvang văr jŭm.$b$,true),
('bunong-vn','SNG',7,3,null,$b$Bar đah toh ay jêng nâm bu bar mlâm kon jun, nâm bu yơng kon bar.$b$,true),
('bunong-vn','SNG',7,4,null,$b$Trô ko ay jêng nâm bu vâl tŭm ƀư ma la. Măt ay jêng nâm bu ntu lŭng dak nglao ta ƀon Hêbron, Dăch mpông pêr Bat-Rabim. Trôm muh ay jêng nâm bu vâl tŭm bri Liban, Uănh mpeh ƀon Damas.$b$,true),
('bunong-vn','SNG',7,5,null,$b$Bôk ay jêng nâm bu yôk Karmel, jêh ri sŏk ay jong uănh nâm bu bok chăng krăk. Dôl hađăch uănh ma sŏk ueh ay, Nuih n'hâm păng pha ay jêh.$b$,true),
('bunong-vn','SNG',7,6,null,$b$Ay jêng ueh ngăn ngên jêh ri ƀư maak ma bu, Hơi nơm bu rŏng, Hơi bu ur druh ueh uănh!$b$,true),
('bunong-vn','SNG',7,7,null,$b$Lĭng săk ay rom ray nâm bu du tơm play đung, jêh ri toh ay jêng nâm bu rkŭm play păng.$b$,true),
('bunong-vn','SNG',7,8,null,$b$Gâp lah gâp mra hao tơm play đung nây jêh ri kuăn rđâng mpak păng. Ơ, ŭch ngăn ma toh ay jêng nâm bu rkŭm play kriăk ƀâu, Jêh ri ƀâu n'hâm ay nsôr nâm bu ƀâu play pom,$b$,true),
('bunong-vn','SNG',7,9,null,$b$jêh ri nau ay chŭm jêng nâm bu dak play kriăk ƀâu ueh reh, truh nơih pơih ta trôm mbung phung gŭ bêch. Bu ur gŭ sai:$b$,false),
('bunong-vn','SNG',7,10,null,$b$Gâp jêng ndơ nơm gâp rŏng, jêh ri păng ŭch ma gâp đŏng.$b$,false),
('bunong-vn','SNG',7,11,null,$b$Văch hom, Hơi nơm gâp rŏng, ăn he hăn ta mir jêh ri gŭ tâm ƀon jê̆;$b$,true),
('bunong-vn','SNG',7,12,null,$b$ăn he hăn ơm ma đang play kriăk ƀâu, gay saơ gĭt lah tơm play kriăk ƀâu lĕ chăt nkŭr jêh, gĭt lah kao play kriăk ƀâu lĕ dang jêh, jêh ri gĭt lah play pom gra nat dôl luh kao. Ta nây gâp mra jao gâp nơm ma may yor nau rŏng.$b$,false),
('bunong-vn','SNG',7,13,null,$b$Play mandragôr ntô̆ ƀâu n'hôl ƀâu kah, jêh ri ta klơ mpông he geh lĕ rngôch play ueh reh, play mhe nđâp ma play ơm, play nây gâp prăp jêh ma may, Hơi nơm gâp rŏng$b$,true),
('bunong-vn','SNG',8,1,null,$b$Ơ ŭch ngăn ma may jêng nâm bu du huê nâu ma gâp, nơm mpu jêh ta toh mê̆ gâp! Tơ lah gâp tâm mâp ma may pa dih, Gâp mra chŭm may, Jêh ri mâu geh ôh nơm tâm rmot ma gâp.$b$,true),
('bunong-vn','SNG',8,2,null,$b$Gâp mra leo may ma ngih mê̆ gâp, ta nây may mra nti ma gâp. Gâp mra ăn ma may ma may nhêt dak play kriăk ƀâu njŭng, Jêh ri dak păt jêh tă bơh play pom gra nat gâp.$b$,true),
('bunong-vn','SNG',8,3,null,$b$Ơ ŭch ngăn ma ti pa chiau păng rkơl tâm dâng bôk gâp, jêh ri ti pa ma păng ut gâp!$b$,true),
('bunong-vn','SNG',8,4,null,$b$Gâp ntĭnh ma khân ay, Hơi phung kon bu ur ƀon Yêrusalem, lơi ta nsônh mâu lah rlay ôh nau rŏng gâp, ăn tât mông tơ lah păng ŭch. Phung băl:$b$,true),
('bunong-vn','SNG',8,5,null,$b$Mbu bu ur nây văch hao tă bơh bri rdah, dôl gŭ nsing ma nơm păng rŏng? Bu klâu gŭ ur: Tâm dâng tơm play pom gâp rlay ay, Ta nây mê̆ ay deh jêh ma ay ma nau ji, Ta nây yơh păng veng ŭnh nkeng ma ay.$b$,false),
('bunong-vn','SNG',8,6,null,$b$Ăn gâp jêng nâm bu du ndơ tâp pŏng khan tâm nuih n'hâm ay, nâm bu du mlâm ndơ tâp pŏng ta nting tur ay; yor lah nau rŏng jêng ktang nâm bu nau khĭt. Nau ntôn jêng nau mhĭk djơh nâm bu môch. Păng hit nâm bu ŭnh, Mpiăt ŭnh duh lơn.$b$,true),
('bunong-vn','SNG',8,7,null,$b$Âk dak mâu dơi blôn nau rŏng ôh mâu lĕ dak lip dơi ndâp păng, Tơ lah du huê bu klâu ŭch rvăt nau rŏng Ma lĕ drăp păng ngih vâl, Bu mra dun lơi. Phung băl:$b$,true),
('bunong-vn','SNG',8,8,null,$b$Hên geh du huê oh bu ur, jêh ri ô băl ê hŏ bŭt toh ôh; moh ndơ hên mra kơl ma oh bu ur hên, ta nar bu dăn gŭ păng?$b$,false),
('bunong-vn','SNG',8,9,null,$b$Tơ lah păng jêng nâm bu mpêr, hên mra ndâk ta klơ păng du mlâm mpêr nching ma prăk; ƀiă lah tơ lah păng jêng du mlâm mpông, hên mra ƀư rnăng king păng ma kđar tơm si sêdar. Bu ur gŭ sai:$b$,true),
('bunong-vn','SNG',8,10,null,$b$Gâp jêng jêh du mlâm mpêr, jêh ri toh gâp jêng nâm bu vâl tŭm; jêh ri gâp jêng măt ma păng nâm bu nơm ăn nau mpay nuih n'hâm.$b$,false),
('bunong-vn','SNG',8,11,null,$b$Y-Salômôn geh đang play kriăk ƀâu ta ƀon Baal-Hamôn. Păng ăn phung mât nkhôm đang play kriăk ƀâu nây; Ăp nơm mra njŭn du rbăn glo prăk tă bơh play kao păng.$b$,true),
('bunong-vn','SNG',8,12,null,$b$Đang play kriăk ƀâu gâp prăp ma gâp nơm yơh. Hơi Y-Salômôn, may dơi geh du rbăn glo prăk nây, Jêh ri bar rhiăng nuyh phung mât play nây. Bu klâu gŭ ur:$b$,true),
('bunong-vn','SNG',8,13,null,$b$Hơi nơm gŭ tâm n'gar trao, phung băl gâp kâp iăt bâr ay ngơi; ăn gâp iăt bâr ay! Bu ur gŭ sai:$b$,false),
('bunong-vn','SNG',8,14,null,$b$Ndal hom, Hơi nơm gâp rŏng, jêh ri jêng nâm bu du mlâm yơng mâu lah du mlâm jun nkuăng ndăm ta klơ yôk ndơ ƀâu kah.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','SNG',1,1,0,'heading',$b$Bu Ur Gŭ Sai Jêh Ri Phung Kon Bu Ur Ƀon Yêrusalem$b$),
('bunong-vn','SNG',1,9,1,'heading',$b$Bu Klâu Gŭ Ur Jêh Ri Bu Ur Gŭ Sai$b$),
('bunong-vn','SNG',3,1,0,'heading',$b$Bu Ur Gŭ Sai Gŭ Rvê$b$),
('bunong-vn','SNG',7,6,0,'heading',$b$Bu Ur Gŭ Sai Jêh Ri Bu Klâu Gŭ Ur Geh Nau Maak Ndrel$b$);
